/* ============================================================
   delegated mailbox windows
   ============================================================ */
function readDelegatedWindowSession() {
  try {
    const raw = sessionStorage.getItem(DELEGATED_SESSION_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed.token !== "string" || !parsed.token || typeof parsed.csrf !== "string") return null;
    return parsed;
  } catch {
    return null;
  }
}

function writeDelegatedWindowSession(session) {
  try {
    if (session) sessionStorage.setItem(DELEGATED_SESSION_KEY, JSON.stringify(session));
    else sessionStorage.removeItem(DELEGATED_SESSION_KEY);
  } catch {}
}

function delegatedCookie(name) {
  try {
    for (const entry of document.cookie.split(";")) {
      const separator = entry.indexOf("=");
      if (separator < 0) continue;
      if (entry.slice(0, separator).trim() !== name) continue;
      return decodeURIComponent(entry.slice(separator + 1).trim());
    }
  } catch {}
  return "";
}

async function redeemDelegatedLaunchCode(code) {
  const response = await fetch("/api/delegation/redeem", {
    method: "POST",
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      "X-CSRF-Token": delegatedCookie("a8m_system_csrf") || delegatedCookie("a8m_csrf")
    },
    credentials: "same-origin",
    cache: "no-store",
    body: JSON.stringify({ code })
  });
  const type = response.headers.get("content-type") || "";
  const payload = type.includes("application/json") ? await response.json().catch(() => null) : null;
  if (!response.ok) {
    const detail = payload && payload.error ? payload.error : {};
    throw new Error(detail.message || t("ui.delegated-mailbox-windows.this-delegated-mailbox-link-has-expired"));
  }
  return payload || {};
}

async function prepareDelegatedWindow() {
  const params = new URLSearchParams(window.location.search);
  const launch = params.get("delegate");
  const stored = readDelegatedWindowSession();
  if (launch === null && !stored) return false;
  state.delegatedMode = true;
  document.documentElement.dataset.delegated = "true";
  if (launch && launch !== "1") {
    try {
      const data = await redeemDelegatedLaunchCode(launch);
      const session = {
        token: data.token,
        csrf: data.csrf,
        mailbox: data.mailbox || {},
        canSend: data.delegatedCanSend !== false,
        expiresAt: data.expiresAt || ""
      };
      writeDelegatedWindowSession(session);
      state.delegatedSession = session;
      state.csrf = data.csrf || "";
      params.set("delegate", "1");
      const query = params.toString();
      window.history.replaceState(null, "", window.location.pathname + (query ? `?${query}` : "") + window.location.hash);
      return true;
    } catch (error) {
      state.delegatedExpired = true;
      showDelegatedClosed(error.message || t("ui.delegated-mailbox-windows.this-delegated-mailbox-link-is-no-longer-availab"));
      return false;
    }
  }
  if (stored) {
    state.delegatedSession = stored;
    state.csrf = stored.csrf || state.csrf;
    return true;
  }
  state.delegatedExpired = true;
  showDelegatedClosed(t("ui.delegated-mailbox-windows.this-delegated-mailbox-is-no-longer-open-ask-the"));
  return false;
}

function showDelegatedClosed(message) {
  showLogin();
  loginForm.hidden = true;
  const panelHost = document.querySelector(".login-panel");
  if (!panelHost) return;
  panelHost.querySelector(".delegated-closed-card")?.remove();
  const panel = document.createElement("div");
  panel.className = "login-card delegated-closed-card";
  panel.innerHTML = `
    <div class="login-heading">
      <p class="eyebrow">${t("ui.delegated-mailbox-windows.delegated-mailbox")}</p>
      <h2>${t("ui.delegated-mailbox-windows.this-window-is-signed-out")}</h2>
      <p>${esc(message)}</p>
    </div>
    <div class="delegated-closed-note"><svg class="icon" aria-hidden="true"><use href="#i-shield-check"/></svg><span>${t("ui.delegated-mailbox-windows.closing-this-window-never-signs-out-the-primary-")}</span></div>
    <div class="delegated-closed-actions">
      <button class="login-submit" type="button" data-delegated-close-window>${t("ui.delegated-mailbox-windows.close-window")}</button>
      <button class="link-btn" type="button" data-delegated-main-mailbox>${t("ui.delegated-mailbox-windows.open-my-main-mailbox")}</button>
    </div>`;
  panelHost.appendChild(panel);
  panel.querySelector("[data-delegated-close-window]")?.addEventListener("click", () => window.close());
  panel.querySelector("[data-delegated-main-mailbox]")?.addEventListener("click", () => {
    clearDelegatedWindowSession();
    window.location.href = "/";
  });
}

function clearDelegatedWindowSession() {
  writeDelegatedWindowSession(null);
  state.delegatedSession = null;
  state.delegatedMode = false;
  try {
    delete document.documentElement.dataset.delegated;
  } catch {}
}

function stopDelegatedHeartbeat() {
  if (state.delegatedHeartbeat) clearInterval(state.delegatedHeartbeat);
  state.delegatedHeartbeat = null;
}

function expireDelegatedWindow(message) {
  if (!state.delegatedMode || state.delegatedExpired) return;
  state.delegatedExpired = true;
  stopDelegatedHeartbeat();
  clearDelegatedWindowSession();
  state.user = null;
  state.csrf = null;
  state.delegatedMailboxes = [];
  document.getElementById("delegatedSwitcher")?.remove();
  document.getElementById("delegatedWindowChip")?.remove();
  showDelegatedClosed(message || t("ui.mandatory-first-login-onboarding.your-primary-alt8mail-session-ended-this-delegat"));
}

function startDelegatedHeartbeat() {
  stopDelegatedHeartbeat();
  if (!state.delegatedMode || !state.delegatedSession?.token) return;
  state.delegatedHeartbeat = setInterval(async () => {
    const session = state.delegatedSession;
    if (!session?.token) return;
    try {
      const response = await fetch("/api/session", {
        headers: { Accept: "application/json", [DELEGATED_SESSION_HEADER]: session.token },
        credentials: "same-origin",
        cache: "no-store"
      });
      if (response.status === 401) {
        const payload = await response.json().catch(() => null);
        expireDelegatedWindow(payload?.error?.message || t("ui.mandatory-first-login-onboarding.your-primary-alt8mail-session-ended-this-delegat"));
      }
    } catch {}
  }, 30_000);
}

let delegatedAuthChannel = null;

function setupDelegatedAuthChannel() {
  if (delegatedAuthChannel) return;
  try {
    delegatedAuthChannel = new BroadcastChannel("a8m-delegated-auth");
    delegatedAuthChannel.addEventListener("message", (event) => {
      if (event.data?.type !== "parent-signed-out") return;
      if (state.delegatedMode) expireDelegatedWindow(t("ui.delegated-mailbox-windows.the-primary-alt8mail-session-signed-out-this-del"));
    });
  } catch {}
}

function broadcastPrimarySignOut() {
  try {
    delegatedAuthChannel?.postMessage({ type: "parent-signed-out" });
  } catch {}
}

async function closeDelegatedWindow() {
  if (state.delegatedExpired) {
    window.close();
    return;
  }
  const session = state.delegatedSession;
  try {
    if (session?.token) await api("/api/delegation/session", { method: "DELETE" });
  } catch {}
  stopDelegatedHeartbeat();
  clearDelegatedWindowSession();
  state.user = null;
  state.csrf = null;
  state.delegatedExpired = true;
  showDelegatedClosed(t("ui.delegated-mailbox-windows.this-delegated-mailbox-window-is-closed-your-pri"));
  setTimeout(() => { try { window.close(); } catch {} }, 200);
}

function delegatedSendBlocked() {
  return Boolean(state.delegatedMode && state.delegatedSession && state.delegatedSession.canSend === false);
}

function delegationInitials(name, email) {
  const source = String(name || email || "?").trim();
  const parts = source.split(/\s+/).filter(Boolean);
  if (parts.length > 1) return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
  return source.slice(0, 2).toUpperCase() || "?";
}

function renderDelegatedMailboxList() {
  const list = document.getElementById("delegatedMailboxList");
  if (!list) return;
  const query = state.delegatedSwitchQuery.trim().toLowerCase();
  const matches = (state.delegatedMailboxes || []).filter((mailbox) => {
    if (!query) return true;
    return `${mailbox.name || ""} ${mailbox.email || ""}`.toLowerCase().includes(query);
  });
  if (!matches.length) {
    list.innerHTML = `<div class="delegated-empty"><svg class="icon" aria-hidden="true"><use href="#i-search"/></svg><strong>${t("ui.delegated-mailbox-windows.no-mailbox-found")}</strong><span>${t("ui.delegated-mailbox-windows.try-a-name-or-email-address")}</span></div>`;
    return;
  }
  list.innerHTML = matches.map((mailbox) => {
    const initials = mailbox.initials || delegationInitials(mailbox.name, mailbox.email);
    const color = mailbox.color || "#34557a";
    const kind = mailbox.canSend ? t("ui.delegated-mailbox-windows.read-send") : t("mail.reader.readOnly");
    return `<button class="delegated-mailbox-row" type="button" role="option" data-delegated-mailbox="${esc(mailbox.id || mailbox.ownerId || "")}" title="${esc(t("ui.delegated-mailbox-windows.open-mailbox-in-new-window", { mailbox: mailbox.email || mailbox.name || t("ui.delegated-mailbox-windows.mailbox") }))}">
      <span class="avatar avatar-sm delegated-mailbox-avatar" style="--av:${esc(color)}" aria-hidden="true"><span class="avatar-initials">${esc(initials)}</span></span>
      <span class="delegated-mailbox-copy"><strong>${esc(mailbox.name || mailbox.email || t("ui.delegated-mailbox-windows.mailbox"))}</strong><span>${esc(mailbox.email || "")}</span></span>
      <span class="delegated-mailbox-kind${mailbox.canSend ? " can-send" : ""}">${kind}</span>
      <svg class="icon delegated-mailbox-open" aria-hidden="true"><use href="#i-external"/></svg>
    </button>`;
  }).join("");
}

function renderDelegatedMailboxSwitcher() {
  const wrapper = document.getElementById("delegatedSwitcher");
  const button = document.getElementById("delegatedSwitchBtn");
  const count = document.getElementById("delegatedSwitchCount");
  if (!wrapper || !button || !count) return;
  const items = state.delegatedMailboxes || [];
  if (state.delegatedMode || !items.length) {
    wrapper.hidden = true;
    state.delegatedSwitchOpen = false;
    document.getElementById("delegatedMailboxPop")?.setAttribute("hidden", "");
    button.setAttribute("aria-expanded", "false");
    return;
  }
  wrapper.hidden = false;
  count.textContent = String(items.length);
  count.hidden = false;
  button.title = items.length === 1
    ? t("ui.delegated-mailbox-windows.open-delegated-mailbox", { mailbox: items[0].email || items[0].name })
    : tn("ui.delegated-mailbox-windows.open-many-delegated-mailboxes", items.length, { count: items.length });
  renderDelegatedMailboxList();
}

function ensureDelegatedMailboxUi() {
  if (document.getElementById("delegatedSwitcher")) {
    renderDelegatedMailboxSwitcher();
    return;
  }
  const topActions = document.querySelector(".top-actions");
  const notify = document.getElementById("notifyBtn");
  if (!topActions || !notify) return;
  const wrapper = document.createElement("div");
  wrapper.className = "delegated-switcher";
  wrapper.id = "delegatedSwitcher";
  wrapper.hidden = true;
  wrapper.innerHTML = `
    <button class="delegated-switch-btn" id="delegatedSwitchBtn" type="button" aria-haspopup="dialog" aria-expanded="false" aria-controls="delegatedMailboxPop" title="${esc(t("ui.delegated-mailbox-windows.open-a-delegated-mailbox"))}">
      <svg class="icon" aria-hidden="true"><use href="#i-people"/></svg>
      <span class="delegated-switch-label">${t("ui.delegated-mailbox-windows.delegated")}</span>
      <span class="delegated-switch-count" id="delegatedSwitchCount" hidden>0</span>
      <svg class="icon delegated-switch-caret" aria-hidden="true"><use href="#i-chevron-down"/></svg>
    </button>
    <div class="delegated-mailbox-pop" id="delegatedMailboxPop" role="dialog" aria-label="${esc(t("ui.delegated-mailbox-windows.delegated-mailboxes"))}" hidden>
      <div class="delegated-mailbox-head">
        <div><strong>${t("ui.delegated-mailbox-windows.delegated-mailboxes")}</strong><span>${t("ui.delegated-mailbox-windows.open-a-mailbox-in-its-own-window")}</span></div>
        <span class="delegated-mailbox-shield" title="${esc(t("ui.delegated-mailbox-windows.each-window-keeps-its-own-session"))}"><svg class="icon" aria-hidden="true"><use href="#i-shield-check"/></svg></span>
      </div>
      <label class="delegated-mailbox-search">
        <svg class="icon" aria-hidden="true"><use href="#i-search"/></svg>
        <input id="delegatedMailboxSearch" type="search" placeholder="${esc(t("ui.delegated-mailbox-windows.search-name-or-email"))}" autocomplete="off" spellcheck="false" aria-label="${esc(t("ui.delegated-mailbox-windows.search-delegated-mailboxes"))}">
      </label>
      <div class="delegated-mailbox-list" id="delegatedMailboxList" role="listbox"></div>
      <div class="delegated-mailbox-foot"><svg class="icon" aria-hidden="true"><use href="#i-lock"/></svg><span>${t("ui.delegated-mailbox-windows.signing-out-of-this-mailbox-closes-every-delegat")}</span></div>
    </div>`;
  topActions.insertBefore(wrapper, notify);
  const button = document.getElementById("delegatedSwitchBtn");
  const search = document.getElementById("delegatedMailboxSearch");
  const list = document.getElementById("delegatedMailboxList");
  button?.addEventListener("click", (event) => {
    event.stopPropagation();
    toggleDelegatedMailboxSwitcher();
  });
  search?.addEventListener("input", () => {
    state.delegatedSwitchQuery = search.value || "";
    renderDelegatedMailboxList();
  });
  search?.addEventListener("keydown", (event) => {
    if (event.key !== "Enter") return;
    event.preventDefault();
    const first = list?.querySelector("[data-delegated-mailbox]");
    if (first) openDelegatedMailbox(first.getAttribute("data-delegated-mailbox"));
  });
  list?.addEventListener("click", (event) => {
    const row = event.target.closest("[data-delegated-mailbox]");
    if (row) openDelegatedMailbox(row.getAttribute("data-delegated-mailbox"));
  });
  document.addEventListener("click", (event) => {
    if (!event.target.closest("#delegatedSwitcher")) closeDelegatedMailboxSwitcher();
  });
  renderDelegatedMailboxSwitcher();
}

function toggleDelegatedMailboxSwitcher(force) {
  const wrapper = document.getElementById("delegatedSwitcher");
  const pop = document.getElementById("delegatedMailboxPop");
  const button = document.getElementById("delegatedSwitchBtn");
  const search = document.getElementById("delegatedMailboxSearch");
  if (!wrapper || !pop || wrapper.hidden) return;
  const open = typeof force === "boolean" ? force : pop.hidden;
  state.delegatedSwitchOpen = open;
  pop.hidden = !open;
  wrapper.classList.toggle("is-open", open);
  button?.setAttribute("aria-expanded", open ? "true" : "false");
  if (open) {
    state.delegatedSwitchQuery = "";
    if (search) search.value = "";
    renderDelegatedMailboxList();
    setTimeout(() => search?.focus(), 30);
  }
}

function closeDelegatedMailboxSwitcher() {
  toggleDelegatedMailboxSwitcher(false);
}

async function openDelegatedMailbox(ownerId) {
  const mailbox = (state.delegatedMailboxes || []).find((item) => (item.id || item.ownerId) === ownerId);
  if (!mailbox) return;
  closeDelegatedMailboxSwitcher();
  let popup = null;
  try {
    popup = window.open("about:blank", "_blank");
    if (popup) {
      try {
        popup.document.write("<!doctype html><title>" + t("ui.delegated-mailbox-windows.opening-delegated-mailbox") + "</title><body style=\"font:14px system-ui;padding:32px;color:#334155\">" + t("ui.delegated-mailbox-windows.opening-the-delegated-mailbox") + "</body>");
        popup.document.close();
      } catch {}
    }
  } catch {}
  try {
    const data = await api("/api/delegation/launch", { method: "POST", body: { ownerId } });
    const url = new URL("/", window.location.origin);
    url.searchParams.set("delegate", data.code);
    if (popup) {
      popup.location.replace(url.toString());
      try { popup.opener = null; } catch {}
    } else {
      const fallback = window.open(url.toString(), "_blank", "noopener");
      if (!fallback) throw new Error(t("ui.delegated-mailbox-windows.allow-pop-ups-for-this-site-then-try-again"));
    }
  } catch (error) {
    try { popup?.close(); } catch {}
    showError(error);
  }
}

function renderDelegatedWindowChrome() {
  const topActions = document.querySelector(".top-actions");
  const notify = document.getElementById("notifyBtn");
  if (!topActions) return;
  let chip = document.getElementById("delegatedWindowChip");
  if (!state.delegatedMode || !state.delegatedSession?.mailbox) {
    chip?.remove();
    document.documentElement.removeAttribute("data-delegated");
    return;
  }
  document.documentElement.dataset.delegated = "true";
  const mailbox = state.delegatedSession.mailbox;
  if (!chip) {
    chip = document.createElement("div");
    chip.className = "delegated-window-chip";
    chip.id = "delegatedWindowChip";
    chip.innerHTML = `<span class="delegated-window-icon"><svg class="icon" aria-hidden="true"><use href="#i-people"/></svg></span>
      <span class="delegated-window-copy"><span>${t("ui.delegated-mailbox-windows.delegated-mailbox")}</span><strong></strong></span>
      <button class="delegated-window-exit" id="delegatedWindowExit" type="button">${t("shell.signOut")}</button>`;
    if (notify) topActions.insertBefore(chip, notify);
    else topActions.prepend(chip);
    chip.querySelector("#delegatedWindowExit")?.addEventListener("click", (event) => {
      event.stopPropagation();
      closeDelegatedWindow();
    });
  }
  const email = chip.querySelector(".delegated-window-copy strong");
  if (email) email.textContent = mailbox.email || mailbox.name || t("ui.delegated-mailbox-windows.mailbox");
  chip.title = `${mailbox.name || mailbox.email || t("ui.delegated-mailbox-windows.delegated-mailbox")}${state.delegatedSession.canSend === false ? t("ui.delegated-mailbox-windows.read-only") : ""}`;
  chip.classList.toggle("is-read-only", state.delegatedSession.canSend === false);
}

function maybeShowPasswordChange() {
  const overlay = document.getElementById("passwordChangeOverlay");
  if (!overlay) return;
  if (state.user && state.user.onboardingRequired) {
    overlay.hidden = true;
    return;
  }
  const required = Boolean(state.user && state.user.passwordChangeRequired);
  if (!required) {
    overlay.hidden = true;
    return;
  }
  overlay.hidden = false;
  const reason = document.getElementById("passwordChangeReason");
  const expiresAt = state.user.passwordExpiresAt ? new Date(state.user.passwordExpiresAt) : null;
  if (reason) {
    reason.textContent = expiresAt && expiresAt.getTime() < Date.now()
      ? t("ui.delegated-mailbox-windows.your-password-has-expired-set-a-new-password-to-")
      : t("ui.delegated-mailbox-windows.your-organization-requires-a-new-password-before");
  }
  setTimeout(() => document.getElementById("passwordCurrent")?.focus(), 80);
}

async function submitPasswordChange() {
  const current = document.getElementById("passwordCurrent");
  const next = document.getElementById("passwordNew");
  const confirm = document.getElementById("passwordConfirm");
  const error = document.getElementById("passwordChangeError");
  const button = document.getElementById("passwordChangeSubmit");
  error.hidden = true;
  if (!current.value) { error.textContent = t("ui.delegated-mailbox-windows.enter-your-current-password"); error.hidden = false; return; }
  if (next.value.length < 8) { error.textContent = t("ui.delegated-mailbox-windows.choose-a-stronger-new-password"); error.hidden = false; return; }
  if (next.value !== confirm.value) { error.textContent = t("ui.delegated-mailbox-windows.the-new-passwords-do-not-match"); error.hidden = false; return; }
  button.disabled = true;
  button.textContent = t("ui.delegated-mailbox-windows.saving");
  try {
    await api("/api/password/change", { method: "POST", body: { currentPassword: current.value, newPassword: next.value } });
    current.value = ""; next.value = ""; confirm.value = "";
    state.user.passwordChangeRequired = false;
    document.getElementById("passwordChangeOverlay").hidden = true;
    await loadBootstrap({ restoreDrafts: false, quiet: true });
    showToast(t("ui.delegated-mailbox-windows.password-updated"));
  } catch (changeError) {
    error.textContent = changeError.message || t("ui.delegated-mailbox-windows.could-not-change-the-password");
    error.hidden = false;
  } finally {
    button.disabled = false;
    button.textContent = t("ui.delegated-mailbox-windows.save-new-password");
  }
}

/* ============================================================
   Mandatory first-login onboarding
   ============================================================ */
function onboardingDisplayNameFallback() {
  const email = state.user?.email || "";
  const local = email.split("@")[0] || "there";
  return local.split(/[._-]+/).filter(Boolean).map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join(" ") || "there";
}

function onboardingName() {
  return String(document.getElementById("onboardingName")?.value || "").trim();
}

function onboardingSelection() {
  const selected = state.onboarding || {};
  return {
    timeFormat: selected.timeFormat || state.preferences.timeFormat || "12h",
    theme: selected.theme || state.preferences.theme || "system",
    accent: selected.accent || state.preferences.accent || "blue"
  };
}

function maybeShowOnboarding() {
  if (!onboardingOverlay) return false;
  const required = Boolean(state.user && state.user.onboardingRequired);
  if (!required) {
    onboardingOverlay.hidden = true;
    document.body.classList.remove("onboarding-active");
    if (app) app.inert = false;
    return false;
  }
  if (!onboardingOverlay.hidden) return true;
  state.onboarding = {
    step: 0,
    saving: false,
    passwordChanged: false,
    timeFormat: state.preferences.timeFormat || "12h",
    theme: state.preferences.theme || "system",
    accent: state.preferences.accent || "blue"
  };
  const name = state.user.name && !/^primary$/i.test(state.user.name) && state.user.name !== state.user.email
    ? state.user.name
    : onboardingDisplayNameFallback();
  document.getElementById("onboardingName").value = name;
  document.getElementById("onboardingEmail").value = state.user.email || "";
  const zoneSelect = document.getElementById("onboardingTimeZone");
  zoneSelect.innerHTML = timeZoneOptions().map((zone) => `<option value="${esc(zone)}">${esc(zone.replace(/_/g, " "))}</option>`).join("");
  zoneSelect.value = state.preferences.timeZone || Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  const language = document.getElementById("onboardingLanguage");
  setLanguageSelectValue(language, state.preferences.language);
  const passwordRequired = Boolean(state.user.passwordChangeRequired);
  document.getElementById("onboardingPasswordSection").hidden = !passwordRequired;
  document.getElementById("onboardingPasswordClear").hidden = passwordRequired;
  document.getElementById("onboardingPasswordError").hidden = true;
  document.getElementById("onboardingTwoFactorBtn").disabled = false;
  document.getElementById("onboardingTwoFactorBtn").textContent = t("ui.mandatory-first-login-onboarding.remind-me-to-set-this-up");
  updateOnboardingAvatar();
  updateOnboardingControls();
  setOnboardingStep(0);
  onboardingOverlay.hidden = false;
  document.body.classList.add("onboarding-active");
  if (app) app.inert = true;
  setTimeout(() => document.getElementById("onboardingName")?.focus(), 120);
  return true;
}

function updateOnboardingAvatar() {
  const name = onboardingName() || onboardingDisplayNameFallback();
  document.getElementById("onboardingAvatar").textContent = initialsFrom(name);
  const finishName = document.getElementById("onboardingFinishName");
  if (finishName) finishName.textContent = name.split(/\s+/)[0] || t("ui.mandatory-first-login-onboarding.there");
}

function updateOnboardingControls() {
  const selection = onboardingSelection();
  $$("[data-onboarding-time-format]").forEach((button) => {
    const active = button.getAttribute("data-onboarding-time-format") === selection.timeFormat;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
  $$("[data-onboarding-theme]").forEach((button) => {
    const active = button.getAttribute("data-onboarding-theme") === selection.theme;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
  $$("[data-onboarding-accent]").forEach((button) => {
    const active = button.getAttribute("data-onboarding-accent") === selection.accent;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
}

function setOnboardingStep(step) {
  const next = Math.max(0, Math.min(3, Number(step) || 0));
  state.onboarding.step = next;
  $$(".onboarding-step", onboardingOverlay).forEach((panel) => { panel.hidden = Number(panel.getAttribute("data-onboarding-step")) !== next; });
  $$("[data-onboarding-step-dot]", onboardingOverlay).forEach((dot) => {
    const index = Number(dot.getAttribute("data-onboarding-step-dot"));
    dot.classList.toggle("is-active", index === next);
    dot.classList.toggle("is-complete", index < next);
  });
  const labels = [t("ui.mandatory-first-login-onboarding.tell-us-who-you-are"), t("ui.mandatory-first-login-onboarding.set-your-workspace-defaults"), t("ui.mandatory-first-login-onboarding.secure-the-account"), t("ui.mandatory-first-login-onboarding.review-and-finish")];
  document.getElementById("onboardingProgressLabel").textContent = t("ui.onboarding.step-of-total", { step: next + 1, total: 4 });
  document.getElementById("onboardingProgressSub").textContent = labels[next];
  document.getElementById("onboardingProgressBar").style.width = `${((next + 1) / 4) * 100}%`;
  const back = document.getElementById("onboardingBack");
  back.disabled = next === 0 || state.onboarding.saving;
  const nextButton = document.getElementById("onboardingNext");
  nextButton.textContent = next === 3 ? t("ui.mandatory-first-login-onboarding.finish-setup") : t("ui.mandatory-first-login-onboarding.continue");
  nextButton.disabled = false;
  const error = document.getElementById("onboardingError");
  error.hidden = true;
  if (next === 3) updateOnboardingSummary();
  const focusTarget = next === 0 ? document.getElementById("onboardingName") : next === 1 ? document.getElementById("onboardingTimeZone") : next === 2 ? document.getElementById("onboardingCurrentPassword") : document.getElementById("onboardingNext");
  setTimeout(() => focusTarget?.focus(), 60);
}

function updateOnboardingSummary() {
  const name = onboardingName();
  const selection = onboardingSelection();
  const zone = document.getElementById("onboardingTimeZone").value || state.preferences.timeZone || "UTC";
  const languageSelect = document.getElementById("onboardingLanguage");
  const language = languageSelect.options[languageSelect.selectedIndex]?.textContent || selection.language || t("ui.mandatory-first-login-onboarding.english");
  document.getElementById("onboardingSummaryName").textContent = name || "—";
  document.getElementById("onboardingSummaryIdentity").textContent = name ? `${name} <${state.user.email}>` : state.user.email;
  document.getElementById("onboardingSummaryZone").textContent = zone.replace(/_/g, " ");
  document.getElementById("onboardingSummaryTime").textContent = selection.timeFormat === "24h" ? t("ui.mandatory-first-login-onboarding.24-hour") : t("ui.mandatory-first-login-onboarding.12-hour");
  document.getElementById("onboardingSummaryLanguage").textContent = language;
  const themeLabel = { light: t("ui.theme-preferences.light"), dark: t("ui.theme-preferences.dark"), system: t("ui.theme-preferences.system") }[selection.theme] || selection.theme;
  const accentLabel = selection.accent.charAt(0).toUpperCase() + selection.accent.slice(1);
  document.getElementById("onboardingSummaryAppearance").textContent = t("ui.mandatory-first-login-onboarding.appearance-summary", { theme: themeLabel, accent: accentLabel });
  updateOnboardingAvatar();
}

function onboardingError(message) {
  const error = document.getElementById("onboardingError");
  if (!error) return;
  error.textContent = message;
  error.hidden = !message;
}

async function submitOnboardingPassword() {
  const current = document.getElementById("onboardingCurrentPassword");
  const next = document.getElementById("onboardingNewPassword");
  const confirm = document.getElementById("onboardingConfirmPassword");
  const error = document.getElementById("onboardingPasswordError");
  error.hidden = true;
  if (!state.user.passwordChangeRequired || state.onboarding.passwordChanged) return true;
  if (state.onboarding.saving) return false;
  if (!current.value) { error.textContent = t("ui.mandatory-first-login-onboarding.enter-your-current-password"); error.hidden = false; current.focus(); return false; }
  if (next.value.length < 8) { error.textContent = t("ui.mandatory-first-login-onboarding.choose-a-new-password-of-at-least-8-characters"); error.hidden = false; next.focus(); return false; }
  if (next.value !== confirm.value) { error.textContent = t("ui.mandatory-first-login-onboarding.the-new-passwords-do-not-match"); error.hidden = false; confirm.focus(); return false; }
  state.onboarding.saving = true;
  const button = document.getElementById("onboardingNext");
  button.disabled = true;
  button.textContent = t("ui.mandatory-first-login-onboarding.updating-password");
  try {
    await api("/api/password/change", { method: "POST", body: { currentPassword: current.value, newPassword: next.value } });
    state.user.passwordChangeRequired = false;
    state.onboarding.passwordChanged = true;
    current.value = ""; next.value = ""; confirm.value = "";
    document.getElementById("onboardingPasswordSection").hidden = true;
    const clear = document.getElementById("onboardingPasswordClear");
    clear.hidden = false;
    clear.innerHTML = `<div class="onboarding-section-label"><span>${t("auth.stepPassword")}</span><span class="onboarding-chip verified">${t("ui.mandatory-first-login-onboarding.updated")}</span></div><p>${t("ui.mandatory-first-login-onboarding.your-new-password-is-active-keep-it-in-a-passwor")}</p>`;
    return true;
  } catch (changeError) {
    error.textContent = changeError.message || t("ui.mandatory-first-login-onboarding.could-not-change-the-password");
    error.hidden = false;
    return false;
  } finally {
    state.onboarding.saving = false;
    button.disabled = false;
    button.textContent = t("ui.mandatory-first-login-onboarding.continue");
  }
}

async function advanceOnboarding() {
  if (state.onboarding.saving) return;
  const step = state.onboarding.step;
  if (step === 0) {
    if (!onboardingName()) { onboardingError(t("ui.mandatory-first-login-onboarding.enter-your-full-name-so-the-from-line-is-correct")); document.getElementById("onboardingName").focus(); return; }
    setOnboardingStep(1);
    return;
  }
  if (step === 1) {
    if (!document.getElementById("onboardingTimeZone").value) { onboardingError(t("ui.mandatory-first-login-onboarding.choose-your-time-zone")); return; }
    if (!document.getElementById("onboardingLanguage").value) { onboardingError(t("ui.mandatory-first-login-onboarding.choose-your-preferred-language")); return; }
    setOnboardingStep(2);
    return;
  }
  if (step === 2) {
    if (!(await submitOnboardingPassword())) return;
    setOnboardingStep(3);
    return;
  }
  await finishOnboarding();
}

async function finishOnboarding() {
  if (!onboardingName()) { setOnboardingStep(0); onboardingError(t("ui.mandatory-first-login-onboarding.enter-your-full-name-so-the-from-line-is-correct")); return; }
  const selection = onboardingSelection();
  const zone = document.getElementById("onboardingTimeZone").value;
  const language = document.getElementById("onboardingLanguage").value;
  const button = document.getElementById("onboardingNext");
  state.onboarding.saving = true;
  button.disabled = true;
  button.textContent = t("ui.mandatory-first-login-onboarding.saving-your-workspace");
  onboardingError("");
  try {
    const data = await api("/api/onboarding/complete", {
      method: "POST",
      body: {
        displayName: onboardingName(),
        timeZone: zone,
        timeFormat: selection.timeFormat,
        language,
        theme: selection.theme,
        accent: selection.accent
      }
    });
    if (data.user) {
      state.user.onboardingRequired = false;
      state.user.name = data.user.name || state.user.name;
      state.user.initials = data.user.initials || state.user.initials;
      state.user.passwordChangeRequired = false;
    }
    if (data.preferences) state.preferences = { ...state.preferences, ...data.preferences };
    onboardingOverlay.hidden = true;
    document.body.classList.remove("onboarding-active");
    if (app) app.inert = false;
    applyServerPreferences();
    applyPreferenceChrome();
    syncPreferencesUi();
    renderAccountChrome();
    await loadBootstrap({ restoreDrafts: false, quiet: true });
    showToast(t("ui.mandatory-first-login-onboarding.workspace-ready-your-sender-name-is-set"));
  } catch (error) {
    if (error.code === "PASSWORD_CHANGE_REQUIRED") {
      state.user.passwordChangeRequired = true;
      document.getElementById("onboardingPasswordSection").hidden = false;
      setOnboardingStep(2);
      onboardingError(t("ui.mandatory-first-login-onboarding.set-a-new-password-before-finishing-setup"));
    } else {
      onboardingError(error.message || t("ui.mandatory-first-login-onboarding.could-not-finish-setup-try-again"));
    }
  } finally {
    state.onboarding.saving = false;
    button.disabled = false;
    button.textContent = state.onboarding.step === 3 ? t("ui.mandatory-first-login-onboarding.finish-setup") : t("ui.mandatory-first-login-onboarding.continue");
  }
}

onboardingOverlay?.addEventListener("input", (event) => {
  if (event.target.id === "onboardingName") {
    updateOnboardingAvatar();
    updateOnboardingSummary();
  }
});
onboardingOverlay?.addEventListener("click", (event) => {
  const timeFormat = event.target.closest("[data-onboarding-time-format]");
  if (timeFormat) {
    state.onboarding.timeFormat = timeFormat.getAttribute("data-onboarding-time-format");
    updateOnboardingControls();
    updateOnboardingSummary();
    return;
  }
  const theme = event.target.closest("[data-onboarding-theme]");
  if (theme) {
    state.onboarding.theme = theme.getAttribute("data-onboarding-theme");
    setTheme(state.onboarding.theme, false);
    updateOnboardingControls();
    updateOnboardingSummary();
    return;
  }
  const accent = event.target.closest("[data-onboarding-accent]");
  if (accent) {
    state.onboarding.accent = accent.getAttribute("data-onboarding-accent");
    setAccent(state.onboarding.accent, false);
    updateOnboardingControls();
    updateOnboardingSummary();
    return;
  }
  if (event.target.closest("#onboardingBack")) { setOnboardingStep(state.onboarding.step - 1); return; }
  if (event.target.closest("#onboardingNext")) { advanceOnboarding(); return; }
  if (event.target.closest("#onboardingTwoFactorBtn")) {
    const twoFactor = event.target.closest("#onboardingTwoFactorBtn");
    twoFactor.disabled = true;
    twoFactor.textContent = t("ui.mandatory-first-login-onboarding.reminder-noted-enable-it-in-settings-security-pr");
    return;
  }
});

function handleSessionExpired() {
  closeOfficeUiOnSignOut();
  if (state.delegatedMode) {
    expireDelegatedWindow(t("ui.mandatory-first-login-onboarding.your-primary-alt8mail-session-ended-this-delegat"));
    return;
  }
  if (loginScreen.hidden) {
    clearClientCryptoMemory();
    showLogin();
    loginError.textContent = t("login.sessionExpired");
    loginError.hidden = false;
  }
}

let TITLE_LOGIN = t("ui.mandatory-first-login-onboarding.alt8mail-secure-email-with-ai-built-in-sign-in");
let TITLE_GENERIC = t("ui.mandatory-first-login-onboarding.alt8mail-secure-ai-powered-email-that-thinks-wit");
let tenantBranding = null;
const TITLE_ACCOUNT = t("ui.mandatory-first-login-onboarding.smarter-conversations-ai-powered-email");

function documentTitleSubject(thread) {
  const text = String(threadSubject(thread) || "(no subject)").replace(/\s+/g, " ").trim();
  if (text.length <= 80) return text;
  return `${text.slice(0, 79).replace(/[\s·—-]+$/, "")}…`;
}

function brandName() {
  return (tenantBranding && tenantBranding.productName ? String(tenantBranding.productName).trim() : "") || "Alt8Mail";
}

function updateDocumentTitle() {
  const brand = brandName();
  let title = TITLE_GENERIC;
  if (!state.user) {
    title = loginScreen && !loginScreen.hidden ? TITLE_LOGIN : TITLE_GENERIC;
  } else if (state.task !== "mail") {
    title = t("app.windowTitleAccount", { brand, email: state.user.email || `${brand} account`, account: TITLE_ACCOUNT });
  } else if (!state.selectedThreadId && state.homeTab === "pulse") {
    title = t("app.windowTitlePulse", { pulse: t("mail.home.tab.pulse"), brand });
  } else if (!state.selectedThreadId && state.homeTab === "search" && state.homeSearchQuery) {
    title = t("ui.mail-home-pulse-search-reports-sticky-no.search-report-title", { query: state.homeSearchQuery.slice(0, 48), brand });
  } else {
    const folderLabel = (folderDef(state.folder).label || t("ui.mail-home-pulse-search-reports-sticky-no.inbox")).trim();
    const thread = state.selectedThreadId ? (viewThreadById(state.selectedThreadId) || currentThread()) : null;
    const imapOffline = state.mailboxMode === "imap" && Boolean(String(state.mailSyncError || "").trim());
    const offline = Boolean(state.offline) || imapOffline;
    if (offline) {
      title = thread
        ? t("app.windowTitleOfflineThread", { folder: folderLabel, subject: documentTitleSubject(thread), brand })
        : t("app.windowTitleOfflineFolder", { folder: folderLabel, brand });
    } else {
      const unread = Math.max(0, Math.floor(Number(unreadCount(state.folder)) || 0));
      const prefix = unread > 0 ? `(${unread}) ` : "";
      title = thread
        ? t("app.windowTitleThread", { prefix, folder: folderLabel, subject: documentTitleSubject(thread), brand })
        : t("app.windowTitleFolder", { prefix, folder: folderLabel, email: state.user.email || `${brand} account`, brand });
    }
  }
  if (state.delegatedMode && state.user) title = t("app.windowTitleDelegated", { title });
  if (document.title !== title) document.title = title;
}

function applyTenantBranding(branding) {
  if (!branding || typeof branding !== "object") return;
  const name = String(branding.productName || "").trim().slice(0, 60) || "Alt8Mail";
  const supportEmail = String(branding.supportEmail || "").trim().slice(0, 200);
  const loginMessage = String(branding.loginMessage || "").trim().slice(0, 240);
  const color = /^#[0-9a-f]{6}$/i.test(String(branding.primaryColor || "")) ? branding.primaryColor : "";
  tenantBranding = { ...branding, productName: name };
  if (color) {
    document.documentElement.style.setProperty("--accent", color);
    document.querySelector('meta[name="theme-color"]')?.setAttribute("content", color);
  }
  const customName = name !== "Alt8Mail";
  document.querySelectorAll(".brand-name, .login-brand-top strong, .login-heading > .eyebrow, .tenant-id strong, .onboarding-brand strong").forEach((node) => { node.textContent = name; });
  document.querySelectorAll(".brand-name").forEach((node) => { node.hidden = !customName; });
  document.querySelectorAll(".brand-logo, .login-wordmark").forEach((node) => { node.hidden = customName; });
  // Never paint generated initials over the supplied brand artwork. A custom
  // white-label tenant shows its name as text instead of a fake icon.
  document.querySelectorAll(".brand-mark, .login-mark, .login-watermark, .tenant-mark, .onboarding-mark, .passkey-brand > span").forEach((node) => {
    node.hidden = customName;
  });
  document.querySelectorAll(".login-demo, .login-legal").forEach((node) => {
    if (node.textContent.includes("Alt8Mail")) node.textContent = node.textContent.replaceAll("Alt8Mail", name);
  });
  const splash = document.getElementById("bootSplash");
  if (splash) {
    splash.setAttribute("aria-label", t("ui.auth-boot.opening-name", { name }));
    const eyebrow = splash.querySelector(".eyebrow");
    if (eyebrow) eyebrow.textContent = name;
  }
  TITLE_GENERIC = name === "Alt8Mail" ? t("ui.mandatory-first-login-onboarding.alt8mail-secure-ai-powered-email-that-thinks-wit") : t("app.windowTitleGeneric", { name });
  TITLE_LOGIN = name === "Alt8Mail" ? t("ui.mandatory-first-login-onboarding.alt8mail-secure-email-with-ai-built-in-sign-in") : t("app.windowTitleSignIn", { name });
  let message = document.getElementById("tenantLoginMessage");
  if (loginMessage) {
    if (!message) {
      message = document.createElement("p");
      message.id = "tenantLoginMessage";
      message.className = "login-demo tenant-login-message";
      document.querySelector(".login-heading")?.appendChild(message);
    }
    message.textContent = loginMessage;
  } else if (message) {
    message.remove();
  }
  const foot = document.querySelector(".login-card-foot");
  let support = document.getElementById("tenantSupportLink");
  const safeSupport = supportEmail.replace(/[^a-zA-Z0-9@._+-]/g, "");
  if (foot && safeSupport.includes("@")) {
    if (!support) {
      support = document.createElement("a");
      support.id = "tenantSupportLink";
      support.style.marginLeft = "8px";
      support.style.color = "var(--accent-ink)";
      foot.appendChild(support);
    }
    support.href = `mailto:${safeSupport}`;
    support.textContent = safeSupport;
  } else if (support) {
    support.remove();
  }
  const legal = document.querySelector('.login-card-foot [data-i18n="login.legal"]');
  if (legal) {
    legal.removeAttribute("data-i18n");
    legal.textContent = branding.hideAttribution ? t("ui.mandatory-first-login-onboarding.tls-1-3") : t("ui.mandatory-first-login-onboarding.protected-by-name-tls", { name });
  }
  const heading = document.querySelector(".login-heading");
  const logoURL = String(branding.logoUrl || "").trim();
  let logo = document.getElementById("tenantLogo");
  if (heading && /^https:\/\//i.test(logoURL)) {
    if (!logo) {
      logo = document.createElement("img");
      logo.id = "tenantLogo";
      logo.className = "tenant-logo";
      logo.style.cssText = "display:block;max-height:48px;max-width:180px;margin:0 auto 18px;object-fit:contain";
      heading.prepend(logo);
    }
    logo.alt = name;
    logo.hidden = false;
    logo.onerror = () => { logo.hidden = true; };
    if (logo.getAttribute("src") !== logoURL) logo.src = logoURL;
  } else if (logo) {
    logo.remove();
  }
  const addFooterLink = (id, label, href) => {
    if (!foot) return;
    const safeHref = String(href || "").trim();
    let link = document.getElementById(id);
    if (!/^https:\/\//i.test(safeHref)) {
      if (link) link.remove();
      return;
    }
    if (!link) {
      link = document.createElement("a");
      link.id = id;
      link.style.marginLeft = "8px";
      link.style.color = "var(--accent-ink)";
      foot.appendChild(link);
    }
    link.href = safeHref;
    link.textContent = label;
    link.target = "_blank";
    link.rel = "noopener noreferrer";
  };
  addFooterLink("tenantSupportUrl", t("ui.mandatory-first-login-onboarding.support"), branding.supportUrl);
  addFooterLink("tenantLegalUrl", t("ui.helpers.legal"), branding.legalUrl);
  if (branding.hideAttribution) {
    document.querySelectorAll(".login-legal").forEach((node) => {
      const parts = String(node.textContent || "").split("·").map((part) => part.trim()).filter(Boolean);
      const remaining = parts.filter((part) => part !== name).join(" · ");
      node.textContent = remaining || t("ui.mandatory-first-login-onboarding.workspace-environment");
    });
  }
  updateDocumentTitle();
}

async function loadTenantBranding() {
  try {
    const response = await fetch("/api/branding", {
      method: "GET", credentials: "same-origin", cache: "no-store",
      headers: { Accept: "application/json" },
    });
    if (!response.ok) return;
    applyTenantBranding(await response.json());
  } catch (_) {
    // Branding is progressive enhancement; the default identity remains.
  }
}

function setOffline(offline) {
  const next = !!offline;
  if (state.offline === next) return;
  state.offline = next;
  updateDocumentTitle();
  if (offlineBanner) offlineBanner.hidden = !next;
  const dot = document.getElementById("connDot");
  const text = document.getElementById("connText");
  if (dot) dot.classList.toggle("is-offline", next);
  if (text) text.textContent = next ? t("shell.offline") : t("shell.connected");
  if (statusMid && next) statusMid.textContent = t("shell.offlineCachedShell");
  if (!next) {
    syncStatusContext();
    if (state.user) refreshMailbox({ quiet: true }).catch(() => {});
  }
}

/* ============================================================
   theme + preferences
   ============================================================ */
function effectiveTheme() {
  const explicit = document.documentElement.getAttribute("data-theme");
  if (explicit) return explicit;
  return window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
}

function setTheme(mode, save = true) {
  if (!["light", "dark", "system"].includes(mode)) mode = "system";
  state.theme = mode;
  if (mode === "system") document.documentElement.removeAttribute("data-theme");
  else document.documentElement.setAttribute("data-theme", mode);
  if (save) {
    prefs.set("theme", mode);
    if (state.user && state.csrf) patchPreferences({ theme: mode }, null);
  }
  syncThemeUI();
}

function applyReaderLightMode() {
  const button = document.getElementById("readerLightBtn");
  const dark = effectiveTheme() === "dark";
  const active = dark && Boolean(state.readerLightMode);
  reader?.classList.toggle("is-light-message", active);
  if (button) {
    button.hidden = !dark;
    button.setAttribute("aria-pressed", active ? "true" : "false");
    button.classList.toggle("is-active", active);
    button.title = active ? t("ui.theme-preferences.return-the-message-to-the-dark-reading-backgroun") : t("ui.theme-preferences.read-message-on-a-light-background");
  }
}

function syncThemeUI() {
  const mode = effectiveTheme();
  applyReaderLightMode();
  const themeBtn = document.getElementById("themeBtn");
  if (themeBtn) {
    const label = mode === "dark" ? t("ui.theme-preferences.switch-to-light-theme") : t("ui.theme-preferences.switch-to-dark-theme");
    themeBtn.setAttribute("aria-label", label);
    themeBtn.title = label;
  }
  $$("[data-set-theme]").forEach((button) => {
    const active = button.getAttribute("data-set-theme") === state.theme;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-checked", active ? "true" : "false");
  });
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) meta.content = mode === "dark" ? "#0b1a2b" : "#093256";
  syncOfficeEditorTheme();
}

function setAccent(key, save = true) {
  if (!ACCENTS[key]) key = "blue";
  state.accent = key;
  document.documentElement.style.setProperty("--accent", ACCENTS[key].value);
  if (save) {
    prefs.set("accent", key);
    if (state.user && state.csrf) patchPreferences({ accent: key }, null);
  }
  $$("[data-set-accent]").forEach((button) => {
    const active = button.getAttribute("data-set-accent") === key;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-checked", active ? "true" : "false");
  });
}

function loadFolderDensity() {
  try { state.folderDensity = JSON.parse(localStorage.getItem("a8m.folderDensity") || "{}") || {}; }
  catch { state.folderDensity = {}; }
}

function saveFolderDensity() {
  try { localStorage.setItem("a8m.folderDensity", JSON.stringify(state.folderDensity || {})); } catch {}
}

function applyFolderDensity(folder = state.folder) {
  const override = state.folderDensity?.[folder];
  const mode = override === "compact" || override === "comfortable" ? override : state.density;
  app.setAttribute("data-density", mode);
  $$("[data-set-density]").forEach((button) => {
    const active = button.getAttribute("data-set-density") === state.density;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-checked", active ? "true" : "false");
  });
}

function renderFolderDensitySettings() {
  const host = document.getElementById("folderDensitySettings");
  if (!host) return;
  const folders = (state.folders || []).filter((folder) => !folder.virtual);
  if (!folders.length) {
    host.innerHTML = "<div class=\"settings-note\">" + t("ui.theme-preferences.no-folders-available-yet") + "</div>";
    return;
  }
  host.innerHTML = `<div class="pref-list">${folders.map((folder) => {
    const label = folder.label || folder.id;
    const override = state.folderDensity?.[folder.id];
    const hint = override ? t("ui.theme-preferences.override-active", { density: override === "compact" ? t("ui.theme-preferences.compact") : t("ui.theme-preferences.comfortable") }) : t("ui.theme-preferences.follows-the-default-density");
    return `<div class="pref-row folder-density-row">
      <span class="folder-density-icon"${folder.color ? ` style="color:${esc(folder.color)}"` : ""}><svg class="icon" aria-hidden="true"><use href="#${esc(folder.icon || "i-folder")}"/></svg></span>
      <div class="pref-copy"><strong>${esc(label)}</strong><span>${esc(hint)}</span></div>
      <select class="pref-select" data-folder-density="${esc(folder.id)}" aria-label="${esc(t("ui.theme-preferences.density-for", { folder: label }))}">
        <option value="">${esc(t("ui.theme-preferences.default-density", { density: state.density }))}</option>
        <option value="comfortable"${override === "comfortable" ? " selected" : ""}>${t("ui.theme-preferences.comfortable")}</option>
        <option value="compact"${override === "compact" ? " selected" : ""}>${t("ui.theme-preferences.compact")}</option>
      </select>
    </div>`;
  }).join("")}</div>`;
  $$("[data-folder-density]", host).forEach((select) => select.addEventListener("change", () => {
    const folder = select.dataset.folderDensity;
    if (!select.value) delete state.folderDensity[folder];
    else state.folderDensity[folder] = select.value;
    saveFolderDensity();
    if (folder === state.folder) applyFolderDensity(folder);
    const hint = select.closest(".folder-density-row")?.querySelector(".pref-copy span");
    if (hint) hint.textContent = state.folderDensity[folder]
      ? t("ui.theme-preferences.override-active", { density: state.folderDensity[folder] === "compact" ? t("ui.theme-preferences.compact") : t("ui.theme-preferences.comfortable") })
      : t("ui.theme-preferences.follows-the-default-density");
    showToast(t("ui.theme-preferences.folder-density-saved"));
  }));
}

function setHighContrast(enabled, save = true) {
  state.highContrast = !!enabled;
  if (state.highContrast) document.documentElement.setAttribute("data-contrast", "high");
  else document.documentElement.removeAttribute("data-contrast");
  const toggle = document.getElementById("highContrastToggle");
  if (toggle) toggle.setAttribute("aria-checked", state.highContrast ? "true" : "false");
  if (save) {
    try { localStorage.setItem("a8m.highContrast", state.highContrast ? "1" : "0"); } catch {}
  }
}

function setDensity(mode, save = true) {
  if (mode !== "compact") mode = "comfortable";
  state.density = mode;
  app.setAttribute("data-density", mode);
  if (save) {
    prefs.set("density", mode);
    if (state.user && state.csrf) patchPreferences({ density: mode }, null);
  }
  $$("[data-set-density]").forEach((button) => {
    const active = button.getAttribute("data-set-density") === mode;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-checked", active ? "true" : "false");
  });
  applyFolderDensity(state.folder);
  const hint = document.getElementById("densityHint");
  if (hint) hint.textContent = mode === "compact"
    ? t("ui.theme-preferences.two-line-rows-without-the-preview-line-more-conv")
    : t("ui.theme-preferences.three-line-rows-with-a-subject-and-preview-line");
}

function setPreference(key, value, save = true) {
  state[key] = !!value;
  $$(`[data-pref="${key}"]`).forEach((control) => {
    control.setAttribute("aria-checked", state[key] ? "true" : "false");
  });
  if (save) {
    prefs.set(key, state[key] ? "1" : "0");
    if (key === "notifyDesktop") {
      if (value) {
        if ("Notification" in window && Notification.permission === "default") {
          Notification.requestPermission().then((permission) => {
            if (permission === "granted" && state.notifyDesktop) registerPushSubscription({ quiet: true }).catch(() => {});
          }).catch(() => {});
        } else if ("Notification" in window && Notification.permission === "granted") {
          registerPushSubscription({ quiet: true }).catch(() => {});
        }
      } else {
        unregisterPushSubscription({ silent: true }).catch(() => {});
      }
    }
    if (state.user && state.csrf) patchPreferences({ [key]: state[key] }, t("ui.events.preference-saved"));
  }
  if (key === "externalWarnings") {
    renderReader();
  }
}

function maxUndoSendSeconds() {
  const configured = Number(state.tenantPolicy?.mail?.undoSendSeconds);
  return configured >= 5 && configured <= 60 ? configured : 60;
}

function normalizeUndoSendSeconds(value) {
  const seconds = Number(value);
  if (!Number.isFinite(seconds) || seconds < 5) return Math.min(8, maxUndoSendSeconds());
  return Math.min(seconds, maxUndoSendSeconds());
}

function loadPreferences() {
  const read = (key, fallback) => {
    const value = prefs.get(key);
    return value === null ? fallback : value !== "0";
  };
  setPreference("markReadOnOpen", read("markReadOnOpen", true), false);
  setPreference("defaultReceipt", read("defaultReceipt", false), false);
  setPreference("notifyDesktop", read("notifyDesktop", true), false);
  setPreference("notifySound", read("notifySound", false), false);
  setPreference("notifyCalendar", read("notifyCalendar", true), false);
  setPreference("externalWarnings", read("externalWarnings", true), false);
  state.defaultPriority = ["low", "normal", "high"].includes(prefs.get("defaultPriority")) ? prefs.get("defaultPriority") : "normal";
  state.undoSendSeconds = normalizeUndoSendSeconds(prefs.get("undoSendSeconds"));
  const prioritySelect = document.getElementById("defaultPrioritySelect");
  if (prioritySelect) prioritySelect.value = state.defaultPriority;
  const undoSelect = document.getElementById("undoSendSelect");
  if (undoSelect) undoSelect.value = String(state.undoSendSeconds);
}

function applySavedPreferences() {
  // Pre-sign-in cache only: avoids a theme flash on the login card. Once a
  // session exists, applyServerPreferences() replaces every value from DB.
  const savedTheme = prefs.get("theme");
  if (savedTheme === "light" || savedTheme === "dark") setTheme(savedTheme, false);
  else { state.theme = "system"; syncThemeUI(); }
  setAccent(ACCENTS[prefs.get("accent")] ? prefs.get("accent") : "blue", false);
  setDensity(prefs.get("density") === "compact" ? "compact" : "comfortable", false);
  loadFolderDensity();
  applyFolderDensity(state.folder);
  setHighContrast(prefs.get("highContrast") === "1", false);
  loadPreferences();
}

function applyServerPreferences() {
  const p = state.preferences || {};
  setTheme(p.theme || "system", false);
  setAccent(p.accent || "blue", false);
  setDensity(p.density || "comfortable", false);
  applyFolderDensity(state.folder);
  if (p.language && currentLocale() !== "en-XA") {
    prefs.set("language", p.language);
    setLocale(p.language).then((actual) => {
      if (actual && actual !== p.language) {
        // The Control Plane disabled the stored language while this account
        // was away. Heal both the local cache and the server preference.
        prefs.set("language", actual);
        patchPreferences({ language: actual }, "").catch(() => {});
      }
    }).catch(() => {});
  }
  for (const key of ["markReadOnOpen", "defaultReceipt", "notifyDesktop", "notifySound", "notifyCalendar", "externalWarnings"]) {
    setPreference(key, p[key] !== false, false);
  }
  state.defaultPriority = ["low", "normal", "high"].includes(p.defaultPriority) ? p.defaultPriority : "normal";
  state.undoSendSeconds = normalizeUndoSendSeconds(p.undoSendSeconds);
  const prioritySelect = document.getElementById("defaultPrioritySelect");
  if (prioritySelect) prioritySelect.value = state.defaultPriority;
  const undoSelect = document.getElementById("undoSendSelect");
  if (undoSelect) undoSelect.value = String(state.undoSendSeconds);
  // Keep the offline/login cache aligned with the authoritative DB row.
  prefs.set("theme", state.theme);
  prefs.set("accent", state.accent);
  prefs.set("density", state.density);
  for (const key of ["markReadOnOpen", "defaultReceipt", "notifyDesktop", "notifySound", "notifyCalendar", "externalWarnings"]) {
    prefs.set(key, state[key] ? "1" : "0");
  }
  if (!state.cabinetViewPending && ["list", "tiles", "thumbs"].includes(p.cabinetView)) {
    state.fileView = p.cabinetView;
    prefs.set("cabinet.view", state.fileView);
  }
  prefs.set("defaultPriority", state.defaultPriority);
  prefs.set("undoSendSeconds", String(state.undoSendSeconds));
}

/* ============================================================
   server-backed workspace preferences
   ============================================================ */
function timeZoneOptions() {
  let zones = [];
  try {
    zones = Intl.supportedValuesOf ? Intl.supportedValuesOf("timeZone") : [];
  } catch {}
  if (!zones.length) {
    zones = ["UTC", "America/Los_Angeles", "America/New_York", "America/Chicago", "America/Denver", "Europe/London", "Europe/Berlin", "Europe/Paris", "Asia/Dubai", "Asia/Kolkata", "Asia/Singapore", "Asia/Tokyo", "Australia/Sydney"];
  }
  const current = currentTimeZone();
  if (current && !zones.includes(current)) zones = [current, ...zones];
  return zones;
}

function syncPreferencesUi() {
  if (!state.preferences) return;
  const preferences = state.preferences;
  setTheme(preferences.theme || "system", false);
  setAccent(preferences.accent || "blue", false);
  setDensity(preferences.density || "comfortable", false);
  for (const key of ["markReadOnOpen", "defaultReceipt", "notifyDesktop", "notifySound", "notifyCalendar", "externalWarnings"]) {
    state[key] = preferences[key] !== false;
    $$(`[data-pref="${key}"]`).forEach((control) => control.setAttribute("aria-checked", state[key] ? "true" : "false"));
  }
  const externalToggle = document.getElementById("externalWarningToggle");
  if (externalToggle) externalToggle.setAttribute("aria-checked", state.externalWarnings ? "true" : "false");
  state.defaultPriority = ["low", "normal", "high"].includes(preferences.defaultPriority) ? preferences.defaultPriority : "normal";
  state.undoSendSeconds = normalizeUndoSendSeconds(preferences.undoSendSeconds);
  const priorityControl = document.getElementById("defaultPrioritySelect");
  if (priorityControl) priorityControl.value = state.defaultPriority;
  const undoControl = document.getElementById("undoSendSelect");
  if (undoControl) undoControl.value = String(state.undoSendSeconds);
  const composeModeControl = document.getElementById("composeModeSelect");
  if (composeModeControl) composeModeControl.value = preferences.composeMode === "plain" ? "plain" : "html";
  const composeWidthControl = document.getElementById("composeWidthSelect");
  if (composeWidthControl) composeWidthControl.value = preferences.composeWidth || "wide";
  const composePositionControl = document.getElementById("composePositionSelect");
  if (composePositionControl) composePositionControl.value = preferences.composePosition || "center";
  const inboxViewControl = document.getElementById("inboxViewSelect");
  if (inboxViewControl) inboxViewControl.value = preferences.inboxView === "individual" ? "individual" : "grouped";
  if (languageSelect) {
    setLanguageSelectValue(languageSelect, preferences.language);
  }
  if (dateFormatSelect) dateFormatSelect.value = preferences.dateFormat || "auto";
  if (weekStartSelect) weekStartSelect.value = preferences.weekStart || "monday";
  if (timeZoneSelect) {
    if (timeZoneSelect.options.length < 3 || !Array.from(timeZoneSelect.options).some((option) => option.value === preferences.timeZone)) {
      timeZoneSelect.innerHTML = timeZoneOptions().map((zone) => `<option value="${esc(zone)}">${esc(zone.replace(/_/g, " "))}</option>`).join("");
    }
    timeZoneSelect.value = preferences.timeZone || "UTC";
  }
  $$("[data-time-format]").forEach((button) => {
    const active = button.getAttribute("data-time-format") === (preferences.timeFormat || "12h");
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-checked", active ? "true" : "false");
  });
  if (workStartInput) workStartInput.value = preferences.workStart || "09:00";
  if (workEndInput) workEndInput.value = preferences.workEnd || "17:00";
  if (workdayRow) {
    $$("[data-work-day]", workdayRow).forEach((button) => {
      const active = (preferences.workDays || []).includes(Number(button.getAttribute("data-work-day")));
      button.setAttribute("aria-pressed", active ? "true" : "false");
    });
  }
  if (defaultFromSelect) {
    const options = aliasesForSelect().map((alias) => `<option value="${esc(alias.email)}">${esc(alias.label)} — ${esc(alias.email)}</option>`).join("");
    if (defaultFromSelect.innerHTML !== options) defaultFromSelect.innerHTML = options;
    const fallback = aliasesForSelect()[0] ? aliasesForSelect()[0].email : "";
    defaultFromSelect.value = preferences.defaultFrom || fallback;
  }
  $$("[data-server-pref]").forEach((control) => {
    const key = control.getAttribute("data-server-pref");
    control.setAttribute("aria-checked", state.preferences[key] ? "true" : "false");
  });
  renderRegionalSettings();
  const zoneHint = document.getElementById("timeZoneHint");
  if (zoneHint) zoneHint.textContent = t("ui.server-backed-workspace-preferences.timestamps-use-zone", { zone: formatTimeZoneLabel() });
}

function renderRegionalSettings() {
  if (!regionalPreview) return;
  const now = new Date();
  const full = new Intl.DateTimeFormat(currentLocale(), {
    weekday: "long", year: "numeric", month: "long", day: "numeric",
    hour: "numeric", minute: "2-digit",
    hour12: state.preferences.timeFormat !== "24h",
    timeZone: currentTimeZone()
  }).format(now);
  const start = zonedWallTimeToUtc(dateKeyInZone(now), state.preferences.workStart || "09:00");
  const end = zonedWallTimeToUtc(dateKeyInZone(now), state.preferences.workEnd || "17:00");
  const dayNames = [t("ui.server-backed-workspace-preferences.mon"), t("ui.server-backed-workspace-preferences.tue"), t("ui.server-backed-workspace-preferences.wed"), t("ui.server-backed-workspace-preferences.thu"), t("ui.server-backed-workspace-preferences.fri"), t("ui.server-backed-workspace-preferences.sat"), t("ui.server-backed-workspace-preferences.sun")];
  const workDays = (state.preferences.workDays || []).map((day) => dayNames[day - 1]).join(", ");
  regionalPreview.innerHTML = `<span class="regional-preview-label">${esc(t("ui.server-backed-workspace-preferences.preview-in-zone", { zone: currentTimeZone().replace(/_/g, " ") }))}</span>
    <strong>${esc(full)}</strong>
    <span>${esc(formatTimeZoneLabel())}</span>
    <span>${esc(t("ui.server-backed-workspace-preferences.work-hours-range", { start: start ? formatClock(start) : "", end: end ? formatClock(end) : "", days: workDays || t("ui.server-backed-workspace-preferences.no-working-days") }))}</span>
    <span>${esc(new Intl.DateTimeFormat(currentLocale(), { dateStyle: "full", timeZone: currentTimeZone() }).format(now))}</span>`;
}

async function patchPreferences(patch, message = t("common.saved")) {
  try {
    const data = await api("/api/preferences", { method: "PATCH", body: patch });
    state.preferences = { ...state.preferences, ...data.preferences };
    if (state.user) state.user.preferences = state.preferences;
    applyPreferenceChrome();
    syncPreferencesUi();
    rerenderAfterPreferenceChange();
    if (message) showToast(message);
    return true;
  } catch (error) {
    showError(error);
    syncPreferencesUi();
    return false;
  }
}

function setLanguageSelectValue(select, preferred) {
  if (!select) return;
  populateLanguageSelect(select);
  select.value = preferred || currentLocale();
  if (!select.value) select.value = currentLocale();
  if (!select.value && select.options.length) select.selectedIndex = 0;
}

async function changeLanguage(value) {
  const previous = currentLocale();
  prefs.set("language", value);
  const saved = await patchPreferences({ language: value }, "");
  if (!saved) {
    prefs.set("language", previous);
    syncPreferencesUi();
    return;
  }
  await setLocale(value);
  const actual = currentLocale();
  if (actual !== value) {
    // The language was disabled between rendering the picker and saving.
    // Persist the effective fallback so the account does not keep an
    // unusable value, then report it through the refreshed selector.
    prefs.set("language", actual);
    await patchPreferences({ language: actual }, "");
    syncPreferencesUi();
    return;
  }
  // A full reload guarantees every dynamic surface is rebuilt in the new
  // locale; incremental re-rendering arrives with the feature modules.
  window.location.reload();
}

function rerenderAfterPreferenceChange() {
  if (state.task === "mail") {
    renderFolders();
    renderList();
    renderReader({ preserveScroll: true });
    syncStatusRange();
  } else if (state.task === "tasks") {
    renderTasks();
  } else if (state.task === "files") {
    renderFiles();
  } else if (state.task === "calendar") {
    renderCalendar();
  } else if (state.task === "settings") {
    renderRegionalSettings();
    renderAuditIfVisible();
  }
  if (!detailsOverlay.hidden) closeDetails();
}

function renderAuditIfVisible() {
  if (state.task === "settings" && state.settingsTab === "audit") renderAudit();
}

/* ============================================================
   toast
   ============================================================ */
/* ============================================================
   auth / boot
   ============================================================ */
const AUTH_SPLASH_HOLD_MS = 5000;
const LOGOUT_SPLASH_MS = 6000;
let bootSplashHideTimer = null;
let logoutInProgress = false;

function hideBootSplash() {
  if (!bootSplash) return;
  clearTimeout(bootSplashHideTimer);
  bootSplash.classList.add("is-hiding");
  bootSplashHideTimer = setTimeout(() => { bootSplash.hidden = true; }, 380);
}

function showBootSplash(note = t("auth.restoringSession")) {
  if (!bootSplash) return;
  clearTimeout(bootSplashHideTimer);
  bootSplash.hidden = false;
  bootSplash.classList.remove("is-hiding", "is-logout");
  bootSplash.setAttribute("aria-label", t("auth.openingApp"));
  const heading = bootSplash.querySelector("h1");
  if (heading) heading.textContent = t("auth.openingWorkspace");
  const copy = bootSplash.querySelector("p:not(.eyebrow)");
  if (copy) copy.textContent = note;
  // Restart the progress animation when the splash is shown a second time.
  void bootSplash.offsetWidth;
}

function showLogoutSplash() {
  if (!bootSplash) return;
  clearTimeout(bootSplashHideTimer);
  bootSplash.hidden = false;
  bootSplash.classList.remove("is-hiding");
  bootSplash.classList.add("is-logout");
  bootSplash.setAttribute("aria-label", t("auth.closingApp", { name: brandName() }));
  const heading = bootSplash.querySelector("h1");
  if (heading) heading.textContent = t("auth.closingWorkspace");
  const copy = bootSplash.querySelector("p:not(.eyebrow)");
  if (copy) copy.textContent = t("auth.sessionEnding");
  void bootSplash.offsetWidth;
}

function clearThemeAccentForLogout() {
  // The login card must not inherit the previous account's accent. Remove the
  // pre-sign-in cache and any legacy accent cookie, then restore the default.
  try {
    for (const key of Object.keys(localStorage)) {
      if (/accent/i.test(key)) localStorage.removeItem(key);
    }
  } catch {}
  try {
    for (const entry of document.cookie.split(";")) {
      const name = entry.split("=")[0].trim();
      if (name && /accent/i.test(name)) {
        document.cookie = `${name}=; Max-Age=0; path=/; SameSite=Lax`;
      }
    }
  } catch {}
  state.accent = "blue";
  document.documentElement.style.setProperty("--accent", ACCENTS.blue.value);
  if (tenantBranding) applyTenantBranding(tenantBranding);
  $$("[data-set-accent]").forEach((button) => {
    const active = button.getAttribute("data-set-accent") === "blue";
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-checked", active ? "true" : "false");
  });
}

function renderSsoButton() {
  if (ssoDivider) ssoDivider.hidden = !(ssoEnabled || samlEnabled);
  renderOidcButton();
  renderSamlButton();
}

function renderOidcButton() {
  if (!ssoBtn) return;
  ssoBtn.hidden = !ssoEnabled;
  ssoBtn.disabled = false;
  if (!ssoEnabled) return;
  const label = ssoDisplayName || t("login.sso");
  const translation = ssoDisplayName ? "" : ' data-i18n="login.sso"';
  ssoBtn.innerHTML = `<svg class="icon" aria-hidden="true"><use href="#i-shield-check"/></svg><span${translation}>${esc(label)}</span>`;
}

function renderSamlButton() {
  if (!samlBtn) return;
  samlBtn.hidden = !samlEnabled;
  samlBtn.disabled = false;
  if (!samlEnabled) return;
  const label = samlDisplayName || t("login.saml");
  const translation = samlDisplayName ? "" : ' data-i18n="login.saml"';
  samlBtn.innerHTML = `<svg class="icon" aria-hidden="true"><use href="#i-shield-check"/></svg><span${translation}>${esc(label)}</span>`;
}

function setSsoButtonsDisabled(disabled) {
  if (ssoBtn) ssoBtn.disabled = disabled;
  if (samlBtn) samlBtn.disabled = disabled;
}

async function loadSsoConfig() {
  const seq = ++ssoConfigSeq;
  let enabled = false;
  let displayName = "";
  try {
    const config = await api("/api/auth/oidc/config", { skipAuth: true });
    enabled = Boolean(config && config.enabled);
    displayName = String((config && config.displayName) || "").trim();
  } catch {}
  if (seq !== ssoConfigSeq) return;
  ssoEnabled = enabled;
  ssoDisplayName = displayName;
  renderSsoButton();
}

async function loadSamlConfig() {
  const seq = ++samlConfigSeq;
  let enabled = false;
  let displayName = "";
  try {
    const config = await api("/api/auth/saml/config", { skipAuth: true });
    enabled = Boolean(config && config.enabled);
    displayName = String((config && config.displayName) || "").trim();
  } catch {}
  if (seq !== samlConfigSeq) return;
  samlEnabled = enabled;
  samlDisplayName = displayName;
  renderSsoButton();
}

function consumeSsoError() {
  try {
    const url = new URL(window.location.href);
    const code = url.searchParams.get("sso_error") || url.searchParams.get("saml_error");
    if (!code) return "";
    url.searchParams.delete("sso_error");
    url.searchParams.delete("saml_error");
    const search = url.searchParams.toString();
    window.history.replaceState({}, "", url.pathname + (search ? `?${search}` : "") + url.hash);
    return code;
  } catch {
    return "";
  }
}

function resetLoginButtons() {
  loginBusy = false;
  if (loginSubmit) { loginSubmit.disabled = false; loginSubmit.textContent = t("login.signIn"); }
  renderSsoButton();
  if (twoFactorSubmit) { twoFactorSubmit.disabled = false; twoFactorSubmit.textContent = t("auth.verifyAndSignIn"); }
  if (usePasskeyBtn) usePasskeyBtn.disabled = false;
}

function showLogin() {
  document.querySelector(".delegated-closed-card")?.remove();
  closeAddonSetup();
  closeAddonResult();
  closeReaderAddonMenu();
  composeSessions.slice().forEach((session) => removeComposeSessionUi(session.id));
  composeSessions = [];
  state.user = null;
  avatarFailures.clear();
  threadIdAliases.clear();
  if (aiAttachmentPicker) settleAiAttachmentPicker([]);
  state.pendingMailRemoval.clear();
  state.notifications = [];
  state.dismissedNotifications = new Set();
  state.aiReader = null;
  activeComposeId = null;
  updateComposeDock();
  hideNotify();
  closeNoticeCenter();
  closeComposeAttach();
  hideToast();
  closeMenus();
  closeHelp();
  closeDetails();
  closeEventDialog();
  closeStatusPop();
  closeDrawer();
  document.body.classList.remove("composing", "drawer-open", "search-open", "reader-open", "person-open");
  loginScreen.hidden = false;
  app.hidden = true;
  loginError.hidden = true;
  loginHint.hidden = true;
  loginForm.hidden = false;
  twoFactorForm.hidden = true;
  const enrollment = document.getElementById("enrollmentForm");
  if (enrollment) enrollment.hidden = true;
  twoFactorChallenge = null;
  state.enrollmentChallenge = null;
  hidePasskeyPrompt();
  loginPassword.type = "password";
  const toggle = document.getElementById("passwordToggle");
  if (toggle) toggle.textContent = t("login.showPassword");
  resetLoginButtons();
  if (consumeSsoError()) {
    loginError.textContent = t("login.ssoFailed");
    loginError.hidden = false;
  }
  loadSsoConfig().catch(() => {});
  loadSamlConfig().catch(() => {});
  loginScreen.scrollTop = 0;
  setTimeout(() => { if (loginEmail && !isMobile()) loginEmail.focus(); }, 60);
  stopOutboxPolling();
  const passwordOverlay = document.getElementById("passwordChangeOverlay");
  if (passwordOverlay) passwordOverlay.hidden = true;
  if (onboardingOverlay) onboardingOverlay.hidden = true;
  if (signatureEditorOverlay) signatureEditorOverlay.hidden = true;
  if (signaturePickerOverlay) signaturePickerOverlay.hidden = true;
  if (spellcheckOverlay) spellcheckOverlay.hidden = true;
  if (identityEditorOverlay) identityEditorOverlay.hidden = true;
  if (folderEditorOverlay) folderEditorOverlay.hidden = true;
  if (folderMenu) folderMenu.hidden = true;
  state.folderEditor = null;
  state.signatureEditor = null;
  state.identityEditor = null;
  state.spellcheck = null;
  state.imageOverrides = new Set();
  document.body.classList.remove("onboarding-active");
  if (app) app.inert = false;
  if (state.pendingSends.length && state.user) {
    // A signed-out tab cannot cancel; data remains in the server queue.
  }
  updateDocumentTitle();
  hideBootSplash();
}

async function finishSignIn(data, { holdSplashMs = 0 } = {}) {
  const splashStartedAt = Date.now();
  if (holdSplashMs > 0) showBootSplash(t("auth.authenticationConfirmed"));
  state.csrf = data.csrf || state.csrf;
  loginScreen.hidden = true;
  app.hidden = false;
  loginForm.hidden = false;
  twoFactorForm.hidden = true;
  const enrollmentForm = document.getElementById("enrollmentForm");
  if (enrollmentForm) enrollmentForm.hidden = true;
  twoFactorChallenge = null;
  state.enrollmentChallenge = null;
  hidePasskeyPrompt();
  resetLoginButtons();
  await loadBootstrap({ restoreDrafts: true });
  loadCatchUp().catch(() => {});
  restoreNavigationFromLocation();
  requestAnimationFrame(layoutComposeSessions);
  if (holdSplashMs > 0) {
    const copy = bootSplash?.querySelector("p:not(.eyebrow)");
    if (copy) copy.textContent = t("auth.mailboxReady");
    const remaining = holdSplashMs - (Date.now() - splashStartedAt);
    if (remaining > 0) await new Promise((resolve) => setTimeout(resolve, remaining));
  }
  hideBootSplash();
}

function finishAuthenticatedSignIn(data) {
  return finishSignIn(data, { holdSplashMs: AUTH_SPLASH_HOLD_MS }).catch((error) => {
    hideBootSplash();
    throw error;
  });
}

async function submitLogin() {
  if (loginBusy) return;
  const email = loginEmail.value.trim();
  const password = loginPassword.value;
  loginError.hidden = true;
  loginHint.hidden = true;
  if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
    loginError.textContent = t("login.invalidEmail");
    loginError.hidden = false;
    loginEmail.focus();
    return;
  }
  if (!password) {
    loginError.textContent = t("login.passwordRequired");
    loginError.hidden = false;
    loginPassword.focus();
    return;
  }
  loginBusy = true;
  loginSubmit.disabled = true;
  loginSubmit.textContent = t("login.signingIn");
  setSsoButtonsDisabled(true);
  try {
    const remember = document.getElementById("rememberMe").checked;
    const data = await api("/api/session", {
      method: "POST",
      skipAuth: true,
      body: { email, password, method: "password", remember }
    });
    if (data.twoFactorRequired) {
      resetLoginButtons();
      showTwoFactorChallenge(data, remember);
      return;
    }
    if (data.enrollmentRequired) {
      resetLoginButtons();
      showEnrollmentChallenge(data, remember);
      return;
    }
    state.csrf = data.csrf;
    await finishAuthenticatedSignIn(data);
  } catch (error) {
    loginError.textContent = error.message;
    loginError.hidden = false;
    resetLoginButtons();
  }
}

function submitSso() {
  if (loginBusy || !ssoEnabled) return;
  loginBusy = true;
  loginError.hidden = true;
  loginHint.hidden = true;
  loginSubmit.disabled = true;
  setSsoButtonsDisabled(true);
  ssoBtn.innerHTML = `<svg class="icon" aria-hidden="true"><use href="#i-shield-check"/></svg><span>${esc(t("login.connectingSso"))}</span>`;
  const remember = document.getElementById("rememberMe").checked ? "1" : "0";
  window.location.assign(`/api/auth/oidc/start?remember=${remember}`);
}

function submitSaml() {
  if (loginBusy || !samlEnabled) return;
  loginBusy = true;
  loginError.hidden = true;
  loginHint.hidden = true;
  loginSubmit.disabled = true;
  setSsoButtonsDisabled(true);
  samlBtn.innerHTML = `<svg class="icon" aria-hidden="true"><use href="#i-shield-check"/></svg><span>${esc(t("login.connectingSso"))}</span>`;
  // SAML sessions do not support "Remember me" in this tranche.
  window.location.assign("/api/auth/saml/start");
}

function showTwoFactorChallenge(data, remember) {
  twoFactorChallenge = { ...data, remember };
  state.twoFactor = data;
  loginForm.hidden = true;
  twoFactorForm.hidden = false;
  loginError.hidden = true;
  loginHint.hidden = true;
  twoFactorError.hidden = true;
  const user = data.user || {};
  const avatarEl = document.getElementById("twoFactorAvatar");
  if (avatarEl) {
    avatarEl.textContent = user.initials || initialsFrom(user.name || "");
    avatarEl.style.setProperty("--av", user.color || "#34557a");
  }
  document.getElementById("twoFactorName").textContent = user.name || t("auth.alt8MailAccount");
  document.getElementById("twoFactorEmail").textContent = user.email || loginEmail.value.trim();
  const passkey = (data.passkeys || [])[0];
  const passkeyPanel = document.getElementById("passkeyPanel");
  const canPasskey = Boolean(data.methods && data.methods.passkey);
  passkeyPanel.hidden = !canPasskey;
  if (canPasskey) {
    document.getElementById("passkeyName").textContent = passkey ? passkey.name : t("auth.registeredPasskey");
  }
  const canAuthenticator = Boolean(data.methods && data.methods.authenticator);
  const canRecovery = Boolean(data.methods && data.methods.recovery);
  const demo = canAuthenticator && data.demoCode ? data.demoCode : "";
  twoFactorDemo.hidden = !demo;
  if (demo) document.getElementById("twoFactorDemoCode").textContent = demo;
  document.getElementById("recoveryModeBtn").hidden = !canRecovery;
  document.getElementById("otpModeBtn").hidden = !canAuthenticator;
  $$("#otpInputs input").forEach((input) => { input.value = ""; input.disabled = !canAuthenticator; });
  document.getElementById("recoveryCode").value = "";
  document.getElementById("trustDevice").checked = false;
  setTwoFactorMode(canAuthenticator ? "otp" : "recovery", { focus: false });
  twoFactorForm.classList.remove("is-shaking");
  requestAnimationFrame(() => {
    const first = canAuthenticator ? document.getElementById("otp0") : document.getElementById("recoveryCode");
    if (first) first.focus();
  });
}

function setTwoFactorMode(mode, { focus = true } = {}) {
  state.twoFactorMode = mode === "recovery" ? "recovery" : "otp";
  const recovery = state.twoFactorMode === "recovery";
  document.getElementById("otpBlock").hidden = recovery;
  document.getElementById("recoveryBlock").hidden = !recovery;
  twoFactorSubmit.textContent = recovery ? t("auth.verifyRecoveryCode") : t("auth.verifyAndSignIn");
  if (!focus) return;
  setTimeout(() => {
    const target = recovery ? document.getElementById("recoveryCode") : document.getElementById("otp0");
    // A mode switch focuses the new code field, but never steals focus from
    // someone already typing in one.
    const active = document.activeElement;
    const inCodeField = Boolean(active && (active.closest?.("#otpInputs") || active.id === "recoveryCode"));
    if (target && !inCodeField) target.focus();
  }, 40);
}

function otpCodeValue() {
  return $$("#otpInputs input").map((input) => input.value.replace(/\D/g, "")).join("");
}

function fillOtp(code) {
  const digits = String(code || "").replace(/\D/g, "").slice(0, 6).split("");
  $$("#otpInputs input").forEach((input, index) => { input.value = digits[index] || ""; });
  const target = $$("#otpInputs input").find((input) => !input.value) || document.getElementById("otp5");
  if (target) target.focus();
}

function hideTwoFactor() {
  twoFactorChallenge = null;
  twoFactorForm.hidden = true;
  loginForm.hidden = false;
  hidePasskeyPrompt();
  const first = document.getElementById("loginPassword");
  if (first) setTimeout(() => first.focus(), 40);
}

async function showPasskeyPrompt() {
  if (!twoFactorChallenge) return;
  if (!window.PublicKeyCredential || !navigator.credentials) {
    twoFactorError.textContent = t("auth.passkeysUnsupported");
    twoFactorError.hidden = false;
    return;
  }
  const profile = passkeyDeviceProfile();
  const passkey = (twoFactorChallenge.passkeys || [])[0];
  document.getElementById("passkeyPromptText").textContent = passkey
    ? t("auth.confirmPasskeyPrompt", { name: passkey.name })
    : t("auth.confirmDevice");
  const deviceName = document.getElementById("passkeyPromptDeviceName");
  const deviceHint = document.getElementById("passkeyPromptDeviceHint");
  if (deviceName) deviceName.textContent = passkey ? passkey.name : profile.label;
  if (deviceHint) deviceHint.textContent = t("auth.deviceHint", { biometric: profile.biometric });
  passkeyPromptStatus.innerHTML = `<span class="passkey-spinner" aria-hidden="true"></span>${esc(t("auth.waitingDevice"))}`;
  passkeyOverlay.hidden = false;
  twoFactorError.hidden = true;
  usePasskeyBtn.disabled = true;
  const controller = new AbortController();
  passkeyPromptAbort = controller;
  clearTimeout(passkeyTimer);
  passkeyTimer = setTimeout(() => {
    if (passkeyOverlay.hidden) return;
    passkeyPromptStatus.innerHTML = `<span class="passkey-spinner" aria-hidden="true"></span>${esc(t("auth.stillWaiting"))}`;
  }, 12000);
  try {
    const begin = await api("/api/session/2fa/webauthn/begin", {
      method: "POST", skipAuth: true,
      body: { challengeId: twoFactorChallenge.challengeId }
    });
    const publicKey = prepareAssertionOptions(begin.publicKey);
    const credential = await navigator.credentials.get({ publicKey, signal: controller.signal });
    const trust = document.getElementById("trustDevice").checked;
    const data = await api(`/api/session/2fa/webauthn/finish?flow=${encodeURIComponent(begin.flowId)}&trustDevice=${trust ? "1" : "0"}`, {
      method: "POST", skipAuth: true, body: serializeWebAuthnCredential(credential)
    });
    clearTimeout(passkeyTimer);
    passkeyTimer = null;
    passkeyPromptAbort = null;
    usePasskeyBtn.disabled = false;
    hidePasskeyPrompt(false);
    state.csrf = data.csrf;
    await finishAuthenticatedSignIn(data);
  } catch (error) {
    const cancelled = (error && error.name === "AbortError") || passkeyOverlay.hidden;
    hidePasskeyPrompt(false);
    usePasskeyBtn.disabled = false;
    if (cancelled) return;
    twoFactorError.textContent = webAuthnErrorMessage(error, "login").message;
    twoFactorError.hidden = false;
    twoFactorForm.classList.add("is-shaking");
    setTimeout(() => twoFactorForm.classList.remove("is-shaking"), 350);
    resetLoginButtons();
  }
}

function hidePasskeyPrompt(abortRequest = true) {
  clearTimeout(passkeyTimer);
  passkeyTimer = null;
  const controller = passkeyPromptAbort;
  passkeyPromptAbort = null;
  if (passkeyOverlay) passkeyOverlay.hidden = true;
  if (abortRequest && controller) {
    try { controller.abort(); } catch {}
  }
  usePasskeyBtn.disabled = false;
}

async function submitTwoFactor(event) {
  if (event) event.preventDefault();
  if (!twoFactorChallenge) return;
  const method = state.twoFactorMode === "recovery" ? "recovery" : "totp";
  const code = method === "recovery" ? document.getElementById("recoveryCode").value.trim() : otpCodeValue();
  if (method === "totp" && code.length !== 6) {
    twoFactorError.textContent = t("auth.enterAuthenticatorCode");
    twoFactorError.hidden = false;
    twoFactorForm.classList.add("is-shaking");
    setTimeout(() => twoFactorForm.classList.remove("is-shaking"), 350);
    return;
  }
  if (method === "recovery" && !code) {
    twoFactorError.textContent = t("auth.enterRecoveryCodeError");
    twoFactorError.hidden = false;
    return;
  }
  await verifyTwoFactor(method, code);
}

async function verifyTwoFactor(method, code) {
  if (!twoFactorChallenge) return;
  twoFactorError.hidden = true;
  twoFactorSubmit.disabled = true;
  twoFactorSubmit.textContent = t("auth.checkingCode");
  usePasskeyBtn.disabled = true;
  try {
    const data = await api("/api/session/2fa", {
      method: "POST",
      skipAuth: true,
      body: {
        challengeId: twoFactorChallenge.challengeId,
        method,
        code,
        trustDevice: document.getElementById("trustDevice").checked
      }
    });
    hidePasskeyPrompt();
    state.csrf = data.csrf;
    await finishAuthenticatedSignIn(data);
  } catch (error) {
    hidePasskeyPrompt();
    twoFactorError.textContent = error.message + (error.details && error.details.attemptsRemaining != null ? ` ${error.details.attemptsRemaining} attempt${error.details.attemptsRemaining === 1 ? "" : "s"} remaining.` : "");
    twoFactorError.hidden = false;
    twoFactorForm.classList.add("is-shaking");
    setTimeout(() => twoFactorForm.classList.remove("is-shaking"), 350);
    resetLoginButtons();
    if (state.twoFactorMode === "otp") fillOtp("");
  }
}

/* ---------- WebAuthn and first-time enrollment ---------- */
function decodeWebAuthnValue(value) {
  const text = String(value || "").replace(/-/g, "+").replace(/_/g, "/");
  const padded = text + "=".repeat((4 - text.length % 4) % 4);
  const binary = atob(padded);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes.buffer;
}

function encodeWebAuthnValue(buffer) {
  const bytes = new Uint8Array(buffer || new ArrayBuffer(0));
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function prepareCreationOptions(publicKey) {
  const options = JSON.parse(JSON.stringify(publicKey || {}));
  options.challenge = decodeWebAuthnValue(options.challenge);
  if (options.user && options.user.id) options.user.id = decodeWebAuthnValue(options.user.id);
  if (Array.isArray(options.excludeCredentials)) {
    options.excludeCredentials = options.excludeCredentials.map((entry) => ({ ...entry, id: decodeWebAuthnValue(entry.id) }));
  }
  return options;
}

function prepareAssertionOptions(publicKey) {
  const options = JSON.parse(JSON.stringify(publicKey || {}));
  options.challenge = decodeWebAuthnValue(options.challenge);
  if (Array.isArray(options.allowCredentials)) {
    options.allowCredentials = options.allowCredentials.map((entry) => ({ ...entry, id: decodeWebAuthnValue(entry.id) }));
  }
  return options;
}

function serializeWebAuthnCredential(credential) {
  if (credential && typeof credential.toJSON === "function") return credential.toJSON();
  const response = credential.response;
  const result = {
    id: credential.id,
    rawId: encodeWebAuthnValue(credential.rawId),
    type: credential.type,
    clientExtensionResults: typeof credential.getClientExtensionResults === "function" ? credential.getClientExtensionResults() : {},
    response: {}
  };
  if (response.attestationObject) {
    result.response = {
      clientDataJSON: encodeWebAuthnValue(response.clientDataJSON),
      attestationObject: encodeWebAuthnValue(response.attestationObject),
      transports: typeof response.getTransports === "function" ? response.getTransports() : []
    };
  } else {
    result.response = {
      clientDataJSON: encodeWebAuthnValue(response.clientDataJSON),
      authenticatorData: encodeWebAuthnValue(response.authenticatorData),
      signature: encodeWebAuthnValue(response.signature),
      userHandle: response.userHandle ? encodeWebAuthnValue(response.userHandle) : null
    };
  }
  return result;
}

function showEnrollmentChallenge(data, remember) {
  state.enrollmentChallenge = { ...data, remember };
  loginForm.hidden = true;
  twoFactorForm.hidden = true;
  const form = document.getElementById("enrollmentForm");
  form.hidden = false;
  document.getElementById("enrollmentError").hidden = true;
  document.getElementById("enrollmentTotpBlock").hidden = true;
  const user = data.user || {};
  document.getElementById("enrollmentAvatar").textContent = user.initials || initialsFrom(user.name || "");
  document.getElementById("enrollmentAvatar").style.setProperty("--av", user.color || "#34557a");
  document.getElementById("enrollmentName").textContent = user.name || t("auth.alt8MailAccount");
  document.getElementById("enrollmentEmail").textContent = user.email || loginEmail.value.trim();
  requestAnimationFrame(() => document.getElementById("enrollmentTotpBtn").focus());
}

function cancelEnrollment() {
  state.enrollmentChallenge = null;
  document.getElementById("enrollmentForm").hidden = true;
  document.getElementById("loginForm").hidden = false;
  document.getElementById("enrollmentTotpBlock").hidden = true;
  resetLoginButtons();
}

async function beginEnrollmentTOTP() {
  const challenge = state.enrollmentChallenge;
  if (!challenge) return;
  const button = document.getElementById("enrollmentTotpBtn");
  button.disabled = true;
  try {
    const data = await api("/api/enrollment/totp/begin", { method: "POST", skipAuth: true, body: { token: challenge.enrollmentToken } });
    document.getElementById("enrollmentTotpSecret").textContent = data.secret;
    document.getElementById("enrollmentTotpBlock").hidden = false;
    const qrHost = document.getElementById("enrollmentQrHost");
    if (qrHost) {
      qrHost.innerHTML = "";
      requestAnimationFrame(() => renderTotpQr(qrHost, data.otpauth, 320));
    }
    document.getElementById("enrollmentTotpCode").value = "";
    document.getElementById("enrollmentTotpCode").focus();
  } catch (error) {
    document.getElementById("enrollmentError").textContent = error.message;
    document.getElementById("enrollmentError").hidden = false;
  } finally { button.disabled = false; }
}

async function verifyEnrollmentTOTP() {
  const challenge = state.enrollmentChallenge;
  if (!challenge) return;
  const code = document.getElementById("enrollmentTotpCode").value.replace(/\D/g, "");
  if (code.length !== 6) {
    document.getElementById("enrollmentError").textContent = t("auth.enterAuthenticatorCode");
    document.getElementById("enrollmentError").hidden = false;
    return;
  }
  const button = document.getElementById("enrollmentTotpVerify");
  button.disabled = true;
  button.textContent = t("auth.verifying");
  try {
    const data = await api("/api/enrollment/totp/finish", { method: "POST", skipAuth: true, body: { token: challenge.enrollmentToken, code } });
    await completeEnrollment(data);
  } catch (error) {
    document.getElementById("enrollmentError").textContent = error.message;
    document.getElementById("enrollmentError").hidden = false;
  } finally {
    button.disabled = false;
    button.textContent = t("auth.verifyAndContinue");
  }
}

async function beginEnrollmentPasskey() {
  const challenge = state.enrollmentChallenge;
  if (!challenge) return;
  if (!window.PublicKeyCredential || !navigator.credentials) {
    document.getElementById("enrollmentError").textContent = t("auth.passkeysUnsupported");
    document.getElementById("enrollmentError").hidden = false;
    return;
  }
  const button = document.getElementById("enrollmentPasskeyBtn");
  button.disabled = true;
  try {
    const begin = await api("/api/enrollment/webauthn/begin", { method: "POST", skipAuth: true, body: { token: challenge.enrollmentToken } });
    const credential = await navigator.credentials.create({ publicKey: prepareCreationOptions(begin.publicKey) });
    if (!credential) throw new Error(t("auth.passkeyCancelled"));
    const data = await api(`/api/enrollment/webauthn/finish?flow=${encodeURIComponent(begin.flowId)}`, {
      method: "POST", skipAuth: true, body: serializeWebAuthnCredential(credential)
    });
    await completeEnrollment(data);
  } catch (error) {
    document.getElementById("enrollmentError").textContent = error.name === "NotAllowedError" ? t("auth.passkeyCancelled") : (error.message || t("auth.passkeyEnrollFailed"));
    document.getElementById("enrollmentError").hidden = false;
  } finally { button.disabled = false; }
}

async function completeEnrollment(data) {
  state.enrollmentChallenge = null;
  document.getElementById("enrollmentForm").hidden = true;
  state.csrf = data.csrf;
  await finishAuthenticatedSignIn(data);
  if (Array.isArray(data.recoveryCodes) && data.recoveryCodes.length) {
    showRecoveryCodes(data.recoveryCodes, t("auth.saveRecoveryCodes"));
  }
}

