async function openTeamTemplatePicker(session) {
  const team = composeTeamInbox(session);
  if (!team) {
    showToast(t("ui.derived-data.open-the-compose-window-from-a-team-inbox-to-use"), "warning");
    return;
  }
  const overlay = ensureTeamTemplateOverlay();
  document.getElementById("teamTemplateNote").textContent = `${team.name} · ${team.address}`;
  const list = document.getElementById("teamTemplateList");
  list.innerHTML = "<div class=\"settings-note\">" + t("ui.derived-data.loading-templates") + "</div>";
  overlay.hidden = false;
  try {
    const data = await api(`/api/team-templates?teamId=${encodeURIComponent(team.id)}`);
    const templates = data.templates || [];
    list.innerHTML = templates.length ? templates.map((template) => `<div class="shared-draft-row">
      <div class="shared-draft-copy"><strong>${esc(template.name)}</strong><span>${esc(template.category || t("ui.derived-data.uncategorized"))} · v${template.version}${template.aliasEmail ? ` · ${esc(template.aliasEmail)}` : ""}${template.variables?.length ? ` · ${template.variables.length} variable${template.variables.length === 1 ? "" : "s"}` : ""}</span></div>
      <button class="btn-secondary small" type="button" data-team-template-insert="${esc(template.id)}">${t("ui.derived-data.insert")}</button>
    </div>`).join("") : "<div class=\"empty-mini\">" + t("ui.derived-data.no-templates-yet-a-team-owner-can-create-them-th") + "</div>";
    $$("[data-team-template-insert]", list).forEach((button) => button.addEventListener("click", async () => {
      try {
        const detail = await api(`/api/team-templates/${encodeURIComponent(button.dataset.teamTemplateInsert)}`);
        const template = detail.template;
        const variables = {};
        for (const name of template.variables || []) {
          const value = await appPrompt({
            eyebrow: t("ui.derived-data.team-template"),
            title: template.name || t("ui.derived-data.insert-template"),
            message: t("ui.derived-data.fill-in-the-template-variable-for-this-message"),
            label: `{{${name}}}`,
            placeholder: t("ui.derived-data.value-for-variable", { name }),
            confirmLabel: t("ui.mandatory-first-login-onboarding.continue"),
            required: false
          });
          if (value == null) return;
          variables[name] = value;
        }
        const rendered = await api(`/api/team-templates/${encodeURIComponent(template.id)}/render`, { method: "POST", body: { variables } });
        applyTeamTemplate(session, rendered);
        overlay.hidden = true;
        showToast(t("ui.derived-data.template-inserted"));
      } catch (error) { showError(error); }
    }));
  } catch (error) {
    list.innerHTML = `<div class="settings-note">${esc(error.message || t("ui.derived-data.templates-could-not-be-loaded"))}</div>`;
  }
}

function insertMeetingLink(session) {
  if (!session?.el) return;
  const bytes = new Uint8Array(8);
  crypto.getRandomValues(bytes);
  const room = `a8m-${Array.from(bytes, (value) => value.toString(16).padStart(2, "0")).join("")}`;
  const url = `https://meet.jit.si/${room}`;
  if (session.htmlMode) {
    const editor = session.el.querySelector("[data-compose-editor]");
    if (editor) {
      editor.focus();
      document.execCommand("insertHTML", false, `<p><a href="${url}">${t("ui.derived-data.join-the-meeting")}</a><br>${url}</p>`);
      updateComposeEditor(session, editor);
    }
  } else {
    const textarea = session.el.querySelector('[data-compose-field="body"]');
    if (textarea) {
      const insert = `${session.body ? "\n\n" : ""}${t("ui.derived-data.join-the-meeting", { url })}`;
      const start = textarea.selectionStart ?? textarea.value.length;
      const end = textarea.selectionEnd ?? start;
      textarea.value = textarea.value.slice(0, start) + insert + textarea.value.slice(end);
      textarea.selectionStart = textarea.selectionEnd = start + insert.length;
      textarea.focus();
      session.body = textarea.value;
      session.bodyHtml = textToEditorHTML(session.body);
    }
  }
  session.dirty = true;
  updateComposeStatus(session);
  scheduleComposeSave(session);
  showToast(t("ui.derived-data.jitsi-meeting-link-inserted"));
}

async function insertPaymentLink(session) {
  if (!session?.el) return;
  const raw = await appPrompt({
    eyebrow: t("ui.mail-home-pulse-search-reports-sticky-no.compose"),
    title: t("ui.compose-manager.insert-payment-link"),
    message: t("ui.derived-data.only-payment-urls-approved-by-your-organization-"),
    label: t("ui.derived-data.payment-url"),
    value: "https://",
    placeholder: "https://pay.example.com/invoice",
    type: "url",
    confirmLabel: t("ui.derived-data.insert-link"),
    validate: (value) => /^https?:\/\//i.test(value) ? "" : t("ui.derived-data.enter-a-valid-https-payment-url")
  });
  if (!raw) return;
  try {
    const data = await api("/api/payment-links/validate", { method: "POST", body: { url: raw.trim() } });
    const url = data.url;
    if (session.htmlMode) {
      const editor = session.el.querySelector("[data-compose-editor]");
      if (editor) {
        editor.focus();
        document.execCommand("insertHTML", false, `<p>${t("ui.derived-data.pay-securely")} <a href="${esc(url)}">${esc(url)}</a></p>`);
        updateComposeEditor(session, editor);
      }
    } else {
      const textarea = session.el.querySelector('[data-compose-field="body"]');
      if (textarea) {
        const insert = `${session.body ? "\n\n" : ""}${t("ui.derived-data.pay-securely", { url })}`;
        textarea.value += insert;
        textarea.focus();
        session.body = textarea.value;
        session.bodyHtml = textToEditorHTML(session.body);
      }
    }
    session.dirty = true;
    updateComposeStatus(session);
    scheduleComposeSave(session);
    showToast(t("ui.derived-data.payment-link-inserted"));
  } catch (error) { showError(error); }
}

