function mailMergeRequest() {
  const session = state.mailMergeSession;
  if (!session) throw new Error(t("ui.derived-data.open-a-compose-window-first"));
  const subject = session.subject.trim();
  if (!subject) throw new Error(t("ui.derived-data.add-a-subject-before-creating-a-merge"));
  return {
    name: subject,
    fromEmail: session.fromEmail || "",
    subject,
    bodyText: session.body || "",
    bodyHtml: session.htmlMode ? session.bodyHtml || "" : "",
    throttleSeconds: Math.min(60, Math.max(1, Number(document.getElementById("mailMergeThrottle").value) || 5)),
    csv: document.getElementById("mailMergeCsv").value
  };
}

async function previewMailMerge() {
  const body = mailMergeRequest();
  const data = await api("/api/mail-merges/preview", { method: "POST", body });
  const host = document.getElementById("mailMergePreview");
  host.hidden = false;
  host.innerHTML = `<strong>${data.count} recipient${data.count === 1 ? "" : "s"} · ${data.throttleSeconds}s throttle</strong>` + (data.preview || []).slice(0, 3).map((item) => `<div class="shared-draft-row"><div class="shared-draft-copy"><strong>${esc(item.subject)}</strong><span>${esc(item.email)}</span></div></div>`).join("");
}

async function queueMailMerge() {
  const body = mailMergeRequest();
  const created = await api("/api/mail-merges", { method: "POST", body });
  const mergeId = created?.merge?.id;
  if (!mergeId) throw new Error(t("ui.derived-data.the-merge-could-not-be-created"));
  const result = await api(`/api/mail-merges/${encodeURIComponent(mergeId)}/queue`, { method: "POST" });
  document.getElementById("mailMergeOverlay").hidden = true;
  showToast(tn("ui.derived-data.mail-merge-queued", result.queued, { count: result.queued, suppressed: result.suppressed ? t("ui.derived-data.suppressed-count", { count: result.suppressed }) : "" }));
}

function applyTeamTemplate(session, template) {  if (!session?.el || !template) return;
  if (template.subject) {
    session.subject = template.subject;
    const subjectInput = session.el.querySelector('[data-compose-field="subject"]');
    if (subjectInput) subjectInput.value = template.subject;
    const title = session.el.querySelector("[data-compose-title]");
    if (title) title.textContent = template.subject;
  }
  if (template.aliasEmail && aliasForEmail(template.aliasEmail)?.canSend) {
    session.fromEmail = template.aliasEmail;
    session.accountId = composeAccountIdFor(template.aliasEmail);
    const fromSelect = session.el.querySelector('[data-compose-field="fromEmail"]');
    if (fromSelect) fromSelect.value = template.aliasEmail;
  }
  if (session.htmlMode && template.bodyHtml) {
    const editor = session.el.querySelector("[data-compose-editor]");
    if (editor) {
      editor.innerHTML = sanitizeEditorHTML(template.bodyHtml);
      normalizeEditorImageSources(editor);
      updateComposeEditor(session, editor);
    }
  } else {
    session.body = template.bodyText || "";
    session.bodyHtml = textToEditorHTML(session.body);
    const textarea = session.el.querySelector('[data-compose-field="body"]');
    if (textarea) textarea.value = session.body;
  }
  session.dirty = true;
  updateComposeOptions(session);
  updateComposeStatus(session);
  scheduleComposeSave(session);
}

