async function openSharedDraft(draftId) {
  if (clientSideEncryption()) {
    showToast(t("ui.compose.client-e2ee-draft-note"), "error");
    return;
  }
  const detail = await api(`/api/shared-drafts/${encodeURIComponent(draftId)}`);
  const lease = await api(`/api/shared-drafts/${encodeURIComponent(draftId)}/lease`, { method: "POST", body: { ttlSeconds: 300 } });
  const payload = detail.draft.payload || {};
  document.getElementById("teamDraftsOverlay").hidden = true;
  openCompose({
    toText: payload.toText || "", ccText: payload.ccText || "", bccText: payload.bccText || "",
    subject: payload.subject || "", bodyText: payload.bodyText || "", bodyHtml: payload.bodyHtml || "",
    htmlMode: payload.htmlMode !== false, fromEmail: payload.fromEmail || undefined,
    threadId: payload.threadId || detail.draft.threadId || null
  }, { sharedDraft: {
    id: detail.draft.id, teamId: detail.draft.teamId,
    version: Number(lease.version || detail.draft.version), writerToken: lease.writerToken,
    comments: detail.comments || []
  }, teamInboxId: detail.draft.teamId });
}

function flushSharedDraft(session, { silent = false } = {}) {
  if (!session?.sharedDraft || session.sharedDraft.paused) return Promise.resolve(null);
  clearTimeout(session.saveTimer);
  if (session.savingPromise) {
    session.pendingSave = true;
    return session.savingPromise;
  }
  session.dirty = true;
  session.saveError = null;
  updateComposeStatus(session);
  session.savingPromise = (async () => {
    try {
      const data = await api(`/api/shared-drafts/${encodeURIComponent(session.sharedDraft.id)}`, {
        method: "PATCH",
        body: {
          baseVersion: session.sharedDraft.version,
          writerToken: session.sharedDraft.writerToken,
          payload: composePayload(session)
        }
      });
      session.sharedDraft.version = Number(data.draft.version);
      session.lastSavedAt = data.draft.updatedAt;
      session.dirty = false;
      session.saveError = null;
      updateComposeStatus(session);
      return data.draft;
    } catch (error) {
      if (error.code === "DRAFT_CONFLICT") {
        session.sharedDraft.paused = true;
        session.saveError = t("ui.derived-data.another-agent-saved-a-newer-version-reload-team-");
        updateComposeStatus(session);
        const team = state.teamInboxes.find((item) => item.id === session.sharedDraft.teamId);
        showToast(t("ui.derived-data.another-agent-saved-a-newer-version-of-this-team"), t("mail.list.teamDrafts"), () => openTeamDrafts(team), { title: t("ui.derived-data.shared-draft-conflict") });
        return null;
      }
      if (error.code === "DRAFT_LEASED") {
        session.sharedDraft.paused = true;
        session.saveError = error.message || t("ui.derived-data.this-draft-is-being-edited-by-another-agent");
        updateComposeStatus(session);
        if (!silent) throw error;
        return null;
      }
      session.saveError = error.message || t("ui.derived-data.shared-draft-could-not-be-saved");
      session.dirty = true;
      updateComposeStatus(session);
      if (!silent) throw error;
      return null;
    } finally {
      session.savingPromise = null;
      if (session.pendingSave) {
        session.pendingSave = false;
        scheduleComposeSave(session, 350);
      }
    }
  })();
  return session.savingPromise;
}

function ensureSubscriptionsFolder() {
  if (!Array.isArray(state.folders)) state.folders = [];
  if (state.activeAccount && state.activeAccount.kind === "external") return;
  if (state.folders.some((folder) => folder.id === "subscriptions")) return;
  state.folders.push({
    id: "subscriptions", label: t("mail.reader.report.eyebrow"), icon: "i-mail", section: "favorites",
    order: 2, badgeMode: "unread", system: true, virtual: true,
    description: t("ui.derived-data.newsletters-and-mailing-lists-with-a-one-click-u")
  });
}

function applyUnsubscribeActions(list) {
  state.unsubscribeActions = new Map();
  for (const action of Array.isArray(list) ? list : []) {
    const sender = normalizeEmail(action?.senderEmail);
    if (sender) state.unsubscribeActions.set(sender, action);
  }
}

function unsubscribeActionFor(message) {
  return state.unsubscribeActions.get(normalizeEmail(message?.from?.email || message?.fromEmail)) || null;
}

function readingTimeForMessage(message) {
  const fromServer = Number(message?.readingMinutes);
  if (Number.isFinite(fromServer) && fromServer >= 0) return Math.round(fromServer);
  const text = message?.bodyText || stripHtml(message?.bodyHtml || "");
  const words = (String(text).trim().match(/\S+/g) || []).length;
  return words ? Math.max(1, Math.ceil(words / 220)) : 0;
}

function readingTimeLabel(minutes) {
  const value = Number(minutes) || 0;
  if (value <= 0) return "";
  return tn("mail.reader.minRead", value, { count: value });
}

function threadReadingMinutes(thread) {
  return (thread?.messages || []).reduce((sum, message) => sum + readingTimeForMessage(message), 0);
}

