function reactionRecentEmojis() {
  try {
    const list = JSON.parse(localStorage.getItem("a8m.reaction.recent") || "[]");
    return Array.isArray(list) ? list.filter((emoji) => typeof emoji === "string").slice(0, 12) : [];
  } catch { return []; }
}

function rememberReactionEmoji(emoji) {
  const list = reactionRecentEmojis().filter((item) => item !== emoji);
  list.unshift(emoji);
  try { localStorage.setItem("a8m.reaction.recent", JSON.stringify(list.slice(0, 12))); } catch {}
}

async function ensureReactionCatalog() {
  if (state.reactionCatalog) return state.reactionCatalog;
  const data = await api("/api/reaction-catalog");
  state.reactionCatalog = data && Array.isArray(data.categories) ? data : { categories: [] };
  return state.reactionCatalog;
}

function reactionSearchMatches(item, query) {
  if (!query) return true;
  const needle = query.toLowerCase();
  return [item.emoji, item.label, item.keywords, item.semantic].some((value) => String(value || "").toLowerCase().includes(needle));
}

function reactionCatalogMarkup(query = "") {
  const catalog = state.reactionCatalog;
  if (!catalog) return `<div class="reaction-catalog-loading"><span class="passkey-spinner" aria-hidden="true"></span>${t("ui.derived-data.loading-emoji")}</div>`;
  const recent = reactionRecentEmojis();
  const groups = [];
  if (!query && recent.length) {
    groups.push(`<div class="reaction-catalog-group"><span class="reaction-catalog-label">${t("ui.derived-data.recently-used")}</span><div class="reaction-catalog-grid">${recent.map((emoji) => `<button type="button" data-reaction-emoji="${esc(emoji)}" title="${esc(t("ui.derived-data.react-with-emoji", { emoji }))}">${esc(emoji)}</button>`).join("")}</div></div>`);
  }
  for (const category of catalog.categories || []) {
    const items = (category.emojis || []).filter((item) => reactionSearchMatches(item, query));
    if (!items.length) continue;
    groups.push(`<div class="reaction-catalog-group"><span class="reaction-catalog-label">${esc(category.name)}</span><div class="reaction-catalog-grid">${items.map((item) => `<button type="button" data-reaction-emoji="${esc(item.emoji)}" data-reaction-semantic="${esc(item.semantic || "")}" title="${esc(item.label || item.emoji)}">${esc(item.emoji)}</button>`).join("")}</div></div>`);
  }
  return groups.join("") || `<div class="reaction-catalog-empty">${esc(t("ui.reactions.no-emoji-match", { query }))}</div>`;
}

function rawMessageId(messageId) {
  const value = String(messageId || "");
  if (!value.startsWith("dlg:")) return value;
  const parts = value.split(":");
  return parts.slice(2).join(":");
}

function reactionCacheKey(ownerId, threadId) {
  return `${ownerId || ""}:${threadId || ""}`;
}

function reactionEntryForThread(thread) {
  const latest = thread?.latest || thread?.messages?.[0];
  if (!latest) return { key: "", entry: null };
  const key = reactionCacheKey(messageOwnerId(latest), thread.id);
  return { key, entry: state.reactionCache.get(key) || null };
}

function threadReactionList(thread) {
  return reactionEntryForThread(thread).entry?.list || [];
}

function reactionsForMessage(message) {
  if (!message) return [];
  const thread = { id: message.threadId || message.id, messages: [message], latest: message };
  return threadReactionList(thread).filter((reaction) => reaction.messageId === rawMessageId(message.id));
}

function reactionHintMarkup(message) {
  const reactions = reactionsForMessage(message);
  if (!reactions.length) return "";
  const counts = new Map();
  for (const reaction of reactions) counts.set(reaction.emoji, (counts.get(reaction.emoji) || 0) + 1);
  const summary = Array.from(counts.entries()).slice(0, 2).map(([emoji, count]) => `${emoji}${count > 1 ? count : ""}`).join(" ");
  return `<span class="meta-dot" aria-hidden="true"></span><span class="thread-reaction-hint" title="${esc(t("mail.reader.reactionsTitle"))}">${esc(summary)}</span>`;
}

function reactionAllowedForMessage(message) {
  if (!message || !tenantFeatureEnabled("reactions")) return false;
  if (message.draft || message.folder === "drafts" || message.folder === "sent" || message.folder === "spam") return false;
  if (message.unsubscribe && typeof message.unsubscribe === "object" && Object.keys(message.unsubscribe).length) return false;
  if (isSentLike(message)) return false;
  return true;
}

function threadReactionAllowed(thread) {
  if (!tenantFeatureEnabled("reactions")) return false;
  if (["sent", "drafts", "spam", "subscriptions"].includes(state.folder)) return false;
  if (!reactionAllowedForMessage(thread?.latest)) return false;
  return !(thread.messages || []).some((message) => message.unsubscribe && typeof message.unsubscribe === "object" && Object.keys(message.unsubscribe).length);
}

function reactionBarMarkup(message) {
  const reactions = reactionsForMessage(message);
  const canReact = reactionAllowedForMessage(message);
  const groups = new Map();
  for (const reaction of reactions) {
    const group = groups.get(reaction.emoji) || { emoji: reaction.emoji, count: 0, own: false, status: "" };
    group.count += 1;
    if (reaction.own) {
      group.own = true;
      group.status = reaction.status;
      group.reactionId = reaction.id;
    }
    groups.set(reaction.emoji, group);
  }
  const chips = Array.from(groups.values()).map((group) => {
    const own = group.own;
    const statusIcon = group.status === "sent" ? '<svg class="icon" aria-hidden="true"><use href="#i-send"/></svg>'
      : group.status === "private" ? '<svg class="icon" aria-hidden="true"><use href="#i-lock"/></svg>'
      : group.status === "pending" ? '<svg class="icon" aria-hidden="true"><use href="#i-clock"/></svg>'
      : "";
    const title = own
      ? group.status === "sent" ? t("ui.derived-data.your-reaction-was-sent-to-the-sender") : group.status === "pending" ? t("ui.derived-data.sending-your-reaction") : t("ui.derived-data.your-private-reaction")
      : t("ui.derived-data.reaction-in-this-conversation");
    return `<span class="reaction-chip${own ? " is-own" : ""}${group.status === "failed" ? " is-failed" : ""}" title="${esc(title)}">
      <span class="reaction-emoji">${group.emoji}</span>${group.count > 1 ? `<b>${group.count}</b>` : ""}${statusIcon}
      ${own ? `<button class="reaction-remove" type="button" data-reaction-remove="${esc(message.id)}" aria-label="${esc(t("ui.derived-data.remove-your-reaction"))}" title="${esc(t("ui.derived-data.remove-your-reaction"))}">×</button>` : ""}
    </span>`;
  }).join("");
  const own = reactions.find((reaction) => reaction.own);
  let statusLine = "";
  if (own?.status === "pending") {
    statusLine = `<span class="reaction-status is-pending"><svg class="icon" aria-hidden="true"><use href="#i-clock"/></svg>${t("ui.derived-data.sending-to-sender")} <button type="button" data-reaction-remove="${esc(message.id)}">${t("ui.derived-data.undo")}</button></span>`;
  } else if (own?.status === "failed") {
    statusLine = `<span class="reaction-status is-failed">${esc(own.error || t("ui.derived-data.could-not-send"))} · <button type="button" data-reaction-remove="${esc(message.id)}">${t("ui.derived-data.undo")}</button></span>`;
  }
  return `<div class="reaction-bar" data-reaction-bar="${esc(message.id)}">
    ${chips}
    ${canReact ? `<button class="reaction-add" type="button" data-reaction-open="${esc(message.id)}" aria-label="${esc(t("ui.derived-data.add-a-reaction"))}" title="${esc(t("ui.derived-data.add-a-reaction"))}"><span class="reaction-smile" aria-hidden="true">☺</span><span>${t("ui.derived-data.react")}</span></button>` : ""}
    ${statusLine}
  </div>`;
}

function threadReactionSummaryMarkup(thread) {
  const reactions = threadReactionList(thread);
  if (!reactions.length) return "";
  const counts = new Map();
  for (const reaction of reactions) counts.set(reaction.emoji, (counts.get(reaction.emoji) || 0) + 1);
  const summary = Array.from(counts.entries()).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([emoji, count]) => `${emoji}${count > 1 ? ` ${count}` : ""}`).join(" · ");
  return `<span class="thread-meta-chip reaction-summary" title="${esc(t("ui.derived-data.visible-reactions-in-this-conversation"))}">${esc(summary)}</span>`;
}

function ensureThreadReactions(thread, { force = false } = {}) {
  if (!thread || thread.latest?.draft) return;
  const latest = thread.latest || thread.messages?.[0];
  if (!latest) return;
  const ownerId = messageOwnerId(latest);
  const key = reactionCacheKey(ownerId, thread.id);
  const existing = state.reactionCache.get(key);
  if (existing?.loading) return;
  if (!force && existing && Date.now() - (existing.loadedAt || 0) < 15000) return;
  state.reactionCache.set(key, { ...(existing || {}), loading: true });
  api(`/api/reactions?threadId=${encodeURIComponent(thread.id)}&ownerId=${encodeURIComponent(ownerId)}`)
    .then((data) => {
      state.reactionCache.set(key, { list: Array.isArray(data.reactions) ? data.reactions : [], loadedAt: Date.now(), loading: false });
      const current = currentThread();
      if (current && current.id === thread.id) renderReader({ preserveScroll: true });
    })
    .catch(() => {
      state.reactionCache.delete(key);
    });
}

function reactionCachePut(message, reaction) {
  const ownerId = messageOwnerId(message);
  const threadId = message.threadId || message.id;
  const key = reactionCacheKey(ownerId, threadId);
  const entry = state.reactionCache.get(key) || { list: [], loadedAt: Date.now(), loading: false };
  const list = (entry.list || []).filter((item) => !(item.own && item.messageId === rawMessageId(message.id)));
  if (reaction) list.push(reaction);
  state.reactionCache.set(key, { list, loadedAt: Date.now(), loading: false });
}

function reactionCacheRemove(message) {
  const ownerId = messageOwnerId(message);
  const threadId = message.threadId || message.id;
  const key = reactionCacheKey(ownerId, threadId);
  const entry = state.reactionCache.get(key);
  if (!entry) return;
  state.reactionCache.set(key, {
    ...entry,
    list: (entry.list || []).filter((item) => !(item.own && item.messageId === rawMessageId(message.id))),
    loadedAt: Date.now()
  });
}

async function applyReaction(message, emoji, visibility, semantic = "") {
  const data = await api(`/api/messages/${encodeURIComponent(message.id)}/reaction`, {
    method: "POST",
    body: { emoji, visibility, semantic: semantic || REACTION_SEMANTIC[emoji] || "" }
  });
  if (data.reaction) reactionCachePut(message, data.reaction);
  renderReader({ preserveScroll: true });
  if (visibility === "sent") {
    showToast(t("ui.derived-data.reaction-will-be-sent-to-the-sender"), t("ui.status-bar-quota-pending-sends.undo"), () => removeReaction(message, { silent: false }));
    const thread = { id: message.threadId || message.id, messages: [message], latest: message };
    setTimeout(() => {
      const entry = reactionEntryForThread(thread).entry;
      if (entry) entry.loadedAt = 0;
      if (currentThread()?.id === thread.id) ensureThreadReactions(thread, { force: true });
    }, 11000);
  } else {
    showToast(t("ui.derived-data.private-reaction-added"));
  }
}

async function removeReaction(message, { silent = false } = {}) {
  const data = await api(`/api/messages/${encodeURIComponent(message.id)}/reaction`, { method: "DELETE", body: {} });
  reactionCacheRemove(message);
  renderReader({ preserveScroll: true });
  if (!silent) {
    if (data.wasSent) showToast(t("ui.derived-data.reaction-removed-the-sender-already-received-the"));
    else if (data.pending) showToast(t("ui.derived-data.reaction-cancelled-before-it-was-sent"));
    else showToast(t("ui.derived-data.reaction-removed"));
  }
}

function closeReactionMenu() {
  reactionMenu?.remove();
  reactionMenu = null;
  reactionMenuMessage = null;
  reactionMenuSendMode = "private";
}

function positionReactionMenu(menu, rect) {
  const width = Math.min(380, window.innerWidth - 24);
  const left = Math.min(window.innerWidth - width - 12, Math.max(12, rect.left || 12));
  let top = (rect.bottom || rect.top || 12) + 6;
  if (top + menu.offsetHeight > window.innerHeight - 12) top = Math.max(12, (rect.top || 12) - menu.offsetHeight - 6);
  menu.style.width = `${width}px`;
  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
}

function openReactionConfirm(message, emoji, semantic) {
  if (!message) return;
  document.getElementById("reactionConfirmOverlay")?.remove();
  const senderName = message.from?.name || message.from?.email || t("ui.reactions.the-sender");
  const reactorName = state.user?.name || state.user?.email || t("mail.reader.you");
  const organization = state.organizationName || t("ui.account-chrome.your-organization");
  const overlay = document.createElement("div");
  overlay.className = "overlay reaction-confirm-overlay";
  overlay.id = "reactionConfirmOverlay";
  overlay.innerHTML = `<div class="dialog reaction-confirm-dialog" role="dialog" aria-modal="true" aria-labelledby="reactionConfirmTitle">
    <div class="reaction-confirm-emoji" aria-hidden="true">${esc(emoji)}</div>
    <h2 id="reactionConfirmTitle">${t("ui.derived-data.send-this-reaction")}</h2>
    <p>${esc(t("ui.derived-data.reaction-confirm-copy", { sender: senderName, reactor: reactorName, organization }))}</p>
    <div class="reaction-confirm-preview"><span aria-hidden="true">${esc(emoji)}</span><div><b>${esc(t("ui.derived-data.reactor-from-org", { reactor: reactorName, organization }))}</b><small>${t("ui.derived-data.reacted-via-alt8mail")}</small></div></div>
    <div class="reaction-confirm-actions"><button class="btn-secondary" type="button" data-reaction-confirm-cancel>${t("tasks.action.cancel")}</button><button class="btn-secondary" type="button" data-reaction-confirm-private>${t("ui.derived-data.keep-private")}</button><button class="btn-primary" type="button" data-reaction-confirm-send>${t("ui.derived-data.send-reaction")}</button></div>
  </div>`;
  document.body.appendChild(overlay);
  const onKey = (event) => { if (event.key === "Escape") close(); };
  const close = () => {
    document.removeEventListener("keydown", onKey);
    overlay.remove();
  };
  overlay.addEventListener("click", (event) => { if (event.target === overlay) close(); });
  overlay.querySelector("[data-reaction-confirm-cancel]")?.addEventListener("click", close);
  overlay.querySelector("[data-reaction-confirm-private]")?.addEventListener("click", () => { close(); applyReaction(message, emoji, "private", semantic).catch(showError); });
  overlay.querySelector("[data-reaction-confirm-send]")?.addEventListener("click", (event) => {
    const button = event.currentTarget;
    button.disabled = true;
    close();
    applyReaction(message, emoji, "sent", semantic).catch(showError);
  });
  document.addEventListener("keydown", onKey);
  setTimeout(() => overlay.querySelector("[data-reaction-confirm-send]")?.focus(), 50);
}

function openReactionMenu(button, message) {
  closeReactionMenu();
  if (!reactionAllowedForMessage(message)) {
    showToast(t("ui.derived-data.reactions-are-unavailable-for-this-message"));
    return;
  }
  const readOnlyDelegate = Boolean(message.delegateOwnerId) && message.delegateCanSend !== true;
  const senderName = message.from?.name || message.from?.email || t("ui.derived-data.the-sender");
  const organisation = state.organizationName || t("ui.derived-data.your-organization");
  const menu = document.createElement("div");
  menu.className = "reaction-menu";
  menu.setAttribute("role", "dialog");
  menu.setAttribute("aria-label", t("ui.derived-data.react-to-this-message"));
  reactionMenuSendMode = "private";
  menu.innerHTML = `<div class="reaction-menu-head"><div><strong>${t("ui.derived-data.react")}</strong><small>${esc(senderName)}</small></div><button class="icon-btn" type="button" data-reaction-close aria-label="${esc(t("ui.derived-data.close-reactions"))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button></div>
    <div class="reaction-quick" role="group" aria-label="${esc(t("ui.derived-data.quick-reactions"))}">${REACTION_QUICK.map((emoji) => `<button type="button" data-reaction-emoji="${emoji}" data-reaction-semantic="${esc(REACTION_SEMANTIC[emoji] || "")}" title="${esc(t("ui.derived-data.react-with-emoji", { emoji }))}">${emoji}</button>`).join("")}</div>
    <div class="reaction-mode" role="group" aria-label="${esc(t("ui.derived-data.reaction-visibility"))}"><button type="button" class="is-active" data-reaction-mode="private">${t("ui.derived-data.private")}</button><button type="button" data-reaction-mode="sent" ${readOnlyDelegate ? "disabled" : ""}>${t("ui.derived-data.send-to-sender")}</button></div>
    <label class="reaction-search"><svg class="icon" aria-hidden="true"><use href="#i-search"/></svg><input type="search" data-reaction-search placeholder="${esc(t("ui.derived-data.search-emoji"))}" autocomplete="off" aria-label="${esc(t("ui.derived-data.search-emoji"))}"></label>
    <div class="reaction-catalog" data-reaction-catalog><div class="reaction-catalog-loading"><span class="passkey-spinner" aria-hidden="true"></span>${t("ui.derived-data.loading-emoji")}</div></div>
    <div class="reaction-suggestions" data-reaction-suggestions><span class="reaction-suggestions-loading">${t("ui.derived-data.finding-the-right-response")}</span></div>
    <p class="reaction-menu-note">${esc(t("ui.derived-data.private-reaction-note", { sender: senderName, organization: organisation }))}</p>`;
  document.body.appendChild(menu);
  reactionMenu = menu;
  reactionMenuMessage = message;
  positionReactionMenu(menu, button.getBoundingClientRect());
  menu.querySelector("[data-reaction-close]")?.focus();
  menu.querySelector("[data-reaction-search]")?.addEventListener("input", (event) => {
    const container = menu.querySelector("[data-reaction-catalog]");
    if (container) container.innerHTML = reactionCatalogMarkup(event.target.value.trim());
  });
  menu.querySelectorAll("[data-reaction-mode]").forEach((modeButton) => modeButton.addEventListener("click", () => {
    reactionMenuSendMode = modeButton.getAttribute("data-reaction-mode") === "sent" ? "sent" : "private";
    menu.querySelectorAll("[data-reaction-mode]").forEach((item) => item.classList.toggle("is-active", item === modeButton));
  }));
  ensureReactionCatalog().then(() => {
    if (reactionMenu !== menu) return;
    const container = menu.querySelector("[data-reaction-catalog]");
    if (container) container.innerHTML = reactionCatalogMarkup();
  }).catch(() => {
    const container = menu.querySelector("[data-reaction-catalog]");
    if (container) container.innerHTML = `<div class="reaction-catalog-empty">${t("ui.derived-data.emoji-catalog-unavailable")}</div>`;
  });
  api("/api/ai/reactions", { method: "POST", body: { messageId: message.id } })
    .then((data) => {
      if (reactionMenu !== menu) return;
      const container = menu.querySelector("[data-reaction-suggestions]");
      const suggestions = Array.isArray(data.suggestions) ? data.suggestions : [];
      if (!container) return;
      if (!suggestions.length) {
        container.innerHTML = `<span class="reaction-suggestions-empty">${t("ui.derived-data.quick-reactions-are-ready-above")}</span>`;
        return;
      }
      container.innerHTML = `<span class="reaction-suggestions-label">${data.ai ? t("ui.derived-data.suggested-by-ai") : t("ui.derived-data.semantic-suggestions")}</span><div class="reaction-suggestions-row">${suggestions.map((item) => `<button type="button" data-reaction-emoji="${esc(item.emoji)}" data-reaction-semantic="${esc(item.semantic || "")}" title="${esc(item.reason || item.label || "")}"><span>${item.emoji}</span><span>${esc(item.label || item.semantic || item.emoji)}</span></button>`).join("")}</div>`;
    })
    .catch(() => {
      const container = menu.querySelector("[data-reaction-suggestions]");
      if (container) container.innerHTML = `<span class="reaction-suggestions-empty">${t("ui.derived-data.quick-reactions-are-ready-above")}</span>`;
    });
}

function threadMetaKey(ownerId, threadId) {
  return `${ownerId || ""}:${threadId || ""}`;
}

function messageOwnerId(message) {
  return message?.delegateOwnerId || state.user?.id || "";
}

function threadMetaForMessage(message) {
  if (!message) return null;
  const threadId = message.threadId || message.id || "";
  return state.threadMeta.get(threadMetaKey(messageOwnerId(message), threadId)) || null;
}

function threadMetaForThread(thread) {
  return thread ? threadMetaForMessage(thread.latest || thread.messages?.[0]) : null;
}

function applyThreadMeta(list) {
  state.threadMeta = new Map();
  for (const item of Array.isArray(list) ? list : []) {
    if (!item?.ownerId || !item?.threadId) continue;
    state.threadMeta.set(threadMetaKey(item.ownerId, item.threadId), item);
  }
}

function threadIsClosed(message) {
  return threadMetaForMessage(message)?.closed === true;
}

function scopeMessages() {
  let messages;
  if (state.query) {
    state.searchParsed = state.searchParsed || parseQuery(state.query);
    state.searchMatched = state.searchResults || [];
    messages = state.searchMatched;
  } else {
    state.searchParsed = null;
    state.searchMatched = [];
    state.searchResults = [];
    state.searchErrors = [];
    state.searchLoading = false;
    const snoozeActive = (message) => Boolean(message.snoozedUntil) && Date.parse(message.snoozedUntil) > Date.now();
    if (state.folder === "starred") {
      messages = state.messages.filter((message) => message.starred && message.folder !== "spam" && message.folder !== "trash" && !message.ignored && !snoozeActive(message));
    } else if (state.folder === "snoozed") {
      messages = state.messages.filter((message) => !message.ignored && snoozeActive(message));
    } else if (state.folder === "subscriptions") {
      messages = state.messages.filter((message) => !message.ignored && !snoozeActive(message) && message.folder === "subscriptions" && !message.delegateOwnerId);
    } else {
      messages = state.messages.filter((message) => message.folder === state.folder && !message.ignored && !snoozeActive(message));
    }
  }
  if (!state.query) {
    const closedView = state.filter === "closed";
    messages = messages.filter((message) => threadIsClosed(message) === closedView);
  }
  if (state.filter === "unread") messages = messages.filter((message) => message.unread);
  if (state.filter === "starred") messages = messages.filter((message) => message.starred);
  if (state.filter === "flagged") messages = messages.filter((message) => message.flagged);
  if (state.filter === "attachments") messages = messages.filter((message) => (message.attachments || []).length);
  if (state.filter === "toMe") messages = messages.filter((message) => messageIsAddressedToMe(message));
  if (state.filter === "mentions") messages = messages.filter((message) => messageMentionsMe(message));
  if (state.filter === "calendar") messages = messages.filter((message) => messageHasCalendarInvite(message));
  if (state.pendingMailRemoval.size) {
    messages = messages.filter((message) => !state.pendingMailRemoval.has(message.id));
  }
  return messages;
}

function messageIsAddressedToMe(message) {
  const me = normalizeEmail(state.user?.email);
  if (!me) return false;
  return ["to", "cc", "bcc"].some((field) => (Array.isArray(message[field]) ? message[field] : []).some((person) => normalizeEmail(person?.email) === me));
}

function messageMentionsMe(message) {
  const me = normalizeEmail(state.user?.email);
  if (!me) return false;
  const local = me.split("@")[0];
  const haystack = `${message.bodyText || ""} ${message.bodyHtml || ""} ${message.snippet || ""}`.toLowerCase();
  return haystack.includes(`@${me}`) || (local.length > 2 && haystack.includes(`@${local}`));
}

function isCalendarAttachment(file) {
  const mime = String(file?.mime || "").toLowerCase();
  const name = String(file?.name || "").toLowerCase();
  return mime.startsWith("text/calendar") || mime === "application/ics" ||
    mime === "application/calendar" || name.endsWith(".ics");
}

function messageHasCalendarInvite(message) {
  if (message.event && typeof message.event === "object") return true;
  return (message.attachments || []).some(isCalendarAttachment);
}

function inboxViewIndividual() {
  return state.preferences?.inboxView === "individual";
}

function individualThreadFor(message) {
  const sender = message.from && message.from.email ? message.from : null;
  const recipient = Array.isArray(message.to) && message.to.length ? message.to[0] : message.to;
  const person = sender || (recipient && recipient.email ? recipient : null);
  return {
    id: message.id,
    messages: [message],
    latest: message,
    subject: message.subject || t("mail.list.noSubject"),
    participants: person ? [person] : [],
    unreadCount: message.unread ? 1 : 0,
    starred: Boolean(message.starred),
    flagged: Boolean(message.flagged),
    pinned: Boolean(message.pinned),
    hasAttachments: (message.attachments || []).length > 0,
    folderSet: [message.folder],
    date: message.date,
    count: 1,
    individual: true,
    repliedAt: message.repliedAt || "",
    forwardedAt: message.forwardedAt || "",
    replyCount: Number(message.replyCount) || 0,
    forwardCount: Number(message.forwardCount) || 0,
    snoozeReturned: Boolean(message.unread && message.snoozedUntil && (Date.parse(message.snoozedUntil) || 0) <= Date.now()),
    snoozeReturnAt: Boolean(message.unread && message.snoozedUntil && (Date.parse(message.snoozedUntil) || 0) <= Date.now()) ? message.snoozedUntil : ""
  };
}

function viewUnit(count) {
  return inboxViewIndividual()
    ? tn("mail.unit.message", count, { count })
    : tn("mail.unit.conversation", count, { count });
}

function pinnedFirstThreads(threads) {
  const pinned = [];
  const returnedSnoozes = [];
  const other = [];
  for (const thread of threads) {
    if (thread.pinned) pinned.push(thread);
    else if (thread.snoozeReturned) returnedSnoozes.push(thread);
    else other.push(thread);
  }
  pinned.sort((a, b) => (Date.parse(b.date) || 0) - (Date.parse(a.date) || 0));
  returnedSnoozes.sort((a, b) => (Date.parse(b.snoozeReturnAt) || 0) - (Date.parse(a.snoozeReturnAt) || 0));
  return pinned.concat(returnedSnoozes, other);
}

function computeView() {
  const scope = scopeMessages();
  let threads;
  if (inboxViewIndividual()) {
    threads = scope.slice().sort((a, b) => (Date.parse(b.date) || 0) - (Date.parse(a.date) || 0)).map(individualThreadFor);
    if (!state.sortDesc) threads = threads.slice().reverse();
  } else {
    threads = buildThreads(scope, state.messages);
    if (!state.sortDesc) threads = threads.slice().reverse();
  }
  // Pinned conversations are a reading priority, not a date order. Keep them
  // above the normal list in both newest-first and oldest-first modes.
  threads = pinnedFirstThreads(threads);
  state.viewScope = scope;
  state.viewThreads = threads;
  return threads;
}

function scopeSet() {
  return new Set(state.viewScope.map((message) => message.id));
}

function threadScopeMessages(thread) {
  const set = scopeSet();
  return thread.messages.filter((message) => set.has(message.id));
}

function representativeMessage(thread) {
  if (state.folder === "sent" && !state.query) {
    const sent = thread.messages.filter((message) => message.folder === "sent");
    if (sent.length) return sent[sent.length - 1];
  }
  if (state.folder === "drafts" && !state.query) {
    const drafts = thread.messages.filter((message) => message.folder === "drafts");
    if (drafts.length) return drafts[drafts.length - 1];
  }
  if (state.query) {
    const inScope = threadScopeMessages(thread);
    if (inScope.length) return inScope[inScope.length - 1];
  }
  return thread.latest;
}

function isSentLike(message) {
  return message.folder === "sent";
}

function threadRowDisplay(thread) {
  const rep = representativeMessage(thread);
  const outgoing = isSentLike(rep);
  const person = (outgoing || rep.draft)
    ? (Array.isArray(rep.to) && rep.to.length ? rep.to[0] : rep.from)
    : rep.from;
  let label;
  if (rep.draft) label = t("mail.list.draftTo", { recipient: recipientLabel(rep) });
  else if (outgoing) label = t("mail.list.toRecipient", { recipient: recipientLabel(rep) });
  else label = rep.from ? rep.from.name : t("mail.list.unknownSender");
  return { rep, person, label, outgoing };
}

function currentThread() {
  return threadById(state.selectedThreadId);
}

function currentMessage() {
  const thread = currentThread();
  if (!thread) return null;
  return thread.latest;
}

function actionMessageIds(threads) {
  const ids = new Set();
  const includeAllFolders = Boolean(state.query) || state.folder === "starred";
  for (const thread of threads) {
    for (const message of thread.messages) {
      if (includeAllFolders) {
        if (message.folder !== "drafts" || state.folder === "drafts" || state.query) ids.add(message.id);
      } else if (state.folder === "snoozed") {
        if (message.snoozedUntil && Date.parse(message.snoozedUntil) > Date.now()) ids.add(message.id);
      } else if (message.folder === state.folder) {
        ids.add(message.id);
      }
    }
  }
  return Array.from(ids);
}

function selectedThreads() {
  return state.viewThreads.filter((thread) => state.selectedIds.has(thread.id));
}

/* ============================================================
   account chrome
   ============================================================ */

function ensurePhase3SettingsUi() {
  const accountPanel = document.querySelector('[data-settings-panel="account"]');
  if (accountPanel && !document.getElementById("yearReviewBlock")) {
    const markup = `<div class="settings-block" id="yearReviewBlock">
      <div class="settings-block-head"><h3>${t("ui.account-chrome.year-in-review")}</h3><p>${t("ui.account-chrome.your-personal-email-story-volume-contacts-focus-")}</p></div>
      <div class="year-review-teaser"><span class="year-review-mark" aria-hidden="true">${t("ui.account-chrome.aa")}</span><div><strong>${t("ui.account-chrome.see-your-year-in-email")}</strong><span>${t("ui.account-chrome.a-private-personal-recap-built-from-your-mailbox")}</span></div><button class="btn-secondary" id="openYearReview" type="button">${t("ui.account-chrome.open-year-in-review")}</button></div>
    </div>`;
    const firstBlock = accountPanel.querySelector(".settings-block");
    if (firstBlock) firstBlock.insertAdjacentHTML("afterend", markup);
    else accountPanel.insertAdjacentHTML("beforeend", markup);
    document.getElementById("openYearReview")?.addEventListener("click", () => openYearReview());
  }
  const rulesPanel = document.querySelector('[data-settings-panel="rules"]');
  if (rulesPanel && tenantFeatureEnabled("reactions") && !document.getElementById("reactionRulesBlock")) {
    rulesPanel.insertAdjacentHTML("beforeend", `<div class="settings-block" id="reactionRulesBlock">
      <div class="settings-block-head"><h3>${t("ui.account-chrome.reaction-rules")}</h3><p>${t("ui.account-chrome.automatically-add-a-private-reaction-when-new-ma")}</p></div>
      <div class="settings-block-body">
        <div class="reaction-rule-list" id="reactionRuleList"><div class="settings-note">${t("ui.account-chrome.loading-reaction-rules")}</div></div>
        <div class="reaction-rules-foot"><span class="settings-note">${t("ui.account-chrome.private-reactions-are-visible-only-to-you")}</span><button class="btn-secondary small" id="addReactionRuleBtn" type="button">${t("ui.account-chrome.new-reaction-rule")}</button></div>
      </div>
    </div>`);
    document.getElementById("addReactionRuleBtn")?.addEventListener("click", () => openReactionRuleEditor());
    loadReactionRules().catch(() => {});
  }
  ensureYearReviewOverlay();
  ensureReactionRuleOverlay();
}

function ensureYearReviewOverlay() {
  if (document.getElementById("yearReviewOverlay")) return;
  document.body.insertAdjacentHTML("beforeend", `<div class="overlay year-review-overlay" id="yearReviewOverlay" hidden>
    <div class="dialog year-review-dialog" role="dialog" aria-modal="true" aria-labelledby="yearReviewTitle">
      <div class="dialog-head">
        <div class="dialog-title-wrap"><span class="dialog-icon"><svg class="icon" aria-hidden="true"><use href="#i-sparkles"/></svg></span>
          <div><h2 id="yearReviewTitle">${t("ui.account-chrome.your-year-in-email-title")}</h2><p>${t("ui.account-chrome.private-to-you-based-on-messages-in-this-mailbox")}</p></div></div>
        <button class="icon-btn" type="button" data-year-review-close aria-label="${esc(t("ui.account-chrome.close-year-in-review"))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button>
      </div>
      <div class="dialog-body" id="yearReviewBody"></div>
    </div>
  </div>`);
}

function ensureReactionRuleOverlay() {
  if (document.getElementById("reactionRuleOverlay")) return;
  const options = ["👍", "❤️", "😂", "🎉", "👀", "✅", "🙏", "🤔", "🚀", "💯"]
    .map((emoji) => `<option value="${emoji}">${emoji} ${esc(REACTION_LABELS[emoji] || REACTION_SEMANTIC[emoji] || "")}</option>`).join("");
  document.body.insertAdjacentHTML("beforeend", `<div class="overlay" id="reactionRuleOverlay" hidden>
    <div class="dialog reaction-rule-dialog" role="dialog" aria-modal="true" aria-labelledby="reactionRuleTitle">
      <div class="dialog-head">
        <div class="dialog-title-wrap"><span class="dialog-icon"><svg class="icon" aria-hidden="true"><use href="#i-sparkles"/></svg></span>
          <div><h2 id="reactionRuleTitle">${t("ui.account-chrome.new-reaction-rule")}</h2><p>${t("ui.account-chrome.react-privately-when-new-mail-matches")}</p></div></div>
        <button class="icon-btn" type="button" data-reaction-rule-close aria-label="${esc(t("ui.account-chrome.close-rule-editor"))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button>
      </div>
      <div class="dialog-body">
        <label class="form-field"><span>${t("ui.account-chrome.rule-name")}</span><input id="reactionRuleName" type="text" maxlength="120" placeholder="${esc(t("ui.account-chrome.thank-the-customer-success-team"))}"></label>
        <div class="reaction-rule-grid">
          <label class="form-field"><span>${t("ui.account-chrome.sender-contains")}</span><input id="reactionRuleSender" type="text" maxlength="160" placeholder="alerts@example.com"></label>
          <label class="form-field"><span>${t("ui.account-chrome.subject-contains")}</span><input id="reactionRuleSubject" type="text" maxlength="160" placeholder="${esc(t("ui.account-chrome.weekly-report"))}"></label>
        </div>
        <div class="reaction-rule-grid">
          <label class="form-field"><span>${t("ui.account-chrome.reaction")}</span><select id="reactionRuleEmoji">${options}</select></label>
          <label class="form-field reaction-rule-enabled"><span>${t("ui.account-chrome.apply-automatically")}</span><input id="reactionRuleEnabled" type="checkbox" checked></label>
        </div>
        <p class="settings-note">${t("ui.account-chrome.at-least-one-condition-is-required-rules-apply-t")}</p>
      </div>
      <div class="dialog-actions"><button class="btn-secondary" type="button" data-reaction-rule-close>${t("tasks.action.cancel")}</button><button class="btn-primary" id="reactionRuleSave" type="button">${t("ui.account-chrome.save-rule")}</button></div>
    </div>
  </div>`);
  document.getElementById("reactionRuleSave")?.addEventListener("click", saveReactionRule);
}

async function loadReactionRules() {
  const data = await api("/api/reaction-rules");
  state.reactionRules = Array.isArray(data.rules) ? data.rules : [];
  renderReactionRules();
}

function renderReactionRules() {
  const list = document.getElementById("reactionRuleList");
  if (!list) return;
  if (!state.reactionRules.length) {
    list.innerHTML = `<div class="reaction-rules-empty"><span class="reaction-rules-empty-icon"><svg class="icon" aria-hidden="true"><use href="#i-sparkles"/></svg></span><div><strong>${t("ui.account-chrome.no-reaction-rules-yet")}</strong><span>${t("ui.account-chrome.add-a-private-reaction-when-matching-mail-arrive")}</span></div></div>`;
    return;
  }
  list.innerHTML = state.reactionRules.map((rule) => {
    const conditions = [];
    if (rule.senderContains) conditions.push(`from ${rule.senderContains}`);
    if (rule.subjectContains) conditions.push(`subject ${rule.subjectContains}`);
    return `<div class="reaction-rule-row">
      <span class="reaction-rule-emoji" aria-hidden="true">${esc(rule.emoji)}</span>
      <div class="reaction-rule-copy"><strong>${esc(rule.name || t("ui.account-chrome.reaction-rule"))}</strong><span>${esc(conditions.join(" · ") || t("ui.account-chrome.any-new-message"))}</span></div>
      <button class="reaction-rule-toggle${rule.enabled ? " is-on" : ""}" type="button" role="switch" aria-checked="${rule.enabled ? "true" : "false"}" data-reaction-rule-toggle="${esc(rule.id)}">${rule.enabled ? t("ui.account-chrome.on") : t("ui.account-chrome.off")}</button>
      <button class="icon-btn" type="button" data-reaction-rule-edit="${esc(rule.id)}" aria-label="${esc(t("ui.account-chrome.edit-reaction-rule"))}" title="${esc(t("tasks.detail.edit"))}"><svg class="icon" aria-hidden="true"><use href="#i-pencil"/></svg></button>
      <button class="icon-btn" type="button" data-reaction-rule-delete="${esc(rule.id)}" aria-label="${esc(t("ui.account-chrome.delete-reaction-rule"))}" title="${esc(t("mail.list.quick.delete"))}"><svg class="icon" aria-hidden="true"><use href="#i-trash"/></svg></button>
    </div>`;
  }).join("");
}

function openReactionRuleEditor(ruleId = "") {
  ensureReactionRuleOverlay();
  const rule = state.reactionRules.find((item) => item.id === ruleId) || null;
  state.reactionRuleEditing = rule;
  document.getElementById("reactionRuleTitle").textContent = rule ? t("ui.account-chrome.edit-reaction-rule") : t("ui.account-chrome.new-reaction-rule");
  document.getElementById("reactionRuleName").value = rule?.name || "";
  document.getElementById("reactionRuleSender").value = rule?.senderContains || "";
  document.getElementById("reactionRuleSubject").value = rule?.subjectContains || "";
  document.getElementById("reactionRuleEmoji").value = rule?.emoji || "👍";
  document.getElementById("reactionRuleEnabled").checked = rule ? rule.enabled !== false : true;
  document.getElementById("reactionRuleOverlay").hidden = false;
  setTimeout(() => document.getElementById("reactionRuleName")?.focus(), 40);
}

function closeReactionRuleEditor() {
  const overlay = document.getElementById("reactionRuleOverlay");
  if (overlay) overlay.hidden = true;
  state.reactionRuleEditing = null;
}

async function saveReactionRule() {
  const name = document.getElementById("reactionRuleName")?.value.trim() || "";
  const senderContains = document.getElementById("reactionRuleSender")?.value.trim() || "";
  const subjectContains = document.getElementById("reactionRuleSubject")?.value.trim() || "";
  const emoji = document.getElementById("reactionRuleEmoji")?.value || "👍";
  const enabled = Boolean(document.getElementById("reactionRuleEnabled")?.checked);
  if (!senderContains && !subjectContains) {
    showToast(t("ui.account-chrome.add-a-sender-or-subject-condition"));
    return;
  }
  const button = document.getElementById("reactionRuleSave");
  if (button) button.disabled = true;
  try {
    const rule = state.reactionRuleEditing;
    if (rule) {
      await api(`/api/reaction-rules/${encodeURIComponent(rule.id)}`, { method: "PATCH", body: { name, senderContains, subjectContains, emoji, enabled } });
    } else {
      await api("/api/reaction-rules", { method: "POST", body: { name, senderContains, subjectContains, emoji, enabled } });
    }
    closeReactionRuleEditor();
    await loadReactionRules();
    showToast(t("ui.account-chrome.reaction-rule-saved"));
  } catch (error) {
    showError(error);
  } finally {
    if (button) button.disabled = false;
  }
}

async function toggleReactionRule(ruleId) {
  const rule = state.reactionRules.find((item) => item.id === ruleId);
  if (!rule) return;
  try {
    await api(`/api/reaction-rules/${encodeURIComponent(ruleId)}`, { method: "PATCH", body: { enabled: !rule.enabled } });
    await loadReactionRules();
  } catch (error) {
    showError(error);
  }
}

async function deleteReactionRule(ruleId) {
  const rule = state.reactionRules.find((item) => item.id === ruleId);
  if (!rule) return;
  const ok = await appConfirm({
    title: t("ui.account-chrome.delete-reaction-rule-title"),
    message: t("ui.account-chrome.reaction-rule-delete-confirm", { rule: rule.name || t("ui.account-chrome.reaction-rule") }),
    confirmLabel: t("ui.named-signature-library.delete-rule"),
    tone: "danger",
    icon: "i-trash"
  });
  if (!ok) return;
  try {
    await api(`/api/reaction-rules/${encodeURIComponent(ruleId)}`, { method: "DELETE", body: {} });
    await loadReactionRules();
    showToast(t("ui.account-chrome.reaction-rule-deleted"));
  } catch (error) {
    showError(error);
  }
}

async function openYearReview(year = null) {
  ensureYearReviewOverlay();
  const overlay = document.getElementById("yearReviewOverlay");
  const body = document.getElementById("yearReviewBody");
  overlay.hidden = false;
  body.innerHTML = `<div class="year-review-loading">${t("ui.account-chrome.building-your-year")}</div>`;
  const target = year || state.yearReviewYear || new Date().getFullYear();
  try {
    const data = await api(`/api/yearly-review?year=${encodeURIComponent(target)}`);
    state.yearReview = data;
    state.yearReviewYear = data.year;
    renderYearReview(data);
  } catch (error) {
    body.innerHTML = `<div class="year-review-loading">${esc(error.message || t("ui.account-chrome.could-not-build-your-year-in-review"))}</div>`;
  }
}

function yearNumber(value) {
  return new Intl.NumberFormat(currentLocale()).format(Number(value) || 0);
}

function yearReadingLabel(minutes) {
  const value = Number(minutes) || 0;
  if (value < 60) return `${value} min`;
  return `${(value / 60).toFixed(1)} hours`;
}

function renderYearReview(data) {
  const body = document.getElementById("yearReviewBody");
  if (!body) return;
  const totals = data.totals || {};
  const maxMonth = Math.max(1, ...(data.monthly || []).map((item) => Number(item.count) || 0));
  const years = Array.isArray(data.years) ? data.years : [data.year];
  const monthBars = (data.monthly || []).map((item) => {
    const count = Number(item.count) || 0;
    const percent = Math.max(count ? 4 : 1, Math.round((count / maxMonth) * 100));
    return `<div class="year-month${count ? "" : " is-empty"}" title="${esc(tn("ui.account-chrome.month-message-count", count, { month: item.label, count: yearNumber(count) }))}" aria-label="${esc(tn("ui.account-chrome.month-message-count", count, { month: item.label, count: yearNumber(count) }))}"><span class="year-month-bar" style="height:${percent}%"></span><small>${esc(String(item.label || "").slice(0, 3))}</small></div>`;
  }).join("");
  const contacts = (items, empty) => items?.length
    ? items.map((item, index) => `<div class="year-contact"><span class="year-contact-rank">${index + 1}</span><div><strong>${esc(item.name || item.email)}</strong><span>${esc(item.email)}</span></div><b>${yearNumber(item.count)}</b></div>`).join("")
    : `<div class="year-review-empty">${esc(empty)}</div>`;
  const reactionTop = (data.reactions?.top || []).map((item) => `<span class="year-reaction"><span>${esc(item.emoji)}</span><b>${yearNumber(item.count)}</b><small>${esc(item.semantic || "")}</small></span>`).join("");
  body.innerHTML = `<div class="year-review-top">
      <div><span class="year-review-kicker">${t("ui.account-chrome.alt8mail-personal-recap")}</span><h3>${esc(t("ui.account-chrome.year-in-your-inbox", { year: data.year }))}</h3><p>${esc((data.highlights || [])[0] || t("ui.account-chrome.your-year-in-email"))}</p></div>
      <label class="year-review-year"><span>${t("ui.account-chrome.year")}</span><select data-year-review-year>${years.map((value) => `<option value="${value}"${Number(value) === Number(data.year) ? " selected" : ""}>${value}</option>`).join("")}</select></label>
    </div>
    <div class="year-review-stats">
      <div class="year-stat"><span>${t("ui.account-chrome.messages")}</span><strong>${yearNumber(totals.messages)}</strong><small>${esc(tn("ui.account-chrome.conversations-count", totals.threads, { count: yearNumber(totals.threads) }))}</small></div>
      <div class="year-stat"><span>${t("ui.account-chrome.sent")}</span><strong>${yearNumber(totals.sent)}</strong><small>${esc(tn("ui.account-chrome.received-count", totals.received, { count: yearNumber(totals.received) }))}</small></div>
      <div class="year-stat"><span>${t("ui.account-chrome.reading-time")}</span><strong>${esc(yearReadingLabel(totals.readingMinutes))}</strong><small>${esc(tn("ui.account-chrome.about-newsletters", totals.newsletters, { count: yearNumber(totals.newsletters) }))}</small></div>
      <div class="year-stat"><span>${t("ui.account-chrome.reactions")}</span><strong>${yearNumber(data.reactions?.given || 0)}</strong><small>${esc(tn("ui.account-chrome.received-count", data.reactions?.received || 0, { count: yearNumber(data.reactions?.received || 0) }))}</small></div>
    </div>
    <div class="year-review-chart"><div class="year-review-section-head"><div><h3>${t("ui.account-chrome.when-your-mailbox-moved")}</h3><p>${t("ui.account-chrome.messages-by-month")}</p></div><span>${esc(t("ui.account-chrome.busiest-month", { month: data.busiestMonth?.label || "—", count: yearNumber(data.busiestMonth?.count || 0) }))}</span></div>
      <div class="year-months" role="img" aria-label="${esc(t("ui.account-chrome.monthly-message-volume"))}">${monthBars}</div>
      <div class="year-review-foot"><span>${esc(t("ui.account-chrome.busiest-day", { date: data.busiestDay?.date ? formatDateOnly(data.busiestDay.date) : "—" }))}</span><span>${esc(t("ui.account-chrome.busiest-hour", { hour: Number.isFinite(Number(data.busiestHour?.hour)) ? `${data.busiestHour.hour}:00` : "—" }))}</span><span>${esc(tn("ui.account-chrome.newsletter-count", totals.newsletters, { count: yearNumber(totals.newsletters) }))}</span>${data.unsubscribed ? `<span>${esc(tn("ui.account-chrome.unsubscribe-count", data.unsubscribed, { count: yearNumber(data.unsubscribed) }))}</span>` : ""}</div>
    </div>
    <div class="year-review-columns">
      <section><div class="year-review-section-head"><div><h3>${t("ui.account-chrome.people-who-shaped-your-year")}</h3><p>${t("ui.account-chrome.most-frequent-senders")}</p></div></div><div class="year-contacts">${contacts(data.topSenders, t("ui.account-chrome.no-incoming-mail-in-this-year"))}</div></section>
      <section><div class="year-review-section-head"><div><h3>${t("ui.account-chrome.your-loudest-recipients")}</h3><p>${t("ui.account-chrome.most-emailed-contacts")}</p></div></div><div class="year-contacts">${contacts(data.topRecipients, t("ui.account-chrome.no-sent-mail-in-this-year"))}</div></section>
    </div>
    <div class="year-review-columns">
      <section><div class="year-review-section-head"><div><h3>${t("ui.account-chrome.reactions-you-shared")}</h3><p>${t("ui.account-chrome.private-and-sent-reactions")}</p></div></div><div class="year-reactions">${reactionTop || "<div class=\"year-review-empty\">" + t("ui.mail-home-pulse-search-reports-sticky-no.no-reactions-yet") + "</div>"}</div></section>
      <section><div class="year-review-section-head"><div><h3>${t("ui.account-chrome.moments-to-remember")}</h3><p>${t("ui.account-chrome.highlights-from-your-mailbox")}</p></div></div><ul class="year-highlights">${(data.highlights || []).slice(1).map((item) => `<li>${esc(item)}</li>`).join("") || "<li>" + t("ui.account-chrome.your-year-is-still-taking-shape") + "</li>"}</ul></section>
    </div>`;
  body.querySelector("[data-year-review-year]")?.addEventListener("change", (event) => openYearReview(event.target.value));
}

function renderAccountChrome() {
  const user = state.user;
  if (!user) return;
  const topAvatar = document.getElementById("accountBtn");
  if (topAvatar) {
    topAvatar.textContent = user.initials || initialsFrom(user.name);
    topAvatar.title = t("ui.account-chrome.account-settings-for", { name: user.name });
  }
  const accountEmail = document.getElementById("accountEmail");
  if (accountEmail) accountEmail.textContent = user.email;
  const copyAccount = document.querySelector("[data-copy-email]");
  if (copyAccount && copyAccount.closest(".account-profile")) copyAccount.setAttribute("data-copy-email", user.email);
  const profile = $(".account-profile");
  if (profile) {
    const av = $(".avatar", profile);
    if (av) { av.textContent = user.initials || initialsFrom(user.name); av.style.setProperty("--av", user.color || "#34557a"); }
    const h3 = $(".account-profile-copy h3", profile);
    const p = $(".account-profile-copy p", profile);
    if (h3) h3.textContent = user.name;
    if (p) p.textContent = t("ui.account-chrome.profile-line", { role: user.role || t("ui.account-chrome.team-member"), company: user.company || "Alt8Mail" });
  }
}

function externalAccountsEnabled() {
  const policy = state.tenantPolicy || {};
  return Boolean(policy.mail && policy.mail.externalAccounts === true);
}

function mailOAuthProviderAvailable(provider) {
  if (!state.mailOAuth || typeof state.mailOAuth[provider] !== "boolean") return true;
  return state.mailOAuth[provider];
}

function activeAccountStorageKey() {
  return `a8m.activeAccount.${normalizeEmail(state.user?.email || "anonymous")}`;
}

function unifiedAccountsAvailable() {
  return externalAccountsEnabled() && (state.accounts || []).some((account) => !account.isNative);
}

function unifiedAccountView() {
  return {
    id: "all",
    kind: "unified",
    email: "",
    displayName: t("ui.account-chrome.all-accounts"),
    color: "#34557a",
    status: "active",
    isNative: false,
    isUnified: true,
    accountCount: (state.accounts || []).length
  };
}

function nativeMailAccount() {
  return (state.accounts || []).find((account) => account.isNative) || null;
}

function defaultComposeAccountId() {
  return state.activeAccountId === "all" ? (nativeMailAccount()?.id || "") : state.activeAccountId;
}

// A message is delivered through the account that owns its From address. A
// native identity never rides on whichever connected mailbox happens to be
// open, otherwise the server rejects the send with BAD_FROM.
function composeAccountIdFor(email) {
  const alias = aliasForEmail(email);
  if (alias?.accountId) return alias.accountId;
  return nativeMailAccount()?.id || defaultComposeAccountId();
}

function accountMenuAccounts() {
  return (state.accounts || []).filter((account) => account.isNative || externalAccountsEnabled());
}

function accountMenuEntries() {
  const entries = [];
  if (unifiedAccountsAvailable()) entries.push(unifiedAccountView());
  entries.push(...accountMenuAccounts());
  return entries;
}

function accountMenuTitle(account) {
  if (!account) return "Alt8Mail";
  if (account.isUnified) return t("accounts.all");
  if (account.isNative) return account.displayName || state.user?.name || "Alt8Mail";
  return account.displayName || mailProviderMeta(account.provider).name || account.email || t("ui.account-chrome.mail-account");
}

function accountMenuSubtitle(account) {
  if (!account) return state.user?.email || "";
  if (account.isUnified) {
    const count = account.accountCount || accountMenuAccounts().length;
    return tn("ui.account-chrome.mailbox-unified-inbox", count, { count });
  }
  return account.email || "";
}

function accountUnreadCount(account) {
  if (!account) return 0;
  if (account.isUnified) {
    return accountMenuAccounts().reduce((total, item) => total + Math.max(0, Number(item.unreadCount) || 0), 0);
  }
  if (account.kind === "delegated") {
    const native = (state.accounts || []).find((item) => item.isNative);
    return Math.max(0, Number(native?.unreadCount) || 0);
  }
  const live = (state.accounts || []).find((item) => item.id === account.id);
  return Math.max(0, Number((live || account).unreadCount) || 0);
}

function accountUnreadTotal() {
  return accountMenuAccounts().reduce((total, account) => total + Math.max(0, Number(account.unreadCount) || 0), 0);
}

function hydrateAccountUnreadCounts() {
  const known = state.knownAccountUnread instanceof Map ? state.knownAccountUnread : new Map();
  for (const account of state.accounts || []) {
    account.unreadCount = Math.max(0, Number(account.unreadCount) || 0);
    if (!known.has(account.id) || state.activeAccountId === "all" || state.activeAccountId === account.id) {
      known.set(account.id, account.unreadCount);
    }
  }
  state.knownAccountUnread = known;
  if (state.activeAccount) {
    if (state.activeAccount.isUnified) {
      state.activeAccount.unreadCount = accountUnreadTotal();
    } else {
      const live = (state.accounts || []).find((item) => item.id === state.activeAccount.id);
      if (live) state.activeAccount.unreadCount = live.unreadCount;
    }
  }
}

function accountMenuProviderLabel(account) {
  if (!account || account.isNative) return "Alt8Mail";
  if (account.isUnified) return t("ui.account-chrome.unified");
  const meta = mailProviderMeta(account.provider);
  return meta.id === "imap" ? "IMAP" : meta.name.replace(/\s+Mail$/, "");
}

function accountMenuBadge(account) {
  if (account?.isUnified) return { label: t("ui.account-chrome.combined"), className: "is-unified" };
  if (account?.isNative) return { label: t("mail.folders.primary"), className: "is-primary" };
  if (account?.status === "reauth") return { label: t("accounts.reconnect"), className: "is-warning" };
  if (account?.status === "error") return { label: t("ui.account-chrome.sync-error-retrying"), className: "is-error" };
  return { label: accountMenuProviderLabel(account), className: "" };
}

function accountMenuLogo(account, extraClass = "") {
  const extra = extraClass ? ` ${extraClass}` : "";
  if (account?.isUnified) {
    return `<span class="account-logo-unified${extra}"><svg class="icon" aria-hidden="true"><use href="#i-inbox"/></svg></span>`;
  }
  if (!account || account.isNative || !account.provider || account.provider === "alt8mail") {
    const name = account?.displayName || state.user?.name || "Alt8Mail";
    const color = account?.color || state.user?.color || "#34557a";
    const initials = initialsFrom(name || account?.email || "A8") || "A8";
    return `<span class="avatar avatar-md account-avatar${extra}" style="--av:${esc(color)}" aria-hidden="true"><span class="avatar-initials">${esc(initials)}</span></span>`;
  }
  return `<img class="account-provider-img${extra}" src="${mailProviderLogo(account.provider)}" alt="" loading="lazy">`;
}

function renderAccountMenuList() {
  const list = document.getElementById("accountMenuList");
  if (!list) return;
  const query = state.accountMenuQuery.trim().toLowerCase();
  const matches = accountMenuEntries().filter((account) => {
    if (!query) return true;
    return `${accountMenuTitle(account)} ${accountMenuSubtitle(account)} ${accountMenuProviderLabel(account)}`
      .toLowerCase().includes(query);
  });
  if (!matches.length) {
    list.innerHTML = `<div class="account-pop-empty"><svg class="icon" aria-hidden="true"><use href="#i-search"/></svg><strong>${t("ui.account-chrome.no-mailbox-found")}</strong><span>${t("ui.account-chrome.try-a-name-or-email-address")}</span></div>`;
    return;
  }
  list.innerHTML = matches.map((account) => {
    const selected = account.id === state.activeAccountId;
    const badge = accountMenuBadge(account);
    const unread = accountUnreadCount(account);
    const unreadLabel = unread > 99 ? "99+" : String(unread);
    return `<button class="account-row${selected ? " is-selected" : ""}" type="button" role="option" aria-selected="${selected}" data-account-menu-id="${esc(account.id)}">
      <span class="account-row-logo">${accountMenuLogo(account)}</span>
      <span class="account-row-copy"><strong>${esc(accountMenuTitle(account))}</strong><span>${esc(accountMenuSubtitle(account))}</span></span>
      <span class="account-row-badge ${badge.className}">${esc(badge.label)}</span>
      <span class="account-row-unread${unread > 0 ? " has-unread" : ""}" title="${esc(tn("ui.account-chrome.unread-message-count", unread, { count: unread }))}"><svg class="icon" aria-hidden="true"><use href="#i-mail"/></svg><span>${unreadLabel}</span></span>
      <span class="account-row-check" aria-hidden="true"><svg class="icon"><use href="#i-check"/></svg></span>
    </button>`;
  }).join("");
}

function renderAccountSwitcher() {
  const menu = document.getElementById("accountMenu");
  const trigger = document.getElementById("accountMenuBtn");
  const triggerLogo = document.getElementById("accountTriggerLogo");
  const triggerName = document.getElementById("accountTriggerName");
  const triggerEmail = document.getElementById("accountTriggerEmail");
  const triggerStatus = document.getElementById("accountTriggerStatus");
  const triggerUnread = document.getElementById("accountTriggerUnread");
  const triggerUnreadCount = document.getElementById("accountTriggerUnreadCount");
  const count = document.getElementById("accountMenuCount");
  const searchWrap = document.getElementById("accountSearchWrap");
  const addPop = document.getElementById("accountPopAddBtn");
  const note = document.getElementById("accountMenuNote");
  if (!menu || !trigger) return;
  const accounts = accountMenuAccounts();
  const active = state.delegatedMode
    ? {
      id: "delegated",
      kind: "delegated",
      provider: "alt8mail",
      email: state.user?.email || state.delegatedSession?.mailbox?.email || "",
      displayName: state.user?.name || t("ui.delegated-mailbox-windows.delegated-mailbox"),
      color: state.user?.color,
      status: "active",
      isNative: true,
      isUnified: false
    }
    : state.activeAccount
      || (state.activeAccountId === "all" && unifiedAccountsAvailable() ? unifiedAccountView() : null)
      || accounts.find((account) => account.id === state.activeAccountId)
      || accounts[0]
      || (state.user ? {
        id: "",
        kind: "native",
        provider: "alt8mail",
        email: state.user.email,
        displayName: state.user.name || "Alt8Mail",
        color: state.user.color,
        status: "active",
        isNative: true,
        isUnified: false
      } : null);
  const visible = Boolean(active) || accounts.length > 0;
  menu.hidden = !visible;
  if (state.delegatedMode) closeAccountMenu(false);
  const canAdd = !state.delegatedMode && externalAccountsEnabled();
  if (addPop) addPop.hidden = !canAdd;
  if (note) note.hidden = externalAccountsEnabled();
  if (count) count.textContent = String(accounts.length);
  if (searchWrap) searchWrap.hidden = accountMenuEntries().length < 5;
  if (!visible || !active) return;
  triggerLogo.innerHTML = accountMenuLogo(active);
  triggerName.textContent = accountMenuTitle(active);
  triggerEmail.textContent = accountMenuSubtitle(active);
  const title = state.delegatedMode ? active.displayName : accountMenuTitle(active);
  const subtitle = accountMenuSubtitle(active);
  const unreadTotal = accountUnreadTotal();
  const unreadText = unreadTotal > 99 ? "99+" : String(unreadTotal);
  if (triggerUnread) {
    triggerUnread.hidden = unreadTotal <= 0;
    triggerUnread.title = tn("ui.account-chrome.unread-across-mailboxes", unreadTotal, { count: unreadTotal });
    if (triggerUnreadCount) triggerUnreadCount.textContent = unreadText;
  }
  trigger.setAttribute("aria-label", state.delegatedMode
    ? t("ui.account-chrome.delegated-mailbox-aria", { title, subtitle: subtitle ? `, ${subtitle}` : "", unread: unreadTotal ? t("ui.account-chrome.unread-suffix", { count: unreadTotal }) : "" })
    : t("ui.account-chrome.mailbox-aria", { title, subtitle: subtitle ? `, ${subtitle}` : "", unread: unreadTotal ? t("ui.account-chrome.unread-across-mailboxes-suffix", { count: unreadTotal }) : "" }));
  trigger.title = `${title}${subtitle ? ` · ${subtitle}` : ""}${unreadTotal ? ` · ${unreadTotal} unread` : ""}`;
  trigger.classList.toggle("is-unified", Boolean(active.isUnified));
  trigger.classList.toggle("is-static", state.delegatedMode);
  if (state.delegatedMode) {
    trigger.setAttribute("aria-disabled", "true");
    trigger.setAttribute("tabindex", "-1");
    trigger.removeAttribute("aria-haspopup");
    trigger.setAttribute("aria-expanded", "false");
  } else {
    trigger.removeAttribute("aria-disabled");
    trigger.removeAttribute("tabindex");
    trigger.setAttribute("aria-haspopup", "dialog");
  }
  const warning = active.status === "reauth" || active.status === "error";
  if (triggerStatus) {
    triggerStatus.hidden = !warning;
    triggerStatus.title = warning ? (active.lastError || connectedAccountStatus(active).label) : "";
    triggerStatus.innerHTML = warning ? `<svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg>` : "";
  }
  renderAccountMenuList();
}

function toggleAccountMenu(force) {
  const menu = document.getElementById("accountMenu");
  const pop = document.getElementById("accountPopover");
  const trigger = document.getElementById("accountMenuBtn");
  if (!menu || !pop || menu.hidden || state.delegatedMode) return;
  const open = typeof force === "boolean" ? force : pop.hidden;
  if (open) {
    clearAccountPings();
    state.accountMenuQuery = "";
    const search = document.getElementById("accountSearch");
    if (search) search.value = "";
    renderAccountSwitcher();
  }
  state.accountMenuOpen = open;
  pop.hidden = !open;
  menu.classList.toggle("is-open", open);
  trigger?.setAttribute("aria-expanded", open ? "true" : "false");
  if (open) {
    setTimeout(() => {
      const searchWrap = document.getElementById("accountSearchWrap");
      const search = document.getElementById("accountSearch");
      if (searchWrap && !searchWrap.hidden && search) {
        search.focus();
        return;
      }
      const row = pop.querySelector(".account-row.is-selected") || pop.querySelector(".account-row");
      row?.focus();
    }, 30);
  }
}

function closeAccountMenu(restoreFocus = false) {
  const menu = document.getElementById("accountMenu");
  const pop = document.getElementById("accountPopover");
  const trigger = document.getElementById("accountMenuBtn");
  if (!menu || !pop) return;
  const wasOpen = !pop.hidden || state.accountMenuOpen;
  state.accountMenuOpen = false;
  state.accountMenuQuery = "";
  pop.hidden = true;
  menu.classList.remove("is-open");
  trigger?.setAttribute("aria-expanded", "false");
  if (restoreFocus && wasOpen) trigger?.focus();
}

function accountMenuVisible() {
  const menu = document.getElementById("accountMenu");
  if (!menu || menu.hidden) return false;
  const rect = menu.getBoundingClientRect();
  return rect.width > 0 && rect.height > 0 && rect.right > 0 && rect.left < window.innerWidth;
}

function resetAccountPingTimer() {
  clearTimeout(state.accountPingTimer);
  state.accountPingTimer = setTimeout(() => dismissAccountPing(), 12000);
}

function renderAccountPing() {
  const node = document.getElementById("accountPing");
  const menu = document.getElementById("accountMenu");
  if (!node) return;
  const ping = state.accountPingCurrent;
  if (!ping) {
    node.hidden = true;
    menu?.classList.remove("has-news");
    return;
  }
  const account = (state.accounts || []).find((item) => item.id === ping.accountId) || ping.account;
  const latest = ping.latest || account?.latestUnread || {};
  const unread = accountUnreadCount(account);
  const unreadText = unread > 99 ? "99+" : String(unread);
  const sender = latest.fromName || latest.fromEmail || t("ui.account-chrome.new-sender");
  const senderLine = latest.fromEmail && latest.fromEmail !== sender ? `${sender} · ${latest.fromEmail}` : sender;
  const logo = document.getElementById("accountPingLogo");
  const accountLabel = document.getElementById("accountPingAccount");
  const subject = document.getElementById("accountPingSubject");
  const meta = document.getElementById("accountPingMeta");
  const count = document.getElementById("accountPingCount");
  const open = document.getElementById("accountPingOpen");
  if (logo) logo.innerHTML = accountMenuLogo(account);
  if (accountLabel) accountLabel.textContent = account?.isNative ? "Alt8Mail" : accountMenuTitle(account);
  if (subject) subject.textContent = latest.subject || t("ui.account-chrome.new-message");
  if (meta) meta.textContent = senderLine;
  if (count) count.innerHTML = `<svg class="icon" aria-hidden="true"><use href="#i-mail"/></svg><span>${unreadText}</span>`;
  if (open) {
    open.setAttribute("data-account-ping-id", ping.accountId);
    open.setAttribute("aria-label", t("ui.account-chrome.open-account-new-mail-from", { account: accountMenuTitle(account), sender }));
  }
  node.hidden = false;
  menu?.classList.add("has-news");
}

function showNextAccountPing() {
  if (state.accountPingCurrent) return;
  const next = state.accountPingQueue.shift();
  if (!next) return;
  state.accountPingCurrent = next;
  renderAccountPing();
  resetAccountPingTimer();
}

function maybeQueueAccountPing(account, increase, latest) {
  if (!account || state.delegatedMode) return;
  if (state.activeAccountId === "all" || state.activeAccountId === account.id) return;
  const payload = {
    accountId: account.id,
    account: { ...account },
    increase,
    latest: latest || account.latestUnread || null
  };
  const detail = payload.latest || {};
  const sender = detail.fromName || detail.fromEmail || t("ui.notifications.a-new-sender");
  const subject = detail.subject || t("ui.alt8mail-intelligence-pre-send-spell-che.new-message");
  if (document.visibilityState !== "visible") {
    showBrowserNotification(t("ui.account-chrome.new-mail-in-account", { account: accountMenuTitle(account) }), `${sender}: ${subject}`, `a8m-account-${account.id}`);
    return;
  }
  if (state.task !== "mail" || !accountMenuVisible()) {
    showToast(t("ui.account-chrome.new-mail-in-account-subject", { account: accountMenuTitle(account), subject }), t("tasks.status.open"), () => {
      setTask("mail");
      switchMailAccount(account.id);
    });
    return;
  }
  const existing = state.accountPingCurrent?.accountId === account.id
    ? state.accountPingCurrent
    : state.accountPingQueue.find((item) => item.accountId === account.id);
  if (existing) {
    Object.assign(existing, payload);
    if (existing === state.accountPingCurrent) {
      renderAccountPing();
      resetAccountPingTimer();
    }
    return;
  }
  state.accountPingQueue.push(payload);
  showNextAccountPing();
}

function dismissAccountPing(showNext = true) {
  clearTimeout(state.accountPingTimer);
  state.accountPingTimer = null;
  state.accountPingCurrent = null;
  renderAccountPing();
  if (showNext) {
    setTimeout(() => {
      if (!state.accountPingCurrent) showNextAccountPing();
    }, 300);
  }
}

function clearAccountPings() {
  clearTimeout(state.accountPingTimer);
  state.accountPingTimer = null;
  state.accountPingCurrent = null;
  state.accountPingQueue = [];
  renderAccountPing();
}

function removeAccountPings(accountId) {
  state.accountPingQueue = state.accountPingQueue.filter((item) => item.accountId !== accountId);
  if (state.accountPingCurrent?.accountId === accountId) dismissAccountPing();
}

function connectedAccountStatus(account) {
  switch (account.status) {
    case "reauth": return { label: t("ui.account-chrome.reconnect-required"), className: "is-reauth" };
    case "error": return { label: t("ui.account-chrome.sync-error-retrying"), className: "is-error" };
    case "disabled": return { label: t("ui.account-chrome.disabled"), className: "" };
    default: return { label: t("shell.connected"), className: "" };
  }
}

function renderConnectedAccounts() {
  const holder = document.getElementById("connectedAccountsList");
  if (!holder) return;
  const add = document.getElementById("connectedAccountAdd");
  if (add) add.hidden = !externalAccountsEnabled() || state.delegatedMode;
  const connected = (state.accounts || []).filter((account) => !account.isNative);
  if (!connected.length) {
    holder.innerHTML = externalAccountsEnabled()
      ? `<div class="connected-account-empty"><strong>${t("ui.account-chrome.no-connected-accounts-yet")}</strong><span>${t("ui.account-chrome.add-gmail-microsoft-365-or-another-imap-mailbox-")}</span></div>`
      : `<div class="connected-account-empty"><strong>${t("shell.connectedAccountsDisabled")}</strong><span>${t("ui.account-chrome.an-administrator-can-enable-them-under-mail-acce")}</span></div>`;
    return;
  }
  holder.innerHTML = connected.map((account) => {
    const status = connectedAccountStatus(account);
    return `<div class="connected-account-row" data-connected-account="${esc(account.id)}">
      <span class="connected-account-logo"><img src="${mailProviderLogo(account.provider)}" alt="" loading="lazy"></span>
      <div class="connected-account-copy">
        <strong>${esc(account.displayName || account.email)}</strong>
        <span>${esc(account.email)} · <span class="connected-account-status ${status.className}">${esc(status.label)}</span></span>
        ${account.lastError ? `<span title="${esc(account.lastError)}">${esc(account.lastError)}</span>` : ""}
      </div>
      <div class="connected-account-actions">
        <button class="btn-secondary" type="button" data-account-sync="${esc(account.id)}">${esc(t("accounts.sync"))}</button>
        <button class="btn-secondary" type="button" data-account-servers="${esc(account.id)}">${esc(t("accounts.servers"))}</button>
        <button class="btn-secondary" type="button" data-account-reconnect="${esc(account.id)}">${esc(account.oauth ? t("accounts.reconnect") : account.status === "reauth" ? t("accounts.reconnect") : t("accounts.password"))}</button>
        <button class="btn-secondary" type="button" data-account-remove="${esc(account.id)}">${esc(t("accounts.remove"))}</button>
      </div>
    </div>`;
  }).join("");
}

function applyConnectedAccountSettingsScope() {
  const connected = Boolean(state.activeAccount && state.activeAccount.kind === "external");
  document.querySelectorAll('[data-settings-tab="rules"], [data-settings-tab="autoreply"]').forEach((tab) => {
    tab.hidden = connected;
  });
  if (connected && ["rules", "autoreply"].includes(state.settingsTab)) {
    state.settingsTab = "account";
  }
}

function switchMailAccount(accountId, { reload = true } = {}) {
  const account = accountId === "all"
    ? (unifiedAccountsAvailable() ? unifiedAccountView() : null)
    : (state.accounts || []).find((item) => item.id === accountId);
  if (!account || accountId === state.activeAccountId) return;
  state.activeAccountId = accountId;
  state.activeAccount = account;
  try { localStorage.setItem(activeAccountStorageKey(), accountId); } catch {}
  state.folder = "inbox";
  state.filter = "all";
  state.query = "";
  state.selectedThreadId = null;
  state.selectedMessageId = null;
  state.messages = [];
  state.mailPages = {};
  state.knownInboxIds = null;
  state.knownSnoozeDueIds = new Set();
  state.homeTab = "home";
  state.pulseData = null;
  state.pulseYear = null;
  renderAccountSwitcher();
  renderAccountChrome();
  if (reload) {
    loadBootstrap({ quiet: true }).catch((error) => showToast(error.message || t("ui.account-chrome.could-not-switch-mail-account")));
  }
}

function startMailOAuth(provider, accountId = "") {
  return new Promise((resolve, reject) => {
    const query = accountId ? `?account=${encodeURIComponent(accountId)}` : "";
    const popup = window.open(
      `/api/mail/oauth/${encodeURIComponent(provider)}/start${query}`,
      "a8m-mail-oauth",
      "width=520,height=720,menubar=no,toolbar=no"
    );
    if (!popup) {
      reject(new Error(t("ui.account-chrome.allow-pop-ups-for-alt8mail-to-finish-the-sign-in")));
      return;
    }
    let settled = false;
    let poll = null;
    let timeout = null;
    const cleanup = () => {
      window.removeEventListener("message", onMessage);
      if (poll) clearInterval(poll);
      if (timeout) clearTimeout(timeout);
    };
    const finish = (fn, value) => {
      if (settled) return;
      settled = true;
      cleanup();
      fn(value);
    };
    const onMessage = (event) => {
      if (event.origin !== window.location.origin) return;
      const data = event.data || {};
      if (data.type !== "a8m-mail-oauth") return;
      try { window.focus(); } catch {}
      if (data.status === "connected") finish(resolve, data.accountId || "");
      else finish(reject, new Error(data.message || t("ui.account-chrome.the-mail-account-was-not-connected")));
    };
    window.addEventListener("message", onMessage);
    poll = setInterval(() => {
      if (popup.closed) finish(reject, new Error(t("ui.account-chrome.sign-in-was-cancelled")));
    }, 800);
    timeout = setTimeout(() => finish(reject, new Error(t("ui.account-chrome.sign-in-timed-out-try-again"))), 5 * 60 * 1000);
  });
}

async function connectMailAccountWithOAuth(provider, accountId = "") {
  const accountID = await startMailOAuth(provider, accountId);
  try { window.focus(); } catch {}
  showToast(accountId ? t("ui.account-chrome.mail-account-reconnected") : t("ui.account-chrome.mail-account-connected"));
  await loadBootstrap({ quiet: true });
  renderConnectedAccounts();
  renderAccountChrome();
  if (!accountId && accountID) {
    const connected = state.accounts.find((account) => account.id === accountID);
    if (connected) switchMailAccount(connected.id, { reload: false });
    await loadBootstrap({ quiet: true });
    setTimeout(() => loadBootstrap({ quiet: true }).catch(() => {}), 4000);
  }
}

