const NON_LATIN_SCRIPT = /[Ѐ-ӿ֐-׿؀-ۿݐ-ݿऀ-ॿ฀-๿Ⴀ-ჿᄀ-ᇿ⺀-鿿가-힯]/u;
const ENGLISH_COMMON_WORDS = new Set([
  "the", "and", "to", "of", "in", "for", "is", "on", "that", "with", "as", "was", "at", "by",
  "be", "this", "from", "or", "an", "are", "it", "not", "you", "we", "your", "have", "has",
  "will", "can", "all", "but", "our", "if", "they", "their", "there", "been", "more", "when",
  "who", "which", "would", "should", "could", "about", "after", "before", "please", "thank",
  "thanks", "hi", "hello", "dear", "regards", "message", "email", "mail"
]);

function selectionLooksNonEnglish(text) {
  const value = String(text || "").trim();
  if (value.length < 2) return false;
  if (NON_LATIN_SCRIPT.test(value)) return true;
  const words = value.toLowerCase().match(/[a-zà-öø-ÿ'’-]+/g) || [];
  if (words.length < 2) return false;
  const englishHits = words.filter((word) => ENGLISH_COMMON_WORDS.has(word)).length;
  const ratio = englishHits / words.length;
  const accented = /[à-öø-ÿ]/i.test(value);
  return ratio < 0.12 || (accented && ratio < 0.3);
}

function selectionTargetLanguage() {
  return (state.preferences && state.preferences.language) || "en-US";
}

function selectionTargetLanguageLabel(language = selectionTargetLanguage()) {
  try {
    return new Intl.DisplayNames([language], { type: "language" }).of(String(language).split("-")[0]) || language;
  } catch {
    return language;
  }
}

function positionSelectionTranslation(anchor) {
  const card = document.getElementById("selectionTranslation");
  if (!card || card.hidden || !anchor) return;
  const width = card.offsetWidth || 360;
  const height = card.offsetHeight || 140;
  const left = Math.min(Math.max(12, anchor.left || 12), Math.max(12, window.innerWidth - width - 12));
  let top = (anchor.bottom || 120) + 10;
  if (top + height > window.innerHeight - 12) {
    top = Math.max(12, (anchor.top || 120) - height - 10);
  }
  card.style.left = `${left}px`;
  card.style.top = `${top}px`;
}

function closeSelectionTranslation() {
  const card = document.getElementById("selectionTranslation");
  if (card) card.hidden = true;
  const body = document.getElementById("selectionTranslationBody");
  if (body) body.innerHTML = "";
  state.selectionTranslation = null;
}

async function openSelectionTranslation(text, anchor = null) {
  const value = String(text || "").trim();
  if (!value) return;
  const card = document.getElementById("selectionTranslation");
  const body = document.getElementById("selectionTranslationBody");
  const languageLabel = document.getElementById("selectionTranslationLanguage");
  const title = document.getElementById("selectionTranslationTitle");
  if (!card || !body) return;
  closeSelectionTranslation();
  state.selectionTranslation = { text: value, anchor: anchor || null };
  if (languageLabel) languageLabel.textContent = t("ui.thread-selection-actions.translating-to", { language: selectionTargetLanguageLabel() });
  if (title) title.textContent = value.length > 120 ? `${value.slice(0, 117)}…` : value;
  body.innerHTML = `<div class="selection-translation-loading"><span class="passkey-spinner" aria-hidden="true"></span><span>${t("ui.thread-selection-actions.translating-this-selection")}</span></div>`;
  card.hidden = false;
  card.style.visibility = "hidden";
  card.style.left = "12px";
  card.style.top = "12px";
  requestAnimationFrame(() => {
    positionSelectionTranslation(anchor);
    card.style.visibility = "visible";
  });
  try {
    const data = await api("/api/ai/translate", {
      method: "POST",
      body: { text: value, language: selectionTargetLanguage() }
    });
    if (!state.selectionTranslation || state.selectionTranslation.text !== value) return;
    const translation = String(data.translation || "").trim();
    if (languageLabel) languageLabel.textContent = t("ui.thread-selection-actions.translated-to", { language: selectionTargetLanguageLabel(data.language || selectionTargetLanguage()) });
    body.innerHTML = `<p class="selection-translation-text">${esc(translation || t("ui.thread-selection-actions.no-translation-was-returned"))}</p>`;
    requestAnimationFrame(() => positionSelectionTranslation(anchor));
  } catch (error) {
    if (!state.selectionTranslation || state.selectionTranslation.text !== value) return;
    body.innerHTML = `<p class="selection-translation-error">${esc(error.message || t("ui.thread-selection-actions.could-not-translate-this-selection"))}</p>`;
    requestAnimationFrame(() => positionSelectionTranslation(anchor));
  }
}

function messageMenuSelectionMarkup(thread) {
  const preview = state.messageMenuSelectionText.replace(/\s+/g, " ").trim();
  const canTranslate = Boolean(state.ai?.enabled) && selectionLooksNonEnglish(preview);
  return `<div class="message-menu-head"><svg class="icon" aria-hidden="true"><use href="#i-copy"/></svg><div><strong>${t("ui.thread-selection-actions.selected-text")}</strong><span>${esc(preview.slice(0, 110))}${preview.length > 110 ? "…" : ""}</span></div></div>
    ${canTranslate ? `<button type="button" data-message-command="translateSelection" class="message-translate-text"><svg class="icon" aria-hidden="true"><use href="#i-translate"/></svg><span>${t("ui.thread-selection-actions.translate")}</span><kbd>${esc(selectionTargetLanguageLabel())}</kbd></button>${messageMenuDivider()}` : ""}
    <button type="button" data-message-command="copyText" class="message-copy-text"><svg class="icon" aria-hidden="true"><use href="#i-copy"/></svg><span>${t("ui.thread-selection-actions.copy-text")}</span><kbd>${t("ui.thread-selection-actions.ctrl-c")}</kbd></button>
    ${messageMenuDivider()}
    ${menuButton("reply", "i-reply", t("mail.reader.reply"))}
    ${menuButton("replyAll", "i-reply-all", t("shell.replyAll"), replyAllAvailable(thread) ? "" : "disabled")}
    ${menuButton("forward", "i-forward", t("mail.reader.forward"))}
    ${menuButton("delete", "i-trash", t("mail.list.quick.delete"), "", "is-danger")}`;
}

async function copyTextToClipboard(text) {
  const value = String(text || "");
  if (!value) return false;
  try {
    await navigator.clipboard.writeText(value);
    return true;
  } catch {}
  try {
    const area = document.createElement("textarea");
    area.value = value;
    area.setAttribute("readonly", "");
    area.style.position = "fixed";
    area.style.opacity = "0";
    document.body.appendChild(area);
    area.select();
    const copied = document.execCommand("copy");
    area.remove();
    return copied;
  } catch {
    return false;
  }
}

function messageMenuMarkup() {
  const thread = messageMenuThread();
  if (!thread) return "<div class=\"message-menu-empty\">" + t("ui.pwa.that-conversation-is-no-longer-available") + "</div>";
  if (state.messageMenuView === "selection" && state.messageMenuSelectionText) return messageMenuSelectionMarkup(thread);
  const message = state.messageMenuMessageId ? (thread.messages.find((item) => item.id === state.messageMenuMessageId) || thread.latest) : thread.latest;
  const view = state.messageMenuView;
  if (view === "move" || view === "copy") return messageMenuFolderList(view);
  if (view === "category") return messageMenuCategoryList(thread);
  if (view === "snooze") return messageMenuSnoozeList();
  if (view === "advanced") return messageMenuAdvancedList();
  const unread = thread.unreadCount > 0;
  const pinned = Boolean(thread.pinned);
  const flagged = Boolean(thread.flagged);
  const isSpam = thread.messages.some((item) => item.folder === "spam");
  const sender = message?.from?.name && message.from.name !== message.from.email ? message.from.name : (message?.from?.email || t("mail.list.unknownSender"));
  const activity = thread.repliedAt || thread.forwardedAt
    ? `${thread.repliedAt ? t("mail.list.replied") : ""}${thread.repliedAt && thread.forwardedAt ? " · " : ""}${thread.forwardedAt ? t("mail.list.forwarded") : ""}`
    : t("ui.thread-selection-actions.no-reply-or-forward-yet");
  return `<div class="message-menu-head"><svg class="icon" aria-hidden="true"><use href="#i-mail"/></svg><div><strong>${esc(threadSubject(thread))}</strong><span>${esc(sender)} · ${esc(activity)}</span></div></div>
    ${menuButton("reply", "i-reply", t("mail.reader.reply"))}
    ${menuButton("replyAll", "i-reply-all", t("shell.replyAll"), replyAllAvailable(thread) ? "" : "disabled")}
    ${menuButton("forward", "i-forward", t("mail.reader.forward"))}
    ${messageMenuDivider()}
    ${menuButton("delete", "i-trash", t("mail.list.quick.delete"), "", "is-danger")}
    ${menuButton("archive", "i-archive", t("mail.list.quick.archive"))}
    <div class="message-menu-sub"><button type="button" data-message-submenu="move"><svg class="icon" aria-hidden="true"><use href="#i-folder"/></svg><span>${t("mail.folders.move")}</span><span class="menu-chevron">›</span></button></div>
    <div class="message-menu-sub"><button type="button" data-message-submenu="copy"><svg class="icon" aria-hidden="true"><use href="#i-files"/></svg><span>${t("ui.thread-selection-actions.copy")}</span><span class="menu-chevron">›</span></button></div>
    ${messageMenuDivider()}
    ${menuButton("markUnread", "i-envelope-open", t("shell.markAsUnread"), unread ? "disabled" : "")}
    ${menuButton(pinned ? "unpin" : "pin", "i-pin", pinned ? t("ui.mail-home-pulse-search-reports-sticky-no.unpin") : t("mail.list.quick.pin"))}
    <div class="message-menu-sub"><button type="button" data-message-submenu="category"><svg class="icon" aria-hidden="true"><use href="#i-tag"/></svg><span>${t("ui.thread-selection-actions.categorize")}</span><span class="menu-chevron">›</span></button></div>
    ${menuButton(flagged ? "unflag" : "flag", "i-flag", flagged ? t("ui.thread-selection-actions.clear-follow-up-flag") : t("mail.list.quick.flag"))}
    ${menuButton("createTask", "i-task", t("ui.thread-selection-actions.add-to-task"))}
    <div class="message-menu-sub"><button type="button" data-message-submenu="snooze"><svg class="icon" aria-hidden="true"><use href="#i-clock"/></svg><span>${t("mail.list.quick.snooze")}</span><span class="menu-chevron">›</span></button></div>
    ${menuButton("rules", "i-sliders", t("ui.settings.rules"))}
    ${menuButton("quickActions", "i-grid", t("ui.thread-selection-actions.set-quick-actions"))}
    ${messageMenuDivider()}
    ${isSpam ? menuButton("notSpam", "i-inbox", t("ui.thread-selection-actions.report-not-junk-action")) : menuButton("reportJunk", "i-alert", t("ui.thread-selection-actions.report-junk"))}
    ${menuButton("reportPhishing", "i-shield-alert", t("ui.thread-selection-actions.report-phishing"))}
    ${menuButton("reportConcern", "i-info", t("ui.thread-selection-actions.report-a-concern"))}
    ${menuButton("block", "i-shield-alert", t("ui.thread-selection-actions.block"), "", "is-danger")}
    ${message?.ignored || thread.messages.some((item) => item.ignored) ? menuButton("unignore", "i-lock", t("ui.thread-selection-actions.unignore-conversation")) : menuButton("ignore", "i-lock", t("ui.alt8mail-intelligence-pre-send-spell-che.ignore"))}
    ${messageMenuDivider()}
    ${menuButton("download", "i-download", t("ui.alt8mail-office.download"))}
    ${menuButton("findRelated", "i-search", t("ui.thread-selection-actions.find-related"))}
    ${menuButton("view", "i-envelope-open", t("ui.thread-selection-actions.view"))}
    <div class="message-menu-sub"><button type="button" data-message-submenu="advanced"><svg class="icon" aria-hidden="true"><use href="#i-sliders"/></svg><span>${t("ui.thread-selection-actions.advanced-actions")}</span><span class="menu-chevron">›</span></button></div>`;
}

function positionMessageMenu(point) {
  if (!messageMenu) return;
  const width = 286;
  const left = Math.min(window.innerWidth - width - 10, Math.max(10, point?.clientX || 120));
  messageMenu.style.left = `${left}px`;
  messageMenu.style.top = "10px";
  messageMenu.hidden = false;
  const height = messageMenu.offsetHeight;
  const top = Math.min(window.innerHeight - height - 10, Math.max(10, point?.clientY || 120));
  messageMenu.style.top = `${top}px`;
}

function openMessageMenu(threadId, messageId, point) {
  const thread = threadById(threadId);
  if (!thread) return;
  closeMenus();
  state.messageMenuThreadId = thread.id;
  state.messageMenuMessageId = messageId || thread.latest?.id || "";
  state.messageMenuView = "";
  state.messageMenuSelectionText = "";
  state.messageMenuPoint = point || { clientX: 120, clientY: 120 };
  messageMenu.innerHTML = messageMenuMarkup();
  positionMessageMenu(state.messageMenuPoint);
  messageMenu.querySelector("button")?.focus();
}

function closeMessageMenu() {
  if (messageMenu) messageMenu.hidden = true;
  state.messageMenuThreadId = "";
  state.messageMenuMessageId = "";
  state.messageMenuView = "";
  state.messageMenuSelectionText = "";
}

function rerenderMessageMenu() {
  if (!state.messageMenuThreadId) return;
  messageMenu.innerHTML = messageMenuMarkup();
  positionMessageMenu(state.messageMenuPoint);
}

function messageMenuTargetMessage(thread) {
  if (!thread) return null;
  return thread.messages.find((message) => message.id === state.messageMenuMessageId) || thread.latest;
}

async function downloadMessageSource(message) {
  if (!message) return;
  try {
    const data = await api(`/api/messages/${encodeURIComponent(message.id)}/source`);
    const subject = String(message.subject || "message").replace(/[\\/:*?"<>|]+/g, "-").slice(0, 80);
    const blob = new Blob([data.source || data.headers || ""], { type: "message/rfc822" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `${subject || "message"}.eml`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
    showToast(t("mail.details.downloaded"));
  } catch (error) {
    showError(error);
  }
}

function printThread(thread, target = null) {
  if (!thread) return;
  const message = target || thread.latest;
  const sender = message.from?.name && message.from.name !== message.from.email ? `${message.from.name} <${message.from.email}>` : (message.from?.email || t("mail.reader.unknownSender"));
  const recipients = (message.to || []).map((person) => person.name ? `${person.name} <${person.email}>` : person.email).join(", ");
  const body = message.bodyText || htmlToText(message.bodyHtml || "");
  const win = window.open("", "_blank", "width=860,height=900");
  if (!win) { showToast(t("ui.thread-selection-actions.allow-pop-ups-to-print-this-message")); return; }
  try { win.opener = null; } catch {}
  win.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(threadSubject(thread))}</title><style>body{font-family:"Segoe UI",Arial,sans-serif;color:#172230;margin:40px;line-height:1.55}h1{font-size:20px;margin:0 0 18px}dl{display:grid;grid-template-columns:80px 1fr;gap:4px 10px;margin:0 0 24px}dt{color:#64748b}dd{margin:0}pre{white-space:pre-wrap;font:inherit;border-top:1px solid #dfe6ee;padding-top:20px}</style></head><body><h1>${esc(threadSubject(thread))}</h1><dl><dt>${t("mail.details.from")}</dt><dd>${esc(sender)}</dd><dt>${t("mail.details.to")}</dt><dd>${esc(recipients || t("ui.derived-data.undisclosed-recipients"))}</dd><dt>${t("mail.details.date")}</dt><dd>${esc(formatDateTimeFull(message.date))}</dd></dl><pre>${esc(body)}</pre></body></html>`);
  win.document.close();
  win.focus();
  setTimeout(() => win.print(), 250);
}

function openRuleForThread(thread) {
  const message = thread?.latest;
  const email = normalizeEmail(message?.from?.email);
  if (!email) return;
  const senderName = message.from?.name || email;
  openSettings("rules");
  setTimeout(() => {
    openRuleEditor({
      id: "",
      name: t("ui.settings.messages-from", { sender: senderName }),
      match: "all",
      conditions: [{ field: "from", operator: "is", value: email }],
      action: { type: "move", value: "archive" },
      enabled: true
    });
    const name = document.getElementById("ruleName");
    if (name) name.value = t("ui.settings.messages-from", { sender: senderName });
  }, 120);
}

function openQuickActionsDialog() {
  const selected = new Set((state.preferences.quickActions || []).slice(0, 3));
  const options = [
    ["archive", "i-archive", t("mail.list.quick.archive")],
    ["markRead", "i-envelope-open", t("mail.list.quick.markRead")],
    ["delete", "i-trash", t("mail.list.quick.delete")],
    ["flag", "i-flag", t("mail.list.quick.flag")],
    ["pin", "i-pin", t("mail.list.quick.pin")],
    ["spam", "i-alert", t("mail.list.quick.spam")],
    ["snooze", "i-clock", t("mail.list.quick.snooze")]
  ];
  const holder = document.getElementById("quickActionsChoices");
  if (!holder) return;
  holder.innerHTML = `<div class="quick-actions-grid">${options.map(([value, icon, label]) => `<button type="button" class="quick-actions-choice${selected.has(value) ? " is-selected" : ""}" data-quick-choice="${value}"><svg class="icon" aria-hidden="true"><use href="#${icon}"/></svg><span>${esc(label)}</span>${selected.has(value) ? '<span class="check">✓</span>' : ""}</button>`).join("")}</div>
    <p class="settings-note">${t("ui.thread-selection-actions.choose-up-to-three-the-shortcuts-appear-as-soon-")}</p>`;
  quickActionsOverlay.hidden = false;
}

function toggleQuickActionChoice(button) {
  if (!button) return;
  const selected = $$("#quickActionsChoices .quick-actions-choice.is-selected");
  const isSelected = button.classList.contains("is-selected");
  if (!isSelected && selected.length >= 3) {
    showToast(t("ui.thread-selection-actions.choose-up-to-three-quick-actions"));
    return;
  }
  button.classList.toggle("is-selected", !isSelected);
  const check = button.querySelector(".check");
  if (isSelected) check?.remove();
  else button.insertAdjacentHTML("beforeend", '<span class="check">✓</span>');
}

async function saveQuickActions() {
  const choices = $$("#quickActionsChoices .quick-actions-choice.is-selected").map((button) => button.getAttribute("data-quick-choice"));
  if (!choices.length) { showToast(t("ui.thread-selection-actions.choose-at-least-one-quick-action")); return; }
  try {
    const data = await api("/api/preferences", { method: "PATCH", body: { quickActions: choices } });
    state.preferences = { ...state.preferences, ...(data.preferences || {}) };
    quickActionsOverlay.hidden = true;
    renderList();
    showToast(t("ui.thread-selection-actions.quick-actions-saved"));
  } catch (error) {
    showError(error);
  }
}

async function loadMailLabels() {
  try {
    const data = await api("/api/labels");
    state.labels = data.labels || [];
    renderLabelSettings();
    renderList({ preserveScroll: true });
    renderReader({ preserveScroll: true });
  } catch {
    // The standalone reference server predates the labels API; keep the
    // built-in labels usable until the Go backend is present.
  }
}

function renderLabelSettings() {
  const holder = document.getElementById("labelSettingsList");
  if (!holder) return;
  const builtins = Object.entries(CATEGORIES).map(([id, category]) => `
    <div class="label-settings-row is-builtin">
      <span class="label-swatch" style="--label:${category.color}"></span>
      <div class="label-settings-copy"><strong>${esc(category.label)}</strong><span>${t("ui.thread-selection-actions.built-in-label")}</span></div>
      <span class="label-builtin-chip">${t("ui.thread-selection-actions.built-in")}</span>
    </div>`).join("");
  const custom = (state.labels || []).map((label) => `
    <div class="label-settings-row">
      <span class="label-swatch" style="--label:${esc(label.color || "#0f6cbd")}"></span>
      <div class="label-settings-copy"><strong>${esc(label.name)}</strong><span>${esc(label.color || "#0f6cbd")}</span></div>
      <div class="label-settings-actions">
        <button class="link-btn" type="button" data-label-edit="${esc(label.id)}">${t("tasks.detail.edit")}</button>
        <button class="link-btn danger" type="button" data-label-delete="${esc(label.id)}">${t("mail.list.quick.delete")}</button>
      </div>
    </div>`).join("");
  holder.innerHTML = `<div class="label-settings-grid">${builtins}${custom}</div>${custom ? "" : "<p class=\"settings-note\">" + t("ui.thread-selection-actions.no-custom-labels-yet-use-new-label-to-create-one") + "</p>"}`;
}

function openLabelEditor(label = null, { applyThreadId = "" } = {}) {
  state.labelEditor = { id: label?.id || "", applyThreadId };
  document.getElementById("labelEditorTitle").textContent = label ? t("ui.thread-selection-actions.edit-label") : t("ui.thread-selection-actions.new-label-title");
  document.getElementById("labelEditorSubtitle").textContent = applyThreadId
    ? t("ui.thread-selection-actions.create-a-label-and-apply-it-to-this-conversation")
    : t("ui.thread-selection-actions.give-this-label-a-name-and-a-colour");
  document.getElementById("labelEditorName").value = label?.name || "";
  document.getElementById("labelEditorColor").value = label?.color || "#0f6cbd";
  document.getElementById("labelEditorError").hidden = true;
  document.getElementById("labelEditorSave").textContent = label ? t("mail.folders.saveChanges") : t("ui.thread-selection-actions.create-label");
  updateLabelEditorPreview();
  labelEditorOverlay.hidden = false;
  setTimeout(() => document.getElementById("labelEditorName")?.focus(), 40);
}

function updateLabelEditorPreview() {
  const color = document.getElementById("labelEditorColor")?.value || "#0f6cbd";
  const name = document.getElementById("labelEditorName")?.value.trim() || t("ui.thread-selection-actions.label-preview");
  const swatch = document.getElementById("labelColorSwatch");
  const preview = document.getElementById("labelPreview");
  if (swatch) swatch.style.setProperty("--label", color);
  if (preview) {
    preview.style.setProperty("--cat", color);
    const text = preview.querySelector("span:last-child");
    if (text) text.textContent = name;
  }
}

function closeLabelEditor() {
  labelEditorOverlay.hidden = true;
  state.labelEditor = null;
}

function applyLabelToThread(threadId, labelId) {
  const thread = threadById(threadId);
  if (!thread || !labelId) return;
  const threads = [thread];
  const current = new Set(thread.latest?.categories || []);
  current.add(labelId);
  const categories = Array.from(current);
  const ids = actionMessageIds(threads);
  if (!ids.length) return;
  const snapshot = captureMailActionSnapshot(ids);
  optimisticMailAction("categorize", "", ids, { categories });
  rebuildIndex();
  renderList({ preserveScroll: true });
  renderReader({ preserveScroll: true });
  enqueueMailAction({
    ids, action: "categorize", categories, threadCount: threads.length,
    previousThreadId: thread.id, snapshot
  });
}

async function saveLabelEditor() {
  const editor = state.labelEditor;
  if (!editor) return;
  const name = document.getElementById("labelEditorName").value.trim();
  const color = document.getElementById("labelEditorColor").value;
  const error = document.getElementById("labelEditorError");
  const button = document.getElementById("labelEditorSave");
  if (!name) {
    error.textContent = t("ui.thread-selection-actions.give-the-label-a-name");
    error.hidden = false;
    return;
  }
  button.disabled = true;
  button.textContent = t("ui.thread-selection-actions.saving");
  try {
    const data = editor.id
      ? await api(`/api/labels/${encodeURIComponent(editor.id)}`, { method: "PATCH", body: { name, color } })
      : await api("/api/labels", { method: "POST", body: { name, color } });
    const label = data.label;
    if (editor.id) {
      state.labels = (state.labels || []).map((item) => item.id === label.id ? label : item);
    } else {
      state.labels = [...(state.labels || []), label];
    }
    closeLabelEditor();
    renderLabelSettings();
    renderList({ preserveScroll: true });
    renderReader({ preserveScroll: true });
    if (editor.applyThreadId && label) applyLabelToThread(editor.applyThreadId, label.id);
    showToast(editor.id ? t("ui.thread-selection-actions.label-updated") : t("ui.thread-selection-actions.label-created"));
  } catch (saveError) {
    error.textContent = saveError.message || t("ui.thread-selection-actions.could-not-save-the-label");
    error.hidden = false;
  } finally {
    button.disabled = false;
    button.textContent = editor.id ? t("mail.folders.saveChanges") : t("ui.thread-selection-actions.create-label");
  }
}

async function deleteMailLabel(id) {
  const label = (state.labels || []).find((item) => item.id === id);
  if (!label) return;
  const ok = await appConfirm({
    title: t("ui.thread-selection-actions.delete-label"),
    message: t("ui.thread-selection-actions.label-will-be-removed", { label: label.name }),
    confirmLabel: t("ui.thread-selection-actions.delete-label-1"),
    tone: "danger"
  });
  if (!ok) return;
  try {
    await api(`/api/labels/${encodeURIComponent(id)}`, { method: "DELETE" });
    state.labels = (state.labels || []).filter((item) => item.id !== id);
    state.messages.forEach((message) => {
      if (Array.isArray(message.categories)) message.categories = message.categories.filter((key) => key !== id);
    });
    rebuildIndex();
    renderLabelSettings();
    renderList({ preserveScroll: true });
    renderReader({ preserveScroll: true });
    showToast(t("ui.thread-selection-actions.label-deleted"));
  } catch (error) {
    showError(error);
  }
}

async function messageMenuCommand(command, button) {
  const thread = messageMenuThread();
  if (!thread) { closeMessageMenu(); return; }
  const threads = messageMenuActionThreads(thread);
  const target = messageMenuTargetMessage(thread);
  const selectionText = state.messageMenuSelectionText;
  const selectionRect = state.messageMenuSelectionRect;
  closeMessageMenu();
  if (command === "copyText") {
    const copied = await copyTextToClipboard(selectionText);
    showToast(copied ? t("ui.thread-selection-actions.selected-text-copied") : t("ui.thread-selection-actions.could-not-copy-the-selected-text"));
    return;
  }
  if (command === "translateSelection") {
    await openSelectionTranslation(selectionText, selectionRect);
    return;
  }
  if (command === "reply") { replyToMessage(target || replyTarget(thread)); return; }
  if (command === "replyAll") { replyToMessage(target || replyTarget(thread), true); return; }
  if (command === "forward") { forwardMessage(target || replyTarget(thread)); return; }
  if (command === "view") {
    state.selectedThreadId = thread.id;
    state.expandedThreadId = thread.id;
    if (target) state.expanded = new Set([target.id]);
    document.body.classList.add("reader-open");
    renderList();
    renderReader();
    syncSelectionUi();
    return;
  }
  if (command === "download") { await downloadMessageSource(target); return; }
  if (command === "print") { printThread(thread, target); return; }
  if (command === "findRelated") {
    const email = target?.from?.email;
    if (!email) return;
    if (state.task !== "mail") setTask("mail");
    searchInput.value = `from:${email}`;
    setQuery(searchInput.value);
    focusSearch();
    return;
  }
  if (command === "rules") { openRuleForThread(thread); return; }
  if (command === "createTask") { addThreadToTask(thread); return; }
  if (command === "quickActions") { openQuickActionsDialog(); return; }
  if (command === "reportJunk") { performBulkAction("spam", "", { threads, anchorThreadId: thread.id }); return; }
  if (command === "reportPhishing") {
    performBulkAction("report", "", { threads, anchorThreadId: thread.id, reason: "phishing", note: "" });
    return;
  }
  if (command === "reportConcern") { openReportDialog(thread); return; }
  if (command === "notSpam") { performBulkAction("notSpam", "", { threads, anchorThreadId: thread.id }); return; }
  if (command === "block") { performBulkAction("block", "", { threads, anchorThreadId: thread.id }); return; }
  if (command === "ignore") { performBulkAction("ignore", "", { threads, anchorThreadId: thread.id }); return; }
  if (command === "unignore") { performBulkAction("unignore", "", { threads, anchorThreadId: thread.id }); return; }
  if (command === "delete" || command === "archive" || command === "markRead" || command === "markUnread" || command === "pin" || command === "unpin" || command === "flag" || command === "unflag") {
    performBulkAction(command, "", { threads, anchorThreadId: thread.id });
    return;
  }
  if (command === "move" || command === "copy") {
    const folder = button?.getAttribute("data-folder-id") || "";
    if (folder) performBulkAction(command, folder, { threads, anchorThreadId: thread.id });
    return;
  }
  if (command === "snooze-custom") {
    const input = messageMenu.querySelector("[data-message-snooze-custom]");
    const value = input?.value ? new Date(input.value) : null;
    if (!value || Number.isNaN(value.getTime()) || value <= new Date()) { showToast(t("ui.thread-selection-actions.choose-a-future-snooze-time")); return; }
    performBulkAction("snooze", "", { threads, anchorThreadId: thread.id, until: value.toISOString() });
    return;
  }
}

function snoozeFromMenu(kind) {
  const thread = messageMenuThread();
  if (!thread) return;
  const until = nextSnoozeDate(kind);
  closeMessageMenu();
  performBulkAction("snooze", "", { threads: messageMenuActionThreads(thread), anchorThreadId: thread.id, until: until.toISOString() });
}

async function toggleCategoryForMenu(key) {
  const thread = messageMenuThread();
  if (!thread) return;
  const threads = messageMenuActionThreads(thread);
  const current = new Set(thread.latest?.categories || []);
  if (current.has(key)) current.delete(key);
  else current.add(key);
  const categories = Array.from(current);
  const ids = actionMessageIds(threads);
  const snapshot = captureMailActionSnapshot(ids);
  optimisticMailAction("categorize", "", ids, { categories });
  rebuildIndex();
  renderList({ preserveScroll: true });
  renderReader({ preserveScroll: true });
  rerenderMessageMenu();
  enqueueMailAction({
    ids,
    action: "categorize",
    categories,
    threadCount: threads.length,
    previousThreadId: thread.id,
    snapshot
  });
}

function setBulkBusy(busy) {
  bulkBar.classList.toggle("is-busy", busy);
  $$("#bulkBar button").forEach((button) => { button.disabled = busy; });
}

async function toggleThreadStar(threadId) {
  const thread = threadById(threadId);
  if (!thread) return;
  const starred = !thread.starred;
  thread.messages.forEach((message) => { message.starred = starred; });
  renderList();
  renderReader();
  try {
    await api("/api/messages/actions", {
      method: "POST",
      body: { ids: thread.messages.map((message) => message.id), action: starred ? "star" : "unstar" }
    });
    rebuildIndex();
    showToast(starred ? t("ui.thread-selection-actions.added-to-starred") : t("ui.thread-selection-actions.removed-from-starred"));
  } catch (error) {
    thread.messages.forEach((message) => { message.starred = !starred; });
    renderList();
    renderReader();
    showError(error);
  }
}

async function toggleThreadPin(thread = currentThread()) {
  if (!thread) return;
  const pinned = !thread.pinned;
  thread.pinned = pinned;
  thread.messages.forEach((message) => { message.pinned = pinned; });
  rebuildIndex();
  renderList();
  renderReader({ preserveScroll: true });
  try {
    await api("/api/messages/actions", {
      method: "POST",
      body: { ids: thread.messages.filter((message) => !message.draft).map((message) => message.id), action: pinned ? "pin" : "unpin" }
    });
    rebuildIndex();
    renderList();
    renderReader({ preserveScroll: true });
    showToast(pinned ? t("ui.thread-selection-actions.email-pinned") : t("ui.thread-selection-actions.email-unpinned"));
  } catch (error) {
    thread.pinned = !pinned;
    thread.messages.forEach((message) => { message.pinned = !pinned; });
    rebuildIndex();
    renderList();
    renderReader({ preserveScroll: true });
    showError(error);
  }
}

async function toggleMessageStar(messageId) {
  const message = messageById(messageId);
  if (!message) return;
  message.starred = !message.starred;
  renderList();
  renderReader({ preserveScroll: true });
  try {
    await api(`/api/messages/${encodeURIComponent(messageId)}`, { method: "PATCH", body: { starred: message.starred } });
    rebuildIndex();
  } catch (error) {
    message.starred = !message.starred;
    renderList();
    renderReader({ preserveScroll: true });
    showError(error);
  }
}

async function toggleThreadFlag(thread = currentThread()) {
  if (!thread) return;
  const flagged = !thread.flagged;
  thread.flagged = flagged;
  thread.messages.forEach((message) => { message.flagged = flagged; });
  renderList();
  renderReader({ preserveScroll: true });
  try {
    await api("/api/messages/actions", {
      method: "POST",
      body: { ids: thread.messages.filter((message) => !message.draft).map((message) => message.id), action: flagged ? "flag" : "unflag" }
    });
    rebuildIndex();
    renderList();
    showToast(flagged ? t("mail.list.flagged") : t("ui.thread-selection-actions.follow-up-flag-cleared"));
  } catch (error) {
    thread.flagged = !flagged;
    thread.messages.forEach((message) => { message.flagged = !flagged; });
    renderList();
    renderReader({ preserveScroll: true });
    showError(error);
  }
}

let pendingReportThreadId = null;
function openReportDialog(thread = currentThread()) {
  if (!thread) {
    showToast(t("ui.thread-selection-actions.select-a-conversation-first"));
    return;
  }
  pendingReportThreadId = thread.id;
  const latest = thread.latest;
  const sender = latest && latest.from ? `${latest.from.name || latest.from.email} <${latest.from.email}>` : t("mail.list.unknownSender");
  reportMessageCard.innerHTML = `<strong>${esc(threadSubject(thread))}</strong><span>${esc(tn("ui.thread-selection-actions.report-card-summary", thread.count, { sender, count: thread.count }))}</span>`;
  reportNote.value = "";
  const defaultReason = reportOverlay.querySelector('input[name="reportReason"][value="phishing"]');
  if (defaultReason) defaultReason.checked = true;
  reportOverlay.hidden = false;
  setTimeout(() => {
    const checked = reportOverlay.querySelector('input[name="reportReason"]:checked') || reportOverlay.querySelector('input[name="reportReason"]');
    if (checked) checked.focus();
  }, 40);
}

function closeReportDialog() {
  reportOverlay.hidden = true;
  reportSubmit.classList.remove("is-busy");
  reportSubmit.disabled = false;
  pendingReportThreadId = null;
}

async function submitSpamReport() {
  const thread = pendingReportThreadId ? threadById(pendingReportThreadId) : currentThread();
  if (!thread) {
    closeReportDialog();
    showToast(t("ui.thread-selection-actions.that-conversation-is-no-longer-available"));
    return;
  }
  const reasonInput = reportOverlay.querySelector('input[name="reportReason"]:checked');
  const ids = thread.messages.filter((message) => message.folder !== "drafts").map((message) => message.id);
  if (!ids.length) {
    closeReportDialog();
    showToast(t("ui.thread-selection-actions.there-is-nothing-to-report"));
    return;
  }
  reportSubmit.classList.add("is-busy");
  reportSubmit.disabled = true;
  try {
    await api("/api/messages/actions", {
      method: "POST",
      body: {
        ids,
        action: "report",
        reason: reasonInput ? reasonInput.value : "spam",
        note: reportNote.value.trim()
      }
    });
    const previousThreadId = state.selectedThreadId;
    closeReportDialog();
    await refreshMailbox({ quiet: true });
    if (previousThreadId && !state.viewThreads.some((item) => item.id === previousThreadId)) {
      state.selectedThreadId = null;
      state.expandedThreadId = null;
      document.body.classList.remove("reader-open");
    }
    renderList();
    renderReader();
    syncSelectionUi();
    const senders = senderEmailsForThreads([thread]);
    if (senders.length) await updateSenderRules(senders, "spam", { message: t("ui.thread-selection-actions.reported-sender-set-to-go-to-junk") });
    showToast(t("ui.thread-selection-actions.reported-to-alt8mail-security-sender-blocked-pen"));
  } catch (error) {
    reportSubmit.classList.remove("is-busy");
    reportSubmit.disabled = false;
    showError(error);
  }
}

function markThreadUnread(thread) {
  if (!thread) return;
  const ids = thread.messages.filter((message) => !message.draft).map((message) => message.id);
  thread.messages.forEach((message) => {
    if (!message.unread) {
      adjustFolderUnread(message.folder, 1);
      adjustSubscriptionUnread(message, 1);
    }
    message.unread = true;
  });
  rebuildIndex();
  renderFolders();
  renderList();
  renderReader({ preserveScroll: true });
  api("/api/messages/actions", { method: "POST", body: { ids, action: "markUnread" } })
    .then(() => showToast(t("ui.thread-selection-actions.marked-as-unread")))
    .catch((error) => { showError(error); refreshMailbox({ quiet: true }).catch(() => {}); });
}

function closeReaderPane() {
  state.selectedThreadId = null;
  state.expandedThreadId = null;
  state.expanded = new Set();
  document.body.classList.remove("reader-open");
  renderList();
  renderReader();
  writeAppHash({ replace: true });
}

function readerAction(action, trigger = null) {
  const thread = currentThread();
  if (!thread) return;
  if (action === "reply") return replyToMessage(replyTarget(thread));
  if (action === "reply-all") return replyToMessage(replyTarget(thread), true);
  if (action === "ai-reply") return replyWithAi(thread);
  if (action === "react") {
    const message = thread.latest;
    if (!threadReactionAllowed(thread)) {
      showToast(t("ui.thread-selection-actions.reactions-are-unavailable-for-this-conversation"));
      return;
    }
    return openReactionMenu(trigger || document.getElementById("readerReactBtn"), message);
  }
  if (action === "forward") return forwardMessage(thread.latest);
  if (action === "archive") return performBulkAction("archive");
  if (action === "delete") return performBulkAction("delete");
  if (action === "mark-unread") return markThreadUnread(thread);
  if (action === "flag") return toggleThreadFlag(thread);
  if (action === "task") return addThreadToTask(thread);
  if (action === "pin") return toggleThreadPin(thread);
  if (action === "spam") return performBulkAction(thread.messages.some((message) => message.folder === "spam") ? "notSpam" : "spam");
  if (action === "report") return openReportDialog(thread);
}

/* ============================================================
   compose manager
   ============================================================ */
function sessionById(id) {
  return composeSessions.find((session) => session.id === id) || null;
}

const RECIPIENT_FIELDS = ["to", "cc", "bcc"];

function splitRecipientText(value) {
  const parts = [];
  let current = "";
  let quote = false;
  let angle = 0;
  for (const ch of String(value || "")) {
    if (ch === '"' && angle === 0) { quote = !quote; current += ch; continue; }
    if (!quote) {
      if (ch === "<") angle += 1;
      else if (ch === ">" && angle > 0) angle -= 1;
    }
    if (!quote && angle === 0 && (ch === "," || ch === ";")) {
      parts.push(current);
      current = "";
    } else {
      current += ch;
    }
  }
  parts.push(current);
  return parts;
}

function parseRecipientEntry(value) {
  const raw = String(value || "").trim();
  if (!raw) return null;
  let name = "";
  let email = raw;
  const angled = raw.match(/^(?:"([^"]*)"|([^<]*?))\s*<([^>\s]+)>\s*$/);
  if (angled) {
    name = String(angled[1] || angled[2] || "").trim();
    email = angled[3];
  } else {
    const comment = raw.match(/^([^\s()]+@[^\s()]+)\s*\(([^)]*)\)\s*$/);
    if (comment) {
      email = comment[1];
      name = comment[2].trim();
    }
  }
  email = normalizeEmail(email);
  const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  return { raw, name, email, valid };
}

function parseRecipientList(value) {
  const seen = new Set();
  const entries = [];
  for (const part of splitRecipientText(value)) {
    const entry = parseRecipientEntry(part);
    if (!entry) continue;
    const key = normalizeEmail(entry.email);
    if (key && seen.has(key)) continue;
    if (key) seen.add(key);
    entries.push(entry);
  }
  return entries;
}

function formatRecipientName(name) {
  const value = String(name || "").trim();
  if (!value || value.includes(",") || value.includes("<") || value.includes(">")) {
    return value ? `"${value.replace(/"/g, '\\"')}"` : "";
  }
  return value;
}

function formatRecipientEntry(entry) {
  if (!entry) return "";
  if (entry.name && normalizeEmail(entry.name) !== normalizeEmail(entry.email)) {
    return `${formatRecipientName(entry.name)} <${entry.email}>`;
  }
  return entry.email;
}

function recipientTextFromEntries(entries) {
  return entries.map(formatRecipientEntry).filter(Boolean).join(", ");
}

function recipientTextWithPending(session, field) {
  const base = String(session[field] || "").trim();
  const pending = String(session.recipientInput?.[field] || "").trim();
  if (!pending) return base;
  return base ? `${base}, ${pending}` : pending;
}

function recipientEntriesFor(session, field) {
  return parseRecipientList(session[field] || "");
}

function recipientPersonFor(entry) {
  return state.people.find((person) => normalizeEmail(person.email) === normalizeEmail(entry.email)) || null;
}

function recipientChipsMarkup(session, field) {
  return recipientEntriesFor(session, field).map((entry, index) => {
    const person = recipientPersonFor(entry);
    const label = entry.name || (person && person.name) || entry.email;
    const showEmail = Boolean(entry.name && normalizeEmail(entry.name) !== normalizeEmail(entry.email));
    return `<span class="recipient-chip${entry.valid ? "" : " is-invalid"}" title="${esc(entry.email || entry.raw)}">
      ${person ? avatar(person, "xs") : ""}
      <span class="recipient-chip-copy"><span class="recipient-chip-name" dir="auto">${esc(label)}</span>${showEmail ? `<span class="recipient-chip-email" dir="ltr">${esc(entry.email)}</span>` : ""}</span>
      <button type="button" class="recipient-chip-remove" data-recipient-remove="${field}" data-recipient-index="${index}" aria-label="${esc(t("ui.thread-selection-actions.remove-name", { name: entry.email || entry.raw }))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button>
    </span>`;
  }).join("");
}

function recipientInputPlaceholder(session, field) {
  return recipientEntriesFor(session, field).length ? t("ui.compose-manager.add-another-recipient") : "name@example.com";
}

function recipientCandidates(session, field) {
  const query = String(session.recipientInput?.[field] || "").trim().toLowerCase();
  const selected = new Set(recipientEntriesFor(session, field).map((entry) => normalizeEmail(entry.email)));
  const candidates = [];
  const seen = new Set();
  for (const person of state.people) {
    const email = normalizeEmail(person.email);
    if (!email || selected.has(email) || seen.has(email)) continue;
    if (query) {
      const haystack = [person.name, person.email, person.company, person.title, person.team, person.role].join(" ").toLowerCase();
      if (!haystack.includes(query)) continue;
    }
    seen.add(email);
    candidates.push(person);
  }
  candidates.sort((a, b) => {
    const aName = String(a.name || "").toLowerCase();
    const bName = String(b.name || "").toLowerCase();
    const aEmail = normalizeEmail(a.email);
    const bEmail = normalizeEmail(b.email);
    const score = (person, name, email) => {
      if (!query) return person.source === "directory" ? 0 : 1;
      if (name.startsWith(query) || email.startsWith(query)) return 0;
      if (name.split(/\s+/).some((part) => part.startsWith(query))) return 1;
      return 2;
    };
    return score(a, aName, aEmail) - score(b, bName, bEmail) || aName.localeCompare(bName);
  });
  return candidates.slice(0, 8);
}

function recipientSuggestionMarkup(session, field) {
  const people = recipientCandidates(session, field);
  const queryEntry = parseRecipientEntry(session.recipientInput?.[field] || "");
  const selected = new Set(recipientEntriesFor(session, field).map((entry) => normalizeEmail(entry.email)));
  const rows = people.map((person, index) => `
    <button type="button" class="recipient-suggestion${session.recipientHighlight === index ? " is-active" : ""}" role="option" data-recipient-suggest-email="${esc(person.email)}" data-recipient-suggest-name="${esc(person.name || "")}">
      ${avatar(person, "sm")}
      <span class="recipient-suggestion-copy"><strong>${esc(person.name || person.email)}</strong><span>${esc(person.email)}${person.company ? ` · ${esc(person.company)}` : ""}</span></span>
      <span class="recipient-suggestion-source">${person.source === "directory" ? t("ui.compose-manager.directory") : person.source === "auto" ? t("ui.compose-manager.auto-saved") : t("ui.compose-manager.contact")}</span>
    </button>`).join("");
  const addRow = queryEntry?.valid && !selected.has(queryEntry.email) && !people.some((person) => normalizeEmail(person.email) === queryEntry.email)
    ? `<button type="button" class="recipient-suggestion recipient-suggestion-add" role="option" data-recipient-add="${esc(queryEntry.email)}" data-recipient-add-name="${esc(queryEntry.name || "")}">
        <span class="recipient-suggestion-add-icon"><svg class="icon" aria-hidden="true"><use href="#i-plus"/></svg></span>
        <span class="recipient-suggestion-copy"><strong>Add ${esc(queryEntry.email)}</strong><span>${t("ui.compose-manager.save-to-your-contacts-and-add-as-a-recipient")}</span></span>
      </button>`
    : "";
  if (!rows && !addRow) return `<div class="recipient-suggest-empty">${t("ui.compose-manager.no-matching-people-or-contacts")}</div>`;
  return rows + addRow;
}

function updateRecipientSuggestions(session, field) {
  const input = session.el?.querySelector(`[data-recipient-input="${field}"]`);
  const panel = session.el?.querySelector(`[data-recipient-suggest="${field}"]`);
  if (!input || !panel) return;
  if (document.activeElement !== input) { panel.hidden = true; input.setAttribute("aria-expanded", "false"); return; }
  panel.innerHTML = recipientSuggestionMarkup(session, field);
  panel.hidden = false;
  input.setAttribute("aria-expanded", "true");
}

function closeRecipientSuggestions(session, field) {
  for (const name of field ? [field] : RECIPIENT_FIELDS) {
    const panel = session.el?.querySelector(`[data-recipient-suggest="${name}"]`);
    const input = session.el?.querySelector(`[data-recipient-input="${name}"]`);
    if (panel) panel.hidden = true;
    if (input) input.setAttribute("aria-expanded", "false");
  }
  if (session) session.recipientHighlight = -1;
}

function updateRecipientField(session, field) {
  const chips = session.el?.querySelector(`[data-recipient-chips="${field}"]`);
  const input = session.el?.querySelector(`[data-recipient-input="${field}"]`);
  const wrap = session.el?.querySelector(`[data-compose-field-wrap="${field}"]`);
  if (chips) chips.innerHTML = recipientChipsMarkup(session, field);
  if (input) {
    input.placeholder = recipientInputPlaceholder(session, field);
    input.value = session.recipientInput?.[field] || "";
  }
  if (wrap) wrap.classList.remove("is-error");
  if (session?.encrypt) scheduleComposeEncryptionCheck(session);
}

function autoSaveRecipient(entry) {
  if (!entry?.valid) return;
  const existing = state.people.find((person) => normalizeEmail(person.email) === normalizeEmail(entry.email));
  if (existing && existing.source === "directory") return;
  if (existing && existing.source !== "auto") return;
  api("/api/contacts/auto", { method: "POST", body: { email: entry.email, name: entry.name || "" } })
    .then((data) => {
      if (!data?.contact) return;
      mergeContactPerson(data.contact);
      for (const session of composeSessions) {
        for (const field of RECIPIENT_FIELDS) {
          if (recipientEntriesFor(session, field).some((item) => normalizeEmail(item.email) === normalizeEmail(data.contact.email))) {
            updateRecipientField(session, field);
          }
        }
      }
    })
    .catch(() => {});
}

function addRecipientEntry(session, field, entry, { focus = true } = {}) {
  if (!entry?.valid) return false;
  const entries = recipientEntriesFor(session, field);
  if (entries.some((item) => normalizeEmail(item.email) === normalizeEmail(entry.email))) {
    session.recipientInput[field] = "";
    updateRecipientField(session, field);
    closeRecipientSuggestions(session, field);
    return true;
  }
  entries.push(entry);
  session[field] = recipientTextFromEntries(entries);
  session.recipientInput[field] = "";
  session.dirty = true;
  session.error = null;
  updateRecipientField(session, field);
  closeRecipientSuggestions(session, field);
  autoSaveRecipient(entry);
  scheduleComposeSave(session);
  scheduleToneSuggestion(session);
  if (focus) session.el?.querySelector(`[data-recipient-input="${field}"]`)?.focus();
  return true;
}

function mentionMapFrom(values) {
  const map = new Map();
  for (const raw of Array.isArray(values) ? values : []) {
    const email = normalizeEmail(typeof raw === "string" ? raw : raw?.email);
    if (!email || map.has(email)) continue;
    map.set(email, { email, name: String(typeof raw === "string" ? "" : raw?.name || email) });
  }
  return map;
}

function renderComposeToneChip(session) {
  const chip = session.el?.querySelector("[data-compose-tone-chip]");
  if (!chip) return;
  const suggestion = session.toneSuggestion;
  const available = Boolean(state.ai?.enabled && suggestion?.available && suggestion.style);
  chip.hidden = !available;
  if (!available) {
    chip.innerHTML = "";
    return;
  }
  chip.innerHTML = `<svg class="icon" aria-hidden="true"><use href="#i-sparkles"/></svg><span>${esc(suggestion.label || suggestion.style)}</span>`;
  chip.title = suggestion.reason || t("ui.compose-manager.suggested-tone", { tone: suggestion.label || suggestion.style });
  chip.setAttribute("data-tone-style", suggestion.style);
  chip.setAttribute("data-tone-label", suggestion.label || suggestion.style);
  chip.setAttribute("data-tone-reason", suggestion.reason || "");
}

function scheduleToneSuggestion(session) {
  if (!session) return;
  clearTimeout(session.toneTimer);
  session.toneTimer = null;
  if (session.clientSide || clientSideEncryption()) {
    session.toneSuggestion = null;
    renderComposeToneChip(session);
    return;
  }
  if (!state.ai?.enabled) {
    session.toneSuggestion = null;
    renderComposeToneChip(session);
    return;
  }
  const recipient = recipientEntriesFor(session, "to")[0]?.email;
  if (!recipient) {
    session.toneSuggestion = null;
    renderComposeToneChip(session);
    return;
  }
  session.toneTimer = setTimeout(async () => {
    const currentRecipient = recipientEntriesFor(session, "to")[0]?.email;
    if (!currentRecipient || normalizeEmail(currentRecipient) !== normalizeEmail(recipient)) return;
    try {
      const data = await api("/api/ai/tone", {
        method: "POST",
        body: {
          recipient,
          subject: session.subject || "",
          draft: session.body || stripHtml(session.bodyHtml || ""),
          language: state.preferences.language || "en-US",
          accountId: composeAccountIdFor(session.fromEmail)
        }
      });
      if (!composeSessions.includes(session)) return;
      session.toneSuggestion = data?.available ? data : null;
      renderComposeToneChip(session);
    } catch {
      if (!composeSessions.includes(session)) return;
      session.toneSuggestion = null;
      renderComposeToneChip(session);
    }
  }, 650);
}

function composeMentionCandidates(query) {
  const needle = String(query || "").toLowerCase();
  const me = normalizeEmail(state.user?.email);
  return (state.people || [])
    .filter((person) => person.source === "directory" && normalizeEmail(person.email) !== me)
    .filter((person) => !needle || String(person.name || "").toLowerCase().includes(needle) || String(person.email || "").toLowerCase().includes(needle))
    .slice(0, 6);
}

function composeMentionContext(session) {
  const editor = session.el?.querySelector("[data-compose-editor]");
  if (editor) {
    const selection = window.getSelection();
    if (!selection || !selection.rangeCount) return null;
    const node = selection.anchorNode;
    if (!node || node.nodeType !== Node.TEXT_NODE || !editor.contains(node)) return null;
    const before = String(node.nodeValue || "").slice(0, selection.anchorOffset);
    const match = before.match(/(?:^|[\s(])@([\p{L}\p{N}._-]{0,40})$/u);
    if (!match) return null;
    const start = selection.anchorOffset - match[1].length - 1;
    const range = selection.getRangeAt(0).cloneRange();
    range.collapse(true);
    return {
      field: "html", node, start, end: selection.anchorOffset, query: match[1],
      rect: range.getBoundingClientRect(), editor
    };
  }
  const textarea = session.el?.querySelector('textarea[data-compose-field="body"]');
  if (!textarea) return null;
  const before = String(textarea.value || "").slice(0, textarea.selectionStart);
  const match = before.match(/(?:^|[\s(])@([\p{L}\p{N}._-]{0,40})$/u);
  if (!match) return null;
  return {
    field: "text", element: textarea, start: textarea.selectionStart - match[1].length - 1,
    end: textarea.selectionStart, query: match[1], rect: textarea.getBoundingClientRect()
  };
}

function closeComposeMentionMenu(session) {
  if (!session) return;
  session.mentionMenu?.remove();
  session.mentionMenu = null;
  session.mentionCtx = null;
}

function placeComposeMentionMenu(menu, rect) {
  const width = Math.min(310, window.innerWidth - 24);
  const left = Math.min(window.innerWidth - width - 12, Math.max(12, rect.left || 12));
  let top = (rect.bottom || rect.top || 12) + 5;
  const height = menu.offsetHeight;
  if (top + height > window.innerHeight - 12) top = Math.max(12, (rect.top || 12) - height - 5);
  menu.style.width = `${width}px`;
  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
}

function showComposeMentionMenu(session, ctx) {
  closeComposeMentionMenu(session);
  const people = composeMentionCandidates(ctx.query);
  if (!people.length) return;
  session.mentionCtx = ctx;
  const menu = document.createElement("div");
  menu.className = "compose-mention-menu";
  menu.setAttribute("role", "listbox");
  menu.innerHTML = people.map((person) => `<button type="button" role="option" data-mention-email="${esc(person.email)}"><span class="compose-mention-name">${esc(person.name || person.email)}</span><span class="compose-mention-address">${esc(person.email)}</span></button>`).join("");
  menu.addEventListener("mousedown", (event) => event.preventDefault());
  menu.addEventListener("click", (event) => {
    const option = event.target.closest("[data-mention-email]");
    if (!option) return;
    const person = people.find((item) => normalizeEmail(item.email) === normalizeEmail(option.getAttribute("data-mention-email")));
    if (person) insertComposeMention(session, person);
  });
  document.body.appendChild(menu);
  session.mentionMenu = menu;
  placeComposeMentionMenu(menu, ctx.rect);
}

function refreshComposeMentionPicker(session) {
  const ctx = composeMentionContext(session);
  if (!ctx) {
    closeComposeMentionMenu(session);
    return;
  }
  showComposeMentionMenu(session, ctx);
}

function insertComposeMention(session, person) {
  const ctx = session.mentionCtx;
  const email = normalizeEmail(person.email);
  if (!ctx || !email) return;
  const insertion = "@" + (person.name || email) + " ";
  session.mentions.set(email, { email, name: person.name || email });
  if (ctx.field === "html" && ctx.node) {
    const text = String(ctx.node.nodeValue || "");
    ctx.node.nodeValue = text.slice(0, ctx.start) + insertion + text.slice(ctx.end);
    const range = document.createRange();
    range.setStart(ctx.node, ctx.start + insertion.length);
    range.collapse(true);
    const selection = window.getSelection();
    selection?.removeAllRanges();
    selection?.addRange(range);
    ctx.editor.focus();
    ctx.editor.dispatchEvent(new Event("input", { bubbles: true }));
  } else if (ctx.field === "text" && ctx.element) {
    ctx.element.setRangeText(insertion, ctx.start, ctx.end, "end");
    ctx.element.focus();
    ctx.element.dispatchEvent(new Event("input", { bubbles: true }));
  }
  closeComposeMentionMenu(session);
}

function openComposeMentionPicker(session) {
  const editor = session.el?.querySelector("[data-compose-editor]");
  if (editor) {
    editor.focus();
    document.execCommand("insertText", false, "@");
  } else {
    const textarea = session.el?.querySelector('textarea[data-compose-field="body"]');
    if (!textarea) return;
    textarea.focus();
    textarea.setRangeText("@", textarea.selectionStart, textarea.selectionEnd, "end");
    textarea.dispatchEvent(new Event("input", { bubbles: true }));
  }
  refreshComposeMentionPicker(session);
}

function commitRecipientInput(session, field, { focus = true } = {}) {
  const input = session.el?.querySelector(`[data-recipient-input="${field}"]`);
  const text = String(session.recipientInput?.[field] || "").trim();
  if (!text) { closeRecipientSuggestions(session, field); return true; }
  const entries = parseRecipientList(text);
  const valid = entries.filter((entry) => entry.valid);
  if (!valid.length) {
    const wrap = session.el?.querySelector(`[data-compose-field-wrap="${field}"]`);
    if (wrap) wrap.classList.add("is-error");
    if (input) input.setAttribute("aria-invalid", "true");
    return false;
  }
  for (const entry of valid) addRecipientEntry(session, field, entry, { focus: false });
  session.recipientInput[field] = "";
  if (input) { input.value = ""; input.removeAttribute("aria-invalid"); }
  updateRecipientField(session, field);
  if (focus) input?.focus();
  return true;
}

function flushRecipientInputs(session, { schedule = false } = {}) {
  if (!session) return;
  for (const field of RECIPIENT_FIELDS) {
    if (String(session.recipientInput?.[field] || "").trim()) {
      commitRecipientInput(session, field, { focus: false });
    }
  }
  if (schedule) scheduleComposeSave(session);
}

function recipientKeydown(event, session, input) {
  const field = input.getAttribute("data-recipient-input");
  if (!field) return;
  if (event.key === "ArrowDown" || event.key === "ArrowUp") {
    if (input.getAttribute("aria-expanded") !== "true") updateRecipientSuggestions(session, field);
    const count = session.el?.querySelectorAll(`[data-recipient-suggest="${field}"] .recipient-suggestion`).length || 0;
    if (!count) return;
    event.preventDefault();
    const step = event.key === "ArrowDown" ? 1 : -1;
    session.recipientHighlight = ((Number(session.recipientHighlight) || 0) + step + count) % count;
    updateRecipientSuggestions(session, field);
    return;
  }
  if (event.key === "Escape") { closeRecipientSuggestions(session, field); return; }
  if (event.key === "Backspace" && !input.value && !session.recipientInput?.[field]) {
    const entries = recipientEntriesFor(session, field);
    if (entries.length) {
      event.preventDefault();
      entries.pop();
      session[field] = recipientTextFromEntries(entries);
      session.dirty = true;
      updateRecipientField(session, field);
      scheduleComposeSave(session);
    }
    return;
  }
  if (event.key === "Enter" || event.key === "Tab" || event.key === "," || event.key === ";") {
    if ((event.key === "," || event.key === ";") && !input.value.trim()) return;
    const highlighted = session.el?.querySelector(`[data-recipient-suggest="${field}"] .recipient-suggestion.is-active`);
    if (event.key === "Enter" && highlighted) {
      event.preventDefault();
      const entry = parseRecipientEntry(highlighted.getAttribute("data-recipient-suggest-email") || highlighted.getAttribute("data-recipient-add") || "");
      if (entry?.valid) {
        entry.name = highlighted.getAttribute("data-recipient-suggest-name") || highlighted.getAttribute("data-recipient-add-name") || entry.name;
        addRecipientEntry(session, field, entry);
      }
      return;
    }
    if (event.key === "Tab" && !input.value.trim()) return;
    event.preventDefault();
    commitRecipientInput(session, field);
  }
}

function recipientPaste(event, session, input) {
  const field = input.getAttribute("data-recipient-input");
  const text = event.clipboardData?.getData("text/plain") || "";
  if (!field || !text.trim()) return;
  event.preventDefault();
  const parts = splitRecipientText(text);
  const endsDelimited = /[;,]\s*$/.test(text);
  const tail = endsDelimited ? "" : parts.pop();
  for (const part of parts) {
    const entry = parseRecipientEntry(part);
    if (entry?.valid) addRecipientEntry(session, field, entry, { focus: false });
  }
  if (tail) {
    session.recipientInput[field] = tail.trim();
    updateRecipientField(session, field);
    updateRecipientSuggestions(session, field);
  }
  input.value = session.recipientInput?.[field] || "";
}

function draftMessageFromSession(session) {
  return state.messages.find((message) => message.id === session.draftId) || null;
}

function isComposeEmpty(session) {
  let body = String(session.body || "").trim();
  const signature = String(session.autoSignature?.text || "").trim();
  const compact = (value) => String(value || "").replace(/\s+/g, "").toLowerCase();
  if (signature && compact(body) === compact(signature)) body = "";
  return !session.to.trim() && !session.cc.trim() && !session.bcc.trim()
    && !Object.values(session.recipientInput || {}).some((value) => String(value).trim())
    && !session.subject.trim() && !body && !session.files.length;
}

function aliasesForSelect() {
  return state.aliases.filter((alias) => alias.canSend);
}

function aliasForEmail(email) {
  return state.aliases.find((alias) => normalizeEmail(alias.email) === normalizeEmail(email)) || null;
}

function aliasDisplay(email) {
  const alias = aliasForEmail(email);
  if (alias) return alias.label && normalizeEmail(alias.label) !== normalizeEmail(alias.email) ? `${alias.label} · ${alias.email}` : alias.email;
  return email || (state.user ? state.user.email : "");
}

function composePriorityMarkup(session) {
  return [["low", t("tasks.priority.low")], ["normal", t("tasks.priority.normal")], ["high", t("tasks.priority.high")]].map(([value, label]) =>
    `<button class="compose-priority-btn${session.priority === value ? " is-active" : ""}" data-compose-priority="${value}" type="button" role="radio" aria-checked="${session.priority === value ? "true" : "false"}" title="${esc(t("ui.compose-manager.priority-label", { priority: label }))}"><span class="priority-dot ${value}"></span>${label}</button>`
  ).join("");
}

function dlpPolicy() {
  const config = state.tenantPolicy && state.tenantPolicy.dlp;
  const labels = Array.isArray(config?.labels) && config.labels.length ? config.labels : [t("ui.compose-manager.public"), t("mail.details.internal"), t("ui.compose-manager.confidential"), t("ui.compose-manager.restricted")];
  return {
    enabled: config?.enabled !== false,
    labels,
    defaultClassification: config?.defaultClassification || t("mail.details.internal"),
  };
}

function classificationOptionsMarkup(selected) {
  const config = dlpPolicy();
  const value = config.labels.includes(selected) ? selected : config.defaultClassification;
  return config.labels.map((label) => `<option value="${esc(label)}"${label === value ? " selected" : ""}>${esc(label)}</option>`).join("");
}

function updateComposeClassification(session) {
  if (!session?.el) return;
  const select = session.el.querySelector('[data-compose-field="classification"]');
  if (select && dlpPolicy().labels.includes(session.classification)) select.value = session.classification;
}

function composeAiToolbarButton() {
  if (!state.ai.enabled || clientSideEncryption()) return "";
  return `<button type="button" class="compose-ai-btn" data-compose-action="ai" title="${esc(t("ui.compose-manager.ai-writing-assistant"))}" aria-label="${esc(t("ui.compose-manager.ai-writing-assistant"))}"><svg class="icon" aria-hidden="true"><use href="#i-sparkles"/></svg><span class="compose-ai-label">AI</span></button>`;
}

function composeMentionToolbarButton() {
  return `<button type="button" class="compose-mention-btn" data-compose-action="mention" title="${esc(t("ui.compose-manager.mention-a-coworker"))}" aria-label="${esc(t("ui.compose-manager.mention-a-coworker"))}">@</button>`;
}

function composeLightButton(session) {
  return `<button type="button" class="editor-light-btn" data-compose-action="editor-light" title="${esc(t("ui.compose-manager.light-writing-area"))}" aria-label="${esc(t("ui.compose-manager.toggle-light-writing-area"))}" aria-pressed="${session.editorLight ? "true" : "false"}"><svg class="icon" aria-hidden="true"><use href="#i-bulb"/></svg></button>`;
}

function setEditorLight(session, enabled) {
  session.editorLight = Boolean(enabled);
  state.editorLight = session.editorLight;
  try { localStorage.setItem("a8m.editorLight", session.editorLight ? "1" : "0"); } catch {}
  session.el?.querySelector(".compose-editor-wrap")?.classList.toggle("is-editor-light", session.editorLight);
  session.el?.querySelectorAll('[data-compose-action="editor-light"]').forEach((button) => {
    button.setAttribute("aria-pressed", session.editorLight ? "true" : "false");
    button.classList.toggle("is-active", session.editorLight);
  });
}

function composeDirectionControls(session) {
  const current = session.direction || "auto";
  const button = (value, label, title) =>
    `<button type="button" data-compose-direction="${value}" class="${current === value ? "is-active" : ""}" aria-pressed="${current === value}" title="${esc(title)}">${esc(label)}</button>`;
  return `<span class="compose-direction" role="group" aria-label="${esc(t("compose.direction"))}">
    ${button("auto", t("compose.direction.auto"), t("compose.direction.autoHint"))}
    ${button("ltr", "LTR", t("compose.direction.ltrHint"))}
    ${button("rtl", "RTL", t("compose.direction.rtlHint"))}
  </span>`;
}

function setComposeDirection(session, direction) {
  if (!session) return;
  const value = ["auto", "ltr", "rtl"].includes(direction) ? direction : "auto";
  session.direction = value;
  for (const field of session.el?.querySelectorAll("[data-compose-editor], [data-compose-field=\"body\"]") || []) {
    field.setAttribute("dir", value);
  }
  for (const button of session.el?.querySelectorAll("[data-compose-direction]") || []) {
    const active = button.getAttribute("data-compose-direction") === value;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  }
  session.dirty = true;
  scheduleComposeSave(session);
}

