function duplicateReplyWarningMarkup(warning) {
  const name = warning?.senderName || warning?.senderEmail || t("ui.compose-manager.this-sender");
  const count = Math.max(1, Number(warning?.count) || 1);
  const copy = count > 1
    ? esc(tn("ui.thread-selection-actions.other-messages-same-subject", count, { count, name }))
    : esc(t("ui.thread-selection-actions.another-message-same-subject", { name }));
  return `<div class="compose-duplicate-warning" data-compose-warning role="status">
    <span class="compose-duplicate-warning-icon"><svg class="icon" aria-hidden="true"><use href="#i-warning-triangle"/></svg></span>
    <span class="compose-duplicate-warning-copy">${copy} <strong>${t("ui.compose-manager.check-the-earlier-message-before-replying")}</strong></span>
    <button class="compose-duplicate-warning-close" type="button" data-compose-warning-close aria-label="${esc(t("ui.compose-manager.dismiss-reminder"))}" title="${esc(t("ui.compose-manager.dismiss-reminder"))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button>
  </div>`;
}

async function checkComposeDuplicateWarning(session) {
  if (!session?.sourceMessageId || !["reply", "replyAll"].includes(session.kind)) return;
  try {
    const data = await api(`/api/messages/${encodeURIComponent(session.sourceMessageId)}/reply-context`);
    const warning = data?.duplicate;
    const live = sessionById(session.id);
    if (!warning || !live?.el || live.duplicateWarning) return;
    live.duplicateWarning = warning;
    const host = live.el.querySelector("[data-compose-warning-host]");
    if (!host) return;
    host.innerHTML = duplicateReplyWarningMarkup(warning);
    host.hidden = false;
  } catch {}
}

function composeEncryptionProtocols() {
  const protocols = state.encryption?.protocols;
  if (Array.isArray(protocols) && protocols.length) return protocols;
  if (state.encryption?.protocol === "both") return ["openpgp", "smime"];
  return [state.encryption?.protocol || "openpgp"];
}

function composeProtocolLabel(protocol) {
  return protocol === "smime" ? t("ui.settings.smime") : t("ui.settings.openpgp");
}

function composeProtocolIdentity(protocol, status = state.encryption) {
  if (!status) return null;
  return protocol === "smime" ? (status.smimeIdentity || null) : (status.identity || null);
}

function defaultComposeProtocol(preferred = "") {
  const protocols = composeEncryptionProtocols();
  const requested = String(preferred || "").toLowerCase();
  if (protocols.includes(requested)) return requested;
  return protocols.find((protocol) => composeProtocolIdentity(protocol)) || protocols[0] || "openpgp";
}

function composeProtectionMarkup(session) {
  if (!state.encryption?.enabled) return "";
  if (session.clientSide || clientSideEncryption()) {
    const protocols = composeEncryptionProtocols();
    const protocolSelect = protocols.length > 1
      ? `<label class="compose-option"><span>${esc(t("ui.compose.protocol"))}</span><select data-compose-field="protocol">${protocols.map((protocol) => `<option value="${esc(protocol)}"${clientComposeProtocol(session) === protocol ? " selected" : ""}>${esc(composeProtocolLabel(protocol))}</option>`).join("")}</select></label>`
      : "";
    return `<div class="compose-option compose-protection">
      <span>${esc(t("ui.compose.client-e2ee"))}</span>
      <div class="compose-protection-toggles">
        <label class="compose-check"><input type="checkbox" data-compose-field="sign" ${session.sign ? "checked" : ""}>${esc(t("ui.compose.sign-message"))}</label>
      </div>
      ${protocolSelect}
      <div class="compose-encryption-status" data-compose-encryption-status></div>
      <span class="compose-encryption-note">${esc(t("ui.compose.client-e2ee-note"))}</span>
    </div>`;
  }
  const protocols = composeEncryptionProtocols();
  const protocolSelect = protocols.length > 1
    ? `<label class="compose-option"><span>${esc(t("ui.compose.protocol"))}</span><select data-compose-field="protocol">${protocols.map((protocol) => `<option value="${esc(protocol)}"${session.protocol === protocol ? " selected" : ""}>${esc(composeProtocolLabel(protocol))}</option>`).join("")}</select></label>`
    : "";
  return `<div class="compose-option compose-protection">
    <span>${esc(t("ui.compose.encryption-options"))}</span>
    <div class="compose-protection-toggles">
      <label class="compose-check"><input type="checkbox" data-compose-field="encrypt" ${session.encrypt ? "checked" : ""}>${esc(t("ui.compose.encrypt-message"))}</label>
      <label class="compose-check"><input type="checkbox" data-compose-field="sign" ${session.sign ? "checked" : ""}>${esc(t("ui.compose.sign-message"))}</label>
    </div>
    ${protocolSelect}
    <div class="compose-encryption-status" data-compose-encryption-status></div>
  </div>`;
}

