function openCompose(prefill = {}, options = {}) {
  const data = prefill || {};
  if (!options.restoring && delegatedSendBlocked()) {
    showToast(t("ui.compose-manager.this-delegated-mailbox-is-read-only"));
    return;
  }
  if (!options.restoring && isMobile()) {
    composeSessions.forEach((session) => {
      if (session.mode !== "minimized" && session.id !== options.id) {
        session.mode = "minimized";
        if (session.el) session.el.hidden = true;
      }
    });
  }
  const id = options.id || `c${++composeCounter}_${uid("draft")}`;
  const draftId = options.draftId || uid("draft");
  const hasServerDraft = Boolean(options.restoring && options.draftId && !options.localDraft);
  const activeAccountAlias = state.activeAccount && state.activeAccount.kind === "external"
    ? aliasForEmail(state.activeAccount.email)
    : null;
  const primary = activeAccountAlias && activeAccountAlias.canSend
    ? activeAccountAlias
    : (state.aliases.find((alias) => alias.id === "primary" && alias.canSend) || aliasesForSelect()[0] || { email: state.user?.email || "" });
  const isNewMessage = !options.restoring && !data.inReplyTo && !data.kind;
  const defaultAlias = activeAccountAlias && activeAccountAlias.canSend
    ? activeAccountAlias
    : (aliasForEmail(state.preferences.defaultFrom) || primary);
  const requestedFrom = data.fromEmail || (isNewMessage ? defaultAlias.email : primary.email);
  const requestedAlias = aliasForEmail(requestedFrom);
  const fromEmail = activeAccountAlias && activeAccountAlias.canSend
    ? (requestedAlias && requestedAlias.accountId === activeAccountAlias.accountId ? requestedFrom : activeAccountAlias.email)
    : (requestedAlias && requestedAlias.canSend ? requestedFrom : defaultAlias.email);
  const composeAccountId = composeAccountIdFor(fromEmail);
  const htmlMode = data.htmlMode != null ? !!data.htmlMode : state.preferences.composeMode !== "plain";
  const context = (data.kind === "reply" || data.kind === "replyAll") ? "reply" : data.kind === "forward" ? "forward" : "new";
  const signatureItem = options.restoring ? null : defaultSignatureForCompose(context, fromEmail);
  const signatureText = signatureItem ? signaturePlainValue(signatureItem) : "";
  const signatureHTML = signatureItem ? signatureRichValue(signatureItem) : "";
  const rawBodyText = data.bodyText != null && data.bodyText !== "" ? data.bodyText : "";
  const rawBodyHTML = data.bodyHtml || "";
  let bodyText = rawBodyText;
  let bodyHtml = rawBodyHTML;
  if (signatureItem && (signatureText || signatureHTML)) {
    if (!rawBodyText && !rawBodyHTML) {
      bodyText = signatureText;
      bodyHtml = signatureHTML;
    } else {
      bodyText = [signatureText, rawBodyText].filter((value) => value && value.trim()).join("\n\n");
      const signatureBlock = signatureHTML ? `<div class="a8m-signature">${signatureHTML}</div>` : "";
      bodyHtml = `${signatureBlock}${signatureBlock && (rawBodyHTML || rawBodyText) ? "<p><br></p>" : ""}${rawBodyHTML || textToEditorHTML(rawBodyText)}`;
    }
  } else if (!bodyHtml && bodyText) {
    bodyHtml = textToEditorHTML(bodyText);
  }
  const hasQuote = htmlMode && /class="compose-quote"/.test(bodyHtml);
  const session = {
    id,
    draftId,
    hasServerDraft,
    localDraft: Boolean(options.localDraft),
    to: data.toText != null ? data.toText : (data.to || ""),
    cc: data.ccText != null ? data.ccText : (data.cc || ""),
    bcc: data.bccText != null ? data.bccText : (data.bcc || ""),
    recipientInput: { to: "", cc: "", bcc: "" },
    recipientHighlight: -1,
    subject: data.subject || "",
    body: bodyText,
    bodyHtml,
    htmlMode,
    direction: ["auto", "ltr", "rtl"].includes(data.direction) ? data.direction : "auto",
    editorLight: state.editorLight,
    hasQuote,
    quoteCollapsed: false,
    fromEmail,
    accountId: composeAccountId,
    autoSignature: signatureItem ? { id: signatureItem.id, text: signatureText, html: signatureHTML } : null,
    signatureContext: context,
    priority: data.priority || state.defaultPriority,
    classification: dlpPolicy().labels.includes(data.classification) ? data.classification : dlpPolicy().defaultClassification,
    receipt: data.receipt != null ? !!data.receipt : state.defaultReceipt === true,
    delivery: !!data.delivery,
    saveCopy: data.saveCopy != null ? !!data.saveCopy : state.preferences.saveCopyEnabled !== false,
    clientSide: clientSideEncryption(),
    encrypt: clientSideEncryption() ? true : data.encrypt === true,
    sign: data.sign === true,
    protocol: clientSideEncryption() ? "openpgp" : defaultComposeProtocol(data.protocol),
    encryptionCheck: null,
    encryptionCheckSeq: 0,
    encryptionCheckTimer: null,
    files: Array.isArray(data.attachments) ? data.attachments.map((file) => ({ ...file })) : [],
    threadId: data.threadId || null,
    inReplyTo: data.inReplyTo || null,
    sourceMessageId: data.sourceMessageId || "",
    duplicateWarning: null,
    sourceAttachments: aiThreadAttachments(data.threadId, data.sourceMessageId ? messageById(data.sourceMessageId) : null),
    aiAttachmentIds: new Set(),
    aiThinking: false,
    aiThinkingMessage: "",
    toneSuggestion: null,
    toneTimer: null,
    toneStyle: "",
    mentions: mentionMapFrom(data.mentions),
    mentionMenu: null,
    mentionCtx: null,
    kind: data.kind || "",
    ccOpen: Boolean(data.ccText || data.cc || data.bccText || data.bcc),
    optionsOpen: false,
    mode: data.windowMode === "minimized" ? "minimized" : (options.mode || "floating"),
    cascade: composeSessions.length,
    manual: false,
    left: null,
    top: null,
    width: null,
    height: null,
    el: null,
    dirty: false,
    lastSavedAt: data.updatedAt || null,
    saveTimer: null,
    savingPromise: null,
    pendingSave: false,
    saveError: null,
    error: null,
    ensureDraft: options.restoring ? null : null,
    restoring: !!options.restoring
  };
  if (options.sharedDraft) session.sharedDraft = { ...options.sharedDraft, comments: Array.isArray(options.sharedDraft.comments) ? options.sharedDraft.comments : [] };
  if (options.teamInboxId) session.teamInboxId = options.teamInboxId;
  const composeTeam = composeTeamInbox(session);
  if (composeTeam) session.teamInboxId = composeTeam.id;
  composeSessions.push(session);
  composeLayer.insertAdjacentHTML("beforeend", composeTemplate(session));
  session.el = composeLayer.querySelector(`[data-compose-id="${CSS.escape(id)}"]`);
  normalizeEditorImageSources(session.el.querySelector("[data-compose-editor]"));
  updateComposeAlignmentState(session, session.el.querySelector("[data-compose-editor]"));
  updateComposeWindow(session);
  updateComposeFiles(session);
  updateComposeStatus(session);
  checkComposeDuplicateWarning(session);
  renderComposeToneChip(session);
  setTimeout(() => scheduleToneSuggestion(session), 300);
  document.body.classList.add("composing");
  setActiveCompose(id);
  updateComposeDock();
  requestAnimationFrame(() => {
    layoutComposeSessions();
    if (!options.restoring) focusComposeField(session);
    else if (session.mode !== "minimized") focusComposeField(session);
  });
  if (!options.restoring) {
    scheduleComposeSave(session, 500);
  }
  if (session.encrypt) scheduleComposeEncryptionCheck(session, 0);
  if (!state.encryptionLoaded) {
    loadEncryptionStatus().then(() => {
      if (!session.el || !sessionById(session.id)) return;
      session.clientSide = clientSideEncryption();
      if (session.clientSide) {
        session.encrypt = true;
        session.protocol = "openpgp";
      } else {
        session.protocol = defaultComposeProtocol(session.protocol);
      }
      reRenderCompose(session);
      if (session.encrypt) scheduleComposeEncryptionCheck(session, 0);
    }).catch(() => {});
  }
  return session;
}

function openMailtoCompose(href) {
  let url;
  try { url = new URL(href, window.location.href); } catch { return; }
  if (url.protocol.toLowerCase() !== "mailto:") return;
  let to = "";
  try { to = decodeURIComponent(url.pathname || "").replace(/^\/+/, "").trim(); } catch { to = String(url.pathname || "").trim(); }
  const subject = url.searchParams.get("subject") || "";
  const body = url.searchParams.get("body") || "";
  openCompose({
    to,
    toText: to,
    subject,
    bodyText: body
  });
}

function localDraftAttachments(attachments) {
  return (attachments || []).map((file) => {
    if (!file?.dataBase64) return { ...file, local: true };
    try {
      const binary = atob(String(file.dataBase64).replace(/\s+/g, ""));
      const bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0));
      const blob = new Blob([bytes], { type: file.mime || "application/octet-stream" });
      return { ...file, local: true, sizeBytes: bytes.length, size: formatBytes(bytes.length), contentUrl: URL.createObjectURL(blob) };
    } catch {
      return { ...file, local: true };
    }
  });
}

function openComposeFromDraft(draft, options = {}) {
  if (!draft) return;
  const existing = composeSessions.find((session) => session.draftId === draft.id);
  if (existing) {
    if (existing.mode === "minimized") restoreComposeSession(existing.id);
    else { setActiveCompose(existing.id); focusComposeField(existing); }
    return;
  }
  const toText = draft.toText != null ? draft.toText : (draft.to || []).map((person) => `${person.name} <${person.email}>`).join(", ");
  const ccText = draft.ccText != null ? draft.ccText : (draft.cc || []).map((person) => person.email).join(", ");
  const bccText = draft.bccText != null ? draft.bccText : (draft.bcc || []).map((person) => person.email).join(", ");
  openCompose({
    toText,
    ccText,
    bccText,
    subject: draft.subject || "",
    bodyText: draft.bodyText || "",
    bodyHtml: draft.bodyHtml || "",
    htmlMode: draft.bodyHtml ? true : undefined,
    fromEmail: draft.fromEmail || (draft.from && draft.from.email) || state.user.email,
    priority: draft.priority,
    classification: draft.classification,
    receipt: draft.receipt,
    delivery: draft.delivery,
    saveCopy: draft.saveCopy,
    encrypt: draft.cryptoEncrypt === true,
    sign: draft.cryptoSigned === true,
    protocol: draft.cryptoProtocol || "",
    attachments: draft.localDraft ? localDraftAttachments(draft.attachments) : draft.attachments,
    mentions: draft.mentions || [],
    threadId: draft.threadId,
    inReplyTo: draft.inReplyTo,
    sourceMessageId: draft.sourceMessageId || "",
    kind: draft.composeKind || "",
    windowMode: draft.windowMode || "floating",
    updatedAt: draft.updatedAt
  }, { restoring: true, draftId: draft.id, localDraft: draft.localDraft === true, id: `c_draft_${draft.id}`, mode: options.forceOpen ? "floating" : (draft.windowMode === "minimized" ? "minimized" : "floating") });
}

function restoreDraftSessions() {
  const drafts = state.messages.filter((message) => message.folder === "drafts" && message.windowMode !== "closed");
  const openIds = new Set(composeSessions.map((session) => session.draftId));
  let floating = composeSessions.filter((session) => session.mode !== "minimized").length;
  for (const draft of drafts.sort((a, b) => Date.parse(a.updatedAt || a.date) - Date.parse(b.updatedAt || b.date))) {
    if (openIds.has(draft.id)) continue;
    const session = openComposeFromDraftWithReturn(draft);
    if (session) {
      if (session.mode !== "minimized") floating += 1;
      if (floating > 1) minimizeComposeSession(session.id);
    }
  }
  updateComposeDock();
}

function openComposeFromDraftWithReturn(draft) {
  const before = composeSessions.length;
  openComposeFromDraft(draft);
  return composeSessions.length > before ? composeSessions[composeSessions.length - 1] : composeSessions.find((session) => session.draftId === draft.id) || null;
}

function updateComposeWindow(session) {
  if (!session.el) return;
  const el = session.el;
  el.hidden = session.mode === "minimized";
  el.classList.toggle("is-inline", session.mode === "inline");
  const title = el.querySelector("[data-compose-title]");
  if (title) title.textContent = session.subject.trim() || t("ui.compose-manager.new-message");
  el.querySelectorAll("[data-compose-cc]").forEach((row) => { row.hidden = !session.ccOpen; });
  const expand = el.querySelector('[data-compose-action="expand"]');
  if (expand) {
    const label = session.mode === "inline" ? t("ui.compose-manager.restore-to-floating-window") : t("ui.compose-manager.expand-into-reading-pane");
    expand.setAttribute("aria-label", label);
    expand.setAttribute("title", label);
  }
  updateComposeOptions(session);
}

function updateComposeOptions(session) {
  if (!session.el) return;
  const toggle = session.el.querySelector('[data-compose-action="options"]');
  const panel = session.el.querySelector("[data-compose-options-panel]");
  if (toggle) toggle.setAttribute("aria-expanded", session.optionsOpen ? "true" : "false");
  if (panel) panel.hidden = !session.optionsOpen;
  const chips = [];
  if (session.clientSide || clientSideEncryption()) {
    chips.push(t("ui.compose.client-e2ee"));
  } else {
    if (session.encrypt || session.sign) chips.push(composeProtocolLabel(session.protocol || defaultComposeProtocol()));
    if (session.encrypt) chips.push(t("ui.compose.encrypt-message"));
  }
  if (session.sign) chips.push(t("ui.compose.sign-message"));
  if (session.receipt) chips.push(t("ui.compose-manager.return-receipt"));
  if (session.delivery) chips.push(t("ui.compose-manager.delivery-report"));
  if (session.priority === "high") chips.push(t("ui.compose-manager.high-priority"));
  else if (session.priority === "low") chips.push(t("ui.compose-manager.low-priority"));
  const alias = aliasForEmail(session.fromEmail);
  if (alias && alias.kind !== "primary") chips.push(alias.label);
  const holder = session.el.querySelector("[data-compose-opt-chips]");
  if (holder) holder.innerHTML = chips.map((chip) => `<span>${esc(chip)}</span>`).join("");
  renderComposeEncryptionStatus(session);
  updateComposeIdentity(session);
}

function composeRecipientEmails(session) {
  const emails = [];
  for (const field of ["to", "cc", "bcc"]) {
    for (const entry of parseRecipientList(recipientTextWithPending(session, field))) {
      if (entry.valid && entry.email) emails.push(entry.email);
    }
  }
  return [...new Set(emails)];
}

function renderComposeEncryptionStatus(session) {
  if (!session?.el) return;
  const host = session.el.querySelector("[data-compose-encryption-status]");
  if (!host) return;
  const status = state.encryption;
  if (!status?.enabled) { host.innerHTML = ""; return; }
  if (session.clientSide || clientSideEncryption()) {
    renderClientComposeEncryptionStatus(session, host);
    return;
  }
  const protocol = session.protocol || defaultComposeProtocol();
  const identity = composeProtocolIdentity(protocol, status);
  const check = session.encryptionCheck;
  const missingKeyCopy = protocol === "smime" ? t("ui.compose.smime-key-required") : t("ui.compose.encryption-key-required");
  const parts = [];
  if (!identity) {
    parts.push(`<span class="compose-encryption-warning"><svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg>${esc(missingKeyCopy)}<button class="link-btn" type="button" data-open-encryption-settings>${esc(t("ui.reader.open-security-settings"))}</button></span>`);
  }
  if (session.encrypt) {
    if (!check) parts.push(`<span class="compose-encryption-note">${esc(t("ui.compose.encryption-checking"))}</span>`);
    else if (check.error) parts.push(`<span class="compose-encryption-warning"><svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg>${esc(t("ui.compose.encryption-check-failed", { error: check.error }))}</span>`);
    else if (check.missing?.length) {
      parts.push(`<span class="compose-encryption-warning"><svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg>${esc(t("ui.compose.encryption-missing-keys", { emails: check.missing.join(", ") }))}</span>`);
    }
    if (check?.changed?.length) {
      parts.push(`<span class="compose-encryption-warning"><svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg>${esc(t("ui.compose.encryption-key-changed", { emails: check.changed.join(", ") }))}</span>`);
    }
    if (check?.expired?.length) {
      parts.push(`<span class="compose-encryption-warning"><svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg>${esc(t("ui.compose.encryption-expired-keys", { emails: check.expired.join(", ") }))}</span>`);
    }
    if (check && !check.error && !check.recipients) {
      parts.push(`<span class="compose-encryption-note">${esc(t("ui.compose.encryption-add-recipient"))}</span>`);
    } else if (check && !check.error && !check.missing?.length && !check.changed?.length && !check.expired?.length && identity) {
      parts.push(`<span class="compose-encryption-ok"><svg class="icon" aria-hidden="true"><use href="#i-shield-check"/></svg>${esc(t("ui.compose.encryption-recipients-ready", { count: check.recipients || 0 }))}</span>`);
    }
  }
  if (session.encrypt || session.sign) {
    parts.push(`<span class="compose-encryption-note">${esc(protocol === "smime" ? t("ui.compose.smime-server-note") : t("ui.compose.encryption-server-note"))}</span>`);
  }
  host.innerHTML = parts.join("");
}

function scheduleComposeEncryptionCheck(session, delay = 220) {
  if (!session?.el || !state.encryption?.enabled) return;
  if (session.encryptionCheckTimer) clearTimeout(session.encryptionCheckTimer);
  session.encryptionCheckTimer = setTimeout(() => {
    session.encryptionCheckTimer = null;
    checkComposeEncryptionRecipients(session).catch(() => {});
  }, delay);
}

function renderClientComposeEncryptionStatus(session, host) {
  const protocol = clientComposeProtocol(session);
  const smime = protocol === "smime";
  const clientState = clientProtocolState(protocol);
  const published = clientPublishedIdentity(protocol);
  const parts = [];
  if (!clientState.supported) {
    parts.push(`<span class="compose-encryption-warning"><svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg>${esc(t("ui.settings.client-key-not-supported"))}</span>`);
  } else if (!clientState.identity) {
    parts.push(`<span class="compose-encryption-warning"><svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg>${esc(t(smime ? "ui.compose.client-smime-setup" : "ui.compose.client-e2ee-setup"))}<button class="link-btn" type="button" data-open-encryption-settings>${esc(t("ui.reader.open-security-settings"))}</button></span>`);
  } else if (!clientState.unlocked) {
    const unlockAction = smime ? `data-client-smime-action="unlock"` : `data-client-crypto-action="unlock"`;
    parts.push(`<span class="compose-encryption-warning"><svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg>${esc(t(smime ? "ui.compose.client-smime-locked" : "ui.compose.client-e2ee-locked"))}<button class="link-btn" type="button" ${unlockAction}>${esc(t(smime ? "ui.settings.smime-browser-unlock" : "ui.settings.unlock-browser-key"))}</button></span>`);
  } else if (!published) {
    parts.push(`<span class="compose-encryption-warning"><svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg>${esc(t(smime ? "ui.settings.smime-browser-not-published" : "ui.settings.client-key-not-published"))}<button class="link-btn" type="button" data-open-encryption-settings>${esc(t("ui.reader.open-security-settings"))}</button></span>`);
  } else if (published.fingerprint !== clientState.identity.fingerprint) {
    parts.push(`<span class="compose-encryption-warning"><svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg>${esc(t(smime ? "ui.settings.smime-browser-mismatch" : "ui.settings.client-key-mismatch"))}<button class="link-btn" type="button" data-open-encryption-settings>${esc(t("ui.reader.open-security-settings"))}</button></span>`);
  }
  if (session.files?.some((file) => !file.local)) {
    parts.push(`<span class="compose-encryption-warning"><svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg>${esc(t("ui.compose.client-e2ee-server-attachment"))}</span>`);
  } else if (session.files?.length) {
    parts.push(`<span class="compose-encryption-note">${esc(t("ui.compose.client-e2ee-attachment-note", { count: session.files.length, limit: formatBytes(clientAttachmentLimits().totalBytes) }))}</span>`);
  }
  const check = session.encryptionCheck;
  if (!check) parts.push(`<span class="compose-encryption-note">${esc(t("ui.compose.encryption-checking"))}</span>`);
  else if (check.directoryChanged?.length) {
    const emails = check.directoryChanged.map((item) => item.email);
    parts.push(`<span class="compose-encryption-warning"><svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg>${esc(t("ui.compose.client-e2ee-directory-key-changed", { emails: emails.join(", ") }))}${emails.map((email) => `<button class="link-btn" type="button" data-client-directory-review="${esc(email)}">${esc(t("ui.compose.client-e2ee-directory-key-review"))}</button>`).join("")}</span>`);
  } else if (check.missing?.length) {
    parts.push(`<span class="compose-encryption-warning"><svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg>${esc(t("ui.compose.encryption-missing-keys", { emails: check.missing.join(", ") }))}</span>`);
  } else if (!check.recipients) {
    parts.push(`<span class="compose-encryption-note">${esc(t("ui.compose.encryption-add-recipient"))}</span>`);
  } else {
    parts.push(`<span class="compose-encryption-ok"><svg class="icon" aria-hidden="true"><use href="#i-shield-check"/></svg>${esc(t("ui.compose.client-e2ee-recipients"))}</span>`);
  }
  host.innerHTML = parts.join("");
}

async function checkClientComposeRecipients(session) {
  const emails = composeRecipientEmails(session);
  const seq = ++session.encryptionCheckSeq;
  if (!emails.length) {
    session.encryptionCheck = { recipients: 0, missing: [], checked: true };
    renderComposeEncryptionStatus(session);
    return;
  }
  let keys;
  try {
    keys = clientComposeProtocol(session) === "smime"
      ? await resolveSMIMERecipientCertificates(emails)
      : await resolveClientRecipientKeys(emails);
  } catch (error) {
    if (seq !== session.encryptionCheckSeq || !sessionById(session.id)) return;
    if (error.code === "DIRECTORY_KEY_CHANGED") {
      session.encryptionCheck = {
        recipients: 0, missing: [], changed: [], expired: [],
        directoryChanged: error.changes || [], checked: true
      };
      renderComposeEncryptionStatus(session);
      return;
    }
    throw error;
  }
  if (seq !== session.encryptionCheckSeq || !sessionById(session.id)) return;
  const missing = emails.filter((email) => !keys.has(email));
  session.encryptionCheck = { recipients: emails.length - missing.length, missing, changed: [], expired: [], checked: true };
  renderComposeEncryptionStatus(session);
}

async function reviewDirectoryKeyChange(session, email) {
  const change = (session?.encryptionCheck?.directoryChanged || []).find((item) => item.email === email);
  if (!change) return;
  const accepted = await appConfirm({
    title: t("ui.compose.client-e2ee-directory-key-title"),
    message: t("ui.compose.client-e2ee-directory-fingerprint", {
      previous: encryptionFingerprintDisplay(change.previousFingerprint),
      current: encryptionFingerprintDisplay(change.fingerprint)
    }),
    confirmLabel: t("ui.compose.client-e2ee-directory-key-review"),
    tone: "warning",
    icon: "i-alert"
  });
  if (!accepted) return;
  if (clientComposeProtocol(session) === "smime") await pinSMIMEDirectoryKey(email, change.fingerprint);
  else await pinDirectoryKey(email, change.fingerprint);
  await checkClientComposeRecipients(session);
  showToast(t("ui.compose.client-e2ee-directory-key-accepted"));
}

async function checkComposeEncryptionRecipients(session) {
  if (!session || !sessionById(session.id)) return;
  if (!state.encryption?.enabled) {
    session.encryptionCheck = null;
    renderComposeEncryptionStatus(session);
    return;
  }
  if (session.clientSide || clientSideEncryption()) {
    try {
      await checkClientComposeRecipients(session);
    } catch (error) {
      session.encryptionCheck = { recipients: 0, missing: [], error: error.message, checked: true };
      renderComposeEncryptionStatus(session);
    }
    return;
  }
  const emails = composeRecipientEmails(session);
  if (!session.encrypt) {
    session.encryptionCheck = null;
    renderComposeEncryptionStatus(session);
    return;
  }
  if (!emails.length) {
    session.encryptionCheck = { recipients: 0, missing: [], changed: [], checked: true };
    renderComposeEncryptionStatus(session);
    return;
  }
  const seq = ++session.encryptionCheckSeq;
  try {
    const protocol = session.protocol || defaultComposeProtocol();
    const data = await api(`/api/encryption/recipients?protocol=${encodeURIComponent(protocol)}&emails=${encodeURIComponent(emails.join(","))}`);
    if (seq !== session.encryptionCheckSeq || !sessionById(session.id)) return;
    const recipients = data?.recipients || {};
    const missing = [];
    const changed = [];
    const expired = [];
    let found = 0;
    const now = Date.now();
    for (const email of emails) {
      const keys = Array.isArray(recipients[email]) ? recipients[email] : [];
      if (!keys.length) { missing.push(email); continue; }
      const valid = keys.filter((key) => !key.notAfter || Date.parse(key.notAfter) > now);
      if (!valid.length) { expired.push(email); continue; }
      found += 1;
      const changedKey = valid.some((key) => key.keyChangedAt && !["verified", "enterprise"].includes(key.trust));
      if (changedKey) changed.push(email);
    }
    session.encryptionCheck = { recipients: found, missing, changed, expired, checked: true };
    renderComposeEncryptionStatus(session);
  } catch (error) {
    session.encryptionCheck = { recipients: 0, missing: [], changed: [], error: error.message, checked: true };
    renderComposeEncryptionStatus(session);
  }
}

function updateComposeIdentity(session) {
  if (!session?.el) return;
  const identity = session.el.querySelector("[data-compose-identity]");
  if (identity) {
    identity.textContent = aliasDisplay(session.fromEmail);
    identity.title = t("ui.compose-manager.sending-as", { email: session.fromEmail });
  }
}

function composeAttachmentPreviewKind(file) {
  const mime = String(file?.mime || "").toLowerCase();
  const name = String(file?.name || "");
  if (mime === "application/pdf" || /\.pdf$/i.test(name)) return "pdf";
  if (mime.startsWith("image/") || /\.(png|jpe?g|gif|webp|svg)$/i.test(name)) return "image";
  return "";
}

function openComposeAttachment(session, index) {
  const file = session?.files?.[Number(index)];
  if (!session || !file) return;
  if (composeAttachmentPreviewKind(file)) {
    const previewFiles = session.files.filter((item) => composeAttachmentPreviewKind(item));
    const previewIndex = previewFiles.findIndex((item) =>
      file.id ? item.id === file.id : item.name === file.name && item.sizeBytes === file.sizeBytes
    );
    openPreview(file, { files: previewFiles, index: previewIndex < 0 ? 0 : previewIndex });
    return;
  }
  if (state.office?.ready && file.id && officeMetaForName(file.name)) {
    editComposeAttachmentInOffice(session.id, Number(index)).catch(showError);
    return;
  }
  openComposeAttach(session.id);
}

function composeFileCard(file, index, sessionId = "") {
  const preview = index != null && Boolean(composeAttachmentPreviewKind(file));
  const office = index != null && !preview && state.office.ready && file.id && officeMetaForName(file.name);
  const title = office ? t("ui.compose-manager.open-in-office-title", { name: file.name || t("ui.compose-manager.attachment") }) : preview ? t("ui.compose-manager.preview-file-title", { name: file.name || t("ui.compose-manager.attachment") }) : t("ui.compose-manager.manage-attachments");
  return `<div class="compose-file-card${preview ? " is-previewable" : ""}" data-compose-file-index="${index ?? ""}" role="button" tabindex="0" title="${esc(title)}" aria-label="${esc(title)}">
    <span class="file-art"><svg class="icon" aria-hidden="true"><use href="#i-file"/></svg></span>
    <span class="file-copy"><strong>${esc(file.name || t("ui.mail-home-pulse-search-reports-sticky-no.attachment"))}</strong><span>${esc(file.mime || file.type || t("ui.mail-home-pulse-search-reports-sticky-no.file"))} · ${esc(file.size || formatBytes(file.sizeBytes))}</span></span>
    <span class="file-card-actions">
      ${office ? `<button class="file-office" data-compose-office="${index}" data-compose-office-session="${esc(sessionId)}" type="button" title="${esc(t("ui.compose-manager.edit-in-office"))}" aria-label="${esc(t("ui.compose-manager.edit-attachment-in-office", { name: file.name || t("ui.compose-manager.attachment") }))}"><svg class="icon" aria-hidden="true"><use href="#i-file"/></svg></button>` : ""}
      ${index == null ? "" : `<button class="file-remove" data-compose-remove="${index}" type="button" aria-label="${esc(t("ui.thread-selection-actions.remove-name", { name: file.name || t("ui.compose-manager.attachment") }))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button>`}
    </span>
  </div>`;
}

function updateComposeFiles(session) {
  if (!session.el) return;
  const box = session.el.querySelector("[data-compose-files]");
  if (!box) return;
  box.className = session.files.length ? "compose-file-grid" : "compose-files";
  box.innerHTML = session.files.map((file, index) => composeFileCard(file, index, session.id)).join("");
}

function toggleComposeQuote(session) {
  if (!session?.el || !session.hasQuote) return;
  session.quoteCollapsed = !session.quoteCollapsed;
  const editor = session.el.querySelector("[data-compose-editor]");
  if (editor) editor.classList.toggle("is-quote-collapsed", session.quoteCollapsed);
  const button = session.el.querySelector('[data-compose-action="toggle-quote"]');
  if (button) {
    button.classList.toggle("is-active", session.quoteCollapsed);
    button.setAttribute("aria-pressed", session.quoteCollapsed ? "true" : "false");
    button.title = session.quoteCollapsed ? t("ui.compose-manager.show-quoted-message") : t("ui.compose-manager.hide-quoted-message");
  }
}

function reRenderCompose(session) {
  if (!session?.el) return;
  const wrapper = document.createElement("div");
  wrapper.innerHTML = composeTemplate(session);
  const next = wrapper.firstElementChild;
  if (!next) return;
  session.el.replaceWith(next);
  session.el = next;
  normalizeEditorImageSources(next.querySelector("[data-compose-editor]"));
  if (session.quoteCollapsed) next.querySelector("[data-compose-editor]")?.classList.add("is-quote-collapsed");
  updateComposeWindow(session);
  updateComposeFiles(session);
  updateComposeStatus(session);
  updateComposeOptions(session);
  for (const field of RECIPIENT_FIELDS) updateRecipientField(session, field);
  layoutComposeSessions();
  const aiPanel = session.el.querySelector("[data-compose-ai-panel]");
  if (aiPanel) aiPanel.hidden = !session.aiOpen;
  if (session.aiOpen) renderComposeAiPanel(session);
}

function setComposeMode(session, mode) {
  if (!session?.el) return;
  const htmlMode = mode !== "plain";
  if (session.htmlMode === htmlMode) return;
  const editor = session.el.querySelector("[data-compose-editor]");
  const textarea = session.el.querySelector('[data-compose-field="body"]');
  if (editor) {
    session.bodyHtml = sanitizeEditorHTML(editor.innerHTML);
    session.body = editorPlainText(editor.innerHTML);
  } else if (textarea) {
    session.body = textarea.value;
  }
  session.htmlMode = htmlMode;
  session.bodyHtml = textToEditorHTML(session.body);
  session.dirty = true;
  reRenderCompose(session);
  scheduleComposeSave(session);
}

function restoreComposeEditorSelection(session, editor) {
  if (!session || !editor) return;
  const selection = window.getSelection();
  const selectionInside = Boolean(selection && selection.rangeCount && editor.contains(selection.anchorNode));
  editor.focus();
  if (selectionInside || !selection) return;
  const range = session.editorRange;
  if (!range || !editor.contains(range.commonAncestorContainer)) return;
  selection.removeAllRanges();
  selection.addRange(range);
}

function rememberComposeEditorSelection(session, editor) {
  if (!session || !editor) return;
  const selection = window.getSelection();
  if (!selection || !selection.rangeCount) return;
  if (!editor.contains(selection.anchorNode)) return;
  session.editorRange = selection.getRangeAt(0).cloneRange();
}

function normalizeEditorFontTags(editor, explicitSize = "") {
  if (!editor) return;
  for (const font of Array.from(editor.querySelectorAll("font"))) {
    const span = document.createElement("span");
    const face = font.getAttribute("face");
    const size = font.getAttribute("size");
    if (face) span.style.fontFamily = face;
    if (explicitSize) {
      if (size === "7" || !size) span.style.fontSize = `${explicitSize}px`;
    } else if (size) {
      const legacy = { 1: "10px", 2: "13px", 3: "16px", 4: "18px", 5: "24px", 6: "32px", 7: "48px" };
      if (legacy[size]) span.style.fontSize = legacy[size];
    }
    while (font.firstChild) span.appendChild(font.firstChild);
    font.replaceWith(span);
  }
}

function applyComposeFontFamily(session, family) {
  if (!session?.el || !family) return;
  const editor = session.el.querySelector("[data-compose-editor]");
  if (!editor) return;
  applyRichFontFamily(editor, family);
  normalizeEditorFontTags(editor);
  updateComposeEditor(session, editor);
  rememberComposeEditorSelection(session, editor);
}

function applyComposeFontSize(session, pixels) {
  if (!session?.el || !pixels) return;
  const editor = session.el.querySelector("[data-compose-editor]");
  if (!editor) return;
  applyRichFontSize(editor, pixels);
  normalizeEditorFontTags(editor);
  updateComposeEditor(session, editor);
  rememberComposeEditorSelection(session, editor);
}

function applyComposeHighlight(session, color) {
  if (!session?.el || !color) return;
  const editor = session.el.querySelector("[data-compose-editor]");
  if (!editor) return;
  restoreComposeEditorSelection(session, editor);
  try { document.execCommand("styleWithCSS", false, true); } catch {}
  document.execCommand("hiliteColor", false, color);
  updateComposeEditor(session, editor);
  rememberComposeEditorSelection(session, editor);
}

function updateComposeAlignmentState(session, editor = null) {
  const target = editor || session?.el?.querySelector("[data-compose-editor]");
  if (!session?.el || !target) return;
  let left = false, center = false, right = false, full = false;
  try {
    left = document.queryCommandState("justifyLeft");
    center = document.queryCommandState("justifyCenter");
    right = document.queryCommandState("justifyRight");
    full = document.queryCommandState("justifyFull");
  } catch {}
  if (!center && !right && !full) left = true;
  const active = { justifyLeft: left, justifyCenter: center, justifyRight: right, justifyFull: full };
  session.el.querySelectorAll("[data-editor-cmd^='justify']").forEach((button) => {
    const isActive = Boolean(active[button.getAttribute("data-editor-cmd")]);
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-pressed", isActive ? "true" : "false");
  });
}

async function applyComposeEditorCommand(session, command, value = null, options = {}) {
  if (!session?.el) return;
  const editor = session.el.querySelector("[data-compose-editor]");
  if (!editor) return;
  restoreComposeEditorSelection(session, editor);
  try { document.execCommand("styleWithCSS", false, true); } catch {}
  if (command === "createLink") {
    const href = await appPrompt({
      eyebrow: t("ui.mail-home-pulse-search-reports-sticky-no.compose"),
      title: t("ui.compose-manager.insert-link"),
      label: t("ui.compose-manager.link-url"),
      value: "https://",
      placeholder: "https://example.com",
      type: "url",
      confirmLabel: t("ui.compose-manager.insert-link"),
      validate: (value) => /^(https?:\/\/|mailto:)/i.test(value) ? "" : t("ui.compose-manager.links-must-start-with-https-http-or-mailto")
    });
    if (!href) return;
    document.execCommand("createLink", false, href.trim());
  } else if (command === "formatBlock") {
    document.execCommand("formatBlock", false, value || "p");
  } else if (command === "removeFormat") {
    document.execCommand("removeFormat", false, null);
  } else {
    document.execCommand(command, false, value);
  }
  normalizeEditorFontTags(editor);
  updateComposeEditor(session, editor);
  updateComposeAlignmentState(session, editor);
  if (!options.keepFocus) {
    editor.focus();
    rememberComposeEditorSelection(session, editor);
  }
}

function localizedAiLanguageName(code, fallback) {
  try {
    const [language, region] = String(code || "").split("-");
    const languages = new Intl.DisplayNames([currentLocale()], { type: "language" });
    const base = languages.of(language) || fallback;
    if (!region) return base;
    const regions = new Intl.DisplayNames([currentLocale()], { type: "region" });
    return `${base} (${regions.of(region) || region})`;
  } catch {
    return fallback;
  }
}

