function toggleComposeAi(session) {
  if (!session?.el) return;
  session.aiOpen = !session.aiOpen;
  const panel = session.el.querySelector("[data-compose-ai-panel]");
  if (!panel) return;
  panel.hidden = !session.aiOpen;
  if (session.aiOpen) renderComposeAiPanel(session);
}

function composeAiSelectedFiles(session) {
  const selected = session?.aiAttachmentIds instanceof Set ? session.aiAttachmentIds : new Set();
  return (session?.sourceAttachments || []).filter((file) => selected.has(file.id));
}

function composeAiAttachmentPanelMarkup(session) {
  const files = session?.sourceAttachments || [];
  if (!files.length) return "";
  const selected = session.aiAttachmentIds instanceof Set ? session.aiAttachmentIds : new Set();
  const total = aiAttachmentTotal(files, selected);
  const over = total > AI_CONTEXT_LIMIT_BYTES;
  const selectable = files.filter((file) => aiAttachmentSizeBytes(file) <= AI_CONTEXT_LIMIT_BYTES);
  const allSelected = selectable.length > 0 && selected.size === selectable.length;
  return `<div class="compose-ai-attachments">
    <div class="compose-ai-attachments-head"><div><strong>${t("ui.compose-manager.attachments-from-this-email")}</strong><span>${t("ui.compose-manager.add-supporting-documents-to-ground-the-draft")}</span></div><label class="compose-ai-select-all"><input type="checkbox" data-ai-compose-select-all ${allSelected ? "checked" : ""}>${t("ui.compose-manager.select-all")}</label></div>
    <div class="compose-ai-attachment-list">${files.map((file) => {
      const size = aiAttachmentSizeBytes(file);
      const tooLarge = size > AI_CONTEXT_LIMIT_BYTES;
      const kind = aiAttachmentKind(file);
      return `<label class="compose-ai-attachment${selected.has(file.id) ? " is-selected" : ""}${tooLarge ? " is-too-large" : ""}">
        <input type="checkbox" data-ai-compose-attachment="${esc(file.id)}" ${selected.has(file.id) ? "checked" : ""} ${tooLarge ? "disabled" : ""}>
        <span class="compose-ai-attachment-mark" data-kind="${esc(kind.toLowerCase())}" aria-hidden="true">${esc(kind)}</span>
        <span class="compose-ai-attachment-copy"><strong>${esc(file.name || t("ui.mail-home-pulse-search-reports-sticky-no.attachment"))}</strong><span>${esc(kind)} · ${esc(file.size || formatBytes(size))}</span></span>
        <span class="compose-ai-attachment-tick" aria-hidden="true"><svg class="icon"><use href="#i-check"/></svg></span>
      </label>`;
    }).join("")}</div>
    <div class="compose-ai-attachment-budget${over ? " is-over" : ""}" data-ai-attachment-budget>${selected.size ? esc(tn("ui.compose-manager.selected-budget", selected.size, { count: selected.size, size: formatBytes(total) })) : t("ui.compose-manager.no-attachments-selected")}</div>
  </div>`;
}

function updateComposeAiAttachmentSelection(session) {
  const panel = session?.el?.querySelector("[data-compose-ai-panel]");
  if (!panel) return;
  const selected = session.aiAttachmentIds instanceof Set ? session.aiAttachmentIds : new Set();
  const files = session.sourceAttachments || [];
  const total = aiAttachmentTotal(files, selected);
  const over = total > AI_CONTEXT_LIMIT_BYTES;
  panel.querySelectorAll("[data-ai-compose-attachment]").forEach((input) => {
    input.checked = selected.has(input.getAttribute("data-ai-compose-attachment"));
    input.closest(".compose-ai-attachment")?.classList.toggle("is-selected", input.checked);
  });
  const selectable = files.filter((file) => aiAttachmentSizeBytes(file) <= AI_CONTEXT_LIMIT_BYTES);
  const selectAll = panel.querySelector("[data-ai-compose-select-all]");
  if (selectAll) {
    selectAll.checked = selectable.length > 0 && selected.size === selectable.length;
    selectAll.indeterminate = selected.size > 0 && selected.size < selectable.length;
  }
  const budget = panel.querySelector("[data-ai-attachment-budget]");
  if (budget) {
    budget.textContent = selected.size
      ? over
        ? esc(tn("ui.compose-manager.selected-budget-exceeds", selected.size, { count: selected.size, size: formatBytes(total) }))
        : esc(tn("ui.compose-manager.selected-budget", selected.size, { count: selected.size, size: formatBytes(total) }))
      : t("ui.compose-manager.no-attachments-selected");
    budget.classList.toggle("is-over", over);
  }
  const generate = panel.querySelector("[data-ai-compose-generate]");
  if (generate) generate.disabled = Boolean(session.aiGenerating) || over;
}

function renderComposeAiPanel(session) {
  const panel = session?.el?.querySelector("[data-compose-ai-panel]");
  if (!panel || !state.ai.enabled) return;
  const languages = composeAiLanguages();
  const styles = composeAiStyles();
  const preferredLanguage = languages.some((item) => item.code === state.preferences.language) ? state.preferences.language : "en-US";
  const selectedAttachmentCount = session.aiAttachmentIds instanceof Set ? session.aiAttachmentIds.size : 0;
  const attachmentTotal = aiAttachmentTotal(session.sourceAttachments || [], session.aiAttachmentIds);
  const attachmentOverLimit = attachmentTotal > AI_CONTEXT_LIMIT_BYTES;
  panel.innerHTML = `<div class="compose-ai-head"><svg class="icon" aria-hidden="true"><use href="#i-sparkles"/></svg><strong>${t("ui.compose-manager.ai-writing-assistant")}</strong><button class="icon-btn" data-ai-compose-close type="button" aria-label="${esc(t("ui.compose-manager.close-ai-assistant"))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button></div>
    <div class="compose-ai-grid">
      <label>${t("ui.compose-manager.style")}<select data-ai-style>${styles.map((item) => `<option value="${esc(item.code)}" ${item.code === (session.toneStyle || "professional") ? "selected" : ""}>${esc(item.name)}</option>`).join("")}</select></label>
      <label>${t("ui.compose-manager.length")}<select data-ai-length><option value="short">${t("ui.compose-manager.short")}</option><option value="medium" selected>${t("ui.compose-manager.medium")}</option><option value="long">${t("ui.compose-manager.long")}</option></select></label>
      <label>${t("settings.language")}<select data-ai-language>${languages.map((item) => `<option value="${esc(item.code)}" ${item.code === preferredLanguage ? "selected" : ""}>${esc(item.name)}</option>`).join("")}</select></label>
      <label>${t("ui.compose-manager.creativity")}<div class="compose-ai-range"><input type="range" min="0" max="100" value="50" data-ai-creativity><span data-ai-creativity-value>50</span></div></label>
      <label class="compose-ai-prompt">${t("ui.compose-manager.instruction")} <small class="muted">${t("ui.compose-manager.optional")}</small><textarea data-ai-prompt placeholder="${esc(t("ui.compose-manager.e-g-follow-up-on-the-launch-timeline-and-ask-for"))}"></textarea></label>
    </div>
    ${composeAiAttachmentPanelMarkup(session)}
    <div class="compose-ai-actions"><button class="btn-primary small" data-ai-compose-generate type="button" ${attachmentOverLimit ? "disabled" : ""}><svg class="icon" aria-hidden="true"><use href="#i-sparkles"/></svg>${t("ui.compose-manager.generate-draft")}</button><span class="settings-note" data-ai-status>${session.aiResult ? t("ui.compose-manager.draft-ready") : (selectedAttachmentCount ? `${esc(tn("ui.compose-manager.attachments-selected-as-context", selectedAttachmentCount, { count: selectedAttachmentCount }))}` : t("ui.compose-manager.uses-this-message-s-current-text-as-context"))}</span></div>
    <div class="compose-ai-result" data-ai-result ${session.aiResult ? "" : "hidden"}>${esc(session.aiResult || "")}</div>
    <div class="compose-ai-actions" data-ai-result-actions ${session.aiResult ? "" : "hidden"}><button class="btn-secondary small" data-ai-compose-insert type="button">${t("ui.compose-manager.insert-below")}</button><button class="btn-secondary small" data-ai-compose-replace type="button">${t("ui.compose-manager.replace-body")}</button></div>`;
  const range = panel.querySelector("[data-ai-creativity]");
  range?.addEventListener("input", () => {
    const value = panel.querySelector("[data-ai-creativity-value]");
    if (value) value.textContent = range.value;
  });
}

async function composeAiGenerate(session) {
  const panel = session?.el?.querySelector("[data-compose-ai-panel]");
  if (!panel) return;
  const editor = session.el.querySelector("[data-compose-editor]");
  const textarea = session.el.querySelector('[data-compose-field="body"]');
  const text = editor ? editorPlainText(editor.innerHTML) : (textarea?.value || session.body || "");
  const status = panel.querySelector("[data-ai-status]");
  const button = panel.querySelector("[data-ai-compose-generate]");
  const selectedFiles = composeAiSelectedFiles(session);
  const attachmentTotal = aiAttachmentTotal(selectedFiles);
  if (attachmentTotal > AI_CONTEXT_LIMIT_BYTES) {
    if (status) status.textContent = t("ui.compose-manager.remove-an-attachment-to-stay-within-the-100-mb-l");
    return;
  }
  session.aiGenerating = true;
  setComposeAiThinking(session, true, t("ui.compose-manager.ai-is-writing-your-draft"));
  if (button) button.disabled = true;
  if (status) status.textContent = t("ui.compose-manager.generating");
  try {
    const data = await api("/api/ai/compose", {
      method: "POST",
      body: {
        text,
        prompt: panel.querySelector("[data-ai-prompt]")?.value || "",
        style: panel.querySelector("[data-ai-style]")?.value || "professional",
        length: panel.querySelector("[data-ai-length]")?.value || "medium",
        creativity: Number(panel.querySelector("[data-ai-creativity]")?.value || 50) / 100,
        language: panel.querySelector("[data-ai-language]")?.value || "en-US",
        attachmentIds: selectedFiles.map((file) => file.id),
        sourceMessageId: session.sourceMessageId || ""
      }
    });
    session.aiResult = data.text || "";
    if (status) status.textContent = `${data.style || "professional"} · ${data.length || "medium"} · ${data.language || "en-US"}${selectedFiles.length ? ` · ${selectedFiles.length} attachment${selectedFiles.length === 1 ? "" : "s"}` : ""}`;
    const result = panel.querySelector("[data-ai-result]");
    if (result) { result.hidden = false; result.textContent = session.aiResult; }
    const actions = panel.querySelector("[data-ai-result-actions]");
    if (actions) actions.hidden = false;
  } catch (error) {
    if (status) status.textContent = error.message || t("ui.compose-manager.ai-generation-failed");
    showError(error);
  } finally {
    session.aiGenerating = false;
    setComposeAiThinking(session, false);
    if (button) button.disabled = aiAttachmentTotal(composeAiSelectedFiles(session)) > AI_CONTEXT_LIMIT_BYTES;
  }
}

function applyComposeAiResult(session, replace) {
  if (!session?.aiResult) return;
  const html = textToEditorHTML(session.aiResult);
  if (session.htmlMode) {
    const editor = session.el.querySelector("[data-compose-editor]");
    if (!editor) return;
    if (replace) editor.innerHTML = html;
    else {
      editor.focus();
      const selection = window.getSelection();
      if (selection && selection.rangeCount && editor.contains(selection.anchorNode)) document.execCommand("insertHTML", false, html);
      else editor.insertAdjacentHTML("beforeend", html);
    }
    updateComposeEditor(session, editor);
  } else {
    const textarea = session.el.querySelector('[data-compose-field="body"]');
    if (!textarea) return;
    textarea.value = replace ? session.aiResult : `${textarea.value}${textarea.value ? "\n\n" : ""}${session.aiResult}`;
    session.body = textarea.value;
    session.bodyHtml = textToEditorHTML(textarea.value);
    session.dirty = true;
    scheduleComposeSave(session);
  }
  showToast(replace ? t("ui.compose-manager.draft-replaced-with-ai-text") : t("ui.compose-manager.ai-draft-inserted"));
}

/* ---------- compose attachment picker ---------- */
function openComposeAttach(sessionId) {
  const session = sessionById(sessionId);
  if (!session) return;
  attachPickerSessionId = sessionId;
  state.composeAttachProvider = storageDefaultId();
  composeAttachOverlay.hidden = false;
  const limit = document.getElementById("composeAttachLimit");
  if (limit) {
    const limits = composeAttachmentLimits();
    limit.textContent = `${formatBytes(limits.perFile)} each · ${formatBytes(limits.total)} total`;
  }
  renderComposeAttachPicker();
}

function closeComposeAttach() {
  composeAttachOverlay.hidden = true;
  attachPickerSessionId = null;
}

function refreshAttachPickerIfOpen() {
  if (!composeAttachOverlay.hidden) renderComposeAttachPicker();
}

function renderComposeAttachPicker() {
  const session = sessionById(attachPickerSessionId);
  if (!session) { closeComposeAttach(); return; }
  const current = composeAttachCurrentList;
  if (current) {
    current.innerHTML = session.files.length ? session.files.map((file, index) => composeFileCard(file, index, attachPickerSessionId)).join("") : "<div class=\"settings-note\">" + t("ui.compose-manager.no-attachments-yet") + "</div>";
  }
  if (composeAttachCurrentCount) composeAttachCurrentCount.textContent = `${session.files.length} file${session.files.length === 1 ? "" : "s"}`;
  if (!composeAttachFileList) return;
  const files = (state.files || []).filter((file) => !file.folder || file.kind !== "folder").slice().sort((a, b) => Date.parse(b.modifiedAt || b.updatedAt || b.date || 0) - Date.parse(a.modifiedAt || a.updatedAt || a.date || 0));
  if (composeAttachFileCount) composeAttachFileCount.textContent = `${files.length} file${files.length === 1 ? "" : "s"} available`;
  composeAttachFileList.innerHTML = files.length ? files.map((file) => `<button class="compose-attach-pick" type="button" data-attach-file="${esc(file.id)}">
    <span class="file-art"><svg class="icon" aria-hidden="true"><use href="#i-file"/></svg></span>
    <span class="file-copy"><strong>${esc(file.name || t("ui.mail-home-pulse-search-reports-sticky-no.file"))}</strong><span>${esc(file.providerLabel || file.providerId || file.provider || t("ui.compose-manager.files"))} · ${esc(formatBytes(file.sizeBytes || 0))}</span></span>
    <span class="file-add">${t("ui.compose-manager.attach")}</span>
  </button>`).join("") : "<div class=\"settings-note\">" + t("ui.compose-manager.no-files-in-your-workspace-yet-upload-one-from-t") + "</div>";
}

function setComposeUploadProgress(percent, label, scanning = false) {
  const box = document.getElementById("composeUploadProgress");
  if (!box) return;
  if (composeUploadHideTimer) {
    clearTimeout(composeUploadHideTimer);
    composeUploadHideTimer = null;
  }
  box.hidden = false;
  const clamped = Math.max(0, Math.min(100, Number(percent) || 0));
  const bar = document.getElementById("composeUploadBar");
  const track = document.getElementById("composeUploadTrack");
  const percentLabel = document.getElementById("composeUploadPercent");
  const text = document.getElementById("composeUploadLabel");
  if (bar) bar.style.width = `${clamped}%`;
  if (track) track.setAttribute("aria-valuenow", String(Math.round(clamped)));
  if (percentLabel) percentLabel.textContent = `${Math.round(clamped)}%`;
  if (text) text.textContent = label || t("ui.compose-manager.uploading");
  box.classList.toggle("is-scanning", Boolean(scanning));
}

function finishComposeUploadProgress() {
  const box = document.getElementById("composeUploadProgress");
  if (!box) return;
  setComposeUploadProgress(100, t("ui.compose-manager.upload-complete"));
  composeUploadHideTimer = setTimeout(() => {
    box.hidden = true;
    box.classList.remove("is-scanning");
    composeUploadHideTimer = null;
  }, 900);
}

function uploadAttachmentWithProgress(file, dataBase64, hooks = {}) {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open("POST", "/api/attachments");
    xhr.withCredentials = true;
    xhr.timeout = 120000;
    xhr.setRequestHeader(t("ui.calendar.accept"), "application/json");
    xhr.setRequestHeader(t("ui.compose-manager.content-type"), "application/json");
    if (!state.delegatedMode && state.activeAccountId) xhr.setRequestHeader(t("ui.compose-manager.x-a8m-account"), state.activeAccountId);
    const delegatedSession = state.delegatedSession;
    if (delegatedSession?.token) xhr.setRequestHeader(DELEGATED_SESSION_HEADER, delegatedSession.token);
    const csrf = delegatedSession?.csrf || state.csrf;
    if (csrf) xhr.setRequestHeader(t("ui.compose-manager.x-csrf-token"), csrf);
    xhr.upload.addEventListener("progress", (event) => {
      if (event.lengthComputable && hooks.onProgress) hooks.onProgress(event.loaded / event.total);
    });
    xhr.upload.addEventListener("load", () => {
      if (hooks.onUploaded) hooks.onUploaded();
    });
    xhr.addEventListener("load", () => {
      setOffline(false);
      let payload = null;
      try { payload = xhr.responseText ? JSON.parse(xhr.responseText) : null; } catch { payload = null; }
      if (xhr.status >= 200 && xhr.status < 300) {
        resolve(payload);
        return;
      }
      if (xhr.status === 401) {
        if (state.delegatedMode) {
          const revoked = payload && payload.error ? payload.error.message : "";
          expireDelegatedWindow(revoked || t("ui.auth-boot.delegated-session-ended"));
        } else {
          handleSessionExpired();
        }
      }
      const detail = payload && payload.error ? payload.error : {};
      reject(new ApiFailure(xhr.status, detail.code || `HTTP_${xhr.status}`,
        detail.message || t("ui.compose-manager.upload-failed-status", { status: xhr.status }), detail.details || null));
    });
    xhr.addEventListener("error", () => {
      setOffline(true);
      reject(new ApiFailure(0, "NETWORK", t("ui.auth-boot.network-unreachable")));
    });
    xhr.addEventListener("timeout", () => {
      reject(new ApiFailure(0, "TIMEOUT", t("ui.auth-boot.upload-timed-out")));
    });
    xhr.send(JSON.stringify({
      name: file.name,
      mime: file.type || "application/octet-stream",
      dataBase64
    }));
  });
}

function composeAttachmentLimits() {
  return {
    perFile: Math.min(Number(state.attachmentMaxBytes) || 25 * 1024 * 1024, 25 * 1024 * 1024),
    total: Math.min(Number(state.composeAttachmentTotalBytes) || 30 * 1024 * 1024, 30 * 1024 * 1024)
  };
}

function composeAttachmentBytes(session) {
  return (session?.files || []).reduce((sum, file) => sum + Math.max(0, Number(file.sizeBytes) || 0), 0);
}

let composeShareReturnFocus = null;

function syncComposeShareDays(value) {
  const days = Number(value) || 0;
  document.querySelectorAll("[data-compose-share-days]").forEach((chip) => {
    const active = Number(chip.getAttribute("data-compose-share-days")) === days;
    chip.classList.toggle("is-active", active);
    chip.setAttribute("aria-pressed", active ? "true" : "false");
  });
}

function syncComposeSharePrivacy(focusRecipient = false) {
  const privacy = document.querySelector("input[name='composeSharePrivacy']:checked")?.value || "public";
  document.querySelectorAll("[data-compose-share-choice]").forEach((choice) => {
    choice.classList.toggle("is-active", choice.getAttribute("data-compose-share-choice") === privacy);
  });
  const wrap = document.getElementById("composeShareRecipientWrap");
  if (wrap) wrap.hidden = privacy !== "private";
  if (privacy === "private" && focusRecipient) {
    setTimeout(() => document.getElementById("composeShareRecipient")?.focus(), 40);
  }
  updateComposeSharePreview();
}

function updateComposeSharePreview() {
  const preview = document.getElementById("composeSharePreview");
  if (!preview) return;
  const days = Math.max(1, Math.min(90, Number(document.getElementById("composeShareExpiry")?.value) || 7));
  const privacy = document.querySelector("input[name='composeSharePrivacy']:checked")?.value || "public";
  const recipient = privacy === "private" ? document.getElementById("composeShareRecipient")?.value.trim() || "" : "";
  const audience = privacy === "private"
    ? recipient ? t("ui.compose-manager.only-recipient", { email: recipient }) : t("ui.compose-manager.only-the-recipient-s-exact-email")
    : t("ui.compose-manager.anyone-with-the-link");
  preview.textContent = tn("ui.compose-manager.secure-cabinet-link-expires", days, { count: days, audience });
}

function setComposeShareStatus(message = "", tone = "") {
  const status = document.getElementById("composeShareStatus");
  if (!status) return;
  status.hidden = !message;
  status.textContent = message;
  status.classList.toggle("is-error", tone === "error");
}

function setComposeShareBusy(busy) {
  const button = document.getElementById("composeShareSubmit");
  if (!button) return;
  button.disabled = Boolean(busy);
  button.classList.toggle("is-busy", Boolean(busy));
  const label = button.querySelector(".compose-share-submit-label");
  if (label) label.textContent = busy ? t("ui.compose-manager.uploading") : t("ui.compose-manager.upload-and-insert-link");
  if (!busy) {
    const wrap = document.getElementById("composeShareProgress");
    const bar = document.getElementById("composeShareProgressBar");
    if (wrap) wrap.hidden = true;
    if (bar) bar.style.width = "0%";
  }
}


function updateComposeShareProgress(fraction) {
  const wrap = document.getElementById("composeShareProgress");
  const bar = document.getElementById("composeShareProgressBar");
  const percent = Math.max(0, Math.min(100, Math.round((Number(fraction) || 0) * 100)));
  if (wrap) wrap.hidden = false;
  if (bar) bar.style.width = `${percent}%`;
  const label = document.querySelector(".compose-share-submit-label");
  if (label) label.textContent = percent >= 100 ? t("ui.compose-manager.creating-secure-link") : t("ui.compose-manager.uploading-percent", { percent });
}

function uploadCabinetChunk(uploadId, chunk, offset, onProgress) {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open("PUT", `/api/files/uploads/${encodeURIComponent(uploadId)}`);
    xhr.withCredentials = true;
    xhr.timeout = 300000;
    xhr.setRequestHeader(t("ui.calendar.accept"), "application/json");
    xhr.setRequestHeader(t("ui.compose-manager.content-type"), "application/octet-stream");
    xhr.setRequestHeader(t("ui.compose-manager.x-a8m-upload-offset"), String(offset));
    if (!state.delegatedMode && state.activeAccountId) xhr.setRequestHeader(t("ui.compose-manager.x-a8m-account"), state.activeAccountId);
    const delegatedSession = state.delegatedSession;
    if (delegatedSession?.token) xhr.setRequestHeader(DELEGATED_SESSION_HEADER, delegatedSession.token);
    const csrf = delegatedSession?.csrf || state.csrf;
    if (csrf) xhr.setRequestHeader(t("ui.compose-manager.x-csrf-token"), csrf);
    xhr.upload.addEventListener("progress", (event) => {
      if (event.lengthComputable) onProgress(offset + event.loaded);
    });
    xhr.addEventListener("load", () => {
      setOffline(false);
      let payload = null;
      try { payload = xhr.responseText ? JSON.parse(xhr.responseText) : null; } catch { payload = null; }
      if (xhr.status >= 200 && xhr.status < 300) { resolve(payload); return; }
      if (xhr.status === 401) {
        if (state.delegatedMode) {
          const revoked = payload && payload.error ? payload.error.message : "";
          expireDelegatedWindow(revoked || t("ui.auth-boot.delegated-session-ended"));
        } else {
          handleSessionExpired();
        }
      }
      const detail = payload && payload.error ? payload.error : {};
      reject(new Error(detail.message || t("ui.compose-manager.request-failed-status", { status: xhr.status })));
    });
    xhr.addEventListener("error", () => {
      setOffline(true);
      reject(new Error(t("errors.NETWORK")));
    });
    xhr.addEventListener("timeout", () => reject(new Error(t("ui.compose-manager.the-upload-timed-out-try-again"))));
    xhr.send(chunk);
  });
}

async function uploadCabinetFileChunked(file, onProgress) {
  const started = await api("/api/files/uploads", { method: "POST", body: {
    name: file.name || t("ui.compose-manager.uploaded-file"),
    mime: file.type || "application/octet-stream",
    sizeBytes: file.size,
    path: t("nav.files"),
    description: t("ui.compose-manager.shared-from-compose-after-reaching-the-attachmen")
  } });
  const uploadId = started?.uploadId;
  if (!uploadId) throw new Error(t("ui.compose-manager.the-upload-could-not-be-started"));
  const chunkSize = Math.max(1024 * 1024, Number(started.chunkSize) || 8 * 1024 * 1024);
  let offset = 0;
  try {
    while (offset < file.size) {
      const chunk = file.slice(offset, Math.min(offset + chunkSize, file.size));
      await uploadCabinetChunk(uploadId, chunk, offset, (loaded) => {
        onProgress?.(Math.min(1, loaded / Math.max(1, file.size)));
      });
      offset += chunk.size;
      onProgress?.(Math.min(1, offset / Math.max(1, file.size)));
    }
    const completed = await api(`/api/files/uploads/${encodeURIComponent(uploadId)}/complete`, { method: "POST", body: {} });
    return completed.file;
  } catch (error) {
    api(`/api/files/uploads/${encodeURIComponent(uploadId)}`, { method: "DELETE", body: {} }).catch(() => {});
    throw error;
  }
}

