function openComposeShareDialog(session, file, { existingFile = null, reason = "" } = {}) {
  const overlay = ensureComposeShareOverlay();
  composeShareReturnFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  state.composeShareFallback = { sessionId: session.id, file, existingFile, resolve: null };
  const promise = new Promise((resolve) => { state.composeShareFallback.resolve = resolve; });
  const name = file.name || existingFile?.name || t("ui.mail-home-pulse-search-reports-sticky-no.file");
  const nameNode = document.getElementById("composeShareFileName");
  if (nameNode) { nameNode.textContent = name; nameNode.title = name; }
  const extNode = document.getElementById("composeShareFileExt");
  const extension = /\.([a-z0-9]{1,5})$/i.exec(name);
  if (extNode) extNode.textContent = extension ? extension[1].toUpperCase() : "FILE";
  document.getElementById("composeShareReason").textContent = reason || t("ui.compose-manager.this-file-exceeds-the-compose-attachment-limit-u");
  document.getElementById("composeShareFileSize").textContent = formatBytes(Number(file.size || existingFile?.sizeBytes || 0));
  document.getElementById("composeShareExpiry").value = "7";
  syncComposeShareDays(7);
  const publicChoice = document.querySelector("input[name='composeSharePrivacy'][value='public']");
  if (publicChoice) publicChoice.checked = true;
  syncComposeSharePrivacy(false);
  document.getElementById("composeShareRecipientWrap").hidden = true;
  document.getElementById("composeShareRecipient").value = "";
  document.getElementById("composeShareNote").value = "";
  setComposeShareStatus("");
  setComposeShareBusy(false);
  updateComposeSharePreview();
  overlay.hidden = false;
  setTimeout(() => {
    const input = document.getElementById("composeShareExpiry");
    input?.focus();
    input?.select?.();
  }, 40);
  return promise;
}

function closeComposeShareDialog(result = false) {
  const fallback = state.composeShareFallback;
  const overlay = document.getElementById("composeShareOverlay");
  if (overlay) overlay.hidden = true;
  state.composeShareFallback = null;
  setComposeShareBusy(false);
  const returnFocus = composeShareReturnFocus;
  composeShareReturnFocus = null;
  if (returnFocus && returnFocus.isConnected) returnFocus.focus();
  if (fallback?.resolve) fallback.resolve(result);
}

async function submitComposeShareFallback() {
  const fallback = state.composeShareFallback;
  const session = sessionById(fallback?.sessionId);
  if (!fallback || !session) { closeComposeShareDialog(false); return; }
  const privacy = document.querySelector("input[name='composeSharePrivacy']:checked")?.value || "public";
  const recipientEmail = privacy === "private" ? document.getElementById("composeShareRecipient").value.trim().toLowerCase() : "";
  const expiresDays = Math.max(1, Math.min(90, Number(document.getElementById("composeShareExpiry").value) || 7));
  const note = document.getElementById("composeShareNote").value.trim();
  if (privacy === "private" && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipientEmail)) {
    setComposeShareStatus(t("ui.compose-manager.enter-the-exact-recipient-email-for-a-private-li"), "error");
    document.getElementById("composeShareRecipient")?.focus();
    return;
  }
  setComposeShareStatus("");
  setComposeShareBusy(true);
  try {
    let fileRecord = fallback.existingFile;
    if (!fileRecord) {
      fileRecord = await uploadCabinetFileChunked(fallback.file, updateComposeShareProgress);
      if (fileRecord) state.files = [fileRecord, ...(state.files || []).filter((item) => item.id !== fileRecord.id)];
    } else {
      const label = document.querySelector(".compose-share-submit-label");
      if (label) label.textContent = t("ui.compose-manager.creating-secure-link");
    }
    const shared = await api(`/api/files/${encodeURIComponent(fileRecord.id)}/share`, { method: "POST", body: {
      access: "view", expiresDays, recipientEmail
    } });
    if (shared.pendingApproval) {
      setComposeShareStatus(t("ui.compose-manager.the-link-is-waiting-for-administrator-approval-i"));
      return;
    }
    const share = shared.share || {};
    insertComposeShareLink(session, { name: fallback.file?.name || fileRecord.name || t("ui.compose-manager.shared-file"), url: share.url, expiresAt: share.expiresAt, recipientEmail, note });
    if (!composeAttachOverlay.hidden) closeComposeAttach();
    composeShareReturnFocus = null;
    closeComposeShareDialog(true);
    showToast(t("ui.compose-manager.secure-cabinet-link-inserted"));
  } catch (error) {
    setComposeShareStatus(error.message || t("ui.compose-manager.the-file-could-not-be-shared"), "error");
  } finally {
    setComposeShareBusy(false);
  }
}

function insertComposeShareLink(session, { name, url, expiresAt, recipientEmail, note }) {
  if (!session || !url) return;
  const expiry = expiresAt ? formatDateOnly(expiresAt) : "";
  const privacy = recipientEmail ? t("ui.compose-manager.private-link-for", { email: recipientEmail }) : t("ui.compose-manager.anyone-with-the-link");
  const intro = note || t("ui.compose-manager.large-file-shared-securely");
  const text = `${intro}
${name}
${url}
${privacy}${expiry ? ` · expires ${expiry}` : ""}`;
  if (session.htmlMode) {
    const editor = session.el?.querySelector("[data-compose-editor]");
    if (!editor) return;
    const html = `<p>${esc(intro)}<br><strong>${esc(name)}</strong><br><a href="${esc(url)}">${esc(url)}</a><br><small>${esc(privacy)}${expiry ? ` · expires ${esc(expiry)}` : ""}</small></p>`;
    editor.focus();
    const selection = window.getSelection();
    if (selection && selection.rangeCount && editor.contains(selection.anchorNode)) document.execCommand("insertHTML", false, html);
    else editor.insertAdjacentHTML("beforeend", html);
    updateComposeEditor(session, editor);
  } else {
    const textarea = session.el?.querySelector('[data-compose-field="body"]');
    if (!textarea) return;
    textarea.value = `${textarea.value}${textarea.value ? "\n\n" : ""}${text}`;
    session.body = textarea.value;
    session.bodyHtml = textToEditorHTML(textarea.value);
    session.dirty = true;
    scheduleComposeSave(session, 200);
    updateComposeStatus(session);
  }
}

function sharedDraftCommentAnchor(session) {
  const editor = session.el?.querySelector("[data-compose-editor]");
  if (!editor) return {};
  const selection = window.getSelection();
  if (!selection || !selection.rangeCount || !editor.contains(selection.anchorNode)) return {};
  const range = selection.getRangeAt(0);
  if (range.collapsed) return {};
  const before = document.createRange();
  before.selectNodeContents(editor);
  before.setEnd(range.startContainer, range.startOffset);
  const start = before.toString().length;
  const quote = range.toString().slice(0, 500);
  return { start, end: start + quote.length, quote };
}

function sharedDraftAnchorRange(editor, anchor) {
  if (!anchor || !Number.isFinite(Number(anchor.start)) || !Number.isFinite(Number(anchor.end))) return null;
  const start = Math.max(0, Number(anchor.start));
  const end = Math.max(start, Number(anchor.end));
  const walker = document.createTreeWalker(editor, NodeFilter.SHOW_TEXT);
  let offset = 0;
  let startNode = null, startOffset = 0, endNode = null, endOffset = 0;
  let node;
  while ((node = walker.nextNode())) {
    const next = offset + node.nodeValue.length;
    if (!startNode && start >= offset && start <= next) { startNode = node; startOffset = start - offset; }
    if (!endNode && end >= offset && end <= next) { endNode = node; endOffset = end - offset; }
    offset = next;
  }
  if (!startNode || !endNode) return null;
  const range = document.createRange();
  range.setStart(startNode, startOffset);
  range.setEnd(endNode, endOffset);
  return range;
}

function applySharedDraftHighlights(session) {
  const editor = session.el?.querySelector("[data-compose-editor]");
  if (!editor || !window.CSS || !CSS.highlights || !window.Highlight) return;
  const ranges = (session.sharedDraft?.comments || [])
    .filter((comment) => !comment.resolvedAt)
    .map((comment) => sharedDraftAnchorRange(editor, comment.anchor))
    .filter(Boolean);
  if (ranges.length) CSS.highlights.set("shared-draft-comments", new Highlight(...ranges));
  else CSS.highlights.delete("shared-draft-comments");
}

function ensureSharedDraftPanel() {
  let overlay = document.getElementById("sharedDraftPanelOverlay");
  if (overlay) return overlay;
  document.body.insertAdjacentHTML("beforeend", `<div class="overlay" id="sharedDraftPanelOverlay" hidden><div class="dialog shared-drafts-dialog" role="dialog" aria-modal="true" aria-labelledby="sharedDraftPanelTitle"><div class="dialog-head"><div><p class="eyebrow">${t("ui.compose-manager.team-draft")}</p><h2 id="sharedDraftPanelTitle">${t("ui.compose-manager.collaboration")}</h2><p class="dialog-note" id="sharedDraftPanelNote"></p></div><button class="icon-btn" type="button" data-shared-panel-close aria-label="${esc(t("common.close"))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button></div><div class="dialog-body"><div class="compose-attach-tabs" role="tablist"><button class="is-active" data-shared-panel-tab="comments" type="button">${t("ui.compose-manager.comments")}</button><button data-shared-panel-tab="versions" type="button">${t("ui.compose-manager.versions")}</button></div><div id="sharedDraftPanelBody"></div></div><div class="dialog-foot"><button class="btn-secondary" type="button" data-shared-panel-close>${t("common.close")}</button></div></div></div>`);
  overlay = document.getElementById("sharedDraftPanelOverlay");
  overlay.addEventListener("click", (event) => {
    if (event.target === overlay || event.target.closest("[data-shared-panel-close]")) { overlay.hidden = true; state.sharedDraftPanel = null; }
    const tab = event.target.closest("[data-shared-panel-tab]");
    if (tab) { state.sharedDraftPanelTab = tab.dataset.sharedPanelTab; renderSharedDraftPanel(); }
  });
  return overlay;
}

function openSharedDraftPanel(session, tab = "comments") {
  if (!session?.sharedDraft) return;
  const overlay = ensureSharedDraftPanel();
  state.sharedDraftPanel = { sessionId: session.id, tab };
  state.sharedDraftPanelTab = tab;
  overlay.hidden = false;
  renderSharedDraftPanel();
}

async function renderSharedDraftPanel() {
  const panel = state.sharedDraftPanel;
  const session = sessionById(panel?.sessionId);
  if (!panel || !session) return;
  const host = document.getElementById("sharedDraftPanelBody");
  const note = document.getElementById("sharedDraftPanelNote");
  if (note) note.textContent = t("ui.compose-manager.draft-version", { version: session.sharedDraft.version, team: session.sharedDraft.teamId || "" });
  if (!host) return;
  $$("[data-shared-panel-tab]").forEach((button) => button.classList.toggle("is-active", button.dataset.sharedPanelTab === state.sharedDraftPanelTab));
  if (state.sharedDraftPanelTab === "versions") {
    host.innerHTML = "<div class=\"settings-note\">" + t("ui.alt8mail-office.loading-versions") + "</div>";
    try {
      const data = await api(`/api/shared-drafts/${encodeURIComponent(session.sharedDraft.id)}/versions`);
      const versions = data.versions || [];
      host.innerHTML = versions.length ? versions.map((version) => `<div class="automation-rule-row"><div class="shared-draft-copy"><strong>${esc(t("ui.compose-manager.version-number", { version: version.version }))}${Number(version.version) === Number(data.currentVersion) ? t("ui.compose-manager.current") : ""}</strong><span>${esc(version.authorName || version.authorEmail || t("mail.reader.unknownSender"))} · ${esc(formatListWhen(version.createdAt))} · ${esc(version.payload?.subject || t("ui.compose-manager.untitled-draft"))}</span></div>${Number(version.version) === Number(data.currentVersion) ? "" : `<button class="btn-secondary small" type="button" data-shared-restore="${version.version}">${t("ui.compose-manager.restore")}</button>`}</div>`).join("") : "<div class=\"empty-mini\">" + t("ui.compose-manager.no-versions-yet") + "</div>";
      $$("[data-shared-restore]", host).forEach((button) => button.addEventListener("click", () => restoreSharedDraftVersion(session, Number(button.dataset.sharedRestore)).catch(showError)));
    } catch (error) {
      host.innerHTML = `<div class="settings-note">${esc(error.message || t("ui.compose-manager.versions-could-not-be-loaded"))}</div>`;
    }
    return;
  }
  const comments = session.sharedDraft.comments || [];
  applySharedDraftHighlights(session);
  host.innerHTML = `<div class="detail-list">${comments.map((comment) => `<div class="detail-row"><span>${esc(comment.authorName || comment.authorEmail || t("ui.compose-manager.teammate"))} · ${esc(formatListWhen(comment.createdAt))}<br>${comment.anchor?.quote ? `<blockquote class="draft-comment-quote">${esc(comment.anchor.quote)}</blockquote>` : ""}${esc(comment.body)}</span><span>${comment.resolvedAt ? `<span class="badge neutral">${t("ui.compose-manager.resolved")}</span>` : `<button class="btn-secondary small" type="button" data-shared-comment-resolve="${esc(comment.id)}">${t("ui.compose-manager.resolve")}</button>`}</span></div>`).join("") || "<div class=\"empty-mini\">" + t("ui.compose-manager.no-comments-yet-select-text-in-the-draft-and-add") + "</div>"}</div><div class="field-row" style="margin-top:12px"><label class="field grow"><span>${t("ui.compose-manager.comment")}</span><textarea id="sharedDraftCommentBody" rows="3" maxlength="1000" placeholder="${esc(t("ui.compose-manager.leave-a-comment-on-the-selected-text"))}"></textarea></label></div><div style="display:flex;justify-content:flex-end"><button class="btn-secondary small" type="button" id="sharedDraftCommentAdd">${t("ui.compose-manager.comment-on-selection")}</button></div>`;
  document.getElementById("sharedDraftCommentAdd")?.addEventListener("click", () => addSharedDraftComment(session).catch(showError));
  $$("[data-shared-comment-resolve]").forEach((button) => button.addEventListener("click", () => resolveSharedDraftComment(session, button.dataset.sharedCommentResolve).catch(showError)));
}

async function addSharedDraftComment(session) {
  const body = String(document.getElementById("sharedDraftCommentBody")?.value || "").trim();
  if (!body) { showToast(t("ui.compose-manager.write-a-comment-first"), "error"); return; }
  const anchor = sharedDraftCommentAnchor(session);
  const data = await api(`/api/shared-drafts/${encodeURIComponent(session.sharedDraft.id)}/comments`, { method: "POST", body: { body, anchor } });
  session.sharedDraft.comments.push(data.comment);
  applySharedDraftHighlights(session);
  document.getElementById("sharedDraftCommentBody").value = "";
  await renderSharedDraftPanel();
  showToast(t("ui.compose-manager.comment-added"));
}

async function resolveSharedDraftComment(session, commentId) {
  await api(`/api/shared-drafts/${encodeURIComponent(session.sharedDraft.id)}/comments/${encodeURIComponent(commentId)}/resolve`, { method: "POST", body: {} });
  const comment = (session.sharedDraft.comments || []).find((item) => item.id === commentId);
  if (comment) comment.resolvedAt = new Date().toISOString();
  applySharedDraftHighlights(session);
  await renderSharedDraftPanel();
}

async function restoreSharedDraftVersion(session, version) {
  if (!(await appConfirm({ title: t("ui.compose-manager.restore-version-title", { version }), message: t("ui.compose-manager.the-current-shared-draft-content-becomes-a-new-v"), confirmLabel: t("ui.compose-manager.restore-version") }))) return;
  const data = await api(`/api/shared-drafts/${encodeURIComponent(session.sharedDraft.id)}/versions/${version}/restore`, { method: "POST", body: { baseVersion: session.sharedDraft.version, writerToken: session.sharedDraft.writerToken } });
  applyRestoredSharedDraft(session, data.draft);
  document.getElementById("sharedDraftPanelOverlay").hidden = true;
  state.sharedDraftPanel = null;
  showToast(t("ui.compose-manager.restored-version", { version }));
}

function applyRestoredSharedDraft(session, draft) {
  const payload = draft?.payload || {};
  session.to = payload.toText || "";
  session.cc = payload.ccText || "";
  session.bcc = payload.bccText || "";
  session.subject = payload.subject || "";
  session.body = payload.bodyText || "";
  session.bodyHtml = payload.bodyHtml || "";
  session.files = Array.isArray(payload.attachments) ? payload.attachments.map((file) => ({ ...file })) : [];
  ["to", "cc", "bcc"].forEach((field) => updateRecipientField(session, field));
  const subject = session.el?.querySelector('[data-compose-field="subject"]');
  if (subject) subject.value = session.subject;
  if (session.htmlMode) {
    const editor = session.el?.querySelector("[data-compose-editor]");
    if (editor) { editor.innerHTML = session.bodyHtml || textToEditorHTML(session.body); updateComposeEditor(session, editor); }
  } else {
    const textarea = session.el?.querySelector('[data-compose-field="body"]');
    if (textarea) { textarea.value = session.body; }
  }
  session.sharedDraft.version = Number(draft.version || session.sharedDraft.version);
  session.dirty = false;
  updateComposeFiles(session);
  updateComposeStatus(session);
}

function releaseComposeLocalFiles(session) {
  for (const file of session?.files || []) {
    if (file?.local && String(file.contentUrl || "").startsWith("blob:")) {
      try { URL.revokeObjectURL(file.contentUrl); } catch {}
      file.contentUrl = "";
    }
  }
}

function removeComposeFile(session, index) {
  if (!session || !Number.isInteger(index)) return;
  const file = session.files[index];
  if (file?.local && String(file.contentUrl || "").startsWith("blob:")) {
    try { URL.revokeObjectURL(file.contentUrl); } catch {}
  }
  session.files.splice(index, 1);
  updateComposeFiles(session);
  updateComposeStatus(session);
  scheduleComposeSave(session, 200);
}

async function uploadClientComposeFiles(session, files) {
  const uploaded = [];
  const limits = clientAttachmentLimits();
  let usage = composeAttachmentBytes(session);
  for (const file of files) {
    const size = Math.max(0, Number(file.size) || 0);
    if (session.files.length >= limits.count) {
      showToast(t("ui.compose.client-e2ee-attachment-limit", { limit: formatBytes(limits.totalBytes) }), "error");
      break;
    }
    if (size > limits.perFileBytes || usage + size > limits.totalBytes) {
      showToast(t("ui.compose.client-e2ee-attachment-limit", { limit: formatBytes(limits.totalBytes) }), "error");
      continue;
    }
    if (session.files.some((item) => item.name === file.name && item.sizeBytes === size)) {
      showToast(t("ui.compose-manager.file-already-attached", { name: file.name }));
      continue;
    }
    try {
      const dataBase64 = await fileToBase64(file);
      const attachment = {
        id: "",
        local: true,
        name: file.name || t("ui.compose-manager.attachment"),
        mime: file.type || "application/octet-stream",
        sizeBytes: size,
        size: formatBytes(size),
        dataBase64,
        contentUrl: URL.createObjectURL(file)
      };
      session.files.push(attachment);
      uploaded.push(attachment);
      usage += size;
      updateComposeFiles(session);
      scheduleComposeSave(session, 200);
      refreshAttachPickerIfOpen();
    } catch (error) {
      showError(error);
    }
  }
  updateComposeStatus(session);
  renderComposeDockTabs();
  return uploaded;
}

async function uploadComposeFiles(session, files) {
  const uploaded = [];
  if (!session || !files?.length) return uploaded;
  if (session.clientSide || clientSideEncryption()) {
    return uploadClientComposeFiles(session, files);
  }
  const limits = composeAttachmentLimits();
  let usage = composeAttachmentBytes(session);
  const queue = [];
  for (const file of files) {
    const size = Math.max(0, Number(file.size) || 0);
    if (size > limits.perFile) {
      await openComposeShareDialog(session, file, { reason: t("ui.compose-manager.file-too-large-link-instead", { name: file.name, limit: formatBytes(limits.perFile) }) });
      continue;
    }
    if (usage + size > limits.total) {
      await openComposeShareDialog(session, file, { reason: t("ui.compose-manager.compose-limit-share-from-cabinet", { usage: formatBytes(usage), limit: formatBytes(limits.total), name: file.name }) });
      continue;
    }
    if (session.files.some((item) => item.name === file.name && item.sizeBytes === size)) {
      showToast(t("ui.compose-manager.file-already-attached", { name: file.name }));
      continue;
    }
    queue.push(file);
    usage += size;
  }
  if (!queue.length) return uploaded;
  const totalBytes = queue.reduce((sum, file) => sum + Math.max(1, file.size || 0), 0);
  let completedBytes = 0;
  for (let index = 0; index < queue.length; index += 1) {
    const file = queue[index];
    const fileWeight = Math.max(1, file.size || 0);
    setComposeUploadProgress((completedBytes / totalBytes) * 100,
      t("ui.compose-manager.preparing-progress", { name: file.name, index: index + 1, total: queue.length }));
    try {
      const status = session.el?.querySelector("[data-compose-status]");
      if (status) status.textContent = t("ui.compose-manager.uploading-file", { name: file.name });
      const dataBase64 = await fileToBase64(file);
      const data = await uploadAttachmentWithProgress(file, dataBase64, {
        onProgress: (fraction) => setComposeUploadProgress(
          ((completedBytes + fileWeight * fraction) / totalBytes) * 100,
          t("ui.compose-manager.uploading-progress", { name: file.name, index: index + 1, total: queue.length })
        ),
        onUploaded: () => setComposeUploadProgress(
          ((completedBytes + fileWeight) / totalBytes) * 100,
          t("ui.compose-manager.scanning-progress", { name: file.name, index: index + 1, total: queue.length }),
          true
        )
      });
      session.files.push(data.attachment);
      uploaded.push(data.attachment);
      updateComposeFiles(session);
      scheduleComposeSave(session, 200);
      refreshAttachPickerIfOpen();
    } catch (error) {
      showError(error);
    }
    completedBytes += fileWeight;
  }
  finishComposeUploadProgress();
  updateComposeStatus(session);
  renderComposeDockTabs();
  return uploaded;
}

async function attachWorkspaceFile(fileId, sessionId = attachPickerSessionId) {
  const session = sessionById(sessionId);
  const file = (state.files || []).find((item) => item.id === fileId);
  if (!session || !file) return null;
  const limits = composeAttachmentLimits();
  const size = Number(file.sizeBytes || 0);
  if (size > limits.perFile || composeAttachmentBytes(session) + size > limits.total) {
    await openComposeShareDialog(session, { name: file.name, size }, {
      existingFile: file,
      reason: t("ui.compose-manager.file-would-exceed-limit", { name: file.name })
    });
    return null;
  }
  try {
    const response = await fetch(`/api/files/${encodeURIComponent(fileId)}/content`, { credentials: "same-origin", headers: delegatedRequestHeaders() });
    if (!response.ok) throw new Error(t("ui.compose-manager.that-file-could-not-be-downloaded"));
    const blob = await response.blob();
    const upload = new File([blob], file.name || "attachment", { type: file.mime || blob.type || "application/octet-stream" });
    const uploaded = await uploadComposeFiles(session, [upload]);
    if (uploaded && uploaded[0]) {
      uploaded[0].sourceFileId = fileId;
      return uploaded[0];
    }
  } catch (error) { showError(error); }
  return null;
}

function updateComposeStatus(session) {
  if (!session.el) return;
  const status = session.el.querySelector("[data-compose-status]");
  const error = session.el.querySelector("[data-compose-error]");
  if (status) {
    status.textContent = session.clientSide
      ? session.saveError || (session.dirty ? t("ui.compose.client-e2ee-draft-saving") : session.lastSavedAt ? t("ui.compose.client-e2ee-draft-saved") : t("ui.compose.client-e2ee-draft-note"))
      : session.aiReplyPending
        ? t("ui.compose-manager.ai-is-drafting-a-reply-from-the-conversation")
        : session.saveError || (session.dirty ? t("ui.named-signature-library.saving") : session.lastSavedAt ? t("ui.compose-manager.draft-saved-on-server") : t("ui.compose-manager.draft-not-saved-yet"));
    status.classList.toggle("is-error", Boolean(session.saveError));
  }
  if (error) {
    error.hidden = !session.error;
    error.textContent = session.error || "";
  }
}

function setActiveCompose(id) {
  activeComposeId = id;
  const session = sessionById(id);
  if (session && session.el && session.mode !== "minimized") session.el.style.zIndex = String(++composeZ + 1);
  renderComposeDockTabs();
}

function focusComposeField(session, field) {
  if (!session || !session.el || session.mode === "minimized") return;
  const selector = field
    ? `[data-compose-field="${field}"]`
    : (session.to ? '[data-compose-field="body"]' : '[data-compose-field="to"]');
  const target = session.el.querySelector(selector);
  if (target) target.focus();
}

function updateComposeDock() {
  const officeTabsVisible = state.delegatedMode ? 0 : officeDockTabs.length;
  const visible = composeSessions.length > 1 || composeSessions.some((session) => session.mode === "minimized") || officeTabsVisible > 0;
  const changed = composeDock.hidden !== !visible;
  composeDock.hidden = !visible;
  document.documentElement.style.setProperty("--compose-dock-h", visible ? "42px" : "0px");
  renderComposeDockTabs();
  document.body.classList.toggle("composing", composeSessions.length > 0);
  document.body.classList.toggle("compose-visible", composeSessions.some((session) => session.mode !== "minimized"));
  if (changed) requestAnimationFrame(layoutComposeSessions);
}

function renderComposeDockTabs() {
  if (composeDock.hidden) {
    composeDockTabs.innerHTML = "";
    return;
  }
  const officeTabsHtml = (state.delegatedMode ? [] : officeDockTabs).map((tab) => {
    const meta = OFFICE_HUB_META[tab.documentType] || OFFICE_HUB_META.word;
    const minimized = tab.minimized;
    const active = tab.id === officeDockActiveId && !minimized;
    return `<div class="compose-tab office-tab${active ? " is-active" : ""}${minimized ? " is-minimized" : ""}" data-office-dock-tab="${esc(tab.id)}" role="button" tabindex="0" title="${minimized ? t("ui.compose-manager.minimized-office-document-click-to-reopen") : t("ui.compose-manager.office-document-is-open")}">
      <span class="compose-tab-icon"><svg class="icon" aria-hidden="true"><use href="#${officeTypeIcon(tab.documentType)}"/></svg></span>
      <span class="compose-tab-text"><strong>${esc(tab.name)}</strong><span class="office-tab-kind">${esc(meta.singular)} · ${minimized ? t("ui.compose-manager.minimized") : t("tasks.status.open")}</span></span>
      <button class="compose-tab-close office-tab-close" data-office-dock-close="${esc(tab.id)}" type="button" aria-label="${esc(t("ui.compose-manager.close-type", { type: meta.singular }))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button>
    </div>`;
  }).join("");
  const composeTabsHtml = composeSessions.map((session) => {
    const title = session.subject.trim() || t("ui.alt8mail-intelligence-pre-send-spell-che.new-message");
    const recipient = session.to.trim() || t("ui.compose-manager.no-recipient");
    const minimized = session.mode === "minimized";
    const flash = minimized && minimizedComposeFlashId === session.id;
    return `<div class="compose-tab${session.id === activeComposeId ? " is-active" : ""}${minimized ? " is-minimized" : ""}${flash ? " is-just-minimized" : ""}" data-compose-tab="${esc(session.id)}" role="button" tabindex="0" title="${minimized ? t("ui.compose-manager.minimized-draft-click-to-reopen") : t("ui.compose-manager.open-draft")}">
      <span class="compose-tab-icon"><svg class="icon" aria-hidden="true"><use href="#i-mail"/></svg></span>
      <span class="compose-tab-text"><strong>${esc(title)}</strong><span>${esc(minimized ? `Minimized · ${recipient}` : recipient)}</span></span>
      <button class="compose-tab-close" data-compose-tab-close="${esc(session.id)}" type="button" aria-label="${esc(t("ui.compose-manager.close-draft"))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button>
    </div>`;
  }).join("");
  composeDockTabs.innerHTML = officeTabsHtml + composeTabsHtml;
}

function layoutComposeSessions() {
  if (isMobile()) {
    composeSessions.forEach((session) => { if (session.el) session.el.hidden = session.mode === "minimized"; });
    return;
  }
  const dockHeight = composeDock.hidden ? 0 : (composeDock.offsetHeight || 42);
  composeSessions.forEach((session) => {
    if (!session.el || session.mode === "minimized") return;
    session.el.hidden = false;
    if (session.mode === "inline") {
      applyInlineLayout(session);
      return;
    }
    session.el.classList.remove("is-inline");
    const sizePreference = state.preferences.composeWidth || "wide";
    const baseWidth = sizePreference === "full"
      ? Math.max(380, window.innerWidth - 56)
      : sizePreference === "wide"
        ? Math.min(1160, Math.max(620, window.innerWidth - 72))
        : Math.min(580, Math.max(380, window.innerWidth - 56));
    let width = session.manual && session.width ? session.width : baseWidth;
    let height = session.manual && session.height ? session.height : Math.min(sizePreference === "wide" ? 620 : 540, Math.max(300, window.innerHeight - 120));
    let left;
    let top;
    if (session.manual && session.left != null) {
      left = session.left;
      top = session.top;
    } else {
      const offset = (session.cascade % 6) * 16;
      const position = state.preferences.composePosition || "center";
      if (position === "center") {
        left = (window.innerWidth - width) / 2 + offset;
        top = (window.innerHeight - height) / 2 - offset;
      } else if (position === "bottom-left") {
        left = 28 + offset;
        top = window.innerHeight - (58 + dockHeight) - height - offset;
      } else {
        left = window.innerWidth - 28 - width - offset;
        top = window.innerHeight - (58 + dockHeight) - height - offset;
      }
      session.left = left;
      session.top = top;
      session.width = width;
      session.height = height;
    }
    const maxLeft = window.innerWidth - width - 12;
    const maxTop = window.innerHeight - height - 12;
    left = Math.max(12, Math.min(left, maxLeft));
    top = Math.max(12, Math.min(top, maxTop));
    session.left = left;
    session.top = top;
    session.el.style.left = left + "px";
    session.el.style.top = top + "px";
    session.el.style.right = "auto";
    session.el.style.bottom = "auto";
    session.el.style.width = width + "px";
    session.el.style.height = height + "px";
  });
}

function applyInlineLayout(session) {
  if (!session.el) return;
  if (state.task !== "mail") {
    session.mode = "minimized";
    session.el.hidden = true;
    return;
  }
  const rect = reader.getBoundingClientRect();
  if (rect.width < 60 || rect.height < 80) {
    session.mode = "minimized";
    session.el.hidden = true;
    return;
  }
  session.el.style.left = rect.left + "px";
  session.el.style.top = rect.top + "px";
  session.el.style.right = "auto";
  session.el.style.bottom = "auto";
  session.el.style.width = rect.width + "px";
  session.el.style.height = rect.height + "px";
}

function flashMinimizedComposeTab(id) {
  minimizedComposeFlashId = id;
  clearTimeout(minimizedComposeFlashTimer);
  renderComposeDockTabs();
  requestAnimationFrame(() => {
    composeDockTabs.querySelector(`[data-compose-tab="${CSS.escape(id)}"]`)?.scrollIntoView({ block: "nearest", inline: "nearest" });
  });
  minimizedComposeFlashTimer = setTimeout(() => {
    if (minimizedComposeFlashId !== id) return;
    minimizedComposeFlashId = null;
    renderComposeDockTabs();
  }, 2400);
}

function minimizeComposeSession(id) {
  const session = sessionById(id);
  if (!session) return;
  // The window mode is part of the persisted draft. Set it before the flush
  // so a reload or a sign-in on another computer restores the dock state.
  session.mode = "minimized";
  if (session.el) { session.el.hidden = true; session.el.classList.remove("is-inline"); }
  if (activeComposeId === id) {
    const next = composeSessions.find((item) => item.id !== id && item.mode !== "minimized");
    activeComposeId = next ? next.id : null;
  }
  updateComposeDock();
  flashMinimizedComposeTab(id);
  persistComposeSession(session);
  showToast(t("ui.compose-manager.draft-minimized-open-it-from-the-blue-dock-tab-b"));
}

async function persistComposeSession(session) {
  if (!session) return null;
  try {
    await flushDraft(session, { silent: true });
    // A save already in flight captured the old mode; run the queued save too
    // so windowMode is guaranteed to reflect the latest UI state.
    if (session.pendingSave || session.dirty) await flushDraft(session, { silent: true });
    return session;
  } catch {
    return null;
  }
}

async function persistComposeSessions() {
  const sessions = composeSessions.slice();
  await Promise.allSettled(sessions.map((session) => persistComposeSession(session)));
}

function flushComposeSessionsKeepalive() {
  if (!state.user || !state.csrf) return;
  for (const session of composeSessions.slice()) {
    if (!session || session.mode === "closed") continue;
    // Never send client-side plaintext to the draft API, even in a keepalive
    // request the server will reject.
    if (session.clientSide || clientSideEncryption()) continue;
    const shared = session.sharedDraft;
    const payload = JSON.stringify(shared
      ? { baseVersion: shared.version, writerToken: shared.writerToken, payload: composePayload(session) }
      : composePayload(session));
    try {
      fetch(shared ? `/api/shared-drafts/${encodeURIComponent(shared.id)}` : `/api/drafts/${encodeURIComponent(session.draftId)}`, {
        method: shared ? "PATCH" : "PUT",
        headers: delegatedRequestHeaders({
          "Content-Type": "application/json",
          "X-CSRF-Token": state.csrf,
          Accept: "application/json"
        }),
        body: payload,
        credentials: "same-origin",
        keepalive: true
      }).catch(() => {});
    } catch {
      // The page is unloading; the best-effort request is enough.
    }
  }
}

function restoreComposeSession(id) {
  const session = sessionById(id);
  if (!session) return;
  if (minimizedComposeFlashId === id) {
    minimizedComposeFlashId = null;
    clearTimeout(minimizedComposeFlashTimer);
  }
  if (isMobile()) {
    composeSessions.forEach((item) => {
      if (item !== session && item.mode !== "minimized") {
        item.mode = "minimized";
        if (item.el) item.el.hidden = true;
      }
    });
  }
  session.mode = "floating";
  if (session.el) { session.el.hidden = false; session.el.classList.remove("is-inline"); }
  setActiveCompose(id);
  updateComposeDock();
  persistComposeSession(session);
  requestAnimationFrame(() => { layoutComposeSessions(); focusComposeField(session); });
}

function expandComposeSession(id) {
  const session = sessionById(id);
  if (!session || isMobile() || session.mode === "minimized") return;
  if (session.mode === "inline") {
    session.mode = "floating";
    updateComposeWindow(session);
    setActiveCompose(id);
    updateComposeDock();
    requestAnimationFrame(() => { layoutComposeSessions(); focusComposeField(session); });
    return;
  }
  if (state.task !== "mail") setTask("mail");
  composeSessions.forEach((item) => {
    if (item !== session && item.mode !== "minimized") {
      item.mode = "minimized";
      if (item.el) item.el.hidden = true;
    }
  });
  session.mode = "inline";
  updateComposeWindow(session);
  setActiveCompose(id);
  updateComposeDock();
  requestAnimationFrame(() => { layoutComposeSessions(); focusComposeField(session); });
}

function removeComposeSessionUi(id) {
  const session = sessionById(id);
  closeComposeMentionMenu(session);
  releaseComposeLocalFiles(session);
  if (session && session.el) session.el.remove();
  if (attachPickerSessionId === id) closeComposeAttach();
  composeSessions = composeSessions.filter((item) => item.id !== id);
  if (activeComposeId === id) {
    const next = composeSessions.find((item) => item.mode !== "minimized") || composeSessions[0];
    activeComposeId = next ? next.id : null;
  }
  if (!composeSessions.length) document.body.classList.remove("composing");
  updateComposeDock();
}

async function closeComposeSession(id, { discard = false } = {}) {
  const session = sessionById(id);
  if (!session) return;
  if (aiAttachmentPicker?.sessionId === id) settleAiAttachmentPicker([]);
  clearTimeout(session.saveTimer);
  if (discard) {
    try {
      if (session.localDraft || session.clientSide) await deleteClientDraft(session.draftId);
      if (!session.localDraft) {
        if (session.sharedDraft) await api(`/api/shared-drafts/${encodeURIComponent(session.sharedDraft.id)}`, { method: "DELETE" });
        else await api(`/api/drafts/${encodeURIComponent(session.draftId)}`, { method: "DELETE" });
      }
    } catch {}
    state.messages = state.messages.filter((message) => message.id !== session.draftId);
    removeComposeSessionUi(id);
    rebuildIndex();
    renderFolders();
    renderList();
    showToast(session.sharedDraft ? t("ui.compose-manager.shared-draft-deleted") : t("ui.compose-manager.draft-discarded"));
    return;
  }
  const empty = isComposeEmpty(session);
  if (empty) {
    try {
      if (session.localDraft || session.clientSide) await deleteClientDraft(session.draftId);
      if (!session.localDraft) {
        if (session.sharedDraft) await api(`/api/shared-drafts/${encodeURIComponent(session.sharedDraft.id)}`, { method: "DELETE" });
        else await api(`/api/drafts/${encodeURIComponent(session.draftId)}`, { method: "DELETE" });
      }
    } catch {}
    state.messages = state.messages.filter((message) => message.id !== session.draftId);
    removeComposeSessionUi(id);
    rebuildIndex();
    renderFolders();
    renderList();
    return;
  }
  if (session.clientSide || clientSideEncryption()) {
    try {
      await flushClientDraft(session);
    } catch (error) {
      showError(error);
      return;
    }
    removeComposeSessionUi(id);
    showToast(t("ui.compose.client-e2ee-draft-saved"));
    return;
  }
  const previousMode = session.mode;
  session.mode = "closed";
  try {
    await flushDraft(session);
  } catch {
    session.mode = previousMode;
    return;
  }
  removeComposeSessionUi(id);
  showToast(t("ui.compose-manager.draft-saved-on-the-server"));
}

function activeComposeMentions(session) {
  const haystack = `${session.body || ""} ${stripHtml(session.bodyHtml || "")}`.toLowerCase();
  return Array.from(session.mentions.values()).filter((mention) => {
    const name = String(mention.name || "").toLowerCase();
    const email = String(mention.email || "").toLowerCase();
    return (name && haystack.includes("@" + name)) || (email && haystack.includes("@" + email));
  });
}

function composePayload(session) {
  flushRecipientInputs(session);
  return {
    toText: recipientTextWithPending(session, "to"),
    ccText: recipientTextWithPending(session, "cc"),
    bccText: recipientTextWithPending(session, "bcc"),
    subject: session.subject,
    bodyText: session.body,
    bodyHtml: (() => {
      const html = session.htmlMode ? restoreEditorImageSources(session.bodyHtml) : "";
      if (!html || !["ltr", "rtl"].includes(session.direction)) return html;
      return `<div dir="${session.direction}">${html}</div>`;
    })(),
    fromEmail: session.fromEmail,
    accountId: composeAccountIdFor(session.fromEmail),
    attachments: session.files,
    mentions: activeComposeMentions(session),
    threadId: session.threadId,
    inReplyTo: session.inReplyTo,
    composeKind: session.kind || "",
    sourceMessageId: session.sourceMessageId || "",
    windowMode: session.mode,
    priority: session.priority,
    classification: session.classification,
    receipt: session.receipt,
    delivery: session.delivery,
    saveCopy: session.saveCopy
  };
}

function scheduleComposeSave(session, delay = 750) {
  if (!session) return;
  clearTimeout(session.saveTimer);
  session.saveTimer = setTimeout(() => {
    flushDraft(session, { silent: true }).catch(() => {});
  }, delay);
}

function clientDraftPayload(session) {
  return {
    toText: session.to,
    ccText: session.cc,
    bccText: session.bcc,
    subject: session.subject,
    bodyText: session.body,
    bodyHtml: session.htmlMode ? restoreEditorImageSources(session.bodyHtml) : "",
    htmlMode: session.htmlMode,
    direction: session.direction,
    fromEmail: session.fromEmail,
    accountId: session.accountId,
    priority: session.priority,
    classification: session.classification,
    receipt: session.receipt,
    delivery: session.delivery,
    saveCopy: session.saveCopy,
    threadId: session.threadId,
    inReplyTo: session.inReplyTo,
    composeKind: session.composeKind || "",
    sourceMessageId: session.sourceMessageId || "",
    windowMode: session.mode,
    sign: session.sign === true,
    protocol: clientComposeProtocol(session),
    attachments: clientComposeAttachments(session),
    mentions: activeComposeMentions(session)
  };
}

function clientDraftMessage(session, payload, updatedAt) {
  const recipients = (value) => parseRecipientList(value).filter((entry) => entry.valid && entry.email).map((entry) => ({ name: entry.name || "", email: entry.email }));
  return {
    id: session.draftId,
    threadId: session.threadId || session.draftId,
    folder: "drafts",
    draft: true,
    localDraft: true,
    subject: payload.subject || t("mail.list.noSubject"),
    snippet: String(payload.bodyText || "").replace(/\s+/g, " ").slice(0, 160),
    bodyText: payload.bodyText || "",
    bodyHtml: payload.bodyHtml || "",
    to: recipients(payload.toText), cc: recipients(payload.ccText), bcc: recipients(payload.bccText),
    toText: payload.toText, ccText: payload.ccText, bccText: payload.bccText,
    from: { name: aliasDisplay(payload.fromEmail), email: payload.fromEmail },
    date: updatedAt,
    updatedAt,
    unread: false, starred: false, draft: true, localDraft: true,
    attachments: (payload.attachments || []).map((file) => ({ name: file.name, mime: file.mime, sizeBytes: Math.floor((String(file.dataBase64 || "").length * 3) / 4), dataBase64: file.dataBase64 })),
    categories: [], classification: payload.classification || "Internal", external: false, event: null,
    cryptoEncrypt: true, cryptoSigned: payload.sign === true, cryptoProtocol: payload.protocol || "openpgp", cryptoClientSide: true,
    windowMode: payload.windowMode || session.mode
  };
}

function flushClientDraft(session, { silent = false } = {}) {
  if (!session || !state.user?.email) return Promise.resolve(null);
  clearTimeout(session.saveTimer);
  if (session.savingPromise) {
    session.pendingSave = true;
    return session.savingPromise;
  }
  session.dirty = true;
  session.saveError = null;
  updateComposeStatus(session);
  session.savingPromise = (async () => {
    try {
      const payload = clientDraftPayload(session);
      const saved = payload.protocol === "smime"
        ? await saveClientSMIMEDraft(state.user.email, session.draftId, payload)
        : await saveClientDraft(state.user.email, session.draftId, payload);
      session.lastSavedAt = saved.updatedAt;
      session.dirty = false;
      session.saveError = null;
      upsertDraftMessage(clientDraftMessage(session, payload, saved.updatedAt));
      rebuildIndex();
      if (state.task === "mail") { renderFolders(); renderList(); }
      updateComposeStatus(session);
      return saved;
    } catch (error) {
      session.saveError = error.message || t("ui.compose.client-e2ee-draft-failed");
      session.dirty = true;
      updateComposeStatus(session);
      if (!silent) throw error;
      return null;
    } finally {
      session.savingPromise = null;
      if (session.pendingSave) {
        session.pendingSave = false;
        scheduleComposeSave(session, 350);
      }
    }
  })();
  return session.savingPromise;
}

function flushDraft(session, { silent = false } = {}) {
  if (!session) return Promise.resolve(null);
  if (session.clientSide) return flushClientDraft(session, { silent });
  if (session.sharedDraft) return flushSharedDraft(session, { silent });
  clearTimeout(session.saveTimer);
  if (session.savingPromise) {
    session.pendingSave = true;
    return session.savingPromise;
  }
  session.dirty = true;
  session.saveError = null;
  updateComposeStatus(session);
  session.savingPromise = (async () => {
    try {
      const data = await api(`/api/drafts/${encodeURIComponent(session.draftId)}`, {
        method: "PUT",
        body: composePayload(session)
      });
      const saved = data.draft;
      session.lastSavedAt = data.savedAt;
      session.dirty = false;
      session.saveError = null;
      upsertDraftMessage(saved);
      rebuildIndex();
      if (state.task === "mail") { renderFolders(); renderList(); }
      updateComposeStatus(session);
      return saved;
    } catch (error) {
      session.saveError = error.message || t("ui.compose-manager.draft-could-not-be-saved");
      session.dirty = true;
      updateComposeStatus(session);
      if (!silent) throw error;
      return null;
    } finally {
      session.savingPromise = null;
      if (session.pendingSave) {
        session.pendingSave = false;
        scheduleComposeSave(session, 350);
      }
    }
  })();
  return session.savingPromise;
}

function upsertDraftMessage(draft) {
  if (!draft) return;
  const existing = state.messages.find((message) => message.id === draft.id);
  if (existing) Object.assign(existing, draft);
  else state.messages.push(draft);
}

/* ============================================================
   Alt8Mail Intelligence · pre-send spell check
   ============================================================ */
const SPELLCHECK_PRODUCT_WORDS = new Set(["alt8mail", "a8m", "lynxkeep", "webmail", "dovecot", "postfix", "rspamd", "clamav"]);

function spellcheckIgnoredWords() {
  try {
    const parsed = JSON.parse(localStorage.getItem("a8m_spell_ignored") || "[]");
    return new Set(Array.isArray(parsed) ? parsed.map((word) => String(word).toLowerCase()) : []);
  } catch {
    return new Set();
  }
}

function addSpellIgnoredWord(word) {
  const key = String(word || "").toLowerCase();
  if (!key) return;
  const ignored = spellcheckIgnoredWords();
  ignored.add(key);
  try { localStorage.setItem("a8m_spell_ignored", JSON.stringify(Array.from(ignored).slice(-500))); } catch {}
}

function spellSuggestionCase(source, suggestion) {
  if (!suggestion) return suggestion;
  if (source && source === source.toUpperCase()) return suggestion.toUpperCase();
  if (source && /^[A-Z]/.test(source)) return suggestion.charAt(0).toUpperCase() + suggestion.slice(1);
  return suggestion;
}

async function loadSpellChecker() {
  if (state.spellChecker) return state.spellChecker;
  if (typeof window.Typo !== "function") throw new Error(t("ui.alt8mail-intelligence-pre-send-spell-che.spell-check-dictionary-is-unavailable"));
  const [aff, dic] = await Promise.all([
    fetch("/vendor/en_US.aff", { credentials: "same-origin", cache: "force-cache" }).then((response) => {
      if (!response.ok) throw new Error(t("ui.alt8mail-intelligence-pre-send-spell-che.spell-check-dictionary-could-not-be-loaded"));
      return response.text();
    }),
    fetch("/vendor/en_US.dic", { credentials: "same-origin", cache: "force-cache" }).then((response) => {
      if (!response.ok) throw new Error(t("ui.alt8mail-intelligence-pre-send-spell-che.spell-check-dictionary-could-not-be-loaded"));
      return response.text();
    })
  ]);
  state.spellChecker = new window.Typo("en_US", aff, dic);
  return state.spellChecker;
}

function collectSpellIssues(checker, text) {
  const cleaned = String(text || "")
    .replace(/https?:\/\/\S+|www\.\S+|[\w.+-]+@[\w.-]+\.[a-z]{2,}|\b[\w-]+\.(?:png|jpe?g|gif|pdf|docx?|xlsx?|pptx?|zip|txt)\b/gi, " ");
  const ignored = spellcheckIgnoredWords();
  const seen = new Map();
  const words = [];
  if (typeof Intl !== "undefined" && Intl.Segmenter) {
    const segmenter = new Intl.Segmenter("en", { granularity: "word" });
    for (const part of segmenter.segment(cleaned)) {
      if (part.isWordLike) words.push(part.segment);
    }
  } else {
    words.push(...(cleaned.match(/[A-Za-z][A-Za-z'’-]*/g) || []));
  }
  for (const raw of words) {
    const word = String(raw || "").replace(/^['’-]+|['’-]+$/g, "");
    if (word.length < 3 || /\d/.test(word)) continue;
    if (/^[A-Z]{2,6}$/.test(word)) continue;
    const key = word.toLowerCase();
    if (ignored.has(key) || SPELLCHECK_PRODUCT_WORDS.has(key)) continue;
    if (checker.check(word) || checker.check(key)) continue;
    let issue = seen.get(key);
    if (!issue) {
      const suggestions = (checker.suggest(key, 4) || [])
        .filter((suggestion) => suggestion && suggestion.toLowerCase() !== key)
        .slice(0, 4)
        .map((suggestion) => spellSuggestionCase(word, suggestion));
      issue = { word, count: 0, suggestions };
      seen.set(key, issue);
    }
    issue.count += 1;
    if (seen.size >= 50) break;
  }
  return Array.from(seen.values());
}

function renderSpellcheckDialog(issues) {
  const holder = document.getElementById("spellcheckIssues");
  holder.innerHTML = issues.map((issue) => `
    <div class="spellcheck-issue" data-spell-issue="${esc(issue.word.toLowerCase())}">
      <div class="spellcheck-word"><strong>${esc(issue.word)}</strong><span>${issue.count} occurrence${issue.count === 1 ? "" : "s"}</span></div>
      <div class="spellcheck-suggestions">
        ${issue.suggestions.length ? issue.suggestions.map((suggestion) => `<button type="button" data-spell-word="${esc(issue.word)}" data-spell-suggestion="${esc(suggestion)}">${esc(suggestion)}</button>`).join("") : `<span class="spellcheck-no-suggestion">${t("ui.alt8mail-intelligence-pre-send-spell-che.no-suggestions")}</span>`}
        <button type="button" class="spellcheck-ignore" data-spell-ignore="${esc(issue.word)}">${t("ui.alt8mail-intelligence-pre-send-spell-che.ignore")}</button>
        <button type="button" class="spellcheck-ignore" data-spell-add="${esc(issue.word)}">${t("ui.alt8mail-intelligence-pre-send-spell-che.add-to-dictionary")}</button>
      </div>
    </div>`).join("");
}

function openSpellcheckDialog(session, issues, action) {
  state.spellcheck = { sessionId: session.id, issues, choices: new Map(), action: action === "schedule" ? "schedule" : "send" };
  document.getElementById("spellcheckSubtitle").textContent = tn("ui.spellcheck.subtitle", issues.length, { count: issues.length });
  renderSpellcheckDialog(issues);
  spellcheckOverlay.hidden = false;
  const status = session.el?.querySelector("[data-compose-status]");
  if (status) status.textContent = t("ui.alt8mail-intelligence-pre-send-spell-che.review-spelling-before-sending");
  setTimeout(() => document.querySelector("#spellcheckIssues [data-spell-suggestion]")?.focus(), 80);
}

function closeSpellcheckDialog() {
  const sessionId = state.spellcheck?.sessionId;
  spellcheckOverlay.hidden = true;
  state.spellcheck = null;
  const session = sessionId ? sessionById(sessionId) : null;
  if (session) updateComposeStatus(session);
}

async function runSpellCheckBeforeSend(session, action = "send") {
  if (!session || !state.preferences.spellCheckEnabled || session.spellCheckBypass) return true;
  if (!String(state.preferences.language || "en").toLowerCase().startsWith("en")) return true;
  const status = session.el?.querySelector("[data-compose-status]");
  if (status) status.textContent = t("ui.alt8mail-intelligence-pre-send-spell-che.alt8mail-intelligence-is-checking-spelling");
  try {
    const checker = await loadSpellChecker();
    const issues = collectSpellIssues(checker, `${session.subject}\n${session.body}`);
    if (!issues.length) {
      updateComposeStatus(session);
      return true;
    }
    openSpellcheckDialog(session, issues, action);
    return false;
  } catch {
    updateComposeStatus(session);
    showToast(t("ui.alt8mail-intelligence-pre-send-spell-che.spell-check-is-unavailable-right-now-sending-wit"), "error");
    return true;
  }
}

function applySpellcheckChoices() {
  const review = state.spellcheck;
  const session = review ? sessionById(review.sessionId) : null;
  if (!review || !session) return;
  const replacements = [];
  for (const [key, value] of review.choices.entries()) {
    if (value == null) continue;
    const issue = review.issues.find((item) => item.word.toLowerCase() === key);
    if (issue) replacements.push({ source: issue.word, value });
  }
  if (!replacements.length) return;
  const replaceText = (text) => {
    let output = String(text || "");
    for (const replacement of replacements) {
      const pattern = new RegExp(`\\b${escapeRegExp(replacement.source)}\\b`, "gi");
      output = output.replace(pattern, (match) => spellSuggestionCase(match, replacement.value));
    }
    return output;
  };
  session.subject = replaceText(session.subject);
  const title = session.el?.querySelector("[data-compose-title]");
  if (title) title.textContent = session.subject.trim() || t("ui.alt8mail-intelligence-pre-send-spell-che.new-message");
  if (session.htmlMode) {
    const editor = session.el?.querySelector("[data-compose-editor]");
    if (editor) {
      const walker = document.createTreeWalker(editor, NodeFilter.SHOW_TEXT);
      const nodes = [];
      while (walker.nextNode()) nodes.push(walker.currentNode);
      for (const node of nodes) {
        const next = replaceText(node.nodeValue);
        if (next !== node.nodeValue) node.nodeValue = next;
      }
      updateComposeEditor(session, editor);
    }
  } else {
    const textarea = session.el?.querySelector('[data-compose-field="body"]');
    const next = replaceText(session.body);
    session.body = next;
    session.bodyHtml = textToEditorHTML(next);
    if (textarea) textarea.value = next;
    updateComposeStatus(session);
    scheduleComposeSave(session);
  }
  renderComposeDockTabs();
}

function composeIntentBodyText(session) {
  const editor = session.el?.querySelector("[data-compose-editor]");
  if (editor) {
    const clone = editor.cloneNode(true);
    clone.querySelectorAll(".compose-quote, [data-compose-quote]").forEach((node) => node.remove());
    return clone.textContent || "";
  }
  return session.body || "";
}

function composeIntentWarnings(session, scheduledFor) {
  const text = composeIntentBodyText(session);
  if (!text.trim()) return [];
  const warnings = [];
  const attachments = Array.isArray(session.files) ? session.files.length : 0;
  if (attachments === 0 && /\b(attached|attachment|attachments|enclosed|enclosure)\b/i.test(text)) {
    warnings.push(t("ui.alt8mail-intelligence-pre-send-spell-che.you-mention-an-attachment-but-no-file-is-attache"));
  }
  const target = scheduledFor ? new Date(scheduledFor) : new Date();
  if (Number.isNaN(target.getTime())) return warnings;
  const targetKey = dateKeyInZone(target);
  const todayKey = dateKeyInZone(new Date());
  if (/\btomorrow\b/i.test(text) && targetKey !== addDaysToKey(todayKey, 1)) {
    warnings.push(t("ui.alt8mail-intelligence-pre-send-spell-che.warning-tomorrow", { when: scheduledFor ? t("ui.alt8mail-intelligence-pre-send-spell-che.on-date", { date: formatDateOnly(target) }) : t("ui.alt8mail-intelligence-pre-send-spell-che.today") }));
  }
  if (/\b(today|tonight|end of day|eod)\b/i.test(text) && targetKey !== todayKey) {
    warnings.push(t("ui.alt8mail-intelligence-pre-send-spell-che.warning-today", { date: formatDateOnly(target) }));
  }
  const weekdays = { monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5, saturday: 6, sunday: 7 };
  const match = text.match(/\b(?:on|by|this|next)\s+(monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/i);
  if (match && weekdayOfKey(targetKey) !== weekdays[match[1].toLowerCase()]) {
    warnings.push(t("ui.alt8mail-intelligence-pre-send-spell-che.warning-date-phrase", { phrase: match[1], date: formatDateOnly(target) }));
  }
  return warnings.slice(0, 3);
}

async function confirmSendIntent(session, scheduledFor) {
  const warnings = composeIntentWarnings(session, scheduledFor);
  if (!warnings.length) return true;
  return appConfirm({
    title: t("ui.alt8mail-intelligence-pre-send-spell-che.check-before-sending"),
    message: warnings.join(" "),
    confirmLabel: t("ui.alt8mail-intelligence-pre-send-spell-che.send-anyway"),
    cancelLabel: t("ui.alt8mail-intelligence-pre-send-spell-che.review"),
    tone: "warning",
    icon: "i-alert"
  });
}

async function runComposeDataProtectionCheck(session) {
  if (!dlpPolicy().enabled) return true;
  let result;
  try {
    result = await api("/api/dlp/check", {
      method: "POST",
      body: {
        subject: session.subject,
        bodyText: session.body,
        bodyHtml: session.htmlMode ? restoreEditorImageSources(session.bodyHtml) : "",
        attachments: session.files,
        classification: session.classification
      }
    });
  } catch (_) {
    // The send endpoint enforces the same policy, so a failed pre-check must
    // not block delivery on its own.
    return true;
  }
  if (result.classification && result.classification !== session.classification) {
    session.classification = result.classification;
    updateComposeClassification(session);
    session.dirty = true;
    showToast(t("ui.alt8mail-intelligence-pre-send-spell-che.classification-set", { classification: result.classification }));
  }
  const warnings = Array.isArray(result.warnings) ? result.warnings.filter(Boolean) : [];
  if (result.blocked) {
    session.error = warnings[0] || t("ui.alt8mail-intelligence-pre-send-spell-che.this-message-is-blocked-by-your-organization-s-d");
    updateComposeStatus(session);
    await appConfirm({
      title: t("ui.alt8mail-intelligence-pre-send-spell-che.data-protection-policy"),
      message: `${warnings.join(" ") || session.error} ${t("ui.alt8mail-intelligence-pre-send-spell-che.remove-flagged-content")}`,
      confirmLabel: t("ui.alt8mail-intelligence-pre-send-spell-che.review-message"),
      cancelLabel: t("ui.alt8mail-intelligence-pre-send-spell-che.close"),
      tone: "danger",
      icon: "i-shield-check"
    });
    return false;
  }
  if (warnings.length) {
    return appConfirm({
      title: t("ui.alt8mail-intelligence-pre-send-spell-che.data-protection-check"),
      message: warnings.join(" "),
      confirmLabel: t("ui.alt8mail-intelligence-pre-send-spell-che.send-anyway"),
      cancelLabel: t("ui.alt8mail-intelligence-pre-send-spell-che.review"),
      tone: "warning",
      icon: "i-shield-check"
    });
  }
  return true;
}

function showDataProtectionBlock(error) {
  const details = (error && error.details) || {};
  const warnings = Array.isArray(details.warnings) ? details.warnings.filter(Boolean) : [];
  return appConfirm({
    title: t("ui.alt8mail-intelligence-pre-send-spell-che.data-protection-policy"),
    message: `${warnings.join(" ") || error.message || t("ui.alt8mail-intelligence-pre-send-spell-che.this-message-is-blocked-by-your-organization-s-d")} ${t("ui.alt8mail-intelligence-pre-send-spell-che.remove-flagged-content")}`,
    confirmLabel: t("ui.alt8mail-intelligence-pre-send-spell-che.review-message"),
    cancelLabel: t("ui.alt8mail-intelligence-pre-send-spell-che.close"),
    tone: "danger",
    icon: "i-shield-check"
  });
}

const OFFLINE_SENDS_KEY = "a8mOfflineSends";
const OFFLINE_MAIL_ACTIONS_KEY = "a8mOfflineMailActions";
const OFFLINE_TASKS_KEY = "a8mOfflineTasks";

function persistOfflineMailAction(job) {
  try {
    const queue = JSON.parse(localStorage.getItem(OFFLINE_MAIL_ACTIONS_KEY) || "[]");
    queue.push({
      key: job.requestId || uid("act"),
      ids: job.ids || [], action: job.action, folder: job.folder || "",
      reason: job.reason || "", note: job.note || "", categories: job.categories || [],
      until: job.until || "", threadCount: job.threadCount || 1, at: new Date().toISOString()
    });
    localStorage.setItem(OFFLINE_MAIL_ACTIONS_KEY, JSON.stringify(queue.slice(-100)));
  } catch {}
}

async function flushOfflineMailActions() {
  let queue = [];
  try { queue = JSON.parse(localStorage.getItem(OFFLINE_MAIL_ACTIONS_KEY) || "[]"); } catch { return; }
  if (!queue.length) return;
  const remaining = [];
  for (const item of queue) {
    try {
      await api("/api/messages/actions", { method: "POST", body: {
        ids: item.ids, action: item.action, folder: item.folder, reason: item.reason,
        note: item.note, categories: item.categories, until: item.until, requestId: item.key
      } });
    } catch (error) {
      if (error.code === "NETWORK") { remaining.push(item); break; }
      showError(error);
    }
  }
  try {
    if (remaining.length) localStorage.setItem(OFFLINE_MAIL_ACTIONS_KEY, JSON.stringify(remaining));
    else localStorage.removeItem(OFFLINE_MAIL_ACTIONS_KEY);
  } catch {}
  if (!remaining.length) {
    showToast(tn("ui.derived-data.offline-mailbox-changes-synced", queue.length, { count: queue.length }));
    refreshMailbox({ quiet: true }).catch(() => {});
  }
}

function queueOfflineTask(job) {
  try {
    const queue = JSON.parse(localStorage.getItem(OFFLINE_TASKS_KEY) || "[]");
    queue.push({ ...job, at: new Date().toISOString() });
    localStorage.setItem(OFFLINE_TASKS_KEY, JSON.stringify(queue.slice(-100)));
  } catch {}
}

async function flushOfflineTasks() {
  let queue = [];
  try { queue = JSON.parse(localStorage.getItem(OFFLINE_TASKS_KEY) || "[]"); } catch { return; }
  if (!queue.length) return;
  const remaining = [];
  for (const item of queue) {
    try {
      const data = await api(item.path, { method: item.method, body: item.body });
      if (item.tempId && data?.task?.id) {
        const index = state.tasks.findIndex((task) => task.id === item.tempId);
        if (index >= 0) state.tasks[index] = data.task;
      }
    } catch (error) {
      if (error.code === "NETWORK") { remaining.push(item); break; }
      showError(error);
    }
  }
  try {
    if (remaining.length) localStorage.setItem(OFFLINE_TASKS_KEY, JSON.stringify(remaining));
    else localStorage.removeItem(OFFLINE_TASKS_KEY);
  } catch {}
  if (!remaining.length) {
    showToast(tn("ui.derived-data.offline-task-changes-synced", queue.length, { count: queue.length }));
    refreshTasks().catch(() => {});
  }
}

function offlineSendKey() {
  try { return crypto.randomUUID(); } catch { return "offline-" + Date.now() + "-" + Math.random().toString(36).slice(2); }
}

function queueOfflineSend(payload, key, subject) {
  try {
    const queue = JSON.parse(localStorage.getItem(OFFLINE_SENDS_KEY) || "[]");
    queue.push({ key, body: payload, subject: subject || "", at: new Date().toISOString() });
    localStorage.setItem(OFFLINE_SENDS_KEY, JSON.stringify(queue.slice(-25)));
  } catch {}
}

async function flushOfflineSends() {
  let queue = [];
  try { queue = JSON.parse(localStorage.getItem(OFFLINE_SENDS_KEY) || "[]"); } catch { return; }
  if (!queue.length) return;
  const remaining = [];
  for (const item of queue) {
    try {
      await api("/api/send", { method: "POST", headers: { "Idempotency-Key": item.key }, body: item.body });
      showToast(t("ui.derived-data.offline-message-sent", { subject: item.subject || t("mail.list.noSubject") }));
    } catch (error) {
      if (error.code === "NETWORK") { remaining.push(item); break; }
      showError(error);
    }
  }
  try {
    if (remaining.length) localStorage.setItem(OFFLINE_SENDS_KEY, JSON.stringify(remaining));
    else localStorage.removeItem(OFFLINE_SENDS_KEY);
  } catch {}
}

async function validateComposeEncryption(session) {
  if (!session.encrypt && !session.sign) return true;
  if (!state.encryptionLoaded) await loadEncryptionStatus();
  if (!state.encryption?.enabled) {
    showToast(t("ui.compose.encryption-unavailable"));
    return false;
  }
  if (session.clientSide || clientSideEncryption()) {
    const protocol = clientComposeProtocol(session);
    const smime = protocol === "smime";
    const clientState = clientProtocolState(protocol);
    const published = clientPublishedIdentity(protocol);
    if (!clientState.supported) { showToast(t("ui.settings.client-key-not-supported")); return false; }
    if (!clientState.identity) { showToast(t(smime ? "ui.compose.client-smime-setup" : "ui.compose.client-e2ee-setup")); return false; }
    if (!published) { showToast(t(smime ? "ui.settings.smime-browser-not-published" : "ui.settings.client-key-not-published")); return false; }
    if (published.fingerprint !== clientState.identity.fingerprint) { showToast(t(smime ? "ui.settings.smime-browser-mismatch" : "ui.settings.client-key-mismatch")); return false; }
    if (!clientProtocolUnlocked(protocol)) { showToast(t(smime ? "ui.compose.client-smime-locked" : "ui.compose.client-e2ee-locked")); return false; }
    if (session.files?.some((file) => !file.local)) { showToast(t("ui.compose.client-e2ee-server-attachment")); return false; }
    const attachmentLimits = clientAttachmentLimits();
    if ((session.files?.length || 0) > attachmentLimits.count || composeAttachmentBytes(session) > attachmentLimits.totalBytes) {
      showToast(t("ui.compose.client-e2ee-attachment-limit", { limit: formatBytes(attachmentLimits.totalBytes) }));
      return false;
    }
    await checkComposeEncryptionRecipients(session);
    const check = session.encryptionCheck;
    if (check?.directoryChanged?.length) { showToast(t("ui.compose.client-e2ee-directory-key-changed", { emails: check.directoryChanged.map((item) => item.email).join(", ") })); return false; }
    if (check?.missing?.length) { showToast(t("ui.compose.encryption-missing-keys", { emails: check.missing.join(", ") })); return false; }
    if (!check?.checked) { showToast(t("ui.compose.encryption-checking")); return false; }
    return true;
  }
  const protocol = session.protocol || defaultComposeProtocol();
  if (!composeEncryptionProtocols().includes(protocol)) {
    showToast(t("ui.compose.encryption-unavailable"));
    return false;
  }
  if (!composeProtocolIdentity(protocol)) {
    showToast(protocol === "smime" ? t("ui.compose.smime-key-required") : t("ui.compose.encryption-key-required"));
    return false;
  }
  if (session.encrypt) {
    await checkComposeEncryptionRecipients(session);
    const check = session.encryptionCheck;
    if (check?.error) {
      showToast(t("ui.compose.encryption-check-failed", { error: check.error }));
      return false;
    }
    if (check?.missing?.length) {
      showToast(t("ui.compose.encryption-missing-keys", { emails: check.missing.join(", ") }));
      return false;
    }
    if (check?.changed?.length) {
      showToast(t("ui.compose.encryption-key-changed", { emails: check.changed.join(", ") }));
      return false;
    }
    if (check?.expired?.length) {
      showToast(t("ui.compose.encryption-expired-keys", { emails: check.expired.join(", ") }));
      return false;
    }
    if (!check?.checked) {
      showToast(t("ui.compose.encryption-checking"));
      return false;
    }
  }
  return true;
}

async function sendComposeSession(id) {
  const session = sessionById(id);
  if (!session || !session.el) return;
  if (validateComposeRecipients(session)) return;
  const sendButton = session.el.querySelector('[data-compose-action="send"]');
  if (sendButton) sendButton.disabled = true;
  if (!(await validateComposeEncryption(session))) {
    if (sendButton) sendButton.disabled = false;
    return;
  }
  let outgoing = composeSendPayload(session, { holdSeconds: state.undoSendSeconds });
  const clientSide = session.clientSide || clientSideEncryption();
  if (clientSide) {
    try {
      const encryptedMIME = await encryptClientComposeMIME(session);
      outgoing = {
        ...outgoing,
        attachments: [],
        bodyText: "",
        bodyHtml: "",
        encrypt: true,
        protocol: clientComposeProtocol(session),
        clientEncrypted: true,
        clientEncryptedMIME: encryptedMIME
      };
    } catch (error) {
      if (sendButton) sendButton.disabled = false;
      if (error.code === "MISSING_RECIPIENT_KEY") {
        showToast(t("ui.compose.client-e2ee-missing-keys", { emails: (error.recipients || []).join(", ") }), "error");
      } else if (error.code === "DIRECTORY_KEY_CHANGED") {
        session.encryptionCheck = { recipients: 0, missing: [], directoryChanged: error.changes || [], checked: true };
        renderComposeEncryptionStatus(session);
        showToast(t("ui.compose.client-e2ee-directory-key-changed", { emails: (error.recipients || []).join(", ") }), "error");
      } else if (error.status !== undefined) {
        showError(error);
      } else {
        console.error("[alt8mail] browser encryption failed", error);
        showToast(t("ui.compose.client-e2ee-failed"), "error");
      }
      return;
    }
  }
  const outgoingKey = offlineSendKey();
  try {
    const spellingOK = await runSpellCheckBeforeSend(session);
    if (!spellingOK) {
      if (sendButton) sendButton.disabled = false;
      return;
    }
    if (!clientSide && !(await runComposeDataProtectionCheck(session))) {
      if (sendButton) sendButton.disabled = false;
      return;
    }
    if (!(await confirmSendIntent(session, null))) {
      if (sendButton) sendButton.disabled = false;
      return;
    }
    if (!clientSide) await flushDraft(session);
    const data = await api("/api/send", {
      method: "POST",
      headers: { "Idempotency-Key": outgoingKey },
      body: outgoing
    });
    state.messages = state.messages.filter((message) => message.id !== session.draftId);
    if (clientSide || session.localDraft) await deleteClientDraft(session.draftId).catch(() => {});
    removeComposeSessionUi(id);
    rebuildIndex();
    renderFolders();
    renderList();
    if (data.queued) {
      const existing = state.pendingSends.find((item) => item.id === data.queued.id);
      if (!existing) state.pendingSends.push(data.queued);
      state.knownPendingIds.add(data.queued.id);
      if (data.outbound) state.outbound = data.outbound;
      updateOutboundUi();
      updatePendingUi();
      updateScheduledUi();
      stopOutboxPolling();
      startOutboxPolling();
      const holdMs = data.holdMs || state.undoSendSeconds * 1000;
      // Client-side encrypted mail has no server-side plaintext to restore,
      // so the send toast must not promise an Undo that would empty the draft.
      const undoLabel = clientSide ? "" : t("ui.status-bar-quota-pending-sends.undo");
      const undoAction = clientSide ? undefined : async () => {
        await cancelQueuedSend(data.queued.id);
      };
      showToast(t("ui.status-bar-quota-pending-sends.sending-subject", { subject: data.queued.subject }), undoLabel, undoAction, {
        countdownAt: data.queued.sendAt,
        sentMessage: t("ui.compose-manager.message-sent"),
        duration: holdMs + 2500,
        onExpire: () => {
          setTimeout(() => {
            refreshMailbox({ quiet: true }).catch(() => {});
          }, 700);
        }
      });
    }
  } catch (error) {
    if (error.code === "NETWORK" || !navigator.onLine) {
      queueOfflineSend(outgoing, outgoingKey, outgoing.subject || session.subject || "");
      removeComposeSessionUi(id);
      state.messages = state.messages.filter((message) => message.id !== session.draftId);
      rebuildIndex();
      renderList();
      showToast(t("ui.alt8mail-intelligence-pre-send-spell-che.offline-message-queued-and-will-send-when-you-re"));
      return;
    }
    session.error = error.message;
    if (sendButton) sendButton.disabled = false;
    updateComposeStatus(session);
    if (error.code === "DOMAIN_DNS_REQUIRED") {
      openDomainBlockedDialog(error.details || {});
    } else if (error.code === "DLP_BLOCKED") {
      session.error = error.message || t("ui.alt8mail-intelligence-pre-send-spell-che.blocked-by-your-organization-s-data-protection-p");
      updateComposeStatus(session);
      await showDataProtectionBlock(error);
    } else {
      showError(error);
    }
    if (error.code === "OUTBOUND_CAP") openStatusPop("outbound");
  }
}

async function cancelQueuedSend(queueId) {
  const queued = state.pendingSends.find((item) => item.id === queueId);
  try {
    const data = await api(`/api/outbox/${encodeURIComponent(queueId)}/cancel`, { method: "POST", body: {} });
    state.pendingSends = state.pendingSends.filter((item) => item.id !== queueId);
    state.knownPendingIds.delete(queueId);
    if (data.outbound) state.outbound = data.outbound;
    updatePendingUi();
    updateScheduledUi();
    updateOutboundUi();
    stopOutboxPolling();
    startOutboxPolling();
    const clientSide = data.clientSide === true || queued?.clientSide === true;
    if (data.draft && !clientSide) {
      upsertDraftMessage(data.draft);
      rebuildIndex();
      renderFolders();
      renderList();
      openComposeFromDraft(data.draft);
    }
    await refreshMailbox({ quiet: true });
    showToast(clientSide
      ? t("ui.status-bar-quota-pending-sends.client-side-send-cancelled")
      : queued && queued.scheduled ? t("ui.alt8mail-intelligence-pre-send-spell-che.scheduled-send-cancelled-draft-restored") : t("ui.alt8mail-intelligence-pre-send-spell-che.send-cancelled-draft-restored"));
  } catch (error) {
    showError(error);
    if (error.code === "SEND_ALREADY_COMMITTED") {
      state.pendingSends = state.pendingSends.filter((item) => item.id !== queueId);
      updatePendingUi();
      updateScheduledUi();
      refreshMailbox({ quiet: true }).catch(() => {});
    }
  }
}

function validateComposeRecipients(session) {
  if (!session || !session.el) return t("ui.alt8mail-intelligence-pre-send-spell-che.compose-window-is-no-longer-open");
  flushRecipientInputs(session);
  const entries = parseRecipientList(session.to);
  const fieldWrap = session.el.querySelector('[data-compose-field-wrap="to"]');
  session.error = null;
  updateComposeStatus(session);
  if (!entries.length) {
    if (fieldWrap) fieldWrap.classList.add("is-error");
    session.el.querySelector('[data-recipient-input="to"]')?.focus();
    session.error = t("ui.alt8mail-intelligence-pre-send-spell-che.add-at-least-one-recipient");
    updateComposeStatus(session);
    return session.error;
  }
  const pendingInvalid = RECIPIENT_FIELDS.some((field) => {
    const pending = String(session.recipientInput?.[field] || "").trim();
    if (!pending) return false;
    const parsed = parseRecipientList(pending);
    return !parsed.length || parsed.some((entry) => !entry.valid);
  });
  if (entries.some((entry) => !entry.valid) || pendingInvalid) {
    if (fieldWrap) fieldWrap.classList.add("is-error");
    session.error = t("ui.alt8mail-intelligence-pre-send-spell-che.one-or-more-recipient-addresses-look-incomplete");
    updateComposeStatus(session);
    return session.error;
  }
  if (fieldWrap) fieldWrap.classList.remove("is-error");
  updateComposeStatus(session);
  return null;
}

async function encryptClientComposeMIME(session) {
  const protocol = clientComposeProtocol(session);
  const fields = {
    bodyText: session.body,
    bodyHtml: session.htmlMode ? restoreEditorImageSources(session.bodyHtml) : "",
    recipientEmails: composeRecipientEmails(session),
    sign: session.sign,
    attachments: clientComposeAttachments(session)
  };
  return protocol === "smime" ? encryptClientSMIMEMIME(fields) : encryptClientMIME(fields);
}

function clientComposeAttachments(session) {
  return (session?.files || [])
    .filter((file) => file.local && file.dataBase64)
    .map((file) => ({ name: file.name, mime: file.mime, dataBase64: file.dataBase64 }));
}

function composeSendPayload(session, extra = {}) {
  flushRecipientInputs(session);
  return {
    draftId: session.clientSide && !session.hasServerDraft ? "" : session.draftId,
    fromEmail: session.fromEmail,
    accountId: composeAccountIdFor(session.fromEmail),
    to: session.to,
    cc: session.cc,
    bcc: session.bcc,
    subject: session.subject,
    bodyText: session.body,
    bodyHtml: (() => {
      const html = session.htmlMode ? restoreEditorImageSources(session.bodyHtml) : "";
      if (!html || !["ltr", "rtl"].includes(session.direction)) return html;
      return `<div dir="${session.direction}">${html}</div>`;
    })(),
    attachments: session.files,
    mentions: activeComposeMentions(session),
    threadId: session.threadId,
    inReplyTo: session.inReplyTo,
    composeKind: session.kind || "",
    sourceMessageId: session.sourceMessageId || "",
    priority: session.priority,
    classification: session.classification,
    receipt: session.receipt,
    delivery: session.delivery,
    saveCopy: session.saveCopy,
    encrypt: session.encrypt === true,
    sign: session.sign === true,
    protocol: session.protocol || defaultComposeProtocol(),
    ...extra
  };
}

function minutesFromTime(value) {
  const [hours, minutes] = String(value || "00:00").split(":").map(Number);
  return (hours || 0) * 60 + (minutes || 0);
}

function timeFromMinutes(value) {
  const minutes = Math.max(0, Math.min(23 * 60 + 59, Math.round(value / 15) * 15));
  return `${String(Math.floor(minutes / 60)).padStart(2, "0")}:${String(minutes % 60).padStart(2, "0")}`;
}

function buildSchedulePresets() {
  const preferences = state.preferences;
  const workStart = preferences.workStart || "09:00";
  const workEnd = preferences.workEnd || "17:00";
  const workDays = new Set(preferences.workDays && preferences.workDays.length ? preferences.workDays : [1, 2, 3, 4, 5]);
  const today = dateKeyInZone(new Date());
  const nowParts = timeZoneParts(new Date());
  const nowMinutes = nowParts.hour * 60 + nowParts.minute;
  const startMinutes = minutesFromTime(workStart);
  const endMinutes = minutesFromTime(workEnd);
  let nextKey = "";
  let nextTime = workStart;
  if (workDays.has(weekdayOfKey(today)) && nowMinutes + 60 < endMinutes) {
    const candidate = Math.max(startMinutes, Math.ceil((nowMinutes + 60) / 15) * 15);
    if (candidate < endMinutes) { nextKey = today; nextTime = timeFromMinutes(candidate); }
  }
  if (!nextKey) {
    for (let offset = 1; offset <= 8; offset += 1) {
      const key = addDaysToKey(today, offset);
      if (workDays.has(weekdayOfKey(key))) { nextKey = key; nextTime = workStart; break; }
    }
  }
  const tomorrow = addDaysToKey(today, 1);
  let monday = addDaysToKey(today, 1);
  for (let offset = 1; offset <= 8; offset += 1) {
    const key = addDaysToKey(today, offset);
    if (weekdayOfKey(key) === 1) { monday = key; break; }
  }
  const afternoonMinutes = Math.min(endMinutes - 30, Math.max(13 * 60, startMinutes + 4 * 60));
  const presets = [
    { id: "next-slot", title: t("ui.alt8mail-intelligence-pre-send-spell-che.recommended"), kicker: t("ui.alt8mail-intelligence-pre-send-spell-che.next-work-slot"), date: nextKey, time: nextTime, recommended: true },
    { id: "tomorrow-morning", title: t("ui.alt8mail-intelligence-pre-send-spell-che.tomorrow-morning"), kicker: t("ui.alt8mail-intelligence-pre-send-spell-che.morning"), date: tomorrow, time: workStart },
    { id: "tomorrow-afternoon", title: t("ui.alt8mail-intelligence-pre-send-spell-che.tomorrow-afternoon"), kicker: t("ui.alt8mail-intelligence-pre-send-spell-che.afternoon"), date: tomorrow, time: timeFromMinutes(afternoonMinutes) },
    { id: "monday-morning", title: t("ui.alt8mail-intelligence-pre-send-spell-che.monday-morning"), kicker: t("ui.alt8mail-intelligence-pre-send-spell-che.start-of-week"), date: monday, time: workStart }
  ];
  const seen = new Set();
  const chosen = [];
  for (const preset of presets) {
    const stamp = zonedWallTimeToUtc(preset.date, preset.time);
    if (!stamp || stamp.getTime() <= Date.now() + 5000) continue;
    const key = `${preset.date}T${preset.time}`;
    if (seen.has(key)) continue;
    seen.add(key);
    chosen.push(preset);
  }
  // A Sunday or holiday can collapse Recommended, Tomorrow and Monday into
  // the same slot. Fill the grid with the next distinct work slots so the
  // scheduling dialog never loses its useful choices.
  for (let offset = 2; chosen.length < 4 && offset <= 10; offset += 1) {
    const key = addDaysToKey(today, offset);
    if (!workDays.has(weekdayOfKey(key))) continue;
    for (const [suffix, title, time] of [["morning", t("ui.alt8mail-intelligence-pre-send-spell-che.morning"), workStart], ["afternoon", t("ui.alt8mail-intelligence-pre-send-spell-che.afternoon"), timeFromMinutes(afternoonMinutes)]]) {
      const stamp = zonedWallTimeToUtc(key, time);
      if (!stamp || stamp.getTime() <= Date.now() + 5000) continue;
      const dedupe = `${key}T${time}`;
      if (seen.has(dedupe)) continue;
      seen.add(dedupe);
      chosen.push({ id: `later-${suffix}-${offset}`, title: `${formatDateOnly(key)} ${title}`, kicker: t("ui.alt8mail-intelligence-pre-send-spell-che.next-work-slot"), date: key, time });
      if (chosen.length >= 4) break;
    }
  }
  return chosen.slice(0, 4);
}

function openScheduleDialog(session) {
  if (!session || !session.el) return;
  const error = validateComposeRecipients(session);
  if (error) { showToast(error); return; }
  scheduleSession = session;
  scheduleChoice = "next-slot";
  const presets = buildSchedulePresets();
  const alias = aliasForEmail(session.fromEmail);
  const fromLabel = alias ? `${alias.label} <${alias.email}>` : session.fromEmail;
  scheduleMessageCard.innerHTML = `<div class="schedule-message-row"><span class="schedule-message-label">${t("mail.details.from")}</span><strong>${esc(fromLabel)}</strong></div>
    <div class="schedule-message-row"><span class="schedule-message-label">${t("mail.details.to")}</span><span>${esc(session.to || t("ui.alt8mail-intelligence-pre-send-spell-che.no-recipient"))}${session.cc ? ` · Cc ${esc(session.cc)}` : ""}</span></div>
    <div class="schedule-message-row"><span class="schedule-message-label">${t("ui.alt8mail-intelligence-pre-send-spell-che.subject")}</span><span>${esc(session.subject.trim() || t("mail.list.noSubject"))}</span></div>`;
  schedulePresets.innerHTML = presets.map((preset) => {
    const stamp = zonedWallTimeToUtc(preset.date, preset.time);
    return `<button class="schedule-preset${preset.recommended ? " is-recommended" : ""}" data-schedule-preset="${preset.id}" type="button" role="radio" aria-checked="false">
      <span class="schedule-preset-icon"><svg class="icon" aria-hidden="true"><use href="#${preset.id === "monday-morning" ? "i-calendar" : "i-calendar-clock"}"/></svg></span>
      <span class="schedule-preset-copy"><strong>${esc(preset.title)}</strong><span>${esc(formatDateOnly(preset.date))} · ${esc(formatClock(stamp))}</span><small>${esc(formatRelativeTime(stamp))}</small></span>
      ${preset.recommended ? "<span class=\"schedule-recommended\">" + t("ui.alt8mail-intelligence-pre-send-spell-che.recommended") + "</span>" : ""}
      <span class="schedule-radio" aria-hidden="true"></span>
    </button>`;
  }).join("") + `<button class="schedule-preset schedule-custom-card${presets.length ? "" : " is-recommended"}" data-schedule-preset="custom" type="button" role="radio" aria-checked="false">
      <span class="schedule-preset-icon"><svg class="icon" aria-hidden="true"><use href="#i-sliders"/></svg></span>
      <span class="schedule-preset-copy"><strong>${t("ui.alt8mail-intelligence-pre-send-spell-che.pick-a-date-and-time")}</strong><span>${t("ui.alt8mail-intelligence-pre-send-spell-che.choose-any-future-moment")}</span><small>${esc(t("ui.alt8mail-intelligence-pre-send-spell-che.uses-zone", { zone: formatTimeZoneShort() }))}</small></span>
      <span class="schedule-radio" aria-hidden="true"></span>
    </button>`;
  state.schedulePresets = presets;
  scheduleZoneInfo.textContent = formatTimeZoneLabel();
  scheduleZoneHint.textContent = t("ui.alt8mail-intelligence-pre-send-spell-che.schedule-zone-hint", { zone: currentTimeZone().replace(/_/g, " ") });
  scheduleDate.min = dateKeyInZone(new Date());
  const initial = presets[0] || { date: addDaysToKey(dateKeyInZone(new Date()), 1), time: state.preferences.workStart || "09:00" };
  scheduleChoice = presets[0] ? presets[0].id : "custom";
  scheduleDate.value = initial.date;
  scheduleTime.value = initial.time;
  scheduleWarning.hidden = true;
  scheduleOverlay.hidden = false;
  selectSchedulePreset(scheduleChoice);
  loadRecipientTimeSuggestions(session);
  setTimeout(() => document.querySelector(`[data-schedule-preset="${scheduleChoice}"]`)?.focus(), 40);
}


function ensureScheduleSuggestionUi() {
  const presets = document.getElementById("schedulePresets");
  if (presets && !document.getElementById("scheduleRecipientSuggestions")) {
    presets.insertAdjacentHTML("beforebegin", `<div class="schedule-recipient-suggestions" id="scheduleRecipientSuggestions" hidden></div>`);
  }
  return document.getElementById("scheduleRecipientSuggestions");
}

function timeValueInZone(value) {
  const parts = timeZoneParts(value);
  if (!parts) return "";
  return `${String(parts.hour).padStart(2, "0")}:${String(parts.minute).padStart(2, "0")}`;
}

async function loadRecipientTimeSuggestions(session) {
  const container = ensureScheduleSuggestionUi();
  if (!container || !session) return;
  const emails = parseRecipientList(session.to || "")
    .map((entry) => normalizeEmail(entry.email))
    .filter(Boolean)
    .slice(0, 20);
  if (!emails.length) {
    container.hidden = true;
    container.innerHTML = "";
    return;
  }
  container.hidden = false;
  container.innerHTML = `<div class="schedule-suggestion-head"><span>${t("ui.alt8mail-intelligence-pre-send-spell-che.best-time-for-recipients")}</span><small>${t("ui.alt8mail-intelligence-pre-send-spell-che.checking-recent-activity")}</small></div>`;
  try {
    const data = await api("/api/send-time-suggestions", { method: "POST", body: { to: emails } });
    if (scheduleSession?.id !== session.id || scheduleOverlay.hidden) return;
    const suggestions = Array.isArray(data.suggestions) ? data.suggestions : [];
    if (!suggestions.length) {
      container.hidden = true;
      container.innerHTML = "";
      return;
    }
    container.innerHTML = `<div class="schedule-suggestion-head"><span>${t("ui.alt8mail-intelligence-pre-send-spell-che.best-time-for-recipients")}</span><small>${suggestions.some((item) => item.known) ? t("ui.alt8mail-intelligence-pre-send-spell-che.based-on-when-they-usually-write") : t("ui.alt8mail-intelligence-pre-send-spell-che.based-on-your-working-hours")}</small></div>
      <div class="schedule-suggestion-list">${suggestions.map((item) => {
        const stamp = new Date(item.sendAt);
        const who = item.recipientName || item.recipient || "";
        const local = item.known && item.recipientLocal ? t("ui.alt8mail-intelligence-pre-send-spell-che.recipient-time", { who, time: item.recipientLocal }) : t("ui.alt8mail-intelligence-pre-send-spell-che.your-working-hours");
        return `<button class="schedule-suggestion" type="button" data-schedule-suggestion="${esc(item.sendAt)}"><strong>${esc(formatClock(stamp))}</strong><span>${esc(local)}</span><small>${esc(item.reason || "")}</small></button>`;
      }).join("")}</div>`;
  } catch {
    if (scheduleSession?.id === session.id) {
      container.hidden = true;
      container.innerHTML = "";
    }
  }
}

function applyScheduleSuggestion(value) {
  const stamp = new Date(value);
  if (!scheduleDate || !scheduleTime || Number.isNaN(stamp.getTime())) return;
  scheduleChoice = "custom";
  scheduleDate.value = dateKeyInZone(stamp);
  scheduleTime.value = timeValueInZone(stamp);
  updateSchedulePreview();
  $$("[data-schedule-preset]", schedulePresets).forEach((button) => {
    button.classList.remove("is-selected");
    button.setAttribute("aria-checked", "false");
  });
}

function selectSchedulePreset(id) {
  scheduleChoice = id;
  const preset = (state.schedulePresets || []).find((item) => item.id === id);
  if (preset) {
    scheduleDate.value = preset.date;
    scheduleTime.value = preset.time;
  }
  $$("[data-schedule-preset]", schedulePresets).forEach((button) => {
    const active = button.getAttribute("data-schedule-preset") === id;
    button.classList.toggle("is-selected", active);
    button.setAttribute("aria-checked", active ? "true" : "false");
  });
  updateSchedulePreview();
}

function updateSchedulePreview() {
  if (!scheduleDate || !scheduleTime) return;
  const stamp = zonedWallTimeToUtc(scheduleDate.value, scheduleTime.value);
  const valid = stamp && !Number.isNaN(stamp.getTime());
  const future = valid && stamp.getTime() > Date.now() + 5000;
  if (!valid) {
    scheduleInsight.innerHTML = "<span class=\"schedule-insight-error\">" + t("ui.alt8mail-intelligence-pre-send-spell-che.choose-a-valid-date-and-time") + "</span>";
    scheduleWarning.hidden = false;
    scheduleWarning.textContent = t("ui.alt8mail-intelligence-pre-send-spell-che.choose-a-valid-date-and-time");
    scheduleConfirm.disabled = true;
    return;
  }
  const time = scheduleTime.value;
  const start = state.preferences.workStart || "09:00";
  const end = state.preferences.workEnd || "17:00";
  const workDays = state.preferences.workDays || [1, 2, 3, 4, 5];
  const workDay = workDays.includes(weekdayOfKey(scheduleDate.value));
  const withinHours = time >= start && time < end;
  const outside = !workDay || !withinHours;
  scheduleInsight.innerHTML = `<div class="schedule-insight-main"><span class="schedule-insight-kicker">${t("ui.alt8mail-intelligence-pre-send-spell-che.leaves-the-outbox")}</span><strong>${esc(formatDateTimeFull(stamp))}</strong><span>${esc(formatRelativeTime(stamp))} · ${esc(formatTimeZoneLabel())}</span></div>
    <div class="schedule-insight-grid"><div><span>${t("nav.calendar")}</span><strong>${esc(workDay ? t("ui.alt8mail-intelligence-pre-send-spell-che.working-day") : t("ui.alt8mail-intelligence-pre-send-spell-che.outside-working-days"))}</strong></div><div><span>${t("ui.alt8mail-intelligence-pre-send-spell-che.working-hours")}</span><strong>${esc(withinHours ? t("ui.alt8mail-intelligence-pre-send-spell-che.within-hours") : t("ui.alt8mail-intelligence-pre-send-spell-che.outside-hours"))}</strong></div><div><span>${t("ui.alt8mail-intelligence-pre-send-spell-che.delivery")}</span><strong>${esc(future ? t("ui.alt8mail-intelligence-pre-send-spell-che.queued-on-the-server") : t("ui.alt8mail-intelligence-pre-send-spell-che.choose-a-future-time"))}</strong></div></div>`;
  scheduleConfirm.disabled = !future;
  if (!future) {
    scheduleWarning.hidden = false;
    scheduleWarning.textContent = t("ui.alt8mail-intelligence-pre-send-spell-che.scheduled-send-must-be-at-least-a-few-seconds-in");
  } else if (outside) {
    scheduleWarning.hidden = false;
    scheduleWarning.textContent = t("ui.alt8mail-intelligence-pre-send-spell-che.outside-working-time", { period: workDay ? t("ui.alt8mail-intelligence-pre-send-spell-che.hours") : t("ui.alt8mail-intelligence-pre-send-spell-che.days") });
  } else {
    scheduleWarning.hidden = true;
  }
  if (scheduleChoice !== "custom") { /* preset selection already styled */ }
}

async function confirmScheduledSend() {
  const session = scheduleSession;
  if (!session) return;
  const stamp = zonedWallTimeToUtc(scheduleDate.value, scheduleTime.value);
  if (!stamp || stamp.getTime() <= Date.now() + 5000) {
    scheduleWarning.hidden = false;
    scheduleWarning.textContent = t("ui.alt8mail-intelligence-pre-send-spell-che.choose-a-future-date-and-time");
    return;
  }
  const error = validateComposeRecipients(session);
  if (error) { showToast(error); return; }
  const button = scheduleConfirm;
  button.disabled = true;
  button.textContent = t("ui.alt8mail-intelligence-pre-send-spell-che.scheduling");
  if (!(await validateComposeEncryption(session))) {
    button.disabled = false;
    button.textContent = t("ui.alt8mail-intelligence-pre-send-spell-che.schedule-send");
    return;
  }
  const clientSide = session.clientSide || clientSideEncryption();
  try {
    const spellingOK = await runSpellCheckBeforeSend(session, "schedule");
    if (!spellingOK) return;
    if (!clientSide && !(await runComposeDataProtectionCheck(session))) return;
    if (!(await confirmSendIntent(session, stamp))) return;
    let payload = composeSendPayload(session, { scheduledFor: stamp.toISOString() });
    if (clientSide) {
      const encryptedMIME = await encryptClientComposeMIME(session);
      payload = {
        ...payload,
        attachments: [],
        bodyText: "",
        bodyHtml: "",
        encrypt: true,
        protocol: clientComposeProtocol(session),
        clientEncrypted: true,
        clientEncryptedMIME: encryptedMIME
      };
    } else {
      await flushDraft(session);
    }
    const data = await api("/api/send", {
      method: "POST",
      body: payload
    });
    state.messages = state.messages.filter((message) => message.id !== session.draftId);
    if (clientSide || session.localDraft) await deleteClientDraft(session.draftId).catch(() => {});
    removeComposeSessionUi(session.id);
    rebuildIndex();
    renderFolders();
    renderList();
    if (data.outbound) state.outbound = data.outbound;
    state.pendingSends.push(data.queued);
    updateOutboundUi();
    updateScheduledUi();
    stopOutboxPolling();
    startOutboxPolling();
    scheduleOverlay.hidden = true;
    scheduleSession = null;
    showToast(t("ui.status-bar-quota-pending-sends.scheduled-for", { when: formatDateTimeFull(data.queued.sendAt) }), clientSide ? "" : t("ui.status-bar-quota-pending-sends.undo"), clientSide ? undefined : async () => {
      await cancelQueuedSend(data.queued.id);
    }, { duration: 12000 });
  } catch (error) {
    scheduleWarning.hidden = false;
    if (clientSide && error.code === "DIRECTORY_KEY_CHANGED") {
      session.encryptionCheck = { recipients: 0, missing: [], directoryChanged: error.changes || [], checked: true };
      renderComposeEncryptionStatus(session);
      scheduleWarning.textContent = t("ui.compose.client-e2ee-directory-key-changed", { emails: (error.recipients || []).join(", ") });
      return;
    }
    const browserEncryptionError = clientSide && error.status === undefined;
    scheduleWarning.textContent = browserEncryptionError ? t("ui.compose.client-e2ee-failed") : error.message;
    if (error.code === "DOMAIN_DNS_REQUIRED") openDomainBlockedDialog(error.details || {});
    else if (error.code === "DLP_BLOCKED") await showDataProtectionBlock(error);
    else if (!browserEncryptionError) showError(error);
  } finally {
    button.disabled = false;
    button.innerHTML = "<svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-send\"/></svg>" + t("ui.alt8mail-intelligence-pre-send-spell-che.schedule-send");
  }
}

function closeScheduleDialog() {
  scheduleOverlay.hidden = true;
  scheduleSession = null;
}

function swapComposeIdentitySignature(session, fromEmail) {
  const current = session.autoSignature;
  if (!current || (!current.text && !current.html)) return;
  const next = defaultSignatureForCompose(session.signatureContext || "new", fromEmail);
  const nextText = next ? signaturePlainValue(next) : "";
  const nextHTML = next ? signatureRichValue(next) : "";
  let changed = false;
  if (session.htmlMode) {
    const oldHTML = current.html || textToEditorHTML(current.text);
    const replacement = nextHTML || textToEditorHTML(nextText);
    if (oldHTML && session.bodyHtml.includes(oldHTML)) {
      session.bodyHtml = sanitizeEditorHTML(session.bodyHtml.replace(oldHTML, replacement));
      const editor = session.el?.querySelector("[data-compose-editor]");
      if (editor) { editor.innerHTML = session.bodyHtml; normalizeEditorImageSources(editor); }
      session.body = editorPlainText(session.bodyHtml);
      changed = true;
    }
  } else {
    const oldText = current.text || htmlToText(current.html);
    if (oldText && session.body.trimStart().startsWith(oldText.trimStart())) {
      const rest = session.body.slice(session.body.indexOf(oldText) + oldText.length).replace(/^\s*\n+/, "");
      session.body = [nextText, rest].filter((part) => part && part.trim()).join("\n\n");
      session.bodyHtml = textToEditorHTML(session.body);
      const textarea = session.el?.querySelector('[data-compose-field="body"]');
      if (textarea) textarea.value = session.body;
      changed = true;
    }
  }
  if (!changed) return;
  session.autoSignature = next ? { id: next.id, text: nextText, html: nextHTML } : null;
  session.dirty = true;
  updateComposeStatus(session);
  scheduleComposeSave(session);
}

function updateComposeField(session, target) {
  const field = target.getAttribute("data-compose-field");
  if (!field) return;
  if (RECIPIENT_FIELDS.includes(field)) {
    session.recipientInput[field] = target.value;
    session.dirty = true;
    session.error = null;
    target.removeAttribute("aria-invalid");
    const wrap = target.closest("[data-compose-field-wrap]");
    if (wrap) wrap.classList.remove("is-error");
    updateRecipientSuggestions(session, field);
    if (session.encrypt) scheduleComposeEncryptionCheck(session);
    return;
  }
  const value = target.type === "checkbox" ? target.checked : target.value;
  session[field] = value;
  if (field === "fromEmail") {
    session.accountId = composeAccountIdFor(value);
    swapComposeIdentitySignature(session, value);
  }
  session.dirty = true;
  session.error = null;
  if (field === "to") {
    const wrap = target.closest('[data-compose-field-wrap="to"]');
    if (wrap) wrap.classList.remove("is-error");
  }
  if (field === "subject") {
    const title = session.el.querySelector("[data-compose-title]");
    if (title) title.textContent = session.subject.trim() || t("ui.alt8mail-intelligence-pre-send-spell-che.new-message");
    renderComposeDockTabs();
  } else if (field === "to" || field === "cc") {
    renderComposeDockTabs();
  }
  if ((field === "encrypt" && value !== true) || field === "protocol") session.encryptionCheck = null;
  if (["fromEmail", "priority", "receipt", "delivery", "saveCopy", "encrypt", "sign", "protocol"].includes(field)) updateComposeOptions(session);
  if (field === "encrypt" || field === "sign" || field === "protocol") scheduleComposeEncryptionCheck(session, 0);
  updateComposeStatus(session);
  scheduleComposeSave(session);
}

function updateComposeEditor(session, editor) {
  if (!session || !editor) return;
  session.bodyHtml = sanitizeEditorHTML(stripEditorArtifacts(editor.innerHTML));
  session.body = editorPlainText(stripEditorArtifacts(editor.innerHTML));
  session.dirty = true;
  session.error = null;
  updateComposeStatus(session);
  scheduleComposeSave(session);
}

function setComposeBodyMarkup(session, html, text = "") {
  if (!session?.el) return;
  const value = String(html || "");
  session.bodyHtml = sanitizeEditorHTML(value);
  session.body = text || editorPlainText(session.bodyHtml);
  session.dirty = true;
  session.error = null;
  const editor = session.el.querySelector("[data-compose-editor]");
  const textarea = session.el.querySelector('[data-compose-field="body"]');
  if (editor) {
    editor.innerHTML = session.bodyHtml;
    normalizeEditorImageSources(editor);
    editor.scrollTop = 0;
  } else if (textarea) {
    textarea.value = session.body;
    textarea.scrollTop = 0;
  }
  updateComposeStatus(session);
  scheduleComposeSave(session);
}

function setComposeBodyText(session, text) {
  const value = String(text || "");
  setComposeBodyMarkup(session, textToEditorHTML(value), value);
}

function refreshComposeEditorContent(session) {
  if (!session?.el) return;
  const editor = session.el.querySelector("[data-compose-editor]");
  if (editor) { editor.innerHTML = sanitizeEditorHTML(session.bodyHtml || textToEditorHTML(session.body || "")); normalizeEditorImageSources(editor); }
  const textarea = session.el.querySelector('[data-compose-field="body"]');
  if (textarea) textarea.value = session.body || "";
}

function beginComposePointer(event, session, mode) {
  if (isMobile() || !session || session.mode !== "floating") return;
  if (event.button !== undefined && event.button !== 0) return;
  const rect = session.el.getBoundingClientRect();
  session.left = rect.left;
  session.top = rect.top;
  session.width = rect.width;
  session.height = rect.height;
  session.manual = true;
  session.el.style.left = rect.left + "px";
  session.el.style.top = rect.top + "px";
  session.el.style.right = "auto";
  session.el.style.bottom = "auto";
  session.el.style.width = rect.width + "px";
  session.el.style.height = rect.height + "px";
  composePointer = { session, mode, startX: event.clientX, startY: event.clientY, left: rect.left, top: rect.top, width: rect.width, height: rect.height };
  document.body.dataset.composePointer = mode;
  document.addEventListener("pointermove", onComposePointerMove);
  document.addEventListener("pointerup", endComposePointer, { once: true });
  document.addEventListener("pointercancel", endComposePointer, { once: true });
  event.preventDefault();
}

function onComposePointerMove(event) {
  if (!composePointer) return;
  const { session, mode, startX, startY, left, top, width, height } = composePointer;
  const dx = event.clientX - startX;
  const dy = event.clientY - startY;
  const margin = 12;
  if (mode === "drag") {
    session.left = Math.max(margin, Math.min(left + dx, window.innerWidth - width - margin));
    session.top = Math.max(margin, Math.min(top + dy, window.innerHeight - height - margin));
    session.el.style.left = session.left + "px";
    session.el.style.top = session.top + "px";
  } else {
    session.width = Math.max(380, Math.min(width + dx, Math.max(380, window.innerWidth - left - margin)));
    session.height = Math.max(300, Math.min(height + dy, Math.max(300, window.innerHeight - top - margin)));
    session.el.style.width = session.width + "px";
    session.el.style.height = session.height + "px";
  }
}

function endComposePointer() {
  if (!composePointer) return;
  composePointer = null;
  delete document.body.dataset.composePointer;
  document.removeEventListener("pointermove", onComposePointerMove);
}

/* ============================================================
   status bar + quota + pending sends
   ============================================================ */
function renderMailClientSetup() {
  const host = document.getElementById("mailClientDetails");
  if (!host) return;
  const data = state.mailClient;
  if (!data) {
    host.innerHTML = `<div class="settings-note">${t("ui.status-bar-quota-pending-sends.server-connection-details-are-available-after-th")}</div>`;
    return;
  }
  const card = (label, protocol, details, tone = "") => {
    if (!details) return "";
    return `<div class="mail-client-card${tone ? " " + tone : ""}">
      <div class="mail-client-card-head"><span class="mail-client-protocol">${esc(protocol)}</span>${tone === "recommended" ? "<span class=\"mail-client-recommended\">" + t("ui.alt8mail-intelligence-pre-send-spell-che.recommended") + "</span>" : ""}</div>
      <strong class="mail-client-host">${esc(details.host || data.host || "—")}</strong>
      <dl class="mail-client-fields">
        <div><dt>${t("ui.status-bar-quota-pending-sends.port")}</dt><dd>${esc(details.port || "—")}</dd></div>
        <div><dt>${t("ui.status-bar-quota-pending-sends.security")}</dt><dd>${esc(details.security || "SSL/TLS")}</dd></div>
        <div><dt>${t("ui.status-bar-quota-pending-sends.username")}</dt><dd class="wrap-anywhere">${esc(data.username || state.user?.email || "—")}</dd></div>
      </dl>
      <span class="mail-client-label">${esc(label)}</span>
    </div>`;
  };
  host.innerHTML = [
    card(t("ui.status-bar-quota-pending-sends.incoming-mail"), "IMAP", data.imap, "recommended"),
    card(t("ui.status-bar-quota-pending-sends.incoming-mail"), "POP3", data.pop3),
    card(t("ui.status-bar-quota-pending-sends.outgoing-mail"), "SMTP", data.smtp)
  ].join("") || `<div class="settings-note">${t("ui.status-bar-quota-pending-sends.your-administrator-has-not-published-mail-client")}</div>`;
  const note = document.getElementById("mailClientNote");
  if (note && data.note) note.textContent = data.note;
}

function updateQuotaUi(quota = null) {
  if (quota) state.quota = quota;
  const data = state.quota;
  if (!data) return;
  const label = t("shell.quotaLabel", { used: formatBytes(data.usedBytes), limit: formatBytes(data.limitBytes) });
  const percent = Math.min(100, Math.max(0, Number(data.percent) || 0));
  const quotaLabel = document.getElementById("quotaLabel");
  const quotaPct = document.getElementById("quotaPct");
  const quotaFill = document.getElementById("quotaBarFill");
  const quotaSource = document.getElementById("quotaSource");
  if (quotaLabel) quotaLabel.textContent = label;
  if (quotaPct) quotaPct.textContent = `${percent.toFixed(percent % 1 ? 1 : 0)}%`;
  if (quotaFill) quotaFill.style.width = `${percent}%`;
  if (quotaSource) quotaSource.textContent = t("shell.quotaSource");
  const statusFill = document.getElementById("statusQuotaFill");
  const statusLabel = document.getElementById("statusQuotaLabel");
  if (statusFill) statusFill.style.width = `${percent}%`;
  if (statusLabel) statusLabel.textContent = label;
  const storageText = document.getElementById("accountStorageText");
  const storageBar = document.getElementById("accountStorageBar");
  const storagePct = document.getElementById("accountStoragePct");
  if (storageText) storageText.textContent = t("shell.storageUsed", { used: formatBytes(data.usedBytes), limit: formatBytes(data.limitBytes) });
  if (storageBar) storageBar.style.width = `${percent}%`;
  if (storagePct) storagePct.textContent = `${percent.toFixed(percent % 1 ? 1 : 0)}%`;
  if (state.statusPop === "quota") renderStatusPop();
}

function outboundIsUnlimited(data) {
  return Boolean(data?.unlimited) || !(Number(data?.limit) > 0);
}

function updateOutboundUi() {
  const data = state.outbound;
  const outboundChip = document.getElementById("outboundChip");
  const outboundText = document.getElementById("outboundText");
  if (data) {
    const value = data.usedWithQueued != null ? data.usedWithQueued : data.used;
    const queuedUnits = data.queuedRecipients != null ? data.queuedRecipients : data.queued;
    const unlimited = outboundIsUnlimited(data);
    if (outboundText) outboundText.textContent = unlimited
      ? t("ui.status-bar-quota-pending-sends.sent-no-cap", { value, queued: queuedUnits ? t("ui.status-bar-quota-pending-sends.queued-suffix", { count: queuedUnits }) : "" })
      : `${value} / ${data.limit} sent${queuedUnits ? ` · ${queuedUnits} queued` : ""}`;
    if (outboundChip) outboundChip.title = unlimited
      ? t("ui.status-bar-quota-pending-sends.no-mailbox-cap-detail", { used: data.used, hours: data.windowHours, queued: queuedUnits ? t("ui.status-bar-quota-pending-sends.queued-suffix-comma", { count: queuedUnits }) : "" })
      : t("ui.status-bar-quota-pending-sends.outbound-cap-detail", { used: data.used, hours: data.windowHours, queued: queuedUnits ? t("ui.status-bar-quota-pending-sends.queued-suffix-comma", { count: queuedUnits }) : "" });
    const usedValue = document.getElementById("outboundUsedValue");
    const limitChip = document.getElementById("outboundLimitChip");
    const fill = document.getElementById("outboundBarFill");
    const reset = document.getElementById("outboundResetText");
    const pct = document.getElementById("outboundPercentText");
    const percent = Math.min(100, Math.max(0, Number(data.percent) || 0));
    if (usedValue) usedValue.textContent = String(value);
    if (limitChip) limitChip.textContent = unlimited ? t("ui.status-bar-quota-pending-sends.no-daily-cap") : `of ${data.limit} per ${data.windowHours}h`;
    if (fill) fill.style.width = `${percent}%`;
    if (reset) reset.textContent = data.queued ? t("ui.status-bar-quota-pending-sends.queued-in-undo", { count: data.queued }) : t("ui.status-bar-quota-pending-sends.rolling-window", { hours: data.windowHours });
    if (pct) pct.textContent = unlimited ? t("ui.status-bar-quota-pending-sends.no-cap") : `${percent.toFixed(percent % 1 ? 1 : 0)}% used`;
  }
  if (state.statusPop === "outbound") renderStatusPop();
}

function updatePendingUi() {
  const chip = document.getElementById("pendingChip");
  const text = document.getElementById("pendingText");
  if (!chip) return;
  const pending = state.pendingSends.filter((item) => !item.scheduled);
  if (!pending.length) {
    chip.hidden = true;
    if (pendingTickTimer) { clearInterval(pendingTickTimer); pendingTickTimer = null; }
    if (state.statusPop === "pending" && !statusPop.hidden) renderStatusPop();
    return;
  }
  chip.hidden = false;
  const first = pending.slice().sort((a, b) => Date.parse(a.sendAt) - Date.parse(b.sendAt))[0];
  const remaining = Date.parse(first.sendAt) - Date.now();
  if (text) text.textContent = pending.length === 1
    ? t("ui.status-bar-quota-pending-sends.sending-in", { countdown: formatCountdown(remaining) })
    : `${pending.length} sending · ${formatCountdown(remaining)}`;
  if (!pendingTickTimer) pendingTickTimer = setInterval(() => updatePendingUi(), 500);
  if (state.statusPop === "pending" && !statusPop.hidden) renderStatusPop();
}

function updateScheduledUi() {
  if (!scheduledChip) return;
  const scheduled = state.pendingSends.filter((item) => item.scheduled).sort((a, b) => Date.parse(a.sendAt) - Date.parse(b.sendAt));
  const countChanged = state.scheduledCount !== scheduled.length;
  state.scheduledCount = scheduled.length;
  if (!scheduled.length) {
    scheduledChip.hidden = true;
  } else {
    scheduledChip.hidden = false;
    const first = scheduled[0];
    const text = document.getElementById("scheduledText");
    if (text) text.textContent = scheduled.length === 1 ? t("shell.scheduledAt", { time: formatListWhen(first.sendAt) }) : tn("shell.scheduledCount", scheduled.length, { count: scheduled.length });
    scheduledChip.title = scheduled.map((item) => `${item.subject} · ${formatDateTimeFull(item.sendAt)}`).join("\n");
  }
  if (countChanged) renderFolders();
  if (state.statusPop === "scheduled" && !statusPop.hidden) renderStatusPop();
  if (state.task === "scheduled") {
    renderScheduled();
    syncStatusRange();
    syncStatusContext();
  }
}

function startOutboxPolling() {
  if (outboxPollTimer) return;
  if (!state.pendingSends.length) return;
  const hasUndo = state.pendingSends.some((item) => !item.scheduled);
  const earliest = Math.min(...state.pendingSends.map((item) => Date.parse(item.sendAt) || Date.now()));
  const delay = hasUndo ? 1500 : Math.min(30000, Math.max(1000, earliest - Date.now() + 500));
  outboxPollTimer = setTimeout(async () => {
    outboxPollTimer = null;
    if (outboxPollBusy) { startOutboxPolling(); return; }
    outboxPollBusy = true;
    try {
      const data = await api("/api/outbox");
      const previous = state.pendingSends.slice();
      state.pendingSends = data.pending || [];
      if (data.outbound) state.outbound = data.outbound;
      updateOutboundUi();
      updatePendingUi();
      updateScheduledUi();
      const emptied = previous.length > 0 && state.pendingSends.length === 0;
      const hadScheduled = previous.some((item) => item.scheduled);
      if (emptied) {
        stopOutboxPolling();
        await refreshMailbox({ quiet: true });
        showToast(hadScheduled ? t("ui.status-bar-quota-pending-sends.scheduled-message-sent") : t("ui.status-bar-quota-pending-sends.message-sent"));
      } else {
        startOutboxPolling();
      }
    } catch {
      startOutboxPolling();
    } finally {
      outboxPollBusy = false;
    }
  }, delay);
}

function stopOutboxPolling() {
  if (outboxPollTimer) clearTimeout(outboxPollTimer);
  outboxPollTimer = null;
  outboxPollBusy = false;
}

function statusPopMarkup(kind) {
  if (kind === "quota") {
    const data = state.quota;
    if (!data) return "<p>" + t("ui.status-bar-quota-pending-sends.quota-unavailable") + "</p>";
    return `<div class="status-pop-metric"><strong>${formatBytes(data.usedBytes)}</strong><span>of ${formatBytes(data.limitBytes)} used</span></div>
      <div class="usage-bar"><span style="width:${Math.min(100, data.percent)}%"></span></div>
      <div class="status-pop-meta"><span>${t("ui.status-bar-quota-pending-sends.source-alt8mail-storage")}</span><span>${data.percent.toFixed(data.percent % 1 ? 1 : 0)}%</span></div>
      <div class="status-breakdown">${(data.folders || []).map((folder) => `<div><span>${esc(folder.label)}</span><span>${formatBytes(folder.bytes)}</span></div>`).join("")}</div>
      <button class="btn-secondary status-refresh" data-status-refresh="quota" type="button"><svg class="icon" aria-hidden="true"><use href="#i-refresh"/></svg>${t("ui.status-bar-quota-pending-sends.refresh-from-alt8mail")}</button>`;
  }
  if (kind === "outbound") {
    const data = state.outbound;
    if (!data) return "<p>" + t("ui.status-bar-quota-pending-sends.usage-unavailable") + "</p>";
    const value = data.usedWithQueued != null ? data.usedWithQueued : data.used;
    const unlimited = outboundIsUnlimited(data);
    const queuedUnits = data.queuedRecipients != null ? data.queuedRecipients : data.queued;
    return `<div class="status-pop-metric"><strong>${value}</strong><span>${unlimited ? t("ui.status-bar-quota-pending-sends.messages-no-daily-cap") : t("ui.status-bar-quota-pending-sends.of-messages", { limit: data.limit })}</span></div>
      <div class="usage-bar"><span style="width:${unlimited ? 0 : Math.min(100, data.percent)}%"></span></div>
      <div class="status-pop-meta"><span>${esc(t("ui.status-bar-quota-pending-sends.rolling-window", { hours: data.windowHours }))}</span><span>${esc(tn("ui.status-bar-quota-pending-sends.queued-count", queuedUnits, { count: queuedUnits }))}</span></div>
      <div class="status-breakdown"><div><span>${t("ui.status-bar-quota-pending-sends.sent")}</span><span>${data.used}</span></div><div><span>${t("ui.status-bar-quota-pending-sends.waiting-in-undo-queue")}</span><span>${queuedUnits}</span></div><div><span>${t("ui.status-bar-quota-pending-sends.remaining")}</span><span>${unlimited ? t("ui.status-bar-quota-pending-sends.unlimited") : data.remaining}</span></div></div>
      <p class="status-pop-note">${t("ui.status-bar-quota-pending-sends.enforced-per-user-by-alt8mail-with-a-per-mailbox")}</p>
      <button class="btn-secondary status-refresh" data-status-refresh="outbound" type="button"><svg class="icon" aria-hidden="true"><use href="#i-refresh"/></svg>${t("ui.status-bar-quota-pending-sends.refresh-usage")}</button>`;
  }
  if (kind === "pending") {
    const pending = state.pendingSends.filter((item) => !item.scheduled);
    if (!pending.length) return "<p class=\"status-pop-note\">" + t("ui.status-bar-quota-pending-sends.there-are-no-messages-waiting-to-send") + "</p>";
    return `<div class="pending-list">${pending.map((item) => {
      const remaining = Date.parse(item.sendAt) - Date.now();
      return `<div class="pending-item">
        <div class="pending-main"><strong>${esc(item.subject)}</strong><span>To ${esc((item.to || []).map((person) => person.name || person.email).join(", "))}</span></div>
        <span class="pending-time">${formatCountdown(remaining)}</span>
        <button class="link-btn" data-cancel-send="${esc(item.id)}" type="button" ${remaining <= 0 ? "disabled" : ""}>${esc(item.clientSide || clientSideEncryption() ? t("tasks.action.cancel") : t("ui.status-bar-quota-pending-sends.undo"))}</button>
      </div>`;
    }).join("")}</div><p class="status-pop-note">${t("ui.status-bar-quota-pending-sends.messages-can-be-undone-until-the-countdown-ends")}${pending.some((item) => item.clientSide) || clientSideEncryption() ? ` ${esc(t("ui.status-bar-quota-pending-sends.client-side-cancel-note"))}` : ""}</p>`;
  }
  if (kind === "scheduled") {
    const scheduled = state.pendingSends.filter((item) => item.scheduled).sort((a, b) => Date.parse(a.sendAt) - Date.parse(b.sendAt));
    if (!scheduled.length) return "<p class=\"status-pop-note\">" + t("ui.status-bar-quota-pending-sends.no-messages-are-scheduled") + "</p>";
    return `<div class="pending-list">${scheduled.map((item) => `<div class="pending-item scheduled">
      <div class="pending-main"><strong>${esc(item.subject || t("mail.list.noSubject"))}</strong><span>${esc(formatDateTimeFull(item.sendAt))}</span><span class="pending-to">To ${esc(scheduledRecipients(item))}</span></div>
      <span class="pending-time">${esc(formatRelativeTime(item.sendAt))}</span>
      <div class="scheduled-item-actions">
        ${item.clientSide || !clientSideEncryption() ? `<button class="link-btn" data-scheduled-send-now="${esc(item.id)}" type="button">${t("ui.status-bar-quota-pending-sends.send-now")}</button>` : ""}
        ${item.clientSide || clientSideEncryption() ? "" : `<button class="link-btn" data-scheduled-edit="${esc(item.id)}" type="button">${t("tasks.detail.edit")}</button>`}
        <button class="link-btn is-danger" data-cancel-send="${esc(item.id)}" type="button">${t("tasks.action.cancel")}</button>
      </div>
    </div>`).join("")}</div><p class="status-pop-note">${t("ui.status-bar-quota-pending-sends.send-now-edit-or-cancel-any-message-until-its-sc")}${scheduled.some((item) => item.clientSide) || clientSideEncryption() ? ` ${esc(t("ui.status-bar-quota-pending-sends.client-side-cancel-note"))}` : ""}</p><button class="btn-secondary status-open-scheduled" data-open-scheduled type="button"><svg class="icon" aria-hidden="true"><use href="#i-calendar-clock"/></svg>${t("ui.status-bar-quota-pending-sends.open-scheduled-center")}</button>`;
  }
  return "";
}

function renderStatusPop() {
  const kind = state.statusPop;
  if (!kind) return;
  statusPopTitle.textContent = kind === "quota" ? t("ui.status-bar-quota-pending-sends.mailbox-storage") : t(kind === "outbound" ? "ui.status-bar-quota-pending-sends.outbound-sending" : kind === "scheduled" ? "ui.status-bar-quota-pending-sends.scheduled-messages" : "ui.status-bar-quota-pending-sends.sending-queue");
  statusPopBody.innerHTML = statusPopMarkup(kind);
  $$("[data-cancel-send]", statusPopBody).forEach((button) => {
    button.addEventListener("click", async () => {
      button.disabled = true;
      await cancelQueuedSend(button.getAttribute("data-cancel-send"));
    });
  });
  $$("[data-status-refresh]", statusPopBody).forEach((button) => {
    button.addEventListener("click", async () => {
      button.disabled = true;
      try {
        if (button.getAttribute("data-status-refresh") === "quota") {
          const quota = await api("/api/quota");
          updateQuotaUi(quota);
        } else {
          const data = await api("/api/outbound");
          state.outbound = data.outbound || data;
          updateOutboundUi();
        }
      } catch (error) { showError(error); }
    });
  });
}

function openStatusPop(kind) {
  const allowed = ["quota", "outbound", "pending", "scheduled"];
  state.statusPop = allowed.includes(kind) ? kind : "quota";
  renderStatusPop();
  statusPop.hidden = false;
}

function closeStatusPop() {
  state.statusPop = null;
  statusPop.hidden = true;
}

function syncStatusRange() {
  if (state.task === "calendar") {
    const prefix = `${state.calendarYear}-${String(state.calendarMonth + 1).padStart(2, "0")}`;
    const count = state.calendarEvents.filter((event) => String(event.date).startsWith(prefix)).length;
    statusRange.textContent = tn("shell.eventsThisMonth", count, { count });
  } else if (state.task === "people") {
    statusRange.textContent = peopleCount.textContent;
  } else if (state.task === "tasks") {
    const open = state.tasks.filter((task) => task.status === "open").length;
    statusRange.textContent = t("shell.taskSummary", { open, completed: state.tasks.length - open });
  } else if (state.task === "files") {
    statusRange.textContent = tn("shell.fileItems", state.files.length, { count: state.files.length });
  } else if (state.task === "scheduled") {
    statusRange.textContent = tn("shell.scheduledCount", scheduledItems().length, { count: scheduledItems().length });
  } else if (state.task === "settings") {
    statusRange.textContent = t("shell.workspaceSettings");
  } else if (!state.query) {
    const page = currentMailPage();
    const total = page
      ? (inboxViewIndividual() ? (page.totalMessages || page.total) : page.total)
      : state.viewThreads.length;
    statusRange.textContent = state.viewThreads.length ? t("mail.range", { start: 1, shown: state.viewThreads.length, total, unit: viewUnit(total) }) : t("mail.emptyRange", { unit: viewUnit(0) });
  }
}

function syncStatusContext() {
  if (state.offline) { statusMid.textContent = t("shell.offlineChangesRetry"); return; }
  if (state.task === "calendar") statusMid.textContent = t("shell.calendarSynced");
  else if (state.task === "people") statusMid.textContent = t("shell.directorySynced");
  else if (state.task === "tasks") statusMid.textContent = t("shell.tasksWorkspaceSynced");
  else if (state.task === "files") { const connected = state.storageProviders.filter((provider) => provider.connected).length; statusMid.textContent = tn("shell.cabinetSynced", connected, { count: connected }); }
  else if (state.task === "scheduled") statusMid.textContent = t("shell.outboxSynced");
  else if (state.task === "settings") statusMid.textContent = t("shell.policyManaged");
  else if (state.query) statusMid.textContent = t("shell.searchingMailbox");
  else statusMid.textContent = t("shell.syncedJustNow");
}

/* ============================================================
   tasks
   ============================================================ */
const TASK_FILTERS = [
  { id: "all", key: "tasks.filter.all" },
  { id: "open", key: "tasks.filter.open" },
  { id: "mine", key: "tasks.filter.mine" },
  { id: "team", key: "tasks.filter.team" },
  { id: "today", key: "tasks.filter.today" },
  { id: "overdue", key: "tasks.filter.overdue" },
  { id: "completed", key: "tasks.filter.completed" }
];

function taskIsMine(task) {
  return normalizeEmail(task.assignee && task.assignee.email) === normalizeEmail(state.user && state.user.email);
}

function taskDueState(task) {
  const today = dateKeyInZone(new Date());
  if (!task.due) return "none";
  if (task.status === "done") return "done";
  if (task.due < today) return "overdue";
  if (task.due === today) return "today";
  return "upcoming";
}

function taskMatchesFilter(task) {
  const filter = state.taskFilter;
  if (filter === "open" && task.status === "done") return false;
  if (filter === "mine" && !taskIsMine(task)) return false;
  if (filter === "team" && taskIsMine(task)) return false;
  if (filter === "today" && (task.status === "done" || task.due !== dateKeyInZone(new Date()))) return false;
  if (filter === "overdue" && taskDueState(task) !== "overdue") return false;
  if (filter === "completed" && task.status !== "done") return false;
  const query = state.query.toLowerCase();
  if (query) {
    const haystack = [task.title, task.notes, task.linkedSubject, ...(task.tags || []), task.assignee && task.assignee.name].join(" ").toLowerCase();
    if (!haystack.includes(query)) return false;
  }
  return true;
}

const TASK_KANBAN_KEYS = {
  todo: "tasks.kanban.todo", in_progress: "tasks.kanban.in_progress",
  review: "tasks.kanban.review", done: "tasks.kanban.done"
};

function taskPriorityLabel(priority) {
  return t({ low: "tasks.priority.low", normal: "tasks.priority.normal", high: "tasks.priority.high", urgent: "tasks.priority.urgent" }[priority] || "tasks.priority.normal");
}

function taskDueLabel(task) {
  if (!task.due) return t("tasks.noDueDate");
  const date = formatDateOnly(task.due);
  if (!task.dueTime) return date;
  const stamp = zonedWallTimeToUtc(task.due, task.dueTime);
  return stamp ? `${date} · ${formatClock(stamp)}` : date;
}

function renderTasks() {
  if (!tasksView || !taskList) return;
  const filtered = state.tasks
    .filter(taskMatchesFilter)
    .sort((a, b) => {
      if (a.status !== b.status) return a.status === "done" ? 1 : -1;
      if (a.due && b.due && a.due !== b.due) return a.due.localeCompare(b.due);
      if (a.due && !b.due) return -1;
      if (!a.due && b.due) return 1;
      const weight = { urgent: 0, high: 1, normal: 2, low: 3 };
      return (weight[a.priority] ?? 2) - (weight[b.priority] ?? 2);
    });
  if (!state.editingTaskId && !filtered.some((task) => task.id === state.selectedTaskId)) {
    state.selectedTaskId = filtered[0] ? filtered[0].id : null;
  }
  const open = state.tasks.filter((task) => task.status === "open").length;
  const done = state.tasks.length - open;
  const today = dateKeyInZone(new Date());
  const dueToday = state.tasks.filter((task) => task.status === "open" && task.due === today).length;
  const overdue = state.tasks.filter((task) => taskDueState(task) === "overdue").length;
  tasksMeta.textContent = t("tasks.meta", { open, dueToday, overdue });
  taskStats.innerHTML = `
    <button class="task-stat" data-task-filter="all" type="button"><span class="task-stat-value">${state.tasks.length}</span><span class="task-stat-label">${esc(t("tasks.stat.all"))}</span><span class="task-stat-hint">${esc(tn("tasks.stat.completedHint", done, { count: done }))}</span></button>
    <button class="task-stat is-accent" data-task-filter="today" type="button"><span class="task-stat-value">${dueToday}</span><span class="task-stat-label">${esc(t("tasks.stat.dueToday"))}</span><span class="task-stat-hint">${esc(t("tasks.stat.planDay"))}</span></button>
    <button class="task-stat${overdue ? " is-danger" : ""}" data-task-filter="overdue" type="button"><span class="task-stat-value">${overdue}</span><span class="task-stat-label">${esc(t("tasks.stat.overdue"))}</span><span class="task-stat-hint">${esc(overdue ? t("tasks.stat.needsAttention") : t("tasks.stat.allClear"))}</span></button>
    <button class="task-stat" data-task-filter="completed" type="button"><span class="task-stat-value">${done}</span><span class="task-stat-label">${esc(t("tasks.stat.completed"))}</span><span class="task-stat-hint">${esc(t("tasks.stat.workspaceTotal"))}</span></button>`;
  taskFilters.innerHTML = TASK_FILTERS.map((filter) => {
    const count = state.tasks.filter((task) => {
      const previous = state.taskFilter;
      state.taskFilter = filter.id;
      const matched = taskMatchesFilter(task);
      state.taskFilter = previous;
      return matched;
    }).length;
    return `<button class="chip${state.taskFilter === filter.id ? " is-active" : ""}" data-task-filter="${filter.id}" type="button">${esc(t(filter.key))}${count ? `<span class="chip-count">${count}</span>` : ""}</button>`;
  }).join("");
  taskList.innerHTML = filtered.length ? filtered.map((task) => {
    const dueState = taskDueState(task);
    const selected = task.id === state.selectedTaskId;
    return `<div class="task-row${selected ? " is-selected" : ""}${task.status === "done" ? " is-done" : ""}" data-task-id="${esc(task.id)}" tabindex="0" role="button" aria-pressed="${selected}">
      <button class="task-check${task.status === "done" ? " is-done" : ""}" data-task-toggle="${esc(task.id)}" type="button" aria-label="${esc(task.status === "done" ? t("tasks.row.reopen") : t("tasks.row.markComplete"))}" aria-pressed="${task.status === "done"}"><svg class="icon" aria-hidden="true"><use href="#i-check"/></svg></button>
      <div class="task-row-main">
        <div class="task-row-title">${esc(task.title)}</div>
        <div class="task-row-meta">
          <span class="task-priority ${esc(task.priority)}">${esc(taskPriorityLabel(task.priority))}</span>
          <span class="task-due ${dueState}">${dueState === "overdue" ? esc(t("tasks.row.overduePrefix")) : ""}${esc(taskDueLabel(task))}</span>
          ${task.linkedThreadId ? "<span class=\"task-linked\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-mail\"/></svg>" + t("ui.tasks.esc-t-tasks-row-email") + "</span>" : ""}
        </div>
        ${(task.tags || []).length ? `<div class="task-tags">${task.tags.map((tag) => `<span>${esc(tag)}</span>`).join("")}</div>` : ""}
      </div>
      ${avatar(task.assignee, "sm")}
    </div>`;
  }).join("") : `<div class="task-empty"><svg class="icon" aria-hidden="true"><use href="#i-task"/></svg><strong>${esc(t("tasks.list.emptyTitle"))}</strong><span>${esc(state.query ? t("tasks.list.emptySearch") : t("tasks.list.emptyCreate"))}</span></div>`;
  renderTaskDetail();
  syncStatusRange();
  syncStatusContext();
  updateTasksBadge();
  renderReminderStack();
}

function renderTaskDetail() {
  if (!taskDetail) return;
  if (state.editingTaskId) {
    const task = state.tasks.find((item) => item.id === state.editingTaskId) || null;
    const editing = Boolean(task);
    const draftLink = editing ? null : state.taskDraftLink;
    const assigneeOptions = [{ name: state.user.name, email: state.user.email, initials: state.user.initials, color: state.user.color }, ...state.people]
      .map((person) => `<option value="${esc(person.email)}"${task && task.assignee && normalizeEmail(task.assignee.email) === normalizeEmail(person.email) ? " selected" : ""}>${esc(person.name)}</option>`).join("");
    taskDetail.innerHTML = `<form class="task-editor" id="taskEditorForm">
      <div class="task-detail-head"><button class="icon-btn task-detail-back" data-task-back type="button" aria-label="${esc(t("tasks.detail.back"))}"><svg class="icon" aria-hidden="true"><use href="#i-arrow-left"/></svg></button><div><span class="eyebrow">${esc(editing ? t("tasks.detail.editTask") : t("tasks.detail.newTask"))}</span><h2>${esc(editing ? t("tasks.detail.update") : draftLink ? t("tasks.detail.turnEmail") : t("tasks.detail.plan"))}</h2></div><button class="icon-btn" data-task-editor-close type="button" aria-label="${esc(t("tasks.detail.closeEditor"))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button></div>
      ${draftLink ? `<div class="task-linked-card task-linked-draft"><svg class="icon" aria-hidden="true"><use href="#i-mail"/></svg><div><strong>${esc(t("tasks.detail.linkedEmail"))}</strong><span>${esc(draftLink.subject)}</span></div><button class="link-btn" data-task-clear-link type="button">${esc(t("tasks.detail.remove"))}</button></div>` : ""}
      <label class="form-field"><span>${esc(t("tasks.field.title"))}</span><input id="taskTitleInput" type="text" value="${esc(task ? task.title : (draftLink?.subject || ""))}" placeholder="${esc(t("tasks.field.titlePlaceholder"))}" maxlength="200" required></label>
      <label class="form-field"><span>${esc(t("tasks.field.notes"))}</span><textarea id="taskNotesInput" rows="4" placeholder="${esc(t("tasks.field.notesPlaceholder"))}">${esc(task ? task.notes : (draftLink?.note || ""))}</textarea></label>
      <div class="form-row">
        <label class="form-field"><span>${esc(t("tasks.field.dueDate"))}</span><input id="taskDueInput" type="date" value="${esc(task ? task.due : "")}"></label>
        <label class="form-field"><span>${esc(t("tasks.field.dueTime"))}</span><input id="taskDueTimeInput" type="time" value="${esc(task ? task.dueTime : "")}"></label>
        <label class="form-field"><span>${esc(t("tasks.field.priority"))}</span><select id="taskPriorityInput">${["low", "normal", "high", "urgent"].map((value) => `<option value="${value}"${task && task.priority === value ? " selected" : ""}>${taskPriorityLabel(value)}</option>`).join("")}</select></label>
      </div>
      <div class="form-row">
        <label class="form-field"><span>${esc(t("tasks.field.kanban"))}</span><select id="taskKanbanInput">${["todo", "in_progress", "review", "done"].map((value) => `<option value="${value}"${task && (task.kanbanStatus || "todo") === value ? " selected" : ""}>${esc(t(TASK_KANBAN_KEYS[value] || value))}</option>`).join("")}</select></label>
        <label class="form-field"><span>${esc(t("tasks.field.parent"))}</span><select id="taskParentInput"><option value="">${esc(t("tasks.field.none"))}</option>${state.tasks.filter((item) => !task || item.id !== task.id).map((item) => `<option value="${esc(item.id)}"${task?.parentTaskId === item.id ? " selected" : ""}>${esc(item.title)}</option>`).join("")}</select></label>
        <label class="form-field"><span>${esc(t("tasks.field.depends"))}</span><select id="taskDependsInput"><option value="">${esc(t("tasks.field.none"))}</option>${state.tasks.filter((item) => !task || item.id !== task.id).map((item) => `<option value="${esc(item.id)}"${task?.dependsOnTaskId === item.id ? " selected" : ""}>${esc(item.title)}</option>`).join("")}</select></label>
      </div>
      <div class="form-row">
        <label class="form-field"><span>${esc(t("tasks.field.reminder"))}</span><input id="taskReminderInput" type="datetime-local" value="${task?.reminderAt ? esc(new Date(task.reminderAt).toISOString().slice(0, 16)) : ""}"></label>
        <label class="form-field"><span>${esc(t("tasks.field.recurrence"))}</span><input id="taskRecurrenceInput" value="${esc(task?.recurrenceRule || "")}" placeholder="${esc(t("ui.tasks.freq-weekly-byday-mo"))}"></label>
      </div>
      <label class="form-field"><span>${esc(t("tasks.field.assignee"))}</span><select id="taskAssigneeInput">${assigneeOptions}</select></label>
      <label class="form-field"><span>${esc(t("tasks.field.tags"))}</span><input id="taskTagsInput" type="text" value="${esc(task ? (task.tags || []).join(", ") : "")}" placeholder="${esc(t("tasks.field.tagsPlaceholder"))}"></label>
      ${task && task.linkedThreadId ? `<div class="task-linked-card"><svg class="icon" aria-hidden="true"><use href="#i-mail"/></svg><div><strong>${esc(t("tasks.detail.linkedEmail"))}</strong><span>${esc(task.linkedSubject || t("tasks.field.openConversation"))}</span></div></div>` : ""}
      <div class="task-editor-actions"><button class="btn-secondary" data-task-editor-close type="button">${esc(t("tasks.action.cancel"))}</button><button class="btn-primary" id="saveTaskBtn" type="submit">${esc(editing ? t("tasks.action.saveChanges") : t("tasks.action.create"))}</button></div>
    </form>`;
    setTimeout(() => document.getElementById("taskTitleInput")?.focus(), 40);
    return;
  }
  const task = state.tasks.find((item) => item.id === state.selectedTaskId);
  if (!task) {
    const open = state.tasks.filter((item) => item.status === "open").length;
    taskDetail.innerHTML = `<div class="task-detail-empty"><span class="task-detail-mark"><svg class="icon" aria-hidden="true"><use href="#i-task"/></svg></span><h2>${esc(t("tasks.detail.emptyTitle"))}</h2><p>${esc(tn("tasks.detail.emptyBody", open, { count: open }))}</p><button class="btn-primary" data-new-task type="button"><svg class="icon" aria-hidden="true"><use href="#i-plus"/></svg>${esc(t("tasks.detail.emptyCreate"))}</button><div class="task-detail-tips"><span><kbd>${t("ui.tasks.enter")}</kbd> ${esc(t("tasks.detail.tipEnter"))}</span><span><kbd>C</kbd> ${esc(t("tasks.detail.tipCompose"))}</span><span>${esc(t("tasks.detail.tipLinked"))}</span></div></div>`;
    return;
  }
  const dueState = taskDueState(task);
  taskDetail.innerHTML = `<div class="task-detail-head">
      <button class="icon-btn task-detail-back" data-task-back type="button" aria-label="${esc(t("tasks.detail.back"))}"><svg class="icon" aria-hidden="true"><use href="#i-arrow-left"/></svg></button>
      <div><span class="eyebrow">${esc(t("tasks.detail.task"))}</span><div class="task-title-line"><h2>${esc(task.title)}</h2><span class="task-status ${task.status}">${esc(task.status === "done" ? t("tasks.status.completed") : t("tasks.status.open"))}</span></div></div>
      <button class="icon-btn" data-task-edit="${esc(task.id)}" type="button" aria-label="${esc(t("tasks.detail.editTask"))}"><svg class="icon" aria-hidden="true"><use href="#i-compose"/></svg></button>
    </div>
    <div class="task-detail-badges"><span class="task-priority ${esc(task.priority)}">${esc(taskPriorityLabel(task.priority))}</span><span class="task-due ${dueState}">${esc(taskDueLabel(task))}</span>${task.kanbanStatus ? `<span class="task-tag">${esc(String(task.kanbanStatus).replace("_", " "))}</span>` : ""}${task.recurrenceRule ? `<span class="task-tag">${esc(task.recurrenceRule)}</span>` : ""}${(task.tags || []).map((tag) => `<span class="task-tag">${esc(tag)}</span>`).join("")}</div>
    <div class="task-detail-grid">
      <div><span>${esc(t("tasks.field.assignee"))}</span><strong>${esc(task.assignee ? task.assignee.name : t("tasks.detail.unassigned"))}</strong></div>
      <div><span>${esc(t("tasks.detail.created"))}</span><strong>${esc(formatDateOnly(task.createdAt))}</strong></div>
      <div><span>${esc(t("tasks.detail.source"))}</span><strong>${esc(task.source === "email" ? t("tasks.detail.emailFollowUp") : t("tasks.detail.manual"))}</strong></div>
      <div><span>${esc(t("tasks.detail.completed"))}</span><strong>${task.completedAt ? esc(formatDateOnly(task.completedAt)) : "—"}</strong></div>
    </div>
    <div class="task-notes"><h3>${esc(t("tasks.detail.notes"))}</h3><p>${esc(task.notes || t("tasks.detail.noNotes")).replace(/\n/g, "<br>")}</p></div>
    ${task.linkedThreadId ? `<button class="task-linked-card" data-task-open-thread="${esc(task.linkedThreadId)}" data-task-open-account="${esc(task.linkedAccountId || "")}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-mail"/></svg><div><strong>${esc(t("tasks.detail.linkedEmail"))}</strong><span>${esc(task.linkedSubject || t("tasks.field.openConversation"))}</span></div><svg class="icon" aria-hidden="true"><use href="#i-chevron-right"/></svg></button>` : ""}
    <div class="task-detail-actions">
      <button class="btn-primary" data-task-toggle="${esc(task.id)}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-check"/></svg>${esc(task.status === "done" ? t("tasks.row.reopen") : t("tasks.row.markComplete"))}</button>
      <button class="btn-secondary" data-task-edit="${esc(task.id)}" type="button">${esc(t("tasks.detail.edit"))}</button>
      <button class="btn-secondary danger-btn" data-task-delete="${esc(task.id)}" type="button">${esc(t("tasks.detail.delete"))}</button>
    </div>`;
}

async function saveTaskForm(event) {
  event.preventDefault();
  const title = document.getElementById("taskTitleInput").value.trim();
  if (!title) { showToast(t("tasks.toast.giveTitle")); document.getElementById("taskTitleInput").focus(); return; }
  const offlineKey = `task-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const payload = {
    title,
    clientRequestId: offlineKey,
    notes: document.getElementById("taskNotesInput").value,
    due: document.getElementById("taskDueInput").value,
    dueTime: document.getElementById("taskDueTimeInput").value,
    priority: document.getElementById("taskPriorityInput").value,
    assigneeEmail: document.getElementById("taskAssigneeInput").value,
    kanbanStatus: document.getElementById("taskKanbanInput").value,
    parentTaskId: document.getElementById("taskParentInput").value,
    dependsOnTaskId: document.getElementById("taskDependsInput").value,
    recurrenceRule: document.getElementById("taskRecurrenceInput").value.trim(),
    reminderAt: document.getElementById("taskReminderInput").value ? new Date(document.getElementById("taskReminderInput").value).toISOString() : "",
    tags: document.getElementById("taskTagsInput").value.split(",").map((tag) => tag.trim()).filter(Boolean)
  };
  const existingTask = state.editingTaskId && state.editingTaskId !== "new"
    ? state.tasks.find((item) => item.id === state.editingTaskId) || null
    : null;
  if (existingTask?.linkedThreadId) {
    payload.linkedThreadId = existingTask.linkedThreadId;
    payload.linkedSubject = existingTask.linkedSubject || "";
  } else if (state.taskDraftLink) {
    payload.linkedThreadId = state.taskDraftLink.threadId;
    payload.linkedSubject = state.taskDraftLink.subject;
  }
  try {
    if (state.editingTaskId && state.editingTaskId !== "new") {
      const data = await api(`/api/tasks/${encodeURIComponent(state.editingTaskId)}`, { method: "PATCH", body: payload });
      const index = state.tasks.findIndex((task) => task.id === data.task.id);
      if (index >= 0) state.tasks[index] = data.task;
      state.selectedTaskId = data.task.id;
      showToast(t("tasks.toast.updated"));
    } else {
      const data = await api("/api/tasks", { method: "POST", body: payload });
      state.tasks.unshift(data.task);
      state.selectedTaskId = data.task.id;
      showToast(t("tasks.toast.created"));
    }
    state.editingTaskId = null;
    state.taskDraftLink = null;
    renderTasks();
  } catch (error) {
    if (error.code === "NETWORK" || !navigator.onLine) {
      if (state.editingTaskId && state.editingTaskId !== "new") {
        const index = state.tasks.findIndex((task) => task.id === state.editingTaskId);
        if (index >= 0) state.tasks[index] = { ...state.tasks[index], ...payload };
        if (!String(state.editingTaskId).startsWith("offline-")) {
          queueOfflineTask({ method: "PATCH", path: `/api/tasks/${encodeURIComponent(state.editingTaskId)}`, body: payload });
        }
        showToast(t("tasks.toast.offlineUpdate"));
      } else {
        const tempId = "offline-" + offlineKey;
        state.tasks.unshift({ id: tempId, ...payload, status: "open", source: "offline", offline: true });
        queueOfflineTask({ method: "POST", path: "/api/tasks", body: payload, tempId });
        showToast(t("tasks.toast.offlineQueued"));
      }
      state.editingTaskId = null;
      state.taskDraftLink = null;
      renderTasks();
      return;
    }
    showError(error);
  }
}

async function toggleTask(taskId) {
  const task = state.tasks.find((item) => item.id === taskId);
  if (!task) return;
  const status = task.status === "done" ? "open" : "done";
  try {
    const data = await api(`/api/tasks/${encodeURIComponent(taskId)}`, { method: "PATCH", body: { status } });
    const index = state.tasks.findIndex((item) => item.id === taskId);
    if (index >= 0) state.tasks[index] = data.task;
    showToast(status === "done" ? t("tasks.toast.completed") : t("tasks.toast.reopened"));
    renderTasks();
  } catch (error) {
    if (error.code === "NETWORK" || !navigator.onLine) {
      task.status = status;
      if (!String(taskId).startsWith("offline-")) {
        queueOfflineTask({ method: "PATCH", path: `/api/tasks/${encodeURIComponent(taskId)}`, body: { status } });
      }
      showToast(t("tasks.toast.offlineChange"));
      renderTasks();
      return;
    }
    showError(error);
  }
}

async function deleteTask(taskId) {
  const task = state.tasks.find((item) => item.id === taskId);
  if (!task) return;
  if (!(await appConfirm({ title: t("tasks.confirm.deleteTitle"), message: t("tasks.confirm.deleteMessage", { title: task.title }), confirmLabel: t("tasks.confirm.deleteAction"), tone: "danger" }))) return;
  try {
    await api(`/api/tasks/${encodeURIComponent(taskId)}`, { method: "DELETE" });
    state.tasks = state.tasks.filter((item) => item.id !== taskId);
    state.selectedTaskId = null;
    state.editingTaskId = null;
    showToast(t("tasks.toast.deleted"));
    renderTasks();
  } catch (error) {
    if (error.code === "NETWORK" || !navigator.onLine) {
      state.tasks = state.tasks.filter((item) => item.id !== taskId);
      state.selectedTaskId = null;
      state.editingTaskId = null;
      if (!String(taskId).startsWith("offline-")) {
        queueOfflineTask({ method: "DELETE", path: `/api/tasks/${encodeURIComponent(taskId)}` });
      }
      showToast(t("tasks.toast.offlineDeletion"));
      renderTasks();
      return;
    }
    showError(error);
  }
}

async function refreshTasks() {
  try {
    const data = await api("/api/tasks");
    state.tasks = data.tasks || [];
    renderTasks();
    showToast(t("tasks.toast.refreshed"));
  } catch (error) {
    showError(error);
  }
}

function addThreadToTask(thread) {
  if (!thread) return;
  const message = thread.messages.find((item) => item.folder !== "sent" && item.folder !== "drafts") || thread.latest;
  const subject = String(threadSubject(thread) || t("tasks.noSubject")).slice(0, 200);
  const senderName = message?.from?.name && message.from.name !== message.from.email
    ? `${message.from.name} <${message.from.email}>`
    : (message?.from?.email || t("tasks.unknownSender"));
  const received = message?.date ? formatDateTimeFull(message.date) : "";
  const snippet = String(message?.snippet || message?.bodyText || stripHtml(message?.bodyHtml || "") || "").trim().slice(0, 1600);
  state.taskDraftLink = {
    threadId: thread.id,
    subject,
    accountId: state.activeAccountId && state.activeAccountId !== "all" ? state.activeAccountId : "",
    note: [`From: ${senderName}`, received ? `Received: ${received}` : "", "", snippet].filter((line, index) => line || index === 2).join("\n")
  };
  state.editingTaskId = "new";
  state.selectedTaskId = null;
  state.taskFilter = "all";
  setTask("tasks");
  if (isMobile()) document.body.classList.add("task-detail-open");
  renderTasks();
  showToast(t("tasks.toast.emailReady"));
}

function openTaskFromEmail(threadId, accountId = "") {
  if (accountId && accountId !== state.activeAccountId && state.accounts.some((account) => account.id === accountId)) {
    switchMailAccount(accountId, { reload: false });
    loadBootstrap({ quiet: true })
      .then(() => openTaskFromEmail(threadId))
      .catch((error) => showToast(error.message || t("tasks.toast.openLinkedError")));
    return;
  }
  const thread = threadById(threadId);
  if (!thread) { showToast(t("tasks.toast.linkedGone")); return; }
  const message = thread.messages.find((item) => item.folder !== "sent" && item.folder !== "drafts") || thread.latest;
  const selection = selectionIdForMessage(message);
  state.selectedThreadId = selection;
  state.folder = FOLDER_LABELS[message.folder] ? message.folder : "inbox";
  state.filter = "all";
  setTask("mail");
  state.selectedThreadId = selection;
  renderList();
  renderReader();
  syncSelectionUi();
  if (isMobile()) document.body.classList.add("reader-open");
}

/* ============================================================
   files + storage
   ============================================================ */
const FILE_FILTERS = [
  { id: "all", label: t("ui.files-storage.all-items") },
  { id: "recent", label: t("ui.files-storage.recent") },
  { id: "shared", label: t("mail.list.shared") },
  { id: "images", label: t("ui.files-storage.images") },
  { id: "documents", label: t("ui.files-storage.documents") },
  { id: "starred", label: t("ui.files-storage.starred") }
];

function storageProvider(providerId) {
  return state.storageProviders.find((provider) => provider.id === providerId) || null;
}

function storageConnected(providerId) {
  const provider = storageProvider(providerId);
  return Boolean(provider && provider.connected);
}

function fileFolderById(id) {
  if (!id) return null;
  return (state.fileFolders || []).find((folder) => folder.id === id) || null;
}

function fileFolderTrail(id) {
  const trail = [];
  const seen = new Set();
  let folder = fileFolderById(id);
  while (folder && !seen.has(folder.id) && trail.length < 10) {
    seen.add(folder.id);
    trail.unshift(folder);
    folder = fileFolderById(folder.parentId);
  }
  return trail;
}

function fileFolderDepth(folder) {
  return Math.max(0, fileFolderTrail(folder.id).length - 1);
}

function childFileFolders(parentId) {
  return (state.fileFolders || [])
    .filter((folder) => (folder.parentId || "") === (parentId || ""))
    .sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: "base" }));
}

function fileProviderName(file) {
  return storageProvider(file.providerId)?.name || t("ui.files-storage.storage");
}

function fileIsImage(file) {
  return String(file.mime || "").startsWith("image/") && !String(file.mime || "").includes("svg");
}

function fileMatchesFilter(file) {
  if (!file.shared && !storageConnected(file.providerId)) return false;
  if (state.fileProvider !== "all" && file.providerId !== state.fileProvider) return false;
  if (state.fileProvider === "all" || state.fileProvider === "a8m") {
    if (state.fileFolderId && file.folderId !== state.fileFolderId) return false;
  }
  if (state.fileFilter === "recent") {
    const modified = new Date(file.modifiedAt);
    if (Number.isNaN(modified.getTime()) || Date.now() - modified.getTime() > 7 * 86400000) return false;
  }
  if (state.fileFilter === "shared" && !file.shared && !(file.sharedWith || []).length) return false;
  if (state.fileFilter === "images" && !String(file.mime || "").startsWith("image/")) return false;
  if (state.fileFilter === "documents" && !["PDF", "DOC", "DOCX", "XLS", "XLSX", "PPT", "PPTX", "TXT", "ODT", "ODS", "ODP", "RTF", "CSV"].includes(String(file.type || "").toUpperCase())) return false;
  if (state.fileFilter === "starred" && !file.starred) return false;
  const query = state.query.toLowerCase();
  if (query) {
    const haystack = [file.name, file.path, file.description, file.owner && file.owner.name, file.type, fileProviderName(file)].join(" ").toLowerCase();
    if (!haystack.includes(query)) return false;
  }
  return true;
}

function folderMatchesQuery(folder) {
  const query = state.query.toLowerCase();
  if (!query) return true;
  return [folder.name, folder.path].join(" ").toLowerCase().includes(query);
}

function fileTypeClass(file) {
  return String(file.type || "FILE").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 5);
}

function fileModifiedStamp(file) {
  const stamp = Date.parse(file.modifiedAt || file.updatedAt || file.createdAt || "");
  return Number.isNaN(stamp) ? 0 : stamp;
}

function cabinetSortValue(file) {
  switch (state.fileSort) {
    case "modified": return fileModifiedStamp(file);
    case "size": return Number(file.sizeBytes) || 0;
    case "type": return String(file.type || "").toLowerCase();
    default: return String(file.name || "").toLowerCase();
  }
}

function sortCabinetFiles(files) {
  const direction = state.fileSortDesc ? -1 : 1;
  return files.slice().sort((a, b) => {
    const left = cabinetSortValue(a);
    const right = cabinetSortValue(b);
    let result;
    if (typeof left === "number" && typeof right === "number") result = left - right;
    else result = String(left).localeCompare(String(right), undefined, { sensitivity: "base", numeric: true });
    return result * direction;
  });
}

function cabinetGroupKey(file) {
  if (state.fileGroup === "type") return String(file.type || t("ui.files-storage.files")).toUpperCase() || "FILES";
  if (state.fileGroup === "provider") return fileProviderName(file);
  if (state.fileGroup === "date") {
    const modified = new Date(fileModifiedStamp(file));
    if (!fileModifiedStamp(file)) return t("mail.list.date.older");
    const today = new Date();
    const todayKey = dateKey(today);
    const key = dateKey(modified);
    if (key === todayKey) return t("mail.list.date.today");
    if (key === addDaysToKey(todayKey, -1)) return t("mail.list.date.yesterday");
    if (Date.now() - modified.getTime() < 7 * 86400000) return t("ui.files-storage.earlier-this-week");
    if (Date.now() - modified.getTime() < 31 * 86400000) return t("ui.files-storage.earlier-this-month");
    if (modified.getFullYear() === today.getFullYear()) return t("ui.files-storage.earlier-this-year");
    return String(modified.getFullYear());
  }
  return "";
}

function cabinetFileRow(file) {
  const provider = storageProvider(file.providerId);
  const selected = file.id === state.selectedFileId;
  const shared = Boolean(file.shared) || (file.sharedWith || []).length > 0;
  const sharedLabel = file.shared ? t("ui.files-storage.shared-with-you") : t("mail.list.shared");
  return `<div class="file-row cabinet-row${selected ? " is-selected" : ""}${file.shared ? " is-shared-file" : ""}" data-file-id="${esc(file.id)}" tabindex="0" role="button" draggable="true" aria-pressed="${selected}" aria-label="${esc(file.name)}">
    <span class="file-type ${fileTypeClass(file)}">${esc(file.type || t("ui.files-storage.file"))}</span>
    <div class="file-main"><strong>${esc(file.name)}</strong><span>${esc(file.path || t("ui.files-storage.files"))} · ${esc(provider ? provider.name : t("ui.files-storage.storage"))}${file.shared ? ` · <em class="file-shared-note">${esc(sharedLabel)}</em>` : ""}</span></div>
    <span class="file-owner">${esc(file.owner ? file.owner.name : "—")}</span>
    <span class="file-modified">${esc(formatDateOnly(file.modifiedAt))}</span>
    <span class="file-size">${esc(formatBytes(file.sizeBytes))}</span>
    <span class="file-flags">${shared ? `<svg class="icon" aria-label="${esc(sharedLabel)}" title="${esc(sharedLabel)}"><use href="#i-people"/></svg>` : ""}${file.dlpClassification ? `<svg class="icon dlp-flag" aria-label="${esc(t("ui.files-storage.data-classification", { classification: file.dlpClassification }))}" title="${esc(file.dlpClassification)}${(file.dlpWarnings || []).length ? ` · ${esc((file.dlpWarnings || []).join(" · "))}` : ""}"><use href="#${(file.dlpWarnings || []).length ? "i-shield-alert" : "i-shield-check"}"/></svg>` : ""}${file.locked ? '<svg class="icon" aria-label="${esc(t("ui.mail-home-pulse-search-reports-sticky-no.locked"))}" title="${esc(t("ui.mail-home-pulse-search-reports-sticky-no.locked"))}"><use href="#i-lock"/></svg>' : ""}</span>
    ${file.shared ? "" : `<button class="star-btn${file.starred ? " is-starred" : ""}" data-file-star="${esc(file.id)}" type="button" aria-label="${file.starred ? t("mail.reader.removeStar") : t("ui.files-storage.star-file")}" aria-pressed="${file.starred ? "true" : "false"}"><svg class="icon" aria-hidden="true"><use href="#i-star"/></svg></button>`}
    <button class="icon-btn cabinet-row-more" data-file-menu="${esc(file.id)}" type="button" aria-label="${esc(t("ui.files-storage.more-actions-for", { name: file.name }))}"><svg class="icon" aria-hidden="true"><use href="#i-more"/></svg></button>
  </div>`;
}

function cabinetFolderRow(folder) {
  const active = state.fileFolderId === folder.id;
  return `<div class="file-row cabinet-row cabinet-folder-row${active ? " is-selected" : ""}" data-folder-open="${esc(folder.id)}" data-folder-drop="${esc(folder.id)}" tabindex="0" role="button" draggable="true" aria-label="${esc(t("ui.files-storage.open-folder-name", { name: folder.name }))}">
    <span class="file-type folder"><svg class="icon" aria-hidden="true"><use href="#i-folder"/></svg></span>
    <div class="file-main"><strong>${esc(folder.name)}</strong><span>${esc(folder.path)}</span></div>
    <span class="file-owner">${t("mail.details.folder")}</span>
    <span class="file-modified">${esc(formatDateOnly(folder.updatedAt))}</span>
    <span class="file-size">${folder.count || 0} ${Number(folder.count) === 1 ? "item" : "items"}</span>
    <span class="file-flags"></span>
    <button class="icon-btn cabinet-row-more" data-folder-menu="${esc(folder.id)}" type="button" aria-label="${esc(t("ui.files-storage.more-actions-for", { name: folder.name }))}"><svg class="icon" aria-hidden="true"><use href="#i-more"/></svg></button>
  </div>`;
}

function cabinetFolderTile(folder, mode) {
  return `<article class="cabinet-tile cabinet-folder-tile ${mode === "thumbs" ? "is-thumb" : ""}" data-folder-open="${esc(folder.id)}" data-folder-drop="${esc(folder.id)}" tabindex="0" role="button" draggable="true" aria-label="${esc(t("ui.files-storage.open-folder-name", { name: folder.name }))}">
    <div class="cabinet-tile-art"><svg class="icon" aria-hidden="true"><use href="#i-folder"/></svg><span class="cabinet-tile-badge">${folder.count || 0}</span></div>
    <strong>${esc(folder.name)}</strong>
    <span>${esc(folder.path)}</span>
    <button class="icon-btn cabinet-tile-more" data-folder-menu="${esc(folder.id)}" type="button" aria-label="${esc(t("ui.files-storage.more-actions-for", { name: folder.name }))}"><svg class="icon" aria-hidden="true"><use href="#i-more"/></svg></button>
  </article>`;
}

function cabinetFileTile(file, mode) {
  const provider = storageProvider(file.providerId);
  const selected = file.id === state.selectedFileId;
  const image = fileIsImage(file) && file.contentUrl;
  return `<article class="cabinet-tile${selected ? " is-selected" : ""}${mode === "thumbs" ? " is-thumb" : ""}${file.shared ? " is-shared-file" : ""}" data-file-id="${esc(file.id)}" tabindex="0" role="button" draggable="true" aria-pressed="${selected}" aria-label="${esc(file.name)}">
    <div class="cabinet-tile-art ${fileTypeClass(file)}">${mode === "thumbs" && image ? `<img src="${esc(file.contentUrl)}" alt="" loading="lazy">` : `<span class="file-type ${fileTypeClass(file)}">${esc(file.type || t("ui.files-storage.file"))}</span>`}${!file.shared && file.starred ? '<span class="cabinet-star-mark"><svg class="icon" aria-hidden="true"><use href="#i-star"/></svg></span>' : ""}${file.shared ? '<span class="cabinet-star-mark cabinet-share-mark" title="${esc(t("ui.files-storage.shared-with-you"))}"><svg class="icon" aria-hidden="true"><use href="#i-people"/></svg></span>' : ""}</div>
    <strong>${esc(file.name)}</strong>
    <span>${file.shared ? t("ui.files-storage.shared-with-you") : esc(provider ? provider.name : t("ui.files-storage.storage"))} · ${esc(formatBytes(file.sizeBytes))}</span>
    <span class="cabinet-tile-meta">${esc(formatDateOnly(file.modifiedAt))}</span>
    <button class="icon-btn cabinet-tile-more" data-file-menu="${esc(file.id)}" type="button" aria-label="${esc(t("ui.files-storage.more-actions-for", { name: file.name }))}"><svg class="icon" aria-hidden="true"><use href="#i-more"/></svg></button>
  </article>`;
}

function renderCabinetBreadcrumb() {
  if (!fileBreadcrumb) return;
  const trail = fileFolderTrail(state.fileFolderId);
  const crumbs = [`<button type="button" data-folder-open="" data-folder-drop="" class="${trail.length ? "" : "is-current"}"><svg class="icon" aria-hidden="true"><use href="#i-cabinet"/></svg>${t("ui.files-storage.all-files")}</button>`];
  trail.forEach((folder, index) => {
    crumbs.push(`<svg class="icon crumb-sep" aria-hidden="true"><use href="#i-chevron-right"/></svg>`);
    crumbs.push(`<button type="button" data-folder-open="${esc(folder.id)}" class="${index === trail.length - 1 ? "is-current" : ""}" data-folder-drop="${esc(folder.id)}">${esc(folder.name)}</button>`);
  });
  fileBreadcrumb.innerHTML = crumbs.join("");
}

function renderCabinetSidebar(filteredFiles) {
  if (cabinetFolderTree) {
    const folders = (state.fileFolders || []).slice().sort((a, b) => String(a.path).localeCompare(String(b.path), undefined, { sensitivity: "base" }));
    cabinetFolderTree.innerHTML = folders.length ? folders.map((folder) => `<button class="cabinet-folder-link${state.fileFolderId === folder.id ? " is-active" : ""}" style="--folder-depth:${fileFolderDepth(folder)};--folder-color:${esc(folder.color || "#0f6cbd")}" data-folder-open="${esc(folder.id)}" data-folder-drop="${esc(folder.id)}" type="button" title="${esc(folder.path)}"><span class="folder-dot" aria-hidden="true"></span><span>${esc(folder.name)}</span><em>${folder.count || 0}</em></button>`).join("") : `<div class="cabinet-folder-empty"><svg class="icon" aria-hidden="true"><use href="#i-folder-plus"/></svg><span>${t("ui.files-storage.no-folders-yet")}</span><button class="link-btn" type="button" data-new-folder>${t("ui.files-storage.create-one")}</button></div>`;
  }
  if (cabinetProviderList) {
    cabinetProviderList.innerHTML = state.storageProviders.map((provider) => {
      const percent = provider.limitBytes ? Math.min(100, (provider.usedBytes / provider.limitBytes) * 100) : 0;
      return `<div class="storage-card cabinet-provider${provider.connected ? " is-connected" : ""}" style="--provider:${provider.color}">
        ${storageProviderMarkup(provider)}
        <div class="cabinet-provider-copy"><strong>${esc(provider.name)}</strong><span>${provider.connected ? `${formatBytes(provider.usedBytes)}${provider.limitBytes ? ` of ${formatBytes(provider.limitBytes)}` : ""}` : t("ui.files-storage.not-connected")}</span>${provider.connected && provider.limitBytes ? `<div class="usage-bar"><span style="width:${percent}%"></span></div>` : ""}</div>
        ${provider.connected ? '<span class="storage-status"><span class="status-dot"></span></span>' : `<button class="link-btn" data-storage-connect="${esc(provider.id)}" type="button">${t("ui.files-storage.connect")}</button>`}
      </div>`;
    }).join("");
  }
  const rootCount = document.getElementById("fileRootCount");
  if (rootCount) rootCount.textContent = `${state.files.length} item${state.files.length === 1 ? "" : "s"} across ${(state.fileFolders || []).length} folder${(state.fileFolders || []).length === 1 ? "" : "s"}`;
  if (cabinetQuota) {
    const quota = state.storageQuota || (storageProvider("a8m")?.quota) || null;
    if (quota) {
      const percent = Math.min(100, Math.max(0, Number(quota.percent) || 0));
      cabinetQuota.innerHTML = `<div class="cabinet-quota-head"><span>${quota.combined ? t("ui.files-storage.mail-cabinet") : t("ui.files-storage.cabinet-storage")}</span><strong>${Math.round(percent)}%</strong></div>
        <div class="usage-bar"><span style="width:${percent}%"></span></div>
        <p>${esc(quota.label || `${formatBytes(quota.usedBytes)} of ${formatBytes(quota.limitBytes)}`)}</p>
        <small>${quota.combined ? t("ui.files-storage.shared-mailbox-allowance") : t("ui.files-storage.separate-cabinet-allowance")} · ${esc(quota.source || "organization")} policy</small>`;
    } else {
      const provider = storageProvider("a8m");
      cabinetQuota.innerHTML = `<div class="cabinet-quota-head"><span>${t("ui.files-storage.cabinet-storage")}</span><strong>${provider ? formatBytes(provider.usedBytes) : "—"}</strong></div><p>${t("ui.files-storage.connected-to-alt8mail-drive")}</p>`;
    }
  }
}

function cabinetGroupedMarkup(folders, files, mode) {
  const groups = new Map();
  for (const file of files) {
    const key = cabinetGroupKey(file) || t("ui.files-storage.files");
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(file);
  }
  const folderMarkup = (list) => mode === "list" || state.fileView === "list"
    ? `<div class="cabinet-list">${list.map(cabinetFolderRow).join("")}</div>`
    : `<div class="cabinet-tiles">${list.map((folder) => cabinetFolderTile(folder, mode)).join("")}</div>`;
  const fileMarkup = (list) => state.fileView === "list"
    ? `<div class="cabinet-list">${list.map(cabinetFileRow).join("")}</div>`
    : `<div class="cabinet-tiles${state.fileView === "thumbs" ? " is-thumbs" : ""}">${list.map((file) => cabinetFileTile(file, state.fileView === "thumbs" ? "thumbs" : "tiles")).join("")}</div>`;
  let html = "";
  if (folders.length) {
    html += `<section class="cabinet-group cabinet-folder-group"><header class="cabinet-group-head"><strong>${t("mail.folders.section.folders")}</strong><span>${folders.length}</span></header>${folderMarkup(folders)}</section>`;
  }
  if (state.fileGroup === "none") {
    if (files.length) html += fileMarkup(files);
  } else {
    for (const [key, list] of groups) {
      html += `<section class="cabinet-group"><header class="cabinet-group-head"><strong>${esc(key)}</strong><span>${list.length}</span></header>${fileMarkup(sortCabinetFiles(list))}</section>`;
    }
  }
  return html;
}

function renderFiles() {
  if (!filesView || !fileList) return;
  const connected = state.storageProviders.filter((provider) => provider.connected);
  const available = state.files.filter((file) => file.shared || storageConnected(file.providerId));
  const filtered = sortCabinetFiles(available.filter(fileMatchesFilter));
  if (!filtered.some((file) => file.id === state.selectedFileId)) state.selectedFileId = filtered[0] ? filtered[0].id : null;
  const used = connected.reduce((sum, provider) => sum + (Number(provider.usedBytes) || 0), 0);
  const limit = connected.reduce((sum, provider) => sum + (Number(provider.limitBytes) || 0), 0);
  const currentFolder = fileFolderById(state.fileFolderId);
  filesMeta.textContent = t("ui.files-storage.files-meta", { items: tn("ui.files-storage.item-count", available.length, { count: available.length }), drives: tn("ui.files-storage.connected-drive-count", connected.length, { count: connected.length }), used: formatBytes(used), limit: limit ? t("ui.files-storage.of-size", { size: formatBytes(limit) }) : "" });
  const providerOptions = [`<option value="all">${t("ui.files-storage.all-connected-drives")}</option>`, ...connected.map((provider) => `<option value="${esc(provider.id)}"${state.fileProvider === provider.id ? " selected" : ""}>${esc(provider.name)}</option>`)].join("");
  if (fileProviderFilter.innerHTML !== providerOptions) fileProviderFilter.innerHTML = providerOptions;
  if (state.fileProvider !== "all" && !connected.some((provider) => provider.id === state.fileProvider)) state.fileProvider = "all";
  fileProviderFilter.value = state.fileProvider;
  fileFilters.innerHTML = FILE_FILTERS.map((filter) => `<button class="chip${state.fileFilter === filter.id ? " is-active" : ""}" data-file-filter="${filter.id}" type="button">${filter.label}</button>`).join("");
  syncStorageDefaultSelects();
  const manageCredentials = document.getElementById("manageStorageCredentialsBtn");
  if (manageCredentials) manageCredentials.hidden = !storageCanManage();
  if (fileSortSelect) fileSortSelect.value = state.fileSort;
  if (fileGroupSelect) fileGroupSelect.value = state.fileGroup;
  if (fileSortDirection) fileSortDirection.classList.toggle("is-desc", state.fileSortDesc);
  fileViewSwitch?.querySelectorAll("[data-file-view]").forEach((button) => {
    button.classList.toggle("is-active", button.getAttribute("data-file-view") === state.fileView);
  });
  renderCabinetBreadcrumb();
  renderCabinetSidebar(filtered);
  const folderScope = state.fileProvider === "all" || state.fileProvider === "a8m";
  const folders = folderScope
    ? childFileFolders(state.fileFolderId).filter(folderMatchesQuery).filter((folder) => {
        if (state.fileFilter === "starred" || state.fileFilter === "shared" || state.fileFilter === "images" || state.fileFilter === "documents") return false;
        return true;
      })
    : [];
  fileList.className = `file-scroll cabinet-view-${state.fileView}`;
  if (!folders.length && !filtered.length) {
    fileList.innerHTML = `<div class="file-empty"><svg class="icon" aria-hidden="true"><use href="#i-cabinet"/></svg><strong>${state.query ? t("ui.files-storage.no-matching-files") : currentFolder ? t("mail.list.empty.folderTitle") : t("ui.files-storage.cabinet-is-empty")}</strong><span>${state.query ? t("tasks.list.emptySearch") : t("ui.files-storage.drop-files-here-upload-a-document-or-save-an-ema")}</span><button class="btn-secondary" type="button" data-cabinet-upload><svg class="icon" aria-hidden="true"><use href="#i-upload"/></svg>${t("ui.files-storage.upload-files")}</button></div>`;
  } else {
    fileList.innerHTML = cabinetGroupedMarkup(folders, filtered, state.fileView);
  }
  renderFileDetail();
  syncStatusRange();
  syncStatusContext();
  syncOfficeCabinetUi();
}

function renderFileDetail() {
  if (!fileDetail) return;
  const file = state.files.find((item) => item.id === state.selectedFileId);
  if (!file) {
    const folder = fileFolderById(state.fileFolderId);
    fileDetail.innerHTML = `<div class="file-detail-empty"><span class="file-detail-mark"><svg class="icon" aria-hidden="true"><use href="#${folder ? "i-folder" : "i-cabinet"}"/></svg></span><h2>${folder ? esc(folder.name) : t("ui.files-storage.your-cabinet-connected")}</h2><p>${folder ? t("ui.files-storage.create-a-folder-inside-or-drop-files-here-to-upl") : t("ui.files-storage.keep-documents-attachments-and-connected-drive-f")}</p><div class="file-detail-actions"><button class="btn-secondary" data-open-storage type="button"><svg class="icon" aria-hidden="true"><use href="#i-plus"/></svg>${t("ui.files-storage.add-storage")}</button><button class="btn-secondary" data-cabinet-upload type="button"><svg class="icon" aria-hidden="true"><use href="#i-upload"/></svg>${t("ui.files-storage.upload")}</button></div><div class="file-detail-tips"><span>${esc(t("ui.files-storage.indexed-items", { count: state.files.filter((item) => storageConnected(item.providerId)).length }))}</span><span>${t("ui.files-storage.oauth-ready-connectors")}</span><span>${t("ui.files-storage.enterprise-sharing-controls")}</span></div></div>`;
    return;
  }
  const provider = storageProvider(file.providerId);
  const image = fileIsImage(file) && file.contentUrl;
  const pdf = file.mime === "application/pdf" && file.contentUrl;
  const folder = fileFolderById(file.folderId);
  const office = canUseOffice(file) ? officeMetaForFile(file) : null;
  const sharedFile = Boolean(file.shared);
  const officeLabel = office && office.editable && !(sharedFile && file.access === "view") ? t("ui.compose-manager.edit-in-office") : t("ui.files-storage.view-in-office");
  fileDetail.innerHTML = `<div class="file-detail-head"><div><span class="eyebrow">${t("ui.files-storage.file-details")}</span><h2>${esc(file.name)}</h2></div><button class="icon-btn file-detail-back" data-file-back type="button" aria-label="${esc(t("ui.files-storage.back-to-files"))}"><svg class="icon" aria-hidden="true"><use href="#i-arrow-left"/></svg></button></div>
    <div class="file-preview-card ${fileTypeClass(file)}">
      ${image ? `<img src="${esc(file.contentUrl)}" alt="${esc(file.name)}" loading="lazy">` : pdf ? `<span class="file-preview-pdf"><svg class="icon" aria-hidden="true"><use href="#i-file"/></svg>PDF</span>` : `<span class="file-preview-generic"><svg class="icon" aria-hidden="true"><use href="#i-file"/></svg><strong>${esc(file.type)}</strong></span>`}
      <div class="file-preview-overlay"><button class="btn-secondary" data-file-preview="${esc(file.id)}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-expand"/></svg>${file.previewable ? t("ui.settings.preview") : t("ui.files-storage.open-details")}</button><button class="btn-secondary" data-file-menu="${esc(file.id)}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-more"/></svg>${t("ui.files-storage.more")}</button></div>
    </div>
    <div class="file-badges"><span class="provider-badge" style="--provider:${provider ? provider.color : "#64748b"}">${esc(provider ? provider.name : t("ui.files-storage.storage"))}</span>${sharedFile ? "<span class=\"policy-chip is-shared\">" + t("ui.files-storage.shared-with-you") + "</span>" : ""}${file.starred && !sharedFile ? "<span class=\"policy-chip\">" + t("ui.files-storage.starred") + "</span>" : ""}${file.locked ? "<span class=\"policy-chip\">" + t("ui.mail-home-pulse-search-reports-sticky-no.locked") + "</span>" : ""}${file.dlpClassification ? `<span class="policy-chip dlp-chip" title="${esc((file.dlpWarnings || []).join(" · "))}"><svg class="icon" aria-hidden="true"><use href="#${(file.dlpWarnings || []).length ? "i-shield-alert" : "i-shield-check"}"/></svg>${esc(file.dlpClassification)}</span>` : ""}${!sharedFile && (file.sharedWith || []).length ? `<span class="policy-chip">${file.sharedWith.length} shared</span>` : ""}</div>
    <p class="file-description">${esc(file.description || (sharedFile ? t("ui.files-storage.shared-by-owner", { owner: file.owner ? file.owner.name : t("ui.files-storage.a-colleague") }) : t("ui.files-storage.no-description")))}</p>
    <div class="file-meta-grid">
      <div><span>${t("ui.files-storage.owner")}</span><strong>${esc(file.owner ? file.owner.name : "—")}</strong></div>
      <div><span>${t("ui.files-storage.modified")}</span><strong>${esc(formatDateOnly(file.modifiedAt))}</strong></div>
      <div><span>${t("mail.details.size")}</span><strong>${esc(formatBytes(file.sizeBytes))}</strong></div>
      <div><span>${t("ui.files-storage.version")}</span><strong>${esc(file.version || "1")}</strong></div>
    </div>
    <div class="file-path"><svg class="icon" aria-hidden="true"><use href="#i-folder"/></svg><button class="link-btn" data-folder-open="${esc(file.folderId || "")}" type="button">${esc(folder ? folder.path : t("ui.files-storage.all-files"))}</button></div>
    <div class="file-detail-actions">
      ${office ? `<button class="btn-primary" data-office-edit="${esc(file.id)}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-file"/></svg>${officeLabel}</button>` : `<button class="btn-primary" data-file-preview="${esc(file.id)}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-expand"/></svg>${t("ui.files-storage.preview")}</button>`}
      ${office ? `<button class="btn-secondary" data-office-versions="${esc(file.id)}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-history"/></svg>${t("ui.files-storage.versions")}</button>` : ""}
      <button class="btn-secondary" data-file-download="${esc(file.id)}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-download"/></svg>${t("ui.files-storage.download")}</button>
      ${sharedFile ? "" : `<button class="btn-secondary" data-file-share="${esc(file.id)}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-people"/></svg>${t("ui.files-storage.share")}</button>
      <button class="btn-secondary" data-file-lock="${esc(file.id)}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-lock"/></svg>${file.locked ? t("ui.files-storage.unlock-link") : t("ui.files-storage.lock-link")}</button>
      <button class="btn-secondary" data-file-send="${esc(file.id)}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-send"/></svg>${t("ui.files-storage.send")}</button>
      <button class="btn-secondary" data-file-menu="${esc(file.id)}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-more"/></svg>${t("ui.files-storage.more")}</button>`}
    </div>
    ${!sharedFile && (file.sharedWith || []).length ? `<div class="file-shared-list"><h3>${t("ui.files-storage.shared-with")}</h3>${file.sharedWith.map((email) => `<span>${avatar({ name: email.split("@")[0], email, initials: initialsFrom(email.split("@")[0]), color: colorForString(email) }, "sm")}${esc(email)}</span>`).join("")}</div>` : ""}`;
}

async function refreshCabinet() {
  try {
    const data = await api("/api/files");
    state.files = data.files || state.files;
    state.fileFolders = data.folders || state.fileFolders;
    if (data.providers) state.storageProviders = data.providers;
    if (data.quota) state.storageQuota = data.quota;
    renderFiles();
    return data;
  } catch (error) {
    showError(error);
    return null;
  }
}

function persistCabinetView() {
  try {
    localStorage.setItem("a8m.cabinet.sort", state.fileSort);
    localStorage.setItem("a8m.cabinet.group", state.fileGroup);
    localStorage.setItem("a8m.cabinet.view", state.fileView);
    localStorage.setItem("a8m.cabinet.sortDesc", state.fileSortDesc ? "1" : "0");
  } catch {}
  if (state.preferences?.cabinetView === state.fileView) return;
  state.preferences = { ...(state.preferences || {}), cabinetView: state.fileView };
  if (state.user) state.user.preferences = state.preferences;
  state.cabinetViewPending = state.fileView;
  api("/api/preferences", { method: "PATCH", body: { cabinetView: state.fileView } })
    .then((data) => {
      if (data?.preferences) state.preferences = { ...state.preferences, ...data.preferences };
    })
    .catch(() => {})
    .finally(() => { state.cabinetViewPending = ""; });
}

function openFileFolder(folderId) {
  state.fileFolderId = folderId || null;
  state.selectedFileId = null;
  document.body.classList.remove("file-open");
  renderFiles();
}

function fileFolderOptions({ excludeId = "", includeRoot = true, selected = "" } = {}) {
  const excluded = new Set([excludeId]);
  if (excludeId) {
    let changed = true;
    for (let pass = 0; pass < 12 && changed; pass += 1) {
      changed = false;
      for (const folder of state.fileFolders || []) {
        if (!excluded.has(folder.id) && excluded.has(folder.parentId)) {
          excluded.add(folder.id);
          changed = true;
        }
      }
    }
  }
  const options = includeRoot ? [`<option value=""${selected === "" ? " selected" : ""}>${t("ui.files-storage.all-files")}</option>`] : [];
  for (const folder of (state.fileFolders || []).slice().sort((a, b) => String(a.path).localeCompare(String(b.path)))) {
    if (excluded.has(folder.id)) continue;
    options.push(`<option value="${esc(folder.id)}"${selected === folder.id ? " selected" : ""}>${esc(folder.path)}</option>`);
  }
  return options.join("");
}

function openFolderDialog(folderId = null, parentId = state.fileFolderId) {
  const folder = fileFolderById(folderId);
  state.folderEditingId = folder ? folder.id : "";
  document.getElementById("folderDialogTitle").textContent = folder ? t("mail.folders.renameTitle") : t("mail.folders.newTitle");
  document.getElementById("folderDialogSubtitle").textContent = folder ? t("ui.files-storage.rename-or-move-this-cabinet-folder") : t("ui.files-storage.create-a-folder-and-optionally-place-it-inside-a");
  document.getElementById("folderName").value = folder ? folder.name : "";
  document.getElementById("folderColor").value = folder?.color || "#0f6cbd";
  document.getElementById("folderParent").innerHTML = fileFolderOptions({ excludeId: folder?.id || "", selected: folder ? folder.parentId || "" : parentId || "" });
  document.getElementById("folderSave").textContent = folder ? t("ui.files-storage.save-folder") : t("mail.folders.createFolder");
  folderOverlay.hidden = false;
  setTimeout(() => document.getElementById("folderName").focus(), 40);
}

async function saveFolderDialog() {
  const name = document.getElementById("folderName").value.trim();
  if (!name) { showToast(t("ui.files-storage.give-the-folder-a-name")); document.getElementById("folderName").focus(); return; }
  const body = {
    name,
    parentId: document.getElementById("folderParent").value || "",
    color: document.getElementById("folderColor").value || ""
  };
  const button = document.getElementById("folderSave");
  button.disabled = true;
  try {
    const editing = state.folderEditingId;
    const data = await api(editing ? `/api/file-folders/${encodeURIComponent(editing)}` : "/api/file-folders", {
      method: editing ? "PATCH" : "POST", body
    });
    state.fileFolders = data.folders || state.fileFolders;
    if (data.files) state.files = data.files;
    folderOverlay.hidden = true;
    state.folderEditingId = "";
    renderFiles();
    showToast(editing ? t("mail.folders.updated") : t("mail.folders.created"));
  } catch (error) { showError(error); }
  finally { button.disabled = false; }
}

async function deleteFileFolder(folderId) {
  const folder = fileFolderById(folderId);
  if (!folder) return;
  const ok = await appConfirm({
    title: t("ui.files-storage.delete-this-folder"),
    message: t("ui.files-storage.folder-move-up-confirm", { folder: folder.name }),
    confirmLabel: t("mail.folders.deleteConfirm"), tone: "danger"
  });
  if (!ok) return;
  try {
    const data = await api(`/api/file-folders/${encodeURIComponent(folderId)}`, { method: "DELETE" });
    state.fileFolders = data.folders || state.fileFolders;
    if (data.files) state.files = data.files;
    if (state.fileFolderId === folderId) state.fileFolderId = folder.parentId || null;
    renderFiles();
    showToast(t("mail.folders.deleted"));
  } catch (error) { showError(error); }
}

async function moveFileToFolder(fileId, folderId) {
  const file = state.files.find((item) => item.id === fileId);
  if (!file) return;
  if ((file.folderId || "") === (folderId || "")) return;
  try {
    const data = await api(`/api/files/${encodeURIComponent(fileId)}`, { method: "PATCH", body: { folderId: folderId || "" } });
    const index = state.files.findIndex((item) => item.id === fileId);
    if (index >= 0) state.files[index] = data.file;
    state.fileFolders = (await refreshCabinet())?.folders || state.fileFolders;
    renderFiles();
    const folder = fileFolderById(folderId);
    showToast(t("ui.files-storage.file-moved-to", { name: file.name, folder: folder ? folder.name : t("ui.files-storage.all-files") }));
  } catch (error) { showError(error); }
}

async function moveFolderToFolder(folderId, parentId) {
  const folder = fileFolderById(folderId);
  if (!folder || folderId === parentId) return;
  try {
    const data = await api(`/api/file-folders/${encodeURIComponent(folderId)}`, { method: "PATCH", body: { parentId: parentId || "" } });
    state.fileFolders = data.folders || state.fileFolders;
    if (data.files) state.files = data.files;
    renderFiles();
    showToast(t("ui.files-storage.file-moved-to", { name: folder.name, folder: fileFolderById(parentId)?.name || t("ui.files-storage.all-files") }));
  } catch (error) { showError(error); }
}

function fileMenuIcon(name) {
  return `<svg class="icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;
}

function fileMenuEntry(action, label, icon, extra = "") {
  return `<button type="button" role="menuitem" data-file-menu-action="${esc(action)}"${extra}>${fileMenuIcon(icon)}<span>${esc(label)}</span>${/^(openin|share-menu|saveas|more)$/.test(action) ? '<svg class="icon menu-chevron" aria-hidden="true"><use href="#i-chevron-right"/></svg>' : ""}</button>`;
}

function fileContextTargetRecord() {
  const target = state.fileContextTarget;
  if (!target) return null;
  if (target.type === "folder") {
    const folder = fileFolderById(target.id);
    return folder ? { type: "folder", folder } : null;
  }
  const file = state.files.find((item) => item.id === target.id);
  return file ? { type: "file", file } : null;
}

function renderFileContextMenu() {
  if (!fileContextMenu) return;
  const record = fileContextTargetRecord();
  if (!record) { fileContextMenu.hidden = true; return; }
  const view = state.fileMenuView || "";
  const back = view ? `<button type="button" class="file-menu-back" data-file-menu-back>${fileMenuIcon("arrow-left")}<span>${t("ui.files-storage.back")}</span></button>` : "";
  let items = "";
  if (record.type === "file") {
    const file = record.file;
    const office = canUseOffice(file) ? officeMetaForFile(file) : null;
    if (!view) {
      if (file.shared) {
        items = [
          office ? fileMenuEntry("office-edit", office.editable && file.access !== "view" ? t("ui.compose-manager.edit-in-office") : t("ui.files-storage.view-in-office"), "file") : "",
          office ? fileMenuEntry("office-versions", t("ui.files-storage.version-history"), "history") : "",
          office && office.documentType !== "pdf" ? fileMenuEntry("office-convert", t("ui.files-storage.convert-to-pdf"), "download") : "",
          office ? `<div class="file-menu-sep"></div>` : "",
          fileMenuEntry("preview", t("ui.settings.preview"), "file"),
          fileMenuEntry("download", t("ui.alt8mail-office.download"), "download"),
          fileMenuEntry("info", t("ui.files-storage.file-info"), "info")
        ].join("");
      } else {
        items = [
          office ? fileMenuEntry("office-edit", office.editable ? t("ui.compose-manager.edit-in-office") : t("ui.files-storage.view-in-office"), "file") : "",
          office ? fileMenuEntry("office-versions", t("ui.files-storage.version-history"), "history") : "",
          office && office.documentType !== "pdf" ? fileMenuEntry("office-convert", t("ui.files-storage.convert-to-pdf"), "download") : "",
          office ? `<div class="file-menu-sep"></div>` : "",
          fileMenuEntry("preview", t("ui.settings.preview"), "file"),
          fileMenuEntry("download", t("ui.alt8mail-office.download"), "download"),
          `<div class="file-menu-sep"></div>`,
          fileMenuEntry("openin", t("ui.files-storage.open-in"), "external"),
          fileMenuEntry("copy-link", t("ui.calendar.copy-link"), "link"),
          fileMenuEntry("more-send", t("ui.files-storage.send-via-email"), "send"),
          fileMenuEntry("share-menu", t("ui.calendar.share"), "people"),
          fileMenuEntry("permissions", t("ui.files-storage.manage-permissions"), "lock"),
          `<div class="file-menu-sep"></div>`,
          fileMenuEntry("rename", t("mail.folders.rename"), "pencil"),
          fileMenuEntry("move", t("mail.folders.move"), "folder"),
          fileMenuEntry("copy", t("ui.calendar.copy"), "copy"),
          fileMenuEntry("saveas", t("ui.files-storage.save-as"), "download"),
          `<div class="file-menu-sep"></div>`,
          fileMenuEntry("delete", t("mail.list.quick.delete"), "trash"),
          fileMenuEntry("info", t("ui.files-storage.file-info"), "info"),
          fileMenuEntry("more", t("ui.files-storage.more"), "more")
        ].join("");
      }
    } else if (view === "openin") {
      items = [
        fileMenuEntry("preview", t("ui.files-storage.preview-in-alt8mail"), "expand"),
        fileMenuEntry("open-browser", t("ui.mail-home-pulse-search-reports-sticky-no.open-in-a-new-tab"), "external"),
        file.providerId !== "a8m" && file.externalUrl ? fileMenuEntry("open-provider", t("ui.files-storage.open-in-provider", { provider: fileProviderName(file) }), "cloud") : "",
        fileMenuEntry("openmail", t("ui.files-storage.send-via-email"), "send")
      ].join("");
    } else if (view === "share") {
      items = [
        fileMenuEntry("share-dialog", t("ui.files-storage.share-with-a-link"), "link"),
        fileMenuEntry("permissions", t("ui.files-storage.manage-permissions"), "lock"),
        fileMenuEntry("share-email", t("ui.files-storage.send-as-email-attachment"), "send")
      ].join("");
    } else if (view === "saveas") {
      items = [
        fileMenuEntry("saveas-copy", t("ui.files-storage.save-a-copy-to-cabinet"), "copy"),
        fileMenuEntry("download", t("ui.files-storage.download-to-this-device"), "download")
      ].join("");
    } else if (view === "more") {
      items = [
        fileMenuEntry("more-send", t("ui.files-storage.send-via-email"), "send"),
        fileMenuEntry("more-star", file.starred ? t("ui.files-storage.remove-from-favourites") : t("ui.files-storage.add-to-favourites"), "star"),
        fileMenuEntry("more-refresh", t("ui.files-storage.refresh-cabinet"), "refresh"),
        fileMenuEntry("info", t("ui.files-storage.file-information"), "info")
      ].join("");
    }
  } else {
    const folder = record.folder;
    if (!view) {
      items = [
        fileMenuEntry("folder-open", t("ui.files-storage.open-folder"), "folder"),
        fileMenuEntry("folder-new", t("ui.files-storage.new-subfolder"), "folder-plus"),
        `<div class="file-menu-sep"></div>`,
        fileMenuEntry("folder-rename", t("mail.folders.rename"), "pencil"),
        fileMenuEntry("folder-color", t("ui.files-storage.change-colour"), "sliders"),
        fileMenuEntry("folder-move", t("mail.folders.moveFolder"), "folder"),
        `<div class="file-menu-sep"></div>`,
        fileMenuEntry("folder-delete", t("mail.folders.deleteConfirm"), "trash"),
        fileMenuEntry("folder-info", t("ui.files-storage.folder-info"), "info")
      ].join("");
    }
  }
  fileContextMenu.innerHTML = `${back}${items}`;
  fileContextMenu.hidden = false;
  const point = state.fileMenuPoint || { x: 80, y: 120 };
  const rect = fileContextMenu.getBoundingClientRect();
  fileContextMenu.style.left = `${Math.max(8, Math.min(point.x, window.innerWidth - rect.width - 12))}px`;
  fileContextMenu.style.top = `${Math.max(8, Math.min(point.y, window.innerHeight - rect.height - 12))}px`;
}

function openFileContextMenu(type, id, x, y, view = "") {
  state.fileContextTarget = { type, id };
  state.fileMenuView = view;
  state.fileMenuPoint = { x, y };
  renderFileContextMenu();
}

function closeFileContextMenu() {
  if (!fileContextMenu) return;
  fileContextMenu.hidden = true;
  state.fileContextTarget = null;
  state.fileMenuView = "";
}

function openFileActionDialog(mode, fileId) {
  const folderRecord = mode === "folder-info" ? fileFolderById(fileId) : null;
  const file = mode === "folder-info" ? null : state.files.find((item) => item.id === fileId);
  if (!file && !folderRecord) return;
  state.fileAction = { mode, fileId };
  const title = document.getElementById("fileActionTitle");
  const subtitle = document.getElementById("fileActionSubtitle");
  const body = document.getElementById("fileActionBody");
  const icon = document.getElementById("fileActionIcon");
  icon.innerHTML = fileMenuIcon(mode === "info" ? "info" : mode === "copy" || mode === "saveas" ? "copy" : mode === "move" ? "folder" : "pencil");
  if (mode === "rename") {
    title.textContent = t("ui.files-storage.rename-file");
    subtitle.textContent = t("ui.files-storage.the-new-name-is-visible-to-everyone-you-share-th");
    body.innerHTML = `<label class="form-field"><span>${t("ui.files-storage.file-name")}</span><input id="fileActionName" maxlength="200" value="${esc(file.name)}"></label>
      <div class="dialog-actions"><button class="btn-secondary" data-file-action-cancel type="button">${t("tasks.action.cancel")}</button><button class="btn-primary" id="fileActionConfirm" type="button">${t("ui.files-storage.save-name")}</button></div>`;
  } else if (mode === "move") {
    title.textContent = t("ui.files-storage.move-file");
    subtitle.textContent = t("ui.files-storage.choose-a-cabinet-folder-connected-drive-files-ke");
    body.innerHTML = `<label class="form-field"><span>${t("ui.files-storage.destination")}</span><select id="fileActionFolder">${fileFolderOptions({ selected: file.folderId || "" })}</select></label>
      <div class="dialog-actions"><button class="btn-secondary" data-file-action-cancel type="button">${t("tasks.action.cancel")}</button><button class="btn-primary" id="fileActionConfirm" type="button">${t("ui.files-storage.move-file")}</button></div>`;
  } else if (mode === "copy" || mode === "saveas") {
    title.textContent = mode === "saveas" ? t("ui.files-storage.save-a-copy") : t("ui.files-storage.copy-file");
    subtitle.textContent = t("ui.files-storage.keep-the-original-and-create-another-copy-in-the");
    const base = file.name || t("ui.mail-home-pulse-search-reports-sticky-no.file");
    const ext = base.includes(".") ? base.slice(base.lastIndexOf(".")) : "";
    const stem = ext ? base.slice(0, -ext.length) : base;
    body.innerHTML = `<label class="form-field"><span>${t("ui.files-storage.copy-name")}</span><input id="fileActionName" maxlength="200" value="${esc(`${stem} copy${ext}`)}"></label>
      <label class="form-field"><span>${t("ui.files-storage.destination")}</span><select id="fileActionFolder">${fileFolderOptions({ selected: state.fileFolderId || "" })}</select></label>
      <div class="dialog-actions"><button class="btn-secondary" data-file-action-cancel type="button">${t("tasks.action.cancel")}</button><button class="btn-primary" id="fileActionConfirm" type="button">${mode === "saveas" ? t("ui.files-storage.save-copy") : t("ui.files-storage.copy-file")}</button></div>`;
  } else if (mode === "info") {
    title.textContent = file.name;
    subtitle.textContent = t("ui.files-storage.file-information-and-cabinet-metadata");
    body.innerHTML = `<div class="file-info-grid">
      <div><span>${t("ui.files-storage.type")}</span><strong>${esc(file.mime || file.type || t("mail.reader.unknownSender"))}</strong></div>
      <div><span>${t("mail.details.size")}</span><strong>${esc(formatBytes(file.sizeBytes))}</strong></div>
      <div><span>${t("ui.files-storage.storage")}</span><strong>${esc(fileProviderName(file))}</strong></div>
      <div><span>${t("mail.details.folder")}</span><strong>${esc(fileFolderById(file.folderId)?.path || t("ui.files-storage.all-files"))}</strong></div>
      <div><span>${t("ui.files-storage.owner")}</span><strong>${esc(file.owner?.name || state.user?.name || "—")}</strong></div>
      <div><span>${t("tasks.detail.created")}</span><strong>${esc(formatDateTimeFull(file.createdAt) || "—")}</strong></div>
      <div><span>${t("ui.files-storage.modified")}</span><strong>${esc(formatDateTimeFull(file.modifiedAt) || "—")}</strong></div>
      <div><span>${t("ui.files-storage.version")}</span><strong>${esc(file.version || "1")}</strong></div>
      <div><span>${t("ui.files-storage.file-id")}</span><strong class="mono">${esc(file.id)}</strong></div>
      <div><span>${t("ui.files-storage.checksum")}</span><strong class="mono">${esc(file.checksum || t("ui.files-storage.not-recorded"))}</strong></div>
    </div><div class="dialog-actions"><button class="btn-secondary" data-file-action-cancel type="button">${t("common.close")}</button><button class="btn-primary" data-file-action-copy-link type="button">${t("ui.files-storage.copy-link")}</button></div>`;
  } else if (mode === "folder-info") {
    const folder = folderRecord;
    title.textContent = folder.name;
    subtitle.textContent = t("ui.files-storage.folder-information");
    body.innerHTML = `<div class="file-info-grid"><div><span>${t("ui.files-storage.path")}</span><strong>${esc(folder.path)}</strong></div><div><span>${t("ui.files-storage.items")}</span><strong>${folder.count || 0}</strong></div><div><span>${t("tasks.detail.created")}</span><strong>${esc(formatDateOnly(folder.createdAt) || "—")}</strong></div><div><span>${t("ui.files-storage.updated")}</span><strong>${esc(formatDateOnly(folder.updatedAt) || "—")}</strong></div><div><span>${t("ui.files-storage.folder-id")}</span><strong class="mono">${esc(folder.id)}</strong></div></div><div class="dialog-actions"><button class="btn-secondary" data-file-action-cancel type="button">${t("common.close")}</button></div>`;
  }
  fileActionOverlay.hidden = false;
  setTimeout(() => body.querySelector("input")?.focus(), 40);
}

async function runFileActionDialog() {
  const action = state.fileAction;
  if (!action) return;
  const file = state.files.find((item) => item.id === action.fileId);
  const button = document.getElementById("fileActionConfirm");
  if (!file || !button) return;
  button.disabled = true;
  try {
    if (action.mode === "rename") {
      const name = document.getElementById("fileActionName").value.trim();
      if (!name) { showToast(t("ui.files-storage.give-the-file-a-name")); return; }
      const data = await api(`/api/files/${encodeURIComponent(file.id)}`, { method: "PATCH", body: { name } });
      const index = state.files.findIndex((item) => item.id === file.id);
      if (index >= 0) state.files[index] = data.file;
      await refreshCabinet();
      showToast(t("ui.files-storage.file-renamed"));
    } else if (action.mode === "move") {
      const folderId = document.getElementById("fileActionFolder").value || "";
      await moveFileToFolder(file.id, folderId);
    } else if (action.mode === "copy" || action.mode === "saveas") {
      const name = document.getElementById("fileActionName").value.trim();
      const folderId = document.getElementById("fileActionFolder").value || "";
      const data = await api(`/api/files/${encodeURIComponent(file.id)}/copy`, { method: "POST", body: { name, folderId } });
      state.files.unshift(data.file);
      await refreshCabinet();
      showToast(action.mode === "saveas" ? t("ui.files-storage.copy-saved-to-cabinet") : t("ui.files-storage.file-copied"));
    }
    fileActionOverlay.hidden = true;
    state.fileAction = null;
  } catch (error) { showError(error); }
  finally { button.disabled = false; }
}

async function createShareForFile(file, options = {}) {
  const data = await api(`/api/files/${encodeURIComponent(file.id)}/share`, {
    method: "POST",
    body: {
      access: options.access || "view",
      expiresDays: Number(options.expiresDays) || 7,
      recipientEmail: options.recipientEmail || ""
    }
  });
  if (data.pendingApproval) return { pendingApproval: true };
  return data.share;
}

async function copyFileLink(fileId) {
  const file = state.files.find((item) => item.id === fileId);
  if (!file) return;
  if (file.shared) { showToast(t("ui.files-storage.only-the-file-owner-can-create-a-share-link")); return; }
  try {
    const share = await createShareForFile(file);
    if (share.pendingApproval) {
      showToast(t("ui.files-storage.share-approval-requested-an-administrator-must-a"));
      return;
    }
    const copied = await copyTextToClipboard(share.url);
    showToast(copied ? t("ui.files-storage.share-link-copied") : share.url);
    if (!(file.sharedWith || []).length) file.sharedWith = [t("ui.files-storage.external-link")];
    renderFiles();
  } catch (error) { showError(error); }
}

async function sendFileViaEmail(fileId) {
  const file = state.files.find((item) => item.id === fileId);
  if (!file) return;
  if (file.shared) { showToast(t("ui.files-storage.only-the-file-owner-can-email-this-file")); return; }
  try {
    const session = openCompose({ subject: t("ui.files-storage.sharing-file-subject", { name: file.name }), bodyText: t("ui.files-storage.sharing-file-body", { name: file.name }) + "\n\n" });
    attachPickerSessionId = session.id;
    await attachWorkspaceFile(file.id);
    closeComposeAttach();
    showToast(t("ui.files-storage.file-attached-to-message", { name: file.name }));
  } catch (error) { showError(error); }
}

async function downloadCabinetFile(fileId) {
  const file = state.files.find((item) => item.id === fileId);
  if (!file || !file.contentUrl) { showToast(t("ui.files-storage.download-is-not-available-for-this-file")); return; }
  const link = document.createElement("a");
  link.href = `${file.contentUrl}${file.contentUrl.includes("?") ? "&" : "?"}download=1`;
  link.download = file.name;
  document.body.appendChild(link);
  link.click();
  link.remove();
}

async function handleFileMenuAction(action) {
  const record = fileContextTargetRecord();
  const file = record?.type === "file" ? record.file : null;
  const folder = record?.type === "folder" ? record.folder : null;
  if (["openin", "share-menu", "saveas", "more"].includes(action)) {
    state.fileMenuView = action;
    renderFileContextMenu();
    return;
  }
  closeFileContextMenu();
  if (!record) return;
  if (file && file.shared && ["copy-link", "more-send", "share-menu", "share-dialog", "share-email", "permissions", "rename", "move", "copy", "saveas", "saveas-copy", "delete", "more-star", "openmail"].includes(action)) {
    showToast(t("ui.files-storage.only-the-file-owner-can-manage-sharing-and-file-"));
    return;
  }
  if (action === "office-edit" && file) { await openOfficeEditorById(file.id); return; }
  if (action === "office-versions" && file) { await openOfficeVersions(file.id); return; }
  if (action === "office-convert" && file) { await convertOfficeFile(file.id); return; }
  if (action === "preview" && file) previewFileRecord(file);
  else if (action === "download" && file) await downloadCabinetFile(file.id);
  else if (action === "copy-link" && file) await copyFileLink(file.id);
  else if (action === "share-dialog" && file) openShareDialog(file.id);
  else if (action === "permissions" && file) openShareDialog(file.id);
  else if (action === "share-email" && file) await sendFileViaEmail(file.id);
  else if (action === "rename" && file) openFileActionDialog("rename", file.id);
  else if (action === "move" && file) openFileActionDialog("move", file.id);
  else if (action === "copy" && file) openFileActionDialog("copy", file.id);
  else if (action === "saveas-copy" && file) openFileActionDialog("saveas", file.id);
  else if (action === "delete" && file) await deleteFile(file.id);
  else if (action === "info" && file) openFileActionDialog("info", file.id);
  else if (action === "open-browser" && file) window.open(file.contentUrl, "_blank", "noopener");
  else if (action === "open-provider" && file && file.externalUrl) window.open(file.externalUrl, "_blank", "noopener");
  else if (action === "openmail" && file) await sendFileViaEmail(file.id);
  else if (action === "more-send" && file) await sendFileViaEmail(file.id);
  else if (action === "more-star" && file) await toggleFileStar(file.id);
  else if (action === "more-refresh") await refreshCabinet();
  else if (action === "folder-open" && folder) openFileFolder(folder.id);
  else if (action === "folder-new" && folder) openFolderDialog(null, folder.id);
  else if (action === "folder-rename" && folder) openFolderDialog(folder.id);
  else if (action === "folder-color" && folder) openFolderDialog(folder.id);
  else if (action === "folder-move" && folder) openFolderDialog(folder.id);
  else if (action === "folder-delete" && folder) await deleteFileFolder(folder.id);
  else if (action === "folder-info" && folder) openFileActionDialog("folder-info", folder.id);
}

/* ============================================================
   Alt8Mail Office
   ============================================================ */
const OFFICE_FALLBACK_FORMATS = {
  word: ["docx", "doc", "odt", "rtf", "txt"],
  cell: ["xlsx", "xls", "ods", "csv"],
  slide: ["pptx", "ppt", "odp"],
  pdf: ["pdf"]
};
const OFFICE_VERSION_SOURCE = {
  template: t("ui.alt8mail-office.source-created-from-template"),
  initial: t("ui.alt8mail-office.source-initial-document"),
  editor: t("ui.alt8mail-office.source-saved-in-editor"),
  restore: t("ui.alt8mail-office.source-restored-version")
};
const OFFICE_VIEW_ONLY_EXTENSIONS = new Set(["doc", "xls", "ppt", "pdf"]);

async function loadOfficeConfig({ silent = true } = {}) {
  if (state.delegatedMode) {
    state.office = { enabled: false, ready: false, publicUrl: "", status: "delegated", formats: {} };
    state.officeLoaded = true;
    syncOfficeCabinetUi();
    return;
  }
  try {
    const data = await api("/api/office/config");
    state.office = {
      enabled: Boolean(data.enabled),
      ready: Boolean(data.ready),
      publicUrl: data.publicUrl || "",
      status: data.status || "not_installed",
      formats: data.formats && Object.keys(data.formats).length ? data.formats : OFFICE_FALLBACK_FORMATS
    };
  } catch (error) {
    state.office = { enabled: false, ready: false, publicUrl: "", status: "unavailable", formats: OFFICE_FALLBACK_FORMATS };
    if (!silent) showError(error);
  }
  state.officeLoaded = true;
  syncOfficeCabinetUi();
  if (state.task === "files" && filesView && !filesView.hidden) renderFiles();
  if (state.task === "mail" && state.selectedThreadId && !state.delegatedMode) renderReader();
  const eventOverlay = document.getElementById("eventOverlay");
  if (eventOverlay && !eventOverlay.hidden) renderEventAttachments();
}

function syncOfficeCabinetUi() {
  const button = document.getElementById("newOfficeDocBtn");
  if (button) button.hidden = !state.office.ready || state.delegatedMode;
  const composeButton = document.getElementById("composeNewOfficeDoc");
  if (composeButton) composeButton.hidden = !state.office.ready || state.delegatedMode;
}

function officeMetaForName(name) {
  const ext = String(name || "").split(".").pop().toLowerCase();
  const formats = state.office.formats && Object.keys(state.office.formats).length ? state.office.formats : OFFICE_FALLBACK_FORMATS;
  for (const type of ["word", "cell", "slide", "pdf"]) {
    if ((formats[type] || []).includes(ext)) {
      return { ext, documentType: type, editable: !OFFICE_VIEW_ONLY_EXTENSIONS.has(ext) };
    }
  }
  return null;
}

function officeMetaForFile(file) {
  if (!file || state.delegatedMode || file.providerId !== "a8m") return null;
  return officeMetaForName(file.name);
}

function canUseOffice(file) {
  return Boolean(state.office.ready && officeMetaForFile(file));
}

function officeTypeLabel(type) {
  return { word: t("ui.alt8mail-office.type-document"), cell: t("ui.alt8mail-office.type-spreadsheet"), slide: t("ui.alt8mail-office.type-presentation"), pdf: "PDF" }[type] || t("ui.alt8mail-office.document");
}

function officeTypeIcon(type) {
  return { word: "i-office-word", cell: "i-office-sheet", slide: "i-office-slides", pdf: "i-file" }[type] || "i-file";
}

function officeTypeClass(type) {
  return { word: "office-type-word", cell: "office-type-sheet", slide: "office-type-slide" }[type] || "office-type-word";
}

const OFFICE_HUB_META = {
  word: { label: t("shell.wordDocuments"), singular: t("ui.alt8mail-office.noun-document"), format: "docx", icon: "i-office-word", kicker: t("ui.alt8mail-office.kicker-documents"), description: t("ui.alt8mail-office.draft-letters-plans-and-contracts-then-return-to") },
  cell: { label: t("shell.excelSpreadsheets"), singular: t("ui.alt8mail-office.noun-spreadsheet"), format: "xlsx", icon: "i-office-sheet", kicker: t("ui.alt8mail-office.kicker-spreadsheets"), description: t("ui.alt8mail-office.build-budgets-trackers-and-models-with-your-work") },
  slide: { label: t("shell.powerPointPresentations"), singular: t("ui.alt8mail-office.noun-presentation"), format: "pptx", icon: "i-office-slides", kicker: t("ui.alt8mail-office.kicker-presentations"), description: t("ui.alt8mail-office.create-decks-pitches-and-reports-with-recent-wor") },
};

function officeTypeNoun(type) {
  return OFFICE_HUB_META[type]?.singular || t("ui.alt8mail-office.noun-document");
}

function officeTypePlural(type) {
  return (OFFICE_HUB_META[type]?.label || "documents").toLowerCase();
}

function officeFilesOfType(type) {
  return (state.files || [])
    .filter((file) => file.kind !== "folder" && officeMetaForFile(file)?.documentType === type)
    .slice()
    .sort((a, b) => Date.parse(b.modifiedAt || b.updatedAt || b.createdAt || 0) - Date.parse(a.modifiedAt || a.updatedAt || a.createdAt || 0));
}

function officeMailFilesOfType(type) {
  const rows = [];
  for (const message of state.messages || []) {
    if (message.delegatedOwnerId) continue;
    for (const attachment of message.attachments || []) {
      if (officeMetaForName(attachment.name)?.documentType === type) rows.push({ message, attachment });
    }
  }
  return rows.sort((a, b) => Date.parse(b.message.date || 0) - Date.parse(a.message.date || 0));
}

let officeHubType = "word";
let officeHubOffset = { x: 0, y: 0 };
let officeOpenType = "word";
let officeOpenOffset = { x: 0, y: 0 };
let officeOpenMobile = { session: null, seen: new Map(), poll: null, qr: "", qrSession: "" };
let officeEditorWindow = null;
let officeSearchTimer = null;
let officeSearchSeq = 0;
let officeWindowPersistTimer = null;
const OFFICE_EDITOR_MIN_WIDTH = 560;
const OFFICE_EDITOR_MIN_HEIGHT = 360;
const OFFICE_DOCK_KEY_PREFIX = "a8m.officeDock.v1";

function officeDockStorageKey() {
  return `${OFFICE_DOCK_KEY_PREFIX}.${normalizeEmail(state.user?.email || "guest")}`;
}

function officeEditorWindowStorageKey() {
  return `a8m.officeWindow.v2.${normalizeEmail(state.user?.email || "guest")}`;
}

function officeEditorWindowSnapshot() {
  const state_ = officeEditorWindow || {};
  const snapshot = { maximized: Boolean(state_.maximized), updatedAt: Date.now() };
  for (const key of ["left", "top", "width", "height"]) {
    const value = Number(state_[key]);
    if (state_[key] !== null && state_[key] !== undefined && state_[key] !== "" && Number.isFinite(value)) {
      snapshot[key] = Math.round(value);
    }
  }
  return snapshot;
}

function persistOfficeWindowPreference(value) {
  if (!state.user || !state.csrf) return;
  clearTimeout(officeWindowPersistTimer);
  officeWindowPersistTimer = setTimeout(async () => {
    try {
      const data = await api("/api/preferences", { method: "PATCH", body: { officeWindow: value } });
      if (!data?.preferences) return;
      state.preferences = { ...state.preferences, ...data.preferences };
      if (state.user) state.user.preferences = state.preferences;
    } catch {}
  }, 500);
}

function readOfficeEditorWindowState() {
  if (officeEditorWindow) return officeEditorWindow;
  let local = null;
  try {
    const raw = localStorage.getItem(officeEditorWindowStorageKey());
    local = raw ? JSON.parse(raw) : null;
  } catch {
    local = null;
  }
  const server = state.user?.preferences?.officeWindow;
  const localHasGeometry = local && typeof local === "object"
    && (Number(local.width) > 0 || Number(local.left) > 0 || local.maximized === true);
  const localStamp = Number(local?.updatedAt || 0);
  const serverStamp = Number(server?.updatedAt || 0);
  const candidate = server && typeof server === "object" && serverStamp > localStamp
    ? server
    : (localHasGeometry ? local : (server && typeof server === "object" ? server : {}));
  officeEditorWindow = { ...candidate };
  return officeEditorWindow;
}

function storeOfficeEditorWindowState() {
  if (!officeEditorWindow) return;
  const snapshot = officeEditorWindowSnapshot();
  officeEditorWindow = snapshot;
  try { localStorage.setItem(officeEditorWindowStorageKey(), JSON.stringify(snapshot)); } catch {}
  persistOfficeWindowPreference(snapshot);
}

function officeEditorIsCompact() {
  return window.matchMedia("(max-width: 720px)").matches;
}

function applyOfficeEditorGeometry() {
  const overlay = document.getElementById("officeEditorOverlay");
  const shell = document.getElementById("officeEditorShell");
  if (!overlay || !shell || overlay.hidden) return;
  if (officeEditorIsCompact()) {
    shell.style.left = "";
    shell.style.top = "";
    shell.style.width = "";
    shell.style.height = "";
    return;
  }
  const state_ = readOfficeEditorWindowState();
  if (state_.maximized) {
    overlay.classList.add("is-maximized");
    shell.style.left = "";
    shell.style.top = "";
    shell.style.width = "";
    shell.style.height = "";
    return;
  }
  overlay.classList.remove("is-maximized");
  const margin = 18;
  const viewportWidth = window.innerWidth;
  const viewportHeight = window.innerHeight;
  const maxWidth = Math.max(OFFICE_EDITOR_MIN_WIDTH, viewportWidth - margin * 2);
  const maxHeight = Math.max(OFFICE_EDITOR_MIN_HEIGHT, viewportHeight - margin * 2);
  const preferredWidth = Math.min(maxWidth, Math.max(Math.min(820, maxWidth), Math.round(viewportWidth * 0.78)));
  const preferredHeight = Math.min(maxHeight, Math.max(Math.min(520, maxHeight), Math.round(viewportHeight * 0.82)));
  const width = Number(state_.width) > 0
    ? Math.min(maxWidth, Math.max(OFFICE_EDITOR_MIN_WIDTH, Number(state_.width)))
    : preferredWidth;
  const height = Number(state_.height) > 0
    ? Math.min(maxHeight, Math.max(OFFICE_EDITOR_MIN_HEIGHT, Number(state_.height)))
    : preferredHeight;
  const maxLeft = Math.max(0, viewportWidth - Math.min(220, width));
  const maxTop = Math.max(0, viewportHeight - 54);
  const hasLeft = state_.left !== null && state_.left !== undefined && Number.isFinite(Number(state_.left));
  const hasTop = state_.top !== null && state_.top !== undefined && Number.isFinite(Number(state_.top));
  const left = hasLeft
    ? Math.min(maxLeft, Math.max(0, Number(state_.left)))
    : Math.round((viewportWidth - width) / 2);
  const top = hasTop
    ? Math.min(maxTop, Math.max(0, Number(state_.top)))
    : Math.round((viewportHeight - height) / 2);
  shell.style.left = `${left}px`;
  shell.style.top = `${top}px`;
  shell.style.width = `${width}px`;
  shell.style.height = `${height}px`;
}

function setOfficeEditorMaximized(maximized) {
  const overlay = document.getElementById("officeEditorOverlay");
  const shell = document.getElementById("officeEditorShell");
  const button = document.getElementById("officeEditorMaximize");
  const state_ = readOfficeEditorWindowState();
  state_.maximized = Boolean(maximized);
  storeOfficeEditorWindowState();
  overlay?.classList.toggle("is-maximized", Boolean(maximized));
  if (maximized && shell) {
    shell.style.left = "";
    shell.style.top = "";
    shell.style.width = "";
    shell.style.height = "";
  }
  if (button) {
    button.querySelector("use")?.setAttribute("href", maximized ? "#i-window-restore" : "#i-window-maximize");
    button.setAttribute("aria-label", maximized ? t("ui.alt8mail-office.restore-editor") : t("ui.alt8mail-office.maximize-editor"));
    button.title = maximized ? t("ui.alt8mail-office.restore-editor") : t("ui.alt8mail-office.maximize-editor");
  }
  if (!maximized && shell) applyOfficeEditorGeometry();
}

function normalizeOfficeDockTab(value) {
  if (!value || !value.id || !value.name) return null;
  const name = String(value.name).slice(0, 180);
  const type = ["word", "cell", "slide"].includes(value.documentType)
    ? value.documentType
    : (officeMetaForName(name)?.documentType || "word");
  return {
    id: String(value.id).slice(0, 120),
    name,
    documentType: type,
    minimized: value.minimized !== false,
  };
}

function readOfficeDockStorage() {
  const prefs = state.user?.preferences || {};
  let value = null;
  let local = null;
  try {
    const raw = localStorage.getItem(officeDockStorageKey());
    local = raw ? JSON.parse(raw) : null;
  } catch {
    local = null;
  }
  if (Object.prototype.hasOwnProperty.call(prefs, "officeDock") && !prefs.officeDock) {
    // An explicit server-side clear wins over a stale browser copy.
    try { localStorage.removeItem(officeDockStorageKey()); } catch {}
  } else {
    value = local || prefs.officeDock || null;
  }
  const rawTabs = Array.isArray(value?.tabs) ? value.tabs : (value?.id ? [value] : []);
  const tabs = [];
  const seen = new Set();
  for (const raw of rawTabs) {
    const tab = normalizeOfficeDockTab(raw);
    if (!tab || seen.has(tab.id)) continue;
    seen.add(tab.id);
    tabs.push(tab);
    if (tabs.length >= OFFICE_DOCK_LIMIT) break;
  }
  const activeId = tabs.some((tab) => tab.id === value?.activeId) ? value.activeId : (tabs[0]?.id || "");
  return { tabs, activeId };
}

function officeDockSnapshot() {
  return {
    tabs: officeDockTabs.map((tab) => ({
      id: tab.id, name: tab.name, documentType: tab.documentType, minimized: Boolean(tab.minimized),
    })),
    activeId: officeDockActiveId,
  };
}

function persistOfficeDockPreference(value) {
  if (!state.user || !state.csrf) return;
  api("/api/preferences", { method: "PATCH", body: { officeDock: value } })
    .then((data) => {
      if (!data || !data.preferences) return;
      state.preferences = { ...state.preferences, ...data.preferences };
      if (state.user) state.user.preferences = state.preferences;
    })
    .catch(() => {});
}

function writeOfficeDockStorage() {
  const value = officeDockSnapshot();
  try {
    localStorage.setItem(officeDockStorageKey(), JSON.stringify(value));
  } catch {}
  persistOfficeDockPreference(value);
}

function renderOfficeDock() {
  updateComposeDock();
}

function clearOfficeDock() {
  officeDockTabs = [];
  officeDockActiveId = "";
  try { localStorage.setItem(officeDockStorageKey(), JSON.stringify({ tabs: [], activeId: "" })); } catch {}
  persistOfficeDockPreference(null);
  renderOfficeDock();
}

function restoreOfficeDockFromStorage() {
  const stored = readOfficeDockStorage();
  officeDockTabs = stored.tabs.map((tab) => ({ ...tab, minimized: true }));
  officeDockActiveId = stored.activeId || officeDockTabs[0]?.id || "";
  renderOfficeDock();
}

function officeTabById(tabId) {
  return officeDockTabs.find((tab) => tab.id === tabId) || null;
}

function officeFrameFor(tab) {
  let frame = officeFrames.get(tab.id);
  if (frame && frame.isConnected) return frame;
  const container = document.getElementById("officeEditorFrames");
  if (!container) return null;
  frame = document.createElement("iframe");
  frame.className = "office-editor-frame";
  frame.title = `${tab.name || t("ui.alt8mail-office.office-document")} — editor`;
  frame.allow = "clipboard-read; clipboard-write; fullscreen";
  frame.allowFullscreen = true;
  frame.dataset.officeTabId = tab.id;
  frame.src = `/office-editor?file=${encodeURIComponent(tab.id)}&theme=${effectiveTheme() === "dark" ? "dark" : "light"}`;
  frame.hidden = true;
  frame.addEventListener("load", () => {
    try {
      frame.contentDocument?.addEventListener("pointerdown", () => closeOfficeEditorSearch(), true);
    } catch {}
  });
  container.appendChild(frame);
  officeFrames.set(tab.id, frame);
  return frame;
}

function destroyOfficeFrame(tabId) {
  const frame = officeFrames.get(tabId);
  if (frame) {
    try { frame.src = "about:blank"; } catch {}
    frame.remove();
    officeFrames.delete(tabId);
  }
}

function destroyAllOfficeFrames() {
  for (const tabId of Array.from(officeFrames.keys())) destroyOfficeFrame(tabId);
}

function updateOfficeEditorChrome(tab) {
  const meta = OFFICE_HUB_META[tab.documentType] || OFFICE_HUB_META.word;
  const title = document.getElementById("officeEditorTitle");
  const metaText = document.getElementById("officeEditorMeta");
  const mark = document.querySelector(".office-editor-mark use");
  if (title) title.textContent = tab.name || t("ui.alt8mail-office.document");
  if (metaText) metaText.textContent = `${officeTypeLabel(tab.documentType)} · Alt8Mail Office`;
  if (mark) mark.setAttribute("href", `#${officeTypeIcon(tab.documentType)}`);
  const search = document.getElementById("officeEditorSearch");
  if (search) {
    search.value = "";
    search.placeholder = t("ui.alt8mail-office.search-documents", { type: officeTypePlural(tab.documentType) });
    search.setAttribute("aria-label", t("ui.alt8mail-office.search-documents", { type: officeTypePlural(tab.documentType) }));
  }
  closeOfficeEditorSearch();
}

function activateOfficeTab(tabId, { focus = true } = {}) {
  const tab = officeTabById(tabId);
  if (!tab) return false;
  if (state.delegatedMode) {
    showToast(t("ui.alt8mail-office.office-is-available-in-your-primary-mailbox-not-"), null, null, { duration: 5000 });
    return false;
  }
  const overlay = document.getElementById("officeEditorOverlay");
  if (!overlay) return false;
  const wasHidden = overlay.hidden;
  officeDockActiveId = tab.id;
  officeDockTabs.forEach((entry) => { entry.minimized = entry.id !== tab.id; });
  state.officeFile = { id: tab.id, name: tab.name, documentType: tab.documentType };
  const frame = officeFrameFor(tab);
  if (!frame) return false;
  for (const [id, candidate] of officeFrames) candidate.hidden = id !== tab.id;
  setTimeout(() => {
    try { frame.contentWindow?.dispatchEvent(new Event("resize")); } catch {}
  }, 60);
  if (wasHidden) setOfficeEditorMaximized(false);
  updateOfficeEditorChrome(tab);
  overlay.hidden = false;
  document.body.classList.add("office-editor-open");
  applyOfficeEditorGeometry();
  writeOfficeDockStorage();
  renderOfficeDock();
  syncOfficeEditorTheme();
  if (focus) setTimeout(() => document.getElementById("officeEditorMinimize")?.focus(), 40);
  return true;
}

function minimizeOfficeEditor() {
  const overlay = document.getElementById("officeEditorOverlay");
  if (!overlay || !officeDockTabs.length) return;
  officeDockTabs.forEach((tab) => { tab.minimized = true; });
  overlay.hidden = true;
  document.body.classList.remove("office-editor-open");
  writeOfficeDockStorage();
  renderOfficeDock();
  const count = officeDockTabs.length;
  showToast(count === 1 ? t("ui.alt8mail-office.office-document-minimized-reopen-it-from-the-doc") : tn("ui.alt8mail-office.documents-in-dock", count, { count }), null, null, { duration: 3600 });
}

function restoreOfficeEditor(tabId = "") {
  const id = tabId || officeDockActiveId || officeDockTabs[0]?.id || "";
  if (!id) return;
  activateOfficeTab(id);
}

function parkOfficeEditorForSignOut() {
  if (officeDockTabs.length) {
    officeDockTabs.forEach((tab) => { tab.minimized = true; });
    writeOfficeDockStorage();
  }
  destroyAllOfficeFrames();
  const overlay = document.getElementById("officeEditorOverlay");
  if (overlay) overlay.hidden = true;
  document.body.classList.remove("office-editor-open");
  state.officeFile = null;
  officeDockTabs = [];
  officeDockActiveId = "";
  officeAttachmentTargets.clear();
  officeEditorWindow = null;
  if (officeOpenMobile.poll) clearInterval(officeOpenMobile.poll);
  officeOpenMobile = { session: null, seen: new Map(), poll: null, qr: "", qrSession: "" };
  renderOfficeDock();
}

function syncOfficeEditorTheme() {
  for (const frame of officeFrames.values()) {
    if (!frame.contentWindow) continue;
    try {
      frame.contentWindow.postMessage({ type: "a8m-office-theme", theme: effectiveTheme() }, window.location.origin);
    } catch {}
  }
}

function refreshOfficeAttachmentTarget(target) {
  setTimeout(() => {
    if (target?.kind === "compose") refreshComposeAttachmentAfterOffice(target).catch(() => {});
    else if (target?.kind === "mail") refreshMailAttachmentAfterOffice(target).catch(() => {});
    else refreshCabinet().catch(() => {});
  }, 900);
}

function closeOfficeTab(tabId, { refresh = true } = {}) {
  const overlay = document.getElementById("officeEditorOverlay");
  const index = officeDockTabs.findIndex((tab) => tab.id === tabId);
  if (index < 0) return;
  const tab = officeDockTabs[index];
  const wasOpen = Boolean(overlay && !overlay.hidden);
  const target = officeAttachmentTargets.get(tab.id) || null;
  officeAttachmentTargets.delete(tab.id);
  destroyOfficeFrame(tab.id);
  officeDockTabs.splice(index, 1);
  if (officeDockActiveId === tab.id) {
    const next = officeDockTabs[Math.min(index, officeDockTabs.length - 1)] || officeDockTabs[0] || null;
    officeDockActiveId = next?.id || "";
    state.officeFile = null;
  }
  if (!officeDockTabs.length) {
    if (overlay) {
      overlay.hidden = true;
      overlay.classList.remove("is-maximized");
    }
    document.body.classList.remove("office-editor-open");
    try { localStorage.setItem(officeDockStorageKey(), JSON.stringify({ tabs: [], activeId: "" })); } catch {}
    persistOfficeDockPreference(null);
    state.officeFile = null;
    officeDockActiveId = "";
  } else if (wasOpen && officeDockActiveId) {
    officeDockTabs.forEach((entry) => { entry.minimized = entry.id !== officeDockActiveId; });
    activateOfficeTab(officeDockActiveId, { focus: false });
  } else {
    officeDockTabs.forEach((entry) => { entry.minimized = true; });
    if (!officeDockActiveId) officeDockActiveId = officeDockTabs[0].id;
    writeOfficeDockStorage();
  }
  renderOfficeDock();
  if (refresh) refreshOfficeAttachmentTarget(target);
}

function closeOfficeEditor(options = {}) {
  closeOfficeTab(officeDockActiveId, options);
}

function officeHubAccept(type) {
  return {
    word: ".doc,.docx,.odt,.rtf,.txt",
    cell: ".xls,.xlsx,.ods,.csv",
    slide: ".ppt,.pptx,.odp",
  }[type] || ".doc,.docx,.xls,.xlsx,.ppt,.pptx";
}

async function uploadOfficeFileToCabinet(file, expectedType, { folderId = null } = {}) {
  if (!file) return null;
  if (!state.office.ready) {
    showToast(t("ui.alt8mail-office.office-is-not-enabled-or-healthy-for-this-worksp"), null, null, { duration: 5000 });
    return null;
  }
  if (officeDockTabs.length >= OFFICE_DOCK_LIMIT) {
    showToast(t("ui.alt8mail-office.dock-limit-upload", { limit: OFFICE_DOCK_LIMIT }), null, null, { duration: 6000 });
    return null;
  }
  const type = OFFICE_HUB_META[expectedType] ? expectedType : officeHubUploadType;
  const meta = officeMetaForName(file.name);
  if (!meta || meta.documentType !== type) {
    showToast(t("ui.alt8mail-office.choose-file-for-window", { type: officeTypeNoun(type) }), null, null, { duration: 5000 });
    return null;
  }
  const max = state.attachmentMaxBytes || 8 * 1024 * 1024;
  if (file.size > max) {
    showToast(t("ui.alt8mail-office.file-larger-than-limit", { name: file.name, limit: formatBytes(max) }), null, null, { duration: 5000 });
    return null;
  }
  try {
    showToast(t("ui.alt8mail-office.uploading-to-cabinet", { name: file.name }));
    const dataBase64 = await fileToBase64(file);
    const uploaded = await postJSONWithProgress("/api/attachments", {
      name: file.name,
      mime: file.type || meta.mime || "application/octet-stream",
      dataBase64,
    });
    const created = await api("/api/files", {
      method: "POST",
      body: { providerId: "a8m", attachmentId: uploaded.attachment.id, folderId: folderId ?? (state.fileFolderId || "") },
    });
    if (!created.file) throw new Error(t("ui.alt8mail-office.the-uploaded-file-could-not-be-added-to-cabinet"));
    state.files = [created.file, ...(state.files || []).filter((item) => item.id !== created.file.id)];
    await refreshCabinet();
    return (state.files || []).find((item) => item.id === created.file.id) || created.file;
  } catch (error) {
    showError(error);
    return null;
  }
}

async function uploadOfficeFileFromPC(file) {
  if (!file) return;
  const type = officeHubUploadType;
  closeOfficeHub();
  const cabinetFile = await uploadOfficeFileToCabinet(file, type);
  if (!cabinetFile) return;
  showToast(t("ui.alt8mail-office.uploaded-opening-in-office", { name: cabinetFile.name }));
  openOfficeEditor(cabinetFile);
}

function openOfficeHub(type) {
  if (state.delegatedMode) {
    showToast(t("ui.alt8mail-office.office-is-available-in-your-primary-mailbox-not-"), null, null, { duration: 5000 });
    return;
  }
  officeHubType = OFFICE_HUB_META[type] ? type : "word";
  const overlay = document.getElementById("officeHubOverlay");
  const windowEl = overlay?.querySelector(".office-hub-window");
  if (!overlay || !windowEl) return;
  officeHubOffset = { x: 0, y: 0 };
  windowEl.style.transform = t("ui.alt8mail-office.translate-0px-0px");
  overlay.hidden = false;
  renderOfficeHub();
  if (!(state.files || []).length) {
    refreshCabinet().then(() => { if (!overlay.hidden) renderOfficeHub(); }).catch(() => {});
  }
  setTimeout(() => document.getElementById("officeHubClose")?.focus(), 40);
}

function closeOfficeHub() {
  const overlay = document.getElementById("officeHubOverlay");
  if (overlay) overlay.hidden = true;
}

function renderOfficeHub() {
  const overlay = document.getElementById("officeHubOverlay");
  const body = document.getElementById("officeHubBody");
  const mark = document.getElementById("officeHubMark");
  const title = document.getElementById("officeHubTitle");
  const subtitle = document.getElementById("officeHubSubtitle");
  if (!overlay || !body) return;
  const type = OFFICE_HUB_META[officeHubType] ? officeHubType : "word";
  const meta = OFFICE_HUB_META[type];
  if (mark) mark.innerHTML = `<svg class="icon" aria-hidden="true"><use href="#${meta.icon}"/></svg>`;
  if (title) title.textContent = meta.label;
  if (subtitle) subtitle.textContent = meta.description;
  const ready = Boolean(state.office.ready);
  const files = (state.files || [])
    .filter((file) => file.kind !== "folder" && officeMetaForFile(file)?.documentType === type)
    .slice()
    .sort((a, b) => Date.parse(b.modifiedAt || b.updatedAt || b.createdAt || 0) - Date.parse(a.modifiedAt || a.updatedAt || a.createdAt || 0))
    .slice(0, 8);
  const mails = (state.messages || [])
    .filter((message) => !message.delegatedOwnerId && (message.attachments || []).some((file) => officeMetaForName(file.name)?.documentType === type))
    .slice()
    .sort((a, b) => Date.parse(b.date || 0) - Date.parse(a.date || 0))
    .slice(0, 6);
  const fileRows = files.length ? files.map((file) => `<button class="office-hub-row" type="button" data-office-hub-open="${esc(file.id)}">
    <span class="office-type-option-icon ${officeTypeClass(type)}"><svg class="icon" aria-hidden="true"><use href="#${officeTypeIcon(type)}"/></svg></span>
    <span class="office-hub-row-copy"><strong>${esc(file.name)}</strong><span>${esc(file.path || t("ui.alt8mail-office.files"))}${file.shared ? t("ui.alt8mail-office.shared-with-me") : ""}</span></span>
    <span class="office-hub-row-meta"><b>${esc(formatDateOnly(file.modifiedAt || file.updatedAt || file.createdAt) || "—")}</b>${file.version ? `v${esc(file.version)}` : ""}</span>
  </button>`).join("") : `<div class="office-hub-empty"><svg class="icon" aria-hidden="true"><use href="#${meta.icon}"/></svg><span>${esc(t("ui.alt8mail-office.no-type-yet", { type: meta.label.toLowerCase() }))}</span><button class="btn-secondary small" type="button" data-office-hub-create="${meta.format}">${esc(t("ui.alt8mail-office.create-singular", { type: meta.singular }))}</button></div>`;
  const mailRows = mails.length ? mails.map((message) => {
    const attachments = (message.attachments || []).filter((file) => officeMetaForName(file.name)?.documentType === type);
    const names = attachments.map((file) => file.name).join(", ");
    return `<button class="office-hub-row" type="button" data-office-hub-mail="${esc(message.threadId || message.id)}">
      <span class="office-type-option-icon office-type-mail"><svg class="icon" aria-hidden="true"><use href="#i-mail"/></svg></span>
      <span class="office-hub-row-copy"><strong>${esc(message.subject || t("mail.list.noSubject"))}</strong><span>${esc(message.fromName || message.fromEmail || t("mail.list.unknownSender"))} · ${esc(names)}</span></span>
      <span class="office-hub-row-meta"><b>${esc(formatDateOnly(message.date) || "—")}</b>${attachments.length} attachment${attachments.length === 1 ? "" : "s"}</span>
    </button>`;
  }).join("") : `<div class="office-hub-empty"><svg class="icon" aria-hidden="true"><use href="#i-mail"/></svg><span>${esc(t("ui.alt8mail-office.no-recent-mail-with-type", { type: meta.singular }))}</span></div>`;
  body.innerHTML = `
    <div class="office-hub-hero">
      <span class="office-hub-kicker">${svgUse("i-sparkles")} Alt8Mail Office</span>
      <h1>${type === "word" ? t("ui.alt8mail-office.what-would-you-like-to-write-today") : type === "cell" ? t("ui.alt8mail-office.what-would-you-like-to-build-today") : t("ui.alt8mail-office.what-would-you-like-to-present-today")}</h1>
      <p>${esc(meta.description)} ${t("ui.alt8mail-office.hub-description-suffix")}</p>
      <div class="office-hub-create">
        <button class="office-hub-create-btn primary" type="button" data-office-hub-create="${meta.format}" ${ready ? "" : "disabled"}>
          <span class="office-type-option-icon ${officeTypeClass(type)}"><svg class="icon" aria-hidden="true"><use href="#${meta.icon}"/></svg></span>
          <span><strong>${esc(t("ui.alt8mail-office.new-blank-type", { type: meta.singular }))}</strong><small>${t("ui.alt8mail-office.create-and-open-in-office")}</small></span>
        </button>
        <button class="office-hub-create-btn" type="button" data-office-hub-cabinet>
          <span class="office-type-option-icon"><svg class="icon" aria-hidden="true"><use href="#i-cabinet"/></svg></span>
          <span><strong>${t("ui.alt8mail-office.browse-cabinet")}</strong><small>${t("ui.alt8mail-office.open-an-existing-file")}</small></span>
        </button>
        <button class="office-hub-create-btn" type="button" data-office-hub-upload>
          <span class="office-type-option-icon"><svg class="icon" aria-hidden="true"><use href="#i-upload"/></svg></span>
          <span><strong>${t("ui.alt8mail-office.browse-from-pc")}</strong><small>${t("ui.alt8mail-office.upload-and-open-in-office")}</small></span>
        </button>
      </div>
      ${ready ? "" : `<div class="office-hub-empty" style="margin-top:14px"><svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg><span>${t("ui.alt8mail-office.office-is-not-available-in-this-workspace-yet-a-")}</span></div>`}
    </div>
    <section class="office-hub-section">
      <div class="office-hub-section-head"><div><h3>${esc(t("ui.alt8mail-office.recent-type", { type: meta.label.toLowerCase() }))}</h3><span>${files.length ? esc(tn("ui.alt8mail-office.last-files-from-cabinet", files.length, { count: files.length })) : t("ui.alt8mail-office.your-recent-work-will-appear-here")}</span></div><button class="link-btn" type="button" data-office-hub-cabinet>${t("ui.alt8mail-office.open-cabinet")}</button></div>
      <div class="office-hub-list">${fileRows}</div>
    </section>
    <section class="office-hub-section">
      <div class="office-hub-section-head"><div><h3>${t("ui.alt8mail-office.from-your-inbox")}</h3><span>${esc(t("ui.alt8mail-office.messages-carrying-type", { type: meta.singular }))}</span></div></div>
      <div class="office-hub-list">${mailRows}</div>
    </section>
    <div class="office-hub-foot"><span>${t("ui.alt8mail-office.minimize-an-office-editor-to-keep-it-in-the-dock")}</span><span>${esc(state.organizationName || t("ui.alt8mail-office.alt8mail-workspace"))}</span></div>`;
  body.scrollTop = 0;
}

function svgUse(id) {
  return `<svg class="icon" aria-hidden="true"><use href="#${id}"/></svg>`;
}

async function openOfficeEditorById(fileId) {
  let file = (state.files || []).find((item) => item.id === fileId);
  if (!file) {
    await refreshCabinet();
    file = (state.files || []).find((item) => item.id === fileId);
  }
  if (!file) {
    showToast(t("ui.alt8mail-office.that-file-is-no-longer-available-in-this-cabinet"));
    if (officeTabById(fileId)) closeOfficeTab(fileId, { refresh: false });
    return;
  }
  openOfficeEditor(file);
}

function openOfficeEditor(file) {
  const meta = officeMetaForFile(file);
  if (!state.office.ready || !meta) {
    showToast(t("ui.alt8mail-office.office-is-not-enabled-or-healthy-for-this-worksp"), null, null, { duration: 5000 });
    return;
  }
  let tab = officeTabById(file.id);
  if (!tab) {
    if (officeDockTabs.length >= OFFICE_DOCK_LIMIT) {
      showToast(t("ui.alt8mail-office.dock-limit-open", { limit: OFFICE_DOCK_LIMIT }), null, null, { duration: 6000 });
      return;
    }
    tab = {
      id: file.id,
      name: file.name || t("ui.alt8mail-office.document"),
      documentType: meta.documentType,
      minimized: false,
    };
    officeDockTabs.push(tab);
  } else {
    tab.name = file.name || tab.name;
    tab.documentType = meta.documentType;
  }
  activateOfficeTab(tab.id);
}

function closeOfficeEditorSearch() {
  const results = document.getElementById("officeEditorSearchResults");
  const input = document.getElementById("officeEditorSearch");
  if (results) results.hidden = true;
  if (input) input.setAttribute("aria-expanded", "false");
}

function renderOfficeEditorSearch() {
  const input = document.getElementById("officeEditorSearch");
  const results = document.getElementById("officeEditorSearchResults");
  const tab = officeTabById(officeDockActiveId);
  if (!input || !results || !tab || document.getElementById("officeEditorOverlay")?.hidden) return;
  const type = tab.documentType || "word";
  const query = String(input.value || "").trim().toLowerCase();
  const matches = (values) => !query || values.some((value) => String(value || "").toLowerCase().includes(query));
  const files = officeFilesOfType(type)
    .filter((file) => matches([file.name, file.path, file.description]))
    .slice(0, query ? 6 : 5);
  const mails = officeMailFilesOfType(type)
    .filter(({ message, attachment }) => matches([attachment.name, message.subject, message.fromName, message.fromEmail]))
    .slice(0, query ? 5 : 3);
  const fileRows = files.map((file) => `<button class="office-search-row" type="button" role="option" data-office-search-file="${esc(file.id)}">
    <span class="office-search-row-icon ${officeTypeClass(type)}"><svg class="icon" aria-hidden="true"><use href="#${officeTypeIcon(type)}"/></svg></span>
    <span class="office-search-row-copy"><strong>${esc(file.name)}</strong><span>${esc(file.path || t("nav.files"))} · ${esc(formatDateOnly(file.modifiedAt || file.updatedAt || file.createdAt) || t("ui.alt8mail-office.recently-updated"))}</span></span>
    <span class="office-search-row-go">${t("tasks.status.open")}</span>
  </button>`).join("");
  const mailRows = mails.map(({ message, attachment }) => `<button class="office-search-row" type="button" role="option" data-office-search-attachment="${esc(attachment.id)}" data-office-search-name="${esc(attachment.name || t("ui.mail-home-pulse-search-reports-sticky-no.attachment"))}" data-office-search-message="${esc(message.id)}">
    <span class="office-search-row-icon office-search-row-mail"><svg class="icon" aria-hidden="true"><use href="#i-mail"/></svg></span>
    <span class="office-search-row-copy"><strong>${esc(attachment.name || t("ui.mail-home-pulse-search-reports-sticky-no.attachment"))}</strong><span>${esc(message.subject || t("mail.list.noSubject"))} · ${esc(message.fromName || message.fromEmail || t("tasks.row.email"))}</span></span>
    <span class="office-search-row-go">${t("tasks.status.open")}</span>
  </button>`).join("");
  const total = files.length + mails.length;
  results.innerHTML = `<div class="office-search-head"><span>${query ? t("mail.search.results") : esc(t("ui.alt8mail-office.recent-type", { type: officeTypePlural(type) }))}</span><span>${esc(tn("ui.alt8mail-office.match-count", total, { count: total }))}</span></div>
    ${fileRows ? `<div class="office-search-group"><span class="office-search-group-label">${t("nav.files")}</span>${fileRows}</div>` : ""}
    ${mailRows ? `<div class="office-search-group"><span class="office-search-group-label">${t("ui.alt8mail-office.email-attachments")}</span>${mailRows}</div>` : ""}
    ${!total ? `<div class="office-search-empty"><svg class="icon" aria-hidden="true"><use href="#i-search"/></svg><strong>No ${esc(officeTypePlural(type))} found</strong><span>${t("ui.alt8mail-office.try-another-name-or-browse-cabinet-and-email-fro")}</span></div>` : ""}
    <div class="office-search-foot"><button type="button" data-office-open-folder><svg class="icon" aria-hidden="true"><use href="#i-folder-open"/></svg>${esc(t("ui.alt8mail-office.browse-all-type", { type: officeTypePlural(type) }))}</button></div>`;
  results.hidden = false;
  input.setAttribute("aria-expanded", "true");
}

function scheduleOfficeSearchRemote(query) {
  clearTimeout(officeSearchTimer);
  const value = String(query || "").trim();
  if (value.length < 2) return;
  const sequence = ++officeSearchSeq;
  officeSearchTimer = setTimeout(async () => {
    try {
      const data = await api(`/api/search?q=${encodeURIComponent("attachment:" + value)}`);
      if (sequence !== officeSearchSeq) return;
      mergeSearchMessages(data.messages || []);
      renderOfficeEditorSearch();
    } catch {}
  }, 260);
}

async function loadOfficeMailContext() {
  try {
    const data = await api("/api/search?q=has:attachment");
    mergeSearchMessages(data.messages || []);
    renderOfficeOpenDialog();
  } catch {}
}

function openOfficeSearchFile(fileId) {
  closeOfficeEditorSearch();
  openOfficeEditorById(fileId).catch(showError);
}

function openOfficeSearchAttachment(button) {
  closeOfficeEditorSearch();
  editMailAttachmentInOffice(
    button.getAttribute("data-office-search-attachment") || "",
    button.getAttribute("data-office-search-name") || t("ui.mail-home-pulse-search-reports-sticky-no.attachment"),
    button.getAttribute("data-office-search-message") || ""
  ).catch(showError);
}

function renderOfficeOpenMobile() {
  const host = document.getElementById("officeOpenQr");
  const note = document.getElementById("officeOpenMobileNote");
  const copy = document.getElementById("officeOpenCopyLink");
  const list = document.getElementById("officeOpenMobileList");
  const session = officeOpenMobile.session;
  if (!host) return;
  if (!session?.active) {
    host.innerHTML = `<div class="office-open-qr-expired"><svg class="icon" aria-hidden="true"><use href="#i-clock"/></svg><strong>${t("ui.alt8mail-office.link-expired")}</strong><span>${t("ui.alt8mail-office.generate-a-new-qr-to-keep-receiving-files")}</span></div>`;
    if (note) note.textContent = t("ui.alt8mail-office.generate-a-fresh-qr-code-to-receive-a-file-from-");
    if (copy) copy.hidden = true;
  } else {
    renderOfficeOpenQr(host, session);
    if (note) note.textContent = t("ui.alt8mail-office.upload-link-connected", { expires: formatRelativeTime(session.expiresAt) });
    if (copy) copy.hidden = false;
  }
  const uploads = session?.uploads || [];
  if (list) {
    list.hidden = !uploads.length;
    list.innerHTML = uploads.slice(0, 4).map((item) => `<div class="office-open-mobile-item is-${esc(item.status || "uploading")}">
      <span class="office-open-mobile-item-icon"><svg class="icon" aria-hidden="true"><use href="#${item.status === "done" ? "i-check" : "i-upload"}"/></svg></span>
      <div><strong>${esc(item.name || t("ui.alt8mail-office.mobile-upload"))}</strong><span>${item.status === "done" ? t("ui.alt8mail-office.ready-to-open") : `${Math.max(0, Math.min(100, Number(item.progress) || 0))}% · ${esc(item.status || "uploading")}`}</span></div>
    </div>`).join("");
  }
}

function renderOfficeOpenQr(host, session) {
  if (!session?.url) return;
  if (officeOpenMobile.qrSession === session.id && host.querySelector("canvas, img")) return;
  host.innerHTML = "";
  if (!window.QRCode) {
    host.innerHTML = `<a class="upload-qr-fallback" href="${esc(session.url)}" target="_blank" rel="noopener">${t("ui.alt8mail-office.open-upload-page")}</a>`;
    return;
  }
  try {
    new window.QRCode(host, {
      text: session.url, width: 148, height: 148, correctLevel: window.QRCode.CorrectLevel.M,
      colorDark: "#0b1a2a", colorLight: "#ffffff"
    });
    officeOpenMobile.qrSession = session.id;
  } catch {
    host.innerHTML = `<a class="upload-qr-fallback" href="${esc(session.url)}" target="_blank" rel="noopener">${t("ui.alt8mail-office.open-upload-page")}</a>`;
  }
}

async function ensureOfficeOpenMobileSession(force = false) {
  const host = document.getElementById("officeOpenQr");
  if (!host) return;
  if (force && officeOpenMobile.session?.id) {
    await api(`/api/upload-sessions/${encodeURIComponent(officeOpenMobile.session.id)}`, { method: "DELETE" }).catch(() => {});
    officeOpenMobile.session = null;
  }
  if (!officeOpenMobile.session?.active) {
    const data = await api("/api/upload-sessions", { method: "POST", body: { folderId: state.fileFolderId || "" } });
    officeOpenMobile.session = data.session;
    officeOpenMobile.seen = new Map();
    officeOpenMobile.qrSession = "";
  }
  startOfficeOpenMobilePoll();
  renderOfficeOpenMobile();
}

function startOfficeOpenMobilePoll() {
  if (officeOpenMobile.poll) clearInterval(officeOpenMobile.poll);
  officeOpenMobile.poll = setInterval(() => refreshOfficeOpenMobile().catch(() => {}), 2400);
}

async function refreshOfficeOpenMobile() {
  const overlay = document.getElementById("officeOpenOverlay");
  const session = officeOpenMobile.session;
  if (!overlay || overlay.hidden || !session?.id) return;
  let data;
  try {
    data = await api(`/api/upload-sessions/${encodeURIComponent(session.id)}`);
  } catch {
    return;
  }
  officeOpenMobile.session = data.session;
  const completed = [];
  for (const item of data.session?.uploads || []) {
    const previous = officeOpenMobile.seen.get(item.id);
    officeOpenMobile.seen.set(item.id, item.status);
    if (item.status === "done" && previous !== "done") completed.push(item);
  }
  renderOfficeOpenMobile();
  if (completed.length) {
    await refreshCabinet().catch(() => {});
    for (const item of completed) {
      const file = (state.files || []).find((entry) => item.fileId && entry.id === item.fileId)
        || (state.files || []).find((entry) => entry.name === item.name);
      if (!file) continue;
      const meta = officeMetaForFile(file);
      if (!meta || meta.documentType !== officeOpenType) {
        showToast(t("ui.alt8mail-office.reached-cabinet-only-type", { name: file.name, type: officeTypePlural(officeOpenType) }));
        continue;
      }
      closeOfficeOpenDialog();
      showToast(t("ui.alt8mail-office.opening-from-phone", { name: file.name }));
      openOfficeEditor(file);
      return;
    }
  }
  if (!data.session?.active) {
    clearInterval(officeOpenMobile.poll);
    officeOpenMobile.poll = null;
    renderOfficeOpenMobile();
  }
}

function renderOfficeOpenDialog() {
  const meta = OFFICE_HUB_META[officeOpenType] || OFFICE_HUB_META.word;
  const mark = document.getElementById("officeOpenMark");
  const kind = document.getElementById("officeOpenKind");
  const title = document.getElementById("officeOpenTitle");
  const subtitle = document.getElementById("officeOpenSubtitle");
  const browseHint = document.getElementById("officeOpenBrowseHint");
  const typeNote = document.getElementById("officeOpenTypeNote");
  if (mark) mark.innerHTML = `<svg class="icon" aria-hidden="true"><use href="#${meta.icon}"/></svg>`;
  if (kind) kind.textContent = officeTypeLabel(officeOpenType);
  if (title) title.textContent = `Open a ${meta.singular}`;
  if (subtitle) subtitle.textContent = t("ui.alt8mail-office.open-editor-subtitle", { type: meta.singular });
  if (browseHint) browseHint.textContent = t("ui.alt8mail-office.choose-from-device", { type: meta.singular });
  if (typeNote) typeNote.textContent = t("ui.alt8mail-office.only-type-opens", { type: officeTypePlural(officeOpenType) });
  const files = officeFilesOfType(officeOpenType);
  const cabinetCount = document.getElementById("officeOpenCabinetCount");
  const cabinetList = document.getElementById("officeOpenCabinetList");
  if (cabinetCount) cabinetCount.textContent = `${files.length} ${files.length === 1 ? "file" : "files"} available`;
  if (cabinetList) {
    cabinetList.innerHTML = files.length ? files.map((file) => `<button class="office-open-row" type="button" data-office-open-file="${esc(file.id)}">
      <span class="office-open-row-icon ${officeTypeClass(officeOpenType)}"><svg class="icon" aria-hidden="true"><use href="#${officeTypeIcon(officeOpenType)}"/></svg></span>
      <span class="office-open-row-copy"><strong>${esc(file.name)}</strong><span>${esc(file.path || t("nav.files"))} · ${esc(formatDateOnly(file.modifiedAt || file.updatedAt || file.createdAt) || t("ui.alt8mail-office.recently-updated"))}</span></span>
      <span class="office-open-row-go">${t("tasks.status.open")}</span>
    </button>`).join("") : `<div class="office-open-empty"><svg class="icon" aria-hidden="true"><use href="#${meta.icon}"/></svg><strong>${esc(t("ui.alt8mail-office.no-type-in-cabinet", { type: officeTypePlural(officeOpenType) }))}</strong><span>${t("ui.alt8mail-office.upload-one-from-this-device-or-your-phone")}</span></div>`;
  }
  const mails = officeMailFilesOfType(officeOpenType);
  const mailCount = document.getElementById("officeOpenMailCount");
  const mailList = document.getElementById("officeOpenMailList");
  if (mailCount) mailCount.textContent = `${mails.length} attachment${mails.length === 1 ? "" : "s"} found`;
  if (mailList) {
    mailList.innerHTML = mails.length ? mails.map(({ message, attachment }) => `<button class="office-open-row" type="button" data-office-open-attachment="${esc(attachment.id)}" data-office-open-attachment-name="${esc(attachment.name || t("ui.mail-home-pulse-search-reports-sticky-no.attachment"))}" data-office-open-message="${esc(message.id)}">
      <span class="office-open-row-icon office-open-row-mail"><svg class="icon" aria-hidden="true"><use href="#i-mail"/></svg></span>
      <span class="office-open-row-copy"><strong>${esc(attachment.name || t("ui.mail-home-pulse-search-reports-sticky-no.attachment"))}</strong><span>${esc(message.subject || t("mail.list.noSubject"))} · ${esc(message.fromName || message.fromEmail || t("tasks.row.email"))}</span></span>
      <span class="office-open-row-go">${t("tasks.status.open")}</span>
    </button>`).join("") : `<div class="office-open-empty"><svg class="icon" aria-hidden="true"><use href="#i-mail"/></svg><strong>${esc(t("ui.alt8mail-office.no-email-type", { type: officeTypePlural(officeOpenType) }))}</strong><span>${t("ui.alt8mail-office.messages-with-matching-attachments-will-appear-h")}</span></div>`;
  }
  renderOfficeOpenMobile();
}

function openOfficeOpenDialog() {
  const tab = officeTabById(officeDockActiveId);
  if (!tab) return;
  officeOpenType = tab.documentType || "word";
  officeOpenOffset = { x: 0, y: 0 };
  const overlay = document.getElementById("officeOpenOverlay");
  const windowEl = document.getElementById("officeOpenWindow");
  if (!overlay || !windowEl) return;
  windowEl.style.transform = t("ui.alt8mail-office.translate-0px-0px");
  overlay.hidden = false;
  renderOfficeOpenDialog();
  refreshCabinet().then(() => { if (!overlay.hidden) renderOfficeOpenDialog(); }).catch(() => {});
  loadOfficeMailContext();
  ensureOfficeOpenMobileSession().catch(showError);
  setTimeout(() => document.getElementById("officeOpenClose")?.focus(), 40);
}

function closeOfficeOpenDialog() {
  const overlay = document.getElementById("officeOpenOverlay");
  if (overlay) overlay.hidden = true;
  if (officeOpenMobile.poll) {
    clearInterval(officeOpenMobile.poll);
    officeOpenMobile.poll = null;
  }
}

async function editComposeAttachmentInOffice(sessionId, index) {
  const session = sessionById(sessionId);
  const file = session?.files?.[index];
  if (!session || !file) return;
  if (!state.office.ready) {
    showToast(t("ui.alt8mail-office.office-is-not-enabled-or-healthy-for-this-worksp"), null, null, { duration: 5000 });
    return;
  }
  if (!file.id) {
    showToast(t("ui.alt8mail-office.this-attachment-cannot-be-opened-in-office"));
    return;
  }
  let sourceFileId = file.sourceFileId || "";
  if (!sourceFileId) {
    const data = await api("/api/files", {
      method: "POST",
      body: {
        providerId: "a8m",
        attachmentId: file.id,
        name: file.name || t("ui.compose-manager.attachment"),
        description: t("ui.alt8mail-office.edited-in-office-from-a-compose-attachment")
      }
    });
    sourceFileId = data.file.id;
    file.sourceFileId = sourceFileId;
    await refreshCabinet();
  }
  let cabinetFile = (state.files || []).find((item) => item.id === sourceFileId);
  if (!cabinetFile) {
    await refreshCabinet();
    cabinetFile = (state.files || []).find((item) => item.id === sourceFileId);
  }
  if (!cabinetFile) {
    showToast(t("ui.alt8mail-office.that-document-is-no-longer-available-in-the-cabi"));
    return;
  }
  officeAttachmentTargets.set(cabinetFile.id, {
    kind: "compose",
    sessionId,
    attachmentId: file.id,
    sourceFileId,
    name: file.name || cabinetFile.name,
    originalVersion: cabinetFile.version || "1"
  });
  if (attachPickerSessionId === sessionId && !composeAttachOverlay.hidden) closeComposeAttach();
  openOfficeEditor(cabinetFile);
}

async function refreshComposeAttachmentAfterOffice(target, attempt = 0) {
  if (!target || target.refreshing) return;
  target.refreshing = true;
  try {
    const session = sessionById(target.sessionId);
    if (!session) return;
    await refreshCabinet();
    const index = session.files.findIndex((file) => file.id === target.attachmentId);
    if (index < 0) return;
    const current = (state.files || []).find((file) => file.id === target.sourceFileId);
    if (!current) return;
    if (String(current.version || "1") === String(target.originalVersion || "1")) {
      // The Document Server callback can lag behind the editor close. Poll
      // long enough for a slow save, and also wake early on the editor's
      // saved-state message.
      if (attempt < 15) {
        target.pendingRetry = true;
        setTimeout(() => {
          target.pendingRetry = false;
          target.refreshing = false;
          refreshComposeAttachmentAfterOffice(target, attempt + 1).catch(() => {});
        }, 2000);
      }
      return;
    }
    const response = await fetch(`/api/files/${encodeURIComponent(target.sourceFileId)}/content`, {
      credentials: "same-origin",
      headers: delegatedRequestHeaders()
    });
    if (!response.ok) return;
    const blob = await response.blob();
    const name = current.name || target.name || t("ui.mail-home-pulse-search-reports-sticky-no.attachment");
    const upload = new File([blob], name, { type: current.mime || blob.type || "application/octet-stream" });
    const max = state.attachmentMaxBytes || 8 * 1024 * 1024;
    if (upload.size > max) {
      showToast(t("ui.alt8mail-office.updated-file-too-large", { name, limit: formatBytes(max) }), null, null, { duration: 6000 });
      return;
    }
    const dataBase64 = await fileToBase64(upload);
    const data = await api("/api/attachments", {
      method: "POST",
      body: { name, mime: upload.type || current.mime || "application/octet-stream", dataBase64 }
    });
    const replacement = data.attachment;
    replacement.sourceFileId = target.sourceFileId;
    session.files[index] = replacement;
    updateComposeFiles(session);
    refreshAttachPickerIfOpen();
    session.dirty = true;
    scheduleComposeSave(session);
    showToast(t("ui.alt8mail-office.compose-attachment-updated-from-office"));
  } finally {
    if (!target.pendingRetry) target.refreshing = false;
  }
}

async function refreshMailAttachmentAfterOffice(target, attempt = 0) {
  if (!target || target.refreshing) return;
  target.refreshing = true;
  try {
    await refreshCabinet();
    const current = (state.files || []).find((file) => file.id === target.sourceFileId);
    if (!current) return;
    if (String(current.version || "1") === String(target.originalVersion || "1")) {
      if (attempt < 10) {
        target.pendingRetry = true;
        setTimeout(() => {
          target.pendingRetry = false;
          target.refreshing = false;
          refreshMailAttachmentAfterOffice(target, attempt + 1).catch(() => {});
        }, 2000);
      }
      return;
    }
    const message = target.messageId ? messageById(target.messageId) : null;
    showToast(t("ui.alt8mail-office.updated-copy-saved", { name: current.name }), t("ui.alt8mail-office.reply-with-file"), async () => {
      const session = message
        ? replyToMessage(message)
        : openCompose({ subject: t("ui.alt8mail-office.updated-file-subject", { name: current.name }), bodyText: t("ui.alt8mail-office.updated-file-body", { name: current.name }) + "\n\n" });
      if (!session) return;
      await attachWorkspaceFile(current.id, session.id);
      showToast(t("ui.alt8mail-office.updated-file-attached-to-the-draft"));
    }, { duration: 9000 });
  } finally {
    if (!target.pendingRetry) target.refreshing = false;
  }
}

const OFFICE_NEW_FORMATS = {
  docx: { label: t("ui.alt8mail-office.document"), placeholder: t("ui.alt8mail-office.untitled-document"), title: t("ui.alt8mail-office.new-word-document"), intro: t("ui.alt8mail-office.blank-word-intro") },
  xlsx: { label: t("ui.alt8mail-office.spreadsheet"), placeholder: t("ui.alt8mail-office.untitled-spreadsheet"), title: t("ui.alt8mail-office.new-excel-spreadsheet"), intro: t("ui.alt8mail-office.blank-excel-intro") },
  pptx: { label: t("ui.alt8mail-office.presentation"), placeholder: t("ui.alt8mail-office.untitled-presentation"), title: t("ui.alt8mail-office.new-powerpoint-presentation"), intro: t("ui.alt8mail-office.blank-powerpoint-intro") },
};

function selectedOfficeNewFormat() {
  return document.querySelector('input[name="officeNewType"]:checked')?.value || "docx";
}

function syncOfficeNewFormat(format, { focus = false } = {}) {
  const next = OFFICE_NEW_FORMATS[format] ? format : "docx";
  const input = document.getElementById("officeNewName");
  const title = document.getElementById("officeNewTitle");
  const intro = document.getElementById("officeNewIntro");
  const meta = OFFICE_NEW_FORMATS[next];
  document.querySelectorAll("input[name=officeNewType]").forEach((radio) => { radio.checked = radio.value === next; });
  document.querySelectorAll("[data-office-type-option]").forEach((option) => {
    option.classList.toggle("is-selected", option.getAttribute("data-office-type-option") === next);
  });
  if (input) input.placeholder = meta.placeholder;
  if (title) title.textContent = meta.title;
  if (intro) intro.textContent = meta.intro;
  if (focus && input) input.focus();
}

function openOfficeNewDialog(options = {}) {
  if (!state.office.ready) {
    showToast(t("ui.alt8mail-office.office-is-not-enabled-or-healthy-for-this-worksp"), null, null, { duration: 5000 });
    return;
  }
  if (officeDockTabs.length >= OFFICE_DOCK_LIMIT) {
    showToast(t("ui.alt8mail-office.dock-limit-create", { limit: OFFICE_DOCK_LIMIT }), null, null, { duration: 6000 });
    return;
  }
  state.officeNewComposeSession = options.composeSessionId || "";
  const overlay = document.getElementById("officeNewOverlay");
  const input = document.getElementById("officeNewName");
  const error = document.getElementById("officeNewError");
  if (!overlay || !input) return;
  input.value = "";
  syncOfficeNewFormat(options.format || "docx");
  const folderNote = document.getElementById("officeNewFolderNote");
  if (folderNote) {
    const folder = fileFolderById(state.fileFolderId);
    folderNote.textContent = t("ui.alt8mail-office.saving-to-folder", { folder: folder ? folder.path : t("ui.files-storage.all-files") });
  }
  if (error) { error.hidden = true; error.textContent = ""; }
  overlay.hidden = false;
  setTimeout(() => input.focus(), 40);
}

function closeOfficeNewDialog() {
  const overlay = document.getElementById("officeNewOverlay");
  if (overlay) overlay.hidden = true;
  state.officeNewComposeSession = "";
}

async function createOfficeDocument() {
  const overlay = document.getElementById("officeNewOverlay");
  const input = document.getElementById("officeNewName");
  const error = document.getElementById("officeNewError");
  const button = document.getElementById("officeNewCreate");
  if (!overlay || !input || !button) return;
  const format = selectedOfficeNewFormat();
  if (error) { error.hidden = true; error.textContent = ""; }
  button.disabled = true;
  const label = button.innerHTML;
  const composeSessionId = state.officeNewComposeSession;
  state.officeNewComposeSession = "";
  button.textContent = t("ui.alt8mail-office.creating");
  try {
    const data = await api("/api/office/documents", {
      method: "POST",
      body: { name: input.value.trim() || input.placeholder || t("ui.alt8mail-office.untitled"), format, folderId: state.fileFolderId || "" }
    });
    overlay.hidden = true;
    await refreshCabinet();
    if (data.file && composeSessionId) {
      const attachment = await attachWorkspaceFile(data.file.id, composeSessionId);
      if (attachment) {
        officeAttachmentTargets.set(data.file.id, {
          kind: "compose",
          sessionId: composeSessionId,
          attachmentId: attachment.id,
          sourceFileId: data.file.id,
          name: data.file.name || attachment.name,
          originalVersion: data.file.version || "1"
        });
        closeComposeAttach();
      }
    }
    if (data.file) openOfficeEditor(data.file);
  } catch (err) {
    if (error) {
      error.textContent = err.message || t("ui.alt8mail-office.could-not-create-the-document");
      error.hidden = false;
    }
  } finally {
    button.disabled = false;
    button.innerHTML = label;
  }
}

async function openOfficeVersions(fileId) {
  const overlay = document.getElementById("officeVersionsOverlay");
  const list = document.getElementById("officeVersionList");
  const meta = document.getElementById("officeVersionsMeta");
  if (!overlay || !list) return;
  state.officeVersionsFileId = fileId;
  const file = (state.files || []).find((item) => item.id === fileId);
  if (meta) meta.textContent = file ? t("ui.alt8mail-office.file-version-note", { name: file.name }) : t("ui.alt8mail-office.every-editor-save-is-kept-as-an-immutable-versio");
  list.innerHTML = `<div class="office-version-empty">${t("ui.alt8mail-office.loading-versions")}</div>`;
  const comparePanel = document.getElementById("officeComparePanel");
  if (comparePanel) comparePanel.hidden = true;
  overlay.hidden = false;
  try {
    const data = await api(`/api/office/documents/${encodeURIComponent(fileId)}/versions`);
    renderOfficeVersions(data);
  } catch (error) {
    list.innerHTML = `<div class="office-version-empty">${esc(error.message || t("ui.alt8mail-office.could-not-load-document-versions"))}</div>`;
  }
}

function renderOfficeVersions(data) {
  const list = document.getElementById("officeVersionList");
  if (!list) return;
  const versions = Array.isArray(data.versions) ? data.versions : [];
  state.officeVersions = versions;
  state.officeVersionsAccess = data.access || "owner";
  const officeDocument = data.document || null;
  const comparePanel = document.getElementById("officeComparePanel");
  if (!versions.length) {
    state.officeVersions = [];
    if (comparePanel) comparePanel.hidden = true;
    list.innerHTML = `<div class="office-version-empty">${t("ui.alt8mail-office.no-versions-yet-open-this-document-in-office-onc")}</div>`;
    return;
  }
  list.innerHTML = versions.map((version) => {
    const current = Boolean(version.current);
    const source = OFFICE_VERSION_SOURCE[version.source] || t("ui.alt8mail-office.saved-version");
    const canRestore = officeDocument && officeDocument.editable && !current;
    const warnings = Array.isArray(version.dlpWarnings) ? version.dlpWarnings : [];
    const reviewStatus = version.reviewStatus === "approved" ? "approved" : version.reviewStatus === "changes_requested" ? "changes" : "";
    const reviewChip = reviewStatus === "approved"
      ? ` <span class="office-version-chip office-review-approved">${t("ui.alt8mail-office.approved")}</span>`
      : reviewStatus === "changes"
        ? ` <span class="office-version-chip office-review-changes">${t("ui.alt8mail-office.changes-requested")}</span>`
        : "";
    const reviewMeta = version.reviewStatus
      ? esc(t("ui.alt8mail-office.reviewed-by", { status: reviewStatus === "approved" ? t("ui.alt8mail-office.approved") : t("ui.alt8mail-office.changes-requested"), reviewer: version.reviewedBy || t("ui.alt8mail-office.a-reviewer") })) + `${version.reviewedAt ? ` ${esc(new Date(version.reviewedAt).toLocaleString())}` : ""}${version.reviewNote ? ` — ${esc(version.reviewNote)}` : ""}`
      : "";
    const canReview = state.officeVersionsAccess === "owner" || state.officeVersionsAccess === "edit";
    const dlp = version.dlpClassification
      ? ` <span class="office-version-chip office-dlp-chip" title="${esc(warnings.join(" · "))}">${esc(version.dlpClassification)}${warnings.length ? t("ui.alt8mail-office.review-suffix") : ""}</span>`
      : "";
    return `<div class="office-version-row${current ? " is-current" : ""}">
      <div class="office-version-copy">
        <strong>${esc(t("ui.alt8mail-office.version-number", { version: String(version.version) }))}${dlp}${reviewChip}${current ? " <span class=\"office-version-chip\">" + t("ui.alt8mail-office.current") + "</span>" : ""}</strong>
        <span>${esc(source)} · ${esc(formatBytes(version.sizeBytes))} · ${esc(new Date(version.createdAt).toLocaleString())}${warnings.length ? ` · ${esc(warnings.join(" "))}` : ""}${reviewMeta}</span>
      </div>
      <div class="office-version-actions">
        ${canReview ? `<select class="office-review-select" data-office-review-select data-office-review-version="${esc(String(version.version))}" aria-label="${esc(t("ui.alt8mail-office.review-version", { version: String(version.version) }))}"><option value="">${t("ui.alt8mail-office.review")}</option><option value="approved"${reviewStatus === "approved" ? " selected" : ""}>${t("ui.alt8mail-office.approve")}</option><option value="changes_requested"${reviewStatus === "changes" ? " selected" : ""}>${t("ui.alt8mail-office.request-changes")}</option></select>` : ""}
        <a class="btn-secondary btn-small" href="/api/office/documents/${encodeURIComponent(state.officeVersionsFileId)}/versions/${encodeURIComponent(String(version.version))}/download" download>${t("ui.alt8mail-office.download")}</a>
        ${!current && versions.length > 1 ? `<button class="btn-secondary btn-small" type="button" data-office-compare="${esc(String(version.version))}">${t("ui.alt8mail-office.compare")}</button>` : ""}
        ${canRestore ? `<button class="btn-secondary btn-small" type="button" data-office-restore="${esc(String(version.version))}">${t("ui.alt8mail-office.restore")}</button>` : ""}
      </div>
    </div>`;
  }).join("");
  if (comparePanel) {
    comparePanel.hidden = versions.length < 2;
    const from = document.getElementById("officeCompareFrom");
    const to = document.getElementById("officeCompareTo");
    const options = versions.map((version) => `<option value="${esc(String(version.version))}">${esc(t("ui.alt8mail-office.version-option", { version: String(version.version), current: version.current ? t("ui.alt8mail-office.current-suffix") : "" }))}</option>`).join("");
    if (from) {
      from.innerHTML = options;
      const previous = versions[1] || versions[0];
      from.value = String(previous.version);
    }
    if (to) {
      to.innerHTML = options;
      to.value = String(versions[0].version);
    }
    const result = document.getElementById("officeCompareResult");
    if (result) result.innerHTML = `<div class="office-version-empty">${t("ui.alt8mail-office.choose-two-versions-or-use-compare-on-an-older-v")}</div>`;
  }
}

async function runOfficeCompare(fromVersion, toVersion) {
  if (!state.officeVersionsFileId) return;
  const fromSelect = document.getElementById("officeCompareFrom");
  const toSelect = document.getElementById("officeCompareTo");
  const from = fromVersion || fromSelect?.value || "";
  const to = toVersion || toSelect?.value || "";
  const panel = document.getElementById("officeComparePanel");
  const result = document.getElementById("officeCompareResult");
  if (panel) panel.hidden = false;
  if (!from || !to || from === to) {
    if (result) result.innerHTML = `<div class="office-version-empty">${t("ui.alt8mail-office.choose-two-different-versions-to-compare")}</div>`;
    return;
  }
  if (fromSelect) fromSelect.value = from;
  if (toSelect) toSelect.value = to;
  if (result) result.innerHTML = `<div class="office-version-empty">${t("ui.alt8mail-office.building-comparison")}</div>`;
  try {
    const data = await api(`/api/office/documents/${encodeURIComponent(state.officeVersionsFileId)}/versions/compare?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`);
    renderOfficeCompare(data);
  } catch (error) {
    if (result) result.innerHTML = `<div class="office-version-empty">${esc(error.message || t("ui.alt8mail-office.could-not-compare-these-versions"))}</div>`;
  }
}

function renderOfficeCompare(data) {
  const result = document.getElementById("officeCompareResult");
  if (!result) return;
  const lines = Array.isArray(data.lines) ? data.lines : [];
  const changed = lines.filter((line) => line.type !== "equal").length;
  const head = `<div class="office-compare-summary"><strong>${esc(t("ui.alt8mail-office.version-comparison", { from: String(data.from?.version || ""), to: String(data.to?.version || "") }))}</strong><span>${changed ? esc(tn("ui.alt8mail-office.changed-lines", changed, { count: changed })) : t("ui.alt8mail-office.no-text-differences")}${data.truncated ? t("ui.alt8mail-office.comparison-truncated") : ""}</span></div>`;
  if (!lines.length) {
    result.innerHTML = `${head}<div class="office-version-empty">${t("ui.alt8mail-office.this-document-has-no-extractable-text-in-these-v")}</div>`;
    return;
  }
  const rows = lines.map((line) => {
    const sign = line.type === "added" ? "+" : line.type === "removed" ? "−" : " ";
    const lineNumber = line.type === "removed" ? line.fromLine : line.toLine;
    return `<div class="office-diff-line ${esc(line.type)}"><span class="office-diff-number">${esc(String(lineNumber || ""))}</span><span class="office-diff-sign">${sign}</span><span class="office-diff-text">${esc(line.text || "")}</span></div>`;
  }).join("");
  result.innerHTML = `${head}<div class="office-diff">${rows}</div>`;
}

async function restoreOfficeVersion(version, button) {
  if (!state.officeVersionsFileId) return;
  if (state.officeFile && state.officeFile.id === state.officeVersionsFileId) {
    showToast(t("ui.alt8mail-office.close-the-editor-before-restoring-a-version"), null, null, { duration: 5000 });
    return;
  }
  const confirmOverlay = document.getElementById("confirmOverlay");
  if (confirmOverlay) confirmOverlay.classList.add("is-office-confirm");
  const confirmed = await appConfirm({
    title: t("ui.compose-manager.restore-version-title", { version }),
    message: t("ui.alt8mail-office.the-restored-content-becomes-a-new-latest-versio"),
    confirmLabel: t("ui.alt8mail-office.restore-version"),
    tone: "default",
    icon: "i-history"
  });
  if (confirmOverlay) confirmOverlay.classList.remove("is-office-confirm");
  if (!confirmed) return;
  if (button) { button.disabled = true; button.textContent = t("ui.alt8mail-office.restoring"); }
  try {
    const data = await api(`/api/office/documents/${encodeURIComponent(state.officeVersionsFileId)}/versions/${encodeURIComponent(String(version))}/restore`, { method: "POST", body: {} });
    showToast(t("ui.alt8mail-office.restored-as-version", { version: data.version }));
    await refreshCabinet();
    await openOfficeVersions(state.officeVersionsFileId);
  } catch (error) {
    showError(error);
  } finally {
    if (button) { button.disabled = false; button.textContent = t("ui.alt8mail-office.restore"); }
  }
}

async function reviewOfficeVersion(version, status, select) {
  if (!state.officeVersionsFileId) return;
  const changes = status === "changes_requested";
  const label = changes ? t("ui.alt8mail-office.request-changes") : t("ui.alt8mail-office.approve-version");
  const confirmOverlay = document.getElementById("confirmOverlay");
  if (confirmOverlay) confirmOverlay.classList.add("is-office-confirm");
  const confirmed = await appConfirm({
    title: `${changes ? t("ui.alt8mail-office.request-changes-to") : t("ui.settings.approve")} version ${version}?`,
    message: changes
      ? t("ui.alt8mail-office.the-review-is-recorded-against-this-immutable-ve")
      : t("ui.alt8mail-office.the-approval-is-recorded-against-this-immutable-"),
    confirmLabel: label,
    tone: "default",
    icon: changes ? "i-history" : "i-shield-check"
  });
  if (confirmOverlay) confirmOverlay.classList.remove("is-office-confirm");
  if (!confirmed) {
    if (select) select.value = "";
    return;
  }
  try {
    await api(`/api/office/documents/${encodeURIComponent(state.officeVersionsFileId)}/versions/${encodeURIComponent(String(version))}/review`, {
      method: "POST", body: { status, note: "" }
    });
    showToast(changes ? t("ui.alt8mail-office.changes-requested") : t("ui.alt8mail-office.version-approved", { version }));
    await openOfficeVersions(state.officeVersionsFileId);
  } catch (error) {
    if (select) select.value = "";
    showError(error);
  }
}

async function convertOfficeFile(fileId, button) {
  if (!state.office.ready) {
    showToast(t("ui.alt8mail-office.office-is-not-enabled-or-healthy-for-this-worksp"), null, null, { duration: 5000 });
    return;
  }
  if (button) { button.disabled = true; }
  showToast(t("ui.alt8mail-office.converting-to-pdf"), null, null, { duration: 60000 });
  try {
    const data = await api(`/api/office/documents/${encodeURIComponent(fileId)}/convert`, { method: "POST", body: {} });
    const file = data.file;
    showToast(file ? t("ui.alt8mail-office.pdf-saved-as", { name: file.name }) : t("ui.alt8mail-office.pdf-saved-to-cabinet"));
    await refreshCabinet();
  } catch (error) {
    showError(error);
  } finally {
    if (button) button.disabled = false;
  }
}

function closeOfficeUiOnSignOut() {
  parkOfficeEditorForSignOut();
  const versions = document.getElementById("officeVersionsOverlay");
  if (versions) versions.hidden = true;
  const newDialog = document.getElementById("officeNewOverlay");
  if (newDialog) newDialog.hidden = true;
  state.office = { enabled: false, ready: false, publicUrl: "", status: "signed_out", formats: {} };
  state.officeFile = null;
  state.officeVersionsFileId = "";
  state.officeComposeAttachment = null;
  state.officeMailAttachment = null;
  state.officeNewComposeSession = "";
  syncOfficeCabinetUi();
}

function setupOfficeUi() {
  document.addEventListener("click", (event) => {
    const target = event.target;
    if (!(target instanceof Element)) return;
    const officeHub = target.closest("[data-office-hub]");
    if (officeHub) {
      event.preventDefault();
      openOfficeHub(officeHub.getAttribute("data-office-hub") || "word");
      return;
    }
    const officeDockClose = target.closest("[data-office-dock-close]");
    if (officeDockClose) {
      event.preventDefault();
      event.stopPropagation();
      closeOfficeTab(officeDockClose.getAttribute("data-office-dock-close") || officeDockActiveId);
      return;
    }
    const officeDockTab = target.closest("[data-office-dock-tab]");
    if (officeDockTab) {
      event.preventDefault();
      restoreOfficeEditor(officeDockTab.getAttribute("data-office-dock-tab") || "");
      return;
    }
    if (target.closest("#officeEditorMinimize")) {
      event.preventDefault();
      minimizeOfficeEditor();
      return;
    }
    if (target.closest("#officeEditorMaximize")) {
      event.preventDefault();
      const overlay = document.getElementById("officeEditorOverlay");
      setOfficeEditorMaximized(!overlay.classList.contains("is-maximized"));
      return;
    }
    const hubUpload = target.closest("[data-office-hub-upload]");
    if (hubUpload) {
      event.preventDefault();
      if (!state.office.ready) {
        showToast(t("ui.alt8mail-office.office-is-not-enabled-or-healthy-for-this-worksp"), null, null, { duration: 5000 });
        return;
      }
      officeHubUploadType = officeHubType;
      const input = document.getElementById("officeHubFileInput");
      if (input) {
        input.accept = officeHubAccept(officeHubType);
        input.click();
      }
      return;
    }
    const hubClose = target.closest("#officeHubClose");
    if (hubClose) {
      event.preventDefault();
      closeOfficeHub();
      return;
    }
    const hubCreate = target.closest("[data-office-hub-create]");
    if (hubCreate) {
      event.preventDefault();
      const format = hubCreate.getAttribute("data-office-hub-create") || "docx";
      closeOfficeHub();
      openOfficeNewDialog({ format });
      return;
    }
    const hubOpen = target.closest("[data-office-hub-open]");
    if (hubOpen) {
      event.preventDefault();
      const fileId = hubOpen.getAttribute("data-office-hub-open");
      closeOfficeHub();
      openOfficeEditorById(fileId).catch(showError);
      return;
    }
    const hubMail = target.closest("[data-office-hub-mail]");
    if (hubMail) {
      event.preventDefault();
      const threadId = hubMail.getAttribute("data-office-hub-mail");
      closeOfficeHub();
      setTask("mail");
      ensureThreadLoaded(threadId).then((loaded) => { if (loaded) selectThread(threadId); }).catch(showError);
      return;
    }
    if (target.closest("[data-office-hub-cabinet]")) {
      event.preventDefault();
      closeOfficeHub();
      setTask("files");
      return;
    }
    const composeOffice = target.closest("[data-compose-office]");
    if (composeOffice && !target.closest(".compose")) {
      event.preventDefault();
      const sessionId = composeOffice.getAttribute("data-compose-office-session") || attachPickerSessionId;
      editComposeAttachmentInOffice(sessionId, Number(composeOffice.getAttribute("data-compose-office"))).catch(showError);
      return;
    }
    const edit = target.closest("[data-office-edit]");
    if (edit) {
      event.preventDefault();
      openOfficeEditorById(edit.getAttribute("data-office-edit") || "").catch(showError);
      return;
    }
    const versions = target.closest("[data-office-versions]");
    if (versions) {
      event.preventDefault();
      openOfficeVersions(versions.getAttribute("data-office-versions") || "").catch(showError);
      return;
    }
    const convert = target.closest("[data-office-convert]");
    if (convert) {
      event.preventDefault();
      convertOfficeFile(convert.getAttribute("data-office-convert") || "", convert).catch(showError);
      return;
    }
    if (target.closest("#newOfficeDocBtn")) {
      event.preventDefault();
      openOfficeNewDialog();
      return;
    }
    if (target.closest("#officeEditorClose")) {
      closeOfficeEditor();
      return;
    }
    if (target.closest("#officeEditorVersions")) {
      if (state.officeFile) openOfficeVersions(state.officeFile.id).catch(showError);
      return;
    }
    if (target.closest("#officeNewClose") || target.closest("#officeNewCancel")) {
      closeOfficeNewDialog();
      return;
    }
    const restore = target.closest("[data-office-restore]");
    if (restore) {
      event.preventDefault();
      restoreOfficeVersion(Number(restore.getAttribute("data-office-restore")), restore).catch(showError);
      return;
    }
    const compare = target.closest("[data-office-compare]");
    if (compare) {
      event.preventDefault();
      const current = (state.officeVersions || []).find((version) => version.current) || (state.officeVersions || [])[0];
      runOfficeCompare(compare.getAttribute("data-office-compare"), current ? String(current.version) : "").catch(showError);
      return;
    }
    if (target.closest("#officeCompareRun")) {
      event.preventDefault();
      runOfficeCompare().catch(showError);
      return;
    }
    if (target.closest("#officeCompareClose")) {
      const panel = document.getElementById("officeComparePanel");
      if (panel) panel.hidden = true;
      return;
    }
    if (target.closest("#officeVersionsClose") || target.closest("#officeVersionsDone")) {
      const overlay = document.getElementById("officeVersionsOverlay");
      if (overlay) overlay.hidden = true;
    }
  });

  document.addEventListener("change", (event) => {
    const select = event.target instanceof Element ? event.target.closest("[data-office-review-select]") : null;
    if (!select || !select.value) return;
    reviewOfficeVersion(select.getAttribute("data-office-review-version"), select.value, select).catch(showError);
  });
  document.getElementById("officeNewCreate")?.addEventListener("click", () => createOfficeDocument().catch(showError));
  document.getElementById("officeNewName")?.addEventListener("keydown", (event) => {
    if (event.key !== "Enter") return;
    event.preventDefault();
    createOfficeDocument().catch(showError);
  });
  document.getElementById("officeNewTypeGroup")?.addEventListener("change", (event) => {
    if (!(event.target instanceof Element) || !event.target.matches('input[name="officeNewType"]')) return;
    syncOfficeNewFormat(event.target.value);
  });
  const newOverlay = document.getElementById("officeNewOverlay");
  if (newOverlay) newOverlay.addEventListener("click", (event) => { if (event.target === newOverlay) closeOfficeNewDialog(); });
  const versionsOverlay = document.getElementById("officeVersionsOverlay");
  if (versionsOverlay) versionsOverlay.addEventListener("click", (event) => { if (event.target === versionsOverlay) versionsOverlay.hidden = true; });
  const hubOverlay = document.getElementById("officeHubOverlay");
  if (hubOverlay) hubOverlay.addEventListener("click", (event) => { if (event.target === hubOverlay) closeOfficeHub(); });
  document.getElementById("officeHubFileInput")?.addEventListener("change", (event) => {
    const input = event.currentTarget;
    const file = input.files?.[0] || null;
    input.value = "";
    uploadOfficeFileFromPC(file).catch(showError);
  });
  const hubHead = document.getElementById("officeHubHead");
  const hubWindow = hubOverlay?.querySelector(".office-hub-window");
  if (hubHead && hubWindow) {
    let drag = null;
    hubHead.addEventListener("pointerdown", (event) => {
      if (event.button !== 0 || event.target.closest("button") || window.matchMedia("(max-width: 760px)").matches) return;
      drag = { x: event.clientX, y: event.clientY, originX: officeHubOffset.x, originY: officeHubOffset.y };
      hubHead.setPointerCapture?.(event.pointerId);
      event.preventDefault();
    });
    hubHead.addEventListener("pointermove", (event) => {
      if (!drag) return;
      const limitX = Math.max(0, (window.innerWidth - hubWindow.offsetWidth) / 2 - 30);
      const limitY = Math.max(0, (window.innerHeight - hubWindow.offsetHeight) / 2 - 30);
      officeHubOffset = {
        x: Math.max(-limitX, Math.min(limitX, drag.originX + event.clientX - drag.x)),
        y: Math.max(-limitY, Math.min(limitY, drag.originY + event.clientY - drag.y)),
      };
      hubWindow.style.transform = `translate(${officeHubOffset.x}px, ${officeHubOffset.y}px)`;
    });
    const endDrag = () => { drag = null; };
    hubHead.addEventListener("pointerup", endDrag);
    hubHead.addEventListener("pointercancel", endDrag);
  }
  document.addEventListener("keydown", (event) => {
    if (!(event.target instanceof Element)) return;
    const dockTab = event.target.closest("[data-office-dock-tab]");
    if (dockTab && !event.target.closest("button") && (event.key === "Enter" || event.key === " ")) {
      event.preventDefault();
      restoreOfficeEditor(dockTab.getAttribute("data-office-dock-tab") || "");
      return;
    }
    if (event.key !== "Escape") return;
    const newDialog = document.getElementById("officeNewOverlay");
    if (newDialog && !newDialog.hidden) { closeOfficeNewDialog(); return; }
    const versionsDialog = document.getElementById("officeVersionsOverlay");
    if (versionsDialog && !versionsDialog.hidden) { versionsDialog.hidden = true; return; }
    const openDialog = document.getElementById("officeOpenOverlay");
    if (openDialog && !openDialog.hidden) { closeOfficeOpenDialog(); return; }
    const hubDialog = document.getElementById("officeHubOverlay");
    if (hubDialog && !hubDialog.hidden) closeOfficeHub();
  });
  window.addEventListener("message", (event) => {
    if (event.origin !== window.location.origin) return;
    const data = event.data || {};
    if (data.type === "a8m-office-error") showToast(data.detail || t("ui.alt8mail-office.office-could-not-open-the-document"));
    if (data.type === "a8m-office-pointerdown" || data.type === "a8m-office-blur") closeOfficeEditorSearch();
    if (data.type === "a8m-office-ready") syncOfficeEditorTheme();
    if (data.type === "a8m-office-saved" && data.detail) {
      const target = officeAttachmentTargets.get(String(data.detail));
      if (target?.kind === "compose") refreshComposeAttachmentAfterOffice(target).catch(() => {});
      else if (target?.kind === "mail") refreshMailAttachmentAfterOffice(target).catch(() => {});
    }
  });
  wireOfficeEditorEnhancements();
}

function setupCabinetInteractions() {
  if (!filesView) return;
  filesView.addEventListener("dragstart", (event) => {
    const fileRow = event.target.closest("[data-file-id][draggable='true']");
    const folderRow = event.target.closest("[data-folder-open][draggable='true']");
    if (!event.dataTransfer) return;
    if (fileRow) {
      event.dataTransfer.setData("application/x-a8m-file", fileRow.getAttribute("data-file-id"));
      event.dataTransfer.effectAllowed = "move";
    } else if (folderRow) {
      event.dataTransfer.setData("application/x-a8m-folder", folderRow.getAttribute("data-folder-open"));
      event.dataTransfer.effectAllowed = "move";
    }
  });
  filesView.addEventListener("dragover", (event) => {
    const types = Array.from(event.dataTransfer?.types || []);
    if (!types.includes("Files") && !types.includes("application/x-a8m-file") && !types.includes("application/x-a8m-folder")) return;
    event.preventDefault();
    if (cabinetDropOverlay) cabinetDropOverlay.hidden = false;
    const dropTarget = event.target.closest("[data-folder-drop]");
    if (cabinetDropTarget) cabinetDropTarget.textContent = dropTarget ? (fileFolderById(dropTarget.getAttribute("data-folder-drop"))?.name || t("ui.files-storage.all-files")) : (fileFolderById(state.fileFolderId)?.name || t("ui.files-storage.all-files"));
    filesView.querySelectorAll(".is-drop-target").forEach((element) => element.classList.remove("is-drop-target"));
    if (dropTarget) dropTarget.classList.add("is-drop-target");
  });
  filesView.addEventListener("dragleave", (event) => {
    if (event.relatedTarget && filesView.contains(event.relatedTarget)) return;
    if (cabinetDropOverlay) cabinetDropOverlay.hidden = true;
    filesView.querySelectorAll(".is-drop-target").forEach((element) => element.classList.remove("is-drop-target"));
  });
  filesView.addEventListener("drop", async (event) => {
    const types = Array.from(event.dataTransfer?.types || []);
    if (!types.includes("Files") && !types.includes("application/x-a8m-file") && !types.includes("application/x-a8m-folder")) return;
    event.preventDefault();
    if (cabinetDropOverlay) cabinetDropOverlay.hidden = true;
    const dropTarget = event.target.closest("[data-folder-drop]");
    const folderId = dropTarget ? dropTarget.getAttribute("data-folder-drop") || null : state.fileFolderId;
    filesView.querySelectorAll(".is-drop-target").forEach((element) => element.classList.remove("is-drop-target"));
    if (types.includes("Files")) {
      await uploadFiles(event.dataTransfer.files, folderId);
      return;
    }
    const fileId = event.dataTransfer.getData("application/x-a8m-file");
    const draggedFolder = event.dataTransfer.getData("application/x-a8m-folder");
    if (fileId) await moveFileToFolder(fileId, folderId);
    else if (draggedFolder && draggedFolder !== folderId) await moveFolderToFolder(draggedFolder, folderId);
  });
}

fileContextMenu?.addEventListener("click", (event) => {
  const menuAction = event.target.closest("[data-file-menu-action]");
  if (menuAction) { event.preventDefault(); handleFileMenuAction(menuAction.getAttribute("data-file-menu-action")); return; }
  if (event.target.closest("[data-file-menu-back]")) { state.fileMenuView = ""; renderFileContextMenu(); }
});
document.addEventListener("click", (event) => {
  if (fileContextMenu && !fileContextMenu.hidden && !event.target.closest("#fileContextMenu") && !event.target.closest("[data-file-menu]") && !event.target.closest("[data-folder-menu]")) closeFileContextMenu();
});
document.addEventListener("contextmenu", (event) => {
  if (!filesView || filesView.hidden || !filesView.contains(event.target)) return;
  const fileRow = event.target.closest("[data-file-id]");
  const folderRow = event.target.closest("[data-folder-open][data-folder-drop]");
  if (!fileRow && !folderRow) return;
  event.preventDefault();
  if (fileRow) openFileContextMenu("file", fileRow.getAttribute("data-file-id"), event.clientX, event.clientY);
  else openFileContextMenu("folder", folderRow.getAttribute("data-folder-open"), event.clientX, event.clientY);
});
filesView?.addEventListener("dblclick", (event) => {
  const folderRow = event.target.closest("[data-folder-open]");
  if (folderRow) { event.preventDefault(); openFileFolder(folderRow.getAttribute("data-folder-open") || null); return; }
  const fileRow = event.target.closest("[data-file-id]");
  if (fileRow) {
    event.preventDefault();
    const file = state.files.find((item) => item.id === fileRow.getAttribute("data-file-id"));
    if (file) previewFileRecord(file);
  }
});
setupCabinetInteractions();
setupOfficeUi();
setupInternalShareUi();

function colorForString(value) {
  const palette = ["#34557a", "#3d6b62", "#5b4a7e", "#7a4a5c", "#7a5a3a", "#3f6570", "#476b4f", "#4f5673"];
  let hash = 0;
  for (const char of String(value)) hash = (hash * 31 + char.charCodeAt(0)) >>> 0;
  return palette[hash % palette.length];
}

function storageCanManage() {
  return Boolean(state.user && (state.user.isSystemAdmin === true || ["owner", "admin"].includes(String(state.user.role || "").toLowerCase())));
}

function storageDefaultId() {
  const current = state.storageProviders.find((provider) => provider.id === state.defaultStorage && provider.connected);
  return current ? current.id : "a8m";
}

function storageDefaultOptions() {
  return state.storageProviders
    .filter((provider) => provider.connected)
    .map((provider) => `<option value="${esc(provider.id)}">${esc(provider.name)}</option>`)
    .join("");
}

function syncStorageDefaultSelects() {
  const options = storageDefaultOptions();
  const selected = storageDefaultId();
  for (const id of ["defaultStorageSelect", "settingsDefaultStorage"]) {
    const select = document.getElementById(id);
    if (!select) continue;
    if (select.innerHTML !== options) select.innerHTML = options;
    select.value = selected;
  }
}

async function setDefaultStorage(providerId) {
  try {
    const data = await api("/api/storage/default", { method: "PUT", body: { providerId } });
    state.defaultStorage = data.defaultProvider || providerId;
    syncStorageDefaultSelects();
    showToast(t("ui.files-storage.provider-now-default", { provider: storageProvider(state.defaultStorage)?.name || t("ui.files-storage.storage") }));
  } catch (error) {
    showError(error);
    syncStorageDefaultSelects();
  }
}

function storageProviderMarkup(provider) {
  if (provider.id === "a8m") {
    return `<span class="storage-provider-mark"><svg class="icon" aria-hidden="true"><use href="#i-drive-cloud"/></svg></span>`;
  }
  return `<span class="storage-provider-mark" style="--provider:${provider.color}">${esc(provider.name.split(" ").map((part) => part[0]).join("").slice(0, 2))}</span>`;
}

function renderStorageSettings() {
  const list = document.getElementById("settingsStorageList");
  if (!list) return;
  syncStorageDefaultSelects();
  list.innerHTML = state.storageProviders.map((provider) => `<div class="settings-storage-row">
    ${storageProviderMarkup(provider)}
    <div class="settings-storage-copy"><strong>${esc(provider.name)}</strong><span>${provider.connected ? (provider.account ? esc(t("ui.alt8mail-office.connected-as-account", { account: provider.account })) : t("ui.alt8mail-office.connected")) : provider.configured ? t("ui.alt8mail-office.ready-to-connect") : t("ui.alt8mail-office.credentials-not-configured")}</span></div>
    ${provider.connected ? `<span class="storage-status"><span class="status-dot"></span>${provider.id === state.defaultStorage ? t("mail.folders.defaultColor") : t("shell.connected")}</span>` : ""}
    <div class="settings-storage-actions">
      ${provider.kind !== "internal" && !provider.configured ? `<button class="link-btn" data-storage-configure="${esc(provider.id)}" type="button">${t("ui.alt8mail-office.configure")}</button>` : ""}
      ${provider.kind !== "internal" && provider.configured && !provider.connected ? `<button class="link-btn" data-storage-connect="${esc(provider.id)}" type="button">${t("ui.alt8mail-office.connect")}</button>` : ""}
      ${provider.connected && provider.kind !== "internal" ? `<button class="link-btn" data-storage-sync="${esc(provider.id)}" type="button">${t("accounts.sync")}</button><button class="link-btn" data-storage-disconnect="${esc(provider.id)}" type="button">${t("ui.alt8mail-office.disconnect")}</button>` : ""}
    </div>
  </div>`).join("");
  if (!storageCanManage()) {
    const manage = document.getElementById("settingsManageStorageBtn");
    if (manage) manage.hidden = true;
  }
}

async function refreshStorageProviders() {
  const data = await api("/api/storage");
  state.storageProviders = data.providers || state.storageProviders;
  if (data.defaultProvider) state.defaultStorage = data.defaultProvider;
  syncStorageDefaultSelects();
  if (state.task === "files") renderFiles();
  if (state.task === "settings" && state.settingsTab === "storage") renderStorageSettings();
}

function credentialProvider() {
  return state.storageCredentialData.find((provider) => provider.id === state.storageCredentialProvider) || state.storageCredentialData[0] || null;
}

function renderStorageCredentials() {
  if (!storageCredentialsTabs || !storageCredentialFields) return;
  storageCredentialsTabs.innerHTML = state.storageCredentialData.map((provider) => `<button class="storage-credentials-tab${provider.id === state.storageCredentialProvider ? " is-active" : ""}" data-credential-provider="${esc(provider.id)}" type="button" role="tab" aria-selected="${provider.id === state.storageCredentialProvider ? "true" : "false"}"><span>${esc(provider.name)}</span><span class="credential-state ${provider.configured ? "is-set" : ""}">${provider.configured ? t("ui.alt8mail-office.configured") : t("ui.alt8mail-office.not-configured")}</span></button>`).join("");
  const provider = credentialProvider();
  if (!provider) {
    storageCredentialFields.innerHTML = `<div class="settings-note">${t("ui.alt8mail-office.no-external-storage-providers-are-available")}</div>`;
    return;
  }
  if (provider.kind === "s3") {
    storageCredentialFields.innerHTML = `
      <div class="credential-callout"><strong>${t("ui.alt8mail-office.s3-minio-bucket")}</strong><span>${t("ui.alt8mail-office.the-bucket-must-already-exist-and-allow-the-acce")}</span></div>
      <div class="credential-grid">
        <label class="form-field"><span>${t("ui.alt8mail-office.endpoint")} <small>${t("ui.alt8mail-office.optional")}</small></span><input data-credential-field="endpoint" value="${esc(provider.endpoint || "")}" placeholder="https://s3.example.com"></label>
        <label class="form-field"><span>${t("ui.alt8mail-office.region")}</span><input data-credential-field="region" value="${esc(provider.region || "us-east-1")}" placeholder="us-east-1"></label>
        <label class="form-field"><span>${t("ui.alt8mail-office.bucket")}</span><input data-credential-field="bucket" value="${esc(provider.bucket || "")}" placeholder="alt8mail-cabinet"></label>
        <label class="form-field"><span>${t("ui.alt8mail-office.access-key")}</span><input data-credential-field="accessKey" value="${esc(provider.accessKey || "")}" autocomplete="off"></label>
        <label class="form-field"><span>${t("ui.alt8mail-office.secret-key")}</span><input data-credential-field="secretKey" type="password" placeholder="${provider.hasSecret ? t("ui.alt8mail-office.leave-blank-to-keep-the-saved-secret") : t("ui.alt8mail-office.enter-the-secret-key")}" autocomplete="new-password"></label>
      </div>
      <div class="credential-checks"><label class="compose-check"><input type="checkbox" data-credential-field="useSSL" ${provider.useSSL !== false ? "checked" : ""}>${t("ui.alt8mail-office.use-tls")}</label><label class="compose-check"><input type="checkbox" data-credential-field="pathStyle" ${provider.pathStyle !== false ? "checked" : ""}>${t("ui.alt8mail-office.path-style-addressing")}</label></div>`;
  } else {
    storageCredentialFields.innerHTML = `
      <div class="credential-callout"><strong>${t("ui.alt8mail-office.oauth-redirect-uri")}</strong><span>${t("ui.alt8mail-office.register-this-exact-callback-in-the-provider-con")}</span><div class="credential-uri"><code>${esc(provider.redirectUri || "")}</code><button class="link-btn" data-copy-credential-uri="${esc(provider.redirectUri || "")}" type="button">${t("ui.alt8mail-office.copy")}</button></div></div>
      <div class="credential-grid">
        <label class="form-field"><span>${t("ui.alt8mail-office.client-id")}</span><input data-credential-field="clientId" value="${esc(provider.clientId || "")}" autocomplete="off" spellcheck="false"></label>
        <label class="form-field"><span>${t("ui.alt8mail-office.client-secret")}</span><input data-credential-field="clientSecret" type="password" placeholder="${provider.hasClientSecret ? t("ui.alt8mail-office.leave-blank-to-keep-the-saved-secret") : t("ui.alt8mail-office.enter-the-client-secret")}" autocomplete="new-password"></label>
      </div>`;
  }
  storageCredentialStatus.textContent = provider.configured
    ? t("ui.alt8mail-office.configured-source", { source: provider.source === "environment" ? t("ui.alt8mail-office.from-server-environment") : "" })
    : t("ui.alt8mail-office.not-configured-yet-save-credentials-then-connect");
  if (storageCredentialsOverlay) storageCredentialsOverlay.hidden = false;
}

async function openStorageCredentials(providerId = "") {
  if (!storageCanManage()) {
    showToast(t("ui.alt8mail-office.only-organization-owners-and-administrators-can-"));
    return;
  }
  try {
    const data = await api("/api/storage/credentials");
    state.storageCredentialData = data.providers || [];
    state.storageCredentialProvider = providerId || state.storageCredentialData[0]?.id || "";
    renderStorageCredentials();
  } catch (error) {
    showError(error);
  }
}

function closeStorageCredentials() {
  if (storageCredentialsOverlay) storageCredentialsOverlay.hidden = true;
}

async function saveStorageCredentials() {
  const provider = credentialProvider();
  if (!provider) return;
  const body = {};
  for (const input of storageCredentialFields.querySelectorAll("[data-credential-field]")) {
    const key = input.getAttribute("data-credential-field");
    if (input.type === "checkbox") body[key] = input.checked;
    else body[key] = input.value.trim();
  }
  const button = document.getElementById("storageCredentialsSave");
  if (button) { button.disabled = true; button.textContent = t("ui.alt8mail-office.saving"); }
  try {
    const data = await api(`/api/storage/credentials/${encodeURIComponent(provider.id)}`, { method: "PUT", body });
    const index = state.storageCredentialData.findIndex((item) => item.id === provider.id);
    if (index >= 0) state.storageCredentialData[index] = data.provider;
    await refreshStorageProviders();
    renderStorageCredentials();
    showToast(t("ui.alt8mail-office.credentials-saved", { provider: provider.name }));
  } catch (error) {
    showError(error);
  } finally {
    if (button) { button.disabled = false; button.textContent = t("ui.alt8mail-office.save-credentials"); }
  }
}

async function clearStorageCredentials() {
  const provider = credentialProvider();
  if (!provider) return;
  const ok = await appConfirm({
    title: t("ui.alt8mail-office.clear-saved-credentials"),
    message: t("ui.alt8mail-office.disconnect-connector-confirm", { provider: provider.name }),
    confirmLabel: t("ui.alt8mail-office.clear-credentials"),
    tone: "danger"
  });
  if (!ok) return;
  try {
    await api(`/api/storage/credentials/${encodeURIComponent(provider.id)}`, { method: "DELETE" });
    const index = state.storageCredentialData.findIndex((item) => item.id === provider.id);
    if (index >= 0) state.storageCredentialData[index] = { ...provider, configured: false, clientId: "", hasClientSecret: false, hasSecret: false, source: "none" };
    await refreshStorageProviders();
    renderStorageCredentials();
    showToast(t("ui.alt8mail-office.storage-credentials-cleared"));
  } catch (error) { showError(error); }
}

function openStorageDialog() {
  storageConnectList.innerHTML = state.storageProviders.map((provider) => `<div class="storage-connect-row" data-provider="${esc(provider.id)}">
    ${storageProviderMarkup(provider)}
    <div class="storage-connect-copy"><strong>${esc(provider.name)}</strong><span>${provider.connected ? esc(t("ui.alt8mail-office.connected-as-account", { account: provider.account || state.user.email })) : provider.configured ? esc(provider.description) : t("ui.alt8mail-office.credentials-are-not-configured-for-this-connecto")}</span></div>
    ${provider.connected ? `<span class="storage-status"><span class="status-dot"></span>${t("shell.connected")}</span>${provider.kind !== "internal" ? `<button class="link-btn" data-storage-sync="${esc(provider.id)}" type="button">${t("accounts.sync")}</button>` : ""}<button class="link-btn" data-storage-disconnect="${esc(provider.id)}" type="button">${t("ui.alt8mail-office.disconnect")}</button>` : provider.kind !== "internal" && !provider.configured ? `<button class="btn-secondary" data-storage-configure="${esc(provider.id)}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-sliders"/></svg>${t("ui.alt8mail-office.configure")}</button>` : `<button class="btn-secondary" data-storage-connect="${esc(provider.id)}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-cloud"/></svg>${t("ui.alt8mail-office.connect")}</button>`}
  </div>`).join("");
  storageOverlay.hidden = false;
}

async function connectStorage(providerId, button) {
  const provider = storageProvider(providerId);
  if (!provider) return;
  if (button) { button.disabled = true; button.innerHTML = "<span class=\"passkey-spinner\" aria-hidden=\"true\"></span>" + t("ui.account-chrome.connecting"); }
  try {
    const data = await api(`/api/storage/${encodeURIComponent(providerId)}/connect`, { method: "POST", body: {} });
    if (data.authorizationUrl) { window.location.href = data.authorizationUrl; return; }
    const index = state.storageProviders.findIndex((item) => item.id === providerId);
    if (index >= 0) state.storageProviders[index] = data.provider;
    for (const file of data.files || []) if (!state.files.some((item) => item.id === file.id)) state.files.push(file);
    renderFiles();
    syncStorageDefaultSelects();
    openStorageDialog();
    showToast(t("ui.files-storage.provider-connected", { provider: provider.name }));
  } catch (error) {
    showError(error);
    if (button) { button.disabled = false; button.textContent = t("ui.alt8mail-office.connect"); }
  }
}

async function disconnectStorage(providerId) {
  const provider = storageProvider(providerId);
  if (!provider) return;
  if (!(await appConfirm({ title: t("ui.alt8mail-office.disconnect-provider-title", { provider: provider.name }), message: t("ui.alt8mail-office.its-files-will-be-hidden-from-the-cabinet-until-"), confirmLabel: t("ui.alt8mail-office.disconnect"), tone: "danger" }))) return;
  try {
    const data = await api(`/api/storage/${encodeURIComponent(providerId)}/disconnect`, { method: "POST", body: {} });
    const index = state.storageProviders.findIndex((item) => item.id === providerId);
    if (index >= 0) state.storageProviders[index] = data.provider;
    if (state.fileProvider === providerId) state.fileProvider = "all";
    renderFiles();
    syncStorageDefaultSelects();
    openStorageDialog();
    showToast(t("ui.files-storage.provider-disconnected", { provider: provider.name }));
  } catch (error) {
    showError(error);
  }
}

async function syncStorage(providerId) {
  const provider = storageProvider(providerId);
  if (!provider) return;
  try {
    const data = await api(`/api/storage/${encodeURIComponent(providerId)}/sync`, { method: "POST", body: {} });
    const index = state.storageProviders.findIndex((item) => item.id === providerId);
    if (index >= 0) state.storageProviders[index] = data.provider;
    state.files = state.files.filter((file) => file.providerId !== providerId);
    for (const file of data.files || []) if (!state.files.some((item) => item.id === file.id)) state.files.push(file);
    renderFiles();
    syncStorageDefaultSelects();
    openStorageDialog();
    showToast(t("ui.files-storage.provider-synced", { provider: provider.name }));
  } catch (error) { showError(error); }
}

function renderSharePermissions() {
  const holder = document.getElementById("sharePermissions");
  if (!holder) return;
  const shares = state.fileShareList || [];
  if (!shares.length) {
    holder.innerHTML = `<div class="share-permissions-head"><strong>${t("ui.alt8mail-office.people-with-access")}</strong><span>${t("ui.alt8mail-office.no-active-links")}</span></div><p class="share-permissions-empty">${t("ui.alt8mail-office.create-a-link-to-let-someone-outside-your-organi")}</p>`;
    return;
  }
  holder.innerHTML = `<div class="share-permissions-head"><strong>${t("ui.alt8mail-office.people-with-access")}</strong><span>${shares.filter((share) => share.active).length} active</span></div>
    <div class="share-permission-list">${shares.map((share) => `<div class="share-permission-row${share.active ? "" : " is-revoked"}">
      <span class="share-permission-icon"><svg class="icon" aria-hidden="true"><use href="#i-link"/></svg></span>
      <div><strong>${esc(share.recipient || t("ui.compose-manager.anyone-with-the-link"))}</strong><span>${share.access === "edit" ? t("ui.calendar.can-edit") : t("ui.calendar.can-view")} · ${share.active ? `expires ${esc(formatDateOnly(share.expiresAt))}` : "revoked"} · ${share.accessCount || 0} opens</span></div>
      ${share.active ? `<button class="link-btn danger-link" data-revoke-share="${esc(share.id)}" type="button">${t("ui.alt8mail-office.revoke")}</button>` : "<span class=\"policy-chip\">" + t("ui.settings.revoked") + "</span>"}
    </div>`).join("")}</div>`;
}

async function loadFileShares(fileId) {
  try {
    const data = await api(`/api/files/${encodeURIComponent(fileId)}/shares`);
    state.fileShareList = data.shares || [];
  } catch {
    state.fileShareList = [];
  }
  renderSharePermissions();
}

function internalSharingAllowed() {
  const policy = state.tenantPolicy && state.tenantPolicy.office;
  if (policy && policy.internalSharing === false) return false;
  const officePolicy = state.office && state.office.policy;
  return !officePolicy || officePolicy.internalSharing !== false;
}

async function loadInternalShares(fileId) {
  const section = document.getElementById("shareInternalSection");
  const list = document.getElementById("shareInternalList");
  const count = document.getElementById("shareInternalCount");
  const file = state.files.find((item) => item.id === fileId);
  if (!section || !list) return;
  if (!file || file.shared || !internalSharingAllowed()) {
    section.hidden = true;
    return;
  }
  section.hidden = false;
  const people = document.getElementById("shareInternalPeople");
  if (people) {
    people.innerHTML = (state.people || [])
      .filter((person) => person.email && normalizeEmail(person.email) !== normalizeEmail(state.user?.email || ""))
      .map((person) => `<option value="${esc(person.email)}">${esc(person.name || person.email)}</option>`)
      .join("");
  }
  if (!state.shareGroupsLoaded) {
    try {
      const data = await api("/api/files/share-groups");
      state.shareGroups = data.groups || [];
      state.shareGroupsLoaded = true;
    } catch {
      state.shareGroups = [];
    }
  }
  const groupSelect = document.getElementById("shareInternalGroup");
  if (groupSelect) {
    groupSelect.innerHTML = `<option value="">${t("ui.alt8mail-office.choose-group")}</option>` + (state.shareGroups || []).map((group) =>
      `<option value="${esc(group.id)}">${esc(group.name)} · ${group.members || 0}</option>`).join("");
  }
  list.innerHTML = `<div class="share-internal-empty">${t("ui.alt8mail-office.loading-internal-access")}</div>`;
  try {
    const data = await api(`/api/files/${encodeURIComponent(fileId)}/permissions`);
    state.filePermissionList = data.permissions || [];
    renderInternalShares();
  } catch (error) {
    list.innerHTML = `<div class="share-internal-empty">${esc(error.message || t("ui.alt8mail-office.could-not-load-internal-access"))}</div>`;
    if (count) count.textContent = t("mail.details.unavailable");
  }
}

function renderInternalShares() {
  const list = document.getElementById("shareInternalList");
  const count = document.getElementById("shareInternalCount");
  if (!list) return;
  const permissions = state.filePermissionList || [];
  if (count) count.textContent = permissions.length ? `${permissions.length} ${permissions.length === 1 ? "grant" : "grants"}` : t("ui.alt8mail-office.no-internal-access");
  if (!permissions.length) {
    list.innerHTML = `<div class="share-internal-empty">${t("ui.alt8mail-office.no-colleagues-or-groups-have-access-yet")}</div>`;
    return;
  }
  list.innerHTML = permissions.map((permission) => {
    const visual = permission.granteeType === "group"
      ? `<span class="share-internal-avatar"><svg class="icon" aria-hidden="true"><use href="#i-users"/></svg></span>`
      : avatar({ name: permission.name || permission.email, email: permission.email, initials: permission.initials, color: permission.color }, "sm");
    const detail = permission.granteeType === "group" ? t("ui.alt8mail-office.group") : (permission.email || "");
    return `<div class="share-internal-row">${visual}<div class="share-internal-copy"><strong>${esc(permission.name || permission.email || t("ui.alt8mail-office.group"))}</strong><span>${esc(detail)} · Can ${permission.access === "edit" ? "edit" : "view"}</span></div><button class="link-btn danger-link" type="button" data-share-internal-remove="${esc(permission.id)}">${t("tasks.detail.remove")}</button></div>`;
  }).join("");
}

async function addInternalShare() {
  if (!fileShareTarget) return;
  const targetInput = document.getElementById("shareInternalTarget");
  const groupSelect = document.getElementById("shareInternalGroup");
  const accessSelect = document.getElementById("shareInternalAccess");
  const email = (targetInput?.value || "").trim();
  const groupId = (groupSelect?.value || "").trim();
  const access = accessSelect?.value === "edit" ? "edit" : "view";
  if (!email && !groupId) {
    showToast(t("ui.alt8mail-office.choose-a-person-or-a-group"));
    return;
  }
  const body = groupId ? { groupId, access } : { email, access };
  await api(`/api/files/${encodeURIComponent(fileShareTarget.id)}/permissions`, { method: "POST", body });
  if (targetInput) targetInput.value = "";
  if (groupSelect) groupSelect.value = "";
  await loadInternalShares(fileShareTarget.id);
  showToast(groupId ? t("ui.alt8mail-office.group-access-granted") : t("ui.alt8mail-office.internal-access-granted"));
}

async function removeInternalShare(permissionId) {
  if (!fileShareTarget) return;
  await api(`/api/files/${encodeURIComponent(fileShareTarget.id)}/permissions/${encodeURIComponent(permissionId)}`, { method: "DELETE" });
  await loadInternalShares(fileShareTarget.id);
  showToast(t("ui.alt8mail-office.internal-access-revoked"));
}

function setupInternalShareUi() {
  const target = document.getElementById("shareInternalTarget");
  const group = document.getElementById("shareInternalGroup");
  const add = document.getElementById("shareInternalAdd");
  target?.addEventListener("input", () => { if (target.value.trim() && group) group.value = ""; });
  group?.addEventListener("change", () => { if (group.value && target) target.value = ""; });
  add?.addEventListener("click", (event) => { event.preventDefault(); addInternalShare().catch(showError); });
  document.getElementById("shareInternalList")?.addEventListener("click", (event) => {
    const remove = event.target.closest("[data-share-internal-remove]");
    if (!remove) return;
    event.preventDefault();
    removeInternalShare(remove.getAttribute("data-share-internal-remove")).catch(showError);
  });
}

function openShareDialog(fileId) {
  const file = state.files.find((item) => item.id === fileId);
  if (!file) return;
  if (file.shared) { showToast(t("ui.alt8mail-office.only-the-file-owner-can-manage-sharing")); return; }
  fileShareTarget = file;
  shareFileName.textContent = file.name;
  shareResult.hidden = true;
  shareUrl.value = "";
  document.getElementById("createShare").hidden = false;
  state.fileShareList = [];
  state.filePermissionList = [];
  renderSharePermissions();
  shareOverlay.hidden = false;
  loadFileShares(file.id);
  loadInternalShares(file.id);
}

async function createShareLink() {
  if (!fileShareTarget) return;
  const button = document.getElementById("createShare");
  button.disabled = true;
  button.textContent = t("ui.alt8mail-office.creating");
  try {
    const share = await createShareForFile(fileShareTarget, {
      access: document.getElementById("shareAccess").value,
      expiresDays: Number(document.getElementById("shareExpiry").value),
      recipientEmail: (document.getElementById("shareRecipient")?.value || "").trim()
    });
    if (share.pendingApproval) {
      showToast(t("ui.alt8mail-office.share-approval-requested-an-administrator-must-a"));
      return;
    }
    state.fileShareList = [{ ...share, recipient: share.recipientEmail || "", active: true, accessCount: 0 }, ...(state.fileShareList || [])];
    renderSharePermissions();
    shareUrl.value = share.url;
    shareResult.hidden = false;
    button.hidden = true;
    showToast(t("ui.alt8mail-office.share-link-created"));
    if (!(fileShareTarget.sharedWith || []).includes("External link")) { fileShareTarget.sharedWith = [...(fileShareTarget.sharedWith || []), t("ui.alt8mail-office.external-link")]; }
    renderFiles();
  } catch (error) {
    showError(error);
  } finally {
    button.disabled = false;
    button.textContent = t("ui.alt8mail-office.create-link");
  }
}

function previewFileRecord(file) {
  if (!file) return;
  const url = file.contentUrl || (file.id ? `/api/attachments/${encodeURIComponent(file.id)}/content` : "");
  openPreview({
    name: file.name,
    type: file.type,
    mime: file.mime,
    size: file.size || formatBytes(file.sizeBytes),
    contentUrl: url,
    previewable: file.previewable
  });
}

async function toggleFileLock(fileId) {
  const file = state.files.find((item) => item.id === fileId);
  if (!file) return;
  try {
    const data = await api(`/api/files/${encodeURIComponent(fileId)}`, { method: "PATCH", body: { locked: !file.locked } });
    const index = state.files.findIndex((item) => item.id === fileId);
    if (index >= 0) state.files[index] = data.file;
    renderFiles();
    showToast(data.file.locked ? t("ui.alt8mail-office.file-link-locked-visitors-must-request-access") : t("ui.alt8mail-office.file-link-unlocked"));
  } catch (error) {
    showError(error);
  }
}

async function toggleFileStar(fileId) {
  const file = state.files.find((item) => item.id === fileId);
  if (!file) return;
  if (file.shared) { showToast(t("ui.alt8mail-office.only-the-file-owner-can-change-favourites")); return; }
  try {
    const data = await api(`/api/files/${encodeURIComponent(fileId)}`, { method: "PATCH", body: { starred: !file.starred } });
    const index = state.files.findIndex((item) => item.id === fileId);
    if (index >= 0) state.files[index] = data.file;
    renderFiles();
    showToast(data.file.starred ? t("ui.alt8mail-office.file-starred") : t("ui.alt8mail-office.file-unstarred"));
  } catch (error) {
    showError(error);
  }
}

async function deleteFile(fileId) {
  const file = state.files.find((item) => item.id === fileId);
  if (!file) return;
  if (file.shared) { showToast(t("ui.alt8mail-office.only-the-file-owner-can-delete-this-file")); return; }
  if (!(await appConfirm({ title: t("ui.alt8mail-office.delete-this-file"), message: t("ui.alt8mail-office.file-removed-from-index", { name: file.name }), confirmLabel: t("ui.alt8mail-office.delete-file"), tone: "danger" }))) return;
  try {
    await api(`/api/files/${encodeURIComponent(fileId)}`, { method: "DELETE" });
    state.files = state.files.filter((item) => item.id !== fileId);
    state.selectedFileId = null;
    await refreshCabinet();
    showToast(t("ui.alt8mail-office.file-removed"));
  } catch (error) {
    showError(error);
  }
}

function fileToBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || "").replace(/^data:[^;]+;base64,/, ""));
    reader.onerror = () => reject(reader.error || new Error(t("ui.alt8mail-office.could-not-read-the-file")));
    reader.readAsDataURL(file);
  });
}

function uploadTargetProvider() {
  return state.fileProvider !== "all" && storageConnected(state.fileProvider) ? state.fileProvider : "a8m";
}

function uploadTargetLabel(providerId, folderId) {
  const provider = providerId === "a8m" ? t("ui.alt8mail-office.alt8mail-drive") : (storageProvider(providerId)?.name || t("ui.alt8mail-office.connected-storage"));
  const folder = fileFolderById(folderId);
  return folder ? `${folder.name} · ${provider}` : provider;
}

function formatUploadTime(ms) {
  if (!Number.isFinite(ms) || ms < 0) return "";
  if (ms < 1000) return "<1s";
  const seconds = Math.round(ms / 1000);
  if (seconds < 60) return `${seconds}s`;
  return `${Math.floor(seconds / 60)}m ${seconds % 60}s`;
}

function uploadManagerStats() {
  const items = state.uploadQueue || [];
  const active = items.filter((item) => item.status === "queued" || item.status === "uploading" || item.status === "preparing").length;
  const done = items.filter((item) => item.status === "done").length;
  const failed = items.filter((item) => item.status === "error").length;
  const mobile = (state.uploadMobileSession?.uploads || []).filter((item) => item.status === "uploading").length;
  return { active: active + mobile, done, failed, mobile };
}

function ensureUploadManager() {
  if (document.getElementById("uploadManager")) return document.getElementById("uploadManager");
  document.body.insertAdjacentHTML("beforeend", `<section class="upload-manager" id="uploadManager" hidden aria-label="${esc(t("ui.alt8mail-office.uploads"))}">
    <header class="upload-manager-head" data-upload-drag-handle>
      <span class="upload-manager-mark"><svg class="icon" aria-hidden="true"><use href="#i-upload"/></svg></span>
      <div class="upload-manager-title"><strong>${t("ui.alt8mail-office.uploads")}</strong><small id="uploadManagerSummary">${t("ui.alt8mail-office.ready")}</small></div>
      <button class="upload-manager-btn" type="button" data-upload-minimize aria-label="${esc(t("ui.alt8mail-office.minimize-uploads"))}" title="${esc(t("ui.alt8mail-office.minimize"))}"><svg class="icon" aria-hidden="true"><use href="#i-chevron-down"/></svg></button>
      <button class="upload-manager-btn" type="button" data-upload-close aria-label="${esc(t("ui.alt8mail-office.close-uploads"))}" title="${esc(t("common.close"))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button>
    </header>
    <nav class="upload-manager-tabs" role="tablist" aria-label="${esc(t("ui.alt8mail-office.upload-source"))}">
      <button type="button" role="tab" data-upload-tab="computer"><svg class="icon" aria-hidden="true"><use href="#i-upload"/></svg>${t("ui.alt8mail-office.computer")}</button>
      <button type="button" role="tab" data-upload-tab="url"><svg class="icon" aria-hidden="true"><use href="#i-link"/></svg>${t("ui.alt8mail-office.from-url")}</button>
      <button type="button" role="tab" data-upload-tab="mobile"><svg class="icon" aria-hidden="true"><use href="#i-cloud"/></svg>${t("ui.alt8mail-office.from-mobile")}</button>
    </nav>
    <div class="upload-manager-body" id="uploadManagerBody"></div>
  </section>`);
  const manager = document.getElementById("uploadManager");
  manager.addEventListener("click", (event) => {
    const tab = event.target.closest("[data-upload-tab]");
    if (tab) { state.uploadTab = tab.getAttribute("data-upload-tab"); if (state.uploadTab === "mobile") ensureMobileUploadSession().catch(showError); renderUploadManager(); return; }
    if (event.target.closest("[data-upload-close]")) { closeUploadManager(); return; }
    if (event.target.closest("[data-upload-minimize]")) { state.uploadManagerMinimized = !state.uploadManagerMinimized; renderUploadManager(); return; }
    if (event.target.closest("[data-upload-choose]")) { document.getElementById("uploadManagerInput")?.click(); return; }
    if (event.target.closest("[data-upload-copy-url]")) {
      const url = state.uploadMobileSession?.url || "";
      if (url) copyTextToClipboard(url).then((ok) => showToast(ok ? t("ui.alt8mail-office.upload-link-copied") : url)).catch(showError);
      return;
    }
    const extend = event.target.closest("[data-upload-extend]");
    if (extend) { extendMobileUploadSession(Number(extend.getAttribute("data-upload-extend")) || 1).catch(showError); return; }
    if (event.target.closest("[data-upload-new-session]")) { createMobileUploadSession(true).catch(showError); return; }
    if (event.target.closest("[data-upload-url-add]")) {
      const input = document.getElementById("uploadUrlInput");
      const value = String(input?.value || "").trim();
      if (!value) { showToast(t("ui.alt8mail-office.enter-a-file-url")); return; }
      enqueueUrlImport(value);
      return;
    }
  });
  manager.addEventListener("change", (event) => {
    if (event.target.id !== "uploadManagerInput") return;
    const files = Array.from(event.target.files || []);
    event.target.value = "";
    if (files.length) enqueueCabinetUploads(files, state.uploadTargetFolderId, state.uploadTargetProvider);
  });
  manager.addEventListener("input", (event) => {
    if (event.target.id === "uploadUrlInput") state.uploadUrlValue = event.target.value;
  });
  manager.addEventListener("dragover", (event) => {
    if (!event.target.closest("[data-upload-drop]")) return;
    event.preventDefault();
    event.target.closest("[data-upload-drop]")?.classList.add("is-drag");
  });
  manager.addEventListener("dragleave", (event) => {
    if (event.target.closest("[data-upload-drop]")) event.target.closest("[data-upload-drop]")?.classList.remove("is-drag");
  });
  manager.addEventListener("drop", (event) => {
    const drop = event.target.closest("[data-upload-drop]");
    if (!drop) return;
    event.preventDefault();
    drop.classList.remove("is-drag");
    const files = Array.from(event.dataTransfer?.files || []);
    if (files.length) enqueueCabinetUploads(files, state.uploadTargetFolderId, state.uploadTargetProvider);
  });
  const head = manager.querySelector("[data-upload-drag-handle]");
  head?.addEventListener("pointerdown", (event) => {
    if (event.button !== 0 || event.target.closest("button")) return;
    const rect = manager.getBoundingClientRect();
    manager.style.left = `${rect.left}px`;
    manager.style.top = `${rect.top}px`;
    manager.style.right = "auto";
    manager.style.bottom = "auto";
    state.uploadDrag = { offsetX: event.clientX - rect.left, offsetY: event.clientY - rect.top };
    event.preventDefault();
  });
  window.addEventListener("pointermove", (event) => {
    if (!state.uploadDrag) return;
    const width = manager.offsetWidth;
    const height = manager.offsetHeight;
    manager.style.left = `${Math.max(8, Math.min(window.innerWidth - width - 8, event.clientX - state.uploadDrag.offsetX))}px`;
    manager.style.top = `${Math.max(8, Math.min(window.innerHeight - height - 8, event.clientY - state.uploadDrag.offsetY))}px`;
  });
  window.addEventListener("pointerup", () => { state.uploadDrag = null; });
  return manager;
}

function openUploadManager(tab = "computer", { files = null, folderId = undefined } = {}) {
  ensureUploadManager();
  state.uploadManagerOpen = true;
  state.uploadManagerMinimized = false;
  state.uploadTab = tab;
  if (folderId !== undefined) state.uploadTargetFolderId = folderId || "";
  state.uploadTargetProvider = uploadTargetProvider();
  renderUploadManager();
  const manager = document.getElementById("uploadManager");
  if (manager) manager.hidden = false;
  if (tab === "mobile") ensureMobileUploadSession().catch(showError);
  if (files?.length) enqueueCabinetUploads(files, state.uploadTargetFolderId, state.uploadTargetProvider);
}

function closeUploadManager() {
  const stats = uploadManagerStats();
  if (stats.active > 0) {
    state.uploadManagerMinimized = true;
    renderUploadManager();
    showToast(t("ui.alt8mail-office.uploads-continue-in-the-background"));
    return;
  }
  state.uploadManagerOpen = false;
  const manager = document.getElementById("uploadManager");
  if (manager) manager.hidden = true;
}

function uploadItemMarkup(item, { mobile = false } = {}) {
  const progress = Math.max(0, Math.min(100, Number(item.progress) || 0));
  const start = Number(item.startedAt) || 0;
  const end = Number(item.endedAt) || (item.status === "uploading" || item.status === "preparing" ? Date.now() : 0);
  const elapsed = start ? formatUploadTime((end || Date.now()) - start) : "";
  const statusText = item.status === "done" ? `${t("ui.alt8mail-office.done")}${elapsed ? ` · ${elapsed}` : ""}`
    : item.status === "error" ? (item.error || t("ui.alt8mail-office.upload-failed"))
      : item.status === "preparing" ? t("ui.alt8mail-office.preparing")
        : item.status === "uploading" ? `${t("ui.alt8mail-office.uploading")}${elapsed ? ` · ${elapsed}` : ""}`
          : t("ui.alt8mail-office.queued");
  return `<div class="upload-item is-${esc(item.status)}${mobile ? " is-mobile" : ""}">
    <span class="upload-item-icon"><svg class="icon" aria-hidden="true"><use href="#${item.kind === "url" ? "i-link" : mobile ? "i-cloud" : "i-file"}"/></svg></span>
    <div class="upload-item-main"><div class="upload-item-head"><b>${esc(item.name)}</b><small>${esc(formatBytes(Number(item.size || item.sizeBytes) || 0))}</small></div><div class="upload-bar"><span style="width:${progress}%"></span></div><div class="upload-item-status"><span>${esc(statusText)}</span><strong>${progress}%</strong></div></div>
  </div>`;
}

function uploadQueueMarkup() {
  const items = state.uploadQueue || [];
  if (!items.length) return `<div class="upload-empty"><svg class="icon" aria-hidden="true"><use href="#i-upload"/></svg><strong>${t("ui.alt8mail-office.nothing-in-this-queue-yet")}</strong><span>${t("ui.alt8mail-office.files-you-add-appear-here-with-live-progress")}</span></div>`;
  return `<div class="upload-queue">${items.map((item) => uploadItemMarkup(item)).join("")}</div>`;
}

function uploadMobileMarkup() {
  const session = state.uploadMobileSession;
  if (!session) return `<div class="upload-empty"><div class="list-loading-spinner" aria-hidden="true"></div><strong>${t("ui.alt8mail-office.generating-a-secure-upload-link")}</strong></div>`;
  const active = session.active !== false && Date.parse(session.expiresAt || "") > Date.now();
  const uploads = Array.isArray(session.uploads) ? session.uploads : [];
  const qr = state.uploadMobileQrData && state.uploadMobileQrSession === session.id
    ? `<img src="${esc(state.uploadMobileQrData)}" alt="${esc(t("ui.alt8mail-office.qr-code-for-mobile-upload"))}" width="180" height="180">`
    : `<div class="upload-qr-host" id="uploadMobileQr"></div>`;
  return `<div class="upload-mobile-card">
    <div class="upload-qr-frame">${active ? qr : `<div class="upload-qr-expired"><svg class="icon" aria-hidden="true"><use href="#i-clock"/></svg><strong>${t("ui.alt8mail-office.link-expired")}</strong><span>${t("ui.alt8mail-office.generate-a-fresh-qr-code")}</span></div>`}</div>
    <div class="upload-mobile-copy"><strong>${active ? t("ui.alt8mail-office.scan-with-your-phone") : t("ui.alt8mail-office.qr-code-expired")}</strong><span>${active ? t("ui.alt8mail-office.open-the-camera-and-scan-the-page-stays-signed-i") : t("ui.alt8mail-office.start-a-new-session-to-keep-uploading")}</span>
      <div class="upload-mobile-actions">${active ? `<button class="btn-secondary small" type="button" data-upload-copy-url><svg class="icon" aria-hidden="true"><use href="#i-copy"/></svg>${t("ui.alt8mail-office.copy-link")}</button>` : ""}<button class="btn-secondary small" type="button" data-upload-new-session><svg class="icon" aria-hidden="true"><use href="#i-refresh"/></svg>${t("ui.alt8mail-office.new-qr")}</button></div>
      ${active ? `<div class="upload-expiry"><svg class="icon" aria-hidden="true"><use href="#i-clock"/></svg><span>${esc(t("ui.alt8mail-office.expires-relative", { time: formatRelativeTime(session.expiresAt) }))}</span><button type="button" data-upload-extend="1">${t("ui.alt8mail-office.1-hour")}</button><button type="button" data-upload-extend="4">${t("ui.alt8mail-office.4-hours")}</button></div>` : ""}
    </div>
  </div>
  ${uploads.length ? `<div class="upload-mobile-list"><div class="upload-mobile-head">${t("ui.alt8mail-office.from-your-phone")} <span>${uploads.length}</span></div>${uploads.map((item) => uploadItemMarkup({ ...item, kind: "mobile", startedAt: Date.parse(item.startedAt || "") || 0, endedAt: item.status === "done" ? Date.parse(item.updatedAt || item.startedAt || "") || Date.now() : 0 }, { mobile: true })).join("")}</div>` : ""}`;
}

function renderUploadManager() {
  const manager = ensureUploadManager();
  if (!manager) return;
  manager.hidden = !state.uploadManagerOpen;
  if (!state.uploadManagerOpen) return;
  manager.classList.toggle("is-minimized", state.uploadManagerMinimized);
  const stats = uploadManagerStats();
  const summary = document.getElementById("uploadManagerSummary");
  if (summary) summary.textContent = stats.active ? `${stats.active} uploading${stats.done ? ` · ${stats.done} done` : ""}${stats.failed ? ` · ${stats.failed} failed` : ""}` : stats.done ? `${stats.done} file${stats.done === 1 ? "" : "s"} uploaded` : t("ui.alt8mail-office.ready-for-files");
  manager.querySelectorAll("[data-upload-tab]").forEach((button) => {
    const active = button.getAttribute("data-upload-tab") === state.uploadTab;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", active ? "true" : "false");
  });
  const body = document.getElementById("uploadManagerBody");
  if (!body) return;
  if (state.uploadTab === "url") {
    body.innerHTML = `<div class="upload-panel"><label class="upload-url-field"><span>${t("ui.alt8mail-office.file-url")}</span><input id="uploadUrlInput" type="url" value="${esc(state.uploadUrlValue || "")}" placeholder="https://example.com/report.pdf" autocomplete="off"></label><button class="btn-primary" type="button" data-upload-url-add><svg class="icon" aria-hidden="true"><use href="#i-link"/></svg>${t("ui.alt8mail-office.add-to-cabinet")}</button><p class="upload-note">${t("ui.alt8mail-office.alt8mail-fetches-the-file-directly-into-alt8mail")}</p>${uploadQueueMarkup()}</div>`;
  } else if (state.uploadTab === "mobile") {
    body.innerHTML = `<div class="upload-panel">${uploadMobileMarkup()}</div>`;
    renderUploadMobileQr();
  } else {
    body.innerHTML = `<div class="upload-panel"><div class="upload-drop" data-upload-drop><span class="upload-drop-icon"><svg class="icon" aria-hidden="true"><use href="#i-upload"/></svg></span><strong>${t("ui.alt8mail-office.drop-files-here")}</strong><span>${t("ui.alt8mail-office.or")} <button class="link-btn" type="button" data-upload-choose>${t("ui.alt8mail-office.choose-from-this-device")}</button></span><small>${esc(uploadTargetLabel(state.uploadTargetProvider, state.uploadTargetFolderId))}</small><input id="uploadManagerInput" type="file" multiple hidden></div>${uploadQueueMarkup()}</div>`;
  }
}

function renderUploadMobileQr() {
  const host = document.getElementById("uploadMobileQr");
  const session = state.uploadMobileSession;
  if (!host || !session?.url) return;
  if (state.uploadMobileQrData && state.uploadMobileQrSession === session.id) return;
  host.innerHTML = "";
  if (!window.QRCode) {
    host.innerHTML = `<a class="upload-qr-fallback" href="${esc(session.url)}" target="_blank" rel="noopener">${t("ui.alt8mail-office.open-upload-page")}</a>`;
    return;
  }
  try {
    new window.QRCode(host, { text: session.url, width: 180, height: 180, correctLevel: window.QRCode.CorrectLevel.M, colorDark: "#0b1a2a", colorLight: "#ffffff" });
    const canvas = host.querySelector("canvas");
    if (canvas) {
      state.uploadMobileQrData = canvas.toDataURL("image/png");
      state.uploadMobileQrSession = session.id;
    }
  } catch {
    host.innerHTML = `<a class="upload-qr-fallback" href="${esc(session.url)}" target="_blank" rel="noopener">${t("ui.alt8mail-office.open-upload-page")}</a>`;
  }
}

function enqueueCabinetUploads(files, folderId = state.fileFolderId, providerId = uploadTargetProvider()) {
  if (!files?.length) return;
  if (!state.uploadManagerOpen) openUploadManager("computer", { folderId });
  const max = state.attachmentMaxBytes || 8 * 1024 * 1024;
  let queued = 0;
  for (const file of Array.from(files)) {
    if (file.size > max) { showToast(t("ui.alt8mail-office.file-larger-than-limit", { name: file.name, limit: formatBytes(max) })); continue; }
    state.uploadQueue.push({
      id: `up_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      kind: "file", name: file.name, size: file.size, progress: 0, status: "queued",
      startedAt: 0, endedAt: 0, file, folderId: folderId || "", providerId: providerId || "a8m"
    });
    queued += 1;
  }
  if (queued) {
    state.uploadTab = "computer";
    renderUploadManager();
    processUploadQueue();
  }
}

function enqueueUrlImport(url) {
  if (!state.uploadManagerOpen) openUploadManager("url", { folderId: state.uploadTargetFolderId });
  state.uploadQueue.push({
    id: `up_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    kind: "url", name: url.replace(/^https?:\/\//, "").slice(0, 80), size: 0, progress: 0,
    status: "queued", startedAt: 0, endedAt: 0, url,
    folderId: state.uploadTargetFolderId || "", providerId: "a8m"
  });
  state.uploadUrlValue = "";
  state.uploadTab = "url";
  renderUploadManager();
  processUploadQueue();
}

function postJSONWithProgress(path, body, onProgress) {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open("POST", path);
    xhr.setRequestHeader(t("ui.calendar.accept"), "application/json");
    xhr.setRequestHeader(t("ui.alt8mail-office.content-type"), "application/json");
    if (state.delegatedSession?.token) xhr.setRequestHeader(DELEGATED_SESSION_HEADER, state.delegatedSession.token);
    if (state.csrf) xhr.setRequestHeader(t("ui.alt8mail-office.x-csrf-token"), state.csrf);
    xhr.upload.onprogress = (event) => { if (event.lengthComputable) onProgress(event.loaded / event.total); };
    xhr.onerror = () => reject(new Error(t("ui.alt8mail-office.network-error-while-uploading")));
    xhr.onload = () => {
      let payload = null;
      try { payload = JSON.parse(xhr.responseText || "{}"); } catch {}
      if (xhr.status >= 200 && xhr.status < 300) { resolve(payload); return; }
      if (xhr.status === 401) handleSessionExpired();
      const detail = payload?.error || {};
      reject(new Error(detail.message || t("ui.compose-manager.upload-failed-status", { status: xhr.status })));
    };
    xhr.send(JSON.stringify(body));
  });
}

async function performUploadItem(item) {
  item.status = "preparing";
  item.startedAt = Date.now();
  renderUploadManager();
  try {
    if (item.kind === "url") {
      let progress = 8;
      const timer = setInterval(() => { progress = Math.min(88, progress + 7); item.progress = progress; renderUploadManager(); }, 320);
      try {
        const data = await api("/api/files/import-url", { method: "POST", body: { url: item.url, folderId: item.folderId || "" } });
        item.fileId = data.file?.id || "";
        item.name = data.file?.name || item.name;
        item.size = Number(data.file?.sizeBytes) || item.size;
      } finally { clearInterval(timer); }
      item.progress = 100;
    } else {
      const dataBase64 = await fileToBase64(item.file);
      item.status = "uploading";
      const attachment = await postJSONWithProgress("/api/attachments", {
        name: item.file.name, mime: item.file.type || "application/octet-stream", dataBase64
      }, (fraction) => { item.progress = Math.max(2, Math.min(72, Math.round(fraction * 72))); renderUploadManager(); });
      item.progress = 78;
      renderUploadManager();
      const created = await api("/api/files", {
        method: "POST",
        body: { providerId: item.providerId || "a8m", attachmentId: attachment.attachment.id, folderId: item.providerId === "a8m" ? (item.folderId || "") : "" }
      });
      item.fileId = created.file?.id || "";
      item.size = Number(created.file?.sizeBytes) || item.size;
      if (created.file && !state.files.some((file) => file.id === created.file.id)) state.files.unshift(created.file);
      item.progress = 100;
    }
    item.status = "done";
    item.endedAt = Date.now();
  } catch (error) {
    item.status = "error";
    item.error = error.message || t("ui.alt8mail-office.upload-failed");
    item.endedAt = Date.now();
  }
  renderUploadManager();
}

async function processUploadQueue() {
  if (state.uploadWorkerBusy) return;
  state.uploadWorkerBusy = true;
  let completed = 0;
  let failed = 0;
  try {
    while (true) {
      const item = state.uploadQueue.find((entry) => entry.status === "queued");
      if (!item) break;
      await performUploadItem(item);
      if (item.status === "done") completed += 1;
      if (item.status === "error") failed += 1;
    }
  } finally {
    state.uploadWorkerBusy = false;
    renderUploadManager();
    if (state.task === "files") refreshCabinet().catch(() => {});
    if (completed || failed) {
      const parts = [];
      if (completed) parts.push(`${completed} uploaded`);
      if (failed) parts.push(`${failed} failed`);
      showToast(parts.join(" · "), failed ? t("ui.alt8mail-office.error") : undefined);
    }
  }
}

function ensureMobileUploadSession() {
  return createMobileUploadSession(false);
}

async function createMobileUploadSession(force = false) {
  if (!state.user) return;
  if (!force && state.uploadMobileSession?.active) return state.uploadMobileSession;
  if (force && state.uploadMobileSession?.id) {
    await api(`/api/upload-sessions/${encodeURIComponent(state.uploadMobileSession.id)}`, { method: "DELETE" }).catch(() => {});
  }
  const data = await api("/api/upload-sessions", { method: "POST", body: { folderId: state.uploadTargetFolderId || "" } });
  state.uploadMobileSession = data.session;
  state.uploadMobileSeen = new Map();
  state.uploadMobileQrData = "";
  state.uploadMobileQrSession = "";
  startMobileUploadPoll();
  renderUploadManager();
  return state.uploadMobileSession;
}

function startMobileUploadPoll() {
  clearInterval(state.uploadMobilePoll);
  state.uploadMobilePoll = setInterval(() => refreshMobileUploadSession().catch(() => {}), 2200);
}

async function refreshMobileUploadSession() {
  const session = state.uploadMobileSession;
  if (!session?.id) return;
  const data = await api(`/api/upload-sessions/${encodeURIComponent(session.id)}`);
  state.uploadMobileSession = data.session;
  let completedNew = false;
  for (const item of data.session?.uploads || []) {
    const previous = state.uploadMobileSeen.get(item.id);
    if (item.status === "done" && previous !== "done") completedNew = true;
    state.uploadMobileSeen.set(item.id, item.status);
  }
  if (state.uploadManagerOpen && state.uploadTab === "mobile") renderUploadManager();
  if (completedNew) {
    await refreshCabinet().catch(() => {});
    showToast(t("ui.alt8mail-office.a-file-arrived-from-your-phone"));
  }
  if (!data.session?.active || Date.parse(data.session?.expiresAt || "") <= Date.now()) {
    clearInterval(state.uploadMobilePoll);
    state.uploadMobilePoll = null;
  }
}

async function extendMobileUploadSession(hours = 1) {
  const session = state.uploadMobileSession;
  if (!session?.id) return;
  const data = await api(`/api/upload-sessions/${encodeURIComponent(session.id)}/extend`, { method: "POST", body: { hours } });
  state.uploadMobileSession = data.session;
  showToast(tn("ui.alt8mail-office.upload-link-extended", hours, { count: hours }));
  renderUploadManager();
}

async function uploadFiles(files, folderId = state.fileFolderId) {
  if (!files?.length) return;
  enqueueCabinetUploads(files, folderId, uploadTargetProvider());
}

/* ============================================================
   scheduled outbox
   ============================================================ */
function scheduledItems() {
  return state.pendingSends
    .filter((item) => item.scheduled)
    .sort((a, b) => Date.parse(a.sendAt) - Date.parse(b.sendAt));
}

function scheduledItemById(id) {
  return state.pendingSends.find((item) => item.scheduled && item.id === id) || null;
}

function scheduledRecipients(item) {
  const people = (item.to || []).map((person) => person.name || person.email).filter(Boolean);
  if (!people.length) return t("ui.scheduled-outbox.no-recipients");
  return people.length > 3 ? `${people.slice(0, 3).join(", ")} +${people.length - 3}` : people.join(", ");
}

function scheduledAliasLabel(item) {
  const alias = state.aliases.find((entry) => normalizeEmail(entry.email) === normalizeEmail(item.from && item.from.email));
  return alias ? alias.label : (item.from && (item.from.name || item.from.email)) || "Alt8Mail";
}

function scheduledAssessment(stamp) {
  const dateKey = dateKeyInZone(stamp);
  const parts = timeZoneParts(stamp);
  const time = `${String(parts.hour).padStart(2, "0")}:${String(parts.minute).padStart(2, "0")}`;
  const workDays = state.preferences.workDays && state.preferences.workDays.length ? state.preferences.workDays : [1, 2, 3, 4, 5];
  const start = state.preferences.workStart || "09:00";
  const end = state.preferences.workEnd || "17:00";
  const workDay = workDays.includes(weekdayOfKey(dateKey));
  const withinHours = time >= start && time < end;
  return {
    workDay,
    withinHours,
    ok: workDay && withinHours,
    label: !workDay ? t("ui.scheduled-outbox.outside-working-days") : withinHours ? t("ui.scheduled-outbox.within-working-hours") : t("ui.scheduled-outbox.outside-working-hours")
  };
}

function scheduledDayLabel(key) {
  const today = dateKeyInZone(new Date());
  if (key === today) return t("mail.list.date.today");
  if (key === addDaysToKey(today, 1)) return t("ui.scheduled-outbox.tomorrow");
  const parts = keyToParts(key);
  if (!parts) return key;
  return new Intl.DateTimeFormat(currentLocale(), {
    weekday: "long", month: "long", day: "numeric", timeZone: "UTC"
  }).format(new Date(Date.UTC(parts.year, parts.month - 1, parts.day, 12)));
}

function scheduledDateBlock(stamp) {
  const parts = timeZoneParts(stamp);
  const date = new Date(Date.UTC(parts.year, parts.month - 1, parts.day, 12));
  return {
    day: parts.day,
    weekday: new Intl.DateTimeFormat(currentLocale(), { weekday: "short", timeZone: "UTC" }).format(date),
    month: new Intl.DateTimeFormat(currentLocale(), { month: "short", timeZone: "UTC" }).format(date).toUpperCase(),
    time: formatClock(stamp)
  };
}

function renderScheduled() {
  if (!scheduledView || !scheduledList) return;
  const allItems = scheduledItems();
  const query = state.query.trim().toLowerCase();
  const items = query ? allItems.filter((item) => {
    const haystack = [
      item.subject,
      item.bodyText,
      scheduledRecipients(item),
      scheduledAliasLabel(item),
      ...(item.attachments || []).map((file) => file.name)
    ].join(" ").toLowerCase();
    return haystack.includes(query);
  }) : allItems;
  const next = items[0];
  const withFiles = items.filter((item) => (item.attachments || []).length).length;
  const withinHours = items.filter((item) => scheduledAssessment(item.sendAt).ok).length;
  scheduledMeta.textContent = items.length
    ? `${items.length}${query ? ` of ${allItems.length}` : ""} waiting · ${formatRelativeTime(next.sendAt)}`
    : query ? tn("ui.scheduled-outbox.no-matches-in-scheduled", allItems.length, { count: allItems.length }) : t("ui.scheduled-outbox.no-messages-waiting");
  scheduledZoneLabel.textContent = formatTimeZoneLabel();
  scheduledQueueNote.textContent = items.length
    ? t("ui.scheduled-outbox.next-leaves-with-zone", { when: formatRelativeTime(next.sendAt), zone: currentTimeZone().replace(/_/g, " ") })
    : t("ui.scheduled-outbox.summary-with-zone", { zone: currentTimeZone().replace(/_/g, " ") });
  scheduledSummary.innerHTML = `
    <div class="scheduled-stat${items.length ? " is-accent" : ""}">
      <span class="scheduled-stat-icon"><svg class="icon" aria-hidden="true"><use href="#i-calendar-clock"/></svg></span>
      <div><span class="scheduled-stat-value">${items.length}</span><span class="scheduled-stat-label">${t("shell.scheduled")}</span><span class="scheduled-stat-hint">${t("ui.scheduled-outbox.server-backed-queue")}</span></div>
    </div>
    <div class="scheduled-stat">
      <span class="scheduled-stat-icon"><svg class="icon" aria-hidden="true"><use href="#i-clock"/></svg></span>
      <div><span class="scheduled-stat-value">${next ? formatRelativeTime(next.sendAt) : "—"}</span><span class="scheduled-stat-label">${t("ui.scheduled-outbox.next-send")}</span><span class="scheduled-stat-hint">${next ? formatDateTimeFull(next.sendAt) : t("ui.scheduled-outbox.nothing-queued")}</span></div>
    </div>
    <div class="scheduled-stat">
      <span class="scheduled-stat-icon"><svg class="icon" aria-hidden="true"><use href="#i-check"/></svg></span>
      <div><span class="scheduled-stat-value">${withinHours}</span><span class="scheduled-stat-label">${t("ui.scheduled-outbox.within-work-hours")}</span><span class="scheduled-stat-hint">${t("ui.scheduled-outbox.policy-aware-delivery")}</span></div>
    </div>
    <div class="scheduled-stat">
      <span class="scheduled-stat-icon"><svg class="icon" aria-hidden="true"><use href="#i-paperclip"/></svg></span>
      <div><span class="scheduled-stat-value">${withFiles}</span><span class="scheduled-stat-label">${t("ui.scheduled-outbox.with-attachments")}</span><span class="scheduled-stat-hint">${esc(tn("ui.scheduled-outbox.text-only-count", items.length - withFiles, { count: items.length - withFiles }))}</span></div>
    </div>`;
  if (!items.length) {
    scheduledList.innerHTML = `<div class="scheduled-empty">
      <span class="scheduled-empty-art"><svg class="icon" aria-hidden="true"><use href="#${query ? "i-search" : "i-calendar-clock"}"/></svg></span>
      <h2>${query ? t("ui.scheduled-outbox.no-scheduled-messages-match") : t("ui.scheduled-outbox.nothing-on-the-schedule")}</h2>
      <p>${query ? esc(t("ui.scheduled-outbox.no-match-for-query", { query: state.query })) : t("ui.scheduled-outbox.write-a-message-choose-send-later-and-it-will-wa")}</p>
      ${query ? "<button class=\"btn-secondary\" data-clear-filters type=\"button\">" + t("shell.clearSearch") + "</button>" : "<button class=\"btn-primary\" data-scheduled-compose type=\"button\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-compose\"/></svg>" + t("ui.scheduled-outbox.compose-a-message") + "</button>"}
      <div class="scheduled-empty-tips"><span>${t("ui.scheduled-outbox.server-persisted")}</span><span>${t("ui.scheduled-outbox.time-zone-aware")}</span><span>${t("ui.scheduled-outbox.fully-audited")}</span></div>
    </div>`;
    return;
  }
  const groups = new Map();
  for (const item of items) {
    const key = dateKeyInZone(item.sendAt);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(item);
  }
  scheduledList.innerHTML = Array.from(groups.entries()).map(([key, groupItems]) => {
    const cards = groupItems.map((item) => {
      const stamp = new Date(item.sendAt);
      const block = scheduledDateBlock(stamp);
      const assessment = scheduledAssessment(stamp);
      const files = (item.attachments || []).length;
      return `<article class="scheduled-card${assessment.ok ? "" : " is-outside"}" data-scheduled-id="${esc(item.id)}">
        <div class="scheduled-date">
          <span class="scheduled-date-weekday">${esc(block.weekday)}</span>
          <strong>${block.day}</strong>
          <span class="scheduled-date-month">${esc(block.month)}</span>
          <small>${esc(block.time)}</small>
        </div>
        <div class="scheduled-card-main">
          <div class="scheduled-card-top">
            <span class="scheduled-state ${assessment.ok ? "is-ok" : "is-warning"}">${esc(assessment.label)}</span>
            <span class="scheduled-relative"><svg class="icon" aria-hidden="true"><use href="#i-clock"/></svg>${esc(formatRelativeTime(stamp))}</span>
          </div>
          <h3>${esc(item.subject || t("mail.list.noSubject"))}</h3>
          <div class="scheduled-recipient-line"><span>${t("mail.details.to")}</span> ${esc(scheduledRecipients(item))}<i aria-hidden="true"></i><span>${t("mail.details.from")}</span> ${esc(scheduledAliasLabel(item))}</div>
          <p class="scheduled-preview">${esc((item.bodyText || "").slice(0, 180)) || t("ui.scheduled-outbox.no-message-body-yet")}</p>
          <div class="scheduled-card-meta">
            <span><svg class="icon" aria-hidden="true"><use href="#i-calendar-clock"/></svg>${esc(formatDateTimeFull(stamp))}</span>
            ${files ? `<span><svg class="icon" aria-hidden="true"><use href="#i-paperclip"/></svg>${files} attachment${files === 1 ? "" : "s"}</span>` : ""}
            <span><svg class="icon" aria-hidden="true"><use href="#i-shield-check"/></svg>${t("ui.scheduled-outbox.server-queue")}</span>
          </div>
        </div>
        <div class="scheduled-card-actions">
          <button class="btn-primary" data-scheduled-send-now="${esc(item.id)}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-send"/></svg>${t("ui.scheduled-outbox.send-now")}</button>
          <button class="btn-secondary" data-scheduled-edit="${esc(item.id)}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-compose"/></svg>${t("tasks.detail.edit")}</button>
          <button class="btn-secondary danger-btn" data-scheduled-cancel="${esc(item.id)}" type="button"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg>${t("tasks.action.cancel")}</button>
        </div>
      </article>`;
    }).join("");
    return `<section class="scheduled-group"><header class="scheduled-group-head"><h3>${esc(scheduledDayLabel(key))}</h3><span>${groupItems.length} message${groupItems.length === 1 ? "" : "s"}</span></header>${cards}</section>`;
  }).join("");
}

function openScheduledEdit(id) {
  const item = scheduledItemById(id);
  if (!item) { showToast(t("ui.scheduled-outbox.that-scheduled-message-is-no-longer-available")); return; }
  closeStatusPop();
  state.scheduledEditId = id;
  const stamp = new Date(item.sendAt);
  const parts = timeZoneParts(stamp);
  scheduledEditTo.value = (item.to || []).map((person) => person.email).join(", ");
  scheduledEditCc.value = (item.cc || []).map((person) => person.email).join(", ");
  scheduledEditSubject.value = item.subject || "";
  scheduledEditBody.innerHTML = item.bodyHtml || textToEditorHTML(item.bodyText || "");
  scheduledEditDate.min = dateKeyInZone(new Date());
  scheduledEditDate.value = dateKeyInZone(stamp);
  scheduledEditTime.value = `${String(parts.hour).padStart(2, "0")}:${String(parts.minute).padStart(2, "0")}`;
  scheduledEditOriginal.innerHTML = `<span class="eyebrow">${t("ui.scheduled-outbox.currently-scheduled")}</span><strong>${esc(formatDateTimeFull(stamp))}</strong><span>${esc(formatRelativeTime(stamp))} · from ${esc(scheduledAliasLabel(item))}</span>`;
  const attachments = (item.attachments || []).length;
  scheduledEditAttachments.innerHTML = attachments
    ? `<svg class="icon" aria-hidden="true"><use href="#i-paperclip"/></svg><span>${esc(tn("ui.scheduled-outbox.attachments-stay", attachments, { count: attachments }))}</span>`
    : `<svg class="icon" aria-hidden="true"><use href="#i-paperclip"/></svg><span>${t("ui.scheduled-outbox.no-attachments-on-this-message")}</span>`;
  state.scheduledEditPresets = buildSchedulePresets().slice(0, 3);
  scheduledEditPresets.innerHTML = state.scheduledEditPresets.map((preset) => `<button class="scheduled-preset" data-scheduled-edit-preset="${esc(preset.id)}" type="button"><strong>${esc(preset.title)}</strong><span>${esc(formatDateOnly(preset.date))} · ${esc(formatClock(zonedWallTimeToUtc(preset.date, preset.time)))}</span></button>`).join("");
  scheduledEditError.hidden = true;
  scheduledEditOverlay.hidden = false;
  updateScheduledEditInsight();
  setTimeout(() => scheduledEditSubject.focus(), 40);
}

function closeScheduledEdit() {
  scheduledEditOverlay.hidden = true;
  scheduledEditBody.innerHTML = "";
  state.scheduledEditId = null;
  scheduledEditError.hidden = true;
  scheduledEditSave.disabled = false;
  scheduledEditSave.innerHTML = "<svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-check\"/></svg>" + t("mail.folders.saveChanges");
}

async function applyScheduledEditCommand(command, value = null) {
  const editor = scheduledEditBody;
  if (!editor) return;
  editor.focus();
  if (command === "createLink") {
    const href = await appPrompt({
      eyebrow: t("ui.scheduled-outbox.scheduled-message"),
      title: t("ui.scheduled-outbox.insert-link"),
      label: t("ui.scheduled-outbox.link-url"),
      value: "https://",
      placeholder: "https://example.com",
      type: "url",
      confirmLabel: t("ui.scheduled-outbox.insert-link"),
      validate: (value) => /^(https?:\/\/|mailto:)/i.test(value) ? "" : t("ui.scheduled-outbox.links-must-start-with-https-http-or-mailto")
    });
    if (!href) return;
    try { document.execCommand("styleWithCSS", false, true); } catch {}
    document.execCommand("createLink", false, href.trim());
    return;
  }
  try { document.execCommand("styleWithCSS", false, true); } catch {}
  document.execCommand(command, false, value);
}

function updateScheduledEditInsight() {
  if (scheduledEditOverlay.hidden) return;
  const stamp = zonedWallTimeToUtc(scheduledEditDate.value, scheduledEditTime.value);
  if (!stamp || Number.isNaN(stamp.getTime())) {
    scheduledEditInsight.innerHTML = "<span class=\"scheduled-insight-error\">" + t("ui.scheduled-outbox.choose-a-valid-send-date-and-time") + "</span>";
    scheduledEditSave.disabled = true;
    return;
  }
  const future = stamp.getTime() > Date.now() + 5000;
  const assessment = scheduledAssessment(stamp);
  scheduledEditInsight.innerHTML = `<div class="scheduled-edit-insight-when"><span class="eyebrow">${t("ui.scheduled-outbox.leaves-the-outbox")}</span><strong>${esc(formatDateTimeFull(stamp))}</strong><span>${esc(formatRelativeTime(stamp))} · ${esc(formatTimeZoneLabel())}</span></div><span class="scheduled-state ${assessment.ok ? "is-ok" : "is-warning"}">${esc(assessment.label)}</span>`;
  if (!future) {
    scheduledEditInsight.innerHTML += "<span class=\"scheduled-insight-error\">" + t("ui.scheduled-outbox.choose-a-time-at-least-a-few-seconds-in-the-futu") + "</span>";
  }
  scheduledEditSave.disabled = !future;
}

async function saveScheduledEdit() {
  const item = scheduledItemById(state.scheduledEditId);
  if (!item) { closeScheduledEdit(); showToast(t("ui.scheduled-outbox.that-scheduled-message-is-no-longer-available")); return; }
  const stamp = zonedWallTimeToUtc(scheduledEditDate.value, scheduledEditTime.value);
  if (!stamp || stamp.getTime() <= Date.now() + 5000) {
    scheduledEditError.textContent = t("ui.scheduled-outbox.choose-a-send-time-at-least-a-few-seconds-in-the");
    scheduledEditError.hidden = false;
    return;
  }
  scheduledEditSave.disabled = true;
  scheduledEditSave.textContent = t("ui.scheduled-outbox.saving");
  try {
    const data = await api(`/api/outbox/${encodeURIComponent(item.id)}`, {
      method: "PATCH",
      body: {
        to: scheduledEditTo.value,
        cc: scheduledEditCc.value,
        subject: scheduledEditSubject.value,
        bodyHtml: scheduledEditBody.innerHTML,
        bodyText: scheduledEditBody.innerText,
        sendAt: stamp.toISOString()
      }
    });
    state.pendingSends = data.pending || state.pendingSends;
    if (data.outbound) state.outbound = data.outbound;
    updatePendingUi();
    updateScheduledUi();
    updateOutboundUi();
    stopOutboxPolling();
    startOutboxPolling();
    closeScheduledEdit();
    showToast(t("ui.scheduled-outbox.scheduled-message-updated"));
  } catch (error) {
    scheduledEditError.textContent = error.message;
    scheduledEditError.hidden = false;
    scheduledEditSave.disabled = false;
    scheduledEditSave.innerHTML = "<svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-check\"/></svg>" + t("mail.folders.saveChanges");
    showError(error);
  }
}

function openSendNowDialog(id) {
  const item = scheduledItemById(id);
  if (!item) { showToast(t("ui.scheduled-outbox.that-scheduled-message-is-no-longer-available")); return; }
  closeStatusPop();
  state.sendNowId = id;
  sendNowSummary.innerHTML = `<strong>${esc(item.subject || t("mail.list.noSubject"))}</strong>
    <span>${esc(t("ui.scheduled-outbox.to-from-summary", { to: scheduledRecipients(item), from: scheduledAliasLabel(item) }))}</span>
    <span class="send-now-original"><svg class="icon" aria-hidden="true"><use href="#i-calendar-clock"/></svg>${esc(t("ui.scheduled-outbox.was-scheduled-for", { when: formatDateTimeFull(item.sendAt) }))}</span>`;
  sendNowConfirm.disabled = false;
  sendNowConfirm.innerHTML = "<svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-send\"/></svg>" + t("ui.scheduled-outbox.send-now");
  sendNowOverlay.hidden = false;
  setTimeout(() => sendNowConfirm.focus(), 40);
}

function closeSendNowDialog() {
  sendNowOverlay.hidden = true;
  state.sendNowId = null;
  sendNowConfirm.disabled = false;
  sendNowConfirm.innerHTML = "<svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-send\"/></svg>" + t("ui.scheduled-outbox.send-now");
}

async function confirmSendNow() {
  const item = scheduledItemById(state.sendNowId);
  if (!item) { closeSendNowDialog(); showToast(t("ui.scheduled-outbox.that-scheduled-message-is-no-longer-available")); return; }
  const subject = item.subject || t("mail.list.noSubject");
  sendNowConfirm.disabled = true;
  sendNowConfirm.textContent = t("shell.sending");
  try {
    const data = await api(`/api/outbox/${encodeURIComponent(item.id)}/send-now`, { method: "POST", body: {} });
    state.pendingSends = data.pending || state.pendingSends;
    if (data.outbound) state.outbound = data.outbound;
    updatePendingUi();
    updateScheduledUi();
    updateOutboundUi();
    stopOutboxPolling();
    startOutboxPolling();
    closeSendNowDialog();
    await refreshMailbox({ quiet: true });
    showToast(t("ui.scheduled-outbox.sent-now", { subject }), t("ui.scheduled-outbox.view-sent"), () => {
      setTask("mail");
      setFolder("sent");
    }, { duration: 9000 });
  } catch (error) {
    if (error.code === "SEND_ALREADY_COMMITTED") {
      state.pendingSends = state.pendingSends.filter((entry) => entry.id !== item.id);
      updatePendingUi();
      updateScheduledUi();
      closeSendNowDialog();
      refreshMailbox({ quiet: true }).catch(() => {});
    } else {
      sendNowConfirm.disabled = false;
      sendNowConfirm.innerHTML = "<svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-send\"/></svg>" + t("ui.scheduled-outbox.send-now");
    }
    showError(error);
  }
}

async function refreshScheduled() {
  try {
    const data = await api("/api/outbox");
    state.pendingSends = data.pending || [];
    if (data.outbound) state.outbound = data.outbound;
    updatePendingUi();
    updateScheduledUi();
    updateOutboundUi();
    renderScheduled();
    showToast(t("ui.scheduled-outbox.schedule-refreshed"));
  } catch (error) {
    showError(error);
  }
}

/* ============================================================
   calendar
   ============================================================ */
const CAL_MONTHS = [t("ui.calendar.january"), t("ui.calendar.february"), t("ui.calendar.march"), t("ui.calendar.april"), t("ui.calendar.may"), t("ui.calendar.june"), t("ui.calendar.july"), t("ui.calendar.august"), t("ui.calendar.september"), t("ui.calendar.october"), t("ui.calendar.november"), t("ui.calendar.december")];
const CAL_WEEKDAYS = [t("ui.calendar.mon"), t("ui.calendar.tue"), t("ui.calendar.wed"), t("ui.calendar.thu"), t("ui.calendar.fri"), t("ui.calendar.sat"), t("ui.calendar.sun")];
const CAL_COLORS = ["#0f6cbd", "#3d6b62", "#7a4a5c", "#8a5a2b", "#476b4f", "#5b4a7e", "#a23b72", "#34557a", "#b45309", "#2563eb", "#0f766e", "#9d174d"];
const CAL_HOUR_START = 7;
const CAL_HOUR_END = 22;
const CAL_HOUR_HEIGHT = 56;

function dateKey(date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

function isoWeek(date) {
  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  const day = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - day);
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
}

function utcDateKey(date) {
  return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, "0")}-${String(date.getUTCDate()).padStart(2, "0")}`;
}

function calendarDateFromKey(key) {
  const parts = keyToParts(key);
  return parts ? new Date(Date.UTC(parts.year, parts.month - 1, parts.day, 12)) : new Date();
}

function calendarById(id) {
  return (state.calendars || []).find((calendar) => calendar.id === id) || null;
}

function calIsOwned(calendar) {
  return Boolean(calendar && calendar.owned);
}

function calCanEdit(calendar) {
  return Boolean(calendar && (calendar.owned || calendar.access === "edit"));
}

function calendarIsVisible(event) {
  if (state.calendarHidden.has(event.calendarId)) return false;
  const calendar = calendarById(event.calendarId);
  if (calendar && calendar.visible === false) return false;
  return true;
}

function calendarColorFor(event) {
  return event.color || calendarById(event.calendarId)?.color || "#0f6cbd";
}

function persistCalendarVisibility() {
  try { localStorage.setItem("a8m.calendar.hidden", JSON.stringify(Array.from(state.calendarHidden))); } catch {}
}

function toggleCalendarVisibility(calendarId, visible) {
  if (visible) state.calendarHidden.delete(calendarId);
  else state.calendarHidden.add(calendarId);
  persistCalendarVisibility();
  const calendar = calendarById(calendarId);
  if (calendar?.owned) {
    api(`/api/calendar/calendars/${encodeURIComponent(calendarId)}`, { method: "PATCH", body: { visible } }).catch(() => {});
    calendar.visible = visible;
  }
  renderCalendar();
}

function calendarMatchesSearch(event) {
  const query = state.calendarSearch.trim().toLowerCase();
  if (!query) return true;
  const haystack = [
    event.title, event.description, event.where, event.organizer, event.organizerName,
    event.calendarName, ...(event.attendeeList || []).map((attendee) => `${attendee.name} ${attendee.email}`),
    ...(event.exceptions || []).map((exception) => `${exception.title} ${exception.location}`)
  ].join(" ").toLowerCase();
  return haystack.includes(query);
}

function parseCalendarRule(rule) {
  const parsed = { freq: "", interval: 1, count: 0, until: "", byDay: [] };
  if (!rule) return parsed;
  for (const part of String(rule).replace(/^RRULE:/i, "").split(";")) {
    const [rawKey, rawValue] = part.split("=");
    const key = String(rawKey || "").trim().toUpperCase();
    const value = String(rawValue || "").trim().toUpperCase();
    if (key === "FREQ") parsed.freq = value;
    else if (key === "INTERVAL") parsed.interval = Math.max(1, Number(value) || 1);
    else if (key === "COUNT") parsed.count = Math.max(0, Number(value) || 0);
    else if (key === "UNTIL") parsed.until = value.length >= 8 ? `${value.slice(0, 4)}-${value.slice(4, 6)}-${value.slice(6, 8)}` : value;
    else if (key === "BYDAY") parsed.byDay = value.split(",").map((day) => day.slice(-2)).filter(Boolean);
  }
  return parsed;
}

function calendarWeekdayCode(date) {
  return ["SU", "MO", "TU", "WE", "TH", "FR", "SA"][date.getUTCDay()];
}

function calendarOccurrenceKeys(event, startKey, endKey) {
  const base = calendarDateFromKey(event.date);
  if (Number.isNaN(base.getTime())) return [];
  const rule = parseCalendarRule(event.recurrenceRule);
  const start = calendarDateFromKey(startKey);
  const end = calendarDateFromKey(endKey);
  if (!rule.freq) return event.date >= startKey && event.date <= endKey ? [event.date] : [];
  const keys = [];
  let produced = 0;
  const baseDay = base.getUTCDate();
  const baseMonth = base.getUTCMonth();
  for (let cursor = new Date(base), guard = 0; cursor <= end && guard < 4000; guard += 1) {
    const key = utcDateKey(cursor);
    if (rule.until && key > rule.until) break;
    if (rule.count && produced >= rule.count) break;
    const daysDiff = Math.round((cursor.getTime() - base.getTime()) / 86400000);
    const weeksDiff = Math.floor(daysDiff / 7);
    const monthsDiff = (cursor.getUTCFullYear() - base.getUTCFullYear()) * 12 + (cursor.getUTCMonth() - baseMonth);
    const yearsDiff = cursor.getUTCFullYear() - base.getUTCFullYear();
    let matches = false;
    if (rule.freq === "DAILY") matches = daysDiff % rule.interval === 0;
    else if (rule.freq === "WEEKLY") {
      matches = rule.byDay.length
        ? weeksDiff % rule.interval === 0 && rule.byDay.includes(calendarWeekdayCode(cursor))
        : daysDiff % (7 * rule.interval) === 0;
    } else if (rule.freq === "MONTHLY") {
      matches = monthsDiff % rule.interval === 0 && cursor.getUTCDate() === baseDay;
    } else if (rule.freq === "YEARLY") {
      matches = yearsDiff % rule.interval === 0 && cursor.getUTCMonth() === baseMonth && cursor.getUTCDate() === baseDay;
    }
    if (matches) {
      produced += 1;
      if (key >= startKey && key <= endKey) keys.push(key);
    }
    cursor = new Date(cursor.getTime() + 86400000);
  }
  return keys;
}

function calendarExceptionOccurrence(event, exception) {
  return {
    ...event,
    title: exception.title || event.title,
    description: exception.description || "",
    where: exception.location || "",
    date: exception.date,
    start: exception.start,
    end: exception.end,
    allDay: Boolean(exception.allDay),
    timezone: exception.timezone || event.timezone,
    status: exception.status || "confirmed",
    sequence: exception.sequence ?? event.sequence,
    reminderMinutes: exception.reminderMinutes ?? event.reminderMinutes,
    occurrenceDate: exception.date,
    occurrenceKey: `${event.id}|${exception.date}|${exception.recurrenceDate}`,
    recurrenceDate: exception.recurrenceDate,
    exceptionId: exception.id,
    recurring: true
  };
}

function calendarOccurrences(startKey, endKey, { all = false } = {}) {
  const out = [];
  const seenExceptions = new Set();
  for (const event of state.calendarEvents || []) {
    if (!all && !calendarIsVisible(event)) continue;
    if (!all && state.calendarHideDeclined && (event.myStatus === "declined" || event.status === "cancelled")) continue;
    if (!all && !calendarMatchesSearch(event)) continue;
    const exceptions = Array.isArray(event.exceptions) ? event.exceptions : [];
    const byOrigin = new Map(exceptions.map((exception) => [exception.recurrenceDate, exception]));
    const keys = calendarOccurrenceKeys(event, startKey, endKey);
    for (const key of keys) {
      const exception = byOrigin.get(key);
      if (exception) {
        seenExceptions.add(exception.id);
        if (exception.status === "cancelled" || exception.date < startKey || exception.date > endKey) continue;
        out.push(calendarExceptionOccurrence(event, exception));
        continue;
      }
      out.push({ ...event, occurrenceDate: key, occurrenceKey: `${event.id}|${key}`, recurring: Boolean(event.recurrenceRule) });
    }
    for (const exception of exceptions) {
      if (seenExceptions.has(exception.id) || exception.status === "cancelled") continue;
      if (exception.date < startKey || exception.date > endKey) continue;
      seenExceptions.add(exception.id);
      out.push(calendarExceptionOccurrence(event, exception));
    }
  }
  out.sort((a, b) => (a.occurrenceDate === b.occurrenceDate ? String(a.start).localeCompare(String(b.start)) : a.occurrenceDate.localeCompare(b.occurrenceDate)));
  return out.slice(0, 2000);
}

function eventsFor(key) {
  return calendarOccurrences(key, key).filter((event) => calendarIsVisible(event));
}

function calendarSelectedDate() {
  return calendarDateFromKey(state.calendarSelected || dateKey(new Date()));
}

function calendarMonthGridStart(year, month) {
  const first = new Date(Date.UTC(year, month, 1, 12));
  const offset = (first.getUTCDay() + 6) % 7;
  return new Date(first.getTime() - offset * 86400000);
}

function calendarViewRange() {
  const selected = calendarSelectedDate();
  if (state.calendarView === "month" || state.calendarView === "split") {
    const start = calendarMonthGridStart(selected.getUTCFullYear(), selected.getUTCMonth());
    return { startKey: utcDateKey(start), endKey: utcDateKey(new Date(start.getTime() + 41 * 86400000)) };
  }
  if (state.calendarView === "week" || state.calendarView === "workweek") {
    const startKey = startOfWeekKey(state.calendarSelected, "monday");
    return { startKey, endKey: addDaysToKey(startKey, 6) };
  }
  if (state.calendarView === "day") return { startKey: state.calendarSelected, endKey: state.calendarSelected };
  return { startKey: state.calendarSelected, endKey: addDaysToKey(state.calendarSelected, 120) };
}

function calendarRangeLabel(startKey, endKey) {
  const start = calendarDateFromKey(startKey);
  const end = calendarDateFromKey(endKey);
  if (state.calendarView === "day") {
    return start.toLocaleDateString(currentLocale(), { weekday: "long", month: "long", day: "numeric", year: "numeric", timeZone: "UTC" });
  }
  if (state.calendarView === "week" || state.calendarView === "workweek") {
    const last = state.calendarView === "workweek" ? calendarDateFromKey(addDaysToKey(startKey, 4)) : end;
    if (start.getUTCMonth() === last.getUTCMonth()) {
      return `${start.toLocaleDateString(currentLocale(), { month: "long", timeZone: "UTC" })} ${start.getUTCDate()}–${last.getUTCDate()}, ${start.getUTCFullYear()}`;
    }
    return `${start.toLocaleDateString(currentLocale(), { month: "short", day: "numeric", timeZone: "UTC" })} – ${last.toLocaleDateString(currentLocale(), { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" })}`;
  }
  if (state.calendarView === "agenda") {
    return `${t("ui.index.text.agenda")} · ${start.toLocaleDateString(currentLocale(), { month: "long", year: "numeric", timeZone: "UTC" })}`;
  }
  const monthAnchor = calendarSelectedDate();
  return monthAnchor.toLocaleDateString(currentLocale(), { month: "long", year: "numeric", timeZone: "UTC" });
}

function calendarEventChip(event, { showTime = true, draggable = true } = {}) {
  const declined = event.myStatus === "declined" || event.status === "cancelled";
  return `<button class="cal-event-chip${event.allDay ? " is-all-day" : ""}${event.invited ? " is-invited" : ""}${declined ? " is-declined" : ""}${event.recurring ? " is-recurring" : ""}" style="--ev:${calendarColorFor(event)}" type="button" data-edit-event="${esc(event.id)}" data-cal-occurrence="${esc(event.occurrenceDate)}"${draggable ? ' draggable="true"' : ""} title="${esc(`${event.start}–${event.end} · ${event.title}${event.where ? ` · ${event.where}` : ""}`)}">
    ${showTime && !event.allDay ? `<span class="cal-event-time">${esc(event.start)}</span>` : ""}
    <span class="cal-event-title">${esc(event.title)}</span>
    ${event.recurring ? '<svg class="icon cal-event-repeat" aria-label="${esc(t("ui.calendar.recurring"))}"><use href="#i-repeat"/></svg>' : ""}
    ${event.invited ? `<span class="cal-rsvp-dot is-${esc(event.myStatus || "needs-action")}" title="${esc(event.myStatus || t("ui.calendar.no-response"))}"></span>` : ""}
  </button>`;
}

function renderCalendar() {
  if (!calMain) return;
  renderCalendarProposalDock();
  if (!state.calendars.length) {
    calMain.innerHTML = `<div class="cal-loading"><span class="passkey-spinner" aria-hidden="true"></span>${t("ui.calendar.loading-calendars")}</div>`;
    return;
  }
  const range = calendarViewRange();
  const occurrences = calendarOccurrences(range.startKey, range.endKey);
  if (calRangeLabel) calRangeLabel.textContent = calendarRangeLabel(range.startKey, range.endKey);
  document.querySelectorAll("#calViewSwitch [data-cal-view]").forEach((button) => {
    button.classList.toggle("is-active", button.getAttribute("data-cal-view") === state.calendarView);
  });
  const hideAgenda = state.calendarView === "agenda";
  if (calAgendaPane) calAgendaPane.hidden = hideAgenda;
  renderCalendarMini();
  renderCalendarLists();
  if (state.calendarView === "month") calMain.innerHTML = monthViewMarkup(occurrences, range);
  else if (state.calendarView === "split") calMain.innerHTML = splitViewMarkup(occurrences, range);
  else if (state.calendarView === "agenda") calMain.innerHTML = agendaViewMarkup(occurrences);
  else calMain.innerHTML = timeViewMarkup(calendarDaysForView(), occurrences);
  renderCalendarAgenda();
  ensureStickyNote("");
  ensureCalendarStickyHost();
  syncStatusRange();
  syncStatusContext();
}

function calendarNarrowWeekdays() {
  const monday = Date.UTC(2024, 0, 1, 12);
  const formatter = new Intl.DateTimeFormat(currentLocale(), { weekday: "narrow", timeZone: "UTC" });
  return Array.from({ length: 7 }, (_value, index) => formatter.format(new Date(monday + index * 86400000)));
}

function renderCalendarMini() {
  if (!calMini) return;
  const year = state.calendarMiniYear ?? state.calendarYear;
  const month = state.calendarMiniMonth ?? state.calendarMonth;
  if (calMiniLabel) calMiniLabel.textContent = `${CAL_MONTHS[month]} ${year}`;
  const start = calendarMonthGridStart(year, month);
  const endKey = utcDateKey(new Date(start.getTime() + 41 * 86400000));
  const occurrences = calendarOccurrences(utcDateKey(start), endKey);
  const eventDates = new Set(occurrences.map((event) => event.occurrenceDate));
  const todayKey = dateKey(new Date());
  let html = `<div class="cal-mini-weekdays">${calendarNarrowWeekdays().map((day) => `<span>${esc(day)}</span>`).join("")}</div><div class="cal-mini-grid">`;
  for (let index = 0; index < 42; index += 1) {
    const date = new Date(start.getTime() + index * 86400000);
    const key = utcDateKey(date);
    const outside = date.getUTCMonth() !== month;
    const classes = ["cal-mini-day", outside ? "is-outside" : "", key === todayKey ? "is-today" : "", key === state.calendarSelected ? "is-selected" : "", eventDates.has(key) ? "has-events" : ""].filter(Boolean).join(" ");
    html += `<button class="${classes}" type="button" data-cal-mini-date="${key}" aria-label="${esc(key)}"><span>${date.getUTCDate()}</span></button>`;
  }
  html += "</div>";
  calMini.innerHTML = html;
}

function calendarListRow(calendar) {
  const checked = !state.calendarHidden.has(calendar.id) && calendar.visible !== false;
  const active = state.calendarActiveId === calendar.id;
  return `<div class="cal-list-row${active ? " is-active" : ""}${calendar.shared ? " is-shared" : ""}" data-calendar-row="${esc(calendar.id)}">
    <label class="cal-list-check" title="${esc(t("ui.calendar.show-or-hide-calendar", { name: calendar.name }))}"><input type="checkbox" data-calendar-visibility="${esc(calendar.id)}" ${checked ? "checked" : ""} aria-label="${esc(t("ui.calendar.show-calendar", { name: calendar.name }))}"><span class="cal-color" style="--cal:${esc(calendar.color)}"></span></label>
    <button class="cal-list-name" type="button" data-calendar-select="${esc(calendar.id)}" title="${esc(calendar.name)}${calendar.shared ? esc(t("ui.calendar.shared-by-owner", { owner: calendar.ownerName || calendar.ownerEmail })) : ""}">${esc(calendar.name)}${calendar.shared ? `<small>${esc(calendar.ownerName || calendar.ownerEmail)}</small>` : ""}</button>
    <span class="cal-list-count">${calendar.eventCount || 0}</span>
    <button class="icon-btn cal-list-more" type="button" data-calendar-menu="${esc(calendar.id)}" aria-label="${esc(t("ui.calendar.options-for", { name: calendar.name }))}"><svg class="icon" aria-hidden="true"><use href="#i-more"/></svg></button>
  </div>`;
}

function renderCalendarLists() {
  const owned = (state.calendars || []).filter((calendar) => calendar.owned && (calendar.kind === "personal" || calendar.kind === "shared"));
  const shared = (state.calendars || []).filter((calendar) => !calendar.owned);
  const other = (state.calendars || []).filter((calendar) => calendar.owned && ["holiday", "birthday", "subscription"].includes(calendar.kind));
  if (calMyCalendars) calMyCalendars.innerHTML = owned.length ? owned.map(calendarListRow).join("") : `<p class="cal-list-empty">${t("ui.calendar.no-calendars-yet")}</p>`;
  if (calSharedHead) calSharedHead.hidden = !shared.length;
  if (calSharedCalendars) calSharedCalendars.innerHTML = shared.map(calendarListRow).join("");
  if (calOtherCalendars) calOtherCalendars.innerHTML = other.length ? other.map(calendarListRow).join("") : `<p class="cal-list-empty">${t("ui.calendar.add-holidays-or-birthdays-for-more-context")}</p>`;
}

function monthViewMarkup(occurrences, range) {
  const start = calendarDateFromKey(range.startKey);
  const month = calendarSelectedDate().getUTCMonth();
  const byDate = new Map();
  for (const event of occurrences) {
    if (!byDate.has(event.occurrenceDate)) byDate.set(event.occurrenceDate, []);
    byDate.get(event.occurrenceDate).push(event);
  }
  const todayKey = dateKey(new Date());
  let html = `<section class="cal-month-view"><div class="cal-month-weekdays">${CAL_WEEKDAYS.map((day) => `<span>${day}</span>`).join("")}</div><div class="cal-month-grid">`;
  for (let index = 0; index < 42; index += 1) {
    const date = new Date(start.getTime() + index * 86400000);
    const key = utcDateKey(date);
    const events = byDate.get(key) || [];
    const classes = ["cal-month-cell", date.getUTCMonth() !== month ? "is-outside" : "", [5, 6].includes(index % 7) ? "is-weekend" : "", key === todayKey ? "is-today" : "", key === state.calendarSelected ? "is-selected" : ""].filter(Boolean).join(" ");
    html += `<div class="${classes}" data-cal-date="${key}" data-cal-drop-date="${key}" role="gridcell" aria-label="${esc(tn("ui.calendar.date-event-count", events.length, { date: key, count: events.length }))}">
      <div class="cal-month-cell-head"><span class="cal-daynum">${date.getUTCDate()}</span><button class="cal-cell-add" type="button" data-cal-new-date="${key}" aria-label="${esc(t("ui.calendar.new-event-on", { date: key }))}"><svg class="icon" aria-hidden="true"><use href="#i-plus"/></svg></button></div>
      <div class="cal-month-events">${events.slice(0, 3).map((event) => calendarEventChip(event)).join("")}${events.length > 3 ? `<button class="cal-more-events" type="button" data-cal-date="${key}">${esc(t("ui.calendar.more-events-count", { count: events.length - 3 }))}</button>` : ""}</div>
    </div>`;
  }
  html += "</div></section>";
  return html;
}

function calendarDaysForView() {
  if (state.calendarView === "day") return [state.calendarSelected];
  const startKey = startOfWeekKey(state.calendarSelected, "monday");
  const count = state.calendarView === "workweek" ? 5 : 7;
  return Array.from({ length: count }, (_, index) => addDaysToKey(startKey, index));
}

function timeViewMarkup(days, occurrences) {
  const byDate = new Map();
  for (const event of occurrences) {
    if (!byDate.has(event.occurrenceDate)) byDate.set(event.occurrenceDate, []);
    byDate.get(event.occurrenceDate).push(event);
  }
  const todayKey = dateKey(new Date());
  const totalHours = CAL_HOUR_END - CAL_HOUR_START;
  const gridHeight = totalHours * CAL_HOUR_HEIGHT;
  const allDayEvents = days.flatMap((day) => (byDate.get(day) || []).filter((event) => event.allDay));
  const timed = (day) => (byDate.get(day) || []).filter((event) => !event.allDay);
  let html = `<section class="cal-time-view" style="--days:${days.length};--hour-height:${CAL_HOUR_HEIGHT}px">
    <div class="cal-time-head"><div class="cal-time-gutter-head"></div>${days.map((day) => {
      const date = calendarDateFromKey(day);
      return `<div class="cal-time-day-head${day === todayKey ? " is-today" : ""}${day === state.calendarSelected ? " is-selected" : ""}" data-cal-date="${day}"><span>${date.toLocaleDateString(currentLocale(), { weekday: "short", timeZone: "UTC" })}</span><strong>${date.getUTCDate()}</strong></div>`;
    }).join("")}</div>
    <div class="cal-time-allday"><div class="cal-time-gutter-label">${t("ui.calendar.all-day")}</div>${days.map((day) => `<div class="cal-time-allday-cell" data-cal-date="${day}" data-cal-drop-date="${day}">${(byDate.get(day) || []).filter((event) => event.allDay).map((event) => calendarEventChip(event, { showTime: false })).join("")}</div>`).join("")}</div>
    <div class="cal-time-scroll">
      <div class="cal-time-gutter" style="height:${gridHeight}px">${Array.from({ length: totalHours + 1 }, (_, index) => `<span style="top:${index * CAL_HOUR_HEIGHT}px">${String(CAL_HOUR_START + index).padStart(2, "0")}:00</span>`).join("")}</div>
      <div class="cal-time-columns" style="height:${gridHeight}px">${days.map((day) => {
        const events = timed(day);
        const now = new Date();
        const nowMinutes = now.getHours() * 60 + now.getMinutes();
        const showNow = day === todayKey;
        return `<div class="cal-time-col" data-cal-date="${day}" data-cal-drop-date="${day}" data-cal-slot="${day}">
          <div class="cal-hour-lines" style="height:${gridHeight}px"></div>
          ${events.map((event) => {
            const [hour, minute] = String(event.start || "09:00").split(":").map(Number);
            const [endHour, endMinute] = String(event.end || "10:00").split(":").map(Number);
            const top = Math.max(0, (hour * 60 + minute - CAL_HOUR_START * 60) / 60 * CAL_HOUR_HEIGHT);
            const height = Math.max(22, ((endHour * 60 + endMinute) - (hour * 60 + minute)) / 60 * CAL_HOUR_HEIGHT - 3);
            return `<div class="cal-time-event" style="--ev:${calendarColorFor(event)};top:${top}px;height:${height}px">${calendarEventChip(event, { showTime: false })}</div>`;
          }).join("")}
          ${showNow && nowMinutes >= CAL_HOUR_START * 60 && nowMinutes <= CAL_HOUR_END * 60 ? `<div class="cal-now-line" style="top:${(nowMinutes - CAL_HOUR_START * 60) / 60 * CAL_HOUR_HEIGHT}px"><span>${now.toLocaleTimeString(currentLocale(), { hour: "numeric", minute: "2-digit" })}</span></div>` : ""}
        </div>`;
      }).join("")}</div>
    </div>
  </section>`;
  return html;
}

function splitViewMarkup(occurrences, range) {
  const month = monthViewMarkup(occurrences, range);
  const dayOccurrences = calendarOccurrences(state.calendarSelected, state.calendarSelected);
  return `<div class="cal-split-view"><div class="cal-split-month">${month}</div><div class="cal-split-day">${timeViewMarkup([state.calendarSelected], dayOccurrences)}</div></div>`;
}

function agendaViewMarkup(occurrences) {
  if (!occurrences.length) {
    return `<div class="cal-agenda-main-empty"><span class="file-detail-mark"><svg class="icon" aria-hidden="true"><use href="#i-calendar"/></svg></span><h2>${state.calendarSearch ? t("ui.calendar.no-matching-events") : t("ui.calendar.your-schedule-is-clear")}</h2><p>${state.calendarSearch ? t("ui.calendar.try-a-different-search-term") : t("ui.calendar.create-an-event-or-add-a-shared-calendar-to-see-")}</p><button class="btn-primary" type="button" data-cal-new-date="${state.calendarSelected}"><svg class="icon" aria-hidden="true"><use href="#i-calendar-plus"/></svg>${t("ui.calendar.new-event")}</button></div>`;
  }
  const groups = new Map();
  for (const event of occurrences) {
    if (!groups.has(event.occurrenceDate)) groups.set(event.occurrenceDate, []);
    groups.get(event.occurrenceDate).push(event);
  }
  let html = `<div class="cal-agenda-main"><header><h2>${state.calendarSearch ? esc(t("ui.calendar.results-for-query", { query: state.calendarSearch })) : t("ui.calendar.upcoming-schedule")}</h2><span>${esc(tn("ui.calendar.event-count", occurrences.length, { count: occurrences.length }))}</span></header>`;
  for (const [day, events] of groups) {
    const date = calendarDateFromKey(day);
    html += `<section class="cal-agenda-day"><div class="cal-agenda-day-head"><strong>${date.toLocaleDateString(currentLocale(), { weekday: "long", timeZone: "UTC" })}</strong><span>${date.toLocaleDateString(currentLocale(), { month: "long", day: "numeric", year: "numeric", timeZone: "UTC" })}</span></div>`;
    html += events.map((event) => `<button class="cal-agenda-row" type="button" data-edit-event="${esc(event.id)}" data-cal-occurrence="${esc(event.occurrenceDate)}" style="--ev:${calendarColorFor(event)}">
      <span class="cal-agenda-time">${event.allDay ? t("ui.calendar.all-day") : `${esc(event.start)}<small>${esc(event.end)}</small>`}</span>
      <span class="cal-agenda-bar"></span>
      <span class="cal-agenda-copy"><strong>${esc(event.title)}</strong><span>${event.where ? `<svg class="icon" aria-hidden="true"><use href="#i-location"/></svg>${esc(event.where)}` : ""}${event.calendarName ? `<em>${esc(event.calendarName)}</em>` : ""}${event.attendees ? `<em>${event.attendees} attendee${event.attendees === 1 ? "" : "s"}</em>` : ""}</span></span>
      ${event.invited ? `<span class="cal-rsvp-chip is-${esc(event.myStatus || "needs-action")}">${esc(event.myStatus === "accepted" ? t("ui.events.accepted") : event.myStatus === "declined" ? t("ui.events.declined") : event.myStatus === "tentative" ? t("ui.calendar.tentative") : t("ui.calendar.respond"))}</span>` : ""}
      ${event.recurring ? '<svg class="icon cal-agenda-repeat" aria-label="${esc(t("ui.calendar.recurring"))}"><use href="#i-repeat"/></svg>' : ""}
    </button>`).join("");
    html += "</section>";
  }
  html += "</div>";
  return html;
}

function renderCalendarAgenda() {
  if (!agendaList) return;
  const selected = state.calendarSelected;
  const events = calendarOccurrences(selected, selected);
  const date = calendarDateFromKey(selected);
  if (agendaDate) agendaDate.textContent = date.toLocaleDateString(currentLocale(), { weekday: "long", month: "long", day: "numeric", timeZone: "UTC" });
  if (agendaCount) agendaCount.textContent = tn("ui.calendar.event-count", events.length, { count: events.length });
  const upcoming = calendarOccurrences(addDaysToKey(selected, 1), addDaysToKey(selected, 30)).slice(0, 4);
  const eventsHtml = events.length ? events.map((event) => `<button class="agenda-event" style="--ev:${calendarColorFor(event)}" data-edit-event="${esc(event.id)}" data-cal-occurrence="${esc(event.occurrenceDate)}" type="button" title="${esc(t("ui.calendar.edit-event-title", { title: event.title }))}">
      <span class="agenda-bar" aria-hidden="true"></span>
      <div class="agenda-time"><strong>${event.allDay ? t("ui.calendar.all-day") : esc(event.start)}</strong>${event.allDay ? "" : esc(event.end)}</div>
      <div class="agenda-main"><div class="agenda-title">${esc(event.title)}</div><div class="agenda-meta">${event.where ? `<span><svg class="icon" aria-hidden="true"><use href="#i-location"/></svg>${esc(event.where)}</span>` : ""}<span><svg class="icon" aria-hidden="true"><use href="#i-people"/></svg>${event.attendees || 0}</span>${event.invited ? `<span class="cal-rsvp-chip is-${esc(event.myStatus || "needs-action")}">${esc(event.myStatus || t("ui.calendar.respond"))}</span>` : ""}</div></div>
      <svg class="icon agenda-edit-icon" aria-hidden="true"><use href="#i-chevron-right"/></svg>
    </button>`).join("") : `<div class="cal-empty"><svg class="icon" aria-hidden="true"><use href="#i-calendar"/></svg><strong>${t("ui.calendar.no-events")}</strong><span>${t("ui.calendar.this-day-is-clear")}</span><button class="link-btn" type="button" data-cal-new-date="${selected}">${t("ui.calendar.add-an-event")}</button></div>`;
  const upcomingHtml = upcoming.length ? `<div class="agenda-upcoming"><div class="agenda-upcoming-head">${t("ui.calendar.coming-up")}</div>${upcoming.map((event) => {
    const eventDate = calendarDateFromKey(event.occurrenceDate);
    return `<button class="upcoming-item" style="--ev:${calendarColorFor(event)}" type="button" data-edit-event="${esc(event.id)}" data-cal-occurrence="${esc(event.occurrenceDate)}">
      <span class="upcoming-date">${eventDate.toLocaleDateString(currentLocale(), { weekday: "short", month: "short", day: "numeric", timeZone: "UTC" })}</span>
      <div class="upcoming-main"><div class="agenda-title">${esc(event.title)}</div><div class="upcoming-meta">${event.allDay ? t("ui.calendar.all-day") : esc(event.start)} · ${esc(event.where || t("ui.calendar.no-location"))}</div></div>
    </button>`;
  }).join("")}</div>` : "";
  agendaList.innerHTML = eventsHtml + upcomingHtml;
}

function selectCalendarDate(key, navigate = true) {
  if (!key) return;
  state.calendarSelected = key;
  const date = calendarDateFromKey(key);
  if (navigate) {
    state.calendarYear = date.getUTCFullYear();
    state.calendarMonth = date.getUTCMonth();
  }
  state.calendarMiniYear = date.getUTCFullYear();
  state.calendarMiniMonth = date.getUTCMonth();
  renderCalendar();
}

function shiftCalendarPeriod(delta) {
  if (state.calendarView === "month" || state.calendarView === "split") {
    const next = new Date(Date.UTC(state.calendarYear, state.calendarMonth + delta, 1, 12));
    state.calendarYear = next.getUTCFullYear();
    state.calendarMonth = next.getUTCMonth();
    const today = new Date();
    state.calendarSelected = today.getMonth() === state.calendarMonth && today.getFullYear() === state.calendarYear
      ? dateKey(today)
      : utcDateKey(new Date(Date.UTC(state.calendarYear, state.calendarMonth, 1, 12)));
  } else if (state.calendarView === "week" || state.calendarView === "workweek") {
    state.calendarSelected = addDaysToKey(state.calendarSelected, delta * 7);
    const date = calendarDateFromKey(state.calendarSelected);
    state.calendarYear = date.getUTCFullYear();
    state.calendarMonth = date.getUTCMonth();
  } else if (state.calendarView === "day") {
    state.calendarSelected = addDaysToKey(state.calendarSelected, delta);
    const date = calendarDateFromKey(state.calendarSelected);
    state.calendarYear = date.getUTCFullYear();
    state.calendarMonth = date.getUTCMonth();
  } else {
    state.calendarSelected = addDaysToKey(state.calendarSelected, delta * 31);
    const date = calendarDateFromKey(state.calendarSelected);
    state.calendarYear = date.getUTCFullYear();
    state.calendarMonth = date.getUTCMonth();
  }
  renderCalendar();
}

function shiftMonth(delta) { shiftCalendarPeriod(delta); }

function setCalendarView(view) {
  state.calendarView = view;
  try { localStorage.setItem("a8m.calendar.view", view); } catch {}
  renderCalendar();
}

let calendarEditingId = null;
let calendarEditingPayload = null;

function calendarTimezoneOptions(selected) {
  let zones = [];
  try { zones = Intl.supportedValuesOf("timeZone"); } catch {}
  if (!Array.isArray(zones) || !zones.length) {
    zones = ["UTC", "Africa/Lagos", "Africa/Cairo", "Africa/Johannesburg", "America/New_York", "America/Chicago",
      "America/Denver", "America/Los_Angeles", "America/Sao_Paulo", "America/Mexico_City", "Asia/Dubai",
      "Asia/Kolkata", "Asia/Singapore", "Asia/Tokyo", "Asia/Shanghai", "Australia/Sydney", "Europe/London",
      "Europe/Paris", "Europe/Berlin", "Europe/Madrid", "Europe/Rome", "Europe/Amsterdam", "Europe/Warsaw",
      "Europe/Istanbul", "Pacific/Auckland"];
  }
  if (!zones.includes("UTC")) zones.unshift("UTC");
  if (selected && !zones.includes(selected)) zones.push(selected);
  zones.sort((a, b) => a.localeCompare(b));
  return zones.map((zone) => `<option value="${esc(zone)}"${zone === selected ? " selected" : ""}>${esc(zone.replace(/_/g, " "))}</option>`).join("");
}

function calendarRuleForForm(rule) {
  const parsed = parseCalendarRule(rule);
  if (!parsed.freq) return { value: "", until: "" };
  if (parsed.freq === "DAILY") return { value: "daily", until: parsed.until };
  if (parsed.freq === "WEEKLY" && parsed.byDay.length === 5 && ["MO", "TU", "WE", "TH", "FR"].every((day) => parsed.byDay.includes(day))) return { value: "weekdays", until: parsed.until };
  if (parsed.freq === "WEEKLY") return { value: "weekly", until: parsed.until };
  if (parsed.freq === "MONTHLY") return { value: "monthly", until: parsed.until };
  if (parsed.freq === "YEARLY") return { value: "yearly", until: parsed.until };
  return { value: "", until: "" };
}

function pollDateKey(value = new Date()) {
  return dateKey(value);
}

function defaultPollSlots() {
  const start = state.calendarSelected || pollDateKey(new Date());
  const next = addDaysToKey(start, 1);
  return [
    { date: start, start: "10:00", end: "11:00" },
    { date: next, start: "14:00", end: "15:00" }
  ];
}

function openCalendarPollDialog() {
  closeMenus();
  state.pollDraftSlots = defaultPollSlots();
  document.getElementById("pollTitle").value = "";
  document.getElementById("pollInvitees").value = "";
  document.getElementById("pollError").hidden = true;
  const zone = state.preferences.timeZone || Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  document.getElementById("pollTimezone").innerHTML = calendarTimezoneOptions(zone);
  renderPollSlots();
  calendarPollOverlay.hidden = false;
  setTimeout(() => document.getElementById("pollTitle").focus(), 40);
}

function renderPollSlots() {
  const holder = document.getElementById("pollSlots");
  if (!holder) return;
  holder.innerHTML = state.pollDraftSlots.map((slot, index) => `<div class="calendar-poll-slot-row">
    <label><span>${t("mail.details.date")}</span><input type="date" data-poll-slot-date="${index}" value="${esc(slot.date)}"></label>
    <label><span>${t("ui.calendar.start")}</span><input type="time" data-poll-slot-start="${index}" value="${esc(slot.start)}"></label>
    <label><span>${t("ui.calendar.end")}</span><input type="time" data-poll-slot-end="${index}" value="${esc(slot.end)}"></label>
    <button class="icon-btn" type="button" data-poll-slot-remove="${index}" aria-label="${esc(t("ui.calendar.remove-time-option"))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button>
  </div>`).join("");
}

function capturePollSlots() {
  const rows = [...document.querySelectorAll("#pollSlots .calendar-poll-slot-row")];
  if (!rows.length) return;
  state.pollDraftSlots = rows.map((row) => ({
    date: row.querySelector("[data-poll-slot-date]")?.value || "",
    start: row.querySelector("[data-poll-slot-start]")?.value || "",
    end: row.querySelector("[data-poll-slot-end]")?.value || ""
  }));
}

async function createCalendarPoll() {
  capturePollSlots();
  const title = document.getElementById("pollTitle").value.trim();
  const invitees = document.getElementById("pollInvitees").value.split(/[,;\s]+/).map((value) => value.trim()).filter(Boolean);
  const timezone = document.getElementById("pollTimezone").value;
  const slots = state.pollDraftSlots.map((slot) => ({ ...slot }));
  const error = document.getElementById("pollError");
  if (!title) { error.textContent = t("ui.calendar.add-a-title-for-the-poll"); error.hidden = false; return; }
  if (!invitees.length) { error.textContent = t("ui.calendar.add-at-least-one-invitee"); error.hidden = false; return; }
  if (slots.some((slot) => !slot.date || !slot.start || !slot.end || slot.end <= slot.start)) {
    error.textContent = t("ui.calendar.each-time-option-needs-a-valid-start-and-end");
    error.hidden = false;
    return;
  }
  const button = document.getElementById("pollCreate");
  button.disabled = true;
  try {
    const data = await api("/api/calendar/polls", {
      method: "POST",
      body: { title, inviteeEmails: invitees, timezone, description: "", slots }
    });
    calendarPollOverlay.hidden = true;
    if (data.poll) state.calendarPolls = [data.poll, ...(state.calendarPolls || [])];
    showToast(t("ui.calendar.meeting-poll-created-and-invitations-sent"));
    if (!calendarPollsOverlay.hidden) renderCalendarPolls();
  } catch (err) {
    error.textContent = err.message || t("ui.calendar.could-not-create-the-poll");
    error.hidden = false;
  } finally { button.disabled = false; }
}

async function openCalendarPolls() {
  calendarPollsOverlay.hidden = false;
  const body = document.getElementById("calendarPollsBody");
  body.innerHTML = `<p class="calendar-polls-empty">${t("ui.calendar.loading-meeting-polls")}</p>`;
  try {
    const data = await api("/api/calendar/polls");
    state.calendarPolls = data.polls || [];
    renderCalendarPolls();
  } catch (error) {
    body.innerHTML = `<p class="calendar-polls-empty">${esc(error.message || t("ui.calendar.could-not-load-meeting-polls"))}</p>`;
  }
}

function pollStatusLabel(status) {
  return status === "scheduled" ? t("shell.scheduled") : status === "closed" ? t("mail.reader.closed") : status === "cancelled" ? t("ui.calendar.cancelled") : t("ui.calendar.collecting-responses");
}

function renderCalendarPolls() {
  const body = document.getElementById("calendarPollsBody");
  if (!body) return;
  const polls = state.calendarPolls || [];
  if (!polls.length) {
    body.innerHTML = `<div class="calendar-polls-empty"><svg class="icon" aria-hidden="true"><use href="#i-clock"/></svg><strong>${t("ui.calendar.no-meeting-polls-yet")}</strong><span>${t("ui.calendar.ask-external-guests-for-availability-then-schedu")}</span><button class="btn-primary" type="button" data-poll-new>${t("ui.calendar.create-a-poll")}</button></div>`;
    return;
  }
  body.innerHTML = polls.map((poll) => {
    const invitees = Array.isArray(poll.invitees) ? poll.invitees : [];
    const responded = invitees.filter((invitee) => invitee.respondedAt).length;
    const slots = Array.isArray(poll.slots) ? poll.slots : [];
    return `<section class="calendar-poll-card">
      <header><div><h3>${esc(poll.title)}</h3><span>${invitees.length} invitee${invitees.length === 1 ? "" : "s"} · ${responded} responded</span></div><span class="calendar-poll-status is-${esc(poll.status)}">${esc(pollStatusLabel(poll.status))}</span></header>
      <div class="calendar-poll-options">
        ${slots.map((slot) => `<div class="calendar-poll-option">
          <div><strong>${esc(slot.date)} · ${esc(slot.start)}–${esc(slot.end)}</strong><span>${Number(slot.yes || 0)} yes · ${Number(slot.maybe || 0)} maybe · ${Number(slot.no || 0)} no</span></div>
          ${poll.status === "open" || poll.status === "closed" ? `<button class="btn-secondary" type="button" data-poll-schedule="${esc(poll.id)}" data-poll-slot="${esc(slot.id)}">${t("ui.calendar.schedule")}</button>` : `<span class="calendar-poll-selected">${poll.selectedSlotId === slot.id ? t("ui.calendar.scheduled-slot") : ""}</span>`}
        </div>`).join("")}
      </div>
      <footer><span>${esc(poll.timezone || "UTC")}</span><div>
        ${poll.status === "open" ? `<button class="link-btn" type="button" data-poll-close="${esc(poll.id)}">${t("ui.calendar.close-poll")}</button>` : ""}
        <button class="link-btn danger-link" type="button" data-poll-delete="${esc(poll.id)}">${t("mail.list.quick.delete")}</button>
      </div></footer>
    </section>`;
  }).join("");
}

async function scheduleCalendarPoll(pollId, slotId) {
  const confirmed = await appConfirm({
    title: t("ui.calendar.schedule-this-time"),
    message: t("ui.calendar.calendar-invitations-will-be-sent-to-every-poll-"),
    confirmLabel: t("ui.calendar.schedule-event")
  });
  if (!confirmed) return;
  try {
    const data = await api(`/api/calendar/polls/${encodeURIComponent(pollId)}/schedule`, {
      method: "POST", body: { slotId }
    });
    calendarPollsOverlay.hidden = true;
    await refreshCalendarData();
    if (data.event) {
      state.calendarSelected = data.event.date;
      openEventDialog(data.event.id, { date: data.event.date });
    }
    showToast(t("ui.calendar.event-scheduled-from-the-poll"));
  } catch (error) { showError(error); }
}

async function closeCalendarPoll(pollId) {
  try {
    await api(`/api/calendar/polls/${encodeURIComponent(pollId)}/close`, { method: "POST", body: {} });
    await openCalendarPolls();
    showToast(t("ui.calendar.poll-closed"));
  } catch (error) { showError(error); }
}

async function deleteCalendarPoll(pollId) {
  if (!(await appConfirm({ title: t("ui.calendar.delete-this-poll"), message: t("ui.calendar.the-signed-guest-links-stop-working"), confirmLabel: t("ui.calendar.delete-poll"), tone: "danger" }))) return;
  try {
    await api(`/api/calendar/polls/${encodeURIComponent(pollId)}`, { method: "DELETE" });
    state.calendarPolls = (state.calendarPolls || []).filter((poll) => poll.id !== pollId);
    renderCalendarPolls();
    showToast(t("ui.calendar.poll-deleted"));
  } catch (error) { showError(error); }
}

function openEventDialog(eventId = null, options = {}) {
  hideNotify();
  closeMenus();
  closeFileContextMenu();
  const event = eventId ? (state.calendarEvents || []).find((item) => item.id === eventId) : null;
  calendarEditingId = event ? event.id : null;
  calendarEditingPayload = event || null;
  state.eventEditingId = calendarEditingId;
  state.eventAttendees = (event?.attendeeList || []).map((attendee) => ({ ...attendee }));
  state.eventAttachments = (event?.attachments || []).map((file) => ({ ...file }));
  state.eventResources = (event?.resourceList || []).map((resource) => ({ ...resource }));
  state.eventCalendarId = event?.calendarId || state.calendarActiveId || "default";
  const requestedDate = options.date || event?.date || "";
  const exception = event?.recurrenceRule ? (event.exceptions || []).find((item) =>
    (requestedDate && (item.recurrenceDate === requestedDate || item.date === requestedDate)) ||
    (!requestedDate && item.recurrenceDate === event.date)) : null;
  const display = exception ? {
    ...event,
    title: exception.title || event.title,
    description: exception.description || "",
    where: exception.location || "",
    date: exception.date,
    start: exception.start,
    end: exception.end,
    allDay: Boolean(exception.allDay),
    timezone: exception.timezone || event.timezone,
    status: exception.status || "confirmed",
    reminderMinutes: exception.reminderMinutes ?? event.reminderMinutes
  } : event;
  state.eventOccurrenceDate = exception?.recurrenceDate || requestedDate || event?.date || "";
  state.eventEditScope = event?.recurrenceRule ? (exception || requestedDate ? "occurrence" : "series") : "series";
  const date = exception?.date || options.date || event?.date || state.calendarSelected || dateKey(new Date());
  if (options.time) {
    const [hour, minute] = String(options.time).split(":").map(Number);
    const end = new Date(0, 0, 0, hour, minute + 30);
    document.getElementById("eventStart").value = `${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}`;
    document.getElementById("eventEnd").value = `${String(end.getHours()).padStart(2, "0")}:${String(end.getMinutes()).padStart(2, "0")}`;
  } else {
    document.getElementById("eventStart").value = display?.start || "10:00";
    document.getElementById("eventEnd").value = display?.end || "10:30";
  }
  document.getElementById("eventDialogEyebrow").textContent = event ? (event.invited ? t("ui.calendar.invitation") : t("ui.calendar.edit-event")) : t("ui.calendar.new-event");
  document.getElementById("eventDialogTitle").textContent = event ? (event.invited ? t("ui.calendar.meeting-invitation") : t("ui.calendar.edit-event")) : options.invite ? t("ui.calendar.invite-people") : t("ui.calendar.schedule-event");
  document.getElementById("eventName").value = display?.title || options.title || "";
  document.getElementById("eventDate").value = date;
  document.getElementById("eventWhere").value = display?.where || "";
  document.getElementById("eventMeetingUrl").value = display?.meetingUrl || "";
  document.getElementById("eventDescription").value = display?.description || "";
  document.getElementById("eventAllDay").checked = Boolean(display?.allDay);
  document.getElementById("eventReminder").value = String(display?.reminderMinutes ?? 15);
  document.getElementById("eventTransparency").value = display?.transparency || "busy";
  document.getElementById("eventColorSelect").value = display?.color || "#0f6cbd";
  document.getElementById("eventColorSelect").style.setProperty("--event-color", display?.color || "#0f6cbd");
  const titleMark = document.getElementById("eventColorMark");
  if (titleMark) titleMark.style.background = display?.color || "#0f6cbd";
  const calendarDot = document.getElementById("eventCalendarDot");
  if (calendarDot) calendarDot.style.background = display?.color || "#0f6cbd";
  const ruleState = calendarRuleForForm(event?.recurrenceRule || "");
  document.getElementById("eventRecurrence").value = ruleState.value;
  document.getElementById("eventUntil").value = ruleState.until || "";
  document.getElementById("eventUntilWrap").hidden = !ruleState.value;
  const scopeWrap = document.getElementById("eventScopeWrap");
  if (scopeWrap) {
    scopeWrap.hidden = !event?.recurrenceRule;
    document.getElementById("eventScope").value = state.eventEditScope;
  }
  const zone = display?.timezone || state.preferences.timeZone || Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  document.getElementById("eventTimezone").innerHTML = calendarTimezoneOptions(zone);
  const editableCalendars = (state.calendars || []).filter((calendar) => calCanEdit(calendar));
  if (!editableCalendars.some((calendar) => calendar.id === state.eventCalendarId)) {
    state.eventCalendarId = editableCalendars[0]?.id || "default";
  }
  document.getElementById("eventCalendarSelect").innerHTML = editableCalendars.map((calendar) => `<option value="${esc(calendar.id)}"${calendar.id === state.eventCalendarId ? " selected" : ""}>${esc(calendar.name)}${calendar.shared ? ` · ${esc(calendar.ownerName || "shared")}` : ""}</option>`).join("");
  const canEdit = !event || (event.canEdit !== false && !event.invited);
  const scopeWrapEditable = document.getElementById("eventScopeWrap");
  if (scopeWrapEditable) scopeWrapEditable.hidden = !event?.recurrenceRule || !canEdit;
  document.getElementById("eventDelete").hidden = !event;
  document.getElementById("eventDelete").textContent = event?.invited && !canEdit ? t("ui.calendar.decline-invitation") :
    (event?.recurrenceRule && state.eventEditScope === "occurrence" ? t("ui.calendar.cancel-this-event") : t("mail.list.quick.delete"));
  document.getElementById("eventSave").disabled = !canEdit;
  document.getElementById("eventAllDay").disabled = !canEdit;
  document.getElementById("eventName").readOnly = !canEdit;
  document.getElementById("eventDescription").readOnly = !canEdit;
  document.getElementById("eventWhere").readOnly = !canEdit;
  document.getElementById("eventMeetingUrl").readOnly = !canEdit;
  document.getElementById("eventDate").disabled = !canEdit;
  document.getElementById("eventStart").disabled = !canEdit;
  document.getElementById("eventEnd").disabled = !canEdit;
  document.getElementById("eventRecurrence").disabled = !canEdit || state.eventEditScope === "occurrence";
  document.getElementById("eventCalendarSelect").disabled = !canEdit;
  document.getElementById("eventColorSelect").disabled = !canEdit;
  state.eventRsvpStatus = event?.myStatus || "needs-action";
  renderEventRsvp();
  renderEventGuestPanel();
  renderEventAttendees();
  renderEventResources();
  if (!Array.isArray(state.calendarResources) || state.calendarResources.length === 0) {
    api("/api/calendar/resources").then((data) => {
      state.calendarResources = data.resources || [];
      renderEventResources();
    }).catch(() => {});
  }
  renderEventAttachments();
  updateEventTimeFields();
  updateEventPreview();
  eventOverlay.hidden = false;
  setTimeout(() => (canEdit ? document.getElementById("eventName") : document.getElementById("eventClose")).focus(), 50);
}

function closeEventDialog() {
  eventOverlay.hidden = true;
  calendarEditingId = null;
  calendarEditingPayload = null;
  state.eventEditingId = null;
  state.eventOccurrenceDate = "";
  state.eventEditScope = "series";
  state.eventAttendees = [];
  state.eventAttachments = [];
  state.eventResources = [];
  const guestPanel = document.getElementById("eventGuestPanel");
  if (guestPanel) { guestPanel.hidden = true; guestPanel.innerHTML = ""; }
  document.getElementById("eventAttendeeSuggest").hidden = true;
}

function updateEventTimeFields() {
  const allDay = document.getElementById("eventAllDay").checked;
  const readOnly = document.getElementById("eventSave").disabled;
  const fields = document.getElementById("eventTimeFields");
  fields.classList.toggle("is-disabled", allDay);
  document.getElementById("eventStart").disabled = allDay || readOnly;
  document.getElementById("eventEnd").disabled = allDay || readOnly;
  document.getElementById("eventUntilWrap").hidden = !document.getElementById("eventRecurrence").value;
}

function renderEventAttendees() {
  const holder = document.getElementById("eventAttendeeChips");
  if (!holder) return;
  const organizer = calendarEditingPayload?.organizer;
  holder.innerHTML = state.eventAttendees.map((attendee, index) => {
    const isOrganizer = attendee.organizer || (organizer && attendee.email.toLowerCase() === organizer.toLowerCase());
    return `<span class="event-attendee-chip${isOrganizer ? " is-organizer" : ""}${attendee.status ? ` is-${esc(attendee.status)}` : ""}" title="${esc(attendee.email)}">
      <span class="event-attendee-avatar" style="--attendee:${colorForString(attendee.email)}">${esc(initialsFrom(attendee.name || attendee.email.split("@")[0]))}</span>
      <span>${esc(attendee.name || attendee.email.split("@")[0])}${isOrganizer ? t("ui.calendar.organizer") : ""}</span>
      ${isOrganizer ? "" : `<button type="button" data-event-attendee-remove="${index}" aria-label="${esc(t("ui.thread-selection-actions.remove-name", { name: attendee.email }))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button>`}
    </span>`;
  }).join("");
  const count = document.getElementById("eventPreviewNote");
  if (count) count.textContent = state.eventAttendees.length ? tn("ui.calendar.attendees-will-be-invited", state.eventAttendees.length, { count: state.eventAttendees.length }) : t("ui.calendar.times-are-shown-in-the-event-time-zone");
  renderEventGuestPanel();
}

function renderEventGuestPanel() {
  const holder = document.getElementById("eventGuestPanel");
  if (!holder) return;
  const event = calendarEditingPayload;
  if (!event || event.invited || event.canEdit === false) {
    holder.hidden = true;
    holder.innerHTML = "";
    return;
  }
  const organizer = String(event.organizer || "").toLowerCase();
  const guests = (state.eventAttendees || []).filter((attendee) => !attendee.organizer &&
    String(attendee.email || "").toLowerCase() !== organizer);
  if (!guests.length) {
    holder.hidden = true;
    holder.innerHTML = "";
    return;
  }
  const sequence = Number(event.sequence || 0);
  const statusOf = (guest) => {
    const value = String(guest.status || "needs-action");
    return ["accepted", "tentative", "declined"].includes(value) ? value : "needs-action";
  };
  const labelFor = (status) => status === "accepted" ? t("ui.events.accepted") : status === "tentative" ? t("ui.mail-home-pulse-search-reports-sticky-no.maybe") : status === "declined" ? t("ui.events.declined") : t("ui.calendar.no-response");
  const counts = { accepted: 0, tentative: 0, declined: 0, "needs-action": 0 };
  guests.forEach((guest) => { counts[statusOf(guest)] += 1; });
  const awaiting = guests.filter((guest) => statusOf(guest) === "needs-action" ||
    Number(guest.lastResponseSequence ?? -1) < sequence);
  const proposals = Array.isArray(event.proposals) ? event.proposals : [];
  const senderEmail = String(event.senderEmail || "").toLowerCase();
  const delegated = senderEmail && senderEmail !== organizer;
  const initials = (guest) => esc(initialsFrom(guest.name || String(guest.email || "?").split("@")[0]));
  holder.hidden = false;
  holder.innerHTML = `<div class="event-guest-head">
      <div><strong>${t("ui.calendar.guest-responses")}</strong><span>${esc(tn("ui.calendar.guest-sequence-summary", guests.length, { count: guests.length, sequence, delegated: delegated ? t("ui.calendar.sent-by-suffix", { name: event.senderName || event.senderEmail }) : "" }))}</span></div>
      ${awaiting.length ? `<button class="link-btn event-resend-btn" type="button" data-event-resend>${esc(tn("ui.calendar.resend-to-waiting", awaiting.length, { count: awaiting.length }))}</button>` : `<span class="event-guest-complete"><svg class="icon" aria-hidden="true"><use href="#i-shield-check"/></svg>${t("ui.calendar.everyone-responded")}</span>`}
    </div>
    <div class="event-guest-summary">
      ${["accepted", "tentative", "declined", "needs-action"].map((status) => `<span class="event-guest-count is-${status}"><b>${counts[status]}</b>${labelFor(status)}</span>`).join("")}
    </div>
    ${event.rsvpAnalytics ? (() => {
      const analytics = event.rsvpAnalytics;
      const avg = Number(analytics.averageResponseMinutes || 0);
      const avgLabel = avg >= 60 ? `${(avg / 60).toFixed(1)}h` : `${Math.round(avg)}m`;
      return `<div class="event-analytics">
        <div class="event-analytics-head"><strong>${t("ui.calendar.rsvp-analytics")}</strong><span>${analytics.total} guests</span></div>
        <div class="event-analytics-stats">
          <span><b>${Number(analytics.responseRate || 0).toFixed(1)}%</b> ${t("ui.calendar.responded")}</span>
          <span><b>${avg > 0 ? avgLabel : "—"}</b> ${t("ui.calendar.average-response")}</span>
          <span><b>${Number(analytics.delivered || 0)}/${Number(analytics.total || 0)}</b> delivered${analytics.failed ? ` · ${analytics.failed} failed` : ""}</span>
        </div>
        ${(analytics.domains || []).length ? `<details class="event-analytics-domains"><summary>${t("ui.calendar.by-domain")}</summary>${analytics.domains.map((domain) => `<div><span>${esc(domain.domain)}</span><span>${Number(domain.responded || 0)}/${Number(domain.total || 0)} replied · ${Number(domain.delivered || 0)} delivered</span></div>`).join("")}</details>` : ""}
      </div>`;
    })() : ""}
    <div class="event-guest-list">
      ${guests.map((guest) => {
        const status = statusOf(guest);
        const stale = Number(guest.lastResponseSequence ?? -1) >= 0 && Number(guest.lastResponseSequence) < sequence;
        return `<div class="event-guest-row">
          <span class="event-attendee-avatar" style="--attendee:${colorForString(guest.email)}">${initials(guest)}</span>
          <div class="event-guest-copy"><strong>${esc(guest.name || displayNameFromEmail(guest.email))}</strong><span>${esc(guest.email)}</span>
            ${stale ? `<small class="event-guest-stale">${t("ui.calendar.awaiting-response-on-the-updated-time")}</small>` : guest.respondedAt ? `<small>${esc(t("ui.calendar.replied-relative", { time: formatRelativeTime(guest.respondedAt) }))}</small>` : ""}
          </div>
          <span class="event-guest-status is-${status}">${labelFor(status)}</span>
        </div>`;
      }).join("")}
    </div>
    ${(event.resourceList || []).length ? `<div class="event-resource-summary"><svg class="icon" aria-hidden="true"><use href="#i-location"/></svg><span>Booked: ${event.resourceList.map((resource) => esc(resource.name)).join(" · ")}</span></div>` : ""}
    ${proposals.length ? `<div class="event-proposals">
      <div class="event-proposals-head"><strong>${t("ui.calendar.proposed-times")}</strong><span>${esc(tn("ui.calendar.proposals-waiting", proposals.length, { count: proposals.length }))}</span></div>
      ${proposals.map((proposal) => `<div class="event-proposal-row">
        <div class="event-proposal-time"><strong>${esc(proposal.date)} · ${esc(proposal.start)}–${esc(proposal.end)}</strong><span>${esc(proposal.timezone || "")}</span></div>
        <div class="event-proposal-copy"><strong>${esc(proposal.attendeeName || displayNameFromEmail(proposal.attendeeEmail))}</strong><span>${esc(proposal.attendeeEmail)}</span>${proposal.note ? `<small>${esc(proposal.note)}</small>` : ""}</div>
        <div class="event-proposal-actions"><button type="button" class="btn-secondary" data-proposal-decline="${esc(proposal.id)}">${t("ui.calendar.decline")}</button><button type="button" class="btn-primary" data-proposal-accept="${esc(proposal.id)}">${t("ui.calendar.accept")}</button></div>
      </div>`).join("")}
    </div>` : ""}`;
}

async function decideCalendarProposal(proposalId, decision, eventId = "") {
  const id = eventId || calendarEditingId;
  if (!id || !proposalId) return false;
  const action = decision === "accept" ? "accept" : "decline";
  const confirmed = await appConfirm({
    title: action === "accept" ? t("ui.calendar.accept-the-proposed-time") : t("ui.calendar.decline-the-proposed-time"),
    message: action === "accept" ? t("ui.calendar.the-event-will-move-and-updated-invitations-will") : t("ui.calendar.the-original-time-stays-in-place-and-the-guest-w"),
    confirmLabel: action === "accept" ? t("ui.calendar.accept-time") : t("ui.calendar.decline-time"),
    tone: action === "accept" ? undefined : "danger"
  });
  if (!confirmed) return false;
  try {
    const data = await api(`/api/calendar/events/${encodeURIComponent(id)}/proposals/${encodeURIComponent(proposalId)}/${action}`, { method: "POST", body: {} });
    if (data.event) {
      calendarEditingPayload = data.event;
      state.eventAttendees = (data.event.attendeeList || []).map((attendee) => ({ ...attendee }));
      state.eventRsvpStatus = data.event.myStatus || state.eventRsvpStatus;
      const index = state.calendarEvents.findIndex((event) => event.id === id);
      if (index >= 0) state.calendarEvents[index] = data.event;
    }
    renderEventGuestPanel();
    renderEventAttendees();
    renderCalendarProposalDock();
    if (state.task === "calendar") renderCalendar();
    showToast(action === "accept" ? t("ui.calendar.proposed-time-accepted-guests-are-being-notified") : t("ui.calendar.proposed-time-declined"));
    return true;
  } catch (error) { showError(error); return false; }
}

async function resendEventInvites() {
  const id = calendarEditingId;
  if (!id) return;
  const button = document.querySelector("[data-event-resend]");
  if (button) button.disabled = true;
  try {
    const data = await api(`/api/calendar/events/${encodeURIComponent(id)}/resend`, { method: "POST", body: {} });
    if (data.event) {
      calendarEditingPayload = data.event;
      state.eventAttendees = (data.event.attendeeList || []).map((attendee) => ({ ...attendee }));
      const index = state.calendarEvents.findIndex((event) => event.id === id);
      if (index >= 0) state.calendarEvents[index] = data.event;
    }
    renderEventGuestPanel();
    renderEventAttendees();
    showToast(data.resent ? tn("ui.calendar.invitation-resent-to-guests", data.resent, { count: data.resent }) : t("ui.calendar.everyone-has-already-responded"));
  } catch (error) { showError(error); }
  finally { if (button) button.disabled = false; }
}

function renderEventResources() {
  const holder = document.getElementById("eventResourceChips");
  const select = document.getElementById("eventResourceSelect");
  if (!holder || !select) return;
  const locked = document.getElementById("eventSave").disabled;
  const selected = state.eventResources || [];
  holder.innerHTML = selected.length ? selected.map((resource, index) => `<span class="event-resource-chip">
    <svg class="icon" aria-hidden="true"><use href="#i-location"/></svg>
    <span><strong>${esc(resource.name || resource.email)}</strong>${resource.location ? `<small>${esc(resource.location)}</small>` : ""}</span>
    ${locked ? "" : `<button type="button" data-event-resource-remove="${index}" aria-label="${esc(t("ui.thread-selection-actions.remove-name", { name: resource.name || resource.email }))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button>`}
  </span>`).join("") : `<span class="event-resource-empty">${t("ui.calendar.no-room-or-resource-booked")}</span>`;
  const chosen = new Set(selected.map((resource) => resource.id));
  const options = (state.calendarResources || []).filter((resource) => !chosen.has(resource.id));
  select.innerHTML = `<option value="">${options.length ? t("ui.calendar.add-a-room-or-resource") : t("ui.calendar.no-saved-rooms-yet-use")}</option>` + options.map((resource) =>
    `<option value="${esc(resource.id)}">${esc(resource.name)}${resource.location ? ` · ${esc(resource.location)}` : ""}${resource.capacity ? ` · seats ${Number(resource.capacity)}` : ""}</option>`).join("");
  select.disabled = locked || options.length === 0;
}

function addEventResource(resourceId) {
  const resource = (state.calendarResources || []).find((item) => item.id === resourceId);
  if (!resource) return;
  state.eventResources = [...(state.eventResources || []), { ...resource }];
  renderEventResources();
}

function ensureCalendarResourceDialog() {
  let overlay = document.getElementById("calendarResourceOverlay");
  if (overlay) return overlay;
  overlay = document.createElement("div");
  overlay.className = "overlay";
  overlay.id = "calendarResourceOverlay";
  overlay.hidden = true;
  overlay.innerHTML = `<div class="dialog resource-dialog" role="dialog" aria-modal="true" aria-labelledby="calendarResourceTitle">
    <div class="dialog-head"><div><p class="eyebrow">${t("nav.calendar")}</p><h2 id="calendarResourceTitle">${t("ui.calendar.new-room-or-resource")}</h2><p class="dialog-note">${t("ui.calendar.saved-to-your-account-and-ready-the-next-time-yo")}</p></div><button class="icon-btn" type="button" data-resource-close aria-label="${esc(t("common.close"))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button></div>
    <div class="dialog-body">
      <label class="form-field"><span>${t("ui.calendar.name")}</span><input id="calendarResourceName" maxlength="120" placeholder="${esc(t("ui.calendar.e-g-focus-room"))}"></label>
      <div class="field-row">
        <label class="form-field"><span>${t("ui.calendar.type")}</span><select id="calendarResourceKind"><option value="room">${t("ui.calendar.room")}</option><option value="equipment">${t("ui.calendar.equipment")}</option><option value="other">${t("ui.calendar.other")}</option></select></label>
        <label class="form-field"><span>${t("ui.calendar.seats")} <em>${t("ui.calendar.optional")}</em></span><input id="calendarResourceCapacity" type="number" min="0" max="10000" value="0"></label>
      </div>
      <label class="form-field"><span>${t("ui.calendar.location")} <em>${t("ui.calendar.optional")}</em></span><input id="calendarResourceLocation" maxlength="160" placeholder="${esc(t("ui.calendar.e-g-2nd-floor-east-wing"))}"></label>
      <label style="display:flex;gap:6px;align-items:center;font-size:12px;margin:8px 0"><input id="calendarResourceApproval" type="checkbox"> ${t("ui.calendar.require-approval-before-this-resource-is-booked")}</label>
      <label class="form-field" id="calendarResourceApproverWrap" hidden><span>${t("ui.calendar.approver-email")}</span><input id="calendarResourceApprover" type="email" placeholder="${esc(t("ui.calendar.defaults-to-you"))}"></label>
      <div class="mini-section" id="calendarResourceApprovals" hidden></div>
      <p class="resource-dialog-hint">${t("ui.calendar.rooms-and-resources-are-visible-only-in-your-acc")}</p>
      <p class="resource-dialog-error" id="calendarResourceError" hidden></p>
    </div>
    <div class="dialog-foot"><button class="btn-secondary" type="button" data-resource-cancel>${t("tasks.action.cancel")}</button><button class="btn-primary" type="button" id="calendarResourceSave">${t("ui.calendar.add-resource")}</button></div>
  </div>`;
  document.body.appendChild(overlay);
  overlay.addEventListener("click", (event) => {
    if (event.target === overlay || event.target.closest("[data-resource-close], [data-resource-cancel]")) closeCalendarResourceDialog();
  });
  document.getElementById("calendarResourceSave")?.addEventListener("click", saveCalendarResource);
  document.getElementById("calendarResourceApproval")?.addEventListener("change", (event) => {
    const wrap = document.getElementById("calendarResourceApproverWrap");
    if (wrap) wrap.hidden = !event.target.checked;
  });
  document.getElementById("calendarResourceName")?.addEventListener("keydown", (event) => {
    if (event.key === "Enter") { event.preventDefault(); saveCalendarResource(); }
  });
  return overlay;
}

function openCalendarResourceDialog() {
  const overlay = ensureCalendarResourceDialog();
  const error = document.getElementById("calendarResourceError");
  document.getElementById("calendarResourceName").value = "";
  document.getElementById("calendarResourceKind").value = "room";
  document.getElementById("calendarResourceCapacity").value = "0";
  document.getElementById("calendarResourceLocation").value = "";
  const approval = document.getElementById("calendarResourceApproval");
  if (approval) approval.checked = false;
  const approverWrap = document.getElementById("calendarResourceApproverWrap");
  if (approverWrap) approverWrap.hidden = true;
  const approver = document.getElementById("calendarResourceApprover");
  if (approver) approver.value = "";
  if (error) { error.hidden = true; error.textContent = ""; }
  loadCalendarResourceApprovals().catch(() => {});
  overlay.hidden = false;
  setTimeout(() => document.getElementById("calendarResourceName")?.focus(), 40);
}

function closeCalendarResourceDialog() {
  const overlay = document.getElementById("calendarResourceOverlay");
  if (overlay) overlay.hidden = true;
}

async function saveCalendarResource() {
  const name = String(document.getElementById("calendarResourceName")?.value || "").trim();
  const kind = String(document.getElementById("calendarResourceKind")?.value || "room");
  const location = String(document.getElementById("calendarResourceLocation")?.value || "").trim();
  const capacity = Math.max(0, Math.min(10000, Number(document.getElementById("calendarResourceCapacity")?.value) || 0));
  const requiresApproval = Boolean(document.getElementById("calendarResourceApproval")?.checked);
  const approverEmail = String(document.getElementById("calendarResourceApprover")?.value || "").trim();
  const error = document.getElementById("calendarResourceError");
  const button = document.getElementById("calendarResourceSave");
  if (!name) {
    if (error) { error.textContent = t("ui.calendar.give-the-room-or-resource-a-name"); error.hidden = false; }
    return;
  }
  if (button) button.disabled = true;
  try {
    const data = await api("/api/calendar/resources", { method: "POST", body: { name, kind, location, capacity, requiresApproval, approverEmail } });
    if (Array.isArray(data.resources)) state.calendarResources = data.resources;
    if (data.resource) addEventResource(data.resource.id);
    renderEventResources();
    closeCalendarResourceDialog();
    showToast(t("ui.calendar.resource-now-available", { resource: data.resource?.name || name }));
  } catch (err) {
    if (error) { error.textContent = err?.message || t("ui.calendar.could-not-save-the-room-or-resource"); error.hidden = false; }
  } finally {
    if (button) button.disabled = false;
  }
}

async function loadCalendarResourceApprovals() {
  const host = document.getElementById("calendarResourceApprovals");
  if (!host) return;
  const data = await api("/api/calendar/resources/approvals");
  const rows = data.approvals || [];
  host.hidden = rows.length === 0;
  host.innerHTML = rows.length ? `<h3>${t("ui.calendar.pending-room-requests")}</h3>${rows.map((item) => `<div class="detail-row"><span>${esc(item.resourceName)} · ${esc(item.title)}<br><small>${formatDate(item.startsAt, { time: true })} · ${esc(item.organizerName || item.organizerEmail)}</small></span><span style="display:flex;gap:6px"><button class="btn-secondary small" type="button" data-resource-approve="${esc(item.eventId)}|${esc(item.resourceId)}">${t("ui.calendar.approve")}</button><button class="btn-secondary small" type="button" data-resource-deny="${esc(item.eventId)}|${esc(item.resourceId)}">${t("ui.calendar.deny")}</button></span></div>`).join("")}` : "";
  $$("[data-resource-approve], [data-resource-deny]").forEach((button) => button.addEventListener("click", async () => {
    const [eventId, resourceId] = String(button.dataset.resourceApprove || button.dataset.resourceDeny).split("|");
    await api(`/api/calendar/resources/approvals/${encodeURIComponent(eventId)}/${encodeURIComponent(resourceId)}`, { method: "POST", body: { decision: button.dataset.resourceApprove ? "approve" : "deny" } });
    showToast(button.dataset.resourceApprove ? t("ui.calendar.resource-approved") : t("ui.calendar.resource-request-denied"));
    await loadCalendarResourceApprovals();
  }));
}

function addEventAttendee(email, name = "") {
  email = String(email || "").trim().toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { showToast(t("ui.calendar.enter-a-valid-email-address")); return; }
  if (state.eventAttendees.some((attendee) => attendee.email.toLowerCase() === email)) { showToast(t("ui.calendar.that-person-is-already-invited")); return; }
  state.eventAttendees.push({ email, name: name || displayNameFromEmail(email), status: "needs-action" });
  renderEventAttendees();
  updateEventPreview();
}

function renderEventAttendeeSuggest() {
  const input = document.getElementById("eventAttendeeInput");
  const suggest = document.getElementById("eventAttendeeSuggest");
  if (!input || !suggest) return;
  const query = input.value.trim().toLowerCase();
  const people = (state.people || []).filter((person) => {
    if (!person.email) return false;
    if (state.eventAttendees.some((attendee) => attendee.email.toLowerCase() === String(person.email).toLowerCase())) return false;
    return !query || `${person.name} ${person.email}`.toLowerCase().includes(query);
  }).slice(0, 6);
  if (!people.length) { suggest.hidden = true; return; }
  suggest.innerHTML = people.map((person) => `<button type="button" data-event-attendee-add="${esc(person.email)}" data-event-attendee-name="${esc(person.name || "")}"><span class="event-attendee-avatar" style="--attendee:${colorForString(person.email)}">${esc(initialsFrom(person.name || person.email))}</span><span><strong>${esc(person.name || person.email)}</strong><small>${esc(person.email)}</small></span></button>`).join("");
  suggest.hidden = false;
}

function renderEventAttachments() {
  const holder = document.getElementById("eventAttachments");
  if (!holder) return;
  holder.innerHTML = state.eventAttachments.length ? state.eventAttachments.map((file, index) => {
    const office = state.office.ready && file.providerId === "a8m" && officeMetaForName(file.name);
    return `<div class="event-attachment-card"><span class="file-type ${String(file.mime || "").split("/").pop().replace(/[^a-z0-9]/gi, "").slice(0, 5)}">${esc(String(file.name || "FILE").split(".").pop().slice(0, 4).toUpperCase())}</span><div><strong>${esc(file.name)}</strong><span>${esc(formatBytes(file.sizeBytes || 0))}</span></div>${office ? `<button class="icon-btn event-attachment-office" type="button" data-event-office="${esc(file.id)}" aria-label="${esc(t("ui.compose-manager.open-in-office-title", { name: file.name }))}" title="${office.editable ? t("ui.compose-manager.edit-in-office") : t("ui.calendar.view-in-office")}"><svg class="icon" aria-hidden="true"><use href="#i-file"/></svg></button>` : ""}<button class="icon-btn" type="button" data-event-attachment-remove="${index}" aria-label="${esc(t("ui.thread-selection-actions.remove-name", { name: file.name }))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button></div>`;
  }).join("") : `<p class="event-attachments-empty">${t("ui.calendar.no-files-attached-add-a-proposal-agenda-or-deck-")}</p>`;
}

function renderEventAttachmentPicker() {
  const holder = document.getElementById("eventAttachmentPicker");
  if (!holder) return;
  const files = (state.files || []).filter((file) => storageConnected(file.providerId)).slice(0, 40);
  holder.innerHTML = files.length ? files.map((file) => `<button type="button" class="event-attach-pick" data-event-attach-file="${esc(file.id)}"><svg class="icon" aria-hidden="true"><use href="#i-file"/></svg><span><strong>${esc(file.name)}</strong><small>${esc(fileProviderName(file))} · ${esc(formatBytes(file.sizeBytes))}</small></span></button>`).join("") : `<p class="event-attachments-empty">${t("ui.calendar.no-cabinet-files-available")}</p>`;
}

function eventFormRecurrence() {
  const value = document.getElementById("eventRecurrence").value;
  const until = document.getElementById("eventUntil").value;
  const weekday = ["SU", "MO", "TU", "WE", "TH", "FR", "SA"][calendarDateFromKey(document.getElementById("eventDate").value).getUTCDay()];
  let rule = "";
  if (value === "daily") rule = t("ui.calendar.freq-daily");
  else if (value === "weekdays") rule = "FREQ=WEEKLY;BYDAY=MO,TU,WE,TH,FR";
  else if (value === "weekly") rule = `FREQ=WEEKLY;BYDAY=${weekday}`;
  else if (value === "monthly") rule = t("ui.calendar.freq-monthly");
  else if (value === "yearly") rule = t("ui.calendar.freq-yearly");
  if (rule && until) rule += `;UNTIL=${until.replace(/-/g, "")}T235959Z`;
  return rule;
}

function updateEventPreview() {
  const colorInput = document.getElementById("eventColorSelect");
  if (colorInput) {
    const color = colorInput.value;
    colorInput.style.setProperty("--event-color", color);
    const titleMark = document.getElementById("eventColorMark");
    if (titleMark) titleMark.style.background = color;
    const calendarDot = document.getElementById("eventCalendarDot");
    if (calendarDot) calendarDot.style.background = color;
  }
  const grid = document.getElementById("eventPreview");
  if (!grid) return;
  const date = document.getElementById("eventDate").value || state.calendarSelected;
  const start = document.getElementById("eventAllDay").checked ? "00:00" : document.getElementById("eventStart").value || "10:00";
  const end = document.getElementById("eventAllDay").checked ? "23:59" : document.getElementById("eventEnd").value || "10:30";
  const title = document.getElementById("eventName").value.trim() || t("ui.calendar.new-event");
  const color = document.getElementById("eventColorSelect").value;
  const zone = document.getElementById("eventTimezone").value;
  const range = document.getElementById("eventPreviewRange");
  const zoneLabel = document.getElementById("eventPreviewZone");
  if (range) range.textContent = calendarDateFromKey(date).toLocaleDateString(currentLocale(), { weekday: "long", month: "long", day: "numeric", timeZone: "UTC" });
  if (zoneLabel) zoneLabel.textContent = (zone || "UTC").replace(/_/g, " ");
  const events = calendarOccurrences(date, date).filter((event) => event.id !== calendarEditingId);
  const [startHour, startMinute] = start.split(":").map(Number);
  const [endHour, endMinute] = end.split(":").map(Number);
  const top = Math.max(0, (startHour * 60 + startMinute - CAL_HOUR_START * 60) / 60 * CAL_HOUR_HEIGHT);
  const height = Math.max(24, ((endHour * 60 + endMinute) - (startHour * 60 + startMinute)) / 60 * CAL_HOUR_HEIGHT - 2);
  grid.innerHTML = `<div class="event-preview-hours">${Array.from({ length: 9 }, (_, index) => `<span style="top:${index * CAL_HOUR_HEIGHT * 1.4}px">${String(CAL_HOUR_START + index * 2).padStart(2, "0")}:00</span>`).join("")}</div>
    <div class="event-preview-col" style="height:${(CAL_HOUR_END - CAL_HOUR_START) * CAL_HOUR_HEIGHT * 1.4}px">
      <div class="event-preview-lines"></div>
      ${events.slice(0, 4).map((event) => {
        const [hour, minute] = String(event.start).split(":").map(Number);
        const [endH, endM] = String(event.end).split(":").map(Number);
        return `<span class="event-preview-ghost" style="--ev:${calendarColorFor(event)};top:${(hour * 60 + minute - CAL_HOUR_START * 60) / 60 * CAL_HOUR_HEIGHT * 1.4}px;height:${Math.max(20, ((endH * 60 + endM) - (hour * 60 + minute)) / 60 * CAL_HOUR_HEIGHT * 1.4)}px">${esc(event.title)}</span>`;
      }).join("")}
      <span class="event-preview-block" style="--ev:${color};top:${top * 1.4}px;height:${height * 1.4}px"><strong>${esc(title)}</strong><span>${start}–${end}</span></span>
    </div>`;
}

async function saveEvent() {
  const title = document.getElementById("eventName").value.trim();
  const date = document.getElementById("eventDate").value;
  const allDay = document.getElementById("eventAllDay").checked;
  const start = allDay ? "00:00" : document.getElementById("eventStart").value;
  const end = allDay ? "23:59" : document.getElementById("eventEnd").value;
  const where = document.getElementById("eventWhere").value.trim();
  const description = document.getElementById("eventDescription").value;
  const timezone = document.getElementById("eventTimezone").value;
  const color = document.getElementById("eventColorSelect").value;
  const calendarId = document.getElementById("eventCalendarSelect").value;
  const meetingUrl = document.getElementById("eventMeetingUrl").value.trim();
  if (!title) { showToast(t("ui.calendar.add-an-event-title")); document.getElementById("eventName").focus(); return; }
  if (!date) { showToast(t("mail.list.chooseDateAria")); return; }
  if (!allDay && (!start || !end || end <= start)) { showToast(t("ui.calendar.end-time-must-be-after-the-start-time")); return; }
  const occurrenceEdit = Boolean(calendarEditingId && state.eventEditScope === "occurrence" &&
    calendarEditingPayload?.recurrenceRule && state.eventOccurrenceDate);
  const payload = {
    title, date, start, end, allDay, where, description, timezone, color, calendarId,
    meetingUrl, recurrenceRule: eventFormRecurrence(),
    reminderMinutes: Number(document.getElementById("eventReminder").value),
    transparency: document.getElementById("eventTransparency").value,
    attendeeEmails: state.eventAttendees.map((attendee) => attendee.email),
    attendeeNames: Object.fromEntries(state.eventAttendees.map((attendee) => [attendee.email, attendee.name || ""])),
    attachmentIds: state.eventAttachments.map((file) => file.id),
    resourceIds: (state.eventResources || []).map((resource) => resource.id),
    ...(occurrenceEdit ? { scope: "occurrence", occurrenceDate: state.eventOccurrenceDate } : {})
  };
  const button = document.getElementById("eventSave");
  button.disabled = true;
  try {
    const editingId = calendarEditingId;
    const data = await api(editingId ? `/api/calendar/events/${encodeURIComponent(editingId)}` : "/api/calendar/events", {
      method: editingId ? "PATCH" : "POST", body: payload
    });
    const selected = calendarDateFromKey(date);
    state.calendarSelected = date;
    state.calendarYear = selected.getUTCFullYear();
    state.calendarMonth = selected.getUTCMonth();
    const savedEvent = data.event;
    const savedOrganizer = String(savedEvent?.organizer || "").toLowerCase();
    const guestCount = (savedEvent?.attendeeList || state.eventAttendees || []).filter((attendee) =>
      !attendee.organizer && String(attendee.email || "").toLowerCase() !== savedOrganizer).length;
    closeEventDialog();
    await refreshCalendarData();
    if (savedEvent?.id && guestCount > 0) {
      const holdMs = Math.max(5, Number(state.undoSendSeconds) || 8) * 1000;
      showToast(editingId ? t("ui.calendar.updated-invitations-are-queued") : t("ui.calendar.invitations-are-queued"), t("ui.status-bar-quota-pending-sends.undo"), async () => {
        const undo = await api(`/api/calendar/events/${encodeURIComponent(savedEvent.id)}/invitations`, { method: "DELETE" });
        setTimeout(() => showToast(undo?.cancelled ? t("ui.calendar.invitations-cancelled") : t("ui.calendar.invitations-were-already-on-their-way")), 0);
      }, {
        duration: holdMs,
        countdownAt: new Date(Date.now() + holdMs).toISOString(),
        sentMessage: t("ui.calendar.invitations-sent")
      });
    } else {
      showToast(editingId ? t("ui.calendar.event-updated") : t("ui.calendar.event-added-to-calendar"));
    }
    if (occurrenceEdit) state.calendarSelected = date;
    else if (savedEvent?.id) state.calendarSelected = savedEvent.date || date;
    renderCalendar();
  } catch (error) { showError(error); }
  finally { button.disabled = false; }
}

async function deleteCalendarEvent(id) {
  if (!id) return;
  const event = (state.calendarEvents || []).find((item) => item.id === id);
  if (event?.invited && !event.canEdit) {
    await rsvpCalendarEvent("declined");
    return;
  }
  const occurrenceOnly = Boolean(event?.recurrenceRule && state.eventEditScope === "occurrence" && state.eventOccurrenceDate);
  if (!(await appConfirm({
    title: occurrenceOnly ? t("ui.calendar.cancel-this-occurrence") : t("ui.calendar.delete-this-event"),
    message: occurrenceOnly ? t("ui.calendar.only-this-occurrence-will-be-cancelled-the-rest-") :
      event?.recurrenceRule ? t("ui.calendar.the-entire-recurring-series-will-be-removed-invi") : t("ui.calendar.the-event-will-be-removed-and-invitees-receive-a"),
    confirmLabel: occurrenceOnly ? t("ui.calendar.cancel-occurrence") : t("ui.calendar.delete-event"), tone: "danger"
  }))) return;
  try {
    const suffix = occurrenceOnly ? `?scope=occurrence&occurrenceDate=${encodeURIComponent(state.eventOccurrenceDate)}` : "";
    await api(`/api/calendar/events/${encodeURIComponent(id)}${suffix}`, { method: "DELETE" });
    if (!occurrenceOnly) state.calendarEvents = state.calendarEvents.filter((item) => item.id !== id);
    closeEventDialog();
    await refreshCalendarData();
    renderCalendar();
    showToast(occurrenceOnly ? t("ui.calendar.occurrence-cancelled") : t("ui.calendar.event-deleted"));
  } catch (error) { showError(error); }
}

function renderEventRsvp() {
  const holder = document.getElementById("eventRsvp");
  if (!holder) return;
  const event = calendarEditingPayload;
  if (!event?.invited) { holder.hidden = true; holder.innerHTML = ""; return; }
  holder.hidden = false;
  holder.innerHTML = `<div><strong>${t("ui.calendar.going")}</strong><span>${t("ui.calendar.your-response-is-visible-to-the-organizer")}</span></div><div class="event-rsvp-actions">${[["accepted", t("ui.calendar.accept")], ["tentative", t("ui.calendar.tentative")], ["declined", t("ui.calendar.decline")]].map(([value, label]) => `<button type="button" class="event-rsvp-btn is-${value}${state.eventRsvpStatus === value ? " is-selected" : ""}" data-event-rsvp="${value}">${label}</button>`).join("")}</div>
    <details class="event-propose"><summary>${t("ui.calendar.propose-a-new-time")}</summary>
      <form data-event-propose>
        <div class="event-propose-grid">
          <label>${t("mail.details.date")}<input type="date" name="date" value="${esc(event.date || "")}" required></label>
          <label>${t("ui.calendar.start")}<input type="time" name="start" value="${esc(event.start || "")}" required></label>
          <label>${t("ui.calendar.end")}<input type="time" name="end" value="${esc(event.end || "")}" required></label>
          <label>${t("settings.timeZone")}<input type="text" name="timezone" value="${esc(event.timezone || "UTC")}" required></label>
          <label class="event-propose-note">${t("ui.calendar.note")}<textarea name="note" maxlength="500" placeholder="${esc(t("ui.calendar.optional-note-for-the-organizer"))}"></textarea></label>
        </div>
        <button class="btn-secondary" type="submit">${t("ui.calendar.send-proposed-time")}</button>
      </form>
    </details>`;
}

async function proposeCalendarTime(form) {
  const id = calendarEditingId;
  if (!id) return;
  const fields = new FormData(form);
  const button = form.querySelector("button[type=submit]");
  if (button) button.disabled = true;
  try {
    const data = await api(`/api/calendar/events/${encodeURIComponent(id)}/counter`, {
      method: "POST",
      body: {
        date: fields.get("date"), start: fields.get("start"), end: fields.get("end"),
        timezone: fields.get("timezone"), note: fields.get("note"),
        occurrenceDate: state.eventOccurrenceDate || ""
      }
    });
    if (data.event) {
      calendarEditingPayload = data.event;
      state.eventAttendees = (data.event.attendeeList || []).map((attendee) => ({ ...attendee }));
      state.eventRsvpStatus = data.event.myStatus || state.eventRsvpStatus;
      const index = state.calendarEvents.findIndex((event) => event.id === id);
      if (index >= 0) state.calendarEvents[index] = data.event;
    }
    renderEventRsvp();
    renderEventGuestPanel();
    showToast(t("ui.calendar.your-proposed-time-was-sent-to-the-organizer"));
  } catch (error) { showError(error); }
  finally { if (button) button.disabled = false; }
}

async function rsvpCalendarEvent(status) {
  const id = calendarEditingId;
  if (!id) return;
  try {
    const data = await api(`/api/calendar/events/${encodeURIComponent(id)}/rsvp`, { method: "POST", body: { status } });
    state.eventRsvpStatus = status;
    if (data.event) {
      const index = state.calendarEvents.findIndex((event) => event.id === id);
      if (index >= 0) state.calendarEvents[index] = data.event;
      calendarEditingPayload = data.event;
    }
    renderEventRsvp();
    await refreshCalendarData();
    renderCalendar();
    showToast(status === "accepted" ? t("ui.calendar.invitation-accepted") : t(status === "declined" ? "ui.calendar.invitation-declined" : "ui.calendar.marked-tentative"));
  } catch (error) { showError(error); }
}

async function refreshCalendarData() {
  try {
    const data = await api("/api/calendar/events");
    state.calendarEvents = data.events || [];
    state.calendars = data.calendars || state.calendars;
    state.calendarSubscriptions = data.subscriptions || state.calendarSubscriptions;
    if (data.resources) state.calendarResources = data.resources;
    if (data.addressBooks) state.addressBooks = data.addressBooks;
    if (!state.calendars.some((calendar) => calendar.id === state.calendarActiveId)) {
      state.calendarActiveId = state.calendars.find((calendar) => calendar.isDefault)?.id || state.calendars[0]?.id || "default";
    }
    renderCalendarProposalDock();
    renderReminderStack();
    if (state.task === "calendar") renderCalendar();
    return data;
  } catch (error) {
    return null;
  }
}

function startCalendarRealtime() {
  // EventSource cannot attach the delegated-session header. A delegated window
  // keeps the 60-second polling fallback, but must never subscribe to the
  // primary mailbox's calendar stream.
  if (!state.calendarRealtime && !state.delegatedMode && typeof EventSource !== "undefined" &&
      (state.capabilities || []).includes("calendar-realtime")) {
    try {
      const source = new EventSource("/api/calendar/stream");
      state.calendarRealtime = source;
      source.addEventListener("calendar", () => {
        clearTimeout(state.calendarRefreshTimer);
        state.calendarRefreshTimer = setTimeout(() => { refreshCalendarData().catch(() => {}); }, 300);
      });
    } catch {}
  }
  if (!state.calendarPollTimer) {
    state.calendarPollTimer = setInterval(() => {
      if (document.visibilityState === "visible" && state.user) refreshCalendarData().catch(() => {});
    }, 60000);
  }
}

function applyCalendarPayload(data) {
  if (!data) return;
  if (data.calendars) state.calendars = data.calendars;
  if (data.events || data.calendarEvents) state.calendarEvents = data.events || data.calendarEvents || [];
  if (data.subscriptions) state.calendarSubscriptions = data.subscriptions;
  if (data.resources) state.calendarResources = data.resources;
  if (!state.calendars.some((calendar) => calendar.id === state.calendarActiveId)) {
    state.calendarActiveId = state.calendars.find((calendar) => calendar.isDefault)?.id || state.calendars[0]?.id || "default";
  }
  renderCalendarProposalDock();
  renderCalendar();
}

function calendarDraftColor(selected) {
  return CAL_COLORS.map((color) => `<button type="button" class="cal-color-choice${color === selected ? " is-active" : ""}" style="--swatch:${color}" data-cal-color-choice="${color}" aria-label="${esc(t("ui.calendar.use-colour", { colour: color }))}"></button>`).join("");
}

const BOOKING_WEEKDAYS = [[1, t("ui.calendar.mon")], [2, t("ui.calendar.tue")], [3, t("ui.calendar.wed")], [4, t("ui.calendar.thu")], [5, t("ui.calendar.fri")], [6, t("ui.calendar.sat")], [0, t("ui.calendar.sun")]];
let bookingTimezoneCache = "";

function bookingTimezoneOptions(selected) {
  if (!bookingTimezoneCache) {
    let zones = [];
    try { zones = Intl.supportedValuesOf("timeZone"); } catch {}
    if (!Array.isArray(zones) || !zones.length) {
      zones = ["UTC", "Africa/Lagos", "Africa/Cairo", "Africa/Johannesburg", "America/New_York", "America/Chicago",
        "America/Denver", "America/Los_Angeles", "America/Sao_Paulo", "America/Mexico_City", "Asia/Dubai",
        "Asia/Kolkata", "Asia/Singapore", "Asia/Tokyo", "Asia/Shanghai", "Australia/Sydney", "Europe/London",
        "Europe/Paris", "Europe/Berlin", "Europe/Madrid", "Europe/Rome", "Europe/Amsterdam", "Europe/Warsaw",
        "Europe/Istanbul", "Pacific/Auckland"];
    }
    if (!zones.includes("UTC")) zones.unshift("UTC");
    zones.sort((a, b) => a.localeCompare(b));
    bookingTimezoneCache = zones.map((zone) => `<option value="${esc(zone)}">${esc(zone.replace(/_/g, " "))}</option>`).join("");
  }
  return bookingTimezoneCache;
}

function fillBookingTimezoneSelect(selected) {
  const select = document.getElementById("bookingPageTimezone");
  if (!select) return;
  if (!select.options.length) select.innerHTML = bookingTimezoneOptions(selected || currentTimeZone());
  const zone = selected || select.value || currentTimeZone();
  if (zone && ![...select.options].some((option) => option.value === zone)) {
    select.insertAdjacentHTML("afterbegin", `<option value="${esc(zone)}">${esc(zone.replace(/_/g, " "))}</option>`);
  }
  select.value = zone;
}

function bookingWeekdayButtons(selected = [1, 2, 3, 4, 5]) {
  return BOOKING_WEEKDAYS.map(([value, label]) => `<button class="booking-weekday${selected.includes(value) ? " is-active" : ""}" type="button" data-booking-weekday="${value}" aria-pressed="${selected.includes(value) ? "true" : "false"}">${label}</button>`).join("");
}

function bookingWeekdayValues() {
  return $$("#bookingWeekdays [data-booking-weekday]")
    .filter((button) => button.getAttribute("aria-pressed") === "true")
    .map((button) => Number(button.getAttribute("data-booking-weekday")));
}

function updateBookingUrlPreview() {
  const slug = (document.getElementById("bookingPageSlug")?.value || "").trim();
  const title = (document.getElementById("bookingPageTitle")?.value || "").trim();
  const derived = slug || title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 64);
  const node = document.getElementById("bookingUrlPreview");
  if (node) node.textContent = `${location.origin}/book/${derived || "your-page"}`;
}

function ensureBookingPagesOverlay() {
  let overlay = document.getElementById("bookingPagesOverlay");
  if (overlay) return overlay;
  document.body.insertAdjacentHTML("beforeend", `<div class="overlay booking-pages-overlay" id="bookingPagesOverlay" hidden>
    <div class="dialog booking-pages-dialog" role="dialog" aria-modal="true" aria-labelledby="bookingPagesTitle">
      <div class="dialog-head"><div class="dialog-title-wrap"><span class="dialog-icon"><svg class="icon" aria-hidden="true"><use href="#i-calendar"/></svg></span><div><p class="eyebrow" id="bookingPagesEyebrow">${t("ui.calendar.booking-pages")}</p><h2 id="bookingPagesTitle">${t("ui.calendar.public-scheduling-links")}</h2><p class="dialog-note">${t("ui.calendar.share-a-link-and-let-people-book-an-open-time-on")}</p></div></div><button class="icon-btn" id="bookingPagesClose" type="button" aria-label="${esc(t("ui.calendar.close-booking-pages"))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button></div>
      <div class="dialog-body booking-pages-body">
        <section class="booking-pages-list-section">
          <div class="booking-section-head"><div><h3>${t("ui.calendar.your-pages")}</h3><p>${t("ui.calendar.active-links-bookings-and-availability")}</p></div><span class="booking-count" id="bookingPageCount"></span></div>
          <div class="booking-pages-list" id="bookingPagesList"><div class="settings-note">${t("ui.calendar.loading-booking-pages")}</div></div>
        </section>
        <section class="booking-editor-card">
          <div class="booking-editor-head"><div><p class="eyebrow" id="bookingFormEyebrow">${t("ui.calendar.new-page")}</p><h3 id="bookingFormTitle">${t("ui.calendar.create-a-booking-page")}</h3><p>${t("ui.calendar.set-the-window-guests-can-book-inside")}</p></div><button class="btn-secondary small" id="bookingFormReset" type="button">${t("ui.calendar.reset")}</button></div>
          <form id="bookingPageForm">
            <div class="field-row">
              <label class="field"><span>${t("tasks.field.title")}</span><input id="bookingPageTitle" required maxlength="120" placeholder="${esc(t("ui.calendar.meet-with-avery"))}" autocomplete="off"></label>
              <label class="field"><span>${t("ui.calendar.slug")}</span><input id="bookingPageSlug" maxlength="64" placeholder="meet-avery" autocomplete="off" spellcheck="false"></label>
            </div>
            <p class="booking-url-preview"><svg class="icon" aria-hidden="true"><use href="#i-link"/></svg><span id="bookingUrlPreview"></span></p>
            <div class="field-row">
              <label class="field"><span>${t("ui.calendar.duration")}</span><select id="bookingPageDuration">${[15, 30, 45, 60, 90].map((minutes) => `<option value="${minutes}"${minutes === 30 ? " selected" : ""}>${esc(tn("ui.calendar.minutes-count", minutes, { count: minutes }))}</option>`).join("")}</select></label>
              <label class="field"><span>${t("settings.timeZone")}</span><select id="bookingPageTimezone"></select></label>
            </div>
            <div class="field-row">
              <label class="field"><span>${t("ui.calendar.available-from")}</span><input id="bookingPageStart" type="time" step="3600" value="09:00"></label>
              <label class="field"><span>${t("ui.calendar.available-until")}</span><input id="bookingPageEnd" type="time" step="3600" value="17:00"></label>
              <div class="field booking-weekdays-field"><span>${t("ui.calendar.days")}</span><div class="booking-weekdays" id="bookingWeekdays">${bookingWeekdayButtons()}</div></div>
            </div>
            <div class="setting-list booking-toggle-row"><div class="setting-row"><div class="setting-copy"><strong>${t("ui.calendar.round-robin")}</strong><span>${t("ui.calendar.distribute-bookings-across-every-available-team-")}</span></div><button class="switch" id="bookingPageRoundRobin" type="button" role="switch" aria-checked="false" aria-label="${esc(t("ui.calendar.round-robin-across-team-members"))}"><span></span></button></div></div>
            <p class="booking-form-error" id="bookingFormError" hidden></p>
            <div class="booking-form-actions"><button class="btn-primary" id="bookingPageSave" type="submit">${t("ui.calendar.create-page")}</button></div>
          </form>
        </section>
      </div>
    </div>
  </div>`);
  overlay = document.getElementById("bookingPagesOverlay");
  overlay.addEventListener("click", (event) => { if (event.target === overlay) overlay.hidden = true; });
  document.getElementById("bookingPagesClose").addEventListener("click", () => { overlay.hidden = true; });
  document.getElementById("bookingFormReset").addEventListener("click", () => resetBookingForm());
  document.getElementById("bookingPageForm").addEventListener("submit", (event) => {
    event.preventDefault();
    createBookingPage().catch(showError);
  });
  document.getElementById("bookingPageTitle")?.addEventListener("input", updateBookingUrlPreview);
  document.getElementById("bookingPageSlug")?.addEventListener("input", updateBookingUrlPreview);
  document.getElementById("bookingWeekdays")?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-booking-weekday]");
    if (!button) return;
    const active = button.getAttribute("aria-pressed") === "true";
    button.setAttribute("aria-pressed", active ? "false" : "true");
    button.classList.toggle("is-active", !active);
  });
  document.getElementById("bookingPageRoundRobin")?.addEventListener("click", () => {
    const toggle = document.getElementById("bookingPageRoundRobin");
    const active = toggle.getAttribute("aria-checked") === "true";
    toggle.setAttribute("aria-checked", active ? "false" : "true");
  });
  return overlay;
}

async function openBookingPages() {
  const overlay = ensureBookingPagesOverlay();
  fillBookingTimezoneSelect(currentTimeZone());
  resetBookingForm();
  overlay.hidden = false;
  await refreshBookingPages();
}

function bookingPageMeta(page) {
  const days = Array.isArray(page.weekdays) && page.weekdays.length
    ? page.weekdays.map((value) => (BOOKING_WEEKDAYS.find(([day]) => day === value) || [value, "?"])[1]).join(" · ")
    : t("ui.calendar.mon-fri");
  return `${esc(page.durationMinutes || 30)} min · ${esc(page.timezone || "UTC")} · ${esc(days)}${page.roundRobin ? t("ui.calendar.round-robin-suffix") : ""}`;
}

async function refreshBookingPages() {
  const host = document.getElementById("bookingPagesList");
  if (!host) return;
  host.innerHTML = "<div class=\"settings-note\">" + t("ui.calendar.loading-booking-pages") + "</div>";
  const data = await api("/api/booking-pages");
  state.bookingPages = data.pages || [];
  const count = document.getElementById("bookingPageCount");
  if (count) count.textContent = `${state.bookingPages.length} page${state.bookingPages.length === 1 ? "" : "s"}`;
  host.innerHTML = state.bookingPages.length ? state.bookingPages.map((page) => `<article class="booking-page-card${page.active === false ? " is-disabled" : ""}">
      <div class="booking-page-main">
        <span class="booking-page-icon"><svg class="icon" aria-hidden="true"><use href="#i-calendar"/></svg></span>
        <div class="booking-page-copy"><strong>${esc(page.title)}</strong><span>${bookingPageMeta(page)}</span><code>/book/${esc(page.slug)}</code></div>
        <span class="booking-status${page.active === false ? " is-off" : ""}">${page.active === false ? t("ui.account-chrome.disabled") : t("ui.named-signature-library.active")}</span>
      </div>
      <div class="booking-page-actions">
        <button class="btn-secondary small" type="button" data-booking-copy="${esc(page.url)}">${t("ui.calendar.copy-link")}</button>
        <button class="btn-secondary small" type="button" data-booking-edit="${esc(page.id)}">${t("tasks.detail.edit")}</button>
        <button class="btn-secondary small" type="button" data-booking-bookings="${esc(page.id)}">${t("ui.calendar.bookings")}</button>
        <button class="btn-secondary small" type="button" data-booking-disable="${esc(page.id)}">${page.active === false ? t("ui.calendar.enable") : t("ui.calendar.disable")}</button>
      </div>
    </article>`).join("") : "<div class=\"booking-empty\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#i-calendar\"/></svg><strong>" + t("ui.calendar.no-booking-pages-yet") + "</strong><span>" + t("ui.calendar.create-one-below-and-share-the-link-with-your-gu") + "</span></div>";
  $$("[data-booking-copy]", host).forEach((button) => button.addEventListener("click", async () => {
    const url = location.origin + button.dataset.bookingCopy;
    try { await navigator.clipboard.writeText(url); showToast(t("ui.calendar.booking-link-copied")); }
    catch { showToast(url); }
  }));
  $$("[data-booking-edit]", host).forEach((button) => button.addEventListener("click", () => editBookingPage(button.dataset.bookingEdit)));
  $$("[data-booking-bookings]", host).forEach((button) => button.addEventListener("click", () => openBookingList(button.dataset.bookingBookings)));
  $$("[data-booking-disable]", host).forEach((button) => button.addEventListener("click", () => toggleBookingPage(button.dataset.bookingDisable)));
}

function resetBookingForm() {
  state.bookingEditId = "";
  const form = document.getElementById("bookingPageForm");
  form?.reset();
  const set = (id, value) => { const node = document.getElementById(id); if (node) node.value = value; };
  set("bookingPageTitle", "");
  set("bookingPageSlug", "");
  set("bookingPageDuration", "30");
  fillBookingTimezoneSelect(currentTimeZone());
  set("bookingPageStart", "09:00");
  set("bookingPageEnd", "17:00");
  const days = document.getElementById("bookingWeekdays");
  if (days) days.innerHTML = bookingWeekdayButtons();
  document.getElementById("bookingPageRoundRobin")?.setAttribute("aria-checked", "false");
  const error = document.getElementById("bookingFormError");
  if (error) { error.hidden = true; error.textContent = ""; }
  const save = document.getElementById("bookingPageSave");
  if (save) save.textContent = t("ui.calendar.create-page");
  const eyebrow = document.getElementById("bookingFormEyebrow");
  if (eyebrow) eyebrow.textContent = t("ui.calendar.new-page");
  const title = document.getElementById("bookingFormTitle");
  if (title) title.textContent = t("ui.calendar.create-a-booking-page");
  updateBookingUrlPreview();
}

function editBookingPage(id) {
  const page = state.bookingPages.find((item) => item.id === id);
  if (!page) return;
  state.bookingEditId = page.id;
  const set = (field, value) => { const node = document.getElementById(field); if (node) node.value = value; };
  set("bookingPageTitle", page.title || "");
  set("bookingPageSlug", page.slug || "");
  set("bookingPageDuration", String(Number(page.durationMinutes) || 30));
  fillBookingTimezoneSelect(page.timezone || currentTimeZone());
  const startHour = Number(page.workingStartHour ?? 9);
  const endHour = Number(page.workingEndHour ?? 17);
  set("bookingPageStart", `${String(startHour).padStart(2, "0")}:00`);
  set("bookingPageEnd", `${String(endHour).padStart(2, "0")}:00`);
  const selectedDays = Array.isArray(page.weekdays) && page.weekdays.length ? page.weekdays : [1, 2, 3, 4, 5];
  const daysHost = document.getElementById("bookingWeekdays");
  if (daysHost) daysHost.innerHTML = bookingWeekdayButtons(selectedDays);
  document.getElementById("bookingPageRoundRobin")?.setAttribute("aria-checked", page.roundRobin ? "true" : "false");
  const error = document.getElementById("bookingFormError");
  if (error) { error.hidden = true; error.textContent = ""; }
  const save = document.getElementById("bookingPageSave");
  if (save) save.textContent = t("ui.calendar.save-page");
  const eyebrow = document.getElementById("bookingFormEyebrow");
  if (eyebrow) eyebrow.textContent = t("ui.calendar.editing-page");
  const title = document.getElementById("bookingFormTitle");
  if (title) title.textContent = t("ui.calendar.update-this-booking-page");
  updateBookingUrlPreview();
  document.querySelector(".booking-editor-card")?.scrollIntoView({ block: "nearest", behavior: "smooth" });
}

async function openBookingList(id) {
  const page = state.bookingPages.find((item) => item.id === id);
  const data = await api(`/api/booking-pages/${encodeURIComponent(id)}/bookings`);
  const rows = data.bookings || [];
  const host = document.getElementById("bookingPagesList");
  if (!host) return;
  host.innerHTML = `<div class="booking-list-head"><div><strong>${esc(page?.title || t("ui.calendar.bookings"))}</strong><span>${rows.length} booking${rows.length === 1 ? "" : "s"}</span></div><button class="btn-secondary small" type="button" id="bookingListBack">${t("ui.calendar.back-to-pages")}</button></div>
    <div class="booking-list">${rows.map((booking) => `<div class="booking-list-row">
      <span class="booking-list-avatar">${esc(initialsFrom(booking.bookerName, booking.bookerEmail))}</span>
      <div class="booking-list-copy"><strong>${esc(booking.bookerName)}</strong><span>${esc(booking.bookerEmail)}</span></div>
      <span class="booking-list-when">${esc(formatDate(booking.startAt, { time: true }))} → ${esc(formatDate(booking.endAt, { time: true }))}</span>
      <span class="booking-status${booking.status === "confirmed" ? "" : " is-off"}">${esc(booking.status)}</span>
      ${booking.status === "confirmed" ? `<button class="btn-secondary small" type="button" data-booking-cancel="${esc(booking.id)}" data-booking-page="${esc(id)}">${t("tasks.action.cancel")}</button>` : ""}
    </div>`).join("") || "<div class=\"booking-empty\"><strong>" + t("ui.calendar.no-bookings-yet") + "</strong><span>" + t("ui.calendar.confirmed-bookings-will-appear-here") + "</span></div>"}</div>`;
  document.getElementById("bookingListBack")?.addEventListener("click", () => refreshBookingPages().catch(showError));
  $$("[data-booking-cancel]").forEach((button) => button.addEventListener("click", async () => {
    if (!(await appConfirm({ title: t("ui.calendar.cancel-booking"), message: t("ui.calendar.the-booker-and-the-calendar-event-will-be-marked"), confirmLabel: t("ui.calendar.cancel-booking-2"), tone: "danger" }))) return;
    await api(`/api/booking-pages/${encodeURIComponent(button.dataset.bookingPage)}/bookings/${encodeURIComponent(button.dataset.bookingCancel)}/cancel`, { method: "POST", body: {} });
    showToast(t("ui.calendar.booking-cancelled"));
    openBookingList(button.dataset.bookingPage).catch(showError);
  }));
}

async function toggleBookingPage(id) {
  const page = state.bookingPages.find((item) => item.id === id);
  if (!page) return;
  if (page.active === false) {
    await api(`/api/booking-pages/${encodeURIComponent(id)}`, { method: "PUT", body: { title: page.title, slug: page.slug, durationMinutes: page.durationMinutes, timezone: page.timezone, workingStartHour: page.workingStartHour, workingEndHour: page.workingEndHour, weekdays: page.weekdays, roundRobin: page.roundRobin, active: true } });
    showToast(t("ui.calendar.booking-page-enabled"));
  } else {
    if (!(await appConfirm({ title: t("ui.calendar.disable-booking-page"), message: t("ui.calendar.the-public-link-stops-accepting-new-bookings-exi"), confirmLabel: t("ui.calendar.disable-page"), tone: "danger" }))) return;
    await api(`/api/booking-pages/${encodeURIComponent(id)}`, { method: "DELETE" });
    showToast(t("ui.calendar.booking-page-disabled"));
  }
  await refreshBookingPages();
}

async function createBookingPage() {
  const title = document.getElementById("bookingPageTitle").value.trim();
  const slug = document.getElementById("bookingPageSlug").value.trim();
  const durationMinutes = Number(document.getElementById("bookingPageDuration").value) || 30;
  const timezone = document.getElementById("bookingPageTimezone").value || "UTC";
  const start = document.getElementById("bookingPageStart").value;
  const end = document.getElementById("bookingPageEnd").value;
  const weekdays = bookingWeekdayValues();
  const roundRobin = document.getElementById("bookingPageRoundRobin").getAttribute("aria-checked") === "true";
  const error = document.getElementById("bookingFormError");
  const fail = (message) => {
    if (error) { error.hidden = false; error.textContent = message; }
    return false;
  };
  if (!title) return fail(t("ui.calendar.give-the-page-a-title"));
  if (!start || !end) return fail(t("ui.calendar.choose-an-availability-window"));
  const [startHour, startMinute] = start.split(":").map(Number);
  const [endHour, endMinute] = end.split(":").map(Number);
  if (startMinute || endMinute) return fail(t("ui.calendar.availability-must-start-and-end-on-the-hour"));
  if (endHour <= startHour) return fail(t("ui.calendar.the-end-of-the-window-must-be-after-the-start"));
  if (!weekdays.length) return fail(t("ui.calendar.select-at-least-one-available-day"));
  if (error) { error.hidden = true; error.textContent = ""; }
  const body = { title, slug, durationMinutes, timezone, workingStartHour: startHour, workingEndHour: endHour, weekdays, roundRobin };
  const button = document.getElementById("bookingPageSave");
  const original = button ? button.textContent : "";
  if (button) { button.disabled = true; button.textContent = state.bookingEditId ? t("ui.named-signature-library.saving") : t("ui.alt8mail-office.creating"); }
  try {
    if (state.bookingEditId) {
      await api(`/api/booking-pages/${encodeURIComponent(state.bookingEditId)}`, { method: "PUT", body });
      showToast(t("ui.calendar.booking-page-updated"));
    } else {
      await api("/api/booking-pages", { method: "POST", body });
      showToast(t("ui.calendar.booking-page-created"));
    }
    resetBookingForm();
    await refreshBookingPages();
  } catch (error) {
    fail(error.message || t("ui.calendar.the-booking-page-could-not-be-saved"));
  } finally {
    if (button) { button.disabled = false; button.textContent = state.bookingEditId ? t("ui.calendar.save-page") : t("ui.calendar.create-page"); }
  }
}

function openCalendarAdd(tab = "create", calendarId = "") {
  state.calendarAddTab = tab;
  state.calendarEditId = calendarId || state.calendars.find((calendar) => calendar.owned)?.id || "default";
  calendarAddOverlay.hidden = false;
  renderCalendarAdd();
  if (tab === "holidays" && !state.holidayCountries?.length) loadHolidayCatalog();
}

function renderCalendarAdd() {
  const panel = document.getElementById("calendarAddPanel");
  if (!panel) return;
  const tab = state.calendarAddTab || "create";
  document.querySelectorAll("#calendarAddNav [data-cal-add-tab]").forEach((button) => {
    button.classList.toggle("is-active", button.getAttribute("data-cal-add-tab") === tab);
  });
  if (tab === "create") {
    const color = state.calendarDraftCreateColor || CAL_COLORS[0];
    panel.innerHTML = `<div class="cal-add-copy"><h3>${t("ui.calendar.create-blank-calendar")}</h3><p>${t("ui.calendar.this-calendar-is-private-until-you-share-it-or-p")}</p></div>
      <label class="form-field"><span>${t("ui.calendar.calendar-name")}</span><input id="calCreateName" maxlength="80" placeholder="${esc(t("ui.calendar.e-g-product-launches"))}"></label>
      <div class="cal-add-colors"><span>${t("ui.calendar.colour")}</span><div>${calendarDraftColor(color)}<input id="calCreateColor" type="color" value="${color}" aria-label="${esc(t("ui.calendar.custom-calendar-colour"))}"></div></div>
      <div class="cal-add-swatches"><span>${t("ui.calendar.charm")}</span><div>${["📅", "🚀", "💼", "🎯", "📊", "🧭", "🎓", "🌍"].map((charm) => `<button type="button" class="cal-charm${state.calendarCharm === charm ? " is-active" : ""}" data-cal-charm="${charm}">${charm}</button>`).join("")}</div></div>
      <div class="cal-add-foot"><button class="btn-secondary" type="button" data-cal-add-close>${t("ui.calendar.discard")}</button><button class="btn-primary" id="calCreateSave" type="button">${t("ui.calendar.save-calendar")}</button></div>`;
  } else if (tab === "edit") {
    const calendars = (state.calendars || []).filter((calendar) => calendar.owned);
    if (!calendars.some((calendar) => calendar.id === state.calendarEditId)) state.calendarEditId = calendars[0]?.id || "";
    const calendar = calendars.find((item) => item.id === state.calendarEditId);
    panel.innerHTML = `<div class="cal-add-copy"><h3>${t("ui.calendar.edit-my-calendars")}</h3><p>${t("ui.calendar.rename-recolour-share-or-remove-a-calendar-you-o")}</p></div>
      <label class="form-field"><span>${t("ui.calendar.select-a-calendar")}</span><select id="calEditSelect">${calendars.map((item) => `<option value="${esc(item.id)}"${item.id === state.calendarEditId ? " selected" : ""}>${esc(item.name)}</option>`).join("")}</select></label>
      ${calendar ? `<label class="form-field"><span>${t("ui.calendar.calendar-name")}</span><input id="calEditName" maxlength="80" value="${esc(calendar.name)}"></label>
      <div class="cal-add-colors"><span>${t("ui.calendar.colour")}</span><div>${calendarDraftColor(calendar.color)}<input id="calEditColor" type="color" value="${esc(calendar.color)}" aria-label="${esc(t("ui.calendar.custom-calendar-colour"))}"></div></div>
      <div class="cal-edit-actions"><button class="btn-secondary" type="button" data-cal-edit-share="${esc(calendar.id)}"><svg class="icon" aria-hidden="true"><use href="#i-people"/></svg>${t("ui.calendar.share")}</button><button class="btn-secondary" type="button" data-cal-edit-publish="${esc(calendar.id)}"><svg class="icon" aria-hidden="true"><use href="#i-globe"/></svg>${t("ui.calendar.publish")}</button><button class="btn-secondary" type="button" data-cal-edit-export="${esc(calendar.id)}"><svg class="icon" aria-hidden="true"><use href="#i-download"/></svg>${t("ui.calendar.export-ics")}</button><button class="btn-secondary danger-btn" type="button" data-cal-edit-delete="${esc(calendar.id)}">${t("ui.calendar.delete-calendar")}</button></div>
      <div class="cal-add-foot"><span class="cal-add-hint">${calendar.shared ? t("ui.calendar.shared-calendar") : tn("ui.calendar.event-count", calendar.eventCount || 0, { count: calendar.eventCount || 0 })}</span><button class="btn-primary" id="calEditSave" type="button">${t("mail.folders.saveChanges")}</button></div>` : `<p class="cal-add-empty">${t("ui.calendar.you-do-not-own-a-calendar-yet-create-one-first")}</p>`}`;
  } else if (tab === "subscribe") {
    panel.innerHTML = `<div class="cal-add-copy"><h3>${t("ui.calendar.subscribe-from-web")}</h3><p>${t("ui.calendar.paste-a-public-or-secret-icalendar-address-chang")}</p></div>
      <label class="form-field"><span>${t("ui.calendar.calendar-address")}</span><input id="calSubscribeUrl" type="url" placeholder="https://calendar.google.com/calendar/ical/…/basic.ics" spellcheck="false"></label>
      <div class="form-row"><label class="form-field grow"><span>${t("ui.calendar.name")} <small>${t("ui.calendar.optional")}</small></span><input id="calSubscribeName" maxlength="80" placeholder="${esc(t("ui.calendar.team-calendar"))}"></label><label class="form-field"><span>${t("ui.calendar.colour")}</span><input id="calSubscribeColor" type="color" value="#7a4a5c"></label></div>
      <div class="cal-add-polish"><svg class="icon" aria-hidden="true"><use href="#i-shield-check"/></svg><span>${t("ui.calendar.only-https-and-webcal-feeds-are-fetched-private-")}</span></div>
      <div class="cal-add-foot"><button class="btn-secondary" type="button" data-cal-add-close>${t("tasks.action.cancel")}</button><button class="btn-primary" id="calSubscribeImport" type="button"><svg class="icon" aria-hidden="true"><use href="#i-download"/></svg>${t("ui.calendar.import-calendar")}</button></div>`;
  } else if (tab === "upload") {
    panel.innerHTML = `<div class="cal-add-copy"><h3>${t("ui.calendar.upload-from-file")}</h3><p>${t("ui.calendar.import-events-from-an-ics-file-by-choosing-it-he")}</p></div>
      <label class="cal-upload-zone" id="calUploadZone"><input id="calImportFile" type="file" accept=".ics,text/calendar"><span class="cal-upload-art"><svg class="icon" aria-hidden="true"><use href="#i-upload"/></svg></span><strong>${t("ui.calendar.choose-an-ics-file")}</strong><span>${t("ui.calendar.or-drag-it-onto-this-panel")}</span><em id="calImportFileName">${t("ui.calendar.no-file-selected")}</em></label>
      <div class="cal-add-polish"><svg class="icon" aria-hidden="true"><use href="#i-lock"/></svg><span>${t("ui.calendar.imported-calendars-are-private-to-your-account")}</span></div>
      <div class="cal-add-foot"><button class="btn-secondary" type="button" data-cal-add-close>${t("tasks.action.cancel")}</button><button class="btn-primary" id="calImportAdd" type="button" disabled><svg class="icon" aria-hidden="true"><use href="#i-calendar-plus"/></svg>${t("ui.calendar.add-to-my-calendars")}</button></div>`;
  } else if (tab === "holidays") {
    panel.innerHTML = `<div class="cal-add-copy"><h3>${t("ui.calendar.holidays")}</h3><p>${esc(t("ui.calendar.holidays-description", { count: state.holidayCountries?.length || "190+" }))}</p></div>
      <label class="cal-holiday-search"><svg class="icon" aria-hidden="true"><use href="#i-search"/></svg><input id="calHolidayFilter" type="search" placeholder="${esc(t("ui.calendar.filter-countries"))}" autocomplete="off"></label>
      <div class="cal-holiday-list" id="calHolidayList"><div class="cal-add-empty">${state.holidayCountries?.length ? "" : t("ui.calendar.loading-countries")}</div></div>
      <div class="cal-add-foot"><span class="cal-add-hint" id="calHolidayHint">${t("ui.calendar.choose-up-to-five-countries")}</span><button class="btn-primary" id="calHolidayAdd" type="button"><svg class="icon" aria-hidden="true"><use href="#i-globe"/></svg>${t("ui.calendar.add-holiday-calendar")}</button></div>`;
    renderHolidayList();
  } else if (tab === "birthdays") {
    const hasBirthdayCalendar = (state.calendars || []).some((calendar) => calendar.kind === "birthday");
    panel.innerHTML = `<div class="cal-add-copy"><h3>${t("ui.calendar.birthdays")}</h3><p>${t("ui.calendar.keep-track-of-the-people-in-your-address-books-b")}</p></div>
      <div class="cal-birthday-art"><span>🎂</span><div><strong>${esc(tn("ui.calendar.contact-birthdays-found", state.people.filter((person) => person.birthday).length, { count: state.people.filter((person) => person.birthday).length }))}</strong><p>${t("ui.calendar.contacts-without-a-birthday-are-skipped-add-birt")}</p></div></div>
      <label class="compose-check cal-birthday-toggle"><input type="checkbox" id="calBirthdayToggle" ${hasBirthdayCalendar ? "checked" : ""}>${t("ui.calendar.turn-on-the-birthday-calendar")}</label>
      <div class="cal-add-polish"><svg class="icon" aria-hidden="true"><use href="#i-people"/></svg><span>${t("ui.calendar.birthdays-stay-inside-alt8mail-and-are-never-sen")}</span></div>
      <div class="cal-add-foot"><button class="btn-secondary" type="button" data-cal-add-close>${t("common.close")}</button><button class="btn-primary" id="calBirthdaySave" type="button">${hasBirthdayCalendar ? t("ui.calendar.refresh-birthdays") : t("ui.calendar.turn-on-birthdays")}</button></div>`;
  }
}

async function loadHolidayCatalog() {
  try {
    const data = await api("/api/calendar/holidays");
    state.holidayCountries = data.countries || [];
    renderHolidayList();
  } catch (error) { showError(error); }
}

function renderHolidayList() {
  const holder = document.getElementById("calHolidayList");
  if (!holder) return;
  const filter = (document.getElementById("calHolidayFilter")?.value || "").toLowerCase();
  const selected = state.holidaySelection || new Set();
  const countries = (state.holidayCountries || []).filter((country) => !filter || country.name.toLowerCase().includes(filter));
  holder.innerHTML = countries.length ? countries.map((country) => `<label class="cal-holiday-row"><input type="checkbox" data-holiday-country="${esc(country.code)}" ${selected.has(country.code) ? "checked" : ""}><span>${esc(country.name)}</span></label>`).join("") : `<div class="cal-add-empty">${t("ui.calendar.no-countries-match-that-filter")}</div>`;
  const hint = document.getElementById("calHolidayHint");
  if (hint) hint.textContent = selected.size ? `${selected.size} selected` : t("ui.calendar.choose-up-to-five-countries");
}

async function saveNewCalendar() {
  const name = document.getElementById("calCreateName")?.value.trim();
  const color = document.getElementById("calCreateColor")?.value || CAL_COLORS[0];
  if (!name) { showToast(t("ui.calendar.give-the-calendar-a-name")); document.getElementById("calCreateName")?.focus(); return; }
  const button = document.getElementById("calCreateSave");
  button.disabled = true;
  try {
    const data = await api("/api/calendar/calendars", { method: "POST", body: { name, color } });
    applyCalendarPayload(data);
    calendarAddOverlay.hidden = true;
    showToast(t("ui.calendar.calendar-created"));
  } catch (error) { showError(error); }
  finally { button.disabled = false; }
}

async function saveEditedCalendar() {
  const id = state.calendarEditId;
  const name = document.getElementById("calEditName")?.value.trim();
  const color = document.getElementById("calEditColor")?.value;
  if (!id || !name) return;
  try {
    const data = await api(`/api/calendar/calendars/${encodeURIComponent(id)}`, { method: "PATCH", body: { name, color } });
    applyCalendarPayload(data);
    renderCalendarAdd();
    showToast(t("ui.calendar.calendar-updated"));
  } catch (error) { showError(error); }
}

async function deleteCalendarFromEditor() {
  const id = state.calendarEditId;
  const calendar = calendarById(id);
  if (!calendar) return;
  if (id === "default") { showToast(t("ui.calendar.the-default-calendar-cannot-be-deleted")); return; }
  const ok = await appConfirm({ title: `Delete “${calendar.name}”?`, message: t("ui.calendar.the-calendar-and-all-of-its-events-are-removed-f"), confirmLabel: t("ui.calendar.delete-calendar"), tone: "danger" });
  if (!ok) return;
  try {
    const data = await api(`/api/calendar/calendars/${encodeURIComponent(id)}`, { method: "DELETE" });
    applyCalendarPayload(data);
    calendarAddOverlay.hidden = true;
    showToast(t("ui.calendar.calendar-deleted"));
  } catch (error) { showError(error); }
}

async function subscribeCalendarFromWeb() {
  const url = document.getElementById("calSubscribeUrl")?.value.trim();
  if (!url) { showToast(t("ui.calendar.paste-a-calendar-address")); return; }
  const button = document.getElementById("calSubscribeImport");
  button.disabled = true;
  button.textContent = t("ui.calendar.importing");
  try {
    const data = await api("/api/calendar/subscribe", {
      method: "POST",
      body: {
        url,
        name: document.getElementById("calSubscribeName")?.value.trim() || "",
        color: document.getElementById("calSubscribeColor")?.value || "#7a4a5c"
      }
    });
    applyCalendarPayload(data);
    calendarAddOverlay.hidden = true;
    showToast(t("ui.calendar.calendar-subscribed"));
  } catch (error) { showError(error); }
  finally { button.disabled = false; button.innerHTML = `<svg class="icon" aria-hidden="true"><use href="#i-download"/></svg>${t("ui.calendar.import-calendar")}`; }
}

async function importCalendarFromFile() {
  const input = document.getElementById("calImportFile");
  const file = input?.files?.[0];
  if (!file) { showToast(t("ui.calendar.choose-an-ics-file")); return; }
  const button = document.getElementById("calImportAdd");
  button.disabled = true;
  button.textContent = t("ui.calendar.importing");
  try {
    const dataBase64 = await fileToBase64(file);
    const data = await api("/api/calendar/import", { method: "POST", body: { name: file.name, dataBase64 } });
    await refreshCalendarData();
    calendarAddOverlay.hidden = true;
    showToast(tn("ui.calendar.events-imported", data.imported || 0, { count: data.imported || 0 }));
  } catch (error) { showError(error); }
  finally { if (button) { button.disabled = false; button.innerHTML = `<svg class="icon" aria-hidden="true"><use href="#i-calendar-plus"/></svg>${t("ui.calendar.add-to-my-calendars")}`; } }
}

async function addHolidayCalendars() {
  const selected = Array.from(state.holidaySelection || []);
  if (!selected.length) { showToast(t("ui.calendar.choose-at-least-one-country")); return; }
  const button = document.getElementById("calHolidayAdd");
  button.disabled = true;
  button.textContent = t("ui.calendar.adding");
  let added = 0;
  try {
    for (const country of selected.slice(0, 5)) {
      const data = await api("/api/calendar/holidays", { method: "POST", body: { country, year: state.calendarYear } });
      applyCalendarPayload(data);
      added += 1;
    }
    state.holidaySelection = new Set();
    calendarAddOverlay.hidden = true;
    showToast(tn("ui.calendar.holiday-calendars-added", added, { count: added }));
  } catch (error) { showError(error); }
  finally { if (button) { button.disabled = false; button.innerHTML = `<svg class="icon" aria-hidden="true"><use href="#i-globe"/></svg>${t("ui.calendar.add-holiday-calendar")}`; } }
}

async function saveBirthdayCalendar() {
  const button = document.getElementById("calBirthdaySave");
  button.disabled = true;
  try {
    const data = await api("/api/calendar/birthdays", { method: "POST", body: {} });
    applyCalendarPayload(data);
    calendarAddOverlay.hidden = true;
    showToast(t("ui.calendar.birthday-calendar-ready"));
  } catch (error) { showError(error); }
  finally { button.disabled = false; }
}

/* ---------- calendar sharing + publication ---------- */
async function openCalendarShare(calendarId) {
  const calendar = calendarById(calendarId) || calendarById(state.calendarActiveId);
  if (!calendar) { showToast(t("ui.calendar.choose-a-calendar-first")); return; }
  state.calendarShareId = calendar.id;
  state.calendarShareTab = "people";
  state.calendarShares = [];
  state.calendarPublication = null;
  calendarShareOverlay.hidden = false;
  renderCalendarShare();
  if (calendar.owned) {
    loadCalendarShares(calendar.id);
    loadCalendarPublication(calendar.id);
  }
}

function renderCalendarShare() {
  const calendar = calendarById(state.calendarShareId);
  const body = document.getElementById("calendarShareBody");
  if (!calendar || !body) return;
  document.getElementById("calendarShareTitle").textContent = calendar.shared ? calendar.name : `Share “${calendar.name}”`;
  document.getElementById("calendarShareSubtitle").textContent = calendar.shared
    ? t("ui.calendar.shared-by-owner-generic", { owner: calendar.ownerName || calendar.ownerEmail || t("ui.calendar.the-owner") })
    : t("ui.calendar.invite-coworkers-with-view-or-edit-access-or-pub");
  document.querySelectorAll("[data-cal-share-tab]").forEach((button) => {
    button.classList.toggle("is-active", button.getAttribute("data-cal-share-tab") === state.calendarShareTab);
    button.hidden = calendar.shared && button.getAttribute("data-cal-share-tab") === "publish";
  });
  if (calendar.shared) {
    body.innerHTML = `<div class="cal-share-shared"><span class="cal-share-icon" style="--cal:${esc(calendar.color)}"><svg class="icon" aria-hidden="true"><use href="#i-people"/></svg></span><div><strong>${esc(calendar.name)}</strong><p>Owner: ${esc(calendar.ownerName || calendar.ownerEmail)} · ${calendar.access === "edit" ? t("ui.calendar.you-can-edit-events") : t("ui.calendar.view-only")}</p></div></div>
      <div class="cal-add-foot"><button class="btn-secondary danger-btn" type="button" data-cal-leave="${esc(calendar.id)}">${t("ui.calendar.leave-shared-calendar")}</button><button class="btn-primary" type="button" data-cal-share-close>${t("mail.list.done")}</button></div>`;
    return;
  }
  if (state.calendarShareTab === "publish") {
    const publication = state.calendarPublication;
    body.innerHTML = `<div class="cal-publish-intro"><span class="cal-share-icon"><svg class="icon" aria-hidden="true"><use href="#i-globe"/></svg></span><div><strong>${t("ui.calendar.publish-a-read-only-icalendar-feed")}</strong><p>${t("ui.calendar.google-calendar-apple-calendar-iphone-ipad-and-o")}</p></div></div>
      ${publication?.published ? `<label class="form-field"><span>${t("ui.calendar.calendar-feed-url")}</span><div class="copy-field"><input id="calPublishUrl" readonly value="${esc(publication.url)}"><button class="btn-secondary" type="button" data-copy-cal-url="${esc(publication.url)}">${t("ui.calendar.copy")}</button></div></label>
      <div class="cal-publish-links"><a class="btn-secondary" href="${esc(publication.webcal)}">${t("ui.calendar.open-in-apple-calendar")}</a><a class="btn-secondary" href="https://calendar.google.com/calendar/u/0/r/settings/addbyurl" target="_blank" rel="noopener">${t("ui.calendar.add-to-google-calendar")}</a></div>
      <div class="cal-publish-hints"><div><strong>${t("ui.calendar.google-calendar")}</strong><span>${t("ui.calendar.other-calendars-from-url-paste-the-feed-url")}</span></div><div><strong>${t("ui.calendar.apple-calendar")}</strong><span>${t("ui.calendar.file-new-calendar-subscription-paste-the-feed-ur")}</span></div><div><strong>${t("ui.calendar.outlook")}</strong><span>${t("ui.calendar.add-calendar-subscribe-from-web-paste-the-feed-u")}</span></div></div>
      <div class="cal-add-foot"><button class="btn-secondary" type="button" data-cal-rotate>${t("ui.calendar.rotate-link")}</button><button class="btn-secondary danger-btn" type="button" data-cal-unpublish>${t("ui.calendar.stop-publishing")}</button><button class="btn-primary" type="button" data-cal-share-close>${t("mail.list.done")}</button></div>`
      : `<div class="cal-publish-empty"><span>${t("ui.calendar.your-calendar-is-private-publishing-creates-a-se")}</span><button class="btn-primary" type="button" data-cal-publish><svg class="icon" aria-hidden="true"><use href="#i-globe"/></svg>${t("ui.calendar.publish-calendar")}</button></div>
      <div class="cal-publish-hints"><div><strong>${t("ui.calendar.google-calendar")}</strong><span>${t("ui.calendar.works-with-from-url-subscriptions")}</span></div><div><strong>${t("ui.calendar.apple-calendar")}</strong><span>${t("ui.calendar.works-with-new-calendar-subscription")}</span></div><div><strong>${t("ui.calendar.revocable")}</strong><span>${t("ui.calendar.stop-publishing-or-rotate-the-link-at-any-time")}</span></div></div>
      <div class="cal-add-foot"><button class="btn-secondary" type="button" data-cal-share-close>${t("tasks.action.cancel")}</button></div>`}`;
    return;
  }
  body.innerHTML = `<div class="cal-share-invite">
      <label class="form-field grow"><span>${t("ui.calendar.invite-a-coworker")}</span><input id="calShareEmail" type="email" placeholder="name@company.com" autocomplete="off"></label>
      <label class="form-field"><span>${t("ui.calendar.access")}</span><select id="calShareAccess"><option value="view">${t("ui.calendar.can-view")}</option><option value="edit">${t("ui.calendar.can-edit")}</option></select></label>
      <button class="btn-primary" type="button" data-cal-share-invite>${t("ui.calendar.send-invite")}</button>
    </div>
    <div class="cal-share-list"><div class="cal-share-list-head"><strong>${t("ui.calendar.people-with-access")}</strong><span>${state.calendarShares.length}</span></div>
      ${state.calendarShares.length ? state.calendarShares.map((share) => `<div class="cal-share-row"><span class="event-attendee-avatar" style="--attendee:${colorForString(share.email)}">${esc(initialsFrom(share.name || share.email))}</span><div><strong>${esc(share.name || share.email)}</strong><span>${esc(share.email)}</span></div><span class="policy-chip">${share.access === "edit" ? t("ui.calendar.can-edit") : t("ui.calendar.can-view")}</span><button class="link-btn danger-link" type="button" data-cal-unshare="${esc(share.userId)}">${t("tasks.detail.remove")}</button></div>`).join("") : `<p class="cal-share-empty">${t("ui.calendar.only-you-can-see-this-calendar-invite-a-coworker")}</p>`}
    </div>
    <div class="cal-share-owner-note"><svg class="icon" aria-hidden="true"><use href="#i-shield-check"/></svg><span>${t("ui.calendar.people-with-edit-access-can-create-and-change-ev")}</span></div>
    <div class="cal-add-foot"><button class="btn-secondary" type="button" data-cal-share-tab-jump="publish"><svg class="icon" aria-hidden="true"><use href="#i-globe"/></svg>${t("ui.calendar.publish-to-google-apple")}</button><button class="btn-primary" type="button" data-cal-share-close>${t("mail.list.done")}</button></div>`;
}

async function loadCalendarShares(calendarId) {
  try {
    const data = await api(`/api/calendar/calendars/${encodeURIComponent(calendarId)}/shares`);
    state.calendarShares = data.shares || [];
  } catch { state.calendarShares = []; }
  if (state.calendarShareTab === "people") renderCalendarShare();
}

async function inviteCalendarShare() {
  const email = document.getElementById("calShareEmail")?.value.trim();
  if (!email) { showToast(t("ui.calendar.enter-a-coworker-email")); return; }
  try {
    const data = await api(`/api/calendar/calendars/${encodeURIComponent(state.calendarShareId)}/share`, {
      method: "POST", body: { email, access: document.getElementById("calShareAccess").value }
    });
    applyCalendarPayload(data);
    await loadCalendarShares(state.calendarShareId);
    showToast(t("ui.calendar.calendar-shared"));
  } catch (error) { showError(error); }
}

async function removeCalendarShare(userId) {
  try {
    const data = await api(`/api/calendar/calendars/${encodeURIComponent(state.calendarShareId)}/share/${encodeURIComponent(userId)}`, { method: "DELETE" });
    applyCalendarPayload(data);
    await loadCalendarShares(state.calendarShareId);
    showToast(t("ui.calendar.access-removed"));
  } catch (error) { showError(error); }
}

async function loadCalendarPublication(calendarId) {
  try {
    const data = await api(`/api/calendar/calendars/${encodeURIComponent(calendarId)}/publish`);
    state.calendarPublication = data;
  } catch { state.calendarPublication = { published: false }; }
  if (state.calendarShareTab === "publish") renderCalendarShare();
}

async function publishCalendar() {
  try {
    const data = await api(`/api/calendar/calendars/${encodeURIComponent(state.calendarShareId)}/publish`, { method: "POST" });
    state.calendarPublication = data;
    renderCalendarShare();
    await refreshCalendarData();
    showToast(t("ui.calendar.calendar-published"));
  } catch (error) { showError(error); }
}

async function rotateCalendarPublication() {
  try {
    const data = await api(`/api/calendar/calendars/${encodeURIComponent(state.calendarShareId)}/publish?rotate=1`, { method: "POST" });
    state.calendarPublication = data;
    renderCalendarShare();
    showToast(t("ui.calendar.new-feed-link-created"));
  } catch (error) { showError(error); }
}

async function unpublishCalendar() {
  try {
    await api(`/api/calendar/calendars/${encodeURIComponent(state.calendarShareId)}/publish`, { method: "DELETE" });
    state.calendarPublication = { published: false };
    renderCalendarShare();
    await refreshCalendarData();
    showToast(t("ui.calendar.calendar-feed-removed"));
  } catch (error) { showError(error); }
}

async function leaveSharedCalendar(calendarId) {
  const calendar = calendarById(calendarId);
  if (!calendar) return;
  const ok = await appConfirm({ title: `Leave “${calendar.name}”?`, message: t("ui.calendar.the-calendar-disappears-from-your-sidebar-you-ca"), confirmLabel: t("ui.calendar.leave-calendar"), tone: "danger" });
  if (!ok) return;
  try {
    const data = await api(`/api/calendar/calendars/${encodeURIComponent(calendarId)}/leave`, { method: "POST" });
    applyCalendarPayload(data);
    calendarShareOverlay.hidden = true;
    showToast(t("ui.calendar.left-shared-calendar"));
  } catch (error) { showError(error); }
}

/* ---------- calendar filter and row menu ---------- */
function renderCalendarFilterMenu() {
  if (!calFilterMenu) return;
  const rows = (state.calendars || []).map((calendar) => `<label class="cal-filter-row"><input type="checkbox" data-cal-filter-id="${esc(calendar.id)}" ${!state.calendarHidden.has(calendar.id) && calendar.visible !== false ? "checked" : ""}><span class="cal-color" style="--cal:${esc(calendar.color)}"></span><span>${esc(calendar.name)}</span><em>${calendar.eventCount || 0}</em></label>`).join("");
  calFilterMenu.innerHTML = `<div class="cal-filter-head"><strong>${t("ui.calendar.show-calendars")}</strong><button class="link-btn" type="button" data-cal-filter-all>${t("ui.calendar.show-all")}</button></div>${rows}
    <div class="cal-filter-sep"></div>
    <label class="cal-filter-row"><input type="checkbox" data-cal-filter-declined ${state.calendarHideDeclined ? "checked" : ""}><span class="cal-color" style="--cal:#98a2b3"></span><span>${t("ui.calendar.hide-declined-invitations")}</span></label>`;
}

function openCalendarRowMenu(calendarId, x, y) {
  const calendar = calendarById(calendarId);
  if (!calendar || !calFilterMenu) return;
  state.calendarRowMenuId = calendarId;
  state.calendarMenuMode = "row";
  calFilterMenu.innerHTML = `<div class="cal-filter-head"><strong>${esc(calendar.name)}</strong><span>${calendar.shared ? t("mail.list.shared") : calCanEdit(calendar) ? t("ui.files-storage.owner") : t("ui.calendar.view")}</span></div>
    <button class="cal-menu-action" type="button" data-cal-row-action="open"><svg class="icon" aria-hidden="true"><use href="#i-calendar"/></svg>${t("ui.calendar.open-calendar")}</button>
    <button class="cal-menu-action" type="button" data-cal-row-action="visibility"><svg class="icon" aria-hidden="true"><use href="#i-check"/></svg>${state.calendarHidden.has(calendar.id) ? t("ui.calendar.show-in-view") : t("ui.calendar.hide-from-view")}</button>
    ${calendar.owned ? `<button class="cal-menu-action" type="button" data-cal-row-action="edit"><svg class="icon" aria-hidden="true"><use href="#i-pencil"/></svg>${t("ui.calendar.rename-or-recolour")}</button>
    <button class="cal-menu-action" type="button" data-cal-row-action="share"><svg class="icon" aria-hidden="true"><use href="#i-people"/></svg>${t("ui.calendar.share-and-publish")}</button>
    ${calendar.id !== "default" ? `<button class="cal-menu-action danger-link" type="button" data-cal-row-action="delete"><svg class="icon" aria-hidden="true"><use href="#i-trash"/></svg>${t("ui.calendar.delete-calendar")}</button>` : ""}` : `<button class="cal-menu-action danger-link" type="button" data-cal-row-action="leave"><svg class="icon" aria-hidden="true"><use href="#i-arrow-left"/></svg>${t("ui.calendar.leave-calendar")}</button>`}`;
  calFilterMenu.hidden = false;
  calFilterMenu.style.position = "fixed";
  const rect = calFilterMenu.getBoundingClientRect();
  calFilterMenu.style.left = `${Math.max(8, Math.min(x || 80, window.innerWidth - rect.width - 12))}px`;
  calFilterMenu.style.top = `${Math.max(8, Math.min(y || 120, window.innerHeight - rect.height - 12))}px`;
}

async function moveCalendarOccurrence(eventId, date) {
  const event = (state.calendarEvents || []).find((item) => item.id === eventId);
  if (!event) return;
  if (!event.canEdit) { showToast(t("ui.calendar.you-can-only-rsvp-to-this-invitation")); return; }
  if (event.date === date) return;
  if (event.recurrenceRule) {
    const ok = await appConfirm({ title: t("ui.calendar.move-the-whole-series"), message: t("ui.calendar.move-series-confirm", { title: event.title, date: formatDateOnly(date) }), confirmLabel: t("ui.calendar.move-series") });
    if (!ok) return;
  }
  try {
    await api(`/api/calendar/events/${encodeURIComponent(eventId)}`, { method: "PATCH", body: { date } });
    state.calendarSelected = date;
    const parsed = calendarDateFromKey(date);
    state.calendarYear = parsed.getUTCFullYear();
    state.calendarMonth = parsed.getUTCMonth();
    await refreshCalendarData();
    renderCalendar();
    showToast(t("ui.calendar.event-moved-to", { date: formatDateOnly(date) }));
  } catch (error) { showError(error); }
}

function setupCalendarInteractions() {
  if (!calendarView) return;
  calendarView.addEventListener("click", (event) => {
    const target = event.target;
    const newDate = target.closest("[data-cal-new-date]");
    if (newDate) { event.preventDefault(); event.stopPropagation(); openEventDialog(null, { date: newDate.getAttribute("data-cal-new-date") }); return; }
    const edit = target.closest("[data-edit-event]");
    if (edit) { event.preventDefault(); event.stopPropagation(); openEventDialog(edit.getAttribute("data-edit-event"), { date: edit.getAttribute("data-cal-occurrence") || "" }); return; }
    const miniDate = target.closest("[data-cal-mini-date]");
    if (miniDate) {
      event.preventDefault(); event.stopPropagation();
      state.calendarSelected = miniDate.getAttribute("data-cal-mini-date");
      const parsed = calendarDateFromKey(state.calendarSelected);
      state.calendarYear = parsed.getUTCFullYear();
      state.calendarMonth = parsed.getUTCMonth();
      state.calendarMiniYear = state.calendarYear;
      state.calendarMiniMonth = state.calendarMonth;
      renderCalendar();
      return;
    }
    const viewButton = target.closest("[data-cal-view]");
    if (viewButton) { event.preventDefault(); event.stopPropagation(); setCalendarView(viewButton.getAttribute("data-cal-view")); return; }
    const calendarSelect = target.closest("[data-calendar-select]");
    if (calendarSelect) { event.preventDefault(); event.stopPropagation(); state.calendarActiveId = calendarSelect.getAttribute("data-calendar-select"); renderCalendarLists(); return; }
    const calendarMenu = target.closest("[data-calendar-menu]");
    if (calendarMenu) {
      event.preventDefault(); event.stopPropagation();
      const button = calendarMenu.getBoundingClientRect();
      openCalendarRowMenu(calendarMenu.getAttribute("data-calendar-menu"), button.left, button.bottom + 4);
      return;
    }
    const shortcut = target.closest("[data-cal-shortcut]");
    if (shortcut) { event.preventDefault(); event.stopPropagation(); openCalendarAdd(shortcut.getAttribute("data-cal-shortcut") === "birthdays" ? "birthdays" : "holidays"); return; }
    const monthCell = target.closest(".cal-month-cell[data-cal-date]");
    if (monthCell) { event.preventDefault(); selectCalendarDate(monthCell.getAttribute("data-cal-date")); return; }
    const allDayCell = target.closest(".cal-time-allday-cell[data-cal-date]");
    if (allDayCell) { event.preventDefault(); selectCalendarDate(allDayCell.getAttribute("data-cal-date")); return; }
    const timeCol = target.closest(".cal-time-col[data-cal-date]");
    if (timeCol && !target.closest(".cal-time-event")) {
      event.preventDefault();
      const rect = timeCol.getBoundingClientRect();
      const offset = Math.max(0, Math.min(rect.height, event.clientY - rect.top));
      const minutes = Math.round((CAL_HOUR_START * 60 + (offset / rect.height) * (CAL_HOUR_END - CAL_HOUR_START) * 60) / 15) * 15;
      const hour = Math.floor(minutes / 60);
      const minute = minutes % 60;
      selectCalendarDate(timeCol.getAttribute("data-cal-date"), false);
      openEventDialog(null, { date: timeCol.getAttribute("data-cal-date"), time: `${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}` });
      return;
    }
  });
  calendarView.addEventListener("dblclick", (event) => {
    const target = event.target;
    if (target.closest("button, a, input, textarea, select, [data-edit-event]")) return;
    const monthCell = target.closest(".cal-month-cell[data-cal-date]");
    if (!monthCell) return;
    event.preventDefault();
    const date = monthCell.getAttribute("data-cal-date");
    selectCalendarDate(date);
    openEventDialog(null, { date });
  });
  calendarView.addEventListener("change", (event) => {
    const visibility = event.target.closest("[data-calendar-visibility]");
    if (visibility) toggleCalendarVisibility(visibility.getAttribute("data-calendar-visibility"), visibility.checked);
  });
  calendarView.addEventListener("dragstart", (event) => {
    const chip = event.target.closest("[data-edit-event]");
    if (!chip || !event.dataTransfer) return;
    event.dataTransfer.setData("application/x-a8m-event", chip.getAttribute("data-edit-event"));
    event.dataTransfer.effectAllowed = "move";
  });
  calendarView.addEventListener("dragover", (event) => {
    if (!event.dataTransfer?.types?.includes("application/x-a8m-event")) return;
    const drop = event.target.closest("[data-cal-drop-date]");
    if (!drop) return;
    event.preventDefault();
    calendarView.querySelectorAll(".is-drop-target").forEach((element) => element.classList.remove("is-drop-target"));
    drop.classList.add("is-drop-target");
  });
  calendarView.addEventListener("dragleave", (event) => {
    if (event.relatedTarget && calendarView.contains(event.relatedTarget)) return;
    calendarView.querySelectorAll(".is-drop-target").forEach((element) => element.classList.remove("is-drop-target"));
  });
  calendarView.addEventListener("drop", (event) => {
    const eventId = event.dataTransfer?.getData("application/x-a8m-event");
    if (!eventId) return;
    const drop = event.target.closest("[data-cal-drop-date]");
    if (!drop) return;
    event.preventDefault();
    calendarView.querySelectorAll(".is-drop-target").forEach((element) => element.classList.remove("is-drop-target"));
    moveCalendarOccurrence(eventId, drop.getAttribute("data-cal-drop-date"));
  });

  document.getElementById("calPrev")?.addEventListener("click", () => shiftCalendarPeriod(-1));
  document.getElementById("calNext")?.addEventListener("click", () => shiftCalendarPeriod(1));
  document.getElementById("calToday")?.addEventListener("click", () => {
    const today = new Date();
    state.calendarYear = today.getFullYear();
    state.calendarMonth = today.getMonth();
    state.calendarSelected = dateKey(today);
    state.calendarMiniYear = state.calendarYear;
    state.calendarMiniMonth = state.calendarMonth;
    renderCalendar();
  });
  document.getElementById("calMiniPrev")?.addEventListener("click", () => {
    const next = new Date(Date.UTC(state.calendarMiniYear ?? state.calendarYear, (state.calendarMiniMonth ?? state.calendarMonth) - 1, 1, 12));
    state.calendarMiniYear = next.getUTCFullYear();
    state.calendarMiniMonth = next.getUTCMonth();
    renderCalendarMini();
  });
  document.getElementById("calMiniNext")?.addEventListener("click", () => {
    const next = new Date(Date.UTC(state.calendarMiniYear ?? state.calendarYear, (state.calendarMiniMonth ?? state.calendarMonth) + 1, 1, 12));
    state.calendarMiniYear = next.getUTCFullYear();
    state.calendarMiniMonth = next.getUTCMonth();
    renderCalendarMini();
  });
  calSearchInput?.addEventListener("input", () => { state.calendarSearch = calSearchInput.value; renderCalendar(); });
  document.getElementById("calAddCalendar")?.addEventListener("click", () => openCalendarAdd("create"));
  document.getElementById("calBookingPages")?.addEventListener("click", () => openBookingPages().catch(showError));
  document.getElementById("calSidebarAdd")?.addEventListener("click", () => openCalendarAdd("create"));
  document.getElementById("calListMore")?.addEventListener("click", () => openCalendarAdd("edit"));
  document.getElementById("calShareBtn")?.addEventListener("click", () => openCalendarShare(state.calendarActiveId));
  document.getElementById("calPrintBtn")?.addEventListener("click", () => window.print());
  document.getElementById("calFilterBtn")?.addEventListener("click", (event) => {
    event.stopPropagation();
    if (!calFilterMenu) return;
    const opening = calFilterMenu.hidden || state.calendarMenuMode !== "filter";
    if (opening) {
      state.calendarMenuMode = "filter";
      state.calendarRowMenuId = "";
      renderCalendarFilterMenu();
      calFilterMenu.hidden = false;
      calFilterMenu.style.position = "absolute";
      const rect = event.currentTarget.getBoundingClientRect();
      calFilterMenu.style.left = `${Math.max(8, Math.min(rect.right - 280, window.innerWidth - 300))}px`;
      calFilterMenu.style.top = `${rect.bottom + 6}px`;
    } else calFilterMenu.hidden = true;
  });
  calFilterMenu?.addEventListener("change", (event) => {
    const filter = event.target.closest("[data-cal-filter-id]");
    if (filter) { toggleCalendarVisibility(filter.getAttribute("data-cal-filter-id"), filter.checked); renderCalendarFilterMenu(); return; }
    if (event.target.closest("[data-cal-filter-declined]")) { state.calendarHideDeclined = event.target.checked; renderCalendar(); }
  });
  calFilterMenu?.addEventListener("click", (event) => {
    if (event.target.closest("[data-cal-filter-all]")) {
      state.calendarHidden.clear();
      persistCalendarVisibility();
      (state.calendars || []).forEach((calendar) => {
        if (calendar.owned && calendar.visible === false) {
          calendar.visible = true;
          api(`/api/calendar/calendars/${encodeURIComponent(calendar.id)}`, { method: "PATCH", body: { visible: true } }).catch(() => {});
        }
      });
      renderCalendar();
      renderCalendarFilterMenu();
      return;
    }
    const action = event.target.closest("[data-cal-row-action]");
    if (!action) return;
    const calendar = calendarById(state.calendarRowMenuId);
    calFilterMenu.hidden = true;
    if (!calendar) return;
    const kind = action.getAttribute("data-cal-row-action");
    if (kind === "open") { state.calendarActiveId = calendar.id; renderCalendarLists(); }
    else if (kind === "visibility") toggleCalendarVisibility(calendar.id, state.calendarHidden.has(calendar.id));
    else if (kind === "edit") openCalendarAdd("edit", calendar.id);
    else if (kind === "share") openCalendarShare(calendar.id);
    else if (kind === "delete") { state.calendarEditId = calendar.id; deleteCalendarFromEditor(); }
    else if (kind === "leave") leaveSharedCalendar(calendar.id);
  });
  document.addEventListener("click", (event) => {
    if (calFilterMenu && !calFilterMenu.hidden && !event.target.closest("#calFilterMenu") && !event.target.closest("#calFilterBtn") && !event.target.closest("[data-calendar-menu]")) calFilterMenu.hidden = true;
  });

  const calNew = document.getElementById("calNew");
  const calNewMenu = document.getElementById("calNewMenu");
  calNew?.addEventListener("click", (event) => {
    event.stopPropagation();
    if (event.target.closest(".cal-new-caret")) {
      calNewMenu.hidden = !calNewMenu.hidden;
      return;
    }
    calNewMenu.hidden = true;
    openEventDialog();
  });
  calNewMenu?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-cal-new]");
    if (!button) return;
    calNewMenu.hidden = true;
    const kind = button.getAttribute("data-cal-new");
    if (kind === "holiday") openCalendarAdd("holidays");
    else if (kind === "poll") openCalendarPollDialog();
    else openEventDialog(null, { invite: kind === "invite" });
  });
  document.addEventListener("click", (event) => {
    if (calNewMenu && !calNewMenu.hidden && !event.target.closest("#calNewMenu") && !event.target.closest("#calNew")) calNewMenu.hidden = true;
  });
  document.getElementById("calPollsBtn")?.addEventListener("click", openCalendarPolls);
  document.getElementById("calendarPollClose")?.addEventListener("click", () => { calendarPollOverlay.hidden = true; });
  document.getElementById("pollCancel")?.addEventListener("click", () => { calendarPollOverlay.hidden = true; });
  document.getElementById("pollCreate")?.addEventListener("click", createCalendarPoll);
  document.getElementById("pollAddSlot")?.addEventListener("click", () => {
    capturePollSlots();
    if (state.pollDraftSlots.length >= 20) { showToast(t("ui.calendar.a-poll-can-have-up-to-20-time-options")); return; }
    const last = state.pollDraftSlots[state.pollDraftSlots.length - 1];
    state.pollDraftSlots.push({ date: addDaysToKey(last?.date || pollDateKey(new Date()), 1), start: last?.start || "10:00", end: last?.end || "11:00" });
    renderPollSlots();
  });
  document.getElementById("pollSlots")?.addEventListener("click", (event) => {
    const remove = event.target.closest("[data-poll-slot-remove]");
    if (!remove) return;
    capturePollSlots();
    if (state.pollDraftSlots.length <= 1) { showToast(t("ui.calendar.keep-at-least-one-time-option")); return; }
    state.pollDraftSlots.splice(Number(remove.getAttribute("data-poll-slot-remove")), 1);
    renderPollSlots();
  });
  document.getElementById("pollSlots")?.addEventListener("input", capturePollSlots);
  calendarPollOverlay?.addEventListener("click", (event) => { if (event.target === calendarPollOverlay) calendarPollOverlay.hidden = true; });
  document.getElementById("calendarPollsClose")?.addEventListener("click", () => { calendarPollsOverlay.hidden = true; });
  calendarPollsOverlay?.addEventListener("click", (event) => {
    if (event.target === calendarPollsOverlay) { calendarPollsOverlay.hidden = true; return; }
    if (event.target.closest("[data-poll-new]")) { calendarPollsOverlay.hidden = true; openCalendarPollDialog(); return; }
    const schedule = event.target.closest("[data-poll-schedule]");
    if (schedule) { scheduleCalendarPoll(schedule.getAttribute("data-poll-schedule"), schedule.getAttribute("data-poll-slot")); return; }
    const close = event.target.closest("[data-poll-close]");
    if (close) { closeCalendarPoll(close.getAttribute("data-poll-close")); return; }
    const remove = event.target.closest("[data-poll-delete]");
    if (remove) { deleteCalendarPoll(remove.getAttribute("data-poll-delete")); return; }
  });

  calendarAddOverlay?.addEventListener("click", (event) => {
    if (event.target === calendarAddOverlay || event.target.closest("#calendarAddClose") || event.target.closest("[data-cal-add-close]")) { calendarAddOverlay.hidden = true; return; }
    const tab = event.target.closest("[data-cal-add-tab]");
    if (tab) { state.calendarAddTab = tab.getAttribute("data-cal-add-tab"); renderCalendarAdd(); if (state.calendarAddTab === "holidays" && !state.holidayCountries?.length) loadHolidayCatalog(); return; }
    const color = event.target.closest("[data-cal-color-choice]");
    if (color) {
      const value = color.getAttribute("data-cal-color-choice");
      if (state.calendarAddTab === "create") { state.calendarDraftCreateColor = value; const input = document.getElementById("calCreateColor"); if (input) input.value = value; }
      else { const input = document.getElementById("calEditColor"); if (input) input.value = value; }
      color.parentElement.querySelectorAll("[data-cal-color-choice]").forEach((button) => button.classList.toggle("is-active", button === color));
      return;
    }
    const charm = event.target.closest("[data-cal-charm]");
    if (charm) { state.calendarCharm = charm.getAttribute("data-cal-charm"); charm.parentElement.querySelectorAll("[data-cal-charm]").forEach((button) => button.classList.toggle("is-active", button === charm)); return; }
    if (event.target.closest("#calCreateSave")) { saveNewCalendar(); return; }
    if (event.target.closest("#calEditSave")) { saveEditedCalendar(); return; }
    const editShare = event.target.closest("[data-cal-edit-share]");
    if (editShare) { calendarAddOverlay.hidden = true; openCalendarShare(editShare.getAttribute("data-cal-edit-share")); return; }
    const editPublish = event.target.closest("[data-cal-edit-publish]");
    if (editPublish) { calendarAddOverlay.hidden = true; openCalendarShare(editPublish.getAttribute("data-cal-edit-publish")); state.calendarShareTab = "publish"; renderCalendarShare(); return; }
    const editExport = event.target.closest("[data-cal-edit-export]");
    if (editExport) { window.location.href = `/api/calendar/export?calendarId=${encodeURIComponent(editExport.getAttribute("data-cal-edit-export"))}`; return; }
    const editDelete = event.target.closest("[data-cal-edit-delete]");
    if (editDelete) { deleteCalendarFromEditor(); return; }
    if (event.target.closest("#calSubscribeImport")) { subscribeCalendarFromWeb(); return; }
    if (event.target.closest("#calImportAdd")) { importCalendarFromFile(); return; }
    if (event.target.closest("#calHolidayAdd")) { addHolidayCalendars(); return; }
    if (event.target.closest("#calBirthdaySave")) { saveBirthdayCalendar(); return; }
  });
  calendarAddOverlay?.addEventListener("change", (event) => {
    if (event.target.id === "calEditSelect") { state.calendarEditId = event.target.value; renderCalendarAdd(); return; }
    if (event.target.id === "calImportFile") {
      const name = event.target.files?.[0]?.name || t("ui.alt8mail-office.no-file-selected");
      const label = document.getElementById("calImportFileName");
      if (label) label.textContent = name;
      const button = document.getElementById("calImportAdd");
      if (button) button.disabled = !event.target.files?.length;
      return;
    }
    const country = event.target.closest("[data-holiday-country]");
    if (country) {
      state.holidaySelection = state.holidaySelection || new Set();
      if (country.checked && state.holidaySelection.size >= 5) { country.checked = false; showToast(t("ui.calendar.choose-up-to-five-countries-at-a-time")); return; }
      if (country.checked) state.holidaySelection.add(country.getAttribute("data-holiday-country"));
      else state.holidaySelection.delete(country.getAttribute("data-holiday-country"));
      renderHolidayList();
    }
  });
  calendarAddOverlay?.addEventListener("input", (event) => {
    if (event.target.id === "calHolidayFilter") renderHolidayList();
  });
  calendarAddOverlay?.addEventListener("dragover", (event) => {
    if (event.target.closest("#calUploadZone")) event.preventDefault();
  });
  calendarAddOverlay?.addEventListener("drop", (event) => {
    if (!event.target.closest("#calUploadZone")) return;
    event.preventDefault();
    const input = document.getElementById("calImportFile");
    if (input && event.dataTransfer.files?.length) {
      input.files = event.dataTransfer.files;
      input.dispatchEvent(new Event("change", { bubbles: true }));
    }
  });

  calendarShareOverlay?.addEventListener("click", (event) => {
    if (event.target === calendarShareOverlay || event.target.closest("#calendarShareClose") || event.target.closest("[data-cal-share-close]")) { calendarShareOverlay.hidden = true; return; }
    const tab = event.target.closest("[data-cal-share-tab]");
    if (tab) { state.calendarShareTab = tab.getAttribute("data-cal-share-tab"); renderCalendarShare(); if (state.calendarShareTab === "publish" && !state.calendarPublication) loadCalendarPublication(state.calendarShareId); return; }
    const jump = event.target.closest("[data-cal-share-tab-jump]");
    if (jump) { state.calendarShareTab = jump.getAttribute("data-cal-share-tab-jump"); renderCalendarShare(); if (!state.calendarPublication) loadCalendarPublication(state.calendarShareId); return; }
    if (event.target.closest("[data-cal-share-invite]")) { inviteCalendarShare(); return; }
    const unshare = event.target.closest("[data-cal-unshare]");
    if (unshare) { removeCalendarShare(unshare.getAttribute("data-cal-unshare")); return; }
    if (event.target.closest("[data-cal-publish]")) { publishCalendar(); return; }
    if (event.target.closest("[data-cal-rotate]")) { rotateCalendarPublication(); return; }
    if (event.target.closest("[data-cal-unpublish]")) { unpublishCalendar(); return; }
    const leave = event.target.closest("[data-cal-leave]");
    if (leave) { leaveSharedCalendar(leave.getAttribute("data-cal-leave")); return; }
    const copy = event.target.closest("[data-copy-cal-url]");
    if (copy) { copyTextToClipboard(copy.getAttribute("data-copy-cal-url")).then((ok) => showToast(ok ? t("ui.calendar.calendar-feed-link-copied") : copy.getAttribute("data-copy-cal-url"))); return; }
  });

  eventOverlay?.addEventListener("submit", (event) => {
    if (event.target.matches("[data-event-propose]")) {
      event.preventDefault();
      proposeCalendarTime(event.target);
    }
  });
  eventOverlay?.addEventListener("input", (event) => {
    if (event.target.id === "eventAttendeeInput") { renderEventAttendeeSuggest(); return; }
    if (["eventName", "eventDate", "eventStart", "eventEnd", "eventColorSelect", "eventRecurrence", "eventUntil", "eventTimezone"].includes(event.target.id)) updateEventPreview();
  });
  eventOverlay?.addEventListener("change", (event) => {
    if (event.target.id === "eventAllDay") { updateEventTimeFields(); updateEventPreview(); return; }
    if (event.target.id === "eventResourceSelect") {
      addEventResource(event.target.value);
      event.target.value = "";
      return;
    }
    if (event.target.id === "eventScope") {
      state.eventEditScope = event.target.value;
      document.getElementById("eventRecurrence").disabled = event.target.value === "occurrence";
      document.getElementById("eventDelete").textContent = event.target.value === "occurrence" ? t("ui.calendar.cancel-this-event") : t("mail.list.quick.delete");
      return;
    }
    if (event.target.id === "eventRecurrence") { document.getElementById("eventUntilWrap").hidden = !event.target.value; document.getElementById("eventUntil").value = event.target.value ? (document.getElementById("eventUntil").value || "") : ""; updateEventPreview(); return; }
    if (["eventDate", "eventStart", "eventEnd", "eventColorSelect", "eventUntil", "eventTimezone"].includes(event.target.id)) updateEventPreview();
  });
  eventOverlay?.addEventListener("keydown", (event) => {
    if (event.target.id === "eventAttendeeInput" && event.key === "Enter") {
      event.preventDefault();
      const email = event.target.value.trim();
      if (email) { addEventAttendee(email); event.target.value = ""; document.getElementById("eventAttendeeSuggest").hidden = true; }
    }
  });
  eventOverlay?.addEventListener("click", (event) => {
    const add = event.target.closest("[data-event-attendee-add]");
    if (add) { addEventAttendee(add.getAttribute("data-event-attendee-add"), add.getAttribute("data-event-attendee-name")); const input = document.getElementById("eventAttendeeInput"); if (input) input.value = ""; document.getElementById("eventAttendeeSuggest").hidden = true; return; }
    const remove = event.target.closest("[data-event-attendee-remove]");
    if (remove) { state.eventAttendees.splice(Number(remove.getAttribute("data-event-attendee-remove")), 1); renderEventAttendees(); updateEventPreview(); return; }
    if (event.target.closest("#eventAttachBtn")) {
      const picker = document.getElementById("eventAttachmentPicker");
      picker.hidden = !picker.hidden;
      if (!picker.hidden) renderEventAttachmentPicker();
      return;
    }
    const pick = event.target.closest("[data-event-attach-file]");
    if (pick) {
      const file = state.files.find((item) => item.id === pick.getAttribute("data-event-attach-file"));
      if (file && !state.eventAttachments.some((item) => item.id === file.id) && state.eventAttachments.length < 10) {
        state.eventAttachments.push({ id: file.id, name: file.name, mime: file.mime, sizeBytes: file.sizeBytes, providerId: file.providerId, contentUrl: file.contentUrl });
        renderEventAttachments();
      }
      return;
    }
    const removeAttach = event.target.closest("[data-event-attachment-remove]");
    const officeAttach = event.target.closest("[data-event-office]");
    if (officeAttach) {
      event.preventDefault();
      event.stopPropagation();
      openOfficeEditorById(officeAttach.getAttribute("data-event-office") || "").catch(showError);
      return;
    }
    if (removeAttach) { state.eventAttachments.splice(Number(removeAttach.getAttribute("data-event-attachment-remove")), 1); renderEventAttachments(); return; }
    const removeResource = event.target.closest("[data-event-resource-remove]");
    if (removeResource) { state.eventResources.splice(Number(removeResource.getAttribute("data-event-resource-remove")), 1); renderEventResources(); return; }
    if (event.target.closest("#eventResourceAdd")) { openCalendarResourceDialog(); return; }
    const rsvp = event.target.closest("[data-event-rsvp]");
    if (rsvp) { rsvpCalendarEvent(rsvp.getAttribute("data-event-rsvp")); return; }
    if (event.target.closest("[data-event-resend]")) { resendEventInvites(); return; }
    const acceptProposal = event.target.closest("[data-proposal-accept]");
    if (acceptProposal) { decideCalendarProposal(acceptProposal.getAttribute("data-proposal-accept"), "accept"); return; }
    const declineProposal = event.target.closest("[data-proposal-decline]");
    if (declineProposal) { decideCalendarProposal(declineProposal.getAttribute("data-proposal-decline"), "decline"); return; }
  });

  document.getElementById("eventClose")?.addEventListener("click", closeEventDialog);
  document.getElementById("eventCancel")?.addEventListener("click", closeEventDialog);
  document.getElementById("eventSave")?.addEventListener("click", saveEvent);
  document.getElementById("eventDelete")?.addEventListener("click", () => deleteCalendarEvent(calendarEditingId));
  eventOverlay?.addEventListener("click", (event) => { if (event.target === eventOverlay) closeEventDialog(); });
}

setupCalendarInteractions();

/* ============================================================
   navigation + chrome
   ============================================================ */
// Hash routes use stable ASCII identifiers, never localized labels. A
// translated folder or task name must not leak into the address bar or break
// bookmarks when the interface language changes.
const HASH_TASK_LABELS = {
  calendar: "Calendar", people: "People", tasks: "Tasks", files: "Files", scheduled: "Scheduled"
};
const HASH_TASK_ROUTES = Object.fromEntries(Object.entries(HASH_TASK_LABELS).map(([task, slug]) => [slug.toLowerCase(), task]));
for (const [task, key] of [["calendar", "ui.hash-tasks.calendar"], ["people", "ui.hash-tasks.people"], ["tasks", "ui.hash-tasks.tasks"], ["files", "ui.hash-tasks.files"], ["scheduled", "ui.hash-tasks.scheduled"]]) {
  HASH_TASK_ROUTES[t(key).toLowerCase()] = task;
}

function currentAppHash() {
  if (!state.user) return "";
  if (state.task === "settings") {
    return state.settingsTab === "appearance" ? "#/Settings" : `#/Settings/${encodeURIComponent(state.settingsTab || "appearance")}`;
  }
  if (HASH_TASK_LABELS[state.task]) return `#/${HASH_TASK_LABELS[state.task]}`;
  const folderSlug = FOLDER_LABELS_EN[state.folder] || String(state.folder || "Inbox");
  const base = `#/${encodeURIComponent(folderSlug)}`;
  const routeThreadId = threadUrlIdForSelection();
  return routeThreadId ? `${base}/${encodeURIComponent(routeThreadId)}` : base;
}

function writeAppHash({ replace = true } = {}) {
  if (!state.user || suppressHashSync) return;
  const next = currentAppHash();
  if (!next) return;
  lastAppliedHash = next;
  if (window.location.hash === next) return;
  const url = window.location.pathname + window.location.search + next;
  try {
    if (replace) window.history.replaceState({ alt8mailRoute: true }, "", url);
    else window.history.pushState({ alt8mailRoute: true }, "", url);
  } catch {
    window.location.hash = next;
  }
}

function folderFromHashSegment(segment) {
  let value = "";
  try { value = decodeURIComponent(segment || "").trim().toLowerCase(); } catch { value = String(segment || "").trim().toLowerCase(); }
  if (!value) return null;
  if (value === "mail") value = "inbox";
  if (value === "junk") value = "spam";
  const known = state.folders.find((folder) => folder.id.toLowerCase() === value || String(folder.label || "").toLowerCase() === value);
  if (known) return known.id;
  const builtin = Object.entries(FOLDER_LABELS).find(([id, label]) => id === value || label.toLowerCase() === value || FOLDER_LABELS_EN[id] === value);
  return builtin ? builtin[0] : null;
}

function applyHashRoute() {
  if (!state.user) return false;
  const raw = window.location.hash.replace(/^#\/?/, "");
  if (!raw) return false;
  let parts;
  try {
    parts = raw.split("/").filter(Boolean).map((part) => decodeURIComponent(part));
  } catch {
    return false;
  }
  const root = String(parts[0] || "").trim().toLowerCase();
  if (!root) return false;
  suppressHashSync = true;
  try {
    if (root === "settings") {
      const requestedTab = String(parts[1] || "appearance").toLowerCase();
      const tab = SETTINGS_META[requestedTab] ? requestedTab : "appearance";
      setTask("settings");
      showSettingsTab(tab);
      return true;
    }
    if (HASH_TASK_ROUTES[root]) {
      setTask(HASH_TASK_ROUTES[root]);
      return true;
    }
    const folderId = folderFromHashSegment(parts[0]);
    if (!folderId) return false;
    setTask("mail");
    if (state.folder !== folderId) setFolder(folderId);
    let targetId = parts[1] || "";
    if (!targetId) {
      if (state.selectedThreadId) {
        state.selectedThreadId = null;
        state.expandedThreadId = null;
        document.body.classList.remove("reader-open");
        renderList();
        renderReader();
        syncSelectionUi();
      }
      return true;
    }
    let selection = selectionIdForRoute(targetId);
    if (!threadById(selection)) {
      ensureThreadLoaded(targetId).then((found) => {
        selection = selectionIdForRoute(targetId);
        if (found && threadById(selection)) {
          selectThread(selection);
          return;
        }
        showToast(t("ui.navigation-chrome.that-conversation-is-no-longer-available"));
        if (state.selectedThreadId) {
          state.selectedThreadId = null;
          state.expandedThreadId = null;
          renderList();
          renderReader();
          syncSelectionUi();
        }
      });
      return true;
    }
    selectThread(selection);
    return true;
  } finally {
    suppressHashSync = false;
    lastAppliedHash = currentAppHash();
  }
}

function restoreNavigationFromLocation() {
  if (window.location.hash && window.location.hash !== "#") {
    if (applyHashRoute()) {
      writeAppHash({ replace: true });
      return true;
    }
  }
  setTask("mail");
  handleDeepLink();
  writeAppHash({ replace: true });
  return false;
}

function handleHashLocationChange() {
  if (!state.user) return;
  if (window.location.hash === lastAppliedHash) return;
  if (!applyHashRoute()) {
    writeAppHash({ replace: true });
    return;
  }
  writeAppHash({ replace: true });
}

function setTask(task) {
  if (!["mail", "calendar", "people", "tasks", "files", "scheduled", "settings"].includes(task)) return;
  state.task = task;
  app.setAttribute("data-task", task);
  if (task !== "mail") clearAccountPings();
  if (task !== "mail") {
    const inlineDraft = composeSessions.find((session) => session.mode === "inline");
    if (inlineDraft) minimizeComposeSession(inlineDraft.id);
  }
  mailView.hidden = task !== "mail";
  calendarView.hidden = task !== "calendar";
  peopleView.hidden = task !== "people";
  tasksView.hidden = task !== "tasks";
  filesView.hidden = task !== "files";
  scheduledView.hidden = task !== "scheduled";
  settingsView.hidden = task !== "settings";
  state.query = "";
  searchInput.value = "";
  updateSearchClear();
  closeSearchHints();
  document.body.classList.remove("reader-open", "person-open", "search-open", "file-open", "task-detail-open");
  if (task === "calendar") renderCalendar();
  if (task === "people") {
    state.peopleQuery = "";
    state.peopleFilter = "all";
    const peopleSearch = document.getElementById("peopleSearch");
    if (peopleSearch) peopleSearch.value = "";
    renderPeople();
  }
  if (task === "tasks") renderTasks();
  if (task === "files") renderFiles();
  if (task === "scheduled") renderScheduled();
  if (task === "settings") {
    syncThemeUI();
    showSettingsTab(state.settingsTab);
  }
  if (task === "mail") { renderFolders(); renderList(); renderReader(); }
  syncNav();
  syncSearchContext();
  syncStatusRange();
  syncStatusContext();
  closeDrawer();
  hideNotify();
  closeMenus();
  writeAppHash({ replace: true });
  updateDocumentTitle();
}

function syncNav() {
  const navTask = state.task === "scheduled" ? "mail" : state.task;
  $$("button[data-task]").forEach((button) => {
    const active = button.getAttribute("data-task") === navTask;
    button.classList.toggle("is-active", active);
    if (active) button.setAttribute("aria-current", "page");
    else button.removeAttribute("aria-current");
  });
}

const LIST_FILTERS = [
  { id: "all", labelKey: "mail.filters.all", icon: "i-mail" },
  { id: "unread", labelKey: "mail.filters.unread", icon: "i-envelope-open" },
  { id: "flagged", labelKey: "mail.filters.flagged", icon: "i-flag" },
  { id: "toMe", labelKey: "mail.filters.toMe", icon: "i-arrow-left" },
  { id: "attachments", labelKey: "mail.filters.attachments", icon: "i-paperclip" },
  { id: "mentions", labelKey: "mail.filters.mentions", icon: "i-at" },
  { id: "calendar", labelKey: "mail.filters.calendar", icon: "i-calendar" },
  { id: "closed", labelKey: "mail.filters.closed", icon: "i-check-circle" }
];

function listFilterLabel(filter = state.filter) {
  const item = LIST_FILTERS.find((entry) => entry.id === filter) || LIST_FILTERS[0];
  return t(item.labelKey);
}

function renderListFilterMenu() {
  const menu = document.getElementById("listFilterMenu");
  if (!menu) return;
  menu.innerHTML = LIST_FILTERS.map((item) => `<button type="button" role="menuitemradio" aria-checked="${state.filter === item.id}" data-list-filter="${item.id}" class="${state.filter === item.id ? "is-active" : ""}"><svg class="icon" aria-hidden="true"><use href="#${item.icon}"/></svg><span>${esc(item.label)}</span>${state.filter === item.id ? '<span class="check">✓</span>' : ""}</button>`).join("");
}

function toggleListFilterMenu(force) {
  const menu = document.getElementById("listFilterMenu");
  const button = document.getElementById("filterBtn");
  if (!menu || !button) return;
  const open = force === undefined ? menu.hidden : Boolean(force);
  renderListFilterMenu();
  menu.hidden = !open;
  button.setAttribute("aria-expanded", open ? "true" : "false");
  button.classList.toggle("is-active", open || state.filter !== "all");
}

function syncChips() {
  $$("button[data-filter]").forEach((button) => {
    button.classList.toggle("is-active", button.getAttribute("data-filter") === state.filter);
  });
  document.getElementById("filterBtn")?.classList.toggle("is-active", state.filter !== "all");
  renderListFilterMenu();
}

function setFolder(folder) {
  if (!state.folders.some((item) => item.id === folder)) return;
  state.folder = folder;
  applyFolderDensity(folder);
  state.filter = "all";
  state.query = "";
  state.collapsedMailGroups = new Set();
  state.selectedIds.clear();
  state.selectedThreadId = null;
  state.expandedThreadId = null;
  searchInput.value = "";
  updateSearchClear();
  document.body.classList.remove("reader-open");
  renderFolders();
  renderList();
  renderReader();
  syncChips();
  syncSearchContext();
  syncStatusContext();
  closeDrawer();
  writeAppHash({ replace: true });
  const key = mailPageKey(folder, "all");
  if (!state.mailPages[key]?.loaded) {
    loadMailPage(folder, "all")
      .then(() => {
        if (state.folder === folder && !state.query) {
          renderList();
          renderReader();
          renderFolders();
          syncSelectionUi();
        }
      })
      .catch((error) => showError(error));
  }
}

function setFilter(filter) {
  if (state.filter === filter) return;
  state.filter = filter;
  state.collapsedMailGroups = new Set();
  state.selectedIds.clear();
  syncChips();
  renderList();
  syncSelectionUi();
  const key = mailPageKey(state.folder, filter);
  if (!state.mailPages[key]?.loaded) {
    loadMailPage(state.folder, filter)
      .then(() => {
        if (state.filter === filter && !state.query) {
          renderList();
          renderReader();
        }
      })
      .catch((error) => showError(error));
  }
}

function openDrawer() {
  if (!isDrawer()) return;
  document.body.classList.add("drawer-open");
  scrim.classList.add("is-open");
  scrim.setAttribute("aria-hidden", "false");
}

function closeDrawer() {
  closeAccountMenu();
  document.body.classList.remove("drawer-open");
  scrim.classList.remove("is-open");
  scrim.setAttribute("aria-hidden", "true");
}

function openHelp() {
  lastFocus = document.activeElement;
  const list = helpOverlay.querySelector(".shortcut-list");
  if (list) list.innerHTML = shortcutReferenceRows();
  helpOverlay.hidden = false;
  setTimeout(() => document.getElementById("helpClose").focus(), 30);
}

function closeHelp() {
  helpOverlay.hidden = true;
  if (lastFocus && typeof lastFocus.focus === "function") {
    try { lastFocus.focus(); } catch {}
  }
}

function moveRecentKey() {
  return `a8m_move_recent_${normalizeEmail(state.user?.email || "anonymous")}`;
}

function moveRecentFolders() {
  try {
    const ids = JSON.parse(localStorage.getItem(moveRecentKey()) || "[]");
    return (Array.isArray(ids) ? ids : []).filter((id) => (state.folders || []).some((folder) => folder.id === id)).slice(0, 4);
  } catch {
    return [];
  }
}

function rememberMoveFolder(id) {
  const current = moveRecentFolders().filter((item) => item !== id);
  current.unshift(id);
  try { localStorage.setItem(moveRecentKey(), JSON.stringify(current.slice(0, 4))); } catch {}
}

function moveFolderRow(folder) {
  const current = state.task === "mail" && state.query === "" && state.folder === folder.id;
  return `<button class="move-folder-row${current ? " is-current" : ""}" type="button" data-move-target="${esc(folder.id)}"><span class="move-folder-icon"${folder.color ? ` style="color:${esc(folder.color)}"` : ""}><svg class="icon" aria-hidden="true"><use href="#${esc(folder.icon || "i-folder")}"/></svg></span><span>${esc(folder.label)}</span>${current ? `<small>${t("ui.navigation-chrome.current")}</small>` : ""}</button>`;
}

function moveMenuListMarkup() {
  const query = state.moveSearch.trim().toLowerCase();
  const folders = (state.folders || [])
    .filter((folder) => !folder.virtual && !folder.delegated && folder.id !== "starred")
    .filter((folder) => !query || folder.label.toLowerCase().includes(query))
    .sort((a, b) => folderSortValue(a) - folderSortValue(b));
  return folders.map(moveFolderRow).join("") || `<div class="move-empty">${esc(t("ui.move-menu.no-folder-matches", { query: state.moveSearch }))}</div>`;
}

function renderMoveMenu() {
  const recent = moveRecentFolders();
  const recentRows = (recent.length ? recent : ["trash", "archive"]).map((id) => (state.folders || []).find((folder) => folder.id === id)).filter(Boolean);
  moveMenu.innerHTML = `<div class="move-panel-head"><span><svg class="icon" aria-hidden="true"><use href="#i-folder"/></svg>${state.moveRuleMode ? t("ui.navigation-chrome.always-move-to") : t("ui.navigation-chrome.move-to")}</span><button class="icon-btn" data-move-close type="button" aria-label="${esc(t("ui.navigation-chrome.close-move-menu"))}"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button></div>
    <div class="move-search"><svg class="icon" aria-hidden="true"><use href="#i-search"/></svg><input data-move-search type="search" value="${esc(state.moveSearch)}" placeholder="${esc(t("ui.navigation-chrome.search-for-a-folder"))}" autocomplete="off"></div>
    <div class="move-scroll">
      <div class="move-section-label">${t("ui.navigation-chrome.most-recent")}</div>
      ${recentRows.map(moveFolderRow).join("")}
      <div class="move-create-row"><svg class="icon" aria-hidden="true"><use href="#i-plus"/></svg><input data-move-new-folder type="text" maxlength="60" placeholder="${esc(t("ui.navigation-chrome.create-new-folder"))}"><button type="button" data-move-create>${t("common.save")}</button></div>
      <button class="move-rule-mode${state.moveRuleMode ? " is-active" : ""}" type="button" data-move-rule-toggle aria-pressed="${state.moveRuleMode ? "true" : "false"}"><span class="move-rule-check">${state.moveRuleMode ? "✓" : ""}</span><span><strong>${t("ui.navigation-chrome.always-move-mail-from-this-sender")}</strong><small>${state.moveRuleMode ? t("ui.navigation-chrome.choosing-a-folder-also-creates-a-rule-and-a-matc") : t("ui.navigation-chrome.create-a-rule-so-future-messages-skip-the-wrong-")}</small></span></button>
      <div class="move-section-label">${state.moveRuleMode ? t("ui.navigation-chrome.choose-the-permanent-destination") : t("ui.navigation-chrome.all-folders")}</div>
      <div class="move-folder-list" data-move-list>${moveMenuListMarkup()}</div>
    </div>`;
}

function openMoveMenu(anchor) {
  if (!currentThread() && !state.selectedIds.size) return;
  state.moveSearch = "";
  state.moveRuleMode = false;
  renderMoveMenu();
  positionMenu(moveMenu, anchor);
  setTimeout(() => moveMenu.querySelector("[data-move-search]")?.focus(), 50);
}

async function chooseMoveTarget(folderId) {
  const folder = (state.folders || []).find((item) => item.id === folderId);
  if (!folder) return;
  const always = state.moveRuleMode;
  closeMenus();
  rememberMoveFolder(folderId);
  await performBulkAction("move", folderId, { alwaysRule: always });
  if (always) showToast(t("ui.reader.future-mail-goes-to", { folder: folder.label }));
}

async function createFolderFromMoveMenu() {
  const input = moveMenu.querySelector("[data-move-new-folder]");
  const label = String(input?.value || "").trim();
  if (!label) { input?.focus(); return; }
  try {
    const data = await api("/api/folders", { method: "POST", body: { label, parentId: "", color: "" } });
    await loadFolders();
    state.moveSearch = "";
    if (data.folder?.id) await chooseMoveTarget(data.folder.id);
  } catch (error) { showError(error); }
}

function positionMenu(menu, anchor) {
  menu.hidden = false;
  const rect = anchor.getBoundingClientRect();
  const width = menu.offsetWidth || 190;
  const left = Math.max(8, Math.min(rect.left, window.innerWidth - width - 8));
  menu.style.left = left + "px";
  menu.style.top = Math.round(rect.bottom + 6) + "px";
}

function closeMenus() {
  newMenu.hidden = true;
  moveMenu.hidden = true;
  if (folderMenu) folderMenu.hidden = true;
  if (messageMenu) messageMenu.hidden = true;
  closeAccountMenu();
  closeSelectionTranslation();
  toggleListFilterMenu(false);
  state.folderMenuTarget = "";
  state.messageMenuThreadId = "";
  state.messageMenuMessageId = "";
  state.messageMenuView = "";
  state.messageMenuSelectionText = "";
  state.bulkMoveOpen = false;
  const bulkMenu = document.getElementById("bulkMoveMenu");
  if (bulkMenu) bulkMenu.hidden = true;
}

function notificationIconName(kind) {
  if (kind === "calendar") return "i-calendar";
  if (kind === "mail") return "i-mail";
  if (kind === "security") return "i-shield-check";
  if (kind === "scheduled") return "i-calendar-clock";
  if (kind === "quota") return "i-alert";
  if (kind === "mention") return "i-at";
  if (kind === "assignment") return "i-users";
  if (kind === "file_access_request") return "i-lock";
  return "i-bell";
}

function buildNotifications() {
  const items = [];
  const now = Date.now();
  const seen = new Set();
  const add = (item) => {
    if (!item || seen.has(item.id)) return;
    seen.add(item.id);
    items.push(item);
  };
  const inbox = state.messages
    .filter((message) => message.folder === "inbox" && message.unread && !message.draft)
    .sort((a, b) => Date.parse(b.date) - Date.parse(a.date))
    .slice(0, 14);
  inbox.forEach((message) => {
    const sender = message.from?.name || message.from?.email || t("ui.navigation-chrome.new-sender");
    add({
      id: "mail:" + message.id,
      kind: "mail",
      title: t("ui.navigation-chrome.new-message-from", { sender }),
      body: message.subject || t("mail.list.noSubject"),
      detail: message.snippet || htmlToText(message.bodyHtml || "").slice(0, 140),
      time: message.date,
      unread: true,
      action: { type: "message", messageId: message.id, threadId: message.threadId || message.id }
    });
  });
  (state.pendingSends || []).forEach((send) => {
    const when = send.sendAt ? Date.parse(send.sendAt) : now;
    if (when < now - 24 * 3600 * 1000) return;
    add({
      id: "scheduled:" + send.id,
      kind: "scheduled",
      title: send.scheduled ? t("ui.navigation-chrome.scheduled-message-queued") : t("ui.navigation-chrome.message-waiting-to-send"),
      body: send.subject || t("mail.list.noSubject"),
      detail: `${send.to?.[0]?.email || t("ui.navigation-chrome.recipient")} · ${formatListWhen(send.sendAt)}`,
      time: send.sendAt || new Date().toISOString(),
      unread: true,
      action: { type: "scheduled" }
    });
  });
  (state.calendarEvents || []).forEach((event) => {
    const start = zonedWallTimeToUtc(event.date, event.start);
    if (!start || start.getTime() < now - 30 * 60 * 1000 || start.getTime() > now + 36 * 3600 * 1000) return;
    add({
      id: "calendar:" + (event.id || `${event.date}-${event.start}-${event.title}`),
      kind: "calendar",
      title: event.title || t("ui.navigation-chrome.upcoming-event"),
      body: `${formatClock(start)} · ${event.where || t("nav.calendar")}`,
      detail: start.getTime() <= now + 15 * 60 * 1000 ? t("ui.navigation-chrome.starting-soon") : t("ui.navigation-chrome.starts-relative", { time: formatRelativeTime(start) }),
      time: start.toISOString(),
      unread: true,
      action: { type: "calendar" }
    });
  });
  const securityGroups = new Set();
  (state.recentAudit || []).forEach((entry) => {
    const action = String(entry.action || "");
    if (!/^(auth|security)\./.test(action)) return;
    const stamp = Date.parse(entry.ts || "");
    if (!Number.isFinite(stamp) || stamp < now - 7 * 24 * 3600 * 1000) return;
    const group = `${action}|${entry.target || ""}|${entry.ip || ""}`;
    if (securityGroups.has(group)) return;
    securityGroups.add(group);
    add({
      id: "audit:" + (entry.id || entry.ts + action),
      kind: "security",
      title: AUDIT_LABELS[action] || t("ui.navigation-chrome.account-security-activity"),
      body: entry.detail || entry.target || t("ui.navigation-chrome.security-event"),
      detail: entry.ip ? `IP ${entry.ip}` : t("ui.navigation-chrome.alt8mail-security"),
      time: entry.ts,
      unread: true,
      action: { type: "security" }
    });
  });
  const quotaPercent = Number(state.quota?.percent || 0);
  if (quotaPercent >= 80) {
    add({
      id: "quota:warning",
      kind: "quota",
      title: t("ui.navigation-chrome.mailbox-storage-is-almost-full"),
      body: t("ui.navigation-chrome.quota-percent-in-use", { percent: quotaPercent.toFixed(0) }),
      detail: t("ui.navigation-chrome.quota-free-space-hint"),
      time: new Date().toISOString(),
      unread: true,
      action: { type: "account" }
    });
  }
  const outboundPercent = Number(state.outbound?.percent || 0);
  if (!outboundIsUnlimited(state.outbound) && outboundPercent >= 80) {
    add({
      id: "outbound:warning",
      kind: "quota",
      title: t("ui.navigation-chrome.outbound-sending-limit-is-almost-reached"),
      body: t("ui.navigation-chrome.messages-used", { used: state.outbound.usedWithQueued || 0, limit: state.outbound.limit }),
      detail: t("ui.status-bar-quota-pending-sends.rolling-window-note"),
      time: new Date().toISOString(),
      unread: true,
      action: { type: "security" }
    });
  }
  for (const notification of state.serverNotifications || []) {
    if (!notification?.id) continue;
    const id = "server:" + notification.id;
    add({
      id,
      kind: notification.kind === "mention" ? "mention" : notification.kind === "assignment" ? "assignment" : notification.kind === "calendar" ? "calendar" : "system",
      title: notification.title || t("ui.navigation-chrome.workspace-notification"),
      body: notification.body || "",
      detail: notification.detail || "",
      time: notification.createdAt,
      unread: !notification.readAt && !state.dismissedNotifications.has(id),
      action: {
        type: notification.kind === "mention" ? "mention" : notification.kind === "assignment" ? "assignment" : notification.kind === "calendar" ? "calendar" : "security",
        threadId: notification.threadId,
        messageId: notification.messageId,
        ownerId: notification.ownerId
      }
    });
  }
  const priority = (item) => item.kind === "mention" || item.kind === "assignment" ? 0
    : item.kind === "security" ? 1
    : item.kind === "calendar" ? 3
    : 2;
  return items
    .map((item) => ({ ...item, unread: !state.dismissedNotifications.has(item.id) && item.unread !== false }))
    .sort((a, b) => priority(a) - priority(b) || Date.parse(b.time || 0) - Date.parse(a.time || 0));
}

function notificationRowMarkup(item, compact = true) {
  const icon = notificationIconName(item.kind);
  const iconClass = item.kind === "security" ? "security" : item.kind === "calendar" ? "accent" : "";
  return `<button class="notify-item${item.unread ? " is-unread" : ""}" type="button" data-notify-id="${esc(item.id)}">
    <span class="notify-icon ${iconClass}"><svg class="icon" aria-hidden="true"><use href="#${icon}"/></svg></span>
    <span class="notify-main"><strong>${item.unread ? '<span class="notify-unread-dot"></span>' : ""}${esc(item.title)}</strong><span>${esc(item.body || "")}</span></span>
    <time>${esc(formatListWhen(item.time))}</time>
  </button>`;
}

function noticeCenterRowMarkup(item) {
  const icon = notificationIconName(item.kind);
  const iconClass = item.kind === "security" ? "security" : item.kind === "calendar" ? "accent" : "";
  return `<div class="notice-center-item${item.unread ? " is-unread" : ""}">
    <span class="notify-icon ${iconClass}"><svg class="icon" aria-hidden="true"><use href="#${icon}"/></svg></span>
    <div class="notice-center-main"><strong>${esc(item.title)}</strong><p>${esc(item.body || "")}</p><div class="notice-center-meta"><span>${esc(item.detail || "")}</span><span>${esc(formatListWhen(item.time))}</span></div></div>
    <div class="notice-center-actions">
      ${item.unread ? `<button class="link-btn" data-notice-read="${esc(item.id)}" type="button">${t("mail.list.quick.markRead")}</button>` : ""}
      <button class="icon-btn" data-notice-open="${esc(item.id)}" type="button" aria-label="${esc(t("ui.navigation-chrome.open-notification"))}" title="${esc(t("tasks.status.open"))}"><svg class="icon" aria-hidden="true"><use href="#i-chevron-right"/></svg></button>
    </div>
  </div>`;
}

let notificationRefreshTimer = null;

async function refreshServerNotifications() {
  if (!state.user || !state.csrf) return;
  try {
    const data = await api("/api/notifications");
    state.serverNotifications = Array.isArray(data.notifications) ? data.notifications : [];
    renderNotifications();
  } catch {
    // Background refresh failures leave the last known list in place.
  }
}

function startNotificationRefresh() {
  if (notificationRefreshTimer) return;
  notificationRefreshTimer = setInterval(refreshServerNotifications, 60_000);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") refreshServerNotifications();
  });
  window.addEventListener("focus", () => refreshServerNotifications());
}

function renderNotifications() {
  state.notifications = buildNotifications();
  const unread = state.notifications.filter((item) => item.unread).length;
  const count = document.getElementById("notifyCount");
  const dot = document.getElementById("notifyDot");
  if (count) {
    count.hidden = unread === 0;
    count.textContent = unread > 99 ? "99+" : String(unread);
  }
  if (dot) dot.hidden = unread === 0;
  if (notifySubtitle) notifySubtitle.textContent = unread ? tn("ui.navigation-chrome.unread-notification-count", unread, { count: unread }) : t("ui.navigation-chrome.you-re-all-caught-up");
  if (notifyList) {
    const recent = state.notifications.slice(0, 7);
    notifyList.innerHTML = recent.length ? recent.map((item) => notificationRowMarkup(item)).join("") : `<div class="notify-empty">${t("ui.navigation-chrome.no-notifications-yet-new-mail-meetings-and-secur")}</div>`;
  }
  if (noticeLayer && !noticeLayer.hidden) renderNoticeCenter();
}

function openNoticeCenter(filter = "all") {
  state.noticeFilter = filter;
  noticeLayer.hidden = false;
  hideNotify();
  renderNoticeCenter();
}

function closeNoticeCenter() {
  noticeLayer.hidden = true;
}

function renderNoticeCenter() {
  if (!noticeBody) return;
  const filter = state.noticeFilter || "all";
  let list = state.notifications || buildNotifications();
  if (filter === "unread") list = list.filter((item) => item.unread);
  else if (filter === "mail") list = list.filter((item) => ["mail", "scheduled", "mention", "assignment"].includes(item.kind));
  else if (filter === "system") list = list.filter((item) => item.kind === "security" || item.kind === "calendar" || item.kind === "quota");
  const unread = list.filter((item) => item.unread).length;
  if (noticeCount) noticeCount.textContent = `${list.length} notification${list.length === 1 ? "" : "s"}${unread ? ` · ${unread} unread` : ""}`;
  if (!list.length) {
    noticeBody.innerHTML = `<div class="notice-empty"><svg class="icon" aria-hidden="true"><use href="#i-bell"/></svg><h3>${t("ui.navigation-chrome.nothing-here-yet")}</h3><p>${filter === "unread" ? t("ui.navigation-chrome.you-ve-read-every-notification") : t("ui.navigation-chrome.new-activity-will-appear-here-automatically")}</p></div>`;
    return;
  }
  const groups = new Map();
  list.forEach((item) => {
    const date = new Date(item.time || Date.now());
    const key = Number.isNaN(date.getTime()) ? t("ui.navigation-chrome.earlier") : date.toDateString() === new Date().toDateString() ? t("mail.list.date.today") : t("ui.navigation-chrome.earlier");
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(item);
  });
  noticeBody.innerHTML = Array.from(groups.entries()).map(([label, entries]) =>
    `<section class="notice-group"><h3>${label}</h3>${entries.map(noticeCenterRowMarkup).join("")}</section>`
  ).join("");
}

function markNotificationRead(id) {
  state.dismissedNotifications.add(id);
  if (String(id).startsWith("server:")) {
    const raw = String(id).slice("server:".length);
    state.serverNotifications = (state.serverNotifications || []).map((item) => item.id === raw ? { ...item, readAt: new Date().toISOString() } : item);
    api(`/api/notifications/${encodeURIComponent(raw)}/read`, { method: "POST", body: {} }).catch(() => {});
  }
  persistDismissedNotifications();
  state.notifications = buildNotifications();
  const unread = state.notifications.filter((item) => item.unread).length;
  const count = document.getElementById("notifyCount");
  if (count) { count.hidden = unread === 0; count.textContent = unread > 99 ? "99+" : String(unread); }
  const dot = document.getElementById("notifyDot");
  if (dot) dot.hidden = unread === 0;
  if (notifyList) notifyList.innerHTML = state.notifications.slice(0, 7).map((item) => notificationRowMarkup(item)).join("") || `<div class="notify-empty">${t("ui.navigation-chrome.no-notifications-yet")}</div>`;
  if (!noticeLayer.hidden) renderNoticeCenter();
}

function markAllNotificationsRead() {
  state.notifications.forEach((item) => state.dismissedNotifications.add(item.id));
  state.serverNotifications = (state.serverNotifications || []).map((item) => ({ ...item, readAt: item.readAt || new Date().toISOString() }));
  api("/api/notifications/read-all", { method: "POST", body: {} }).catch(() => {});
  persistDismissedNotifications();
  renderNotifications();
  if (!noticeLayer.hidden) renderNoticeCenter();
}

function handleNotificationAction(id) {
  const item = (state.notifications || []).find((entry) => entry.id === id);
  if (!item) return;
  markNotificationRead(id);
  hideNotify();
  closeNoticeCenter();
  if (item.action?.type === "message") {
    setTask("mail");
    setFolder("inbox");
    const target = item.action.messageId ? messageById(item.action.messageId) : null;
    const selection = target ? selectionIdForMessage(target) : item.action.threadId;
    if (selection) selectThread(selection);
  } else if (item.action?.type === "scheduled") {
    setTask("scheduled");
  } else if (item.action?.type === "mention" || item.action?.type === "assignment") {
    setTask("mail");
    const ownerId = item.action.ownerId || "";
    if (ownerId && ownerId !== state.user?.id) {
      const folderId = "delegate_" + ownerId;
      if (!state.folders.some((folder) => folder.id === folderId)) {
        showToast(t("ui.navigation-chrome.this-conversation-is-in-a-shared-mailbox-you-can"));
        return;
      }
      setFolder(folderId);
    } else {
      setFolder("inbox");
    }
    const threadId = item.action.threadId || item.action.messageId;
    if (threadId) {
      setTimeout(() => {
        if (!threadById(threadId) && !messageById(threadId)) {
          showToast(t("ui.navigation-chrome.this-conversation-is-in-a-mailbox-you-do-not-hav"));
          return;
        }
        selectThread(threadId);
      }, 280);
    }
  } else if (item.action?.type === "calendar") {
    setTask("calendar");
    if (item.action?.threadId) {
      setTimeout(() => {
        const event = (state.calendarEvents || []).find((entry) => entry.id === item.action.threadId);
        if (event) openEventDialog(event.id, { date: event.date });
      }, 280);
    }
  } else if (item.action?.type === "account") {
    openSettings("account");
  } else {
    openSettings("security");
  }
}

function showNotify() {
  notifyPop.hidden = false;
  renderNotifications();
}

function hideNotify() {
  if (notifyPop) notifyPop.hidden = true;
}

function toggleNotify() {
  if (notifyPop.hidden) showNotify(); else hideNotify();
}


