const SHORTCUT_DEFAULTS = {
  next: "j", previous: "k", select: "x", compose: "c", search: "/",
  archive: "e", delete: "#", unread: "u", reply: "r", replyAll: "a",
  forward: "f", star: "s", help: "?"
};
const SHORTCUT_META = [
  ["next", t("ui.mail-home-pulse-search-reports-sticky-no.next-conversation")], ["previous", t("ui.mail-home-pulse-search-reports-sticky-no.previous-conversation")],
  ["select", t("mail.list.selectConversation")], ["compose", t("ui.alt8mail-intelligence-pre-send-spell-che.new-message")], ["search", t("mail.search.placeholder.mail")],
  ["archive", t("ui.settings.archive-conversation")], ["delete", t("ui.settings.delete-conversation")],
  ["unread", t("ui.settings.mark-unread")], ["reply", t("mail.reader.reply")], ["replyAll", t("shell.replyAll")],
  ["forward", t("mail.reader.forward")], ["star", t("mail.list.starConversation")], ["help", t("ui.settings.shortcut-reference")]
];
const SHORTCUTS_KEY = "a8mShortcuts";

function shortcutMap() {
  let stored = {};
  try { stored = JSON.parse(localStorage.getItem(SHORTCUTS_KEY) || "{}") || {}; } catch { stored = {}; }
  const result = { ...SHORTCUT_DEFAULTS };
  for (const [key] of SHORTCUT_META) {
    const value = String(stored[key] || "").trim();
    if (value.length === 1) result[key] = value.toLowerCase();
  }
  return result;
}

function saveShortcutMap(map) {
  try { localStorage.setItem(SHORTCUTS_KEY, JSON.stringify(map)); } catch {}
}

function refreshShortcutConflicts(host) {
  const inputs = $$("[data-shortcut-key]", host);
  const counts = {};
  inputs.forEach((input) => {
    const value = String(input.value || "").trim().toLowerCase();
    if (value) counts[value] = (counts[value] || 0) + 1;
  });
  inputs.forEach((input) => {
    const value = String(input.value || "").trim().toLowerCase();
    input.classList.toggle("is-conflict", Boolean(value) && counts[value] > 1);
  });
  const duplicates = Object.keys(counts).filter((value) => counts[value] > 1);
  const note = document.getElementById("shortcutConflict");
  if (note) {
    note.hidden = !duplicates.length;
    note.textContent = duplicates.length
      ? t("ui.settings.duplicate-keys", { keys: duplicates.map((value) => value.toUpperCase()).join(", ") })
      : "";
  }
}

function renderShortcutSettings() {
  const host = document.getElementById("shortcutSettings");
  if (!host) return;
  const map = shortcutMap();
  host.innerHTML = `<div class="pref-list shortcut-settings-list">${SHORTCUT_META.map(([key, label]) => `
    <div class="pref-row">
      <div class="pref-copy"><strong>${esc(label)}</strong></div>
      <input class="shortcut-key-input" maxlength="1" data-shortcut-key="${key}" value="${esc(map[key])}" aria-label="${esc(t("ui.settings.shortcut-aria", { action: label }))}" autocomplete="off" spellcheck="false">
    </div>`).join("")}</div>
    <p class="shortcut-conflict" id="shortcutConflict" hidden></p>
    <div class="settings-actions"><button class="btn-secondary small" type="button" id="shortcutReset">${t("ui.settings.reset-to-defaults")}</button></div>`;
  $$("[data-shortcut-key]", host).forEach((input) => {
    input.addEventListener("focus", () => input.select());
    input.addEventListener("input", () => {
      const key = input.dataset.shortcutKey;
      const value = String(input.value || "").trim().toLowerCase();
      if (value.length !== 1) {
        input.value = shortcutMap()[key];
        showToast(t("ui.settings.use-one-character-per-shortcut"), "error");
        refreshShortcutConflicts(host);
        return;
      }
      const next = shortcutMap();
      next[key] = value;
      saveShortcutMap(next);
      input.value = value;
      refreshShortcutConflicts(host);
      showToast(t("ui.settings.shortcut-saved"));
    });
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") { event.preventDefault(); input.blur(); }
      if (event.key === "Escape") { input.value = shortcutMap()[input.dataset.shortcutKey]; input.blur(); }
    });
  });
  refreshShortcutConflicts(host);
  document.getElementById("shortcutReset")?.addEventListener("click", () => {
    try { localStorage.removeItem(SHORTCUTS_KEY); } catch {}
    renderShortcutSettings();
    showToast(t("ui.settings.shortcuts-reset"));
  });
}

function shortcutReferenceRows() {
  const map = shortcutMap();
  return SHORTCUT_META.filter(([key]) => key !== "help" && key !== "search").map(([key, label]) => `<div class="shortcut-row"><span>${esc(label)}</span><span class="shortcut-keys"><kbd>${esc(map[key].toUpperCase())}</kbd></span></div>`).join("") +
    `<div class="shortcut-row"><span>${t("mail.search.placeholder.mail")}</span><span class="shortcut-keys"><kbd>${esc(map.search.toUpperCase())}</kbd><kbd>${t("ui.settings.ctrl")}</kbd><kbd>K</kbd></span></div>
     <div class="shortcut-row"><span>${t("ui.settings.send-from-compose")}</span><span class="shortcut-keys"><kbd>${t("ui.settings.ctrl")}</kbd><kbd>${t("ui.settings.enter")}</kbd></span></div>
     <div class="shortcut-row"><span>${t("ui.settings.this-dialog")}</span><span class="shortcut-keys"><kbd>${esc(map.help.toUpperCase())}</kbd></span></div>
     <div class="shortcut-row"><span>${t("ui.settings.close-a-panel")}</span><span class="shortcut-keys"><kbd>${t("ui.settings.esc")}</kbd></span></div>`;
}

